import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Shield, Key, Fingerprint, Trash2, Plus, RefreshCw, AlertTriangle, Smartphone, Clock, Activity, Globe, Settings as SettingsIcon, MapPin, Cpu } from 'lucide-react';
import { startRegistration } from '@simplewebauthn/browser';
import { AppleBrandSvg, WindowsBrandSvg, GoogleWorkspaceSvg, YubicoBrandSvg, BitwardenBrandSvg, OnePasswordSvg } from './common/BrandLogos';
import { useToast } from './common';

interface Passkey {
  id: string;
  name: string | null;
  aaguid: string | null;
  createdAt: string;
  lastUsedAt?: string | null;
  lastUsedIpV4?: string | null;
  lastUsedIpV6?: string | null;
  lastUsedUa?: string | null;
  browser?: string | null;
  os?: string | null;
  deviceName?: string | null;
  city?: string | null;
  country?: string | null;
  region?: string | null;
  latitude?: string | null;
  longitude?: string | null;
  providerName?: string | null;
  icon?: string | null;
  securityLevel?: string | null;
  manufacturer?: string | null;
  logo?: string | null;
  counter: number;
  transports?: string | null;
  registrationIpV4?: string | null;
  registrationIpV6?: string | null;
  registrationCity?: string | null;
  registrationCountry?: string | null;
  registrationUa?: string | null;
  lastUsedCity?: string | null;
  lastUsedCountry?: string | null;
}

export const PasskeyModule = ({ onRequirePasskey }: { onRequirePasskey?: () => void }) => {
  const { addToast } = useToast();
  const [passkeys, setPasskeys] = useState<Passkey[]>([]);
  const [loading, setLoading] = useState(true);
  const [registering, setRegistering] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editName, setEditName] = useState('');
  const [confirmingDelete, setConfirmingDelete] = useState<string | null>(null);

  useEffect(() => {
    fetchPasskeys();
  }, []);

  const fetchPasskeys = async () => {
    try {
      const res = await fetch(`/admin/webauthn/passkeys`);
      if (res.status === 403) {
        if (onRequirePasskey) onRequirePasskey();
        return;
      }
      if (!res.ok) throw new Error('Failed to fetch keys');
      const data = await res.json() as any;
      setPasskeys(data.passkeys || []);
    } catch (err) {
      addToast('Could not load your security keys.', 'error');
    } finally {
      setLoading(false);
    }
  };

  const saveName = async (id: string) => {
    try {
      const res = await fetch(`/admin/webauthn/passkeys/${id}`, { 
        method: 'PUT',
        headers: { 
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({ name: editName })
      });
      if (res.status === 403) {
        if (onRequirePasskey) onRequirePasskey();
        return;
      }
      if (!res.ok) throw new Error('Failed to rename key');

      setPasskeys(p => p.map(k => k.id === id ? { ...k, name: editName } : k));
      setEditingId(null);
      addToast('Name updated successfully.', 'success');
    } catch (err) {
      addToast('Failed to update name.', 'error');
    }
  };

  const deletePasskey = async (id: string) => {
    try {
      const res = await fetch(`/admin/webauthn/passkeys/${id}`, { 
        method: 'DELETE'
      });
      if (res.status === 403) {
        if (onRequirePasskey) onRequirePasskey();
        return;
      }
      if (!res.ok) throw new Error('Failed to remove key');

      setPasskeys(p => p.filter(k => k.id !== id));
      setConfirmingDelete(null);
      addToast('Security key removed successfully.', 'success');
    } catch (err) {
      addToast('Failed to remove key.', 'error');
    }
  };

  const generatePasskey = async () => {
    setRegistering(true);
    try {
      const challengeRes = await fetch(`/admin/webauthn/generate-registration`, { 
        method: 'POST'
      });
      if (challengeRes.status === 403) {
        if (onRequirePasskey) onRequirePasskey();
        return;
      }
      const options = await challengeRes.json() as any;

      if (!challengeRes.ok) {
        throw new Error(options.error || 'Challenge generation failed');
      }

      const attResp = await startRegistration({ optionsJSON: options });

      const verifyRes = await fetch(`/admin/webauthn/verify-registration`, {
        method: 'POST',
        headers: { 
          'Content-Type': 'application/json'
        },
        body: JSON.stringify(attResp),
      });
      if (verifyRes.status === 403) {
        if (onRequirePasskey) onRequirePasskey();
        return;
      }
      if (!verifyRes.ok) throw new Error('Security verification failed.');

      addToast('Security key added successfully.', 'success');
      fetchPasskeys();
    } catch (err: any) {
      console.error(err);
      addToast(err.message || 'Setup was cancelled or failed.', 'error');
    } finally {
      setRegistering(false);
    }
  };

  const getProviderIcon = (iconName: string | null, logoUrl?: string | null, providerName?: string | null, manufacturer?: string | null) => {
    const combined = `${iconName || ''} ${providerName || ''} ${manufacturer || ''}`.toLowerCase();

    if (combined.includes('1password') || combined.includes('agilebits')) {
      return (
