          <OnePasswordSvg className="w-7 h-7" />
        </div>
      );
    }
    if (combined.includes('apple') || combined.includes('icloud') || combined.includes('touch id') || combined.includes('face id')) {
      return (
        <div className="w-9 h-9 flex items-center justify-center overflow-hidden rounded-xl bg-white/10 border border-white/15 p-1 text-white">
          <AppleBrandSvg className="w-6 h-6" />
        </div>
      );
    }
    if (combined.includes('google') || combined.includes('chrome') || combined.includes('android')) {
      return (
        <div className="w-9 h-9 flex items-center justify-center overflow-hidden rounded-xl bg-white/10 border border-white/15 p-1.5">
          <GoogleWorkspaceSvg className="w-6 h-6" />
        </div>
      );
    }
    if (combined.includes('windows') || combined.includes('hello') || combined.includes('microsoft')) {
      return (
        <div className="w-9 h-9 flex items-center justify-center overflow-hidden rounded-xl bg-[#00A4EF]/10 border border-[#00A4EF]/20 p-1.5">
          <WindowsBrandSvg className="w-6 h-6" />
        </div>
      );
    }
    if (combined.includes('yubico') || combined.includes('yubikey') || iconName === 'key') {
      return (
        <div className="w-9 h-9 flex items-center justify-center overflow-hidden rounded-xl bg-[#5EBA41]/10 border border-[#5EBA41]/20 p-1">
          <YubicoBrandSvg className="w-7 h-7" />
        </div>
      );
    }
    if (combined.includes('bitwarden')) {
      return (
        <div className="w-9 h-9 flex items-center justify-center overflow-hidden rounded-xl bg-[#175DDC]/10 border border-[#175DDC]/20 p-1">
          <BitwardenBrandSvg className="w-7 h-7" />
        </div>
      );
    }

    if (logoUrl) {
      return (
        <div className="w-9 h-9 flex items-center justify-center overflow-hidden rounded-xl bg-white p-1 shadow-md">
          <img 
            src={logoUrl} 
            alt="" 
            className="max-w-full max-h-full object-contain"
          />
        </div>
      );
    }

    return (
      <div className="w-9 h-9 flex items-center justify-center overflow-hidden rounded-xl bg-indigo-500/10 border border-indigo-500/20 text-indigo-400">
        <Key className="w-5 h-5" />
      </div>
    );
  };

  return (
    <div className="space-y-12">
