import React, { useState } from 'react';
import { Check, X, Shield, ShieldCheck, ShieldAlert, Eye, EyeOff } from 'lucide-react';

export interface PasswordRequirement {
  id: string;
  label: string;
  test: (p: string) => boolean;
}

export const PASSWORD_REQUIREMENTS: PasswordRequirement[] = [
  { id: 'length', label: 'Minimum 8 characters', test: (p: string) => (p || '').length >= 8 },
  { id: 'uppercase', label: 'At least one uppercase letter (A-Z)', test: (p: string) => /[A-Z]/.test(p || '') },
  { id: 'lowercase', label: 'At least one lowercase letter (a-z)', test: (p: string) => /[a-z]/.test(p || '') },
  { id: 'number', label: 'At least one number (0-9)', test: (p: string) => /[0-9]/.test(p || '') },
  { id: 'special', label: 'At least one special character (!@#$%^&*)', test: (p: string) => /[^A-Za-z0-9]/.test(p || '') },
];

/**
 * Validates whether all standard password requirements are met.
 */
export const isPasswordValid = (password: string): boolean => {
  return PASSWORD_REQUIREMENTS.every((req) => req.test(password));
};

/**
 * Calculates a strength rating score (0 to 100) and label for a password.
 */
export const getPasswordStrength = (password: string): {
  score: number;
  passedCount: number;
  label: string;
  colorClass: string;
  barColorClass: string;
} => {
  const p = password || '';
  if (!p) {
    return {
      score: 0,
      passedCount: 0,
      label: 'Enter Password',
      colorClass: 'text-slate-500',
      barColorClass: 'bg-slate-700',
    };
  }

  const passedCount = PASSWORD_REQUIREMENTS.filter((req) => req.test(p)).length;
  const score = Math.round((passedCount / PASSWORD_REQUIREMENTS.length) * 100);

  if (passedCount <= 2) {
    return {
      score,
      passedCount,
      label: 'Weak',
      colorClass: 'text-rose-400',
      barColorClass: 'bg-rose-500',
    };
  }
  if (passedCount <= 4) {
    return {
      score,
      passedCount,
      label: 'Moderate',
      colorClass: 'text-amber-400',
      barColorClass: 'bg-amber-500',
    };
  }
  return {
    score,
    passedCount,
    label: 'Strong & Secure',
    colorClass: 'text-emerald-400',
    barColorClass: 'bg-emerald-500',
  };
};

export interface PasswordChecklistProps {
  /** The current password string to test */
  password?: string;
  /** Optional interactive mode for testing inside sandboxes or registries without parent inputs */
  interactive?: boolean;
  /** Optional header title override */
  title?: string;
  /** Optional container class name */
  className?: string;
}

export const PasswordChecklist: React.FC<PasswordChecklistProps> = ({
  password: externalPassword,
  interactive = false,
  title = 'Password Security Standards',
  className = '',
}) => {
  const [internalPassword, setInternalPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);

  // If interactive or no external password prop provided, allow internal input
  const isInteractiveMode = interactive || externalPassword === undefined;
  const currentPassword = isInteractiveMode ? internalPassword : externalPassword;

  const strength = getPasswordStrength(currentPassword);
  const allPassed = isPasswordValid(currentPassword);

  return (
    <div className={`space-y-4 p-5 bg-slate-950/60 border border-white/5 rounded-2xl ${className}`}>
      {/* Interactive Sandbox Test Input if rendered in demo mode */}
      {isInteractiveMode && (
        <div className="space-y-2 pb-3 border-b border-white/5">
          <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">
            Interactive Test Input
          </label>
          <div className="relative">
            <input
              type={showPassword ? 'text' : 'password'}
              value={internalPassword}
              onChange={(e) => setInternalPassword(e.target.value)}
              placeholder="Type password to test..."
              className="w-full bg-slate-900 border border-white/10 rounded-xl px-3.5 py-2.5 text-xs text-white placeholder:text-slate-600 focus:outline-none focus:border-blue-500/50 font-mono"
            />
            <button
              type="button"
              onClick={() => setShowPassword(!showPassword)}
              className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-500 hover:text-slate-300 transition-colors"
            >
              {showPassword ? <EyeOff className="w-3.5 h-3.5" /> : <Eye className="w-3.5 h-3.5" />}
            </button>
          </div>
        </div>
      )}

      {/* Header & Strength Bar */}
      <div className="space-y-2">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            {allPassed ? (
              <ShieldCheck className="w-4 h-4 text-emerald-400" />
            ) : strength.passedCount > 2 ? (
              <Shield className="w-4 h-4 text-amber-400" />
            ) : (
              <ShieldAlert className="w-4 h-4 text-slate-500" />
            )}
            <span className="text-xs font-black tracking-wider uppercase text-white">
              {title}
            </span>
          </div>
          <span className={`text-[10px] font-black uppercase tracking-widest ${strength.colorClass}`}>
            {strength.label}
          </span>
        </div>

        {/* Dynamic Progress Bar */}
        <div className="w-full bg-slate-900/80 rounded-full h-1.5 overflow-hidden border border-white/5">
          <div
            className={`h-full transition-all duration-300 rounded-full ${strength.barColorClass}`}
            style={{ width: `${Math.max(strength.score, 6)}%` }}
          />
        </div>
      </div>

      {/* Requirements List */}
      <div className="grid grid-cols-1 gap-2 pt-1">
        {PASSWORD_REQUIREMENTS.map((req) => {
          const met = req.test(currentPassword);
          return (
            <div
              key={req.id}
              className={`flex items-center gap-2.5 transition-all text-xs font-medium ${
                met ? 'text-emerald-400' : 'text-slate-500'
              }`}
            >
              <div
                className={`w-4 h-4 rounded-md flex items-center justify-center border transition-all shrink-0 ${
                  met
                    ? 'bg-emerald-500/20 border-emerald-500/40 text-emerald-400'
                    : 'bg-slate-900 border-white/5 text-slate-600'
                }`}
              >
                {met ? <Check className="w-2.5 h-2.5 stroke-[3]" /> : <X className="w-2.5 h-2.5 opacity-40" />}
              </div>
              <span className={`text-[11px] ${met ? 'font-bold text-slate-200' : 'text-slate-500'}`}>
                {req.label}
              </span>
            </div>
          );
        })}
      </div>

      <div className="text-[10px] text-slate-600 font-medium pt-1">
        All standard special characters are accepted and encrypted at rest.
      </div>
    </div>
  );
};
export default PasswordChecklist;

/** @jsxImportSource react */
import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { KeyRound, Lock, ShieldCheck, ShieldAlert, Check, X, RefreshCw, Eye, EyeOff } from 'lucide-react';
import { PASSWORD_REQUIREMENTS, isPasswordValid, getPasswordStrength } from './PasswordChecklist';

interface PasswordManagementModuleProps {
  hasPassword?: boolean;
  onRequirePasskey?: () => void;
  notify?: (message: string, type: 'success' | 'error' | 'info') => void;
}

export function PasswordManagementModule({
  hasPassword = false,
  onRequirePasskey,
  notify,
}: PasswordManagementModuleProps) {
  const [isEditing, setIsEditing] = useState(false);
  const [currentPassword, setCurrentPassword] = useState('');
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [showCurrent, setShowCurrent] = useState(false);
  const [showNew, setShowNew] = useState(false);
  const [showConfirm, setShowConfirm] = useState(false);
  const [saving, setSaving] = useState(false);
  const [status, setStatus] = useState<{ type: 'success' | 'error'; message: string } | null>(null);

  const strength = getPasswordStrength(newPassword);
  const passwordsMatch = newPassword.length > 0 && newPassword === confirmPassword;
  const canSubmit = isPasswordValid(newPassword) && passwordsMatch && (!hasPassword || currentPassword.length > 0);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!canSubmit) return;

    setSaving(true);
    setStatus(null);

    try {
      const storedToken = typeof window !== 'undefined' ? localStorage.getItem('foundation_session') : null;
      const headers: Record<string, string> = {
        'Content-Type': 'application/json',
      };
      if (storedToken) {
        headers['Authorization'] = `Bearer ${storedToken}`;
      }

      const res = await fetch('/api/auth/password/change', {
        method: 'POST',
        headers,
        credentials: 'include',
        body: JSON.stringify({
          currentPassword: hasPassword ? currentPassword : '',
          newPassword,
        }),
      });

      const data = await res.json() as any;

      if (data.success) {
        const msg = hasPassword ? 'Password successfully changed!' : 'Password successfully created!';
        setStatus({ type: 'success', message: msg });
        notify?.(msg, 'success');
        setCurrentPassword('');
        setNewPassword('');
        setConfirmPassword('');
        setIsEditing(false);

        if (typeof window !== 'undefined') {
          window.dispatchEvent(new CustomEvent('foundation-auth-change'));
          window.dispatchEvent(new CustomEvent('foundation-user-updated', { detail: { hasPassword: true } }));
        }
      } else if (res.status === 403) {
        setStatus({ type: 'error', message: 'Security verification required.' });
        onRequirePasskey?.();
      } else {
        const err = data.error || 'Failed to update password.';
        setStatus({ type: 'error', message: err });
        notify?.(err, 'error');
      }
    } catch {
      const err = 'Network error — unable to save password.';
      setStatus({ type: 'error', message: err });
      notify?.(err, 'error');
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className="p-8 sm:p-10 rounded-[2.5rem] bg-slate-900/40 border border-white/5 space-y-6">
      <div className="flex items-start sm:items-center justify-between gap-4 flex-col sm:flex-row">
        <div className="flex items-center gap-4">
          <div className="p-3 bg-blue-500/10 rounded-2xl border border-blue-500/20 shrink-0">
            <KeyRound className="w-6 h-6 text-blue-400" />
          </div>
          <div>
            <div className="flex items-center gap-2">
              <h3 className="text-xl font-black text-white uppercase tracking-tight">Account Password</h3>
              <span className={`px-2 py-0.5 rounded-md text-[9px] font-black uppercase tracking-wider border ${
                hasPassword 
                  ? 'bg-emerald-500/10 text-emerald-400 border-emerald-500/20' 
                  : 'bg-amber-500/10 text-amber-400 border-amber-500/20'
              }`}>
                {hasPassword ? 'Configured' : 'Not Set'}
              </span>
            </div>
            <p className="text-slate-400 text-xs mt-0.5">
              {hasPassword
                ? 'Your account has an active password for credential and SSO logins.'
                : 'You are using passwordless / OAuth sign-in. You can set a password for direct logins.'}
            </p>
          </div>
        </div>

        <button
          type="button"
          onClick={() => {
            setIsEditing(!isEditing);
            setStatus(null);
          }}
          className="px-4 py-2 rounded-xl bg-slate-800 hover:bg-slate-700 text-white text-xs font-bold transition-all shrink-0 cursor-pointer"
        >
          {isEditing ? 'Cancel' : hasPassword ? 'Change Password' : 'Create Password'}
        </button>
      </div>

      <AnimatePresence>
        {isEditing && (
          <motion.form
            initial={{ opacity: 0, height: 0 }}
            animate={{ opacity: 1, height: 'auto' }}
            exit={{ opacity: 0, height: 0 }}
            transition={{ duration: 0.2 }}
            onSubmit={handleSubmit}
            className="pt-6 border-t border-white/5 space-y-5 overflow-hidden"
          >
            {hasPassword && (
              <div className="space-y-1.5">
                <label className="text-xs font-bold text-slate-300">Current Password</label>
                <div className="relative">
                  <input
                    type={showCurrent ? 'text' : 'password'}
                    value={currentPassword}
                    onChange={(e) => setCurrentPassword(e.target.value)}
                    placeholder="Enter current password"
                    className="w-full px-4 py-3 rounded-2xl bg-slate-950 border border-slate-800 text-xs font-mono text-white placeholder-slate-600 focus:outline-none focus:border-blue-500 transition-colors pr-10"
                    required
                  />
                  <button
                    type="button"
