import { useToast } from './common';

interface Session {
  id: string;
  os: string | null;
  browser: string | null;
  ipV4: string | null;
  ipV6: string | null;
  ipAddress: string | null;
  location: string | null;
  deviceName: string | null;
  userAgent: string | null;
  isCurrent: boolean;
  isPersistent: boolean;
  lastActiveAt: string;
  createdAt: string;
  expiresAt: string;
  passkeyVerifiedAt: string | null;
  cfRay: string | null;
}

export const SessionModule = ({ onRequirePasskey }: { onRequirePasskey?: () => void }) => {
  const { addToast } = useToast();
  const [sessions, setSessions] = useState<Session[]>([]);
  const [loading, setLoading] = useState(true);
  const [revokingId, setRevokingId] = useState<string | null>(null);
  const [revokingAll, setRevokingAll] = useState(false);
  const [showLegend, setShowLegend] = useState(false);

  const fetchSessions = async () => {
    setLoading(true);
    try {
      const res = await fetch('/admin/sessions');
      if (res.status === 403) {
        if (onRequirePasskey) onRequirePasskey();
        return;
      }
      if (!res.ok) throw new Error('Failed to fetch sessions');
      const data = await res.json() as any;
      setSessions(data.sessions || []);
    } catch (err) {
      addToast('Could not load active sessions.', 'error');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchSessions();
  }, []);

  const revokeSession = async (id: string) => {
    setRevokingId(id);
    try {
      const res = await fetch(`/admin/sessions/${id}`, { method: 'DELETE' });
      if (res.status === 403) {
        if (onRequirePasskey) onRequirePasskey();
        return;
      }
      if (!res.ok) throw new Error('Failed to revoke session');

      setSessions(prev => prev.filter(s => s.id !== id));
      addToast('Session revoked successfully.', 'success');
    } catch (err) {
      addToast('Failed to revoke session.', 'error');
    } finally {
      setRevokingId(null);
    }
  };

  const revokeAllOtherSessions = async () => {
    setRevokingAll(true);
    try {
      const res = await fetch('/admin/sessions', { method: 'DELETE' });
      if (res.status === 403) {
        if (onRequirePasskey) onRequirePasskey();
        return;
      }
      if (!res.ok) throw new Error('Failed to revoke other sessions');

      setSessions(prev => prev.filter(s => s.isCurrent));
      addToast('All other sessions revoked successfully.', 'success');
