export interface ServiceLayer {
  id: string;
  name: string;
  category?: string;
  icon?: string | React.ReactNode;
  metadata?: Record<string, any>;
}

export interface InstanceLayer {
  id: string;
  serviceId: string;
  name: string;
  ownerName?: string;
  ownerAvatar?: string;
  amountFormatted?: string;
  cadence?: string;
  dueDateFormatted?: string;
  notes?: string;
  metadata?: Record<string, any>;
}

export interface AbstractInstancePickerProps {
  services: ServiceLayer[];
  instances: InstanceLayer[];
  selectedInstanceId?: string | null;
  onChange: (instanceId: string | null, selectedInstance?: InstanceLayer | null, service?: ServiceLayer | null) => void;
  placeholder?: string;
  label?: string;
  disabled?: boolean;
  className?: string;
}

export const AbstractInstancePicker: React.FC<AbstractInstancePickerProps> = ({
  services = [],
  instances = [],
  selectedInstanceId,
  onChange,
  placeholder = 'Select service or instance...',
  label,
  disabled = false,
  className = ''
}) => {
  const [isOpen, setIsOpen] = useState(false);
  const [search, setSearch] = useState('');
  const [selectedServiceFilter, setSelectedServiceFilter] = useState<string | null>(null);

  const triggerRef = useRef<HTMLDivElement>(null);
  const dropdownRef = useRef<HTMLDivElement>(null);
  const [coords, setCoords] = useState<{ top: number; left: number; width: number; placeAbove: boolean }>({
    top: 0,
    left: 0,
    width: 0,
    placeAbove: false
  });

  const selectedInstance = instances.find(i => i.id === selectedInstanceId) || null;
  const selectedService = selectedInstance ? services.find(s => s.id === selectedInstance.serviceId) : null;

  const updatePosition = () => {
    if (!triggerRef.current) return;
    const rect = triggerRef.current.getBoundingClientRect();
    const dropdownHeight = 360;
    const margin = 8;
    const placeAbove = rect.bottom + dropdownHeight > window.innerHeight && rect.top > dropdownHeight;

    // Viewport edge clamping
    const width = Math.min(rect.width, window.innerWidth - 24);
    let left = rect.left;
    if (left + width > window.innerWidth - 12) {
      left = window.innerWidth - width - 12;
    }
    if (left < 12) left = 12;

    setCoords({
      top: placeAbove ? rect.top - dropdownHeight - margin : rect.bottom + margin,
      left,
      width,
      placeAbove
    });
  };

  useEffect(() => {
    if (isOpen) {
      updatePosition();
      const handleResizeOrScroll = () => updatePosition();
      window.addEventListener('resize', handleResizeOrScroll, { passive: true });
      window.addEventListener('scroll', handleResizeOrScroll, true);
      return () => {
        window.removeEventListener('resize', handleResizeOrScroll);
        window.removeEventListener('scroll', handleResizeOrScroll, true);
      };
    }
  }, [isOpen]);

  useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => {
      if (
        dropdownRef.current && !dropdownRef.current.contains(e.target as Node) &&
        triggerRef.current && !triggerRef.current.contains(e.target as Node)
      ) {
        setIsOpen(false);
      }
    };
    if (isOpen) {
      document.addEventListener('mousedown', handleClickOutside);
      return () => document.removeEventListener('mousedown', handleClickOutside);
    }
  }, [isOpen]);

  // Filter instances
  const filteredInstances = instances.filter(inst => {
    if (selectedServiceFilter && inst.serviceId !== selectedServiceFilter) return false;
    if (!search.trim()) return true;
    const q = search.toLowerCase();
    const service = services.find(s => s.id === inst.serviceId);
    return (
      inst.name.toLowerCase().includes(q) ||
      (inst.ownerName && inst.ownerName.toLowerCase().includes(q)) ||
      (service && service.name.toLowerCase().includes(q)) ||
      (inst.cadence && inst.cadence.toLowerCase().includes(q)) ||
      (inst.notes && inst.notes.toLowerCase().includes(q))
    );
  });

  return (
    <div className={`relative ${className}`}>
      {label && (
        <label className="text-xs font-black tracking-widest text-slate-400 mb-1.5 flex items-center justify-between">
          <span className="flex items-center gap-1.5">
            <Layers size={13} className="text-amber-400" />
            {label}
          </span>
          <span className="text-[10px] text-amber-400/80 font-normal">Layer 1 Service & Layer 2 Instance</span>
        </label>
      )}

      <div
        ref={triggerRef}
        onClick={() => !disabled && setIsOpen(!isOpen)}
        className={`w-full bg-black/60 border rounded-xl p-3 flex items-center justify-between transition-all cursor-pointer select-none ${
          disabled ? 'opacity-50 cursor-not-allowed border-white/5' :
          isOpen ? 'border-amber-500/60 ring-2 ring-amber-500/20 shadow-lg shadow-amber-500/5' : 'border-white/10 hover:border-white/20'
        }`}
      >
        <div className="flex items-center gap-2.5 min-w-0 flex-1">
          {selectedInstance ? (
            <>
              <div className="w-8 h-8 rounded-lg bg-amber-500/10 border border-amber-500/20 flex items-center justify-center text-amber-400 shrink-0 text-sm font-bold">
                {selectedService?.icon || '🧾'}
              </div>
              <div className="min-w-0 flex-1">
                <div className="flex items-center gap-2">
                  <span className="text-sm font-bold text-white truncate">{selectedInstance.name}</span>
                  {selectedInstance.ownerName && (
                    <span className="text-[11px] px-1.5 py-0.5 rounded bg-white/10 text-slate-300 font-medium">
                      {selectedInstance.ownerName}
                    </span>
                  )}
                </div>
                <div className="flex items-center gap-2 text-[11px] text-slate-400 mt-0.5">
                  {selectedService && <span className="font-semibold text-amber-400/90">{selectedService.name}</span>}
                  {selectedInstance.amountFormatted && <span>• {selectedInstance.amountFormatted}</span>}
                  {selectedInstance.cadence && <span>/{selectedInstance.cadence}</span>}
                  {selectedInstance.dueDateFormatted && <span>• Due {selectedInstance.dueDateFormatted}</span>}
                </div>
              </div>
            </>
          ) : (
            <span className="text-sm text-slate-500">{placeholder}</span>
          )}
        </div>

        <div className="flex items-center gap-1.5 ml-2 shrink-0">
          {selectedInstance && (
            <button
              type="button"
              onClick={(e) => {
                e.stopPropagation();
                onChange(null, null, null);
              }}
              className="p-1 text-slate-500 hover:text-white rounded-md hover:bg-white/10 transition-colors"
              title="Clear selection"
            >
              <X size={14} />
            </button>
          )}
          <ChevronDown
            size={16}
            className={`text-slate-400 transition-transform duration-200 ${isOpen ? 'rotate-180 text-amber-400' : ''}`}
          />
        </div>
      </div>

      {isOpen && typeof document !== 'undefined' && createPortal(
        <div
          ref={dropdownRef}
          style={{
            position: 'fixed',
            top: coords.top,
            left: coords.left,
            width: coords.width,
            maxHeight: 380,
            zIndex: 9999
          }}
          className="bg-slate-900/95 backdrop-blur-xl border border-white/15 rounded-2xl shadow-2xl overflow-hidden flex flex-col animate-in fade-in zoom-in-95 duration-150"
        >
          {/* Search Header */}
          <div className="p-3 border-b border-white/10 space-y-2 shrink-0">
            <div className="relative">
              <Search size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
              <input
                type="text"
                value={search}
                onChange={e => setSearch(e.target.value)}
                placeholder="Search services, members, or instances..."
                autoFocus
                className="w-full bg-black/40 border border-white/10 rounded-xl pl-9 pr-3 py-2 text-xs text-white placeholder-slate-500 focus:outline-none focus:border-amber-500/50"
              />
            </div>

            {/* Service Filters */}
            {services.length > 0 && (
              <div className="flex items-center gap-1.5 overflow-x-auto pb-1 custom-scrollbar">
                <button
                  type="button"
                  onClick={() => setSelectedServiceFilter(null)}
                  className={`text-[10px] font-bold px-2.5 py-1 rounded-lg transition-all shrink-0 ${
                    selectedServiceFilter === null
                      ? 'bg-amber-500 text-black shadow-sm font-black'
                      : 'bg-white/5 text-slate-400 hover:bg-white/10 hover:text-white'
                  }`}
                >
                  All Services ({instances.length})
                </button>
                {services.map(srv => {
                  const count = instances.filter(i => i.serviceId === srv.id).length;
                  return (
                    <button
                      key={srv.id}
                      type="button"
                      onClick={() => setSelectedServiceFilter(selectedServiceFilter === srv.id ? null : srv.id)}
                      className={`text-[10px] font-bold px-2.5 py-1 rounded-lg transition-all shrink-0 flex items-center gap-1 ${
                        selectedServiceFilter === srv.id
                          ? 'bg-amber-500 text-black shadow-sm font-black'
                          : 'bg-white/5 text-slate-400 hover:bg-white/10 hover:text-white'
                      }`}
                    >
                      <span>{srv.icon || '🏷️'}</span>
                      <span>{srv.name}</span>
                      <span className="opacity-70 text-[9px]">({count})</span>
                    </button>
                  );
                })}
              </div>
            )}
          </div>

          {/* Instance List */}
          <div className="overflow-y-auto p-2 space-y-1 flex-1 custom-scrollbar">
            {filteredInstances.length === 0 ? (
              <div className="p-8 text-center text-xs text-slate-500">
                No instances found
              </div>
            ) : (
              filteredInstances.map(inst => {
                const srv = services.find(s => s.id === inst.serviceId);
                const isSelected = inst.id === selectedInstanceId;

                return (
                  <div
                    key={inst.id}
                    onClick={() => {
                      onChange(inst.id, inst, srv);
                      setIsOpen(false);
                    }}
                    className={`p-2.5 rounded-xl transition-all cursor-pointer flex items-center justify-between gap-3 ${
                      isSelected
                        ? 'bg-amber-500/20 border border-amber-500/40 text-amber-200'
                        : 'hover:bg-white/5 border border-transparent text-slate-200'
                    }`}
                  >
                    <div className="flex items-center gap-2.5 min-w-0 flex-1">
                      <div className="w-7 h-7 rounded-lg bg-white/5 border border-white/10 flex items-center justify-center text-xs shrink-0">
                        {srv?.icon || '🧾'}
                      </div>
                      <div className="min-w-0 flex-1">
                        <div className="flex items-center gap-2">
                          <span className="text-xs font-bold text-white truncate">{inst.name}</span>
                          {inst.ownerName && (
                            <span className="text-[10px] px-1.5 py-0.2 rounded bg-white/10 text-slate-300 font-medium">
                              {inst.ownerName}
                            </span>
                          )}
                        </div>
                        <div className="flex items-center gap-1.5 text-[10px] text-slate-400 mt-0.5 flex-wrap">
                          {srv && <span className="font-medium text-amber-400/90">{srv.name}</span>}
                          {inst.amountFormatted && <span>• {inst.amountFormatted}</span>}
                          {inst.cadence && <span>/{inst.cadence}</span>}
                          {inst.dueDateFormatted && <span>• Due {inst.dueDateFormatted}</span>}
                        </div>
                      </div>
                    </div>

                    {isSelected && (
                      <Check size={16} className="text-amber-400 shrink-0" />
                    )}
                  </div>
                );
              })
            )}
          </div>
        </div>,
        document.body
      )}
    </div>
  );
};

