} from '@shared/cookie-consent';

export const CookieConsentBanner: React.FC = () => {
  const [isVisible, setIsVisible] = useState(false);
  const [showPreferencesModal, setShowPreferencesModal] = useState(false);
  const [preferences, setPreferences] = useState<CookieConsentPreferences>(DEFAULT_CONSENT_PREFERENCES);

  useEffect(() => {
    // Check if consent has already been established
    const existing = getCookieConsent();
    if (!existing) {
      setIsVisible(true);
    } else {
      setPreferences(existing);
    }

    // Listen for custom trigger to reopen modal (e.g. from Cookie Policy page or footer)
    const handleOpenModal = () => {
      const current = getCookieConsent() || DEFAULT_CONSENT_PREFERENCES;
      setPreferences(current);
      setShowPreferencesModal(true);
    };

    window.addEventListener('gp-open-cookie-preferences', handleOpenModal);
    return () => {
      window.removeEventListener('gp-open-cookie-preferences', handleOpenModal);
    };
  }, []);

  const handleAcceptAll = () => {
    const updated = saveCookieConsent({
      functional: true,
      analytics: true,
    });
    setPreferences(updated);
    setIsVisible(false);
    setShowPreferencesModal(false);
  };

  const handleRejectNonEssential = () => {
    const updated = saveCookieConsent({
      functional: false,
      analytics: false,
    });
    setPreferences(updated);
    setIsVisible(false);
    setShowPreferencesModal(false);
  };

  const handleSaveCustom = () => {
    const updated = saveCookieConsent({
      functional: preferences.functional,
      analytics: preferences.analytics,
    });
    setPreferences(updated);
    setIsVisible(false);
    setShowPreferencesModal(false);
  };

  return (
    <>
      {/* Floating Bottom Cookie Consent Banner */}
      <AnimatePresence>
        {isVisible && (
          <motion.aside
            initial={{ opacity: 0, y: 50, scale: 0.95 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, y: 50, scale: 0.95 }}
            transition={{ type: 'spring', damping: 25, stiffness: 300 }}
            aria-label="Cookie consent notice"
            className="fixed bottom-6 left-6 right-6 md:left-auto md:right-8 md:max-w-md z-[999] bg-slate-900/90 backdrop-blur-xl border border-white/10 rounded-[2rem] p-6 shadow-2xl shadow-cyan-950/40 text-slate-100"
          >
            <div className="flex items-start space-x-4">
              <div className="p-3 bg-cyan-500/10 border border-cyan-500/20 rounded-2xl text-cyan-400 shrink-0 mt-0.5">
                <Cookie className="w-5 h-5" />
              </div>
              <div className="space-y-2">
                <h3 className="text-sm font-black uppercase tracking-wider text-white">
                  Cookie & Privacy Choices
                </h3>
                <p className="text-xs text-slate-400 leading-relaxed">
                  We use essential cookies for security and authentication. Optional cookies help us remember preferences and improve platform telemetry. You can opt-in or opt-out at any time.
                </p>
              </div>
            </div>

            <div className="flex items-center justify-between gap-2 mt-5 pt-4 border-t border-white/5">
              <button
                type="button"
                onClick={() => setShowPreferencesModal(true)}
                className="text-[11px] font-bold text-slate-400 hover:text-cyan-400 underline underline-offset-4 transition-colors"
              >
                Customize
              </button>
              <div className="flex items-center space-x-2">
                <button
                  type="button"
                  onClick={handleRejectNonEssential}
                  className="px-3.5 py-2 rounded-xl text-xs font-bold bg-slate-800 hover:bg-slate-700 text-slate-300 transition-all active:scale-95"
                >
                  Essential Only
                </button>
                <button
                  type="button"
                  onClick={handleAcceptAll}
                  className="px-4 py-2 rounded-xl text-xs font-black uppercase tracking-wider bg-cyan-500 hover:bg-cyan-400 text-slate-950 transition-all shadow-lg shadow-cyan-500/20 active:scale-95"
                >
                  Accept All
                </button>
              </div>
            </div>
          </motion.aside>
        )}
      </AnimatePresence>

      {/* Granular Cookie Preferences Modal */}
      <AnimatePresence>
        {showPreferencesModal && (
          <div className="fixed inset-0 z-[1000] flex items-center justify-center p-4 sm:p-6">
            <motion.div
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              onClick={() => setShowPreferencesModal(false)}
              className="fixed inset-0 bg-slate-950/80 backdrop-blur-md"
            />

            <motion.div
              initial={{ opacity: 0, scale: 0.95, y: 15 }}
              animate={{ opacity: 1, scale: 1, y: 0 }}
              exit={{ opacity: 0, scale: 0.95, y: 15 }}
              className="relative w-full max-w-lg bg-slate-900 border border-slate-800 rounded-[2.5rem] p-6 sm:p-8 shadow-2xl z-10 space-y-6"
            >
              <div className="flex items-start justify-between">
                <div className="flex items-center space-x-3">
                  <div className="p-3 bg-cyan-500/10 border border-cyan-500/20 rounded-2xl text-cyan-400">
                    <Settings2 className="w-5 h-5" />
                  </div>
                  <div>
                    <h2 className="text-lg font-black text-white">Cookie Preferences</h2>
                    <p className="text-xs text-slate-400 font-medium">Manage and adjust your privacy permissions.</p>
                  </div>
                </div>
                <button
                  onClick={() => setShowPreferencesModal(false)}
                  className="p-2 text-slate-400 hover:text-white rounded-xl hover:bg-slate-800 transition-colors"
                >
                  <X className="w-5 h-5" />
                </button>
              </div>

              {/* Category Controls */}
              <div className="space-y-4">
                {/* Essential */}
                <div className="p-4 bg-slate-950/60 border border-slate-800 rounded-2xl flex items-start justify-between gap-4">
                  <div className="space-y-1">
                    <div className="flex items-center space-x-2">
                      <span className="text-xs font-bold text-white uppercase tracking-wider">Strictly Essential</span>
                      <span className="text-[10px] font-black uppercase px-2 py-0.5 rounded-full bg-cyan-500/10 text-cyan-400 border border-cyan-500/20">Required</span>
                    </div>
                    <p className="text-xs text-slate-400 leading-relaxed">
                      Required for security, zero-trust hardware passkeys, SSO routing, and session state. Cannot be disabled.
                    </p>
                  </div>
                  <input
                    type="checkbox"
