                    className="w-5 h-5 rounded accent-cyan-500 cursor-not-allowed opacity-80 mt-1"
                  />
                </div>

                {/* Functional */}
                <div className="p-4 bg-slate-950/60 border border-slate-800 rounded-2xl flex items-start justify-between gap-4">
                  <div className="space-y-1">
                    <div className="flex items-center space-x-2">
                      <span className="text-xs font-bold text-white uppercase tracking-wider">Functional Preferences</span>
                      <span className="text-[10px] font-black uppercase px-2 py-0.5 rounded-full bg-slate-800 text-slate-400">Optional</span>
                    </div>
                    <p className="text-xs text-slate-400 leading-relaxed">
                      Remembers your application settings, active server selections, layout preferences, and UI themes.
                    </p>
                  </div>
                  <input
                    type="checkbox"
                    id="pref-functional"
                    checked={preferences.functional}
                    onChange={(e) => setPreferences({ ...preferences, functional: e.target.checked })}
                    className="w-5 h-5 rounded accent-cyan-500 cursor-pointer mt-1"
                  />
                </div>

                {/* Analytics */}
                <div className="p-4 bg-slate-950/60 border border-slate-800 rounded-2xl flex items-start justify-between gap-4">
                  <div className="space-y-1">
                    <div className="flex items-center space-x-2">
                      <span className="text-xs font-bold text-white uppercase tracking-wider">Analytics & Performance</span>
                      <span className="text-[10px] font-black uppercase px-2 py-0.5 rounded-full bg-slate-800 text-slate-400">Optional</span>
                    </div>
                    <p className="text-xs text-slate-400 leading-relaxed">
                      Provides anonymized telemetry on feature usage, route latency, and error reporting to help us improve.
                    </p>
                  </div>
                  <input
                    type="checkbox"
                    id="pref-analytics"
                    checked={preferences.analytics}
                    onChange={(e) => setPreferences({ ...preferences, analytics: e.target.checked })}
