import React, { useState, useEffect } from 'react';
import { Clock } from 'lucide-react';

interface DurationInputProps {
  seconds: number;
  onChange: (totalSeconds: number) => void;
  label?: string;
  minSeconds?: number;
  maxSeconds?: number;
}

export function DurationInput({
  seconds,
  onChange,
  label,
  minSeconds = 1,
  maxSeconds = 86400 * 30,
}: DurationInputProps) {
  const [mode, setMode] = useState<'hms' | 'seconds'>('hms');

  // Compute breakdown
  const hours = Math.floor(seconds / 3600);
  const minutes = Math.floor((seconds % 3600) / 60);
  const secs = seconds % 60;

  const handleHmsChange = (newH: number, newM: number, newS: number) => {
    const total = Math.max(minSeconds, Math.min(newH * 3600 + newM * 60 + newS, maxSeconds));
    onChange(total);
  };

  const handleSecondsChange = (val: number) => {
    const total = Math.max(minSeconds, Math.min(val || 0, maxSeconds));
    onChange(total);
  };

  return (
    <div className="space-y-2">
      <div className="flex items-center justify-between">
        {label && (
          <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">
            {label}
          </label>
        )}
        <div className="flex items-center gap-1 p-0.5 bg-slate-950 rounded-lg border border-white/5 text-[10px] font-black uppercase">
          <button
            type="button"
            onClick={() => setMode('hms')}
            className={`px-2 py-1 rounded-md transition-colors ${
              mode === 'hms' ? 'bg-blue-600 text-white' : 'text-slate-500 hover:text-slate-300'
            }`}
          >
            H / M / S
          </button>
          <button
            type="button"
            onClick={() => setMode('seconds')}
            className={`px-2 py-1 rounded-md transition-colors ${
              mode === 'seconds' ? 'bg-blue-600 text-white' : 'text-slate-500 hover:text-slate-300'
            }`}
          >
            Raw Seconds
          </button>
        </div>
      </div>

      {mode === 'hms' ? (
        <div className="grid grid-cols-3 gap-2">
          <div className="space-y-1">
            <div className="text-[9px] font-bold text-slate-500 uppercase">Hours</div>
            <div className="relative">
              <input
                type="number"
                min={0}
                max={720}
                value={hours}
                onChange={(e) => handleHmsChange(parseInt(e.target.value, 10) || 0, minutes, secs)}
                className="w-full bg-slate-950 border border-slate-800 rounded-xl px-3 py-2.5 text-xs text-white font-mono font-bold text-center focus:outline-none focus:border-blue-500"
              />
              <span className="absolute right-2.5 top-1/2 -translate-y-1/2 text-[10px] text-slate-500 font-bold pointer-events-none">h</span>
            </div>
          </div>

          <div className="space-y-1">
            <div className="text-[9px] font-bold text-slate-500 uppercase">Minutes</div>
            <div className="relative">
              <input
                type="number"
                min={0}
                max={59}
                value={minutes}
                onChange={(e) => handleHmsChange(hours, parseInt(e.target.value, 10) || 0, secs)}
                className="w-full bg-slate-950 border border-slate-800 rounded-xl px-3 py-2.5 text-xs text-white font-mono font-bold text-center focus:outline-none focus:border-blue-500"
              />
              <span className="absolute right-2.5 top-1/2 -translate-y-1/2 text-[10px] text-slate-500 font-bold pointer-events-none">m</span>
            </div>
          </div>

          <div className="space-y-1">
            <div className="text-[9px] font-bold text-slate-500 uppercase">Seconds</div>
            <div className="relative">
              <input
                type="number"
                min={0}
                max={59}
                value={secs}
                onChange={(e) => handleHmsChange(hours, minutes, parseInt(e.target.value, 10) || 0)}
                className="w-full bg-slate-950 border border-slate-800 rounded-xl px-3 py-2.5 text-xs text-white font-mono font-bold text-center focus:outline-none focus:border-blue-500"
              />
              <span className="absolute right-2.5 top-1/2 -translate-y-1/2 text-[10px] text-slate-500 font-bold pointer-events-none">s</span>
            </div>
          </div>
        </div>
      ) : (
        <div className="relative">
          <input
            type="number"
            min={minSeconds}
            max={maxSeconds}
            value={seconds}
            onChange={(e) => handleSecondsChange(parseInt(e.target.value, 10) || 0)}
            className="w-full bg-slate-950 border border-slate-800 rounded-xl px-4 py-2.5 text-xs text-white font-mono font-bold focus:outline-none focus:border-blue-500"
          />
          <span className="absolute right-3.5 top-1/2 -translate-y-1/2 text-xs text-slate-500 font-mono">
            seconds ({hours > 0 ? `${hours}h ` : ''}{minutes > 0 ? `${minutes}m ` : ''}{secs}s)
          </span>
        </div>
      )}
    </div>
  );
}

