import { useAuth } from '@shared/auth/client';
import { Loader2, Shield, Lock, ArrowRight } from 'lucide-react';

interface GuardProps {
  children: React.ReactNode;
}

export const Guard: React.FC<GuardProps> = ({ children }) => {
  const { user, loading } = useAuth();
  console.log('[AUTH_FLOW:E] Guard render', { loading, authenticated: !!user, userId: user?.id });

  if (loading) {
    return (
      <div className="min-h-screen bg-slate-950 flex items-center justify-center">
        <Loader2 className="w-8 h-8 text-white animate-spin" />
      </div>
    );
  }

  if (!user) {
    return (
      <div className="min-h-screen bg-slate-950 flex items-center justify-center p-4">
        <div className="max-w-md w-full bg-slate-900/50 backdrop-blur-xl border border-white/10 rounded-2xl p-8 text-center">
          <div className="w-16 h-16 bg-red-500/20 rounded-full flex items-center justify-center mx-auto mb-6">
            <Lock className="w-8 h-8 text-red-500" />
          </div>
          <h2 className="text-2xl font-black text-white mb-2">Security Verification Required</h2>
          <p className="text-slate-400 mb-8">This area is protected. Please sign in to continue.</p>
          <button 
            onClick={() => window.location.href = '/'}
            className="w-full py-3 bg-white text-black font-semibold rounded-xl flex items-center justify-center gap-2 hover:bg-slate-200 transition-colors"
          >
            Return to Safety <ArrowRight className="w-4 h-4" />
          </button>
        </div>
      </div>
    );
  }

  return <>{children}</>;
};

/** @jsxImportSource react */
import React, { useState, useEffect, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { 
  Shield, 
  ChevronDown, 
  User, 
  LogOut, 
  Settings, 
  Bell, 
  LayoutGrid, 
  Wrench, 
  ShieldCheck, 
  Trash2, 
  Lock, 
  HelpCircle,
  ExternalLink,
  Sparkles,
  CheckCircle2,
  Server,
  Activity,
  Check,
  Clock,
  AlertTriangle,
  Info,
  RefreshCw,
  X,
  ChevronRight,
  Search
} from 'lucide-react';
import { useAuth } from '@shared/auth/client';
import { formatAvatarUrl } from '../../services/avatar';
import { FLEET_VERSION } from '@shared/constants';
import { Wordmark } from './Wordmark';

interface HeaderProps {
  navigate?: (to: string) => void;
}

interface NotificationItem {
  id: number;
  guildId?: string;
  sourceProject?: string;
  sourceProjectName?: string;
  actorId: string;
  actorName: string;
  actorUsername?: string | null;
  actorAvatar?: string | null;
  action: string;
  friendlyAction?: string;
  targetType: string;
  friendlyTarget?: string;
  reason?: string;
  targetId?: string | null;
  recordId?: string | null;
  severity?: string | null;
  location?: string | null;
  ipAddress?: string | null;
  oldValuesJson?: string | null;
  newValuesJson?: string | null;
  metadataJson?: string | null;
  createdAt: string;
}

export function Header({ navigate }: HeaderProps) {
  const { user, logout } = useAuth();
  const [isOpen, setIsOpen] = useState(false);
  const [isNotifOpen, setIsNotifOpen] = useState(false);
  const [isFullHistoryOpen, setIsFullHistoryOpen] = useState(false);
  const [notifications, setNotifications] = useState<NotificationItem[]>([]);
  const [isLoadingNotifs, setIsLoadingNotifs] = useState(false);
  const [unreadCount, setUnreadCount] = useState(0);
  const [historySearch, setHistorySearch] = useState('');
  const [lastReadTimestamp, setLastReadTimestamp] = useState<string>(() => {
    if (typeof window !== 'undefined') {
      return localStorage.getItem('foundation_last_read_notif') || '';
    }
    return '';
  });
  const [selectedNotif, setSelectedNotif] = useState<NotificationItem | null>(null);
  const [notifFilter, setNotifFilter] = useState<'all' | 'portainer' | 'wrestler' | 'auth' | 'system' | 'user'>('all');
  const [projectFilter, setProjectFilter] = useState<string>('all');
  const [deletingLogId, setDeletingLogId] = useState<number | null>(null);
  const [scrolled, setScrolled] = useState(false);

  const menuRef = useRef<HTMLDivElement>(null);
  const notifRef = useRef<HTMLDivElement>(null);

  const isOwner = user?.globalRole?.toLowerCase() === 'owner';

  const handleDeleteLog = async (logId: number, e: React.MouseEvent) => {
    e.stopPropagation();
    if (!confirm(`Are you sure you want to permanently delete audit log record #${logId}? This action is irreversible and restricted to the Owner.`)) {
      return;
    }

    setDeletingLogId(logId);
    try {
      const res = await fetch(`/api/admin/activity-logs/${logId}`, {
        method: 'DELETE',
        credentials: 'include'
      });
      const data = await res.json() as { success: boolean; error?: string };
      if (data.success) {
        setNotifications(prev => prev.filter(n => n.id !== logId));
      } else {
        alert(data.error || 'Failed to delete log entry.');
      }
    } catch (e) {
      alert('Error communicating with server.');
    } finally {
      setDeletingLogId(null);
    }
  };

  const fetchNotifications = async () => {
    setIsLoadingNotifs(true);
    try {
      const res = await fetch('/api/admin/activity-logs?limit=250', {
        headers: { 'Accept': 'application/json' },
        credentials: 'include'
      });
      if (res.ok) {
        const data = await res.json() as { success: boolean; logs?: any[] };
        if (data.success && Array.isArray(data.logs)) {
          setNotifications(data.logs);

          // Calculate unread items based on last read timestamp
          if (lastReadTimestamp) {
            const count = data.logs.filter((l: NotificationItem) => new Date(l.createdAt).getTime() > new Date(lastReadTimestamp).getTime()).length;
            setUnreadCount(count);
          } else {
            setUnreadCount(Math.min(data.logs.length, 5));
          }
        }
      }
    } catch (e) {
      console.warn('Failed to fetch notifications:', e);
    } finally {
      setIsLoadingNotifs(false);
    }
  };

  useEffect(() => {
    fetchNotifications();
    const interval = setInterval(fetchNotifications, 60000); // 1-minute live poll
    return () => clearInterval(interval);
  }, []);

  const handleMarkAllRead = () => {
    const now = new Date().toISOString();
    setLastReadTimestamp(now);
    setUnreadCount(0);
    if (typeof window !== 'undefined') {
      localStorage.setItem('foundation_last_read_notif', now);
    }
  };

  useEffect(() => {
    const handleScroll = () => setScrolled(window.scrollY > 10);
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(e.target as Node)) {
        setIsOpen(false);
      }
      if (notifRef.current && !notifRef.current.contains(e.target as Node)) {
        setIsNotifOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleNav = (path: string) => {
    setIsOpen(false);
    setIsNotifOpen(false);
    if (navigate) {
      navigate(path);
    } else if (typeof window !== 'undefined') {
      window.location.href = path;
    }
  };

  const getActionBadge = (action: string) => {
    if (action.includes('SCRAPE') || action.includes('WRESTLER')) {
      return { label: 'Roster', bg: 'bg-purple-500/10 text-purple-400 border-purple-500/20' };
    }
    if (action.includes('AUTH') || action.includes('LOGIN') || action.includes('PASSKEY') || action.includes('SESSION')) {
      return { label: 'Security', bg: 'bg-emerald-500/10 text-emerald-400 border-emerald-500/20' };
    }
    if (action.includes('PORTAINER') || action.includes('STACK') || action.includes('CONTAINER')) {
      return { label: 'Portainer', bg: 'bg-sky-500/10 text-sky-400 border-sky-500/20' };
    }
    if (action.includes('DELETE')) {
      return { label: 'Deletion', bg: 'bg-rose-500/10 text-rose-400 border-rose-500/20' };
    }
    return { label: 'System', bg: 'bg-blue-500/10 text-blue-400 border-blue-500/20' };
  };

  const getProjectBadge = (source?: string, sourceName?: string) => {
    const key = (source || 'foundation').toLowerCase();
    const label = sourceName || key.toUpperCase();

    switch (key) {
      case 'portainer':
        return { label: 'Portainer', bg: 'bg-sky-500/15 text-sky-300 border-sky-500/30' };
      case 'ledger':
        return { label: 'LEDGER', bg: 'bg-emerald-500/15 text-emerald-300 border-emerald-500/30' };
      case 'food':
        return { label: 'FOOD', bg: 'bg-amber-500/15 text-amber-300 border-amber-500/30' };
      case 'globot':
        return { label: 'GloBot', bg: 'bg-red-500/15 text-red-300 border-red-500/30' };
      case 'groupcord':
        return { label: 'GroupCord', bg: 'bg-indigo-500/15 text-indigo-300 border-indigo-500/30' };
      case 'lets-draw-down':
        return { label: 'LETS Draw-Down', bg: 'bg-yellow-500/15 text-yellow-300 border-yellow-500/30' };
      case 'voyarr':
        return { label: 'Voyarr', bg: 'bg-fuchsia-500/15 text-fuchsia-300 border-fuchsia-500/30' };
      case 'i-am':
        return { label: 'I AM', bg: 'bg-amber-400/15 text-amber-200 border-amber-400/30' };
      default:
        return { label: 'Foundation', bg: 'bg-cyan-500/15 text-cyan-300 border-cyan-500/30' };
    }
  };

  const filteredNotifications = notifications.filter(n => {
    if (projectFilter !== 'all') {
      const p = (n.sourceProject || n.guildId || 'foundation').toLowerCase();
      if (p !== projectFilter.toLowerCase()) return false;
    }
    if (notifFilter === 'all') return true;
    if (notifFilter === 'portainer') return n.sourceProject === 'portainer' || n.targetType.includes('portainer') || n.action.includes('PORTAINER');
    if (notifFilter === 'wrestler') return n.targetType === 'wrestlers' || n.action.includes('WRESTLER') || n.action.includes('SCRAPE');
    if (notifFilter === 'auth') return n.action.includes('AUTH') || n.action.includes('LOGIN') || n.action.includes('PASSKEY') || n.action.includes('SESSION');
    if (notifFilter === 'user') return n.targetType === 'user' || n.targetType === 'users' || n.action.includes('USER') || n.action.includes('PASSWORD') || n.action.includes('ROLE');
    if (notifFilter === 'system') return n.targetType === 'system_settings' || n.action.includes('SYSTEM') || n.action.includes('MAINTENANCE') || n.action.includes('FLEET');
    return true;
  });

  const navGroups = [
    {
      label: 'Platform & Services',
      items: [
        { label: 'Service Directory', path: '/apps', icon: LayoutGrid, desc: 'Fleet apps & dev servers' },
        { label: 'Notification Engine', path: '/notifications', icon: Bell, desc: 'Recipes, channels & dispatch logs' },
        { label: 'Tools & Utilities', path: '/tools', icon: Wrench, desc: 'Wrestler & theme managers' },
      ],
    },
    {
      label: 'Security & Compliance',
      items: [
        { label: 'User Directory', path: '/users', icon: User, desc: 'Accounts, passkeys & access' },
        { label: 'Security Hub', path: '/security', icon: ShieldCheck, desc: 'Passkeys, audit & posture', badge: 'Active' },
        { label: 'Deletion Queue', path: '/security/deletion-queue', icon: Trash2, desc: 'Secure data retention' },
        { label: 'Permissions & Roles', path: '/roles', icon: Lock, desc: 'Access control management' },
      ],
    },
    {
      label: 'System & Support',
      items: [
        { label: 'Platform Settings', path: '/platform-settings', icon: Server, desc: 'Maintenance & platform flags' },
        { label: 'Help Center', path: '/docs', icon: HelpCircle, desc: 'Guides & documentation' },
      ],
    },
  ];

  return (
    <nav className="fixed top-0 left-0 right-0 z-[100] px-6 py-4">
      <div className="max-w-7xl mx-auto">
        <div className={`transition-all duration-500 ${scrolled ? 'bg-slate-900/85 backdrop-blur-2xl shadow-2xl px-6 py-3 rounded-3xl' : 'bg-slate-900/50 backdrop-blur-md px-6 py-3 rounded-3xl'} border border-white/5 flex items-center justify-between`}>

          {/* Logo & Branding */}
          <div className="flex items-center space-x-3.5 group cursor-pointer" onClick={() => navigate ? navigate('/') : (window.location.href = '/')}>
            <div className="w-10 h-10 bg-slate-950 rounded-2xl flex items-center justify-center border border-white/10 group-hover:border-cyan-500/40 group-hover:shadow-[0_0_20px_rgba(6,182,212,0.25)] transition-all shadow-inner overflow-hidden shrink-0">
               <img src="/icons/foundation.png" className="w-6 h-6 object-contain" alt="Foundation" />
            </div>
            <Wordmark showVersion={true} size="md" />
          </div>

          {/* Right Controls & User Menu */}
          <div className="flex items-center space-x-3 sm:space-x-4">
            {user ? (
              <>
                {/* Notification Bell Trigger & Dropdown */}
                <div className="relative" ref={notifRef}>
              <button 
                type="button"
                onClick={(e) => {
                  e.stopPropagation();
                  setIsNotifOpen(prev => {
                    const next = !prev;
                    if (next) fetchNotifications();
                    return next;
                  });
                }}
                className={`p-2.5 text-slate-400 hover:text-white bg-slate-950/40 hover:bg-slate-900 border rounded-xl transition-all relative cursor-pointer ${
                  isNotifOpen ? 'border-blue-500/50 bg-slate-900 text-white shadow-lg shadow-blue-500/10' : 'border-white/5 hover:border-white/10'
                }`}
                title="System Notifications & Activity Logs"
              >
                <Bell className="w-4 h-4" />
                {unreadCount > 0 && (
                  <span className="absolute -top-1 -right-1 min-w-[18px] h-[18px] px-1 bg-blue-600 text-white rounded-full text-[10px] font-black flex items-center justify-center border-2 border-slate-900 shadow-md animate-pulse">
                    {unreadCount > 9 ? '9+' : unreadCount}
                  </span>
                )}
              </button>

              {/* Notification Popover Panel */}
              <AnimatePresence>
                {isNotifOpen && (
                  <motion.div
                    initial={{ opacity: 0, y: 12, scale: 0.96 }}
                    animate={{ opacity: 1, y: 0, scale: 1 }}
                    exit={{ opacity: 0, y: 10, scale: 0.96 }}
                    transition={{ duration: 0.18, ease: 'easeOut' }}
                    className="absolute top-full right-0 mt-3 w-80 sm:w-96 bg-slate-900/95 border border-white/10 rounded-3xl shadow-2xl overflow-hidden backdrop-blur-2xl z-50 flex flex-col max-h-[80vh]"
                  >
                    {/* Header */}
                    <div className="p-4 border-b border-white/5 flex items-center justify-between shrink-0 bg-slate-950/50">
                      <div className="flex items-center gap-2.5">
                        <div className="p-2 bg-blue-500/10 rounded-xl border border-blue-500/20 text-blue-400">
                          <Bell className="w-4 h-4" />
                        </div>
                        <div>
                          <h4 className="text-xs font-bold text-white flex items-center gap-2">
                            <span>Notifications & Activity</span>
                            {unreadCount > 0 && (
                              <span className="px-1.5 py-0.2 bg-blue-500/20 text-blue-400 text-[10px] font-mono rounded">
                                {unreadCount} new
                              </span>
                            )}
                          </h4>
                          <p className="text-[10px] text-slate-400">Real-time fleet activity feed</p>
                        </div>
                      </div>

                      <div className="flex items-center gap-1.5">
                        <button
                          type="button"
                          onClick={fetchNotifications}
                          disabled={isLoadingNotifs}
                          className="p-1.5 text-slate-400 hover:text-white rounded-lg hover:bg-white/5 transition-colors disabled:opacity-50"
                          title="Refresh Activity"
                        >
                          <RefreshCw className={`w-3.5 h-3.5 ${isLoadingNotifs ? 'animate-spin' : ''}`} />
                        </button>
                        {unreadCount > 0 && (
                          <button
                            type="button"
                            onClick={handleMarkAllRead}
                            className="p-1.5 text-slate-400 hover:text-emerald-400 rounded-lg hover:bg-emerald-500/10 transition-colors text-[11px] flex items-center gap-1 font-bold"
                            title="Mark all as read"
                          >
                            <Check className="w-3.5 h-3.5" />
                          </button>
                        )}
                      </div>
                    </div>

                    {/* Filter Tabs */}
                    <div className="flex px-3 pt-2.5 pb-2 border-b border-white/5 gap-1 bg-slate-950/20 shrink-0">
                      {(['all', 'wrestler', 'auth', 'system'] as const).map(tab => (
                        <button
                          key={tab}
                          type="button"
                          onClick={() => setNotifFilter(tab)}
                          className={`px-2.5 py-1 rounded-lg text-[10px] font-black uppercase tracking-wider transition-all ${
                            notifFilter === tab 
                              ? 'bg-blue-600 text-white shadow-sm' 
                              : 'text-slate-400 hover:text-slate-200 hover:bg-white/5'
                          }`}
                        >
                          {tab}
                        </button>
                      ))}
                    </div>

                    {/* Notification Feed List */}
                    <div className="overflow-y-auto divide-y divide-white/5 custom-scrollbar flex-1">
                      {isLoadingNotifs && notifications.length === 0 ? (
                        <div className="p-8 text-center text-slate-500 flex flex-col items-center gap-2 text-xs">
                          <RefreshCw className="w-4 h-4 animate-spin text-blue-400" />
                          <span>Loading notifications...</span>
                        </div>
                      ) : filteredNotifications.length === 0 ? (
                        <div className="p-8 text-center text-slate-500 text-xs">
                          <p className="font-bold text-slate-400">No activity logged</p>
                          <p className="text-[10px] text-slate-600 mt-1">Events will appear here in real time</p>
                        </div>
                      ) : (
                        filteredNotifications.map((notif) => {
                          const isUnread = lastReadTimestamp 
                            ? new Date(notif.createdAt).getTime() > new Date(lastReadTimestamp).getTime()
                            : true;
                          const badge = getActionBadge(notif.action);
                          const projBadge = getProjectBadge(notif.sourceProject, notif.sourceProjectName);

                          return (
                            <div
                              key={notif.id}
                              onClick={() => setSelectedNotif(selectedNotif?.id === notif.id ? null : notif)}
                              className={`p-3.5 hover:bg-white/5 transition-all cursor-pointer relative group ${
                                isUnread ? 'bg-blue-500/[0.03]' : ''
                              }`}
                            >
                              <div className="flex items-start gap-3">
                                {isUnread && (
                                  <span className="w-1.5 h-1.5 rounded-full bg-blue-500 mt-1.5 shrink-0 animate-pulse" />
                                )}

                                <div className="flex-1 min-w-0">
                                  <div className="flex items-center justify-between gap-2 mb-1.5">
                                    <div className="flex items-center gap-1.5 min-w-0">
                                      {/* Source Project Badge */}
                                      <span className={`px-1.5 py-0.5 rounded text-[9px] font-black uppercase tracking-wider border ${projBadge.bg}`}>
                                        {projBadge.label}
                                      </span>
                                      <span className={`px-1.5 py-0.5 rounded text-[9px] font-black uppercase tracking-wider border ${badge.bg}`}>
                                        {badge.label}
                                      </span>
                                      {notif.friendlyTarget && (
                                        <span className="text-[10px] text-slate-400 font-medium truncate hidden sm:inline">
                                          {notif.friendlyTarget}
                                        </span>
                                      )}
                                    </div>
                                    <span className="text-[10px] text-slate-500 font-mono flex items-center gap-1 shrink-0">
                                      <Clock className="w-2.5 h-2.5" />
                                      {new Date(notif.createdAt).toLocaleTimeString(undefined, { hour: '2-digit', minute: '2-digit' })}
                                    </span>
                                  </div>

                                  <p className="text-xs font-bold text-white truncate group-hover:text-blue-300 transition-colors">
                                    {notif.friendlyAction || notif.action.replace(/_/g, ' ')}
                                  </p>

                                  <div className="flex items-center justify-between text-[11px] text-slate-400 mt-1">
                                    <span className="truncate text-slate-400">
                                      By <strong className="text-slate-200 font-semibold">{notif.actorName}</strong>
                                    </span>
                                    {notif.location && (
                                      <span className="text-[9px] text-slate-500 font-mono truncate max-w-[90px]">
                                        {notif.location}
                                      </span>
                                    )}
                                  </div>

                                  {/* Expanded Inspection Detail */}
                                  {selectedNotif?.id === notif.id && (
                                    <div className="mt-2.5 pt-2.5 border-t border-white/5 bg-slate-950/80 p-2.5 rounded-xl text-[10px] font-mono space-y-1.5 animate-in fade-in duration-150">
                                      <div className="flex justify-between items-center">
                                        <span className="text-slate-500 uppercase tracking-wider text-[9px] font-black">Actor:</span>
                                        <span className="text-white font-bold">{notif.actorName}</span>
                                      </div>
                                      <div className="flex justify-between items-center">
                                        <span className="text-slate-500 uppercase tracking-wider text-[9px] font-black">Target:</span>
                                        <span className="text-slate-300 font-bold">{notif.friendlyTarget || notif.targetType}</span>
                                      </div>
                                      {notif.reason && (
                                        <div className="flex justify-between items-start gap-2">
                                          <span className="text-slate-500 uppercase tracking-wider text-[9px] font-black shrink-0">Reason:</span>
                                          <span className="text-blue-300 text-right font-sans text-[11px]">{notif.reason}</span>
                                        </div>
                                      )}
                                      {notif.recordId && (
                                        <div className="flex justify-between">
                                          <span className="text-slate-500 uppercase tracking-wider text-[9px] font-black">Record ID:</span>
                                          <span className="text-slate-300 truncate max-w-[180px]">{notif.recordId}</span>
                                        </div>
                                      )}
                                      {notif.ipAddress && (
                                        <div className="flex justify-between">
                                          <span className="text-slate-500 uppercase tracking-wider text-[9px] font-black">IP Origin:</span>
