              {/* History Table / Feed */}
              <div className="overflow-y-auto custom-scrollbar flex-1 py-2 divide-y divide-white/5 space-y-2">
                {(() => {
                  const filtered = filteredNotifications.filter(n => {
                    if (!historySearch.trim()) return true;
                    const query = historySearch.toLowerCase();
                    return (
                      n.actorName.toLowerCase().includes(query) ||
                      (n.actorUsername && n.actorUsername.toLowerCase().includes(query)) ||
                      (n.reason && n.reason.toLowerCase().includes(query)) ||
                      (n.friendlyAction && n.friendlyAction.toLowerCase().includes(query)) ||
                      (n.friendlyTarget && n.friendlyTarget.toLowerCase().includes(query)) ||
                      n.action.toLowerCase().includes(query) ||
                      n.targetType.toLowerCase().includes(query) ||
                      (n.recordId && n.recordId.toLowerCase().includes(query)) ||
                      (n.ipAddress && n.ipAddress.toLowerCase().includes(query))
                    );
                  });

                  if (filtered.length === 0) {
                    return (
                      <div className="p-12 text-center text-slate-500 flex flex-col items-center gap-2">
                        <Activity className="w-8 h-8 text-slate-600" />
                        <span className="text-sm font-bold text-slate-400">No matching events found</span>
                        <span className="text-xs text-slate-600">Try adjusting your filter or search query</span>
                      </div>
                    );
                  }

                  return filtered.map((notif) => {
                    const badge = getActionBadge(notif.action);
                    const projBadge = getProjectBadge(notif.sourceProject, notif.sourceProjectName);

                    return (
                      <div
                        key={notif.id}
                        className="p-4 rounded-2xl bg-slate-950/40 hover:bg-slate-950/80 border border-white/5 transition-all space-y-3"
                      >
                        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-2">
                          <div className="flex flex-wrap items-center gap-2">
                            {/* Source Project Badge */}
                            <span className={`px-2 py-0.5 rounded-md text-[10px] font-black uppercase tracking-wider border ${projBadge.bg}`}>
                              {projBadge.label}
                            </span>
                            <span className={`px-2 py-0.5 rounded-md text-[10px] font-black uppercase tracking-wider border ${badge.bg}`}>
                              {badge.label}
                            </span>
                            <span className="text-sm font-bold text-white">
                              {notif.friendlyAction || notif.action.replace(/_/g, ' ')}
                            </span>
                            {notif.friendlyTarget && (
                              <span className="px-2 py-0.5 bg-slate-800/80 border border-white/5 rounded text-[10px] text-slate-400 font-mono">
                                {notif.friendlyTarget}
                              </span>
                            )}
                          </div>

                          <span className="text-xs text-slate-400 font-mono flex items-center gap-1.5 shrink-0">
                            <Clock className="w-3.5 h-3.5 text-slate-500" />
                            {new Date(notif.createdAt).toLocaleDateString(undefined, { month: 'short', day: 'numeric', year: 'numeric' })} at {new Date(notif.createdAt).toLocaleTimeString(undefined, { hour: '2-digit', minute: '2-digit' })}
                          </span>
                        </div>

                        {/* Event Details Grid */}
                        <div className="grid grid-cols-1 md:grid-cols-3 gap-3 p-3 bg-slate-900/60 rounded-xl border border-white/5 text-xs">
                          <div>
                            <span className="text-[10px] font-black uppercase text-slate-500 block mb-0.5">Actor (Display Name)</span>
                            <div className="flex items-center gap-1.5">
                              <User className="w-3.5 h-3.5 text-blue-400 shrink-0" />
                              <strong className="text-white font-semibold">{notif.actorName}</strong>
                              {notif.actorUsername && (
                                <span className="text-slate-500 text-[11px]">(@{notif.actorUsername})</span>
                              )}
                            </div>
                          </div>

                          <div>
                            <span className="text-[10px] font-black uppercase text-slate-500 block mb-0.5">Target & Record</span>
                            <div className="font-mono text-[11px] text-slate-300 truncate">
                              {notif.targetType} {notif.recordId ? `(${notif.recordId})` : ''}
                            </div>
                          </div>

                          <div>
                            <span className="text-[10px] font-black uppercase text-slate-500 block mb-0.5">Reason & Trigger</span>
                            <div className="text-blue-300 font-medium truncate">
                              {notif.reason || 'Manual Administrative Action'}
                            </div>
                          </div>
                        </div>

                        {/* Location, Forensic IP & Owner Actions */}
                        <div className="flex flex-wrap items-center justify-between gap-3 text-[11px] text-slate-500 font-mono pt-1">
                          <div className="flex flex-wrap items-center gap-4">
                            {notif.location && (
                              <span>Location: <strong className="text-slate-400 font-medium">{notif.location}</strong></span>
                            )}
                            {notif.ipAddress && (
                              <span>IP Address: <strong className="text-slate-400 font-medium">{notif.ipAddress}</strong></span>
                            )}
                          </div>

                          {/* Owner-Only Delete Log Action */}
                          {isOwner && (
                            <button
                              type="button"
                              onClick={(e) => handleDeleteLog(notif.id, e)}
                              disabled={deletingLogId === notif.id}
                              className="px-2.5 py-1 rounded-lg bg-rose-500/10 hover:bg-rose-500/20 text-rose-400 border border-rose-500/20 text-[10px] font-sans font-bold flex items-center gap-1.5 transition-all cursor-pointer disabled:opacity-50"
                              title="Permanently Delete Log (Owner Only)"
                            >
                              <Trash2 className="w-3 h-3" />
                              <span>{deletingLogId === notif.id ? 'Deleting...' : 'Delete Entry'}</span>
                            </button>
                          )}
                        </div>
                      </div>
                    );
                  });
                })()}
              </div>

              {/* Modal Footer */}
              <div className="pt-4 border-t border-white/5 flex items-center justify-between shrink-0">
                <button
                  type="button"
                  onClick={handleMarkAllRead}
                  className="px-4 py-2 rounded-xl bg-slate-800 hover:bg-slate-700 text-xs font-bold text-slate-300 hover:text-white transition-colors cursor-pointer"
                >
                  Mark All As Read
                </button>
                <button
                  type="button"
                  onClick={() => setIsFullHistoryOpen(false)}
                  className="px-6 py-2 rounded-xl bg-blue-600 hover:bg-blue-500 text-xs font-bold text-white transition-all cursor-pointer shadow-lg shadow-blue-600/20"
                >
                  Close History
                </button>
              </div>
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </nav>
  );
}

