/** @jsxImportSource react */
import React, { useState, useRef, useEffect } from 'react';
import { ChevronDown, Plus, Check, Search, X } from 'lucide-react';

interface SearchablePresetSelectProps {
  value: string;
  onChange: (val: string) => void;
  presets: string[];
  placeholder?: string;
  label?: string;
}

export function SearchablePresetSelect({
  value,
  onChange,
  presets,
  placeholder = 'Select or type custom message...',
  label,
}: SearchablePresetSelectProps) {
  const [isOpen, setIsOpen] = useState(false);
  const [query, setQuery] = useState('');
  const [customInput, setCustomInput] = useState('');
  const dropdownRef = useRef<HTMLDivElement>(null);

  // Close on outside click
  useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(e.target as Node)) {
        setIsOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const filteredPresets = presets.filter((p) =>
    p.toLowerCase().includes(query.toLowerCase())
  );

  const handleSelect = (preset: string) => {
    onChange(preset);
    setIsOpen(false);
    setQuery('');
  };

  const handleAddCustom = () => {
    if (customInput.trim()) {
      onChange(customInput.trim());
      setCustomInput('');
      setIsOpen(false);
      setQuery('');
    }
  };

  return (
    <div className="relative space-y-2" ref={dropdownRef}>
      {label && (
        <label className="text-xs font-black uppercase tracking-widest text-slate-400">
          {label}
        </label>
      )}

      {/* Selected Item / Input Trigger */}
      <div
        onClick={() => setIsOpen(!isOpen)}
        className="w-full bg-slate-950/60 border border-slate-800 hover:border-slate-700 px-4 py-3 rounded-xl text-sm text-slate-200 cursor-pointer flex items-center justify-between gap-3 transition-colors"
      >
        <span className="truncate font-medium">
          {value || <span className="text-slate-500 italic">{placeholder}</span>}
        </span>
        <ChevronDown className={`w-4 h-4 text-slate-500 shrink-0 transition-transform ${isOpen ? 'rotate-180' : ''}`} />
      </div>

      {/* Dropdown Overlay */}
      {isOpen && (
        <div className="absolute left-0 right-0 top-full mt-2 z-[1000] bg-slate-900 border border-white/10 rounded-2xl shadow-2xl overflow-hidden max-h-80 flex flex-col animate-in fade-in zoom-in-95 duration-150">
          {/* Search Header */}
          <div className="p-3 border-b border-white/5 bg-slate-950/80 flex items-center gap-2">
            <Search className="w-4 h-4 text-slate-500 shrink-0" />
            <input
              type="text"
              placeholder="Search pre-configured messages..."
