import React, { createContext, useContext, useState, useCallback } from 'react';

type ToastType = 'info' | 'success' | 'warning' | 'error';

interface Toast {
  id: string;
  title?: string;
  type: ToastType;
  message: string | React.ReactNode;
  persistent?: boolean;
  onIconClick?: () => void;
}

export interface ToastObject {
  title?: string;
  message?: string | React.ReactNode;
  type?: ToastType;
  persistent?: boolean;
  onIconClick?: () => void;
}

interface ToastContextType {
  addToast: (
    contentOrMessage: string | React.ReactNode | ToastObject,
    type?: ToastType,
    options?: { id?: string; persistent?: boolean; onIconClick?: () => void }
  ) => string;
  removeToast: (id: string) => void;
  toasts: Toast[];
}

const ToastContext = createContext<ToastContextType | undefined>(undefined);

export const ToastProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [toasts, setToasts] = useState<Toast[]>([]);

  const addToast = useCallback((
    contentOrMessage: string | React.ReactNode | ToastObject,
    typeParam?: ToastType,
    options?: { id?: string; persistent?: boolean; onIconClick?: () => void }
  ) => {
    let message: string | React.ReactNode;
    let toastTitle: string | undefined;
    let type: ToastType = typeParam || 'info';
    let persistent = options?.persistent ?? false;
    let onIconClick = options?.onIconClick;

    if (
      contentOrMessage !== null &&
      typeof contentOrMessage === 'object' &&
      !React.isValidElement(contentOrMessage) &&
      ('message' in (contentOrMessage as any) || 'title' in (contentOrMessage as any))
    ) {
      const obj = contentOrMessage as ToastObject;
      toastTitle = obj.title;
      message = obj.message || '';
      if (obj.type) type = obj.type;
      if (obj.persistent !== undefined) persistent = obj.persistent;
      if (obj.onIconClick) onIconClick = obj.onIconClick;
    } else {
      message = contentOrMessage as string | React.ReactNode;
    }

    const id = options?.id || Math.random().toString(36).substring(2, 9);

    setToasts((prev) => {
      const existing = prev.find((t) => t.id === id);
      const newToast: Toast = { id, title: toastTitle, message, type, persistent, onIconClick };
      if (existing) {
        return prev.map((t) => t.id === id ? newToast : t);
      } else {
        return [...prev, newToast];
      }
    });

    if (!persistent) {
      // Auto-remove after 5 seconds
      setTimeout(() => {
        setToasts((prev) => prev.filter((t) => t.id !== id));
      }, 5000);
    }

    return id;
  }, []);

  const removeToast = useCallback((id: string) => {
    setToasts((prev) => prev.filter((t) => t.id !== id));
  }, []);

  return (
    <ToastContext.Provider value={{ addToast, removeToast, toasts }}>
      {children}
    </ToastContext.Provider>
  );
};

export const useToast = () => {
  const context = useContext(ToastContext);
  if (!context) {
    throw new Error('useToast must be used within a ToastProvider');
  }
  return context;
};

