      setNewTagInput('');
    }
  };

  const handleRemoveTag = (tagToRemove: string) => {
    setTags(tags.filter(t => t !== tagToRemove));
  };

  const handleCreateNote = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if (!newContent.trim()) return;

    setSubmitting(true);
    try {
      const res = await fetch('/api/admin/directory-notes', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          targetType,
          targetId,
          targetName,
          content: newContent.trim(),
          privacyLevel: newPrivacy,
          tags,
        }),
      });

      const json = await res.json() as { success: boolean; note?: any; error?: string };
      if (json.success && json.note) {
        setNotes(prev => [json.note, ...prev]);
        setNewContent('');
        setTags([]);
        setNewTagInput('');
        onNotesCountChange?.(targetId, notes.length + 1);
        addToast({ title: 'Note Saved', message: `Note added with ${newPrivacy} privacy.`, type: 'success' });
      } else {
        addToast({ title: 'Failed to Save', message: json.error || 'Unable to save note.', type: 'error' });
      }
    } catch (err: any) {
      addToast({ title: 'Error', message: err.message, type: 'error' });
    } finally {
      setSubmitting(false);
    }
  };

  const handleStartEdit = (note: DirectoryNote) => {
    setEditingNoteId(note.id);
    setEditContent(note.content);
    setEditPrivacy(note.privacyLevel);
  };

  const handleSaveEdit = async (noteId: string) => {
    if (!editContent.trim()) return;
    setSavingEdit(true);
    try {
      const res = await fetch(`/api/admin/directory-notes/${noteId}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          content: editContent.trim(),
          privacyLevel: editPrivacy,
        }),
      });

      const json = await res.json() as { success: boolean; error?: string };
      if (json.success) {
        setNotes(prev => prev.map(n => n.id === noteId ? {
          ...n,
          content: editContent.trim(),
          privacyLevel: editPrivacy,
          updatedAt: new Date().toISOString(),
        } : n));
        setEditingNoteId(null);
        addToast({ title: 'Note Updated', message: 'Changes saved successfully.', type: 'success' });
      } else {
        addToast({ title: 'Update Failed', message: json.error, type: 'error' });
      }
    } catch (err: any) {
      addToast({ title: 'Error', message: err.message, type: 'error' });
    } finally {
      setSavingEdit(false);
    }
  };

  const handleDeleteNote = async (noteId: string) => {
    setDeletingId(noteId);
    try {
      const res = await fetch(`/api/admin/directory-notes/${noteId}`, {
        method: 'DELETE',
      });
      const json = await res.json() as { success: boolean; error?: string };
      if (json.success) {
        setNotes(prev => {
          const next = prev.filter(n => n.id !== noteId);
          onNotesCountChange?.(targetId, next.length);
          return next;
        });
        addToast({ title: 'Note Deleted', message: 'Note has been permanently removed.', type: 'info' });
      } else {
        addToast({ title: 'Delete Failed', message: json.error, type: 'error' });
      }
    } catch (err: any) {
      addToast({ title: 'Error', message: err.message, type: 'error' });
    } finally {
      setDeletingId(null);
    }
  };

  const formatTimestamp = (isoString: string) => {
    if (!isoString) return '';
    try {
      const d = new Date(isoString);
      const diffMs = Date.now() - d.getTime();
      const diffMins = Math.floor(diffMs / 60000);
      if (diffMins < 1) return 'Just now';
      if (diffMins < 60) return `${diffMins}m ago`;
      const diffHours = Math.floor(diffMins / 60);
      if (diffHours < 24) return `${diffHours}h ago`;
      const diffDays = Math.floor(diffHours / 24);
      if (diffDays < 7) return `${diffDays}d ago`;
      return d.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
    } catch {
      return isoString;
    }
  };

  const getPrivacyBadge = (level: PrivacyLevel) => {
    switch (level) {
      case 'private':
        return {
          label: 'Private',
          icon: Lock,
          className: 'bg-rose-500/10 text-rose-400 border-rose-500/30',
          desc: 'Only visible to you'
        };
      case 'internal':
        return {
          label: 'Internal',
          icon: Users,
          className: 'bg-amber-500/10 text-amber-400 border-amber-500/30',
          desc: 'Visible to authenticated team members & admins'
        };
      case 'public':
        return {
          label: 'Public',
          icon: Globe,
          className: 'bg-emerald-500/10 text-emerald-400 border-emerald-500/30',
          desc: 'Visible to all directory visitors'
        };
    }
  };

  const filteredNotes = notes.filter(n => {
    if (filterPrivacy === 'all') return true;
    return n.privacyLevel === filterPrivacy;
  });

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 sm:p-6 md:p-8">
      {/* Backdrop */}
      <div 
        className="fixed inset-0 bg-slate-950/80 backdrop-blur-md transition-opacity" 
        onClick={onClose} 
      />

      {/* Modal Card */}
      <motion.div
        initial={{ opacity: 0, scale: 0.95, y: 15 }}
        animate={{ opacity: 1, scale: 1, y: 0 }}
        exit={{ opacity: 0, scale: 0.95, y: 15 }}
        className="relative w-full max-w-3xl max-h-[90vh] bg-slate-950 border border-slate-800 rounded-[2.5rem] shadow-2xl flex flex-col overflow-hidden z-10"
      >
        {/* Header */}
        <div className="p-6 md:p-8 border-b border-slate-800/80 bg-slate-900/40 shrink-0">
          <div className="flex items-start justify-between gap-4">
            <div className="flex items-center space-x-4">
              <div className="w-14 h-14 rounded-2xl bg-slate-900 border border-slate-800 flex items-center justify-center overflow-hidden shadow-inner shrink-0">
                {targetIcon ? (
                  <img src={targetIcon} alt={targetName} className="w-full h-full object-cover p-1 rounded-xl" />
                ) : (
                  <span className="text-2xl">{targetSymbol || '🚀'}</span>
                )}
              </div>

              <div>
                <div className="flex items-center gap-2 flex-wrap">
                  <h2 className="text-xl md:text-2xl font-black text-white tracking-tight">
                    {targetName}
                  </h2>
                  <span className="px-2.5 py-0.5 rounded-full text-[10px] font-black uppercase tracking-wider bg-blue-500/10 text-blue-400 border border-blue-500/20">
                    {targetType === 'app' ? 'PWA Project' : targetType === 'stack' ? 'Docker Stack' : 'Container'}
                  </span>
                  <span className="px-2 py-0.5 rounded-md text-[10px] font-mono font-bold bg-slate-900 text-slate-400 border border-white/5">
                    {notes.length} note{notes.length === 1 ? '' : 's'}
                  </span>
                </div>
                <p className="text-xs text-slate-400 font-medium mt-1">
                  Operational notes, maintenance logs, and configuration memos with granular privacy controls.
                </p>
              </div>
            </div>

            <button
              onClick={onClose}
              className="p-2.5 text-slate-400 hover:text-white bg-slate-900 hover:bg-slate-800 border border-slate-800 rounded-2xl transition-all cursor-pointer"
              title="Close (Esc)"
            >
              <X className="w-5 h-5" />
            </button>
          </div>
        </div>

        {/* Scrollable Content */}
        <div className="flex-1 overflow-y-auto p-6 md:p-8 space-y-6">
          {/* Create Note Section */}
          <div className="p-5 rounded-3xl bg-slate-900/40 border border-white/5 space-y-4">
            <div className="flex items-center justify-between">
              <span className="text-xs font-black uppercase tracking-widest text-slate-300 flex items-center gap-2">
                <StickyNote className="w-4 h-4 text-cyan-400" />
                <span>Add Note</span>
              </span>

              {/* Privacy Selector Pills */}
              <div className="flex items-center gap-1.5 p-1 bg-slate-950/80 rounded-xl border border-white/5">
                {(['private', 'internal', 'public'] as PrivacyLevel[]).map(level => {
                  const badge = getPrivacyBadge(level);
                  const Icon = badge.icon;
                  const isSelected = newPrivacy === level;
                  return (
                    <button
                      key={level}
                      type="button"
                      onClick={() => setNewPrivacy(level)}
                      className={`flex items-center gap-1 px-2.5 py-1 rounded-lg text-[10px] font-black uppercase tracking-wider transition-all cursor-pointer ${
                        isSelected 
                          ? badge.className + ' font-bold shadow-sm' 
                          : 'text-slate-500 hover:text-slate-300'
                      }`}
                      title={badge.desc}
                    >
                      <Icon className="w-3 h-3" />
                      <span>{badge.label}</span>
                    </button>
                  );
                })}
              </div>
            </div>

            {/* Note Textarea */}
            <div className="relative">
              <textarea
                value={newContent}
                onChange={(e) => setNewContent(e.target.value)}
                onKeyDown={(e) => {
                  if ((e.metaKey || e.ctrlKey) && e.key === 'Enter') {
                    handleCreateNote();
                  }
                }}
                placeholder={`Write a ${newPrivacy} note for ${targetName}... (Press Cmd+Enter to save)`}
                rows={3}
                className="w-full p-4 rounded-2xl bg-slate-950 border border-slate-800 text-xs text-white placeholder-slate-600 focus:outline-none focus:border-cyan-500/50 transition-colors resize-y leading-relaxed font-sans"
              />
            </div>

            {/* Tag bar & Submit button */}
            <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3 pt-1">
              <div className="flex items-center gap-2 flex-wrap">
                <div className="flex items-center gap-1.5 px-3 py-1 bg-slate-950 rounded-xl border border-white/5 text-xs text-slate-400">
                  <Tag className="w-3 h-3 text-slate-500" />
                  <input
                    type="text"
                    value={newTagInput}
                    onChange={(e) => setNewTagInput(e.target.value)}
                    onKeyDown={(e) => {
                      if (e.key === 'Enter') {
                        e.preventDefault();
                        handleAddTag();
                      }
                    }}
                    placeholder="Add tag (Enter)..."
                    className="bg-transparent text-xs text-white placeholder-slate-600 focus:outline-none w-24 sm:w-28"
                  />
                  {newTagInput && (
                    <button type="button" onClick={handleAddTag} className="text-cyan-400 hover:text-cyan-300 text-[10px] font-bold cursor-pointer">
                      Add
                    </button>
                  )}
                </div>

                {tags.map(t => (
                  <span key={t} className="inline-flex items-center gap-1 px-2 py-0.5 rounded-lg bg-cyan-500/10 text-cyan-400 border border-cyan-500/20 text-[10px] font-mono">
                    #{t}
                    <button type="button" onClick={() => handleRemoveTag(t)} className="hover:text-rose-400 ml-0.5 cursor-pointer">
                      ×
                    </button>
                  </span>
                ))}
              </div>

              <div className="flex items-center gap-2 self-end sm:self-auto">
                <button
                  type="button"
                  onClick={() => handleCreateNote()}
                  disabled={!newContent.trim() || submitting}
                  className="flex items-center gap-2 px-5 py-2 rounded-xl bg-cyan-500 hover:bg-cyan-400 text-slate-950 text-xs font-black uppercase tracking-wider transition-all disabled:opacity-50 cursor-pointer shadow-lg shadow-cyan-500/20"
                >
                  {submitting ? <RefreshCw className="w-3.5 h-3.5 animate-spin" /> : <Plus className="w-3.5 h-3.5" />}
                  <span>Save Note</span>
                </button>
              </div>
            </div>
          </div>

          {/* Filter Bar */}
          {notes.length > 0 && (
            <div className="flex items-center justify-between pt-2 border-t border-slate-900/60">
              <span className="text-xs font-black text-slate-400 uppercase tracking-widest">
                Activity Feed ({filteredNotes.length})
              </span>

              <div className="flex items-center gap-1">
                {(['all', 'private', 'internal', 'public'] as const).map(tab => (
                  <button
                    key={tab}
                    type="button"
                    onClick={() => setFilterPrivacy(tab)}
                    className={`px-2.5 py-1 rounded-lg text-[10px] font-black uppercase tracking-wider transition-all cursor-pointer ${
                      filterPrivacy === tab 
                        ? 'bg-slate-800 text-white font-bold' 
                        : 'text-slate-500 hover:text-slate-300'
                    }`}
                  >
                    {tab === 'all' ? 'All' : tab}
                  </button>
                ))}
              </div>
            </div>
          )}

          {/* Notes List */}
          {loading ? (
            <div className="py-12 text-center text-slate-500 space-y-2">
              <RefreshCw className="w-6 h-6 animate-spin mx-auto text-cyan-400" />
              <p className="text-xs font-bold uppercase tracking-wider">Loading notes...</p>
            </div>
          ) : filteredNotes.length === 0 ? (
            <div className="py-12 text-center text-slate-500 space-y-2 bg-slate-900/20 rounded-3xl border border-white/5">
              <StickyNote className="w-8 h-8 mx-auto text-slate-600 opacity-50" />
              <p className="text-xs font-bold text-slate-400">No notes found</p>
              <p className="text-[11px] text-slate-600">
                {filterPrivacy !== 'all' ? `No ${filterPrivacy} notes exist yet.` : 'Add the first note above to document deployment steps or reminders.'}
              </p>
            </div>
          ) : (
            <div className="space-y-4">
              {filteredNotes.map(note => {
                const badge = getPrivacyBadge(note.privacyLevel);
                const BadgeIcon = badge.icon;
                const isEditing = editingNoteId === note.id;

                return (
                  <div
                    key={note.id}
                    className="p-5 rounded-3xl bg-slate-900/40 border border-white/5 hover:border-slate-800 transition-all space-y-3 group"
                  >
                    {/* Note Card Header */}
                    <div className="flex items-start justify-between gap-3">
                      <div className="flex items-center gap-3">
                        <div className="w-8 h-8 rounded-xl bg-slate-800 border border-white/10 flex items-center justify-center overflow-hidden shrink-0">
                          {note.authorAvatar ? (
                            <img src={note.authorAvatar} alt={note.authorName} className="w-full h-full object-cover" />
                          ) : (
                            <span className="text-xs font-black text-slate-400">
                              {note.authorName.charAt(0).toUpperCase()}
                            </span>
                          )}
                        </div>

                        <div>
                          <div className="flex items-center gap-2">
                            <span className="text-xs font-bold text-white">
                              {note.authorName}
                            </span>
                            <span className={`inline-flex items-center gap-1 px-2 py-0.5 rounded-md text-[9px] font-black uppercase tracking-wider border ${badge.className}`}>
                              <BadgeIcon className="w-2.5 h-2.5" />
                              <span>{badge.label}</span>
                            </span>
                          </div>

                          <span className="text-[10px] text-slate-500 flex items-center gap-1 mt-0.5 font-mono">
                            <Clock className="w-3 h-3" />
                            <span>{formatTimestamp(note.createdAt)}</span>
                            {note.updatedAt && note.updatedAt !== note.createdAt && (
                              <span className="text-slate-600">(edited)</span>
                            )}
                          </span>
                        </div>
                      </div>

                      {/* Action buttons (Edit/Delete) */}
                      {note.canEdit && !isEditing && (
                        <div className="flex items-center gap-1 opacity-80 group-hover:opacity-100 transition-opacity">
                          <button
                            type="button"
                            onClick={() => handleStartEdit(note)}
                            className="p-1.5 rounded-lg bg-slate-800/80 hover:bg-slate-700 text-slate-400 hover:text-white transition-colors cursor-pointer"
                            title="Edit Note"
                          >
                            <Edit3 className="w-3.5 h-3.5" />
                          </button>
                          <button
                            type="button"
                            onClick={() => handleDeleteNote(note.id)}
                            disabled={deletingId === note.id}
                            className="p-1.5 rounded-lg bg-slate-800/80 hover:bg-rose-500/20 text-slate-400 hover:text-rose-400 transition-colors cursor-pointer disabled:opacity-50"
                            title="Delete Note"
                          >
                            {deletingId === note.id ? (
                              <RefreshCw className="w-3.5 h-3.5 animate-spin" />
                            ) : (
                              <Trash2 className="w-3.5 h-3.5" />
                            )}
                          </button>
                        </div>
                      )}
                    </div>

                    {/* Content / Edit Form */}
                    {isEditing ? (
                      <div className="space-y-3 pt-2">
                        <textarea
                          value={editContent}
                          onChange={(e) => setEditContent(e.target.value)}
                          rows={3}
                          className="w-full p-3 rounded-xl bg-slate-950 border border-slate-700 text-xs text-white placeholder-slate-600 focus:outline-none focus:border-cyan-500"
                        />

                        <div className="flex items-center justify-between gap-2 flex-wrap">
                          <div className="flex items-center gap-1 p-1 bg-slate-950 rounded-lg border border-white/5">
                            {(['private', 'internal', 'public'] as PrivacyLevel[]).map(lvl => (
                              <button
                                key={lvl}
                                type="button"
                                onClick={() => setEditPrivacy(lvl)}
                                className={`px-2 py-0.5 rounded text-[9px] font-black uppercase tracking-wider cursor-pointer ${
                                  editPrivacy === lvl 
                                    ? getPrivacyBadge(lvl).className + ' font-bold' 
                                    : 'text-slate-500 hover:text-slate-300'
                                }`}
                              >
                                {lvl}
                              </button>
                            ))}
                          </div>

                          <div className="flex items-center gap-2">
                            <button
                              type="button"
                              onClick={() => setEditingNoteId(null)}
                              className="px-3 py-1.5 rounded-lg bg-slate-800 text-slate-300 hover:text-white text-xs font-bold transition-all cursor-pointer"
                            >
                              Cancel
                            </button>
                            <button
                              type="button"
                              onClick={() => handleSaveEdit(note.id)}
                              disabled={savingEdit || !editContent.trim()}
                              className="flex items-center gap-1.5 px-4 py-1.5 rounded-lg bg-cyan-500 hover:bg-cyan-400 text-slate-950 text-xs font-black uppercase tracking-wider transition-all disabled:opacity-50 cursor-pointer"
                            >
                              {savingEdit ? <RefreshCw className="w-3 h-3 animate-spin" /> : <Save className="w-3 h-3" />}
                              <span>Save</span>
                            </button>
                          </div>
                        </div>
                      </div>
                    ) : (
                      <div className="space-y-2">
                        <p className="text-xs text-slate-300 whitespace-pre-wrap leading-relaxed font-sans">
                          {note.content}
                        </p>

                        {note.tags && note.tags.length > 0 && (
                          <div className="flex items-center gap-1.5 flex-wrap pt-1">
                            {note.tags.map(t => (
                              <span key={t} className="px-2 py-0.5 rounded-md bg-white/5 text-slate-400 text-[9px] font-mono">
                                #{t}
                              </span>
                            ))}
                          </div>
                        )}
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          )}
        </div>

        {/* Footer */}
        <div className="p-4 sm:p-6 border-t border-slate-800/80 bg-slate-900/60 flex items-center justify-between gap-3 shrink-0">
          <div className="flex items-center space-x-2 text-xs text-slate-500">
            <Shield className="w-4 h-4 text-cyan-400" />
            <span>Private notes are isolated to your user account.</span>
          </div>
          <button
            onClick={onClose}
            className="px-6 py-2 bg-slate-800 hover:bg-slate-700 text-white text-xs font-bold rounded-xl transition-all cursor-pointer"
          >
            Close
          </button>
        </div>
      </motion.div>
    </div>
  );
}

/** @jsxImportSource react */
import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { 
  X, 
  Server, 
  Cpu, 
  Terminal, 
  Copy, 
  Check, 
  ShieldCheck, 
  Key,
  HardDrive
} from 'lucide-react';
import { useBodyScrollLock } from '../../../hooks/useBodyScrollLock';

interface AgentEnrollmentModalProps {
  isOpen: boolean;
  onClose: () => void;
}

export function AgentEnrollmentModal({ isOpen, onClose }: AgentEnrollmentModalProps) {
  useBodyScrollLock(isOpen);
  const [nodeName, setNodeName] = useState('');
  const [brand, setBrand] = useState('synology');
  const [installMethod, setInstallMethod] = useState<'compose' | 'oneliner' | 'docker_run'>('compose');
  const [loading, setLoading] = useState(false);
  const [enrolledData, setEnrolledData] = useState<any>(null);
  const [copied, setCopied] = useState(false);

  if (!isOpen) return null;

  const handleEnroll = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!nodeName.trim()) return;

    setLoading(true);
    try {
      const res = await fetch('/api/admin/agents/enroll', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
body: JSON.stringify({
          name: nodeName.trim().toLowerCase(),
          brand
        })
      });

      const json = await res.json() as { success: boolean; error?: string };
      if (json.success) {
        setEnrolledData(json);
      }
    } catch (err) {
      console.error('Enrollment error:', err);
    } finally {
      setLoading(false);
    }
  };

  const getInstructions = () => {
    if (!enrolledData) return '';

    const opRef = enrolledData.opReference || `op://57s77wi4sbpj5zxxm7habzczo4/Foundation-Agent Stack - ${enrolledData.agentName.toUpperCase()}/Authentication & Security/FOUNDATION_AGENT_TOKEN`;

    if (installMethod === 'compose') {
      return `# 1. Save as docker-compose.yml on your ${brand.toUpperCase()} node:
version: '3.8'

services:
  foundation-agent:
    image: ghcr.io/gameproductions/foundation-agent:latest
    container_name: foundation-agent
    restart: unless-stopped
    security_opt:
      - no-new-privileges:true
    volumes:
      - /var/run/docker.sock:/var/run/docker.sock:ro
    environment:
      - FOUNDATION_URL=https://foundation.gpnet.dev
      - HARDWARE_BRAND=${brand}
      - AGENT_NAME=${enrolledData.agentName}
      - REPORT_INTERVAL_MS=15000
      - FOUNDATION_AGENT_TOKEN=${opRef}

# 2. Launch securely via 1Password CLI:
op run --account gameproductions -- docker compose up -d`;
    }

    if (installMethod === 'oneliner') {
      return enrolledData.oneLiner;
    }

    return `docker run -d \\
  --name foundation-agent \\
  --restart unless-stopped \\
  -v /var/run/docker.sock:/var/run/docker.sock:ro \\
  -e FOUNDATION_URL="https://foundation.gpnet.dev" \\
  -e HARDWARE_BRAND="${brand}" \\
  -e AGENT_NAME="${enrolledData.agentName}" \\
  -e FOUNDATION_AGENT_TOKEN="${enrolledData.token}" \\
  ghcr.io/gameproductions/foundation-agent:latest`;
  };

  const handleCopy = () => {
    navigator.clipboard.writeText(getInstructions());
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/80 backdrop-blur-md">
      <motion.div
        initial={{ opacity: 0, scale: 0.96 }}
        animate={{ opacity: 1, scale: 1 }}
        exit={{ opacity: 0, scale: 0.96 }}
        className="bg-slate-900 border border-slate-800 rounded-[2.5rem] w-full max-w-2xl max-h-[90vh] flex flex-col shadow-2xl overflow-hidden"
      >
        {/* Header */}
        <div className="p-6 border-b border-slate-800 flex items-center justify-between bg-slate-950/40">
          <div className="flex items-center space-x-3">
            <div className="p-2.5 rounded-2xl bg-cyan-500/10 text-cyan-400 border border-cyan-500/20">
              <Server className="w-6 h-6" />
            </div>
            <div>
              <h3 className="text-xl font-black text-white tracking-tight">
                Enroll Hardware Node Sidecar
              </h3>
