/** @jsxImportSource react */



import React, { useState } from 'react';

/**
 * Foundation Data Center 
 * Standardization of bulk data operations (Import/Export).
 * Implements D1 batching logic to prevent worker timeouts.
 */
export const DataCenter = ({ tables, onImport, onExport }: { tables: any[], onImport: (tableName: string, offset: number, limit: number) => Promise<void> | void, onExport: (tableName: string) => void }) => {
  const [progress, setProgress] = useState(0);
  const [status, setStatus] = useState('idle');

  const handleImport = async (file: File, tableName: string) => {
    setStatus('importing');
    setProgress(0);

    // Mock: Batch processing logic (chunked upload)
    const chunkSize = 100;
    const totalLines = 1000; // Simulated
    for (let i = 0; i < totalLines; i += chunkSize) {
      await onImport(tableName, i, chunkSize); // Execution in D1 Batch
      setProgress(Math.round(((i + chunkSize) / totalLines) * 100));
    }

    setStatus('complete');
  };

  return (
    <div className="gp-data-center">
      <h2>Data Center</h2>
      <p className="description">Manage high-performance imports and encrypted backups.</p>

      <div className="table-list scrollable-list">
        {tables.map((table) => (
          <div key={table.name} className="data-control-card">
            <div className="table-info">
              <h3>{table.name}</h3>
              <p>{table.description}</p>
            </div>
            <div className="actions">
              <input
                type="file"
                accept=".json,.csv"
                onChange={(e) => {
                  if (e.target.files && e.target.files.length > 0) {
                    handleImport(e.target.files[0], table.name);
                  }
                }}
              />
              <button 
                className="btn-export" 
                onClick={() => onExport(table.name)}
              >
                Export Secure Snapshot (.json)
              </button>
            </div>
          </div>
        ))}
      </div>

      {status !== 'idle' && (
        <div className="progress-container">
          <div className="progress-bar" style={{ width: `${progress}%` }}></div>
          <span>{status === 'complete' ? '✨ Operation Complete' : `Processing: ${progress}%`}</span>
        </div>
      )}
    </div>
  );
};

/**
 * 🏢 Google Workspace Administration Hub
 * Central Command Matrix interface for Google Workspace Users, Groups,
 * Group Settings, Aliases, Domains, and Scope Profiles.
 */

import React, { useState, useEffect, useMemo } from 'react';
import {
  Users,
  Building2,
  Globe,
  Settings2,
  Mail,
  Shield,
  ShieldCheck,
  ShieldAlert,
  Plus,
  Trash2,
  Edit,
  RotateCw,
  Search,
  Filter,
  CheckCircle2,
  AlertCircle,
  Clock,
  ExternalLink,
  ChevronRight,
  UserPlus,
  Key,
  Copy,
  Check,
  Inbox,
  Radio,
  Sliders,
  Layers,
  Sparkles,
  Lock,
  Eye,
  AtSign,
  UserCheck,
  UserX,
  RefreshCw,
  FolderTree,
  Send,
  Zap,
  Info
} from 'lucide-react';
import { toast } from 'sonner';

interface Domain {
  domainName: string;
  verified: boolean;
  isPrimary: boolean;
}

interface GroupSettings {
  whoCanPostMessage?: string;
  whoCanViewGroup?: string;
  whoCanViewMembership?: string;
  whoCanJoin?: string;
  allowExternalMembers?: boolean;
  whoCanModerateMembers?: string;
  whoCanModerateContent?: string;
  isArchived?: boolean;
  includeInGlobalAddressList?: boolean;
  collaborativeInbox?: boolean;
  spamModerationLevel?: string;
}

interface Group {
  id: string;
  email: string;
  name: string;
  description?: string;
  aliases?: string[];
  directMembersCount?: number;
  settings?: GroupSettings;
  scopeProfileId?: string;
}

interface Member {
  id: string;
  email: string;
  role: 'MEMBER' | 'MANAGER' | 'OWNER';
  type: string;
}

interface User {
  id: string;
  primaryEmail: string;
  name: {
    givenName: string;
    familyName: string;
    fullName: string;
  };
  isAdmin: boolean;
  suspended: boolean;
  orgUnitPath: string;
  aliases?: string[];
  lastLoginTime?: string;
  isEnrolledIn2Sv?: boolean;
}

interface ScopeProfile {
  id: string;
  name: string;
  description?: string;
  targetDomain?: string;
  defaultSettingsJson: string;
  filterCriteriaJson: string;
  isDefault?: boolean;
}

interface DiagnosticStatus {
  success: boolean;
  adminEmail: string;
  serviceAccount: string;
  domainsCount: number;
  groupsCount: number;
  latencyMs: number;
  scopesAuthorized: string[];
  error?: string;
}

export function GoogleWorkspaceManager() {
  const [activeTab, setActiveTab] = useState<'groups' | 'users' | 'scopes' | 'domains' | 'diagnostics'>('groups');

  // Data States
  const [status, setStatus] = useState<DiagnosticStatus | null>(null);
  const [domains, setDomains] = useState<Domain[]>([]);
  const [groups, setGroups] = useState<Group[]>([]);
  const [users, setUsers] = useState<User[]>([]);
  const [scopes, setScopes] = useState<ScopeProfile[]>([]);
  const [auditLogs, setAuditLogs] = useState<any[]>([]);

  // Loading & Filter States
  const [loading, setLoading] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedDomain, setSelectedDomain] = useState('all');
  const [selectedScopeFilter, setSelectedScopeFilter] = useState('all');
  const [externalFilter, setExternalFilter] = useState<'all' | 'allowed' | 'denied'>('all');
  const [memberOnlyFilter, setMemberOnlyFilter] = useState(false);

  // Modals & Drawers
  const [selectedGroup, setSelectedGroup] = useState<Group | null>(null);
  const [groupDrawerOpen, setGroupDrawerOpen] = useState(false);
  const [drawerTab, setDrawerTab] = useState<'settings' | 'aliases' | 'members'>('settings');
  const [groupMembers, setGroupMembers] = useState<Member[]>([]);
  const [loadingMembers, setLoadingMembers] = useState(false);

  const [createGroupModalOpen, setCreateGroupModalOpen] = useState(false);
  const [createUserModalOpen, setCreateUserModalOpen] = useState(false);
  const [createScopeModalOpen, setCreateScopeModalOpen] = useState(false);

  // Form States for New Group
  const [newGroupName, setNewGroupName] = useState('');
  const [newGroupUsername, setNewGroupUsername] = useState('');
  const [newGroupDomain, setNewGroupDomain] = useState('');
  const [newGroupDesc, setNewGroupDesc] = useState('');
  const [newGroupScope, setNewGroupScope] = useState('fleet_core');
  const [newGroupCustomSettings, setNewGroupCustomSettings] = useState<Partial<GroupSettings>>({});

  // Inline alias addition state
  const [newAliasInput, setNewAliasInput] = useState('');
  // Inline member addition state
  const [newMemberEmail, setNewMemberEmail] = useState('');
  const [newMemberRole, setNewMemberRole] = useState<'MEMBER' | 'MANAGER' | 'OWNER'>('MEMBER');

  // Load Initial Status & Domains
  const fetchStatusAndDomains = async () => {
    try {
      const [statusRes, domainRes, scopesRes] = await Promise.all([
        fetch('/api/admin/workspace/status'),
        fetch('/api/admin/workspace/domains'),
        fetch('/api/admin/workspace/scope-profiles')
      ]);

      if (statusRes.ok) {
        const s = await statusRes.json() as any;
        setStatus(s);
      }
      if (domainRes.ok) {
        const d = await domainRes.json() as { domains?: any[] };
        setDomains(d.domains || []);
        if (d.domains?.length && !newGroupDomain) {
          const primary = d.domains.find((dom: Domain) => dom.isPrimary) || d.domains[0];
          setNewGroupDomain(primary.domainName);
        }
      }
      if (scopesRes.ok) {
        const sc = await scopesRes.json() as { profiles?: any[] };
        setScopes(sc.profiles || []);
      }
    } catch (err: any) {
      console.warn('Initial fetch error:', err.message);
    }
  };

  const fetchGroups = async () => {
    setLoading(true);
    try {
      const params = new URLSearchParams({ includeSettings: 'true' });
      if (selectedDomain !== 'all') params.append('domain', selectedDomain);
      if (selectedScopeFilter !== 'all') params.append('scopeProfileId', selectedScopeFilter);
      if (searchQuery) params.append('query', searchQuery);
      if (memberOnlyFilter) params.append('memberOnly', 'true');

      const res = await fetch(`/api/admin/workspace/groups?${params.toString()}`);
      if (res.ok) {
        const data = await res.json() as { groups?: any[] };
        setGroups(data.groups || []);
      } else {
        toast.error('Failed to load Google Groups');
      }
    } catch (err: any) {
      toast.error(`Groups Error: ${err.message}`);
    } finally {
      setLoading(false);
    }
  };

  const fetchUsers = async () => {
    setLoading(true);
    try {
      const params = new URLSearchParams();
      if (selectedDomain !== 'all') params.append('domain', selectedDomain);
      if (searchQuery) params.append('query', searchQuery);

      const res = await fetch(`/api/admin/workspace/users?${params.toString()}`);
      if (res.ok) {
        const data = await res.json() as { users?: any[] };
        setUsers(data.users || []);
      } else {
        toast.error('Failed to load Google Workspace Users');
      }
    } catch (err: any) {
      toast.error(`Users Error: ${err.message}`);
    } finally {
      setLoading(false);
    }
  };

  const fetchAuditLogs = async () => {
    try {
      const res = await fetch('/api/admin/workspace/audit-logs');
      if (res.ok) {
        const data = await res.json() as { logs?: any[] };
        setAuditLogs(data.logs || []);
      }
    } catch {
      // Non-blocking
    }
  };

  useEffect(() => {
    fetchStatusAndDomains();
  }, []);

  useEffect(() => {
    if (activeTab === 'groups') fetchGroups();
    else if (activeTab === 'users') fetchUsers();
    else if (activeTab === 'diagnostics') fetchAuditLogs();
  }, [activeTab, selectedDomain, selectedScopeFilter, memberOnlyFilter]);

  // Load details & members for selected group in drawer
  const openGroupDrawer = async (group: Group) => {
    setSelectedGroup(group);
    setGroupDrawerOpen(true);
    setLoadingMembers(true);
    try {
      const [detailsRes, membersRes] = await Promise.all([
        fetch(`/api/admin/workspace/groups/${encodeURIComponent(group.email)}`),
        fetch(`/api/admin/workspace/groups/${encodeURIComponent(group.email)}/members`)
      ]);

      if (detailsRes.ok) {
        const d = await detailsRes.json() as { group?: any };
        setSelectedGroup(d.group);
      }
      if (membersRes.ok) {
        const m = await membersRes.json() as { members?: any[] };
        setGroupMembers(m.members || []);
      }
    } catch (err: any) {
      toast.error(`Failed to load group details: ${err.message}`);
    } finally {
      setLoadingMembers(false);
    }
  };

  // Group Settings Save Handler
  const handleSaveGroupSettings = async (settings: Partial<GroupSettings>) => {
    if (!selectedGroup) return;
    try {
      const res = await fetch(`/api/admin/workspace/groups/${encodeURIComponent(selectedGroup.email)}/settings`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(settings)
      });
      if (res.ok) {
        toast.success('Group settings updated successfully');
        setSelectedGroup(p => p ? { ...p, settings: { ...p.settings, ...settings } } : null);
        fetchGroups();
      } else {
        const err = await res.json() as { error?: string };
        toast.error(err.error || 'Failed to update settings');
      }
    } catch (err: any) {
      toast.error(`Error: ${err.message}`);
    }
  };

  // Create Group Handler
  const handleCreateGroup = async () => {
    if (!newGroupName || !newGroupUsername || !newGroupDomain) {
      toast.error('Please enter group name and email address');
      return;
    }
    const email = `${newGroupUsername.trim().toLowerCase()}@${newGroupDomain}`;
    try {
      const res = await fetch('/api/admin/workspace/groups', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          name: newGroupName.trim(),
          email,
          description: newGroupDesc.trim(),
          scopeProfileId: newGroupScope,
          customSettings: newGroupCustomSettings
        })
      });

      if (res.ok) {
        toast.success(`Google Group ${email} created successfully!`);
        setCreateGroupModalOpen(false);
        setNewGroupName('');
        setNewGroupUsername('');
        setNewGroupDesc('');
        fetchGroups();
      } else {
        const err = await res.json() as { error?: string };
        toast.error(err.error || 'Failed to create group');
      }
    } catch (err: any) {
      toast.error(`Creation Error: ${err.message}`);
    }
  };

  // Delete Group Handler
  const handleDeleteGroup = async (groupKey: string) => {
    if (!confirm(`Are you sure you want to permanently delete the Google Group "${groupKey}"?`)) return;
    try {
      const res = await fetch(`/api/admin/workspace/groups/${encodeURIComponent(groupKey)}`, {
        method: 'DELETE'
      });
      if (res.ok) {
        toast.success(`Group ${groupKey} deleted`);
        if (selectedGroup?.email === groupKey) setGroupDrawerOpen(false);
        fetchGroups();
      } else {
        const err = await res.json() as { error?: string };
        toast.error(err.error || 'Failed to delete group');
      }
    } catch (err: any) {
      toast.error(`Error: ${err.message}`);
    }
  };

  // Alias Actions
  const handleAddAlias = async () => {
    if (!selectedGroup || !newAliasInput) return;
    try {
      const res = await fetch(`/api/admin/workspace/groups/${encodeURIComponent(selectedGroup.email)}/aliases`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ alias: newAliasInput.trim() })
      });
      if (res.ok) {
        toast.success(`Alias ${newAliasInput} added`);
        setSelectedGroup(p => p ? { ...p, aliases: [...(p.aliases || []), newAliasInput.trim()] } : null);
        setNewAliasInput('');
        fetchGroups();
      } else {
        const err = await res.json() as { error?: string };
        toast.error(err.error || 'Failed to add alias');
      }
    } catch (err: any) {
      toast.error(`Error: ${err.message}`);
    }
  };

  const handleRemoveAlias = async (alias: string) => {
    if (!selectedGroup) return;
    try {
      const res = await fetch(`/api/admin/workspace/groups/${encodeURIComponent(selectedGroup.email)}/aliases/${encodeURIComponent(alias)}`, {
        method: 'DELETE'
      });
      if (res.ok) {
        toast.success(`Alias ${alias} removed`);
        setSelectedGroup(p => p ? { ...p, aliases: (p.aliases || []).filter(a => a !== alias) } : null);
        fetchGroups();
      } else {
        const err = await res.json() as { error?: string };
        toast.error(err.error || 'Failed to remove alias');
      }
    } catch (err: any) {
      toast.error(`Error: ${err.message}`);
    }
  };

  // Member Actions
  const handleAddMember = async () => {
    if (!selectedGroup || !newMemberEmail) return;
    try {
      const res = await fetch(`/api/admin/workspace/groups/${encodeURIComponent(selectedGroup.email)}/members`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email: newMemberEmail.trim(), role: newMemberRole })
      });
      if (res.ok) {
        const data = await res.json() as { member?: any };
        toast.success(`Added ${newMemberEmail} to group`);
        setGroupMembers(p => [...p, data.member]);
        setNewMemberEmail('');
      } else {
        const err = await res.json() as { error?: string };
        toast.error(err.error || 'Failed to add member');
      }
    } catch (err: any) {
      toast.error(`Error: ${err.message}`);
    }
  };

  const handleRemoveMember = async (memberKey: string) => {
    if (!selectedGroup) return;
    try {
      const res = await fetch(`/api/admin/workspace/groups/${encodeURIComponent(selectedGroup.email)}/members/${encodeURIComponent(memberKey)}`, {
        method: 'DELETE'
      });
      if (res.ok) {
        toast.success(`Removed ${memberKey}`);
        setGroupMembers(p => p.filter(m => m.email !== memberKey && m.id !== memberKey));
      } else {
        const err = await res.json() as { error?: string };
        toast.error(err.error || 'Failed to remove member');
      }
    } catch (err: any) {
      toast.error(`Error: ${err.message}`);
    }
  };

  // Filtered Groups list
  const filteredGroups = useMemo(() => {
    return groups.filter(g => {
      if (externalFilter === 'allowed' && !g.settings?.allowExternalMembers) return false;
      if (externalFilter === 'denied' && g.settings?.allowExternalMembers) return false;
      if (searchQuery) {
        const q = searchQuery.toLowerCase();
        const matchesName = g.name?.toLowerCase().includes(q);
        const matchesEmail = g.email?.toLowerCase().includes(q);
        const matchesAlias = g.aliases?.some(a => a.toLowerCase().includes(q));
        if (!matchesName && !matchesEmail && !matchesAlias) return false;
      }
      return true;
    });
  }, [groups, externalFilter, searchQuery]);

  return (
    <div className="space-y-6">
      {/* Top Banner & Telemetry Bar */}
      <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-4 bg-slate-900/60 p-5 rounded-2xl border border-sky-500/20 backdrop-blur-xl shadow-2xl relative overflow-hidden">
        <div className="absolute -right-20 -top-20 w-64 h-64 bg-sky-500/10 rounded-full blur-3xl pointer-events-none" />

        <div className="flex items-center gap-3.5 z-10">
          <div className="p-3 bg-gradient-to-br from-sky-500/20 to-indigo-500/20 rounded-xl border border-sky-500/30 text-sky-400">
            <Building2 className="w-6 h-6" />
          </div>
          <div>
            <div className="flex items-center gap-2">
              <h2 className="text-xl font-black text-white tracking-tight">Google Workspace Admin</h2>
              <span className="px-2 py-0.5 text-[10px] font-extrabold uppercase tracking-wider bg-sky-500/20 text-sky-300 border border-sky-500/30 rounded-md">
                Admin SDK v1
              </span>
            </div>
            <p className="text-xs text-slate-400 font-medium mt-0.5">
              Centralized central management of Users, Groups, Group Settings, Aliases, Domains, and Scopes.
            </p>
          </div>
        </div>

        {/* Live Diagnostics Quick Badge */}
        <div className="flex items-center gap-3 z-10">
