}

interface NasFullTelemetry {
  id: string;
  name: string;
  vendor: string;
  host: string;
  port: number;
  useHttps: boolean;
  status: string;
  remoteTunnelUrl?: string;
  tailscaleIp?: string;
  telemetry: {
    model: string;
    serialNumber: string;
    version: string;
    uptime: number;
    temperature: number;
    temperatureWarn: boolean;
    cpu: {
      model: string;
      cores: number;
      clockSpeed: number;
      usagePct: number;
    };
    ram: {
      totalBytes: number;
      usedBytes: number;
      usagePct: number;
    };
    network: Array<{
      interface: string;
      ip: string;
      speed: number;
      status: string;
    }>;
  };
  storage: {
    pools: Array<{
      id: string;
      name: string;
      raidType: string;
      status: string;
      totalCapacityBytes: number;
      usedCapacityBytes: number;
      freeCapacityBytes: number;
      usagePct: number;
    }>;
    disks: Array<{
      id: string;
      name: string;
      vendor: string;
      model: string;
      type: string;
      capacityBytes: number;
      temperature: number;
      smartStatus: string;
      slot: number;
    }>;
  };
  shares: Array<{
    name: string;
    path: string;
    description: string;
    isEncrypted: boolean;
    usedBytes?: number;
  }>;
}

export const NasManager = () => {
  const [devices, setDevices] = useState<NasDevice[]>([]);
  const [selectedDevice, setSelectedDevice] = useState<NasDevice | null>(null);
  const [telemetry, setTelemetry] = useState<NasFullTelemetry | null>(null);
  const [loading, setLoading] = useState(true);
  const [loadingTelemetry, setLoadingTelemetry] = useState(false);
  const [scanning, setScanning] = useState(false);
  const [scanProgress, setScanProgress] = useState({ percent: 0, currentIp: '', stage: '' });
  const [activeTab, setActiveTab] = useState<'overview' | 'storage' | 'shares' | 'remote' | 'settings'>('overview');

  // Add Device Modal
  const [showAddModal, setShowAddModal] = useState(false);
  const [newDeviceName, setNewDeviceName] = useState('');
  const [newDeviceHost, setNewDeviceHost] = useState('');
  const [newDevicePort, setNewDevicePort] = useState(5001);
  const [newDeviceVendor, setNewDeviceVendor] = useState('synology_dsm');
  const [newDeviceTunnel, setNewDeviceTunnel] = useState('');
  const [newDeviceTailscale, setNewDeviceTailscale] = useState('');

  const toast = useToast();

  useEffect(() => {
    fetchDevices();
  }, []);

  useEffect(() => {
    if (selectedDevice) {
      fetchDeviceTelemetry(selectedDevice.id);
    }
  }, [selectedDevice]);

  const fetchDevices = async () => {
    setLoading(true);
    try {
      const res = await fetch('/api/admin/nas/devices');
      const json = await res.json() as any;
      if (json.success && json.data) {
        setDevices(json.data);
        if (json.data.length > 0 && !selectedDevice) {
          setSelectedDevice(json.data[0]);
        }
      }
    } catch {
      toast.error('Failed to load NAS devices');
    } finally {
      setLoading(false);
    }
  };

  const fetchDeviceTelemetry = async (deviceId: string) => {
    setLoadingTelemetry(true);
    try {
      const res = await fetch(`/api/admin/nas/devices/${deviceId}/telemetry`);
      const json = await res.json() as any;
      if (json.success && json.data) {
        setTelemetry(json.data);
      }
    } catch {
      toast.error('Failed to load NAS live telemetry');
    } finally {
      setLoadingTelemetry(false);
    }
  };

  const handleScanSubnet = async () => {
    setScanning(true);
    setScanProgress({ percent: 10, currentIp: '10.0.0.1 (Gateway)', stage: 'Probing Subnet for NAS & DSM Endpoints' });

    const keyIps = ['10.0.0.1 (Gateway)', '10.0.0.33 (NAS-T)', '10.0.0.34 (PER-V)', '10.0.0.35', '10.0.0.40'];
    let idx = 0;
    const interval = setInterval(() => {
      idx++;
      if (idx < keyIps.length) {
        setScanProgress({
          percent: Math.min(90, idx * 22),
          currentIp: keyIps[idx],
          stage: `Probing WebAPI ports (5001, 5000, 8080, 80) on ${keyIps[idx]}`
        });
      }
    }, 400);

    try {
      const res = await fetch('/api/admin/nas/devices/scan', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ baseSubnet: '10.0.0' })
      });
      clearInterval(interval);
      const json = await res.json() as any;
      if (json.success && json.data) {
        setScanProgress({ percent: 100, currentIp: 'Complete', stage: `Scan complete: Discovered ${json.data.length} storage nodes` });
        toast.success(`Discovered ${json.data.length} candidate NAS devices`);
        fetchDevices();
        setTimeout(() => setScanning(false), 2500);
      } else {
        setScanning(false);
      }
    } catch {
      clearInterval(interval);
      toast.error('Subnet NAS discovery failed');
      setScanning(false);
    }
  };

  const handleCreateDevice = async () => {
    if (!newDeviceName || !newDeviceHost) return;
    try {
      const res = await fetch('/api/admin/nas/devices', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          name: newDeviceName,
          host: newDeviceHost,
          port: newDevicePort,
          vendor: newDeviceVendor,
          remoteTunnelUrl: newDeviceTunnel || null,
          tailscaleIp: newDeviceTailscale || null,
          useHttps: newDevicePort === 5001 || newDevicePort === 443
        })
      });
      const json = await res.json() as any;
      if (json.success) {
        toast.success('NAS device enrolled successfully');
        setShowAddModal(false);
        setNewDeviceName('');
        setNewDeviceHost('');
        fetchDevices();
      }
    } catch {
      toast.error('Failed to enroll NAS device');
    }
  };

  const handleReboot = async (deviceId: string) => {
    if (!confirm('Are you sure you want to reboot this NAS node?')) return;
    try {
      const res = await fetch(`/api/admin/nas/devices/${deviceId}/reboot`, { method: 'POST' });
      const json = await res.json() as any;
      if (json.success) {
        toast.success(json.data?.message || 'Reboot command dispatched');
      }
    } catch {
      toast.error('Failed to trigger NAS reboot');
    }
  };

  const getVendorIcon = (vendor: string) => {
    if (vendor === 'synology_dsm') return <SynologyBrandSvg className="w-6 h-6" />;
    if (vendor === 'truenas_scale') return <TrueNasBrandSvg className="w-6 h-6" />;
    if (vendor === 'qnap_qts') return <QnapBrandSvg className="w-6 h-6" />;
    return <HardDrive className="w-6 h-6 text-blue-400" />;
  };

  const formatBytes = (bytes: number | string | undefined) => {
    if (!bytes) return '0 B';
    const num = typeof bytes === 'string' ? parseFloat(bytes) : bytes;
    const units = ['B', 'KB', 'MB', 'GB', 'TB', 'PB'];
    let val = num;
    let u = 0;
    while (val >= 1024 && u < units.length - 1) {
      val /= 1024;
      u++;
    }
    return `${val.toFixed(1)} ${units[u]}`;
  };

  return (
    <div className="space-y-8">
      {/* Top Banner & Control Bar */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 p-6 bg-slate-900/60 border border-white/10 rounded-3xl backdrop-blur-xl">
        <div className="flex items-center gap-3.5">
          <div className="p-3 bg-gradient-to-br from-blue-600 to-indigo-600 rounded-2xl text-white shadow-lg shadow-blue-500/20">
            <HardDrive className="w-6 h-6" />
          </div>
          <div>
            <h2 className="text-xl font-black text-white">Universal NAS Fleet Manager</h2>
            <p className="text-xs text-slate-400 font-medium">Official DSM WebAPI Hardware Diagnostics, Storage Pool Health, SMART Maps & Zero-Trust Tunnels</p>
