  const fetchData = async () => {
    setLoading(true);
    try {
      const [projRes, rolesRes, assignRes] = await Promise.all([
        fetch('/admin/projects'),
        fetch('/admin/roles'),
        fetch('/admin/project-roles'),
      ]);

      const projData = await projRes.json() as any;
      const rolesData = await rolesRes.json() as any;
      const assignData = await assignRes.json() as any;

      if (projData.success) setProjects(projData.projects || []);
      if (rolesData.success) setRoles(rolesData.roles || []);
      if (assignData.success) setAssignments(assignData.projectRoles || []);
