      const res = await fetch('/admin/project-roles', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          userId: editingAssignment.userId,
          projectId: editingAssignment.projectId,
          roleId: editingAssignment.roleId,
          customDisplayName: editingAssignment.customDisplayName || '',
          customRoleTitle: editingAssignment.customRoleTitle || '',
          permissions: parsedPerms,
          foundationAccess: editingAssignment.foundationAccess === 'true' ? 'true' : 'false',
        }),
      });

      const data = await res.json() as any;
      if (data.success) {
        toast.success('Project role and permissions updated!');
        setEditingAssignment(null);
        fetchData();
      } else {
        toast.error(data.error || 'Failed to save project role.');
