  };

  const handleScanNetwork = async () => {
    setScanning(true);
    setScanProgress({ percent: 5, currentIp: '10.0.0.1 (Gateway)', stage: 'Probing Subnet Gateway & Infrastructure Nodes', foundCount: 0 });

    const keyIps = ['10.0.0.1 (Gateway)', '10.0.0.33 (NAS-T)', '10.0.0.34 (PER-V)', '10.0.0.35 (Auxiliary)', '10.0.0.10', '10.0.0.25', '10.0.0.50'];
    let currentIdx = 0;

    const interval = setInterval(() => {
      currentIdx++;
      if (currentIdx < keyIps.length) {
        const pct = Math.min(92, Math.round((currentIdx / keyIps.length) * 90) + 10);
        setScanProgress(prev => ({
          ...prev,
          percent: pct,
          currentIp: keyIps[currentIdx],
          stage: `Probing candidate ports (5001, 81, 9443, 80, 443) on ${keyIps[currentIdx]}`
        }));
      }
    }, 450);

    try {
      const res = await fetch('/api/admin/reverse-proxy/devices/scan', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ baseSubnet: '10.0.0' })
