const PRESET_MAINTENANCE_REASONS = [
  'Scheduled routine system optimization and database indexing.',
  'Emergency security patch and edge firewall updates.',
  'Upgrading core authentication services and database clusters.',
  'Platform migration and zero-downtime microservice sync.',
  'Scheduled hardware maintenance on central compute nodes.',
  'API infrastructure performance tuning and cache warming.'
];

const PRESET_BANNER_MESSAGES = [
  '⚠️ Scheduled Maintenance in progress. Services will resume shortly.',
  '🔒 Fleet-wide security upgrade underway. Read-only mode is temporarily active.',
  '⚡ High-performance database cluster optimization in progress. Minimal disruption expected.',
  '🛠️ System maintenance in progress. All data is safe and queueing for resumption.',
  '🛰️ Central node synchronization underway. Access will restore momentarily.'
];

export const SecurityMonitor = () => {
  const [blocks, setBlocks] = useState<Block[]>([]);
  const [config, setConfig] = useState<SecurityConfig | null>(null);
  const [loading, setLoading] = useState(true);
  const [filter, setFilter] = useState('');
  const [activeTab, setActiveTab] = useState<'blocks' | 'policies' | 'rules' | 'status'>('blocks');
  const [maintenance, setMaintenance] = useState(false);
  const [maintenanceDetails, setMaintenanceDetails] = useState<any>(null);
  const [bannerMessage, setBannerMessage] = useState(PRESET_BANNER_MESSAGES[0]);
  const [maintenanceReason, setMaintenanceReason] = useState(PRESET_MAINTENANCE_REASONS[0]);
  const [estimatedEndTime, setEstimatedEndTime] = useState('');
  const [editingTier, setEditingTier] = useState<{ tier: string; botName?: string; limit: number; window: number } | null>(null);
  const [updating, setUpdating] = useState(false);
  const [toggling, setToggling] = useState(false);
  const [requiresPasskey, setRequiresPasskey] = useState(false);
  const [blockHistory, setBlockHistory] = useState<Block[]>([]);
  const [blockIpInput, setBlockIpInput] = useState('');
  const [blockDuration, setBlockDuration] = useState(3600);
  const [blocking, setBlocking] = useState(false);
  const [clearing, setClearing] = useState(false);
  const [editingBlockTtl, setEditingBlockTtl] = useState<number | null>(null);

  useEffect(() => {
    document.title = 'Security Hub | Foundation';
    fetchData();
    const interval = setInterval(fetchData, 30000);
    return () => clearInterval(interval);
  }, []);

  const fetchData = async () => {
    try {
      const [resBlocks, resHistory, resConfig, resMaintenance] = await Promise.all([
        fetch('/admin/security/blocks'),
        fetch('/admin/security/blocks/history'),
        fetch('/admin/security/config'),
        fetch('/admin/maintenance')
      ]);

      if (resBlocks.status === 403 || resConfig.status === 403 || resMaintenance.status === 403) {
        const failedRes = resBlocks.status === 403 ? resBlocks : (resConfig.status === 403 ? resConfig : resMaintenance);
        const data = await failedRes.json().catch(() => null) as any;
        if (data && data.requireWebAuthn) {
          setRequiresPasskey(true);
        } else {
          console.warn('[Fleet Security] Security check returned 403 Forbidden.');
        }
        return;
      }

      if (!resBlocks.ok || !resConfig.ok || !resMaintenance.ok) {
        throw new Error('One or more security requests failed');
      }

      const dataBlocks = await resBlocks.json() as { success: boolean; blocks: Block[] };
      const dataHistory = resHistory.ok ? await resHistory.json() as { success: boolean; history: Block[] } : null;
      const dataConfig = await resConfig.json() as { success: boolean; config: SecurityConfig };
      const dataMaintenance = await resMaintenance.json() as { enabled: boolean; details?: any };

      if (dataBlocks.success) setBlocks(dataBlocks.blocks);
      if (dataHistory?.success) setBlockHistory(dataHistory.history);
      if (dataConfig.success) setConfig(dataConfig.config);
      setMaintenance(dataMaintenance.enabled);
      if (dataMaintenance.details) {
        setMaintenanceDetails(dataMaintenance.details);
        if (dataMaintenance.details.bannerMessage) setBannerMessage(dataMaintenance.details.bannerMessage);
        if (dataMaintenance.details.reason) setMaintenanceReason(dataMaintenance.details.reason);
        if (dataMaintenance.details.estimatedEndTime) setEstimatedEndTime(dataMaintenance.details.estimatedEndTime);
      }
    } catch (err) {
      console.error('[Fleet Security] Data fetch failed:', err);
    } finally {
      setLoading(false);
    }
  };

  const handleUnblock = async (ip: string) => {
    try {
      const res = await fetch('/admin/security/unblock', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ ip })
      });
      if (res.status === 403) {
        const data = await res.json() as any;
        if (data.requireWebAuthn) {
          setRequiresPasskey(true);
          return;
        }
      }
      if (res.ok) {
        setBlocks(prev => prev.filter(b => b.ip !== ip));
      }
    } catch (err) {
      console.error('[Fleet Security] Unblock failed:', err);
    }
  };

  const handleBlockIp = async () => {
    const ip = blockIpInput.trim();
    if (!ip) return;
    setBlocking(true);
    try {
      const res = await fetch('/admin/security/block', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ ip, durationSeconds: blockDuration, reason: 'MANUAL_ADMIN_RESTRICTION' })
      });
      if (res.status === 403) {
        const data = await res.json() as any;
        if (data.requireWebAuthn) {
          setRequiresPasskey(true);
          return;
        }
      }
      if (res.ok) {
        setBlockIpInput('');
        fetchData();
      }
    } catch (err) {
      console.error('[Fleet Security] Manual block failed:', err);
    } finally {
      setBlocking(false);
    }
  };

  const handleClearHistory = async () => {
    setClearing(true);
    try {
      const res = await fetch('/admin/security/blocks/history', { method: 'DELETE' });
      if (res.status === 403) {
        const data = await res.json() as any;
        if (data.requireWebAuthn) {
          setRequiresPasskey(true);
          return;
        }
      }
      if (res.ok) {
        setBlockHistory([]);
      }
    } catch (err) {
      console.error('[Fleet Security] Clear history failed:', err);
    } finally {
      setClearing(false);
    }
  };

  const handleUpdateConfig = async () => {
    if (!editingTier) return;
    setUpdating(true);
    try {
      const res = await fetch('/admin/security/config', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(editingTier)
      });
      if (res.status === 403) {
        const data = await res.json() as any;
        if (data.requireWebAuthn) {
          setRequiresPasskey(true);
          return;
        }
      }
      if (res.ok) {
        await fetchData();
        setEditingTier(null);
      }
    } catch (err) {
      console.error('[Fleet Security] Config update failed:', err);
    } finally {
      setUpdating(false);
    }
  };

  const handleBlockTtlSave = async () => {
    if (editingBlockTtl === null || editingBlockTtl < 60) return;
    setUpdating(true);
    try {
      const res = await fetch('/admin/security/config', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ blockTtl: editingBlockTtl })
      });
      if (res.status === 403) {
        const data = await res.json() as any;
        if (data.requireWebAuthn) {
          setRequiresPasskey(true);
          return;
        }
      }
      if (res.ok) {
        await fetchData();
        setEditingBlockTtl(null);
      }
    } catch (err) {
      console.error('[Fleet Security] Block TTL update failed:', err);
    } finally {
      setUpdating(false);
    }
  };

  const filteredBlocks = blocks.filter(b => {
    const q = filter.trim().toLowerCase();
    if (!q) return true;
    return (
      b.ip.toLowerCase().includes(q) ||
      b.bot?.toLowerCase().includes(q) ||
      (b as any).referenceCode?.toLowerCase().includes(q) ||
      b.linkedEntity?.entityName?.toLowerCase().includes(q)
    );
  });

  return (
