          <div className="flex items-center space-x-3">
            <div className="p-2 bg-blue-500/10 rounded-lg border border-blue-500/20">
              <ShieldAlert className="w-5 h-5 text-blue-500" />
            </div>
            <span className="text-[10px] font-black uppercase tracking-[0.3em] text-blue-500">Fleet Security Defense</span>
          </div>
          <h1 className="text-4xl sm:text-5xl font-black text-white uppercase tracking-tight">
            Security Hub
          </h1>
          <p className="text-slate-500 text-sm max-w-xl">
            Active system defense and site access management. Monitoring all incoming traffic for stability and safety.
          </p>
        </header>

        <div className="flex items-center gap-4 mb-10 overflow-x-auto pb-4 scrollbar-hide">
          <button 
            onClick={() => setActiveTab('blocks')}
            className={`px-8 py-4 rounded-2xl text-xs font-black uppercase tracking-widest transition-all flex items-center gap-3 border ${activeTab === 'blocks' ? 'bg-blue-600 text-white border-blue-500 shadow-xl shadow-blue-500/20' : 'bg-slate-900/50 text-slate-500 border-slate-900 hover:text-white'}`}
          >
            <ShieldAlert className="w-4 h-4" />
            Active Blocks ({blocks.length})
          </button>
          <button 
            onClick={() => setActiveTab('policies')}
            className={`px-8 py-4 rounded-2xl text-xs font-black uppercase tracking-widest transition-all flex items-center gap-3 border ${activeTab === 'policies' ? 'bg-blue-600 text-white border-blue-500 shadow-xl shadow-blue-500/20' : 'bg-slate-900/50 text-slate-500 border-slate-900 hover:text-white'}`}
          >
            <Sliders className="w-4 h-4" />
            Security & Complexity Policies
          </button>
          <button 
            onClick={() => setActiveTab('rules')}
            className={`px-8 py-4 rounded-2xl text-xs font-black uppercase tracking-widest transition-all flex items-center gap-3 border ${activeTab === 'rules' ? 'bg-blue-600 text-white border-blue-500 shadow-xl shadow-blue-500/20' : 'bg-slate-900/50 text-slate-500 border-slate-900 hover:text-white'}`}
          >
            <Settings className="w-4 h-4" />
            Rate Limit Rules
          </button>
          <button 
            onClick={() => setActiveTab('status')}
            className={`px-8 py-4 rounded-2xl text-xs font-black uppercase tracking-widest transition-all flex items-center gap-3 border ${activeTab === 'status' ? 'bg-blue-600 text-white border-blue-500 shadow-xl shadow-blue-500/20' : 'bg-slate-900/50 text-slate-500 border-slate-900 hover:text-white'}`}
          >
            <Activity className="w-4 h-4" />
            Maintenance Mode
          </button>
        </div>

        <div className="space-y-8">
          {activeTab === 'policies' ? (
            <SecurityRequirementsManager />
