                    className="flex items-center gap-2 bg-blue-600 text-white px-6 py-3 rounded-2xl text-xs font-black uppercase tracking-widest disabled:opacity-50 transition-opacity cursor-pointer shadow-lg shadow-blue-600/20"
                  >
                    <Plus className="w-4 h-4" />
                    {blocking ? 'Blocking...' : 'Block IP'}
                  </button>
                </div>
              </div>

              <div className="bg-slate-900/30 border border-white/5 rounded-[2.5rem] overflow-hidden">
                <div className="p-8 border-b border-white/5 flex items-center justify-between">
                  <h3 className="text-xl font-black text-white uppercase tracking-tight flex items-center gap-3">
                    <ShieldAlert className="w-5 h-5 text-rose-500" />
                    Active Access Restrictions
                  </h3>
                  <div className="relative">
                    <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-600" />
                    <input 
                      type="text" 
                      placeholder="Search IP, reference code, or user..." 
                      value={filter}
                      onChange={(e) => setFilter(e.target.value)}
                      className="bg-slate-950/50 border border-slate-900 pl-12 pr-6 py-3 rounded-2xl w-80 text-sm text-white"
                    />
                  </div>
                </div>
                <table className="w-full text-left">
                  <thead>
                    <tr className="bg-slate-900/50 text-[10px] font-black uppercase tracking-widest text-slate-500">
                      <th className="px-8 py-5">Reference / IP</th>
                      <th className="px-8 py-5">Linked Entity</th>
                      <th className="px-8 py-5">Enforcement Reason</th>
                      <th className="px-8 py-5">Bot / Scope</th>
                      <th className="px-8 py-5">Expires</th>
                      <th className="px-8 py-5 text-right">Actions</th>
                    </tr>
                  </thead>
                  <tbody>
                    <AnimatePresence>
                      {filteredBlocks.length === 0 ? (
                        <tr><td colSpan={6} className="px-8 py-12 text-center text-slate-600 text-sm font-medium">No active restrictions</td></tr>
                      ) : filteredBlocks.map((block) => (
                        <motion.tr key={block.ip} className="hover:bg-white/5">
                          <td className="px-8 py-6">
                            <div className="flex flex-col gap-1">
                              {(block as any).referenceCode && (
                                <span className="font-mono text-xs font-black text-cyan-400 bg-cyan-950/50 px-2 py-0.5 rounded-lg border border-cyan-800/50 w-fit">
                                  {(block as any).referenceCode}
                                </span>
                              )}
                              <code className="text-slate-300 font-bold text-xs">{block.ip}</code>
                            </div>
                          </td>

                          {/* Linked Entity Resolution */}
                          <td className="px-8 py-6">
                            {block.linkedEntity ? (
