                                <div className="w-7 h-7 rounded-full bg-blue-500/10 border border-blue-500/20 flex items-center justify-center text-xs font-bold text-blue-400 overflow-hidden shrink-0">
                                  {(() => {
                                    const resolved = formatAvatarUrl(block.linkedEntity.avatarUrl, block.linkedEntity.entityId);
                                    return resolved ? (
                                      <img src={resolved} alt="" className="w-full h-full object-cover" />
                                    ) : (
                                      block.linkedEntity.entityName[0].toUpperCase()
                                    );
                                  })()}
                                </div>
                                <div className="flex flex-col">
                                  <span className="font-bold text-white text-xs flex items-center gap-1.5">
                                    {block.linkedEntity.entityName}
                                  </span>
                                  {block.linkedEntity.entitySubtext && (
                                    <span className="text-[10px] text-slate-500 font-mono">
                                      {block.linkedEntity.entitySubtext}
                                    </span>
                                  )}
                                </div>
                              </div>
                            ) : (
                              <span className="text-slate-600 text-xs italic">Unidentified Client</span>
                            )}
                          </td>

                          <td className="px-8 py-6">
                            <div className="flex flex-col">
                              <span className="text-white font-semibold text-xs">
                                {(block as any).reasonDetail?.title || block.tier || 'Access Throttle'}
                              </span>
                              <span className="text-slate-500 text-[11px] max-w-xs truncate">
                                {(block as any).reasonDetail?.explanation || 'Rate limit threshold exceeded'}
                              </span>
                            </div>
