                    </h3>
                    <button
                      onClick={handleClearHistory}
                      disabled={clearing || blockHistory.length === 0}
                      className="flex items-center gap-2 text-xs font-black uppercase tracking-widest text-slate-500 hover:text-rose-400 disabled:opacity-40 transition-colors cursor-pointer"
                    >
                      <Trash2 className="w-3 h-3" />
                      {clearing ? 'Clearing...' : 'Clear History'}
                    </button>
                  </div>
                  <table className="w-full text-left">
                    <thead>
                      <tr className="bg-slate-900/50 text-[10px] font-black uppercase tracking-widest text-slate-500">
                        <th className="px-8 py-5">IP / Reference</th>
                        <th className="px-8 py-5">Linked Entity</th>
                        <th className="px-8 py-5">Action & Scope</th>
                        <th className="px-8 py-5">Reason</th>
                        <th className="px-8 py-5">When</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-white/5">
                      {blockHistory.slice().reverse().map((block, i) => (
                        <tr key={`${block.ip}-${block.triggered}-${i}`} className="hover:bg-white/5 opacity-80">
                          <td className="px-8 py-5">
                            <div className="flex flex-col">
                              <code className="text-slate-300 font-bold text-xs">{block.ip || '—'}</code>
                              {(block as any).referenceCode && (
                                <span className="text-[10px] text-cyan-400 font-mono">{(block as any).referenceCode}</span>
                              )}
                            </div>
                          </td>

                          {/* Linked Entity */}
                          <td className="px-8 py-5">
                            {block.linkedEntity ? (
                              <div className="flex items-center gap-2">
                                <div className="w-6 h-6 rounded-full bg-blue-500/10 border border-blue-500/20 flex items-center justify-center text-[10px] font-bold text-blue-400 overflow-hidden shrink-0">
