            <button
              onClick={() => setViewMode('grid')}
              className={`p-1.5 rounded-lg text-xs font-bold transition-all ${viewMode === 'grid' ? 'bg-cyan-500/20 text-cyan-400' : 'text-slate-500 hover:text-white'}`}
              title="Grid View"
            >
              <LayoutGrid className="w-4 h-4" />
            </button>
          </div>
        </div>
      </div>

      {filteredUsers.length === 0 ? (
        <div className="p-12 text-center text-slate-500 text-sm">
          No users matching the filter criteria.
        </div>
      ) : viewMode === 'table' ? (
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-slate-900/50 text-[10px] uppercase tracking-widest text-slate-500 font-bold">
                <th className="px-8 py-4">User</th>
                <th className="px-8 py-4">Status</th>
                <th className="px-8 py-4">Roles</th>
                <th className="px-8 py-4">Last Activity</th>
                <th className="px-8 py-4 text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-800/50">
              {filteredUsers.map((user) => (
                <tr key={user.id} className="hover:bg-slate-900/30 transition-colors group">
                  <td className="px-8 py-5">
                    <div className="flex items-center gap-4">
                      <div className="w-10 h-10 rounded-full bg-slate-800 flex items-center justify-center border border-slate-700">
                        <User className="w-5 h-5 text-slate-400" />
                      </div>
                      <div>
                        <div className="text-white font-bold text-sm tracking-tight flex items-center gap-1.5">
                          <span>{user.displayName || user.username}</span>
                          {user.displayName && user.username && user.displayName !== user.username && (
                            <span className="text-xs font-normal text-cyan-400/80">(@{user.username})</span>
                          )}
                        </div>
                        <div className="text-slate-500 text-xs flex items-center gap-1">
                          <Mail className="w-3 h-3" />
                          {user.email || 'No email'}
                        </div>
                      </div>
                    </div>
                  </td>
                  <td className="px-8 py-5">
                    {user.isActive ?? user.status === 'active' ? (
                      <span className="flex items-center gap-1.5 text-emerald-500 text-xs font-bold">
                        <CheckCircle className="w-3 h-3" />
                        Active
                      </span>
                    ) : (
                      <span className="flex items-center gap-1.5 text-slate-500 text-xs font-bold">
                        <XCircle className="w-3 h-3" />
                        {user.status || 'Deactivated'}
                      </span>
                    )}
                  </td>
                  <td className="px-8 py-5">
                    <div className="flex flex-wrap gap-2">
                      {(user.roles || (user.globalRole ? [user.globalRole] : [])).map((role: string) => (
                        <span key={role} className="px-2 py-0.5 bg-cyan-500/10 text-cyan-400 border border-cyan-500/20 rounded text-[9px] font-bold uppercase tracking-wider">
                          {role}
                        </span>
                      ))}
                    </div>
                  </td>
                  <td className="px-8 py-5 text-slate-500 text-xs font-mono">
                    {user.lastLogin || user.updatedAt ? new Date(user.lastLogin || user.updatedAt).toLocaleDateString() : 'Never'}
                  </td>
                  <td className="px-8 py-5 text-right">
                    <div className="flex items-center justify-end gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                      <button 
                        onClick={() => onUpdate(user.id, { isActive: !(user.isActive ?? user.status === 'active') })}
                        className="p-2 hover:bg-slate-800 rounded-lg text-slate-400 hover:text-white transition-colors"
                        title="Toggle Access"
                      >
                        <Key className="w-4 h-4" />
                      </button>
                      <button 
                        onClick={() => onDelete(user.id)}
                        className="p-2 hover:bg-slate-800 rounded-lg text-red-400/50 hover:text-red-400 transition-colors"
                        title="Delete User"
                      >
                        <Trash2 className="w-4 h-4" />
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      ) : (
        <div className="p-6 grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
          {filteredUsers.map((user) => (
            <div key={user.id} className="p-5 rounded-2xl bg-slate-900/50 border border-slate-800 flex flex-col justify-between space-y-3">
              <div className="flex items-start justify-between">
                <div className="flex items-center gap-3">
                  <div className="w-10 h-10 rounded-full bg-slate-800 flex items-center justify-center border border-slate-700">
                    <User className="w-5 h-5 text-slate-400" />
                  </div>
                  <div>
                    <h4 className="text-sm font-bold text-white">{user.displayName || user.username}</h4>
                    {user.displayName && user.username && user.displayName !== user.username && (
                      <p className="text-xs text-cyan-400/80">@{user.username}</p>
                    )}
                  </div>
                </div>
                <span className={`px-2 py-0.5 rounded text-[9px] font-bold uppercase ${user.isActive ?? user.status === 'active' ? 'bg-emerald-500/10 text-emerald-400 border border-emerald-500/20' : 'bg-slate-800 text-slate-400'}`}>
                  {user.isActive ?? user.status === 'active' ? 'Active' : 'Inactive'}
                </span>
              </div>

              <div className="flex flex-wrap gap-1.5">
                {(user.roles || (user.globalRole ? [user.globalRole] : [])).map((role: string) => (
                  <span key={role} className="px-2 py-0.5 bg-cyan-500/10 text-cyan-400 border border-cyan-500/20 rounded text-[9px] font-bold uppercase">
                    {role}
                  </span>
                ))}
              </div>

              <div className="pt-2 border-t border-slate-800/80 flex items-center justify-between text-xs text-slate-500">
                <span className="font-mono text-[11px] truncate max-w-[150px]">{user.email || 'No email'}</span>
                <div className="flex items-center gap-1">
                  <button 
                    onClick={() => onUpdate(user.id, { isActive: !(user.isActive ?? user.status === 'active') })}
                    className="p-1.5 hover:bg-slate-800 rounded text-slate-400 hover:text-white"
                  >
                    <Key className="w-3.5 h-3.5" />
                  </button>
                  <button 
                    onClick={() => onDelete(user.id)}
                    className="p-1.5 hover:bg-slate-800 rounded text-rose-400 hover:text-rose-300"
                  >
                    <Trash2 className="w-3.5 h-3.5" />
                  </button>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}

      <footer className="p-4 bg-slate-900/50 border-t border-slate-800 text-center">
        <p className="text-[10px] text-slate-600 font-bold tracking-widest uppercase">
          2026 GameProductions™. All rights reserved.
        </p>
      </footer>
    </div>
  );
};

/** @jsxImportSource react */
import React, { useState, useEffect, useMemo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { 
  Key, 
  ShieldCheck, 
  Search, 
  Plus, 
  FolderLock, 
  RefreshCw, 
  ExternalLink, 
  Copy, 
  Check, 
  Eye, 
  EyeOff, 
  Trash2, 
  Edit3, 
  X, 
  Layers, 
  Tag, 
  Terminal, 
  Database, 
  Server, 
  Sparkles,
  Lock,
  ChevronRight,
  Sliders,
  AlertCircle,
  Info,
  Globe,
  Shield,
  Radio,
  Activity,
  Zap,
  Settings,
  Code,
  AlertTriangle
} from 'lucide-react';
import { toast } from 'sonner';
import { useBodyScrollLock } from '../../../hooks/useBodyScrollLock';
import { PasskeyChallenge } from '../../PasskeyChallenge';

interface OpVault {
  id: string;
  name: string;
  description?: string;
  items?: number;
  attributeVersion?: number;
  contentVersion?: number;
  type?: string;
  createdAt?: string;
  updatedAt?: string;
}

interface OpField {
  id?: string;
  section?: {
    id: string;
    label?: string;
  };
  type: 'STRING' | 'CONCEALED' | 'URL' | 'EMAIL' | 'DATE' | 'OTP' | 'MENU';
  label: string;
  value?: string;
}

interface OpSection {
  id: string;
  label: string;
}

interface OpItem {
  id: string;
  title: string;
  category: 'API_CREDENTIAL' | 'SECURE_NOTE' | 'SERVER' | 'LOGIN' | string;
  tags?: string[];
  fields?: OpField[];
  sections?: OpSection[];
  notesPlain?: string;
}

interface FleetApp {
  id: string;
  name: string;
  description?: string;
  apiKeyPrefix: string;
  status: 'active' | 'revoked' | 'suspended';
  allowedVaultsJson: string;
  allowedCategoriesJson: string;
  allowedTagsJson: string;
  permissionLevel: 'read_only' | 'read_write' | 'sync';
  rateLimitPerMin: number;
  lastAccessedAt?: string;
  lastAccessedIp?: string;
  createdAt: string;
}

interface FleetLog {
  id: number;
  appId: string;
  appName?: string;
  action: string;
  vaultId?: string;
  itemTitle?: string;
  ipAddress?: string;
  status: 'SUCCESS' | 'DENIED' | 'ERROR';
  errorMessage?: string;
  durationMs: number;
  createdAt: string;
}

export function VaultManager() {
  const [activeTab, setActiveTab] = useState<'vaults' | 'fleet' | 'settings'>('vaults');
  const [vaults, setVaults] = useState<OpVault[]>([]);
  const [selectedVaultId, setSelectedVaultId] = useState<string>('');
  const [items, setItems] = useState<OpItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedCategory, setSelectedCategory] = useState<string>('ALL');
  const [activeItem, setActiveItem] = useState<OpItem | null>(null);
  const [itemDetailsLoading, setItemDetailsLoading] = useState(false);
  const [revealedFields, setRevealedFields] = useState<Record<string, boolean>>({});
  const [copiedKey, setCopiedKey] = useState<string | null>(null);

  // Modal states
  const [isCreateModalOpen, setIsCreateModalOpen] = useState(false);
  const [isVaultInfoModalOpen, setIsVaultInfoModalOpen] = useState(false);
  const [selectedVaultInfo, setSelectedVaultInfo] = useState<OpVault | null>(null);
  const [vaultInfoLoading, setVaultInfoLoading] = useState(false);
  const [isPasskeyStepUpRequired, setIsPasskeyStepUpRequired] = useState(false);
  const [pendingRevealAction, setPendingRevealAction] = useState<(() => void) | null>(null);

  // Fleet Applications Gateway state
  const [fleetAppsList, setFleetAppsList] = useState<FleetApp[]>([]);
  const [fleetLogs, setFleetLogs] = useState<FleetLog[]>([]);
  const [fleetLoading, setFleetLoading] = useState(false);
  const [isProvisionModalOpen, setIsProvisionModalOpen] = useState(false);
  const [generatedKeyData, setGeneratedKeyData] = useState<{ rawKey: string; name: string; appId: string } | null>(null);

  // Settings & Testing state
  const [configSummary, setConfigSummary] = useState<any>(null);
  const [testingConnection, setTestingConnection] = useState(false);
  const [testResult, setTestResult] = useState<any>(null);
  const [selectedAuthMode, setSelectedAuthMode] = useState<'service_account' | 'connect' | 'auto'>('service_account');
  const [inputSaToken, setInputSaToken] = useState('');
  const [inputConnectHost, setInputConnectHost] = useState('');
  const [inputConnectToken, setInputConnectToken] = useState('');

  // Form State for creating new secret item
  const [newTitle, setNewTitle] = useState('');
  const [newCategory, setNewCategory] = useState('API_CREDENTIAL');
  const [newTags, setNewTags] = useState('');
  const [newNotes, setNewNotes] = useState('');
  const [newSections, setNewSections] = useState<{ id: string; label: string; fields: { label: string; value: string; type: 'STRING' | 'CONCEALED' | 'URL' }[] }[]>([
    {
      id: 'sec_auth',
      label: 'Authentication & Security',
      fields: [{ label: 'SECRET_KEY', value: '', type: 'CONCEALED' }]
    }
  ]);
  const [creating, setCreating] = useState(false);

  useEffect(() => {
    fetchVaults();
    fetchConfigSummary();
  }, []);

  useEffect(() => {
    if (selectedVaultId && activeTab === 'vaults') {
      fetchItems(selectedVaultId);
    }
    if (activeTab === 'fleet') {
      fetchFleetData();
    }
  }, [selectedVaultId, activeTab]);

  const fetchConfigSummary = async () => {
    try {
      const res = await fetch('/api/admin/vaults/settings/summary');
      const data = await res.json() as any;
      if (data.success && data.summary) {
        setConfigSummary(data.summary);
        if (data.summary.activeMode && data.summary.activeMode !== 'unconfigured') {
          setSelectedAuthMode(data.summary.activeMode);
        }
      }
    } catch {
      // Ignore
    }
  };

  const handleOpenVaultInfo = async (vaultId: string) => {
    setIsVaultInfoModalOpen(true);
    setVaultInfoLoading(true);
    try {
      const res = await fetch(`/api/admin/vaults/${vaultId}`);
      const data = await res.json() as any;
      if (data.success && data.vault) {
        setSelectedVaultInfo(data.vault);
      } else {
        const fallback = vaults.find(v => v.id === vaultId);
        setSelectedVaultInfo(fallback || null);
      }
    } catch {
      const fallback = vaults.find(v => v.id === vaultId);
      setSelectedVaultInfo(fallback || null);
    } finally {
      setVaultInfoLoading(false);
    }
  };

  const fetchVaults = async () => {
    try {
      const res = await fetch('/api/admin/vaults');
      const data = await res.json() as any;
      if (data.success && Array.isArray(data.vaults)) {
        setVaults(data.vaults);
        if (data.vaults.length > 0 && !selectedVaultId) {
          setSelectedVaultId(data.vaults[0].id);
        }
      }
    } catch (err) {
      console.warn('Failed to fetch dynamic vaults:', err);
    }
  };

  const fetchItems = async (vaultId: string) => {
    setLoading(true);
    try {
      const res = await fetch(`/api/admin/vaults/${vaultId}/items`);
      const data = await res.json() as any;
      if (data.success && Array.isArray(data.items)) {
        setItems(data.items);
      } else {
        setItems([]);
      }
    } catch (err) {
      console.error('Error fetching vault items:', err);
      toast.error('Failed to load vault items');
      setItems([]);
    } finally {
      setLoading(false);
    }
  };

  const loadItemDetails = async (itemId: string) => {
    setItemDetailsLoading(true);
    try {
      const res = await fetch(`/api/admin/vaults/${selectedVaultId}/items/${itemId}`);
      const data = await res.json() as any;
      if (data.success && data.data) {
        setActiveItem(data.data);
      }
    } catch (err) {
      console.error('Error fetching item details:', err);
      toast.error('Failed to load item details');
    } finally {
      setItemDetailsLoading(false);
    }
  };

  const fetchFleetData = async () => {
    setFleetLoading(true);
    try {
      const [appsRes, logsRes] = await Promise.all([
        fetch('/api/admin/vaults/fleet-apps'),
        fetch('/api/admin/vaults/fleet-logs')
      ]);
      const appsData = await appsRes.json() as any;
      const logsData = await logsRes.json() as any;

      if (appsData.success && Array.isArray(appsData.apps)) {
        setFleetAppsList(appsData.apps);
      }
      if (logsData.success && Array.isArray(logsData.logs)) {
        setFleetLogs(logsData.logs);
      }
    } catch (err) {
      console.error('Failed to fetch fleet app data:', err);
    } finally {
      setFleetLoading(false);
    }
  };

  const handleCreateItem = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newTitle.trim()) {
      toast.error('Item title is required');
      return;
    }

    setCreating(true);
    try {
      const payload = {
        title: newTitle.trim(),
        category: newCategory,
        tags: newTags.split(',').map(t => t.trim()).filter(Boolean),
        notesPlain: newNotes,
        sections: newSections.map(s => ({
          id: s.id,
          label: s.label
        })),
        fields: newSections.flatMap(s =>
          s.fields.map(f => ({
            section: { id: s.id, label: s.label },
            type: f.type,
            label: f.label,
            value: f.value
          }))
        )
      };

      const res = await fetch(`/api/admin/vaults/${selectedVaultId}/items`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload)
      });

      const data = await res.json() as any;
      if (data.success) {
        toast.success(`Secret '${newTitle}' saved to 1Password!`);
        setIsCreateModalOpen(false);
        setNewTitle('');
        setNewTags('');
        setNewNotes('');
        fetchItems(selectedVaultId);
      } else {
        toast.error(data.error || 'Failed to create secret item');
      }
    } catch (err: any) {
      toast.error(err.message || 'Network error');
    } finally {
      setCreating(false);
    }
  };

  const handleDeleteItem = async (itemId: string, itemTitle?: string) => {
    if (!confirm(`Are you sure you want to permanently delete '${itemTitle || itemId}' from 1Password?`)) {
      return;
    }

    try {
      const res = await fetch(`/api/admin/vaults/${selectedVaultId}/items/${itemId}`, {
        method: 'DELETE'
      });
      const data = await res.json() as any;
      if (data.success) {
        toast.success('Secret item removed from 1Password');
        if (activeItem?.id === itemId) setActiveItem(null);
        fetchItems(selectedVaultId);
      } else {
        toast.error(data.error || 'Failed to delete item');
      }
    } catch (err: any) {
      toast.error(err.message || 'Network error');
    }
  };

  const handleRevealField = (fieldKey: string) => {
    if (revealedFields[fieldKey]) {
      setRevealedFields(prev => ({ ...prev, [fieldKey]: false }));
      return;
    }

    setPendingRevealAction(() => () => {
      setRevealedFields(prev => ({ ...prev, [fieldKey]: true }));
      toast.success('Credential revealed via biometric passkey step-up');
    });
    setIsPasskeyStepUpRequired(true);
  };

  const handleCopy = (text: string, keyName: string) => {
    navigator.clipboard.writeText(text);
    setCopiedKey(keyName);
    toast.success('Copied to clipboard');
    setTimeout(() => setCopiedKey(null), 2000);
  };

  const handleTestConnection = async () => {
    setTestingConnection(true);
    setTestResult(null);
    try {
      const payload: any = { authMode: selectedAuthMode };
      if (selectedAuthMode === 'service_account' && inputSaToken) {
        payload.serviceAccountToken = inputSaToken;
      }
      if (selectedAuthMode === 'connect') {
        if (inputConnectHost) payload.connectHost = inputConnectHost;
        if (inputConnectToken) payload.connectToken = inputConnectToken;
      }

      const res = await fetch('/api/admin/vaults/test-connection', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload)
      });
      const data = await res.json() as any;
      setTestResult(data);
      if (data.success) {
        toast.success(data.message);
        fetchConfigSummary();
      } else {
        toast.error(data.error || 'Connection test failed');
      }
    } catch (err: any) {
      setTestResult({ success: false, error: err.message });
      toast.error(err.message || 'Connection test failed');
    } finally {
      setTestingConnection(false);
    }
  };

  const handleRotateKey = async (appId: string) => {
    if (!confirm(`Rotate the Fleet Application key for '${appId}'? Connected instances will need the new token.`)) return;
    try {
      const res = await fetch(`/api/admin/vaults/fleet-apps/${appId}/rotate`, { method: 'POST' });
      const data = await res.json() as any;
      if (data.success && data.rawKey) {
        setGeneratedKeyData({ rawKey: data.rawKey, name: appId, appId });
        toast.success(`Key rotated for '${appId}'`);
        fetchFleetData();
      } else {
        toast.error(data.error || 'Failed to rotate key');
      }
    } catch (err: any) {
      toast.error(err.message || 'Failed to rotate key');
    }
  };

  const handleRevokeApp = async (appId: string) => {
    if (!confirm(`Revoke and remove Fleet Application connection '${appId}'?`)) return;
    try {
      const res = await fetch(`/api/admin/vaults/fleet-apps/${appId}`, { method: 'DELETE' });
      const data = await res.json() as any;
      if (data.success) {
        toast.success(`Fleet Application '${appId}' revoked`);
        fetchFleetData();
      } else {
        toast.error(data.error || 'Failed to revoke app');
      }
    } catch (err: any) {
      toast.error(err.message || 'Failed to revoke app');
    }
  };

  const filteredItems = useMemo(() => {
    return items.filter(item => {
      const matchesSearch = searchQuery === '' || 
        item.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
        item.id.toLowerCase().includes(searchQuery.toLowerCase()) ||
        (item.tags && item.tags.some(t => t.toLowerCase().includes(searchQuery.toLowerCase())));

      const matchesCategory = selectedCategory === 'ALL' || item.category === selectedCategory;
      return matchesSearch && matchesCategory;
    });
  }, [items, searchQuery, selectedCategory]);

  return (
    <div className="space-y-8">
      {/* Passkey Verification Dialog */}
      {isPasskeyStepUpRequired && (
        <PasskeyChallenge
          appName="1Password Credential Reveal"
          onSuccess={() => {
            setIsPasskeyStepUpRequired(false);
            if (pendingRevealAction) {
              pendingRevealAction();
              setPendingRevealAction(null);
            }
          }}
          onCancel={() => {
            setIsPasskeyStepUpRequired(false);
            setPendingRevealAction(null);
          }}
        />
      )}

      {/* Header Banner & Hub Navigation */}
