                          <span>Rate: {app.rateLimitPerMin}/min</span>
                        </div>
                        {app.lastAccessedAt && (
                          <div className="text-[10px] text-slate-500 font-mono">
                            Last Active: {new Date(app.lastAccessedAt).toLocaleString()} ({app.lastAccessedIp || 'LAN'})
                          </div>
                        )}
                      </div>

                      {/* Card Action Buttons */}
                      <div className="pt-3 border-t border-slate-800 flex items-center justify-between gap-2">
                        <button
                          onClick={() => handleRotateKey(app.id)}
                          className="px-3 py-1.5 rounded-xl bg-slate-800 hover:bg-indigo-600/20 text-slate-300 hover:text-indigo-300 border border-slate-700 text-xs font-bold transition-all cursor-pointer flex items-center gap-1.5"
                        >
                          <RefreshCw className="w-3.5 h-3.5" />
                          <span>Rotate Key</span>
                        </button>

                        <button
                          onClick={() => handleRevokeApp(app.id)}
                          className="px-3 py-1.5 rounded-xl bg-rose-500/10 hover:bg-rose-500/20 text-rose-400 border border-rose-500/20 text-xs font-bold transition-all cursor-pointer flex items-center gap-1.5"
                        >
                          <Trash2 className="w-3.5 h-3.5" />
                          <span>Revoke</span>
                        </button>
                      </div>
                    </div>
                  );
                })}
              </div>
            )}
          </div>

          {/* Real-Time Access & Sync Audit Logs */}
          <div className="bg-slate-900/60 border border-slate-800/80 rounded-3xl p-6 space-y-4">
            <div className="flex items-center justify-between">
              <div>
                <h4 className="text-base font-black text-white">Fleet Access &amp; Gateway Audit Trail</h4>
                <p className="text-xs text-slate-400">Live telemetry of Fleet Application credential requests and sync events.</p>
              </div>
              <button
                onClick={fetchFleetData}
                className="p-2 text-slate-400 hover:text-white rounded-xl hover:bg-slate-800 transition-colors cursor-pointer"
              >
                <RefreshCw className="w-4 h-4" />
              </button>
            </div>

            {fleetLogs.length === 0 ? (
              <div className="py-8 text-center text-xs text-slate-500">No Fleet Application access requests recorded yet.</div>
            ) : (
              <div className="overflow-x-auto">
                <table className="w-full text-left text-xs font-sans">
                  <thead>
                    <tr className="border-b border-slate-800 text-slate-500 font-mono text-[10px] uppercase">
                      <th className="pb-3 font-bold">Timestamp</th>
                      <th className="pb-3 font-bold">Fleet App</th>
                      <th className="pb-3 font-bold">Operation</th>
                      <th className="pb-3 font-bold">Item / Vault</th>
                      <th className="pb-3 font-bold">IP Address</th>
                      <th className="pb-3 font-bold">Status</th>
                      <th className="pb-3 font-bold">Latency</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-800/50 text-slate-300">
                    {fleetLogs.slice(0, 15).map(log => (
                      <tr key={log.id} className="hover:bg-slate-800/30">
                        <td className="py-2.5 font-mono text-slate-500 text-[11px] whitespace-nowrap">
                          {new Date(log.createdAt).toLocaleTimeString()}
                        </td>
                        <td className="py-2.5 font-bold text-white">{log.appName || log.appId}</td>
                        <td className="py-2.5 font-mono text-indigo-400 font-bold">{log.action}</td>
                        <td className="py-2.5 font-mono text-slate-400">{log.itemTitle || log.vaultId?.substring(0, 10) || 'All'}</td>
                        <td className="py-2.5 font-mono text-slate-500">{log.ipAddress || '127.0.0.1'}</td>
                        <td className="py-2.5">
                          <span className={`px-2 py-0.5 rounded text-[10px] font-bold uppercase ${
                            log.status === 'SUCCESS' ? 'bg-emerald-500/20 text-emerald-400' : 'bg-rose-500/20 text-rose-400'
                          }`}>
                            {log.status}
                          </span>
                        </td>
                        <td className="py-2.5 font-mono text-slate-400">{log.durationMs}ms</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </div>
        </div>
      )}

      {/* TAB 3: INTEGRATION SETTINGS (OPTION A VS CONNECT) */}
      {activeTab === 'settings' && (
        <div className="max-w-3xl mx-auto space-y-6">
          <div className="p-8 bg-slate-900/60 border border-slate-800 rounded-3xl space-y-6">
            <div>
              <div className="flex items-center gap-3">
                <div className="p-3 bg-indigo-500/10 text-indigo-400 rounded-2xl border border-indigo-500/20">
                  <Sliders className="w-6 h-6" />
                </div>
                <div>
                  <h3 className="text-xl font-black text-white">1Password Fleet Integration Controls</h3>
                  <p className="text-xs text-slate-400">Choose between direct Service Account API access and 1Password Connect.</p>
                </div>
              </div>
            </div>

            {/* Mode Selector */}
            <div className="space-y-3">
              <label className="text-xs font-bold text-slate-300 uppercase tracking-wider block">Authentication Strategy</label>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                <button
                  type="button"
                  onClick={() => setSelectedAuthMode('service_account')}
                  className={`p-4 rounded-2xl border text-left space-y-1.5 transition-all cursor-pointer ${
                    selectedAuthMode === 'service_account'
                      ? 'bg-indigo-600/15 border-indigo-500 text-white shadow-lg shadow-indigo-500/10'
                      : 'bg-slate-950/40 border-slate-800 text-slate-400 hover:border-slate-700'
                  }`}
                >
                  <div className="flex items-center justify-between">
                    <span className="font-bold text-sm text-white">Direct Service Account</span>
                    {selectedAuthMode === 'service_account' && <Check className="w-4 h-4 text-indigo-400" />}
                  </div>
                  <p className="text-xs text-slate-400 leading-relaxed">
                    Uses official Service Account token (`opsa_...`). Communicates directly with 1Password cloud without Connect containers.
                  </p>
                </button>

                <button
                  type="button"
                  onClick={() => setSelectedAuthMode('connect')}
                  className={`p-4 rounded-2xl border text-left space-y-1.5 transition-all cursor-pointer ${
                    selectedAuthMode === 'connect'
                      ? 'bg-indigo-600/15 border-indigo-500 text-white shadow-lg shadow-indigo-500/10'
                      : 'bg-slate-950/40 border-slate-800 text-slate-400 hover:border-slate-700'
                  }`}
                >
                  <div className="flex items-center justify-between">
                    <span className="font-bold text-sm text-white">1Password Connect Server</span>
                    {selectedAuthMode === 'connect' && <Check className="w-4 h-4 text-indigo-400" />}
                  </div>
                  <p className="text-xs text-slate-400 leading-relaxed">
                    Uses self-hosted 1Password Connect Docker/Kubernetes container with sync server host &amp; access token.
                  </p>
                </button>
              </div>
            </div>

            {/* Input Form Fields */}
            <div className="space-y-4 pt-4 border-t border-slate-800">
              {selectedAuthMode === 'service_account' ? (
                <div className="space-y-2">
                  <label className="text-xs font-bold text-slate-300 flex items-center justify-between">
                    <span>1Password Service Account Token (OP_SERVICE_ACCOUNT_TOKEN)</span>
                    <span className="text-[10px] text-emerald-400 font-mono font-bold">Standard: opsa_...</span>
                  </label>
                  <input
                    type="password"
                    value={inputSaToken}
                    onChange={e => setInputSaToken(e.target.value)}
                    placeholder={configSummary?.serviceAccountTokenPrefix || "opsa_xxxxxxxxxxxxxxxxxxxxxxxxxxxx"}
                    className="w-full px-4 py-3 bg-slate-950 border border-slate-800 rounded-2xl text-xs font-mono text-white focus:outline-none focus:border-indigo-500"
                  />
                  <p className="text-[11px] text-slate-500">
                    Generated in 1Password.com &gt; Developer &gt; Service Accounts. Granted access to Fleet Services &amp; Self-Hosted Infrastructure vaults.
                  </p>
                </div>
              ) : (
                <div className="space-y-4">
                  <div className="space-y-2">
                    <label className="text-xs font-bold text-slate-300">1Password Connect Host (OP_CONNECT_HOST)</label>
                    <input
                      type="text"
                      value={inputConnectHost}
                      onChange={e => setInputConnectHost(e.target.value)}
                      placeholder={configSummary?.connectHost || "http://1password-connect:8080 or https://op.gpnet.dev"}
                      className="w-full px-4 py-3 bg-slate-950 border border-slate-800 rounded-2xl text-xs font-mono text-white focus:outline-none focus:border-indigo-500"
                    />
                    <p className="text-[11px] text-slate-500">
                      Supports direct IP, Tailscale MagicDNS (`http://host.ts.net:8080`), WireGuard (`http://10.x.x.x:8080`), or Cloudflare Tunnel HTTPS endpoint.
                    </p>
                  </div>

                  <div className="space-y-2">
                    <label className="text-xs font-bold text-slate-300">1Password Connect Access Token (OP_CONNECT_TOKEN)</label>
                    <input
                      type="password"
                      value={inputConnectToken}
                      onChange={e => setInputConnectToken(e.target.value)}
                      placeholder={configSummary?.connectTokenPrefix || "eyJhbGciOiJFUzI1Ni..."}
                      className="w-full px-4 py-3 bg-slate-950 border border-slate-800 rounded-2xl text-xs font-mono text-white focus:outline-none focus:border-indigo-500"
                    />
                  </div>

                  {/* Cloudflare Zero Trust Service Token (Optional for Cloudflare Tunnel Ingress) */}
                  <div className="p-4 rounded-2xl bg-slate-950/60 border border-white/5 space-y-3">
                    <div className="flex items-center justify-between">
                      <span className="text-xs font-bold text-white flex items-center gap-1.5">
                        <Globe className="w-3.5 h-3.5 text-blue-400" />
                        Cloudflare Zero Trust Service Token (Optional)
                      </span>
                      <span className="text-[10px] px-2 py-0.5 rounded bg-blue-500/10 border border-blue-500/20 text-blue-300 font-mono">
                        CF-Access Headers
                      </span>
                    </div>
                    <p className="text-[11px] text-slate-400 leading-relaxed">
                      Required when routing requests through a Cloudflare Zero Trust Access Tunnel protected with Service Token auth.
                    </p>
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                      <div>
                        <label className="text-[10px] font-bold text-slate-400 block mb-1">CF-Access-Client-Id</label>
                        <input
                          type="text"
                          placeholder="xxxxxxxxxxxxxxxx.access"
                          className="w-full px-3 py-2 bg-slate-900 border border-slate-800 rounded-xl text-xs font-mono text-white focus:outline-none focus:border-indigo-500"
                          readOnly
                          value={configSummary?.hasCloudflareServiceToken ? "Configured in Environment" : ""}
                        />
                      </div>
                      <div>
                        <label className="text-[10px] font-bold text-slate-400 block mb-1">CF-Access-Client-Secret</label>
                        <input
                          type="password"
                          placeholder="••••••••••••••••••••••••••••••••"
                          className="w-full px-3 py-2 bg-slate-900 border border-slate-800 rounded-xl text-xs font-mono text-white focus:outline-none focus:border-indigo-500"
                          readOnly
                          value={configSummary?.hasCloudflareServiceToken ? "••••••••••••••••" : ""}
                        />
                      </div>
                    </div>
                  </div>
                </div>
              )}
            </div>

            {/* Test Connection Button & Diagnostic Box */}
            <div className="pt-4 border-t border-slate-800 space-y-4">
              <button
                type="button"
                onClick={handleTestConnection}
                disabled={testingConnection}
                className="w-full py-3.5 bg-gradient-to-r from-indigo-600 to-cyan-600 hover:from-indigo-500 hover:to-cyan-500 text-white font-bold rounded-2xl transition-all shadow-lg shadow-indigo-500/20 disabled:opacity-50 flex items-center justify-center gap-2 cursor-pointer"
              >
                <Zap className={`w-4 h-4 ${testingConnection ? 'animate-spin' : ''}`} />
                <span>{testingConnection ? 'Testing Connectivity...' : 'Test 1Password Live Connection'}</span>
              </button>

              {testResult && (
                <div className={`p-4 rounded-2xl border text-xs space-y-2 ${
                  testResult.success ? 'bg-emerald-500/10 border-emerald-500/30 text-emerald-300' : 'bg-rose-500/10 border-rose-500/30 text-rose-300'
                }`}>
                  <div className="flex items-center gap-2 font-bold">
                    {testResult.success ? <Check className="w-4 h-4 text-emerald-400" /> : <AlertTriangle className="w-4 h-4 text-rose-400" />}
                    <span>{testResult.success ? 'Connection Verified' : 'Connection Failed'}</span>
                  </div>
                  <p className="leading-relaxed">{testResult.message || testResult.error}</p>
                  {testResult.vaults && (
                    <div className="flex flex-wrap gap-2 pt-1 font-mono text-[11px]">
                      {testResult.vaults.map((v: any) => (
                        <span key={v.id} className="px-2 py-0.5 rounded bg-slate-900 border border-slate-800 text-slate-300">
                          {v.name}
                        </span>
                      ))}
                    </div>
                  )}
                </div>
              )}
            </div>
          </div>
        </div>
      )}

      {/* MODAL 1: CREATE ITEM MODAL */}
      <CreateItemModal
        isOpen={isCreateModalOpen}
        onClose={() => setIsCreateModalOpen(false)}
        onSubmit={handleCreateItem}
        creating={creating}
        newTitle={newTitle}
        setNewTitle={setNewTitle}
        newCategory={newCategory}
        setNewCategory={setNewCategory}
        newTags={newTags}
        setNewTags={setNewTags}
        newNotes={newNotes}
        setNewNotes={setNewNotes}
        newSections={newSections}
        setNewSections={setNewSections}
      />

      {/* MODAL 2: VAULT INFO MODAL */}
      <VaultInfoModal
        isOpen={isVaultInfoModalOpen}
        onClose={() => setIsVaultInfoModalOpen(false)}
        vault={selectedVaultInfo}
        loading={vaultInfoLoading}
        totalLoadedItems={items.length}
      />

      {/* MODAL 3: PROVISION FLEET APP MODAL */}
      <ProvisionFleetModal
        isOpen={isProvisionModalOpen}
        onClose={() => setIsProvisionModalOpen(false)}
        onSuccess={(app, rawKey) => {
          setIsProvisionModalOpen(false);
          setGeneratedKeyData({ rawKey, name: app.name, appId: app.id });
          fetchFleetData();
        }}
        vaults={vaults}
      />

      {/* MODAL 4: GENERATED FLEET KEY REVEAL MODAL */}
      {generatedKeyData && (
        <GeneratedKeyModal
          data={generatedKeyData}
          onClose={() => setGeneratedKeyData(null)}
        />
      )}
    </div>
  );
}

// Subcomponent: Create Item Modal with True Portal & Scroll Lock
interface CreateItemModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSubmit: (e: React.FormEvent) => void;
  creating: boolean;
  newTitle: string;
  setNewTitle: (v: string) => void;
  newCategory: string;
  setNewCategory: (v: string) => void;
  newTags: string;
  setNewTags: (v: string) => void;
  newNotes: string;
  setNewNotes: (v: string) => void;
  newSections: any[];
  setNewSections: React.Dispatch<React.SetStateAction<any[]>>;
}

function CreateItemModal({
  isOpen,
  onClose,
  onSubmit,
  creating,
  newTitle,
  setNewTitle,
  newCategory,
  setNewCategory,
  newTags,
  setNewTags,
  newNotes,
  setNewNotes,
  newSections,
  setNewSections
}: CreateItemModalProps) {
  useBodyScrollLock(isOpen);

  if (!isOpen) return null;

  const addSection = () => {
    setNewSections(prev => [
      ...prev,
      {
        id: `sec_${Date.now()}`,
        label: 'New Section',
        fields: [{ label: 'VARIABLE_NAME', value: '', type: 'CONCEALED' }]
      }
    ]);
  };

  const addFieldToSection = (sectionIndex: number) => {
    setNewSections(prev => {
      const copy = [...prev];
      copy[sectionIndex].fields.push({ label: '', value: '', type: 'CONCEALED' });
      return copy;
    });
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
      <motion.div
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        exit={{ opacity: 0 }}
        onClick={onClose}
        className="fixed inset-0 bg-slate-950/80 backdrop-blur-md"
      />

      <motion.div
        initial={{ opacity: 0, scale: 0.95, y: 20 }}
        animate={{ opacity: 1, scale: 1, y: 0 }}
        exit={{ opacity: 0, scale: 0.95, y: 20 }}
        className="relative w-full max-w-2xl bg-slate-900 border border-slate-800 rounded-3xl shadow-2xl overflow-hidden flex flex-col z-10 my-8 max-h-[90vh]"
      >
        <div className="p-6 border-b border-slate-800 flex items-center justify-between bg-slate-950/40">
          <div className="flex items-center gap-3">
            <div className="p-2.5 bg-indigo-500/10 text-indigo-400 rounded-xl">
              <Key className="w-5 h-5" />
            </div>
            <div>
              <h3 className="text-lg font-black text-white">Create New Secret Item</h3>
              <p className="text-xs text-slate-400">Save structured credentials directly into 1Password.</p>
            </div>
          </div>

          <button
            onClick={onClose}
            className="p-2 rounded-xl text-slate-400 hover:text-white hover:bg-slate-800 transition-colors cursor-pointer"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        <form onSubmit={onSubmit} className="p-6 space-y-6 overflow-y-auto">
          <div className="space-y-4">
            <div>
              <label className="text-xs font-bold text-slate-300 block mb-1.5">Item Title / Name</label>
              <input
                type="text"
                value={newTitle}
                onChange={e => setNewTitle(e.target.value)}
                placeholder="e.g. Voyarr RealDebrid API, Discord Bot Token"
                className="w-full px-4 py-3 bg-slate-950 border border-slate-800 rounded-2xl text-sm text-white focus:outline-none focus:border-indigo-500 font-medium"
                required
              />
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="text-xs font-bold text-slate-300 block mb-1.5">Category</label>
                <select
                  value={newCategory}
                  onChange={e => setNewCategory(e.target.value)}
                  className="w-full px-4 py-3 bg-slate-950 border border-slate-800 rounded-2xl text-sm text-white focus:outline-none focus:border-indigo-500"
                >
                  <option value="API_CREDENTIAL">API Credential</option>
                  <option value="LOGIN">Login &amp; Password</option>
                  <option value="SECURE_NOTE">Secure Note</option>
                  <option value="SERVER">Server / SSH</option>
                </select>
              </div>

              <div>
                <label className="text-xs font-bold text-slate-300 block mb-1.5">Tags (Comma-separated)</label>
                <input
                  type="text"
                  value={newTags}
                  onChange={e => setNewTags(e.target.value)}
                  placeholder="e.g. production, bot, media"
                  className="w-full px-4 py-3 bg-slate-950 border border-slate-800 rounded-2xl text-sm text-white focus:outline-none focus:border-indigo-500"
                />
              </div>
            </div>

            <div>
              <label className="text-xs font-bold text-slate-300 block mb-1.5">Operational Notes</label>
              <textarea
                value={newNotes}
                onChange={e => setNewNotes(e.target.value)}
                placeholder="Centralized notes or SOP context..."
                rows={2}
                className="w-full px-4 py-3 bg-slate-950 border border-slate-800 rounded-2xl text-sm text-white focus:outline-none focus:border-indigo-500"
              />
            </div>
          </div>

          <div className="space-y-4 pt-4 border-t border-slate-800">
            <div className="flex items-center justify-between">
              <span className="text-xs font-black text-slate-400 uppercase tracking-wider">Sections &amp; Variables</span>
              <button
                type="button"
                onClick={addSection}
                className="text-xs text-indigo-400 hover:text-indigo-300 font-bold flex items-center gap-1 cursor-pointer"
              >
                <Plus className="w-3.5 h-3.5" /> Add Section
              </button>
            </div>

            {newSections.map((sec, secIdx) => (
              <div key={sec.id} className="p-4 bg-slate-950/60 rounded-2xl border border-slate-800 space-y-3">
                <input
                  type="text"
                  value={sec.label}
                  onChange={e => {
                    const copy = [...newSections];
                    copy[secIdx].label = e.target.value;
                    setNewSections(copy);
                  }}
                  placeholder="Section Name (e.g. Authentication, Endpoint)"
                  className="w-full px-3 py-2 bg-slate-900 border border-slate-800 rounded-xl text-xs font-bold text-indigo-300 focus:outline-none"
                />

                <div className="space-y-2">
                  {sec.fields.map((f: any, fIdx: number) => (
                    <div key={fIdx} className="grid grid-cols-12 gap-2">
                      <input
                        type="text"
                        value={f.label}
                        onChange={e => {
                          const copy = [...newSections];
                          copy[secIdx].fields[fIdx].label = e.target.value;
                          setNewSections(copy);
                        }}
                        placeholder="KEY_NAME"
                        className="col-span-5 px-3 py-2 bg-slate-900 border border-slate-800 rounded-xl text-xs text-white focus:outline-none font-mono"
                      />
                      <input
                        type="text"
                        value={f.value}
                        onChange={e => {
                          const copy = [...newSections];
                          copy[secIdx].fields[fIdx].value = e.target.value;
                          setNewSections(copy);
                        }}
                        placeholder="Value or secret"
                        className="col-span-5 px-3 py-2 bg-slate-900 border border-slate-800 rounded-xl text-xs text-white focus:outline-none font-mono"
                      />
                      <select
                        value={f.type}
                        onChange={e => {
                          const copy = [...newSections];
                          copy[secIdx].fields[fIdx].type = e.target.value as any;
                          setNewSections(copy);
                        }}
                        className="col-span-2 px-2 py-2 bg-slate-900 border border-slate-800 rounded-xl text-[10px] text-slate-300 focus:outline-none"
                      >
                        <option value="CONCEALED">Hidden</option>
                        <option value="STRING">Text</option>
                        <option value="URL">URL</option>
                      </select>
                    </div>
                  ))}

                  <button
                    type="button"
                    onClick={() => addFieldToSection(secIdx)}
                    className="text-[11px] text-slate-400 hover:text-white font-bold flex items-center gap-1 cursor-pointer pt-1"
                  >
                    <Plus className="w-3 h-3" /> Add Variable
                  </button>
                </div>
              </div>
            ))}
          </div>

          <button
            type="submit"
            disabled={creating || !newTitle.trim()}
            className="w-full py-3.5 bg-gradient-to-r from-indigo-600 to-cyan-600 hover:from-indigo-500 hover:to-cyan-500 text-white font-bold rounded-2xl transition-all shadow-lg shadow-indigo-500/20 disabled:opacity-50 flex items-center justify-center gap-2 cursor-pointer"
          >
            <ShieldCheck className="w-4 h-4" />
            {creating ? 'Saving to 1Password...' : 'Save Secret Item to Vault'}
          </button>
        </form>
      </motion.div>
    </div>
  );
}

// Subcomponent: Vault Information & Official API Details Modal
interface VaultInfoModalProps {
  isOpen: boolean;
  onClose: () => void;
  vault: OpVault | null;
  loading: boolean;
  totalLoadedItems: number;
}

function VaultInfoModal({ isOpen, onClose, vault, loading, totalLoadedItems }: VaultInfoModalProps) {
  useBodyScrollLock(isOpen);
  const [copied, setCopied] = useState<string | null>(null);

  if (!isOpen) return null;

  const handleCopy = (text: string, id: string) => {
    navigator.clipboard.writeText(text);
