  onSuccess: (app: any, rawKey: string) => void;
  vaults: OpVault[];
}

function ProvisionFleetModal({ isOpen, onClose, onSuccess, vaults }: ProvisionFleetModalProps) {
  useBodyScrollLock(isOpen);
  const [name, setName] = useState('');
  const [description, setDescription] = useState('');
  const [permissionLevel, setPermissionLevel] = useState<'read_only' | 'read_write' | 'sync'>('read_write');
  const [rateLimitPerMin, setRateLimitPerMin] = useState(60);
  const [allowedVaults, setAllowedVaults] = useState<string[]>(['*']);
  const [allowedCategories, setAllowedCategories] = useState<string[]>(['LOGIN', 'API_CREDENTIAL', 'SECURE_NOTE', 'SERVER']);
  const [tagFilters, setTagFilters] = useState('voyarr, media');
  const [saving, setSaving] = useState(false);

  if (!isOpen) return null;

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!name.trim()) return;

    setSaving(true);
    try {
      const res = await fetch('/api/admin/vaults/fleet-apps', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          name: name.trim(),
          description,
          permissionLevel,
          rateLimitPerMin,
          allowedVaults,
          allowedCategories,
          allowedTags: tagFilters.split(',').map(t => t.trim()).filter(Boolean)
        })
      });
      const data = await res.json() as any;
      if (data.success) {
        toast.success(data.message);
        onSuccess(data.app, data.rawKey);
      } else {
        toast.error(data.error || 'Failed to provision Fleet Application');
      }
    } catch (err: any) {
      toast.error(err.message || 'Network error');
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
      <motion.div
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        exit={{ opacity: 0 }}
