import type { DevActionLog, DevState, DevTransition } from './useDevMode';

interface DevActionConsoleProps {
  projectId: string;
  projectName: string;
  state: DevState;
  transition?: DevTransition;
  currentTask?: string;
  progress: number;
  logs: DevActionLog[];
  processLog?: string;
  onRefreshProcessLog?: () => Promise<void>;
  onClearLogs?: () => void;
  devPort?: number | null;
  isOpen: boolean;
  onToggle: () => void;
}

export const DevActionConsole: React.FC<DevActionConsoleProps> = ({
  projectId,
  projectName,
  state,
  transition,
  currentTask,
  progress,
  logs = [],
  processLog = '',
  onRefreshProcessLog,
  onClearLogs,
  devPort,
  isOpen,
  onToggle,
}) => {
  const [activeTab, setActiveTab] = useState<'actions' | 'terminal'>('actions');
  const [copied, setCopied] = useState(false);
  const [isMaximized, setIsMaximized] = useState(false);
  const terminalBottomRef = useRef<HTMLDivElement>(null);
  const actionListRef = useRef<HTMLDivElement>(null);

  // Auto-scroll action log on update
  useEffect(() => {
    if (actionListRef.current) {
      actionListRef.current.scrollTop = actionListRef.current.scrollHeight;
    }
  }, [logs]);

  // Auto-scroll terminal log on update
  useEffect(() => {
    if (terminalBottomRef.current) {
      terminalBottomRef.current.scrollIntoView({ behavior: 'smooth' });
    }
  }, [processLog, activeTab]);

  const handleCopyLogs = () => {
    const text =
      activeTab === 'actions'
        ? logs.map((l) => `[${l.timestamp}] [${l.level.toUpperCase()}] ${l.task}${l.detail ? ` - ${l.detail}` : ''}`).join('\n')
        : processLog;
    navigator.clipboard.writeText(text);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const getLevelBadge = (level: DevActionLog['level']) => {
    switch (level) {
      case 'success':
        return <span className="px-1.5 py-0.5 rounded text-[8px] font-black uppercase bg-emerald-500/20 text-emerald-400 border border-emerald-500/30">SUCCESS</span>;
      case 'step':
        return <span className="px-1.5 py-0.5 rounded text-[8px] font-black uppercase bg-cyan-500/20 text-cyan-400 border border-cyan-500/30">STEP</span>;
      case 'warn':
        return <span className="px-1.5 py-0.5 rounded text-[8px] font-black uppercase bg-amber-500/20 text-amber-400 border border-amber-500/30">WARN</span>;
      case 'error':
        return <span className="px-1.5 py-0.5 rounded text-[8px] font-black uppercase bg-rose-500/20 text-rose-400 border border-rose-500/30">ERROR</span>;
      default:
        return <span className="px-1.5 py-0.5 rounded text-[8px] font-black uppercase bg-slate-800 text-slate-400 border border-slate-700">INFO</span>;
    }
  };

  const getLevelIcon = (level: DevActionLog['level']) => {
    switch (level) {
      case 'success':
        return <CheckCircle2 className="w-3.5 h-3.5 text-emerald-400 shrink-0 mt-0.5" />;
      case 'step':
        return <Activity className="w-3.5 h-3.5 text-cyan-400 shrink-0 mt-0.5 animate-pulse" />;
      case 'warn':
        return <AlertTriangle className="w-3.5 h-3.5 text-amber-400 shrink-0 mt-0.5" />;
      case 'error':
        return <XCircle className="w-3.5 h-3.5 text-rose-400 shrink-0 mt-0.5" />;
      default:
        return <Info className="w-3.5 h-3.5 text-slate-400 shrink-0 mt-0.5" />;
    }
  };

  const isBusy = state === 'starting' || state === 'stopping';

  return (
    <div className="w-full mt-3 font-sans">
      {/* Console Toggle Button */}
      <div className="flex items-center justify-between gap-2">
        <button
          type="button"
          onClick={onToggle}
          className={`flex items-center gap-2 px-3 py-1.5 rounded-xl text-[10px] font-black uppercase tracking-wider transition-all border ${
            isOpen
              ? 'bg-slate-800 text-cyan-400 border-cyan-500/40 shadow-sm'
              : 'bg-slate-950/80 text-slate-400 hover:text-white border-slate-800/80 hover:bg-slate-900'
          }`}
        >
          <Terminal className="w-3.5 h-3.5 text-cyan-400" />
          <span>{isOpen ? 'Hide Dev Console' : 'Dev Console & Action Log'}</span>
          {logs.length > 0 && (
            <span className="px-1.5 py-0.2 rounded-full text-[9px] bg-slate-800 text-slate-300 font-mono">
              {logs.length}
            </span>
          )}
          {isOpen ? <ChevronUp className="w-3.5 h-3.5 ml-0.5" /> : <ChevronDown className="w-3.5 h-3.5 ml-0.5" />}
        </button>

        {isBusy && currentTask && !isOpen && (
          <div className="flex items-center gap-2 text-[10px] font-mono text-cyan-400 animate-pulse truncate max-w-[240px] sm:max-w-none">
            <RefreshCw className="w-3 h-3 animate-spin shrink-0" />
            <span className="truncate">{currentTask}</span>
          </div>
        )}
      </div>

      {/* Expandable Console Drawer */}
      <AnimatePresence>
        {isOpen && (
          <motion.div
            initial={{ opacity: 0, height: 0 }}
            animate={{ opacity: 1, height: 'auto' }}
            exit={{ opacity: 0, height: 0 }}
            transition={{ duration: 0.2 }}
            className={`mt-2 rounded-2xl border border-slate-800 bg-slate-950/95 overflow-hidden shadow-2xl backdrop-blur-xl ${
              isMaximized ? 'fixed inset-4 z-50 flex flex-col' : 'relative'
            }`}
          >
            {/* Top Console Bar */}
            <div className="flex items-center justify-between px-3.5 py-2.5 bg-slate-900/80 border-b border-slate-800 text-xs">
              <div className="flex items-center space-x-2">
                <span className="w-2.5 h-2.5 rounded-full bg-cyan-400 animate-pulse" />
                <span className="font-bold text-white tracking-tight">{projectName} Dev Lifecycle</span>
                {devPort && (
                  <span className="px-1.5 py-0.5 bg-slate-800 text-emerald-400 rounded text-[9px] font-mono font-bold">
                    :{devPort}
                  </span>
                )}
              </div>

              {/* Tabs and Actions */}
              <div className="flex items-center space-x-1.5">
                <div className="flex bg-slate-950 p-0.5 rounded-lg border border-slate-800">
                  <button
                    type="button"
                    onClick={() => setActiveTab('actions')}
                    className={`px-2.5 py-1 rounded-md text-[10px] font-bold uppercase transition-all ${
                      activeTab === 'actions' ? 'bg-slate-800 text-cyan-400 shadow-sm' : 'text-slate-500 hover:text-slate-300'
                    }`}
                  >
                    Action History ({logs.length})
                  </button>
                  <button
                    type="button"
                    onClick={() => {
                      setActiveTab('terminal');
                      onRefreshProcessLog?.();
                    }}
                    className={`px-2.5 py-1 rounded-md text-[10px] font-bold uppercase transition-all ${
                      activeTab === 'terminal' ? 'bg-slate-800 text-cyan-400 shadow-sm' : 'text-slate-500 hover:text-slate-300'
                    }`}
                  >
                    Raw Terminal Output
                  </button>
                </div>

                {onRefreshProcessLog && (
                  <button
                    type="button"
                    onClick={onRefreshProcessLog}
                    className="p-1.5 text-slate-400 hover:text-white bg-slate-900 hover:bg-slate-800 border border-slate-800 rounded-lg transition-colors"
                    title="Refresh Output"
                  >
                    <RefreshCw className="w-3.5 h-3.5" />
                  </button>
                )}

                <button
                  type="button"
                  onClick={handleCopyLogs}
                  className="p-1.5 text-slate-400 hover:text-white bg-slate-900 hover:bg-slate-800 border border-slate-800 rounded-lg transition-colors"
                  title="Copy to Clipboard"
                >
                  {copied ? <Check className="w-3.5 h-3.5 text-emerald-400" /> : <Copy className="w-3.5 h-3.5" />}
                </button>

                {onClearLogs && (
                  <button
                    type="button"
                    onClick={onClearLogs}
                    className="p-1.5 text-slate-400 hover:text-rose-400 bg-slate-900 hover:bg-slate-800 border border-slate-800 rounded-lg transition-colors"
                    title="Clear Log History"
                  >
                    <Trash2 className="w-3.5 h-3.5" />
                  </button>
                )}

                <button
                  type="button"
                  onClick={() => setIsMaximized(!isMaximized)}
                  className="p-1.5 text-slate-400 hover:text-white bg-slate-900 hover:bg-slate-800 border border-slate-800 rounded-lg transition-colors"
                  title={isMaximized ? 'Restore view' : 'Maximize view'}
                >
                  {isMaximized ? <Minimize2 className="w-3.5 h-3.5" /> : <Maximize2 className="w-3.5 h-3.5" />}
                </button>
              </div>
            </div>

            {/* Current Active Task Banner (When in Transition) */}
            {isBusy && (
              <div className="p-3 bg-cyan-950/20 border-b border-cyan-500/20 flex flex-col sm:flex-row sm:items-center justify-between gap-2.5">
                <div className="flex items-center space-x-2.5 min-w-0">
                  <RefreshCw className="w-4 h-4 text-cyan-400 animate-spin shrink-0" />
                  <div className="min-w-0">
                    <div className="text-[11px] font-bold text-white flex items-center gap-2">
                      <span>{state === 'starting' ? 'Booting Dev Server' : 'Shutting Down Server'}</span>
                      <span className="text-cyan-400 font-mono text-[10px]">({progress}%)</span>
                    </div>
                    <div className="text-[10px] text-cyan-300/80 font-mono truncate">{currentTask || 'Executing task...'}</div>
                  </div>
                </div>

                <div className="w-full sm:w-48 bg-slate-900 rounded-full h-2 overflow-hidden border border-slate-800 shrink-0">
                  <div
                    className="h-full bg-gradient-to-r from-cyan-500 to-emerald-400 transition-all duration-300"
                    style={{ width: `${Math.max(5, progress)}%` }}
                  />
                </div>
              </div>
            )}

            {/* Content Area */}
            <div
              ref={actionListRef}
              className={`p-3.5 overflow-y-auto font-mono text-[11px] leading-relaxed space-y-2 ${
                isMaximized ? 'flex-1 max-h-none' : 'max-h-56 md:max-h-64'
              }`}
            >
              {activeTab === 'actions' ? (
                logs.length === 0 ? (
                  <div className="py-6 text-center text-slate-600 text-xs">
                    No actions logged yet. Press &quot;Start Dev&quot; to begin.
                  </div>
                ) : (
                  logs.map((log) => (
                    <div
                      key={log.id}
                      className="flex items-start space-x-2.5 p-2 rounded-xl bg-slate-900/40 border border-slate-900/80 hover:border-slate-800 transition-colors"
                    >
                      {getLevelIcon(log.level)}
                      <div className="flex-1 min-w-0">
                        <div className="flex items-center space-x-2 flex-wrap gap-y-1">
                          <span className="text-[9px] text-slate-500 font-mono flex items-center space-x-1">
                            <Clock className="w-2.5 h-2.5 inline" />
                            <span>{log.timestamp}</span>
                          </span>
                          {getLevelBadge(log.level)}
                          <span className="font-semibold text-slate-200">{log.task}</span>
                        </div>
                        {log.detail && (
                          <div className="text-[10px] text-slate-400 mt-1 pl-1 border-l-2 border-slate-800 break-words whitespace-pre-wrap">
                            {log.detail}
                          </div>
                        )}
                      </div>
                    </div>
                  ))
                )
              ) : (
                <div className="p-3 bg-black/60 rounded-xl border border-slate-900 text-slate-300 font-mono text-[10px] whitespace-pre-wrap break-all leading-tight">
                  {processLog.trim() || 'No raw terminal output captured for this process yet.'}
                  <div ref={terminalBottomRef} />
                </div>
              )}
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
};

/** @jsxImportSource react */
import React from 'react';
import { RefreshCw, Zap, Terminal } from 'lucide-react';
import type { DevDbMode, DevState } from './useDevMode';

export const DevControl = ({
  state,
  isDevActive,
  dbMode,
  onDbModeChange,
  onToggle,
}: {
  state: DevState;
  isDevActive: boolean;
  dbMode: DevDbMode;
  onDbModeChange: (mode: DevDbMode) => void;
  onToggle: () => void;
}) => {
  const busy = state === 'starting' || state === 'stopping';
  return (
    <div className="flex items-center gap-2 flex-wrap min-w-0">
      {!isDevActive && state !== 'starting' && (
        <select
          value={dbMode}
          onChange={(e) => onDbModeChange(e.target.value as DevDbMode)}
          className="bg-slate-950 border border-slate-800 text-[9px] font-mono text-slate-300 rounded-xl px-2 py-1.5 outline-none focus:border-blue-500 cursor-pointer min-w-0"
        >
          <option value="neon">Neon DB (Prod)</option>
          <option value="local">Local DB (Dev)</option>
        </select>
      )}
      <button
        onClick={onToggle}
        disabled={busy}
        className={`flex items-center gap-2 px-3 py-1.5 rounded-xl text-[9px] font-black uppercase tracking-widest transition-all disabled:opacity-50 min-w-0 ${
          isDevActive
            ? 'bg-emerald-500/20 text-emerald-400 hover:bg-emerald-500/30 border border-emerald-500/30'
            : 'bg-slate-800 text-slate-400 hover:text-white hover:bg-slate-700'
        }`}
      >
        {busy ? (
          <RefreshCw className="w-3 h-3 animate-spin" />
        ) : isDevActive ? (
          <Zap className="w-3 h-3" />
        ) : (
          <Terminal className="w-3 h-3" />
        )}
        <span className="truncate">
          {state === 'starting' ? 'Starting...' : state === 'stopping' ? 'Stopping...' : isDevActive ? 'Stop Dev' : 'Start Dev'}
        </span>
      </button>
    </div>
  );
};

/** @jsxImportSource react */
import React, { useState, useEffect, useRef } from 'react';
import { 
  X, 
  Globe, 
  Terminal, 
  Database, 
  Activity, 
  RefreshCw, 
  Copy, 
  Check, 
  Trash2, 
  Maximize2, 
  Minimize2, 
  ExternalLink,
  Zap,
  Clock,
  AlertTriangle,
  CheckCircle2,
  XCircle,
  Info
} from 'lucide-react';
import { DevProgressBar } from './DevProgressBar';
import type { DevServerStatus, DevTransition, DevState, DevActionLog, DevDbMode } from './useDevMode';

interface DevEnvironmentModalProps {
  projectId: string;
  projectName: string;
  domain: string;
  isDevActive: boolean;
  devInfo?: DevServerStatus;
  state: DevState;
  progress: number;
  transition?: DevTransition;
  currentTask?: string;
  actionLogs?: DevActionLog[];
  rawProcessLog?: string;
  dbSelection?: DevDbMode;
  onStop: (id: string) => void;
  onStart?: (id: string) => void;
  fetchLog: (id: string) => Promise<string>;
  onClearLogs?: (id: string) => void;
  onClose: () => void;
  alignLeft?: boolean;
}

const layerBadge = (value: string | undefined) =>
  value === 'online'
    ? 'bg-emerald-500/20 text-emerald-400 border border-emerald-500/30'
    : value === 'starting'
    ? 'bg-amber-500/20 text-amber-400 border border-amber-500/30 animate-pulse'
    : 'bg-slate-800 text-slate-500 border border-slate-700/50';

const getLevelBadge = (level: DevActionLog['level']) => {
  switch (level) {
    case 'success':
      return <span className="px-1.5 py-0.5 rounded text-[8px] font-black uppercase bg-emerald-500/20 text-emerald-400 border border-emerald-500/30">SUCCESS</span>;
    case 'step':
      return <span className="px-1.5 py-0.5 rounded text-[8px] font-black uppercase bg-cyan-500/20 text-cyan-400 border border-cyan-500/30">STEP</span>;
    case 'warn':
      return <span className="px-1.5 py-0.5 rounded text-[8px] font-black uppercase bg-amber-500/20 text-amber-400 border border-amber-500/30">WARN</span>;
    case 'error':
      return <span className="px-1.5 py-0.5 rounded text-[8px] font-black uppercase bg-rose-500/20 text-rose-400 border border-rose-500/30">ERROR</span>;
    default:
      return <span className="px-1.5 py-0.5 rounded text-[8px] font-black uppercase bg-slate-800 text-slate-400 border border-slate-700">INFO</span>;
  }
};

const getLevelIcon = (level: DevActionLog['level']) => {
  switch (level) {
    case 'success':
      return <CheckCircle2 className="w-3 h-3 text-emerald-400 shrink-0 mt-0.5" />;
    case 'step':
      return <Activity className="w-3 h-3 text-cyan-400 shrink-0 mt-0.5 animate-pulse" />;
    case 'warn':
      return <AlertTriangle className="w-3 h-3 text-amber-400 shrink-0 mt-0.5" />;
    case 'error':
      return <XCircle className="w-3 h-3 text-rose-400 shrink-0 mt-0.5" />;
    default:
      return <Info className="w-3 h-3 text-slate-400 shrink-0 mt-0.5" />;
  }
};

export const DevEnvironmentModal: React.FC<DevEnvironmentModalProps> = ({
  projectId,
  projectName,
  domain,
  isDevActive,
  devInfo,
  state,
  progress,
  transition,
  currentTask,
  actionLogs = [],
  rawProcessLog = '',
  dbSelection,
  onStop,
  onStart,
  fetchLog,
  onClearLogs,
  onClose,
  alignLeft = false,
}) => {
  const [activeTab, setActiveTab] = useState<'layers' | 'actions' | 'terminal'>('layers');
  const [liveLog, setLiveLog] = useState(rawProcessLog);
  const [copied, setCopied] = useState(false);
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [isMaximized, setIsMaximized] = useState(false);
  const terminalBottomRef = useRef<HTMLDivElement>(null);
  const actionListRef = useRef<HTMLDivElement>(null);

  // Dynamic real-time log stream polling while modal is open
  useEffect(() => {
    let isMounted = true;
    const pollInterval = setInterval(async () => {
      try {
        const text = await fetchLog(projectId);
        if (isMounted) setLiveLog(text);
      } catch (e) {
        // silent error during dynamic poll
      }
    }, 1500);

    return () => {
      isMounted = false;
      clearInterval(pollInterval);
    };
  }, [projectId, fetchLog]);

  useEffect(() => {
    if (activeTab === 'terminal' && terminalBottomRef.current) {
      terminalBottomRef.current.scrollIntoView({ behavior: 'smooth' });
    }
  }, [liveLog, activeTab]);

  useEffect(() => {
    if (activeTab === 'actions' && actionListRef.current) {
      actionListRef.current.scrollTop = actionListRef.current.scrollHeight;
    }
  }, [actionLogs, activeTab]);

  const handleCopy = () => {
    const text = activeTab === 'actions'
      ? actionLogs.map(l => `[${l.timestamp}] [${l.level.toUpperCase()}] ${l.task}${l.detail ? ` - ${l.detail}` : ''}`).join('\n')
      : liveLog;
    navigator.clipboard.writeText(text);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleRefresh = async () => {
    setIsRefreshing(true);
    try {
      const text = await fetchLog(projectId);
      setLiveLog(text);
    } finally {
      setIsRefreshing(false);
    }
  };

  const layerStatus = (key: 'frontend' | 'api') => devInfo?.layers?.[key] || 'offline';
  const isBusy = state === 'starting' || state === 'stopping';

  return (
    <div
      className={`absolute mt-2 w-96 max-w-[calc(100vw-1.5rem)] bg-slate-950 border border-slate-700/80 rounded-2xl p-4 shadow-2xl z-50 text-left font-sans space-y-4 backdrop-blur-xl ${
        isMaximized 
          ? 'fixed inset-4 z-[999] w-auto max-w-none m-0 flex flex-col justify-between overflow-hidden bg-slate-950/98' 
          : alignLeft ? 'left-0' : 'right-0'
      }`}
      onClick={(e) => e.stopPropagation()}
    >
      {/* Top Header Bar */}
      <div className="flex items-center justify-between border-b border-slate-800/80 pb-3">
        <div className="flex items-center space-x-2 min-w-0">
          <span className={`w-2.5 h-2.5 rounded-full shrink-0 ${isDevActive ? 'bg-emerald-400 animate-pulse' : 'bg-slate-600'}`} />
          <div className="min-w-0">
            <h4 className="text-xs font-black uppercase tracking-wider text-white truncate">{projectName} Dev Environment</h4>
            <p className="text-[9px] font-mono text-slate-500 truncate">{domain}</p>
          </div>
        </div>

        <div className="flex items-center space-x-1.5 shrink-0">
          <button
            type="button"
            onClick={() => setIsMaximized(!isMaximized)}
            className="p-1 text-slate-400 hover:text-white bg-slate-900/60 hover:bg-slate-800 rounded-lg transition-colors"
            title={isMaximized ? "Minimize" : "Maximize"}
          >
            {isMaximized ? <Minimize2 className="w-3.5 h-3.5" /> : <Maximize2 className="w-3.5 h-3.5" />}
          </button>
          <button 
            type="button"
            onClick={onClose} 
            className="p-1 text-slate-400 hover:text-white bg-slate-900/60 hover:bg-slate-800 rounded-lg transition-colors"
          >
            <X className="w-3.5 h-3.5" />
          </button>
        </div>
      </div>

      {/* Live Transition Banner */}
      {isBusy && (
        <div className="p-3 bg-cyan-950/30 border border-cyan-500/30 rounded-xl space-y-2">
          <div className="flex items-center justify-between text-xs">
            <div className="flex items-center gap-2">
              <RefreshCw className="w-3.5 h-3.5 text-cyan-400 animate-spin" />
              <span className="font-bold text-white text-[11px]">
                {state === 'starting' ? 'Starting Server...' : 'Stopping Server...'}
              </span>
            </div>
            <span className="text-[10px] font-mono font-bold text-cyan-400">{progress}%</span>
          </div>

          <DevProgressBar percent={progress} mode={transition === 'stop' ? 'stop' : 'start'} />

          {currentTask && (
            <div className="text-[9px] font-mono text-cyan-300 bg-cyan-950/60 px-2.5 py-1 rounded border border-cyan-500/20 truncate">
              <span className="text-cyan-500 font-bold mr-1">STEP:</span>{currentTask}
            </div>
          )}
        </div>
      )}

      {/* Sub-Tabs */}
      <div className="flex items-center justify-between bg-slate-900/80 p-1 rounded-xl border border-slate-800 text-[10px] font-bold">
        <button
          type="button"
          onClick={() => setActiveTab('layers')}
          className={`flex-1 py-1.5 rounded-lg transition-all text-center uppercase tracking-wider ${
            activeTab === 'layers' ? 'bg-slate-800 text-cyan-400 shadow-sm' : 'text-slate-500 hover:text-slate-300'
          }`}
        >
          Layers & Ports
        </button>
        <button
          type="button"
          onClick={() => setActiveTab('actions')}
          className={`flex-1 py-1.5 rounded-lg transition-all text-center uppercase tracking-wider ${
            activeTab === 'actions' ? 'bg-slate-800 text-cyan-400 shadow-sm' : 'text-slate-500 hover:text-slate-300'
          }`}
        >
          Actions ({actionLogs.length})
        </button>
        <button
          type="button"
          onClick={() => setActiveTab('terminal')}
          className={`flex-1 py-1.5 rounded-lg transition-all text-center uppercase tracking-wider ${
            activeTab === 'terminal' ? 'bg-slate-800 text-cyan-400 shadow-sm' : 'text-slate-500 hover:text-slate-300'
          }`}
        >
          Terminal
        </button>
      </div>

      {/* TAB CONTENT */}
      <div className={isMaximized ? 'flex-1 overflow-y-auto space-y-4 pr-1' : 'space-y-3'}>
