import { useEffect, useRef, useState, useCallback } from 'react';
import { useToast } from '../../common';

export type DevDbMode = 'neon' | 'local';
export type DevTransition = 'start' | 'stop';
export type DevState = 'idle' | 'starting' | 'stopping' | 'running' | 'failed';

export interface DevLayerStatus {
  frontend: 'online' | 'starting' | 'offline';
  api: 'online' | 'starting' | 'offline';
  database: 'connected' | 'offline';
}

export interface DevActionLog {
  id: string;
  timestamp: string;
  level: 'info' | 'step' | 'success' | 'warn' | 'error';
  task: string;
  detail?: string;
}

export interface DevServerStatus {
  running: boolean;
  managed: boolean;
  startedAt: string | null;
  uptime: number;
  dbMode: DevDbMode;
  port: number | null;
  url: string | null;
  database: string;
  layers: DevLayerStatus;
  lastExit: { code: number | null; signal: string | null; at: number } | null;
}

const FAST_POLL_MS = 1200;
const SLOW_POLL_MS = 12000;
const TRANSITION_TIMEOUT_MS = 45000;

export function useDevMode() {
  const { addToast } = useToast();
  const [devServers, setDevServers] = useState<Record<string, DevServerStatus>>({});
  const [allowInProd, setAllowInProd] = useState(false);
  const [transitions, setTransitions] = useState<Record<string, DevTransition>>({});
  const [transitionSince, setTransitionSince] = useState<Record<string, number>>({});
  const [dbSelection, setDbSelection] = useState<Record<string, DevDbMode>>({});

  // Real-time task and action logs
  const [currentTasks, setCurrentTasks] = useState<Record<string, string>>({});
  const [actionLogs, setActionLogs] = useState<Record<string, DevActionLog[]>>({});
  const [rawProcessLogs, setRawProcessLogs] = useState<Record<string, string>>({});
  const [openConsoles, setOpenConsoles] = useState<Record<string, boolean>>({});

  const allowInProdRef = useRef(false);
  allowInProdRef.current = allowInProd;
  const transitionsRef = useRef(transitions);
  transitionsRef.current = transitions;
  const transitionSinceRef = useRef(transitionSince);
  transitionSinceRef.current = transitionSince;

  const appendLog = useCallback((id: string, level: DevActionLog['level'], task: string, detail?: string) => {
    const timeStr = new Date().toLocaleTimeString('en-US', { hour12: false, hour: '2-digit', minute: '2-digit', second: '2-digit' });
    const logItem: DevActionLog = {
      id: `${Date.now()}-${Math.random().toString(36).substr(2, 6)}`,
      timestamp: timeStr,
      level,
      task,
      detail,
    };
    setActionLogs((prev) => {
      const existing = prev[id] || [];
      return { ...prev, [id]: [...existing.slice(-99), logItem] };
    });
  }, []);

  const clearLogs = useCallback((id: string) => {
    setActionLogs((prev) => ({ ...prev, [id]: [] }));
  }, []);

  const toggleConsole = useCallback((id: string) => {
    setOpenConsoles((prev) => ({ ...prev, [id]: !prev[id] }));
  }, []);

  const finishTransition = useCallback((id: string) => {
    setTransitions((prev) => {
      const next = { ...prev };
      delete next[id];
      return next;
    });
    setTransitionSince((prev) => {
      const next = { ...prev };
      delete next[id];
      return next;
    });
  }, []);

  const failTransition = useCallback((id: string, message: string) => {
    appendLog(id, 'error', 'Transition Failed', message);
    setCurrentTasks((prev) => ({ ...prev, [id]: `Error: ${message}` }));
    addToast(message, 'error');
    if (typeof window !== 'undefined') {
      window.dispatchEvent(new CustomEvent('foundation-api-mutate', { detail: { type: 'dev_state_changed', id, status: 'failed', error: message } }));
      window.dispatchEvent(new CustomEvent('foundation:notification', { 
        detail: {
          title: `Dev Server Failed: ${id}`,
          message,
          type: 'error',
          timestamp: new Date().toISOString()
        }
      }));
    }
    finishTransition(id);
  }, [addToast, appendLog, finishTransition]);

  const poll = useCallback(async () => {
    try {
      const res = await fetch('/admin/projects/dev/status');
      const data: any = await res.json();
      if (data.allowInProd) setAllowInProd(true);
      if (data.success) setDevServers(data.running || {});
      return data;
    } catch {
      return null;
    }
  }, []);

  const fetchLog = useCallback(async (id: string): Promise<string> => {
    try {
      const res = await fetch(`/admin/projects/dev/log?id=${encodeURIComponent(id)}`);
      const data: any = await res.json();
      const logText = data.log || '';
      setRawProcessLogs((prev) => ({ ...prev, [id]: logText }));
      return logText;
    } catch {
      return '';
    }
  }, []);

  const start = useCallback(async (id: string, chosenDbMode?: DevDbMode) => {
    const dbMode = chosenDbMode || dbSelection[id] || 'neon';
    setTransitions((prev) => ({ ...prev, [id]: 'start' }));
    setTransitionSince((prev) => ({ ...prev, [id]: Date.now() }));
    setOpenConsoles((prev) => ({ ...prev, [id]: true })); // Auto-open console for instant feedback
    setCurrentTasks((prev) => ({ ...prev, [id]: `Preparing environment for ${id} (${dbMode} DB)...` }));

    appendLog(id, 'info', 'Initiating Dev Server', `Target DB: ${dbMode === 'neon' ? 'Neon Production DB' : 'Local Dev PostgreSQL'}`);
    appendLog(id, 'step', 'Dispatching API Request', 'Sending POST /admin/projects/dev/start...');

    try {
      const res = await fetch('/admin/projects/dev/start', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ id, dbMode }),
      });
      const data: any = await res.json();
      if (data.success) {
        if (allowInProdRef.current) {
          appendLog(id, 'success', 'Dev Signal Sent', `Production signal active on port ${data.port}`);
          setCurrentTasks((prev) => ({ ...prev, [id]: `Dev mode signal active on port ${data.port}` }));
          addToast(`Dev signal sent for ${id} on port ${data.port}.`, 'info');
          setTimeout(() => finishTransition(id), 2000);
        } else {
          appendLog(id, 'step', 'Process Spawned', `Detached process launched on port ${data.port}. Streaming logs to ${data.logFile || 'disk'}`);
          setCurrentTasks((prev) => ({ ...prev, [id]: `Probing runtime layers on http://localhost:${data.port}...` }));
          addToast(`Dev server starting for ${id} on port ${data.port}`, 'success');
          poll();
          fetchLog(id);
        }
      } else {
        failTransition(id, data.error || 'Failed to start dev server');
      }
    } catch (err: any) {
      failTransition(id, `Network Error: ${err.message}`);
    }
  }, [addToast, appendLog, dbSelection, finishTransition, failTransition, fetchLog, poll]);

  const stop = useCallback(async (id: string) => {
    setTransitions((prev) => ({ ...prev, [id]: 'stop' }));
    setTransitionSince((prev) => ({ ...prev, [id]: Date.now() }));
    setOpenConsoles((prev) => ({ ...prev, [id]: true })); // Auto-open console
    setCurrentTasks((prev) => ({ ...prev, [id]: `Sending SIGTERM stop signal to ${id}...` }));

    appendLog(id, 'info', 'Stopping Dev Server', 'Dispatching POST /admin/projects/dev/stop...');
    try {
      const res = await fetch('/admin/projects/dev/stop', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ id }),
      });
      const data: any = await res.json();
      if (data.success) {
        appendLog(id, 'step', 'Process Termination Dispatched', 'Waiting for process group cleanup...');
        addToast(`Stopping dev server for ${id}...`, 'info');
        poll();
      } else {
        failTransition(id, data.error || 'Failed to stop dev server');
      }
    } catch (err: any) {
      failTransition(id, `Network Error: ${err.message}`);
    }
  }, [addToast, appendLog, failTransition, finishTransition, poll]);

  // Slow global poll
  useEffect(() => {
    poll();
    const interval = setInterval(poll, SLOW_POLL_MS);
    return () => clearInterval(interval);
  }, [poll]);

  // Fast poll while any transition is in-flight, with timeout detection
  useEffect(() => {
    const active = Object.keys(transitions).length > 0;
    if (!active) return;

    const tick = async () => {
      const data = await poll();
      const running: Record<string, DevServerStatus> = data?.running || {};

      // In prod (allowInProd), start is a signal
      if (data?.allowInProd) {
        Object.keys(transitionsRef.current).forEach((id) => {
          if (transitionsRef.current[id] === 'start') {
            appendLog(id, 'success', 'Dev Mode Enabled', 'Running in production override mode.');
            addToast('Dev mode enabled in production.', 'success');
            finishTransition(id);
          }
        });
        return;
      }

      Object.entries(transitionsRef.current).forEach(([id, type]) => {
        const since = transitionSinceRef.current[id] || 0;
        const timedOut = Date.now() - since > TRANSITION_TIMEOUT_MS;
        const status = running[id];

        // Layer inspection
        const layers = status?.layers;
        const frontendOnline = layers?.frontend === 'online';
        const apiOnline = layers?.api === 'online';
        const dbConnected = layers?.database === 'connected';

        const layersUp = !!(frontendOnline || apiOnline);
        const ready = status?.running ? (layersUp || (status.uptime ?? 0) >= 6) : false;

        if (type === 'start') {
          // Update live task indicator
          if (status?.running) {
            const activeLayers = [
              frontendOnline ? 'Frontend ✓' : 'Frontend...',
              apiOnline ? 'API ✓' : 'API...',
              dbConnected ? 'Database ✓' : 'Database...'
            ].join(' | ');
            setCurrentTasks((prev) => ({ ...prev, [id]: `Verifying layers (${activeLayers})` }));
            fetchLog(id);
          }

          if (ready) {
            appendLog(
              id,
              'success',
              'Dev Server Ready',
              `Active on http://localhost:${status.port || 'default'} (Frontend: ${layers?.frontend || 'online'}, API: ${layers?.api || 'online'})`
            );
            setCurrentTasks((prev) => ({ ...prev, [id]: `Active on http://localhost:${status.port || 'default'}` }));
            addToast(`${id} dev server is ready.`, 'success');
            if (typeof window !== 'undefined') {
              window.dispatchEvent(new CustomEvent('foundation-api-mutate', { detail: { type: 'dev_state_changed', id, status: 'running', port: status.port } }));
              window.dispatchEvent(new CustomEvent('foundation:notification', {
                detail: {
                  title: `Dev Server Ready: ${id}`,
                  message: `Dev server is running on http://localhost:${status.port || 'default'}`,
                  type: 'success',
                  timestamp: new Date().toISOString()
                }
              }));
            }
            finishTransition(id);
            fetchLog(id);
          } else if (timedOut) {
            failTransition(
              id,
              status?.lastExit
                ? `Dev server for ${id} failed (exit ${status.lastExit.code ?? status.lastExit.signal}). Check the terminal log.`
                : `Timed out waiting for dev server ${id} to respond.`
            );
          }
        } else if (type === 'stop') {
          if (status && !status.running) {
            appendLog(id, 'success', 'Dev Server Stopped', 'Process terminated and port released.');
            setCurrentTasks((prev) => ({ ...prev, [id]: 'Dev server stopped.' }));
            addToast(`${id} dev server stopped.`, 'success');
            if (typeof window !== 'undefined') {
              window.dispatchEvent(new CustomEvent('foundation-api-mutate', { detail: { type: 'dev_state_changed', id, status: 'stopped' } }));
              window.dispatchEvent(new CustomEvent('foundation:notification', {
                detail: {
                  title: `Dev Server Stopped: ${id}`,
                  message: `Dev server process terminated and port released.`,
                  type: 'info',
                  timestamp: new Date().toISOString()
                }
              }));
            }
            finishTransition(id);
            fetchLog(id);
          } else if (timedOut) {
            failTransition(id, `Timed out stopping dev server for ${id}.`);
          }
        }
      });
    };

    tick();
    const interval = setInterval(tick, FAST_POLL_MS);
    return () => clearInterval(interval);
  }, [transitions, addToast, appendLog, finishTransition, failTransition, fetchLog, poll]);

  const isTransitioning = (id: string) => !!transitions[id];
  const transitionType = (id: string): DevTransition | undefined => transitions[id];

  const progressFor = (id: string): number => {
    const t = transitions[id];
    if (t === 'start') {
      const layers = devServers[id]?.layers;
      if (!layers) return 30;
      const online =
        (layers.frontend === 'online' ? 1 : 0) +
        (layers.api === 'online' ? 1 : 0) +
        (layers.database === 'connected' ? 1 : 0);
      return Math.min(95, 30 + Math.round((online / 3) * 65));
    }
    if (t === 'stop') {
      return 60;
    }
    const status = devServers[id];
    if (status?.running) return 100;
    return 0;
  };

  const stateFor = (id: string): DevState => {
    const t = transitions[id];
    if (t === 'start') return 'starting';
    if (t === 'stop') return 'stopping';
    const status = devServers[id];
    if (status?.lastExit && !status.running) return 'failed';
    if (status?.running) return 'running';
    return 'idle';
  };

  return {
    devServers,
    allowInProd,
    transitions,
    dbSelection,
    setDbSelection,
    actionLogs,
    rawProcessLogs,
    currentTasks,
    openConsoles,
    toggleConsole,
    clearLogs,
    start,
    stop,
    poll,
    fetchLog,
    isTransitioning,
    transitionType,
    progressFor,
    stateFor,
  };
}

