              <X className="w-4 h-4" />
            </button>
          )}
        </div>

        {/* Row 2: Dedicated Scrollable Topic Tabs with Navigation Arrows & Edge Gradients */}
        <div className="relative flex items-center pt-1 border-t border-white/5">
          {/* Scroll Left Button */}
          {canScrollLeft && (
            <button
