interface SubRule {
  title: string;
  body: string;
}

interface RuleSection {
  id: string;
  num?: string;
  title: string;
  body: string;
  subsections: SubRule[];
}

const MARKDOWN_CLEANUP: Array<[RegExp, string]> = [
  [/^#+\s*/gm, ''],
  [/^[-*]\s+/gm, '• '],
  [/\*\*(.*?)\*\*/g, '$1'],
  [/`([^`]*)`/g, '$1'],
  [/\*\*/g, ''],
  [/^>\s*/gm, ''],
];

function cleanMarkdown(text: string): string {
  let out = text.replace(/\r\n/g, '\n');
  for (const [re, repl] of MARKDOWN_CLEANUP) {
    out = out.replace(re, repl as any);
  }
  return out;
}

function slug(s: string): string {
  return s.toLowerCase().replace(/[^\w]+/g, '-').replace(/^-+|-+$/g, '');
}

function parseRules(raw: string): { title: string; sections: RuleSection[] } {
  const lines = raw.split('\n');
  const title = lines[0]?.replace(/^\s*#\s*/, '').trim() || 'Global Laws & Standards';

  const sections: RuleSection[] = [];
  let current: RuleSection | null = null;
  let currentSub: SubRule | null = null;

  const flushSub = () => {
    if (current && currentSub && currentSub.body.trim()) current.subsections.push(currentSub);
    currentSub = null;
  };
  const flushSection = () => {
    flushSub();
    if (current) sections.push(current);
    current = null;
  };

  for (const rawLine of lines) {
    const line = rawLine.trim();
    if (!line) continue;

    // Section heading ## N. Title
    const h2 = line.match(/^##\s+(.+)$/);
    if (h2) {
      flushSection();
      const text = h2[1].trim();
      const numMatch = text.match(/^(\d+)\.?\s+(.*)$/);
      current = {
        id: slug(numMatch ? `${numMatch[1]}-${numMatch[2]}` : text),
        num: numMatch ? numMatch[1] : undefined,
        title: numMatch ? numMatch[2] : text,
        body: '',
        subsections: [],
      };
      continue;
    }

    // h3 ### Sub
    const h3 = line.match(/^###\s+(.+)$/);
    if (h3) {
      flushSub();
      if (current) currentSub = { title: h3[1].trim(), body: '' };
      continue;
    }

    if (currentSub) currentSub.body += line + '\n';
    else if (current) current.body += line + '\n';
  }

  flushSection();
  return { title, sections };
}

