            <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-600 group-hover:text-blue-500 transition-colors" />
            <input
              type="text"
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              placeholder="Search rules..."
              className="bg-slate-900/60 border border-slate-900 focus:border-blue-500/50 outline-none pl-12 pr-6 py-3.5 rounded-2xl w-full text-sm font-medium transition-all"
            />
          </div>
        </div>
      </div>

      <div className="space-y-4 scrollable-list max-h-[70vh] overflow-y-auto pr-2">
        <AnimatePresence initial={false}>
          {filtered.length > 0 ? (
            filtered.map((section) => {
              const open = isOpen(section.id);
              return (
                <motion.div
                  key={section.id}
                  layout
                  initial={{ opacity: 0, y: 10 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0, y: -10 }}
                  className="bg-slate-900/40 border border-slate-900 hover:border-blue-500/25 rounded-2xl overflow-hidden transition-colors"
                >
                  <button onClick={() => toggle(section.id)} className="w-full flex items-center justify-between gap-4 p-5 text-left">
                    <div className="flex items-center gap-4 min-w-0">
                      <div className="flex-shrink-0 w-12 h-12 bg-slate-950 rounded-xl border border-slate-900 flex items-center justify-center">
                        {section.num ? (
                          <span className="font-mono text-lg font-black text-blue-400">{section.num}</span>
                        ) : (
                          <Hash className="w-4 h-4 text-slate-600" />
                        )}
                      </div>
                      <div className="min-w-0">
                        <h3 className="text-base font-black text-white tracking-tight truncate">
                          {section.title || 'Untitled Rule'}
                        </h3>
                        <p className="text-[10px] font-black uppercase tracking-widest text-slate-600 mt-0.5">
                          Rule {section.num || '—'}
                          {section.subsections.length > 0 ? ` · ${section.subsections.length} sub-rules` : ''}
                        </p>
                      </div>
                    </div>
                    <ChevronDown className={`w-5 h-5 flex-shrink-0 text-slate-600 transition-transform ${open ? 'rotate-180' : ''}`} />
                  </button>
                  <AnimatePresence initial={false}>
                    {open && (
                      <motion.div
                        initial={{ height: 0, opacity: 0 }}
                        animate={{ height: 'auto', opacity: 1 }}
                        exit={{ height: 0, opacity: 0 }}
                        transition={{ duration: 0.2 }}
                        className="overflow-hidden"
                      >
                        <div className="px-6 pb-6 pt-5 space-y-4 border-t border-white/5">
                          {section.body.trim() && (
                            <div className="text-sm text-slate-400 leading-relaxed whitespace-pre-wrap">
                              {cleanMarkdown(section.body)}
                            </div>
                          )}
                          {section.subsections.length > 0 && (
                            <div className="space-y-3">
                              {section.subsections.map((sub) => (
                                <div key={slug(sub.title)} className="p-4 bg-slate-900/40 rounded-xl border border-white/5">
                                  <h4 className="text-xs font-black text-cyan-400 uppercase tracking-widest mb-2">{sub.title}</h4>
                                  <p className="text-[13px] text-slate-400 leading-relaxed whitespace-pre-wrap">{cleanMarkdown(sub.body)}</p>
                                </div>
                              ))}
                            </div>
                          )}
                        </div>
                      </motion.div>
                    )}
                  </AnimatePresence>
                </motion.div>
              );
            })
          ) : (
            <div className="py-20 bg-slate-900/20 rounded-3xl border border-dashed border-slate-800 flex flex-col items-center justify-center space-y-3">
              <Search className="w-12 h-12 text-slate-800" />
              <p className="text-slate-500 font-bold">No rules match "{search}"</p>
            </div>
          )}
        </AnimatePresence>
      </div>
    </div>
  );
};

