interface ErrorDetailModalProps {
  isOpen: boolean;
  onClose: () => void;
  log: any;
  details: any;
  onCopy: () => void;
}

export function ErrorDetailModal({ isOpen, onClose, log, details, onCopy }: ErrorDetailModalProps) {
  const { addToast } = useToast();

  const getEventCategory = (eventKey: string): string => {
    const availableEvents = [
      { key: 'stack.create', label: 'Stack Created', category: 'Portainer' },
      { key: 'stack.update', label: 'Stack Updated', category: 'Portainer' },
      { key: 'stack.redeploy', label: 'Stack Redeployed', category: 'Portainer' },
      { key: 'stack.error', label: 'Stack Error / Outage', category: 'Portainer' },
      { key: 'stack.delete', label: 'Stack Deleted', category: 'Portainer' },
      { key: 'user.created', label: 'New User Onboarded', category: 'Users' },
      { key: 'auth.login_failed', label: 'Failed Login Attempt', category: 'Security' },
      { key: 'auth.role_change', label: 'Role / Permission Escalation', category: 'Security' },
      { key: 'scrape.completed', label: 'Wrestler Scrape Completed', category: 'Scraper' },
      { key: 'test.alert', label: 'Test Alert Event', category: 'Testing' }
    ];
    const event = availableEvents.find(e => e.key === log.eventKey);
    return event?.category || 'Other';
  };

  if (!isOpen) return null;

  const status = log.status;
  const statusColor = status === 'delivered' ? 'bg-emerald-500/10 text-emerald-400 border border-emerald-500/20' :
    status === 'skipped' ? 'bg-amber-500/10 text-amber-400 border border-amber-500/20' :
    'bg-rose-500/10 text-rose-400 border border-rose-500/20';

  return (
    <AnimatePresence>
      {isOpen && (
        <div className="fixed inset-0 bg-black/85 backdrop-blur-md flex items-center justify-center p-4 z-[1100] animate-in fade-in duration-200" onClick={onClose}>
          <motion.div
            initial={{ scale: 0.95, opacity: 0 }}
            animate={{ scale: 1, opacity: 1 }}
            exit={{ scale: 0.95, opacity: 0 }}
            className="bg-slate-900 border border-white/10 rounded-3xl w-full max-w-2xl max-h-[80vh] flex flex-col p-6 shadow-2xl relative overflow-hidden"
            onClick={(e) => e.stopPropagation()}
          >
            <div className="flex items-center justify-between pb-4 border-b border-white/5 shrink-0">
              <div className="flex items-center gap-3">
                <div className="p-2.5 bg-rose-500/10 rounded-xl border border-rose-500/20 text-rose-400">
                  <AlertCircle className="w-5 h-5" />
                </div>
                <div>
                  <h3 className="text-base font-bold text-white">Error Details</h3>
                  <p className="text-xs text-slate-400">{log.eventKey} • {log.channelType}</p>
                </div>
              </div>
              <button
                type="button"
                onClick={onClose}
                className="text-slate-400 hover:text-white p-1 rounded-lg hover:bg-white/5 transition-colors"
              >
                <X className="w-4 h-4" />
              </button>
            </div>

            <div className="flex-1 overflow-y-auto custom-scrollbar py-6 space-y-6">
              <div className="space-y-4">
                <div>
                  <label className="block text-xs font-bold text-slate-300 uppercase tracking-wider mb-2">Status</label>
                  <span className={`inline-flex items-center px-3 py-1.5 rounded-xl text-xs font-bold capitalize ${statusColor}`}>
                    {status}
                  </span>
                </div>

                <div>
                  <label className="block text-xs font-bold text-slate-300 uppercase tracking-wider mb-2">Event</label>
                  <p className="text-xs font-mono text-white bg-slate-950 px-3 py-2 rounded-xl border border-white/5">{log.eventKey}</p>
                </div>

                <div>
                  <label className="block text-xs font-bold text-slate-300 uppercase tracking-wider mb-2">Category</label>
                  <p className="text-xs text-white bg-slate-950 px-3 py-2 rounded-xl border border-white/5">Portainer</p>
                </div>

                <div>
                  <label className="block text-xs font-bold text-slate-300 uppercase tracking-wider mb-2">Channel</label>
                  <p className="text-xs font-mono text-white bg-slate-950 px-3 py-2 rounded-xl border border-white/5">{log.channelType}</p>
                </div>

                <div>
                  <label className="block text-xs font-bold text-slate-300 uppercase tracking-wider mb-2">Dispatched At</label>
                  <p className="text-xs text-white bg-slate-950 px-3 py-2 rounded-xl border border-white/5">
                    {new Date(log.dispatchedAt).toLocaleString()}
                  </p>
                </div>

                {log.errorMessage && (
                  <div className="border-t border-white/5 pt-4">
                    <label className="block text-xs font-bold text-slate-300 uppercase tracking-wider mb-2">Error Message</label>
                    <div className="bg-rose-500/10 border border-rose-500/20 rounded-xl p-4">
                      <p className="text-xs text-rose-300 whitespace-pre-wrap font-mono text-left">{log.errorMessage}</p>
                    </div>
                  </div>
                )}

                {log.skipReason && (
                  <div className="border-t border-white/5 pt-4">
                    <label className="block text-xs font-bold text-slate-300 uppercase tracking-wider mb-2">Skip Reason</label>
                    <div className="bg-amber-500/10 border border-amber-500/20 rounded-xl p-4">
                      <p className="text-xs text-amber-300 whitespace-pre-wrap font-mono text-left">{log.skipReason}</p>
                    </div>
                  </div>
                )}

                <div className="border-t border-white/5 pt-4">
                  <label className="block text-xs font-bold text-slate-300 uppercase tracking-wider mb-2">Raw Log Data</label>
                  <div className="bg-slate-950 border border-white/5 rounded-xl p-4 relative">
                    <pre className="text-[10px] text-slate-300 font-mono whitespace-pre-wrap overflow-x-auto max-h-48 overflow-y-auto">
                      {JSON.stringify(details, null, 2)}
                    </pre>
                    <button
                      onClick={() => {
                        navigator.clipboard.writeText(JSON.stringify(details, null, 2));
                        // Toast would need to be passed in or handled differently
                      }}
                      className="absolute top-2 right-2 p-1.5 text-slate-400 hover:text-white bg-white/5 rounded-lg transition-colors"
                      title="Copy to clipboard"
                    >
                      <FileText className="w-4 h-4" />
                    </button>
                  </div>
                </div>
              </div>
            </div>

            <div className="mt-6 pt-4 border-t border-white/5 flex justify-end gap-2">
              <button
                onClick={() => {
                  navigator.clipboard.writeText(JSON.stringify(details, null, 2));
                  // Toast notification would need context
                }}
                className="px-4 py-2 bg-slate-800 hover:bg-slate-700 text-slate-300 hover:text-white text-xs font-bold rounded-xl transition-all flex items-center gap-2 cursor-pointer"
              >
                <FileText className="w-3.5 h-3.5" />
                <span>Copy All Details</span>
              </button>
              <button
                onClick={onClose}
                className="px-4 py-2 bg-cyan-600 hover:bg-cyan-500 text-white text-xs font-bold rounded-xl transition-all cursor-pointer"
              >
                Close
              </button>
            </div>
          </motion.div>
        </div>
      )}
    </AnimatePresence>
  );
}

