}

const parseItem = (itemJson?: string): any => {
  if (!itemJson) return null;
  try {
    return JSON.parse(itemJson);
  } catch {
    return null;
  }
};

const parseDiffs = (diffsJson?: string): Array<{ field: string; oldValue: any; newValue: any }> => {
  if (diffsJson) {
    try {
      return JSON.parse(diffsJson);
    } catch {
      return [];
    }
  }
  return [];
};

