  const [saving, setSaving] = useState(false);

  useEffect(() => {
    if (isOpen) {
      setLoading(true);
      fetch('/api/admin/portainer/settings')
        .then(res => res.json() as Promise<{ success: boolean; data?: any }>)
        .then(json => {
          if (json.success && json.data) {
            setSettings(json.data);
          }
        })
        .catch(err => console.error('Failed to load settings:', err))
        .finally(() => setLoading(false));
    }
  }, [isOpen]);

  const handleSave = async () => {
    setSaving(true);
    try {
      const res = await fetch('/api/admin/portainer/settings', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(settings),
      });
      const json = await res.json() as { success: boolean; error?: string };
      if (json.success) {
        addToast({ title: 'Settings Saved', message: 'Auto-scan & notification preferences updated.', type: 'success' });
        onClose();
      } else {
        addToast({ title: 'Save Failed', message: json.error, type: 'error' });
      }
    } catch (err: any) {
      addToast({ title: 'Save Failed', message: err.message, type: 'error' });
    } finally {
      setSaving(false);
    }
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/80 backdrop-blur-md">
      <motion.div
        initial={{ opacity: 0, scale: 0.96 }}
