      const month = d.getMonth() + 1;
      const expr = `${m} ${h} ${day} ${month} *`;
      setCronExpression(expr);
      setCronLabel(`One-Time: ${dateStr} at ${timeDisplay}`);
    } else if (preset === 'daily') {
      const expr = `${m} ${h} * * *`;
      setCronExpression(expr);
      setCronLabel(`Daily at ${timeDisplay}`);
    } else if (preset === 'weekly') {
      const expr = `${m} ${h} * * ${dayOfWeekStr}`;
      const dayNames = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
      const dayName = dayNames[parseInt(dayOfWeekStr, 10)] || 'Sunday';
      setCronExpression(expr);
      setCronLabel(`Every ${dayName} at ${timeDisplay}`);
    } else if (preset === 'custom') {
      const expr = customCron || cronExpression;
      setCronExpression(expr);
      setCronLabel(`Custom Cron: ${expr}`);
