  Check, 
  ExternalLink, 
  Upload, 
  Globe, 
  CheckCircle2, 
  AlertTriangle,
  Folder,
  Bell,
  Send,
  Save,
  Code2,
  Plus,
  AlertCircle
} from 'lucide-react';
import { PortainerStackDetails, PortainerStackVolume } from '@shared/portainer/types';
