import { useBodyScrollLock } from '../../hooks/useBodyScrollLock';
import type { PortainerClient } from '@shared/portainer/client';

interface StackDetailsModalProps {
  stackId: number | null;
  endpointId?: number;
  isOpen: boolean;
  onClose: () => void;
  onRedeploy: (stackId: number) => Promise<void>;
  onAction: (stackId: number, action: 'start' | 'stop' | 'restart' | 'pause' | 'unpause') => Promise<void>;
  onEdit: (stackId: number) => void;
  onDelete: (stackId: number) => Promise<void>;
  onSaveIcon: (stackId: number, iconUrl: string) => Promise<void>;
}

export function StackDetailsModal({
  stackId,
  endpointId = 2,
  isOpen,
  onClose,
  onRedeploy,
  onAction,
  onEdit,
  onDelete,
  onSaveIcon,
}: StackDetailsModalProps) {
  const [details, setDetails] = useState<PortainerStackDetails | null>(null);
  const [loading, setLoading] = useState(false);
  const [activeTab, setActiveTab] = useState<'volumes' | 'networks' | 'env' | 'images' | 'branding' | 'discord' | 'raw'>('volumes');
  const [revealedKeys, setRevealedKeys] = useState<Record<string, boolean>>({});
  const [discordWebhookUrl, setDiscordWebhookUrl] = useState('');
  const [notifyOnDeploy, setNotifyOnDeploy] = useState(true);
  const [notifyOnLifecycle, setNotifyOnLifecycle] = useState(true);
  const [notifyOnError, setNotifyOnError] = useState(true);
  const [savingDiscord, setSavingDiscord] = useState(false);
  const [testingDiscord, setTestingDiscord] = useState(false);
  const [copiedKey, setCopiedKey] = useState<string | null>(null);
  const [customIconInput, setCustomIconInput] = useState('');
  const [actionLoading, setActionLoading] = useState<string | null>(null);
  const [confirmDelete, setConfirmDelete] = useState(false);

  // In-Modal Compose CRUD State
  const [isEditingCompose, setIsEditingCompose] = useState(false);
  const [composeText, setComposeText] = useState('');
  const [editingEnvVars, setEditingEnvVars] = useState<Array<{ name: string; value: string }>>([]);
  const [savingCompose, setSavingCompose] = useState(false);
  const [composeError, setComposeError] = useState<string | null>(null);
  const [composeSuccess, setComposeSuccess] = useState(false);

  const fetchDetails = async () => {
    if (!stackId) return;
    setLoading(true);
    setComposeError(null);
    try {
      const res = await fetch(`/api/admin/portainer/stacks/${stackId}/details?envId=${endpointId}`);
      const json = await res.json() as { success: boolean; data?: any };
      if (json.success && json.data) {
        setDetails(json.data);
        if (json.data.customIcon) {
          setCustomIconInput(json.data.customIcon);
        }
        if (json.data.composeFile) {
          setComposeText(json.data.composeFile);
        }
        if (json.data.env) {
          setEditingEnvVars(json.data.env.map((e: any) => ({ name: e.name, value: e.value })));
        }
      }
    } catch (err) {
      console.error('Failed to load stack details:', err);
    } finally {
      setLoading(false);
    }
  };

  const handleSaveComposeDirect = async () => {
    if (!stackId) return;
    setSavingCompose(true);
    setComposeError(null);
    try {
      const res = await fetch(`/api/admin/portainer/stacks/${stackId}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          endpointId,
          stackFileContent: composeText,
          env: editingEnvVars,
          prune: true,
        }),
      });
      const json = await res.json() as { success: boolean; error?: string };
      if (json.success) {
        setComposeSuccess(true);
        setIsEditingCompose(false);
        setTimeout(() => setComposeSuccess(false), 3500);
        await fetchDetails();
      } else {
        setComposeError(json.error || 'Failed to save compose manifest.');
      }
    } catch (err: any) {
      setComposeError(err.message);
    } finally {
      setSavingCompose(false);
    }
  };

  const fetchDiscordSettings = async () => {
    try {
      const res = await fetch('/api/admin/portainer/notifications/discord');
      const data = await res.json() as { success: boolean; data?: { webhookUrl?: string; notifyOnDeploy?: boolean; notifyOnLifecycle?: boolean; notifyOnError?: boolean } };
      if (data.success && data.data) {
        setDiscordWebhookUrl(data.data.webhookUrl || '');
        setNotifyOnDeploy(data.data.notifyOnDeploy ?? true);
        setNotifyOnLifecycle(data.data.notifyOnLifecycle ?? true);
        setNotifyOnError(data.data.notifyOnError ?? true);
      }
    } catch {
      // ignore
    }
  };

  const handleSaveDiscordInModal = async () => {
    setSavingDiscord(true);
    try {
      const res = await fetch('/api/admin/portainer/notifications/discord', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          enabled: true,
          webhookUrl: discordWebhookUrl,
          notifyOnDeploy,
          notifyOnLifecycle,
          notifyOnError,
        }),
      });
      const data = await res.json() as { success: boolean; error?: string };
      if (data.success) {
        alert('Discord notification settings saved successfully.');
      } else {
        alert(data.error || 'Failed to save settings.');
      }
    } catch (err: any) {
      alert(err.message || 'Save error');
    } finally {
      setSavingDiscord(false);
    }
  };

  const handleTestDiscordInModal = async () => {
    if (!discordWebhookUrl) {
      alert('Please enter a Discord Webhook URL to test.');
      return;
    }
    setTestingDiscord(true);
    try {
      const res = await fetch('/api/admin/portainer/notifications/discord/test', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          webhookUrl: discordWebhookUrl,
        }),
      });
      const data = await res.json() as { success: boolean; error?: string };
      if (data.success) {
        alert('Test notification successfully sent to your Discord channel!');
      } else {
        alert(data.error || 'Test failed.');
      }
    } catch (err: any) {
      alert(err.message || 'Test error');
    } finally {
      setTestingDiscord(false);
    }
  };

  useEffect(() => {
    if (isOpen && stackId) {
      fetchDetails();
      fetchDiscordSettings();
      setActiveTab('volumes');
      setRevealedKeys({});
      setConfirmDelete(false);
    } else {
      setDetails(null);
    }
  }, [isOpen, stackId, endpointId]);

  if (!isOpen || !stackId) return null;

  const isSensitive = (key: string) => {
    return /token|secret|pass|key|auth|cred|pwd|hash|database_url/i.test(key);
  };

  const copyToClipboard = (text: string, id: string) => {
    navigator.clipboard.writeText(text);
    setCopiedKey(id);
    setTimeout(() => setCopiedKey(null), 2000);
  };

  const handleIconUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = async () => {
        const base64 = reader.result as string;
        setCustomIconInput(base64);
        await onSaveIcon(stackId, base64);
        if (details) setDetails({ ...details, customIcon: base64 });
      };
      reader.readAsDataURL(file);
    }
  };

  const handleCustomIconSave = async () => {
    await onSaveIcon(stackId, customIconInput);
    if (details) setDetails({ ...details, customIcon: customIconInput });
  };

  const executeAction = async (action: 'start' | 'stop' | 'restart' | 'pause' | 'unpause') => {
    setActionLoading(action);
    try {
      await onAction(stackId, action);
      await fetchDetails();
    } finally {
      setActionLoading(null);
    }
  };

  const executeRedeploy = async () => {
    setActionLoading('redeploy');
    try {
      await onRedeploy(stackId);
      await fetchDetails();
    } finally {
      setActionLoading(null);
    }
  };

  const executeDelete = async () => {
    setActionLoading('delete');
    try {
      await onDelete(stackId);
      onClose();
    } finally {
      setActionLoading(null);
    }
  };

  // Progress notification state
  const [updateProgress, setUpdateProgress] = useState<{
    visible: boolean;
    stage: string;
    progress: number;
    message: string;
    stackId?: number;
    endpointId?: number;
  } | null>(null);

  const handleUpdateImage = async (img: any, stackId: number, endpointId: number) => {
    setUpdateProgress({
      visible: true,
      stage: 'checking',
      progress: 5,
      message: 'Checking for image updates...',
      stackId,
      endpointId,
    });

    try {
      // Use SSE endpoint for real-time progress updates
      const response = await fetch(`/api/admin/portainer/stacks/${stackId}/update`, {
        method: 'POST',
        headers: { 
          'Content-Type': 'application/json',
          'Accept': 'text/event-stream',
        },
        body: JSON.stringify({ endpointId }),
      });

      if (!response.ok) {
        const errData = await response.json().catch(() => ({ error: 'Unknown error' })) as { error?: string };
        throw new Error(errData?.error || 'Failed to start update');
      }

      // Read SSE stream
      const reader = response.body?.getReader();
      const decoder = new TextDecoder();

      if (reader) {
        while (true) {
          const { done, value } = await reader.read();
          if (done) break;

          const chunk = decoder.decode(value, { stream: true });
          const lines = chunk.split('\n');

          for (const line of lines) {
            if (line.startsWith('data: ')) {
              try {
                const progressData = JSON.parse(line.slice(6));
                setUpdateProgress(prev => prev ? { 
                  ...prev, 
                  stage: progressData.stage, 
                  progress: progressData.progress, 
                  message: progressData.message 
                } : null);

                if (progressData.stage === 'complete' || progressData.stage === 'error') {
                  break;
                }
              } catch (e) {
                // Ignore parse errors
              }
            }
          }
        }
      }

      // Refresh details after update completes
      await fetchDetails();

      // Hide progress after a delay
      setTimeout(() => setUpdateProgress(null), 3000);

    } catch (err: any) {
      setUpdateProgress(prev => prev ? { ...prev, stage: 'error', progress: 100, message: `Update failed: ${err.message}` } : null);
      setTimeout(() => setUpdateProgress(null), 5000);
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/80 backdrop-blur-md">
      <motion.div
        initial={{ opacity: 0, scale: 0.96 }}
        animate={{ opacity: 1, scale: 1 }}
        exit={{ opacity: 0, scale: 0.96 }}
        className="bg-slate-900 border border-slate-800 rounded-[2.5rem] w-full max-w-4xl max-h-[90vh] flex flex-col shadow-2xl overflow-hidden"
      >
        {/* Modal Header */}
        <div className="p-6 border-b border-slate-800 flex items-start justify-between gap-4 bg-slate-950/40">
          <div className="flex items-center space-x-4">
            <StackIcon
              name={details?.name || ''}
              image={details?.images?.[0]?.name}
              customIcon={details?.customIcon || customIconInput}
              size="lg"
            />
            <div>
              <div className="flex items-center space-x-3">
                <h3 className="text-xl font-black text-white tracking-tight">
                  {details?.name || `Stack #${stackId}`}
                </h3>
                <span className={`px-2.5 py-0.5 rounded-full text-[10px] font-black uppercase tracking-wider border ${
                  details?.statusLabel === 'running'
                    ? 'bg-emerald-500/10 text-emerald-400 border-emerald-500/20'
                    : 'bg-rose-500/10 text-rose-400 border-rose-500/20'
                }`}>
                  {details?.statusLabel || 'Unknown'}
                </span>
                <span className="px-2 py-0.5 rounded bg-slate-800 border border-slate-700 text-slate-400 text-[10px] font-mono">
                  Env #{endpointId}
                </span>
              </div>
