/** @jsxImportSource react */
import React, { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import { X, Layers, Save, RefreshCw, Plus, Trash2, Key } from 'lucide-react';

import { useBodyScrollLock } from '../../hooks/useBodyScrollLock';

interface StackEditorModalProps {
  stackId: number | null;
  endpointId?: number;
  isOpen: boolean;
  onClose: () => void;
  onSaved: () => void;
}

export function StackEditorModal({
  stackId,
  endpointId = 2,
  isOpen,
  onClose,
  onSaved,
}: StackEditorModalProps) {
  useBodyScrollLock(isOpen);
  const [name, setName] = useState('');
  const [composeYaml, setComposeYaml] = useState('');
  const [envVars, setEnvVars] = useState<Array<{ name: string; value: string }>>([]);
  const [customTemplates, setCustomTemplates] = useState<any[]>([]);
  const [selectedTemplateId, setSelectedTemplateId] = useState<string>('');
  const [environments, setEnvironments] = useState<any[]>([]);
  const [selectedEndpointId, setSelectedEndpointId] = useState<number>(endpointId);
  const [loadingTemplates, setLoadingTemplates] = useState(false);
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const isCreate = !stackId;

  useEffect(() => {
    if (isOpen) {
      setError(null);
      setSelectedTemplateId('');
      setSelectedEndpointId(endpointId);

      // Dynamically fetch live Portainer environments
      fetch('/api/admin/portainer/environments')
        .then(res => res.json() as Promise<{ success: boolean; data?: any[] }>)
        .then(json => {
          if (json.success && Array.isArray(json.data)) {
            setEnvironments(json.data);
          }
        })
        .catch(() => {});

      // Fetch Portainer Custom Templates for instant template loading
      if (isCreate) {
        setLoadingTemplates(true);
        fetch('/api/admin/portainer/templates')
          .then(res => res.json() as Promise<{ success: boolean; data?: any[] }>)
          .then(json => {
            if (json.success && Array.isArray(json.data)) {
              setCustomTemplates(json.data);
            }
          })
          .catch(() => {})
          .finally(() => setLoadingTemplates(false));
      }

      if (stackId) {
        setLoading(true);
        fetch(`/api/admin/portainer/stacks/${stackId}/details?envId=${endpointId}`)
          .then(res => res.json() as Promise<{ success: boolean; data?: any }>)
          .then(json => {
            if (json.success && json.data) {
              setName(json.data.name || '');
              setComposeYaml(json.data.composeFile || '');
              setEnvVars(json.data.env || []);
            }
          })
          .catch(err => setError(err.message))
          .finally(() => setLoading(false));
      } else {
        setName('');
        setComposeYaml(`version: '3.8'\n\nservices:\n  app:\n    image: nginx:latest\n    restart: unless-stopped\n    ports:\n      - "8080:80"\n`);
        setEnvVars([]);
      }
    }
  }, [isOpen, stackId, endpointId, isCreate]);

  const handleSelectTemplate = async (templateId: string) => {
    setSelectedTemplateId(templateId);
    if (!templateId) return;

    try {
      setLoading(true);
      const res = await fetch(`/api/admin/portainer/templates/${templateId}`);
      const json = await res.json() as { success: boolean; data?: any };
      if (json.success && json.data) {
        const tmpl = json.data;
        if (!name) setName(tmpl.Title?.toLowerCase().replace(/[^a-z0-9_-]/g, '-') || '');
        if (tmpl.fileContent) setComposeYaml(tmpl.fileContent);
        if (Array.isArray(tmpl.Variables) && tmpl.Variables.length > 0) {
          const mappedVars = tmpl.Variables.map((v: any) => ({
            name: v.name,
            value: v.defaultValue || ''
          }));
          setEnvVars(mappedVars);
        }
      }
    } catch (err: any) {
      setError(`Failed loading template: ${err.message}`);
    } finally {
      setLoading(false);
    }
  };

  if (!isOpen) return null;

  const handleAddEnv = () => {
    setEnvVars([...envVars, { name: '', value: '' }]);
  };

  const handleUpdateEnv = (index: number, field: 'name' | 'value', val: string) => {
    const updated = [...envVars];
    updated[index][field] = val;
    setEnvVars(updated);
  };

  const handleRemoveEnv = (index: number) => {
    setEnvVars(envVars.filter((_, i) => i !== index));
  };

  const handleSave = async () => {
    setSaving(true);
    setError(null);
    try {
      const url = isCreate 
        ? `/api/admin/portainer/stacks`
        : `/api/admin/portainer/stacks/${stackId}`;
      const method = isCreate ? 'POST' : 'PUT';

      const res = await fetch(url, {
        method,
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          name,
          stackFileContent: composeYaml,
          env: envVars.filter(e => e.name.trim()),
          endpointId: selectedEndpointId,
        }),
      });

      const json = await res.json() as { success: boolean; error?: string };
      if (!json.success) {
        throw new Error(json.error || 'Failed to save stack');
      }

      onSaved();
      onClose();
    } catch (err: any) {
      setError(err.message);
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/80 backdrop-blur-md">
      <motion.div
        initial={{ opacity: 0, scale: 0.96 }}
        animate={{ opacity: 1, scale: 1 }}
        exit={{ opacity: 0, scale: 0.96 }}
        className="bg-slate-900 border border-slate-800 rounded-[2.5rem] w-full max-w-4xl max-h-[90vh] flex flex-col shadow-2xl overflow-hidden"
      >
        {/* Header */}
        <div className="p-6 border-b border-slate-800 flex items-center justify-between bg-slate-950/40">
          <div className="flex items-center space-x-3">
            <div className="p-2.5 rounded-2xl bg-cyan-500/10 text-cyan-400 border border-cyan-500/20">
              <Layers className="w-6 h-6" />
            </div>
            <div>
              <h3 className="text-xl font-black text-white tracking-tight">
                {isCreate ? 'Create Portainer Stack' : `Edit Stack: ${name}`}
              </h3>
              <p className="text-xs text-slate-400">Environment #{endpointId}</p>
            </div>
          </div>

          <button
            onClick={onClose}
            className="p-2 rounded-xl text-slate-400 hover:text-white hover:bg-slate-800 transition-colors"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Content */}
        <div className="p-6 overflow-y-auto flex-1 space-y-6">
          {error && (
            <div className="p-4 rounded-xl bg-rose-500/10 border border-rose-500/20 text-rose-400 text-xs">
              {error}
            </div>
          )}

          {loading ? (
            <div className="py-20 flex flex-col items-center justify-center space-y-3">
              <RefreshCw className="w-8 h-8 text-cyan-400 animate-spin" />
              <p className="text-sm text-slate-400">Fetching compose file...</p>
            </div>
          ) : (
            <>
              {isCreate && (
                <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
