            className="flex items-center space-x-2 px-6 py-2.5 rounded-xl bg-cyan-600 hover:bg-cyan-500 text-white text-xs font-bold transition-colors disabled:opacity-50 shadow-lg shadow-cyan-600/20"
          >
            {saving ? <RefreshCw className="w-4 h-4 animate-spin" /> : <Save className="w-4 h-4" />}
            <span>{isCreate ? 'Create & Deploy Stack' : 'Save & Redeploy'}</span>
          </button>
        </div>
      </motion.div>
    </div>
  );
}

