function resolveAutoIcon(name: string, image?: string): string | null {
  const normName = name.toLowerCase().replace(/[^a-z0-9]/g, '');
  const normImage = (image || '').toLowerCase();

  for (const [key, url] of Object.entries(KNOWN_SERVICE_ICONS)) {
    const cleanKey = key.replace(/[^a-z0-9]/g, '');
    if (normName.includes(cleanKey) || normImage.includes(cleanKey)) {
      return url;
    }
  }

  // Check linuxserver image repository icons
  if (normImage.includes('linuxserver/')) {
    const lscrApp = normImage.split('linuxserver/')[1]?.split(':')[0];
    if (lscrApp && KNOWN_SERVICE_ICONS[lscrApp]) {
      return KNOWN_SERVICE_ICONS[lscrApp];
    }
  }

  return null;
}

export function StackIcon({ name, image, customIcon, className = '', size = 'md' }: StackIconProps) {
  const [error, setError] = useState(false);

  const sizeClasses = {
    sm: 'w-8 h-8 rounded-xl',
    md: 'w-12 h-12 rounded-2xl',
    lg: 'w-16 h-16 rounded-2xl',
    xl: 'w-20 h-20 rounded-3xl',
  };

  const iconSizeClasses = {
    sm: 'w-4 h-4',
    md: 'w-6 h-6',
    lg: 'w-8 h-8',
    xl: 'w-10 h-10',
  };

  const resolvedUrl = customIcon || resolveAutoIcon(name, image);

  if (resolvedUrl && !error) {
    return (
      <div className={`${sizeClasses[size]} bg-slate-950/80 border border-white/10 p-2 flex items-center justify-center overflow-hidden shadow-inner group-hover:scale-105 transition-transform ${className}`}>
        <img
          src={resolvedUrl}
          alt={name}
          className="w-full h-full object-contain filter drop-shadow"
          onError={() => setError(true)}
          loading="lazy"
        />
      </div>
    );
  }

  return (
    <div className={`${sizeClasses[size]} bg-cyan-500/10 border border-cyan-500/20 flex items-center justify-center text-cyan-400 group-hover:scale-105 transition-transform ${className}`}>
      <Server className={iconSizeClasses[size]} />
    </div>
  );
}

import React, { useState, useRef, useEffect, useMemo } from 'react';
import { Search, ChevronDown, Check, Plus } from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';
import { useReducedMotion } from '../../hooks/useReducedMotion';

export interface SearchableOption {
  value: string;
  label: string;
  icon?: React.ReactNode;
  metadata?: any;
}

interface SearchableSelectProps {
  options: SearchableOption[];
  value: string;
  onChange: (value: string) => void;
  placeholder?: string;
  className?: string;
  icon?: React.ReactNode;
  onCreate?: (search: string) => Promise<string | void> | string | void;
}

export const SearchableSelect: React.FC<SearchableSelectProps> = ({
  options,
  value,
  onChange,
  placeholder = 'Select option...',
  className = '',
  icon: LeadingIcon,
  onCreate,
}) => {
  const reduced = useReducedMotion();
  const [isOpen, setIsOpen] = useState(false);
  const [search, setSearch] = useState('');
  const [activeIndex, setActiveIndex] = useState(0);
  const containerRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  const sortedOptions = useMemo(() => {
    return [...options].sort((a, b) => a.label.localeCompare(b.label));
  }, [options]);

  const selectedOption = useMemo(
    () => sortedOptions.find(o => o.value === value),
    [sortedOptions, value]
  );

  const showCreateOption = useMemo(() => {
    if (!onCreate || !search.trim()) return false;
    return !sortedOptions.some(opt => opt.label.toLowerCase() === search.trim().toLowerCase());
  }, [sortedOptions, search, onCreate]);

  const filteredOptions = useMemo(() => {
    if (!search) return sortedOptions;
    return sortedOptions.filter(opt =>
      opt.label.toLowerCase().includes(search.toLowerCase()) ||
      (opt.metadata?.email && opt.metadata.email.toLowerCase().includes(search.toLowerCase()))
    );
  }, [sortedOptions, search]);

  useEffect(() => { setActiveIndex(0); }, [search]);

  useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => {
      if (containerRef.current && !containerRef.current.contains(e.target as Node)) {
        setIsOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (!isOpen) {
      if (e.key === 'Enter' || e.key === ' ' || e.key === 'ArrowDown') setIsOpen(true);
      return;
    }
    switch (e.key) {
      case 'ArrowDown':
        e.preventDefault();
        setActiveIndex(prev => (prev + 1) % filteredOptions.length);
        break;
      case 'ArrowUp':
        e.preventDefault();
        setActiveIndex(prev => (prev - 1 + filteredOptions.length) % filteredOptions.length);
        break;
      case 'Enter':
        e.preventDefault();
        if (filteredOptions[activeIndex]) {
          onChange(filteredOptions[activeIndex].value);
          setIsOpen(false);
        }
        break;
      case 'Escape':
        setIsOpen(false);
        break;
    }
  };

  const dropdownContent = (
    <>
      {/* Search Input */}
      <div className="p-3 border-b border-white/5 bg-white/2">
        <div className="relative flex items-center">
          <Search size={14} className="absolute left-3 text-slate-500" />
          <input
            ref={inputRef}
            type="text"
            value={search}
            onChange={e => setSearch(e.target.value)}
            placeholder="Search..."
            className="w-full bg-black/40 border border-white/10 rounded-xl pl-9 pr-4 py-2.5 text-sm text-white placeholder:text-slate-600 focus:border-blue-500/30 transition-all focus:outline-none"
            onClick={e => e.stopPropagation()}
          />
        </div>
      </div>

      {/* Options List */}
      <div className="max-h-[260px] overflow-y-auto scrollbar-thin scrollbar-thumb-white/10" role="listbox">
        {showCreateOption && (
          <div
            role="option"
            onClick={async e => {
              e.stopPropagation();
              const newId = await onCreate!(search.trim());
              if (newId) onChange(newId);
              setSearch('');
              setIsOpen(false);
            }}
            className="flex items-center gap-3 px-4 py-3 cursor-pointer transition-all hover:bg-white/5 text-blue-400 font-bold"
          >
            <div className="w-8 h-8 rounded-xl bg-blue-500/10 flex items-center justify-center border border-blue-500/20">
              <Plus size={14} className="text-blue-400" />
            </div>
            <span className="text-xs font-bold tracking-tight">Create "{search.trim()}"</span>
          </div>
        )}
        {filteredOptions.length > 0 ? (
          filteredOptions.map((option, idx) => {
            const isActive = idx === activeIndex;
            const isSelected = option.value === value;
            return (
              <div
                key={option.value}
                role="option"
                aria-selected={isSelected}
                onClick={e => { e.stopPropagation(); onChange(option.value); setIsOpen(false); }}
                onMouseEnter={() => setActiveIndex(idx)}
                className={`flex items-center gap-3 px-4 py-3 cursor-pointer transition-all ${
                  isActive ? 'bg-white/5' : ''
                } ${isSelected ? 'text-blue-400' : 'text-slate-300'}`}
              >
                <div className="w-8 h-8 rounded-xl bg-black/40 flex items-center justify-center border border-white/5 text-xs font-black italic shrink-0">
                  {option.icon || option.label.charAt(0)}
                </div>
                <div className="flex-1 flex flex-col overflow-hidden">
                  <span className="text-xs font-bold tracking-tight truncate">{option.label}</span>
                  {option.metadata?.subtext && (
                    <span className="text-[10px] text-slate-500 truncate">{option.metadata.subtext}</span>
                  )}
                </div>
                {isSelected && <Check size={14} className="text-blue-400 shrink-0" />}
              </div>
            );
          })
        ) : (
          <div className="p-8 text-center">
            <p className="text-[10px] text-slate-600 font-black uppercase tracking-[0.2em] italic">No Matches Found</p>
          </div>
        )}
      </div>
    </>
  );

  return (
    <div className={`relative ${className}`} ref={containerRef} onKeyDown={handleKeyDown}>
      {/* Trigger */}
      <div
        onClick={() => { setIsOpen(!isOpen); if (!isOpen) setTimeout(() => inputRef.current?.focus(), 50); }}
        aria-expanded={isOpen}
        aria-haspopup="listbox"
        className={`flex items-center gap-3 px-3 py-2.5 bg-slate-900/60 border rounded-xl cursor-pointer transition-all duration-200 group ${
          isOpen ? 'border-blue-500/40 ring-1 ring-blue-500/10' : 'border-white/5 hover:border-white/10'
        }`}
      >
        <div className="flex-1 flex items-center gap-2 overflow-hidden">
          {selectedOption?.icon || LeadingIcon || <Search size={13} className="text-slate-500 shrink-0" />}
          <span className={`text-xs font-medium truncate ${selectedOption ? 'text-white' : 'text-slate-500'}`}>
            {selectedOption ? selectedOption.label : placeholder}
          </span>
        </div>
        <ChevronDown size={13} className={`text-slate-500 shrink-0 transition-transform duration-200 ${isOpen ? 'rotate-180' : ''}`} />
      </div>

      {/* Dropdown */}
      {reduced ? (
        isOpen && (
          <div className="absolute z-[3000] left-0 right-0 mt-1.5 bg-[#0d0d0d]/98 backdrop-blur-2xl border border-white/10 rounded-2xl shadow-2xl overflow-hidden">
            {dropdownContent}
          </div>
        )
      ) : (
        <AnimatePresence>
          {isOpen && (
            <motion.div
              initial={{ opacity: 0, y: -6, scale: 0.97 }}
              animate={{ opacity: 1, y: 0, scale: 1 }}
              exit={{ opacity: 0, y: -6, scale: 0.97 }}
              transition={{ duration: 0.15, ease: 'easeOut' }}
              className="absolute z-[3000] left-0 right-0 mt-1.5 bg-[#0d0d0d]/98 backdrop-blur-2xl border border-white/10 rounded-2xl shadow-2xl overflow-hidden"
            >
              {dropdownContent}
            </motion.div>
          )}
        </AnimatePresence>
      )}
    </div>
  );
};

import React, { useState } from 'react'
import { useAuth } from '../context/AuthContext'
import { getApiUrl } from '../utils/api'

const AICoach: React.FC = () => {
  const { token, householdId } = useAuth()
  const [messages, setMessages] = useState<{ role: 'user' | 'coach', text: string }[]>([
    { role: 'coach', text: "Hello! I'm your LEDGER Coach. Ask me anything about your finances." }
  ])
  const [input, setInput] = useState('')
  const [loading, setLoading] = useState(false)

  const askCoach = async () => {
    if (!input.trim()) return
    const question = input
    setMessages(prev => [...prev, { role: 'user', text: question }])
    setInput('')
    setLoading(true)

    try {
      const res = (await fetch(`${getApiUrl()}/api/interop/coach/ask/ask`, {
              method: 'POST',
              headers: { 
                'Content-Type': 'application/json',
                'Authorization': `Bearer ${token}`,
                'x-household-id': householdId || ''
              },
              body: JSON.stringify({ question: question })
            }) as any)
      const data = (await res.json() as any)
      setMessages(prev => [...prev, { role: 'coach', text: data.answer }])
    } catch (e: any) {
      setMessages(prev => [...prev, { role: 'coach', text: "Sorry, I'm having trouble connecting to the backend right now." }])
    } finally {
      setLoading(false)
    }
  }

  return (
    <section className="card" style={{ gridColumn: 'span 1', display: 'flex', flexDirection: 'column', height: '400px' }}>
      <h3 style={{ marginBottom: '0.25rem' }}>💬 AI Financial Coach</h3>
      <p className="text-xs text-secondary font-medium mb-4">Chat with our secure, offline AI to get personalized financial advice, budgeting suggestions, or help organizing your household cash flow.</p>
      <div style={{ flex: 1, overflowY: 'auto', display: 'flex', flexDirection: 'column', gap: '0.8rem', paddingRight: '0.5rem' }}>
        {messages?.map((m, i) => (
          <div key={i} style={{ 
            alignSelf: m.role === 'user' ? 'flex-end' : 'flex-start',
            background: m.role === 'user' ? 'var(--primary)' : 'rgba(255,255,255,0.05)',
            color: 'white',
            padding: '0.6rem 1rem',
            borderRadius: m.role === 'user' ? '1rem 1rem 0 1rem' : '1rem 1rem 1rem 0',
            fontSize: '0.9rem',
            maxWidth: '85%'
          }}>
            {m.text}
          </div>
        ))}
        {loading && <div style={{ fontSize: '0.8rem', color: 'var(--text-secondary)' }}>Coach is thinking...</div>}
      </div>
      <div style={{ marginTop: '1rem', display: 'flex', gap: '0.5rem' }}>
        <input 
          value={input} 
          onChange={(e) => setInput(e.target.value)}
          onKeyDown={(e) => e.key === 'Enter' && askCoach()}
          placeholder="Ask a question..."
          style={{ flex: 1 }}
        />
        <button onClick={askCoach} className="primary" style={{ padding: '0.5rem 1rem' }}>Ask</button>
      </div>
    </section>
  )
}

