import React, { useState, useEffect, useCallback } from 'react'
import { useAuth } from '../context/AuthContext'
import { useToast } from '../context/ToastContext'
import { Card } from './ui/Card'
import { Button } from './ui/Button'
import { Input } from './ui/Input'
import { getApiUrl } from '../utils/api'
import { Smartphone, Check, X, RefreshCw, ArrowRight } from 'lucide-react'
import { InlineToast } from './ui/InlineToast'

interface PendingRequest {
  id: string
  code: string
  deviceInfo: string
  status: string
  expiresAt: string
  createdAt: string
}

export function CrossDeviceRequests() {
  const { token } = useAuth()
  const { showToast } = useToast()
  const [approvalCode, setApprovalCode] = useState('')
  const [approving, setApproving] = useState(false)
  const [pendingRequests, setPendingRequests] = useState<PendingRequest[]>([])
  const [loadingPending, setLoadingPending] = useState(false)

  const apiUrl = (getApiUrl() || '').replace(/\/$/, '')

  const fetchPending = useCallback(async () => {
    if (!token) return
    setLoadingPending(true)
    try {
      const res = await fetch(`${apiUrl}/api/auth/cross-device/pending`, {
        headers: { Authorization: `Bearer ${token}` }
      })
      if (res.ok) {
        const json = await res.json() as any
        setPendingRequests(json.data || [])
      }
    } catch (e: any) {
      console.error('Failed to fetch pending cross-device requests', e)
    } finally {
      setLoadingPending(false)
    }
  }, [token, apiUrl])

  useEffect(() => {
    fetchPending()
    const interval = setInterval(fetchPending, 10000)
    return () => clearInterval(interval)
  }, [fetchPending])

  const handleApprove = async () => {
    if (approvalCode.length !== 6) return
    setApproving(true)
    try {
      const res = await fetch(`${apiUrl}/api/auth/cross-device/approve`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` },
        body: JSON.stringify({ code: approvalCode.toUpperCase() })
      })
      if (res.ok) {
        showToast('Device authorized successfully', 'success')
        setApprovalCode('')
        fetchPending()
      } else {
        const json = await res.json() as any
        showToast(json.error || 'Failed to authorize device', 'error')
      }
    } catch (e: any) {
      showToast('Error authorizing device', 'error')
    } finally {
      setApproving(false)
    }
  }

  return (
    <Card className="bg-[#121212] border-white/5 overflow-hidden" title="Authorize Device Sign-In" subtitle="Approve a sign-in request from another device by entering the 6-character code shown there.">
      <div className="space-y-5">
        <div className="flex items-end gap-4">
          <div className="flex-1">
            <Input
              label="Author Code"
              value={approvalCode}
              onChange={(e) => setApprovalCode(e.target.value.toUpperCase().slice(0, 6))}
              placeholder="ENTER CODE"
              className="bg-white/5 border-white/5 font-mono font-black text-center tracking-[0.5em] text-lg"
              maxLength={6}
            />
          </div>
          <Button
            variant="primary"
            size="sm"
            onClick={handleApprove}
            disabled={approvalCode.length !== 6}
            loading={approving}
            aria-label="Authorize device sign-in"
            className="px-6"
          >
            <ArrowRight className="w-4 h-4 mr-2" /> Authorize
          </Button>
        </div>

        <div className="border-t border-white/5 pt-5">
          <div className="flex items-center justify-between mb-4">
            <h4 className="text-xs font-black tracking-widest text-slate-400">Pending Requests</h4>
            <button
              onClick={fetchPending}
              aria-label="Refresh pending requests"
              className="text-[10px] font-black text-slate-500 hover:text-white tracking-widest transition-colors flex items-center gap-1"
            >
              <RefreshCw className={`w-3 h-3 ${loadingPending ? 'animate-spin' : ''}`} /> Refresh
            </button>
          </div>
          {pendingRequests.length === 0 ? (
            <div className="text-center py-6 text-slate-500">
              <Smartphone className="w-6 h-6 mx-auto mb-2 opacity-30" />
              <p className="text-xs font-bold">No pending authorization requests</p>
            </div>
          ) : (
            <div className="space-y-3" aria-live="polite">
              {pendingRequests.map((req) => {
                const deviceInfo = (() => {
                  try { return JSON.parse(req.deviceInfo) } catch { return {} }
                })()
                return (
                  <div key={req.id} className="flex items-center justify-between gap-3 p-3 rounded-xl bg-white/[0.02] border border-white/5">
                    <div className="flex items-center gap-3 min-w-0">
                      <div className="w-10 h-10 rounded-lg bg-white/5 flex items-center justify-center shrink-0">
                        <Smartphone className="w-5 h-5 text-slate-400" />
                      </div>
                      <div className="min-w-0">
                        <p className="text-sm font-bold text-slate-200 truncate">{deviceInfo.userAgent?.slice(0, 50) || 'Unknown device'}</p>
                        <p className="text-[10px] text-slate-500 font-mono">{req.code} · Expires {new Date(req.expiresAt).toLocaleTimeString()}</p>
                      </div>
                    </div>
                    <InlineToast
                      message="Authorize this device?"
                      type="confirm"
                      onConfirm={async () => {
                        try {
                          const res = await fetch(`${apiUrl}/api/auth/cross-device/approve`, {
                            method: 'POST',
                            headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` },
                            body: JSON.stringify({ code: req.code })
                          })
                          if (res.ok) {
                            showToast('Device authorized', 'success')
                            fetchPending()
                          } else {
                            const json = await res.json() as any
                            showToast(json.error || 'Failed', 'error')
                          }
                        } catch (e: any) {
                          showToast('Error', 'error')
                        }
                      }}
                    />
                  </div>
                )
              })}
            </div>
          )}
        </div>
      </div>
    </Card>
  )
}

import React, { useState } from 'react'
import { useAuth } from '../context/AuthContext'
import { Checkbox } from './ui/Checkbox'

interface CustomizerProps {
  settings: any
  onUpdate: (newSettings: any) => void
}

const Customizer: React.FC<CustomizerProps> = ({ settings, onUpdate }) => {
  const { } = useAuth()
  const [isOpen, setIsOpen] = useState(false)

  const toggleWidget = (widgetId: string) => {
    const layout = settings.dashboardLayout || {}
    const newSettings = {
      ...settings,
      dashboardLayout: {
        ...layout,
        [widgetId]: !layout[widgetId]
      }
    }
    onUpdate(newSettings)
  }

  const widgets = [
    { id: 'healthScore', name: 'Financial Intelligence' },
    { id: 'recentTransactions', name: 'Recent Transactions' },
    { id: 'calendar', name: 'Financial Calendar' },
    { id: 'savingsBuckets', name: 'Savings Buckets' },
    { id: 'smartInsights', name: 'AI Smart Insights' }
  ]

  return (
    <div style={{ position: 'fixed', bottom: '2rem', right: '2rem', zIndex: 1000 }}>
      <button 
        onClick={() => setIsOpen(!isOpen)}
        style={{ 
          width: '50px', height: '50px', borderRadius: '50%', 
          background: 'var(--primary)', border: 'none', color: 'white', 
          fontSize: '1.5rem', cursor: 'pointer', boxShadow: '0 4px 12px rgba(0,0,0,0.3)' 
        }}
      >
        {isOpen ? '✕' : '⚙️'}
      </button>

      {isOpen && (
        <div className="card reveal" style={{ 
          position: 'absolute', bottom: '60px', right: 0, 
          width: '300px', padding: '1.5rem', background: 'var(--bg-card)', 
          border: '1px solid var(--glass-border)', boxShadow: '0 10px 25px rgba(0,0,0,0.5)' 
        }}>
          <h3 style={{ marginBottom: '1rem' }}>Personalize Dashboard</h3>

          <div style={{ display: 'grid', gap: '1rem' }}>
            <section>
              <h4 style={{ fontSize: '0.8rem', color: 'var(--text-secondary)', marginBottom: '0.5rem' }}>Visible Widgets</h4>
              {widgets.map(w => (
                <label key={w.id} style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', cursor: 'pointer', padding: '0.3rem 0' }}>
                  <span style={{ fontSize: '0.9rem' }}>{w.name}</span>
                  <Checkbox 
                    checked={settings.dashboardLayout?.[w.id] !== false} 
                    onChange={() => toggleWidget(w.id)}
                  />
                </label>
              ))}
            </section>

            <section>
              <h4 style={{ fontSize: '0.8rem', color: 'var(--text-secondary)', marginBottom: '0.5rem' }}>Visual Overrides</h4>
              <div style={{ display: 'flex', gap: '0.5rem', marginBottom: '1rem' }}>
                {['default', 'glass', 'minimal'].map(style => (
                  <button 
                    key={style}
                    onClick={() => onUpdate({ ...settings, uiStyle: style })}
                    style={{ 
                      flex: 1, padding: '0.4rem', fontSize: '0.7rem', 
                      background: settings.uiStyle === style ? 'var(--primary)' : 'rgba(255,255,255,0.05)',
                      border: '1px solid var(--glass-border)', borderRadius: '0.4rem'
                    }}
                  >
                    {style.toUpperCase()}
                  </button>
                ))}
              </div>

              <h4 style={{ fontSize: '0.8rem', color: 'var(--text-secondary)', marginBottom: '0.5rem' }}>Color Palette</h4>
              <div style={{ display: 'grid', gridTemplateColumns: 'repeat(5, 1fr)', gap: '0.5rem' }}>
                {['emerald', 'sapphire', 'ruby', 'luxury', 'blood', 'carbon', 'ember', 'professional'].map(tId => (
                  <button 
                    key={tId}
                    onClick={() => {
                        // We use index.css [data-theme] for this
                        document.documentElement.setAttribute('data-theme', tId);
                        localStorage.setItem('ledger_theme', tId);
                        onUpdate({ ...settings, theme: tId });
                    }}
                    style={{ 
                      aspectRatio: '1', borderRadius: '50%',
                      background: tId === 'blood' ? '#ff0000' : 
                                 tId === 'luxury' ? '#d4af37' : 
                                 tId === 'ruby' ? '#ef4444' : 
                                 tId === 'sapphire' ? '#3b82f6' : 
                                 tId === 'emerald' ? '#10b981' : 
                                 tId === 'carbon' ? '#ffffff' : 
                                 tId === 'ember' ? '#f97316' : 
                                 '#64748b',
                      border: settings.theme === tId ? '2px solid white' : '2px solid transparent',
                      cursor: 'pointer',
                      boxShadow: '0 2px 5px rgba(0,0,0,0.2)'
                    }}
                    title={tId}
                  />
                ))}
              </div>
            </section>
          </div>

          <button 
            className="primary" 
            style={{ width: '100%', marginTop: '1.5rem' }}
            onClick={() => setIsOpen(false)}
          >
            Done
          </button>
        </div>
      )}
    </div>
  )
}

