const formatJoinedAt = (joinedAt?: string | null) => {
  if (!joinedAt) return '—';
  const joined = new Date(joinedAt);
  if (isNaN(joined.getTime())) return '—';
  const diff = Date.now() - joined.getTime();
  const days = Math.floor(diff / 86400000);
  if (days <= 0) return 'Today';
  if (days === 1) return 'Yesterday';
  if (days < 30) return `${days}d ago`;
  const months = Math.floor(days / 30);
  if (months < 12) return `${months}mo ago`;
  const years = Math.floor(months / 12);
  return `${years}y ago`;
};

const joinMethodLabel = (method?: string | null) => {
  if (!method) return '—';
  const map: Record<string, string> = {
    create: 'Founder',
    invite: 'Invite link',
    code: 'Invite code',
    system: 'Seeded'
  };
  return map[method] || method;
};

const HouseholdRegistry: React.FC = () => {
  const { householdId } = useAuth();
  const { data: profile } = (useApi('/api/user/profile') as any);
  const { data: households } = (useApi('/api/user/households') as any);
  const { data: members, mutate: mutateMembers } = (useApi(householdId ? `/api/user/households/${householdId}/members` : null) as any);
  const { data: invites, mutate: mutateInvites } = (useApi(householdId ? `/api/user/households/${householdId}/invites` : null) as any);

  const currentHousehold = useMemo(() => {
    if (Array.isArray(households) && householdId) {
      return households.find((h: any) => h.id === householdId)
    }
    return null
  }, [households, householdId]);

  const userRole = useMemo(() => {
    if (Array.isArray(members) && profile?.id) {
      const member = members.find((m: any) => m.id === profile.id);
      return member?.role || 'member';
    }
    return 'member';
  }, [members, profile]);

  const isAdmin = userRole === 'admin' || userRole === 'owner';
  const isOwner = userRole === 'owner';

  const { showToast } = useToast();
  const [isRenaming, setIsRenaming] = useState(false);
  const [householdName, setHouseholdName] = useState('');
  const [inviteEmail, setInviteEmail] = useState('');
  const [inviteUrl, setInviteUrl] = useState('');
  const [inviteCode, setInviteCode] = useState('');
  const [inviteMethod, setInviteMethod] = useState<'link' | 'code' | 'both'>('link');
  const [inviteCodeLength, setInviteCodeLength] = useState<6 | 8>(6);
  const [inviteLifetimeHours, setInviteLifetimeHours] = useState<24 | 168>(24);
  const [inviteReusable, setInviteReusable] = useState(true);
  const [showInviteOptions, setShowInviteOptions] = useState(false);
  const [revokingInviteId, setRevokingInviteId] = useState<string | null>(null);
  const [togglingInvites, setTogglingInvites] = useState(false);
  const [copied, setCopied] = useState(false);
  const [loading, setLoading] = useState(false);
  const [isCreateModalOpen, setIsCreateModalOpen] = useState(false);
  const [newHouseholdName, setNewHouseholdName] = useState('');
  const [creating, setCreating] = useState(false);

  // Member Management State
  const [updatingRole, setUpdatingRole] = useState<string | null>(null);
  const [archiving, setArchiving] = useState(false);
  const [confirmRemoveId, setConfirmRemoveId] = useState<string | null>(null);
  const [removingMember, setRemovingMember] = useState<string | null>(null);
  const [isArchiveModalOpen, setIsArchiveModalOpen] = useState(false);

  React.useEffect(() => {
    if (currentHousehold?.name) {
      setHouseholdName(currentHousehold.name);
    }
  }, [currentHousehold]);

  const handleRename = async () => {
    const token = localStorage.getItem('ledger_token');
    try {
      const res = (await fetch(`${API_URL}/api/user/households/${householdId}`, {
              method: 'PATCH',
              headers: { 
                'Authorization': `Bearer ${token}`,
                'Content-Type': 'application/json'
              },
              body: JSON.stringify({ name: householdName })
            }) as any);
      if (res.ok) {
        showToast('Household renamed successfully', 'success');
        window.location.reload();
        setIsRenaming(false);
      } else {
        const err = (await res.json() as any);
        showToast(formatHumanError(err, 'Failed to rename household'), 'error');
      }
    } catch (err: any) {
      console.error(err);
      showToast(formatHumanError(err, 'Failed to connect to servers'), 'error');
    }
  };

  const updateMemberRole = async (memberId: string, role: string) => {
    setUpdatingRole(memberId);
    const token = localStorage.getItem('ledger_token');
    try {
      const res = (await fetch(`${API_URL}/api/user/households/${householdId}/members/${memberId}`, {
              method: 'PATCH',
              headers: { 
                'Authorization': `Bearer ${token}`,
                'Content-Type': 'application/json'
              },
              body: JSON.stringify({ role })
            }) as any);
      if (res.ok) {
        showToast('Member role updated', 'success');
        mutateMembers();
      } else {
        const err = (await res.json() as any);
        showToast(formatHumanError(err, 'Failed to update role'), 'error');
      }
    } finally {
      setUpdatingRole(null);
    }
  };

  const removeMember = async (memberId: string) => {
    setRemovingMember(memberId);
    const token = localStorage.getItem('ledger_token');
    try {
      const res = (await fetch(`${API_URL}/api/user/households/${householdId}/members/${memberId}`, {
              method: 'DELETE',
              headers: { 'Authorization': `Bearer ${token}` }
            }) as any);
      if (res.ok) {
        showToast('Member removed', 'success');
        setConfirmRemoveId(null);
        mutateMembers();
      } else {
        const err = (await res.json() as any);
        showToast(formatHumanError(err, 'Failed to remove member'), 'error');
      }
    } finally {
      setRemovingMember(null);
    }
  };

  const archiveHousehold = async () => {
    setArchiving(true);
    const token = localStorage.getItem('ledger_token');
    try {
      const res = (await fetch(`${API_URL}/api/user/households/${householdId}`, {
              method: 'DELETE',
              headers: { 'Authorization': `Bearer ${token}` }
            }) as any);
      if (res.ok) {
        showToast('Household archived successfully', 'success');
        window.location.href = '/#/';
        window.location.reload();
      } else {
        const err = (await res.json() as any);
        showToast(formatHumanError(err, 'Failed to archive household'), 'error');
      }
    } finally {
      setArchiving(false);
      setIsArchiveModalOpen(false);
    }
  };

  const confirmCreate = async () => {
    if (!newHouseholdName) return;
    const token = localStorage.getItem('ledger_token');
    setCreating(true);
    try {
      const res = (await fetch(`${API_URL}/api/user/households`, {
              method: 'POST',
              headers: { 
                'Authorization': `Bearer ${token}`,
                'Content-Type': 'application/json'
              },
              body: JSON.stringify({ name: newHouseholdName })
            }) as any);
      if (res.ok) {
        showToast('New household created', 'success');
        window.location.reload(); // Switch context
      } else {
        const err = (await res.json() as any);
        showToast(formatHumanError(err, 'Failed to create household'), 'error');
      }
    } catch (err: any) {
      showToast(formatHumanError(err, 'Network error while creating household'), 'error');
    } finally {
      setCreating(false);
      setIsCreateModalOpen(false);
      setNewHouseholdName('');
    }
  };

  const generateInvite = async () => {
    setLoading(true);
    setInviteUrl('');
    setInviteCode('');
    const token = localStorage.getItem('ledger_token');
    try {
      const res = (await fetch(`${API_URL}/api/user/households/invite`, {
              method: 'POST',
              headers: { 
                'Authorization': `Bearer ${token}`,
                'Content-Type': 'application/json',
                'x-household-id': householdId || ''
              },
              body: JSON.stringify({
                email: inviteEmail || undefined,
                method: inviteMethod,
                codeLength: inviteMethod === 'link' ? undefined : inviteCodeLength,
                codeLifetimeHours: inviteLifetimeHours,
                reusable: inviteReusable
              })
            }) as any);
      const data = (await res.json() as any);
      if (res.ok) {
        if (inviteMethod !== 'code') {
          setInviteUrl(`${window.location.origin}/${data.url}`);
        }
        if (inviteMethod !== 'link' && data.code) {
          setInviteCode(data.code);
        }
        if (inviteEmail) {
           showToast(`Invitation sent to ${inviteEmail}`, 'success');
        } else if (inviteMethod !== 'link' && data.code) {
           showToast('Invite code generated', 'success');
        } else {
           showToast('Invite link created', 'success');
        }
        mutateInvites();
      } else {
        showToast(formatHumanError(data, 'Invite generation failed'), 'error');
      }
    } catch (err: any) {
      showToast(formatHumanError(err, 'Network error while generating invite'), 'error');
    } finally {
      setLoading(false);
    }
  };

  const revokeInvite = async (inviteId: string) => {
    setRevokingInviteId(inviteId);
    const token = localStorage.getItem('ledger_token');
    try {
      const res = (await fetch(`${API_URL}/api/user/households/${householdId}/invites/${inviteId}`, {
              method: 'DELETE',
              headers: { 'Authorization': `Bearer ${token}` }
            }) as any);
      if (res.ok) {
        showToast('Invitation revoked', 'success');
        mutateInvites();
      } else {
        const err = (await res.json() as any);
        showToast(formatHumanError(err, 'Failed to revoke invite'), 'error');
      }
    } catch (err: any) {
      showToast(formatHumanError(err, 'Network error while revoking invite'), 'error');
    } finally {
      setRevokingInviteId(null);
    }
  };

  const toggleInvitesEnabled = async () => {
    setTogglingInvites(true);
    const token = localStorage.getItem('ledger_token');
    const next = !(currentHousehold?.invitesEnabled ?? true);
    try {
      const res = (await fetch(`${API_URL}/api/user/households/${householdId}`, {
              method: 'PATCH',
              headers: { 
                'Authorization': `Bearer ${token}`,
                'Content-Type': 'application/json'
              },
              body: JSON.stringify({ invitesEnabled: next })
            }) as any);
      if (res.ok) {
        showToast(next ? 'Invites enabled for this household' : 'Invites disabled for this household', 'success');
        window.location.reload();
      } else {
        const err = (await res.json() as any);
        showToast(formatHumanError(err, 'Failed to toggle invites'), 'error');
      }
    } catch (err: any) {
      showToast(formatHumanError(err, 'Network error while toggling invites'), 'error');
    } finally {
      setTogglingInvites(false);
    }
  };

  const copyInviteValue = (value: string) => {
    navigator.clipboard.writeText(value);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div className="space-y-8">
      {/* Household Settings */}
      <div className="card p-8 bg-gradient-to-br from-emerald-500/5 to-transparent border-l-4 border-emerald-500">
        <div className="flex items-center justify-between mb-8">
           <div className="flex items-center gap-4">
              <div className="w-12 h-12 rounded-2xl bg-emerald-500/10 flex items-center justify-center text-emerald-500">
                 <Shield size={24} />
              </div>
              <div>
                 <div className="flex items-center gap-3">
                    {isRenaming ? (
                      <div className="flex items-center gap-2">
                        <input 
                          className="bg-black border border-emerald-500/30 rounded px-2 py-1 text-lg font-black italic tracking-tight outline-none"
                          value={householdName}
                          onChange={e => setHouseholdName(e.target.value)}
                          onKeyDown={e => e.key === 'Enter' && handleRename()}
                          autoFocus
                        />
                        <button onClick={handleRename} className="px-3 py-1 bg-emerald-500 text-black text-xs font-black rounded hover:scale-105 transition-all">Save</button>
                        <button onClick={() => {
                          setHouseholdName(currentHousehold?.name || '');
                          setIsRenaming(false);
                        }} className="px-3 py-1 bg-white/10 text-white text-xs font-black rounded hover:bg-white/20 transition-all">Cancel</button>
                      </div>
                    ) : (
                      <>
                        <h3 className="text-2xl font-black italic tracking-tight leading-none">{currentHousehold?.name || 'Personal Account'}</h3>
                        {isAdmin && (
                          <button onClick={() => setIsRenaming(true)} className="text-slate-500 hover:text-emerald-500">
                            <Edit3 size={16} />
                          </button>
                        )}
                      </>
                    )}
                 </div>
                 <p className="text-[10px] font-black tracking-[0.3em] text-emerald-500/60 mt-1">Current Household</p>
              </div>
           </div>
           <button 
             onClick={() => setIsCreateModalOpen(true)}
             className="flex items-center gap-2 px-4 py-2 bg-white/5 hover:bg-white/10 rounded-xl text-xs font-black tracking-widest text-secondary transition-all"
           >
              <Plus size={14} />
              New Household
           </button>
        </div>

        {/* Address Section */}
        <div className="pt-4 pb-2 border-t border-white/5 space-y-4">
          <AddressPanel householdId={householdId!} userRole={userRole} />
          {isOwner && householdId && (
            <AddressVisibilitySettings householdId={householdId} />
          )}
        </div>

        {/* Members List */}
        <div className="space-y-4 pt-6 border-t border-white/5 mb-8">
           <div className="flex items-center justify-between mb-4">
              <div>
                <h4 className="text-sm font-black tracking-widest flex items-center gap-2">
                   <Users size={14} className="text-emerald-500" />
                   Household Members
                </h4>
                <p className="text-xs text-secondary opacity-40 font-bold tracking-tight">Active participants in this context</p>
              </div>
           </div>

           <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              {(members || []).map((m: any) => (
                 <div key={m.id} className="p-4 bg-white/[0.02] border border-white/5 rounded-2xl flex items-center justify-between group hover:border-emerald-500/20 transition-all">
                    <div className="flex items-center gap-3">
                       <img 
                         src={sanitizeImageUrl(m.avatarUrl) || `https://api.dicebear.com/7.x/bottts/svg?seed=${encodeURIComponent(m.id)}`} 
                         className="w-10 h-10 rounded-xl border border-white/10" 
                         alt={m.displayName || ''} 
                       />
                       <div>
                          <div className="flex items-center gap-2">
                             <p className="text-sm font-black tracking-tight">{m.displayName || 'System User'}</p>
                             <span className={`text-[10px] px-1.5 py-0.5 rounded font-black tracking-widest ${ m.role === 'owner' ? 'bg-emerald-500 text-black' : m.role === 'admin' ? 'bg-blue-500/20 text-blue-400 border border-blue-500/30' : 'bg-white/5 text-slate-400' }`}>
                                {m.role}
                             </span>
                          </div>
                           <p className="text-[10px] text-slate-500 font-mono italic opacity-60 truncate max-w-[120px]">{m.email}</p>
                           <p className="text-[10px] text-slate-600 font-bold tracking-wide">
                              Joined {formatJoinedAt(m.joinedAt)} · {joinMethodLabel(m.joinMethod)}
                           </p>
                       </div>
                    </div>

                    {isAdmin && m.id !== profile?.id && m.role !== 'owner' && (
                       <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-all">
                          <select 
                            className="bg-black border border-white/10 rounded-lg text-[10px] font-black py-1 px-2 outline-none hover:border-emerald-500/30 transition-all"
                            value={m.role}
                            onChange={(e) => updateMemberRole(m.id, e.target.value)}
                            disabled={updatingRole === m.id}
                          >
                             <option value="member">Member</option>
                             <option value="admin">Admin</option>
                             <option value="observer">Observer</option>
                          </select>

                          {confirmRemoveId === m.id ? (
                            <InlineToast 
                              message="Remove member?" 
                              type="confirm" 
                              onConfirm={() => removeMember(m.id)} 
                              onCancel={() => setConfirmRemoveId(null)} 
                            />
                          ) : (
                            <button 
                              onClick={() => setConfirmRemoveId(m.id)}
                              disabled={removingMember === m.id}
                              className="p-2 text-red-500 hover:bg-red-500/10 rounded-lg transition-all"
                              title="Remove from Household"
                            >
                               <UserMinus size={14} />
                            </button>
                          )}
                       </div>
                    )}
                 </div>
              ))}
           </div>
        </div>

        {/* Invitation Control */}
        <div className="space-y-4 pt-6 border-t border-white/5">
           <div className="flex items-center justify-between">
              <div>
                <h4 className="text-sm font-black tracking-widest flex items-center gap-2">
                   <UserCheck size={14} className="text-emerald-500" />
                   Invite New Member
                </h4>
                <p className="text-xs text-secondary opacity-40 font-bold tracking-tight">Expand your household's collaborative access</p>
              </div>
              {isAdmin && (
                <button
                  onClick={toggleInvitesEnabled}
                  disabled={togglingInvites}
                  className={`flex items-center gap-2 px-3 py-1.5 rounded-xl text-[10px] font-black tracking-widest transition-all border ${currentHousehold?.invitesEnabled === false ? 'border-red-500/30 text-red-500 bg-red-500/5' : 'border-emerald-500/30 text-emerald-500 bg-emerald-500/5'}`}
                  title="Toggle household-wide invites"
                >
                  <Power size={12} />
                  {currentHousehold?.invitesEnabled === false ? 'Invites Off' : 'Invites On'}
                </button>
              )}
           </div>

           {currentHousehold?.invitesEnabled === false && (
             <div className="p-3 rounded-2xl border border-red-500/20 bg-red-500/5 text-xs font-bold text-red-400/80 tracking-wide">
                Invites are currently disabled for this household. Turn them on to generate new invites.
             </div>
           )}

           <div className="flex gap-3">
              <input 
                type="email"
                placeholder="Member's email address (optional)..."
                className="flex-1 bg-black/40 border border-white/5 p-4 rounded-2xl text-sm font-bold focus:border-emerald-500/30 transition-all outline-none"
                value={inviteEmail}
                onChange={e => setInviteEmail(e.target.value)}
              />
              <button 
                onClick={generateInvite}
                disabled={loading || !isAdmin}
                className="px-8 py-4 bg-emerald-500 hover:bg-emerald-600 disabled:opacity-50 disabled:grayscale text-black font-black tracking-widest text-xs rounded-2xl transition-all flex items-center gap-3 shadow-lg shadow-emerald-500/20"
              >
                {loading ? <Plus className="animate-spin" /> : <Send size={16} />}
                {inviteEmail ? 'Send Invite' : 'Generate Link'}
              </button>
           </div>

           {isAdmin && (
             <>
              <button
                onClick={() => setShowInviteOptions(!showInviteOptions)}
                className="flex items-center gap-2 text-[10px] font-black tracking-widest text-slate-500 hover:text-emerald-500 transition-all"
              >
                <ChevronDown size={12} className={`transition-transform ${showInviteOptions ? 'rotate-180' : ''}`} />
                Invite Options
              </button>

              {showInviteOptions && (
                <div className="p-4 bg-black/40 border border-white/5 rounded-2xl grid grid-cols-1 sm:grid-cols-2 gap-4">
                   <label className="block">
                     <span className="text-[10px] font-black tracking-widest text-secondary block mb-1">DELIVERY METHOD</span>
                     <select
                       className="w-full bg-black border border-white/10 rounded-lg text-xs font-black py-2 px-2 outline-none hover:border-emerald-500/30 transition-all"
                       value={inviteMethod}
                       onChange={e => setInviteMethod(e.target.value as any)}
                     >
                        <option value="link">Invite link</option>
                        <option value="code">Join code</option>
                        <option value="both">Link + code</option>
                     </select>
                   </label>
                   <label className="block">
                     <span className="text-[10px] font-black tracking-widest text-secondary block mb-1">CODE LENGTH</span>
                     <select
                       className="w-full bg-black border border-white/10 rounded-lg text-xs font-black py-2 px-2 outline-none hover:border-emerald-500/30 transition-all disabled:opacity-40"
                       value={inviteCodeLength}
                       onChange={e => setInviteCodeLength(Number(e.target.value) as any)}
                       disabled={inviteMethod === 'link'}
                     >
                        <option value={6}>6 characters</option>
                        <option value={8}>8 characters</option>
                     </select>
                   </label>
                   <label className="block">
                     <span className="text-[10px] font-black tracking-widest text-secondary block mb-1">EXPIRY</span>
                     <select
                       className="w-full bg-black border border-white/10 rounded-lg text-xs font-black py-2 px-2 outline-none hover:border-emerald-500/30 transition-all"
                       value={inviteLifetimeHours}
                       onChange={e => setInviteLifetimeHours(Number(e.target.value) as any)}
                     >
                        <option value={24}>24 hours</option>
                        <option value={168}>7 days</option>
                     </select>
                   </label>
                   <label className="flex items-center gap-3 pt-5 cursor-pointer select-none">
                     <input
                       type="checkbox"
                       checked={inviteReusable}
                       onChange={e => setInviteReusable(e.target.checked)}
                       className="w-4 h-4 accent-emerald-500"
                     />
                     <span className="text-[10px] font-black tracking-widest text-secondary">REUSABLE INVITE</span>
                   </label>
                </div>
              )}
             </>
            )}

            {inviteUrl && (
              <div className="p-4 bg-emerald-500/5 border border-emerald-500/20 rounded-2xl flex items-center justify-between gap-4">
                 <div className="flex-1 overflow-hidden">
                    <p className="text-[10px] text-emerald-500 font-black tracking-widest mb-1">Invite Link Active ({inviteLifetimeHours}h)</p>
                    <code className="text-xs text-slate-300 font-mono break-all">{inviteUrl}</code>
                 </div>
                 <button 
                   onClick={() => copyInviteValue(inviteUrl)}
                   className={`p-3 rounded-xl transition-all ${copied ? 'bg-emerald-500 text-black' : 'bg-white/5 text-emerald-500 hover:bg-white/10'}`}
                 >
                   {copied ? <Check size={18} /> : <Copy size={18} />}
                 </button>
              </div>
            )}

            {inviteCode && (
              <div className="p-4 bg-blue-500/5 border border-blue-500/20 rounded-2xl flex items-center justify-between gap-4">
                 <div className="flex-1">
                    <p className="text-[10px] text-blue-400 font-black tracking-widest mb-1">Join Code Active ({inviteLifetimeHours}h{inviteReusable ? ' · Reusable' : ''})</p>
                    <code className="text-2xl font-mono font-black tracking-[0.4em] text-blue-300">{inviteCode}</code>
                 </div>
                 <button 
                   onClick={() => copyInviteValue(inviteCode)}
                   className={`p-3 rounded-xl transition-all ${copied ? 'bg-emerald-500 text-black' : 'bg-white/5 text-blue-400 hover:bg-white/10'}`}
                 >
                   {copied ? <Check size={18} /> : <Copy size={18} />}
                 </button>
              </div>
            )}

            {isAdmin && Array.isArray(invites) && invites.length > 0 && (
              <div className="space-y-2 pt-2">
                 <p className="text-[10px] font-black tracking-widest text-slate-500 flex items-center gap-2">
                    <KeyRound size={12} /> ACTIVE INVITES ({invites.length})
                 </p>
                 {(invites as any[]).map((inv: any) => {
                    const isExpired = inv.expiresAt && new Date(inv.expiresAt) < new Date();
                    return (
                      <div key={inv.id} className="p-3 bg-white/[0.02] border border-white/5 rounded-xl flex items-center justify-between gap-3">
                         <div className="flex-1 min-w-0">
                            <div className="flex items-center gap-2 flex-wrap">
                              {inv.joinCode && (
                                <code className="font-mono font-black tracking-[0.25em] text-blue-300 text-sm">{inv.joinCode}</code>
                              )}
                              {inv.joinCode ? (
                                <span className="text-[9px] px-1.5 py-0.5 rounded bg-blue-500/10 text-blue-400 font-black tracking-widest">CODE</span>
                              ) : (
                                <span className="text-[9px] px-1.5 py-0.5 rounded bg-emerald-500/10 text-emerald-400 font-black tracking-widest">LINK</span>
                              )}
                              {inv.disabledAt && (
                                <span className="text-[9px] px-1.5 py-0.5 rounded bg-red-500/10 text-red-400 font-black tracking-widest">REVOKED</span>
                              )}
                              {isExpired && (
                                <span className="text-[9px] px-1.5 py-0.5 rounded bg-white/5 text-slate-400 font-black tracking-widest">EXPIRED</span>
                              )}
                            </div>
                            <p className="text-[10px] text-slate-500 font-bold tracking-wide mt-1">
                              {inv.reusable ? 'Reusable' : 'Single-use'} · {inv.joinCount || 0} joined
                              {inv.expiresAt ? ` · Expires ${new Date(inv.expiresAt).toLocaleString()}` : ''}
                            </p>
                         </div>
                         <button
                           onClick={() => revokeInvite(inv.id)}
                           disabled={revokingInviteId === inv.id}
                           className="p-2 text-red-500 hover:bg-red-500/10 rounded-lg transition-all disabled:opacity-50"
                           title="Revoke invite"
                         >
                            <Trash2 size={14} />
                         </button>
                      </div>
                    )
                 })}
              </div>
            )}
        </div>
      </div>

      {/* Danger Zone */}
      {isOwner && (
        <div className="p-8 border-2 border-dashed border-red-500/20 rounded-[2rem] bg-red-500/[0.02] flex items-center justify-between">
           <div className="flex items-center gap-4">
              <div className="w-12 h-12 rounded-2xl bg-red-500/10 flex items-center justify-center text-red-500">
                 <ShieldAlert size={24} />
              </div>
              <div>
                 <h3 className="text-xl font-black italic tracking-tight">Danger Zone</h3>
                 <p className="text-xs font-bold text-red-500/60 tracking-widest">Permanent household deactivation</p>
              </div>
           </div>
           <button 
             onClick={() => setIsArchiveModalOpen(true)}
             className="px-6 py-3 border border-red-500/30 hover:bg-red-500 text-red-500 hover:text-black font-black tracking-widest text-[10px] rounded-xl transition-all"
           >
              Archive Household
           </button>
        </div>
      )}

      <Modal
        isOpen={isCreateModalOpen}
        onClose={() => setIsCreateModalOpen(false)}
        title="Create New Household"
        footer={
          <>
            <Button variant="secondary" onClick={() => setIsCreateModalOpen(false)}>Cancel</Button>
            <Button variant="primary" onClick={confirmCreate} disabled={creating || !newHouseholdName}>
              {creating ? 'Creating...' : 'Create Household'}
            </Button>
          </>
        }
      >
        <div className="space-y-4">
          <p className="text-secondary text-sm font-medium">Enter a name for your new household. You can invite members after creation.</p>
          <Input 
            label="Household Name"
            placeholder="e.g. Smith Residence, Vacation Fund"
            value={newHouseholdName}
            onChange={(e) => setNewHouseholdName(e.target.value)}
            autoFocus
          />
        </div>
      </Modal>

      <Modal
        isOpen={isArchiveModalOpen}
        onClose={() => setIsArchiveModalOpen(false)}
        title="Archive Household?"
        footer={
          <>
            <Button variant="secondary" onClick={() => setIsArchiveModalOpen(false)}>Nevermind</Button>
            <Button variant="danger" onClick={archiveHousehold} disabled={archiving}>
              {archiving ? 'Archiving...' : 'Confirm Archival'}
            </Button>
          </>
        }
      >
        <div className="space-y-4 text-center py-4">
          <div className="w-20 h-20 bg-red-500/10 rounded-full flex items-center justify-center mx-auto text-red-500 mb-4 animate-pulse">
             <ShieldAlert size={40} />
          </div>
          <p className="text-white font-bold text-lg">Are you absolutely sure?</p>
          <p className="text-slate-400 text-sm">
            Archiving this household will restrict access for all members. All historical data will be moved to the <strong>Archival Vault</strong> and can only be restored by the owner.
          </p>
        </div>
      </Modal>
    </div>
  );
};

export default HouseholdRegistry;

import React, { useMemo } from 'react'
import { useAuth } from '../context/AuthContext'
import { useApi } from '../hooks/useApi'
import { SearchableSelect } from './ui/SearchableSelect'

const HouseholdSwitcher: React.FC = () => {
  const { householdId, setHouseholdId } = useAuth()
  const { data: households, loading } = (useApi('/api/user/households') as any)

  const options = useMemo(() => {
    if (!Array.isArray(households)) return []
    return [...households]
      .sort((a: any, b: any) => a.name.localeCompare(b.name))
      .map((h: any) => ({
        value: h.id,
        label: `${h.name} (${h.role})`,
        metadata: { subtext: h.role }
      }))
  }, [households])

  if (loading) return null

  return (
    <div style={{ minWidth: 200 }}>
      <SearchableSelect
        options={options}
        value={householdId || ''}
        onChange={(val) => setHouseholdId(val)}
        placeholder="Select household..."
      />
    </div>
  )
}

export default HouseholdSwitcher

import React, { useState } from 'react'
import { useAuth } from '../context/AuthContext'
import { useToast } from '../context/ToastContext'
import { Button } from './ui/Button'
import { getApiUrl } from '../utils/api'
import { Shield, Home, Users, ArrowRight, LogIn, Loader2 } from 'lucide-react'

type Step = 'choose' | 'join' | 'create'

const HouseholdWizard: React.FC = () => {
  const { token: userToken, refreshProfile, setHouseholdId } = useAuth()
  const { showToast } = useToast()
  const [step, setStep] = useState<Step>('choose')
  const [loading, setLoading] = useState(false)
  const [errorMsg, setErrorMsg] = useState('')
  const [code, setCode] = useState('')
  const [householdName, setHouseholdName] = useState('')

  const finish = async (householdId: string) => {
    await refreshProfile()
    setHouseholdId(householdId)
  }

  const handleJoinByCode = async () => {
    if (!code.trim()) {
      setErrorMsg('Enter your household invite code.')
      return
    }
    if (!userToken) return
    setLoading(true)
    setErrorMsg('')
    try {
      const res = (await fetch(`${getApiUrl()}/api/user/households/join-by-code`, {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${userToken}`,
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({ code: code.trim() })
      }) as any)

      const data: any = await res.json().catch(() => ({}))
      if (!res.ok) {
        setErrorMsg(data.error || 'That invite code could not be used.')
        return
      }
      showToast('Welcome to your household!', 'success')
      finish(data.householdId)
    } catch (err: any) {
      setErrorMsg('Network error. Check your connection and try again.')
    } finally {
      setLoading(false)
    }
  }

  const handleCreate = async () => {
    if (!householdName.trim()) {
      setErrorMsg('Give your household a name.')
      return
    }
    if (!userToken) return
    setLoading(true)
    setErrorMsg('')
    try {
      const res = (await fetch(`${getApiUrl()}/api/user/households`, {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${userToken}`,
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({ name: householdName.trim(), currency: 'USD' })
      }) as any)

      const data: any = await res.json().catch(() => ({}))
      if (!res.ok) {
        setErrorMsg(data.error || 'Could not create your household.')
        return
      }
      showToast('Household created!', 'success')
      finish(data.id)
    } catch (err: any) {
      setErrorMsg('Network error. Check your connection and try again.')
    } finally {
      setLoading(false)
    }
  }

  const back = () => {
    setStep('choose')
    setErrorMsg('')
  }

  return (
    <div className="flex-center min-h-screen p-4 bg-black">
      <div className="w-full max-w-lg p-12 rounded-[3.5rem] bg-white/5 border border-white/5 backdrop-blur-3xl reveal space-y-10 text-center relative overflow-hidden group">
        <div className="absolute -inset-24 bg-primary/5 rounded-full blur-[100px] group-hover:bg-primary/10 transition-all duration-1000"></div>

        <div className="relative space-y-6">
          <div className="w-20 h-20 rounded-3xl bg-primary/10 border border-primary/20 flex items-center justify-center text-primary mx-auto shadow-2xl shadow-primary/20">
            <Home size={32} />
          </div>

          <div>
            <div className="flex items-center justify-center gap-2 mb-2">
              <Shield size={12} className="text-secondary" />
              <p className="text-xs font-black tracking-[0.4em] text-secondary">Get Started</p>
            </div>
            <h2 className="text-4xl font-black italic tracking-tighter leading-tight underline decoration-primary/30 underline-offset-8">Welcome to Ledger</h2>
          </div>

          <p className="text-secondary font-medium leading-relaxed">
            You're not part of a household yet. Join an existing household with an invite code, or start your own financial space.
          </p>
        </div>

        {step === 'choose' && (
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 relative">
            <button
              onClick={() => setStep('join')}
              className="rounded-3xl border border-white/10 bg-white/5 p-6 space-y-3 text-left transition-all hover:border-primary/40 hover:bg-primary/5 active:scale-[0.98]"
            >
              <Users size={24} className="text-primary" />
              <p className="font-bold text-white tracking-wide">Join a Household</p>
              <p className="text-sm text-secondary">Use an invite code from a household owner.</p>
            </button>
            <button
              onClick={() => setStep('create')}
              className="rounded-3xl border border-white/10 bg-white/5 p-6 space-y-3 text-left transition-all hover:border-primary/40 hover:bg-primary/5 active:scale-[0.98]"
            >
              <Home size={24} className="text-primary" />
              <p className="font-bold text-white tracking-wide">Start Your Own</p>
              <p className="text-sm text-secondary">Create a new household you administer.</p>
            </button>
          </div>
        )}

        {step === 'join' && (
          <div className="space-y-4 relative">
            <label className="block text-left text-xs font-bold tracking-widest text-secondary">
              INVITE CODE
              <input
                value={code}
                onChange={(e) => setCode(e.target.value.toUpperCase())}
                onKeyDown={(e) => { if (e.key === 'Enter') handleJoinByCode() }}
                placeholder="ABC123"
                maxLength={12}
                className="mt-2 w-full rounded-2xl border border-white/10 bg-black/40 px-4 py-3 font-mono text-lg tracking-[0.3em] text-white placeholder:text-slate-600 focus:border-primary/50 focus:outline-none"
              />
            </label>
            {errorMsg && <p className="text-red-400 text-xs font-bold tracking-widest">{errorMsg}</p>}
            <div className="flex gap-3">
              <Button variant="glass" onClick={back} className="flex-1">Back</Button>
              <Button onClick={handleJoinByCode} loading={loading} className="flex-1">
                {loading ? <Loader2 size={16} className="animate-spin" /> : <><LogIn size={16} className="mr-2" /> Join</>}
              </Button>
            </div>
          </div>
        )}

        {step === 'create' && (
          <div className="space-y-4 relative">
            <label className="block text-left text-xs font-bold tracking-widest text-secondary">
              HOUSEHOLD NAME
              <input
                value={householdName}
                onChange={(e) => setHouseholdName(e.target.value)}
                onKeyDown={(e) => { if (e.key === 'Enter') handleCreate() }}
                placeholder="Our Household"
                maxLength={100}
                className="mt-2 w-full rounded-2xl border border-white/10 bg-black/40 px-4 py-3 text-white placeholder:text-slate-600 focus:border-primary/50 focus:outline-none"
              />
            </label>
            {errorMsg && <p className="text-red-400 text-xs font-bold tracking-widest">{errorMsg}</p>}
            <div className="flex gap-3">
              <Button variant="glass" onClick={back} className="flex-1">Back</Button>
              <Button onClick={handleCreate} loading={loading} className="flex-1">
                {loading ? <Loader2 size={16} className="animate-spin" /> : <><ArrowRight size={16} className="mr-2" /> Create</>}
              </Button>
            </div>
          </div>
        )}

        <div className="text-xs text-slate-600 font-bold tracking-widest">
          Your data stays yours — secure by design.
        </div>
      </div>
    </div>
  )
}

export default HouseholdWizard

import React, { useState, useCallback, useRef } from 'react';
import { 
  FileCheck, 
  ShieldCheck, 
  Building,
  Layers,
  StickyNote,
  Trash2,
  X
} from 'lucide-react';
import { useToast } from '../context/ToastContext';
import { useApi } from '../hooks/useApi';
import { useAuth } from '../context/AuthContext';
import { getApiUrl } from '../utils/api';
import { Modal } from './ui/Modal';
import ParsingModeSelect from './entity/ParsingModeSelect';
import type { ParsingMode, EntityInput } from '../utils/import/types';
import { useEntityMatching } from '../utils/import/useEntityMatching';
import EntityMatchReview from './entity/EntityMatchReview';

interface ImportReviewProps {
  onImportComplete: () => void;
  scope: 'household' | 'private';
}

const ImportReview: React.FC<ImportReviewProps> = ({ onImportComplete, scope }) => {
  const [file, setFile] = useState<File | null>(null);
  const [workbook, setWorkbook] = useState<any>(null);
  const [availableSheets, setAvailableSheets] = useState<string[]>([]);
  const [selectedSheet, setSelectedSheet] = useState<string>('');
  const [reviewItems, setReviewItems] = useState<any[]>([]);
  const [analyzing, setAnalyzing] = useState(false);
  const [committing, setCommitting] = useState(false);
  const { showToast } = useToast();
  const { user, globalRole } = useAuth() as any;
  const householdId = localStorage.getItem('ledger_householdId');

  // Mapping states
  const [headers, setHeaders] = useState<string[]>([]);
  const [rawRows, setRawRows] = useState<any[]>([]);
  const [columnMapping, setColumnMapping] = useState({
    description: '',
    amount: '',
    date: '',
    category: '',
    notes: ''
  });
  const [showMapping, setShowMapping] = useState(false);

  // Advanced Mapping Configuration States
  const [layoutMode, setLayoutMode] = useState<'rows' | 'cells'>('rows');
  const [staticTargetUser, setStaticTargetUser] = useState<string>('');
  const [staticDate, setStaticDate] = useState<string>('');
  const [fieldPatterns, setFieldPatterns] = useState<Record<string, string>>({
    description: '',
    amount: '',
    date: ''
  });
  const [additionalFields, setAdditionalFields] = useState<{ fieldName: string; column: string; pattern: string }[]>([]);

  // Step management
  const [step, setStep] = useState<'idle' | 'select-mode' | 'mapping' | 'match' | 'review' | 'done'>('idle');
  const [entityInputs, setEntityInputs] = useState<EntityInput[]>([]);
  const match = useEntityMatching(entityInputs);

  // Preview Limit & Modal States
  const [previewLimit, setPreviewLimit] = useState<string>('5');
  const [rawTextContent, setRawTextContent] = useState<string>('');
  const [showFullDoc, setShowFullDoc] = useState(false);

  // Template States
  const [savedTemplates, setSavedTemplates] = useState<Record<string, any>>(() => {
    try {
      const stored = localStorage.getItem('ledger_import_templates');
      return stored ? JSON.parse(stored) : {};
    } catch {
      return {};
    }
  });
  const [templateName, setTemplateName] = useState('');

  const saveTemplate = (name: string) => {
    const tmpl = {
      columnMapping,
      layoutMode,
      fieldPatterns,
      additionalFields,
    };
    const stored = localStorage.getItem('ledger_import_templates');
    const templates = stored ? JSON.parse(stored) : {};
    templates[name.trim()] = tmpl;
    localStorage.setItem('ledger_import_templates', JSON.stringify(templates));
    return templates;
  };

  const handleSaveTemplate = () => {
    if (!templateName.trim()) {
      showToast('Please enter a template name', 'error');
      return;
    }
    const updated = saveTemplate(templateName.trim());
    setSavedTemplates(updated);
    showToast(`Template "${templateName.trim()}" saved`, 'success');
    setTemplateName('');
  };

  const handleDeleteTemplate = (name: string, e: React.MouseEvent) => {
    e.stopPropagation();
    const updated = { ...savedTemplates };
    delete updated[name];
    setSavedTemplates(updated);
    localStorage.setItem('ledger_import_templates', JSON.stringify(updated));
    showToast(`Template "${name}" deleted`, 'success');
  };

  // Fetch household memberships to identify household role
  const { data: householdMemberships } = (useApi<any[]>('/api/user/households') as any);
  const currentMembership = (householdMemberships || []).find((h: any) => h.id === householdId);
  const isHouseholdOwner = currentMembership?.role === 'owner';
  const isPlatformOwner = globalRole === 'owner';

  // Select source endpoint for mapping members
  let membersUrl = '';
  if (isPlatformOwner) {
    membersUrl = '/api/admin/users';
  } else if (isHouseholdOwner && householdId && scope === 'household') {
    membersUrl = `/api/user/households/${householdId}/members`;
  }

  const { data: rawMembers } = (useApi<any>(membersUrl ? membersUrl : null) as any);
  const members = Array.isArray(rawMembers)
    ? rawMembers
    : (rawMembers?.data && Array.isArray(rawMembers.data) ? rawMembers.data : []);

  // Fetch entity lists for matching
  const { data: categoriesList = [] } = (useApi<any[]>('/api/financials/categories') as any);
  const categories = Array.isArray(categoriesList) ? categoriesList : [];
  const { data: providersList = [] } = (useApi<any[]>('/api/user/service-providers') as any);
  const providers = Array.isArray(providersList) ? providersList : [];
  const { data: accountsList = [] } = (useApi<any[]>('/api/financials/accounts') as any);
  const accounts = Array.isArray(accountsList) ? accountsList : [];

  const handleExcelSheetParsing = async (wb: any, sheetName: string) => {
    const ws = wb.getWorksheet(sheetName);
    if (!ws) return;

    const fileHeaders: string[] = [];
    ws.getRow(1).eachCell((cell: any) => {
      if (cell.text) fileHeaders.push(cell.text);
    });
    setHeaders(fileHeaders);

    const rows: any[] = [];
    ws.eachRow((row: any, rowNumber: number) => {
      if (rowNumber === 1) return;
      const rowData: any = {};
      row.eachCell((cell: any, colNumber: number) => {
        const h = fileHeaders[colNumber - 1];
        if (h) rowData[h] = cell.value;
      });
      rows.push(rowData);
    });
    setRawRows(rows);

    setColumnMapping({
      description: fileHeaders.find(h => /desc|name|merchant|payee/i.test(h)) || fileHeaders[0] || '',
      amount: fileHeaders.find(h => /amount|cost|val|price|debit/i.test(h)) || fileHeaders[1] || '',
      date: fileHeaders.find(h => /date|time/i.test(h)) || fileHeaders[2] || '',
      category: fileHeaders.find(h => /cat/i.test(h)) || '',
      notes: fileHeaders.find(h => /note|memo/i.test(h)) || ''
    });
    setShowMapping(true);
  };

  const handleParsingModeSelect = useCallback(async (mode: ParsingMode, predefinedFormat?: string, templateName?: string) => {
    if (!file) return

    if (mode === 'predefined' && (predefinedFormat === 'legacy-expense-tracker' || predefinedFormat === 'ledger-spreadsheet')) {
      showToast('This format is handled by the Legacy Expense Tracker import mode. Please switch to Legacy Expense Tracker mode.', 'error')
      setStep('idle')
      return
    }

    if (mode === 'custom' || (mode === 'auto' && !file.name.endsWith('.xlsx'))) {
      setStep('mapping')
    }

    // For xlsx with auto-detect, parse directly
    if (mode === 'auto' && file.name.endsWith('.xlsx')) {
      setAnalyzing(true)
      try {
        const ExcelJS = (await import('exceljs')).default
        const wb = new ExcelJS.Workbook()
        const arrayBuffer = await file.arrayBuffer()
        await wb.xlsx.load(arrayBuffer)
        setWorkbook(wb as any)
        const sheetNames = (wb.worksheets || []).map((ws: any) => ws.name)
        setAvailableSheets(sheetNames)
        setSelectedSheet(sheetNames[0])
        await handleExcelSheetParsing(wb, sheetNames[0])
      } catch {
        showToast('Failed to load Excel library', 'error')
      } finally {
        setAnalyzing(false)
      }
    }

    // For template mode, apply saved template and show mapping
    if (mode === 'template' && templateName) {
      try {
        const stored = localStorage.getItem('ledger_import_templates')
        if (stored) {
          const templates = JSON.parse(stored)
          const tmpl = templates[templateName]
          if (tmpl) {
            setColumnMapping(tmpl.columnMapping || { description: '', amount: '', date: '', category: '', notes: '' })
            setLayoutMode(tmpl.layoutMode || 'rows')
            setFieldPatterns(tmpl.fieldPatterns || { description: '', amount: '', date: '' })
            setAdditionalFields(tmpl.additionalFields || [])
          }
        }
      } catch {}
      // Parse and show mapping
      await handleFileParse(file)
    }
  }, [file])

  const handleFileParse = async (uploadedFile: File) => {
    setStep('mapping')
    if (uploadedFile.name.endsWith('.xlsx')) {
      setAnalyzing(true);
      setRawTextContent('');
      try {
        const ExcelJS = (await import('exceljs')).default;
        const wb = new ExcelJS.Workbook();
        const arrayBuffer = (await uploadedFile.arrayBuffer() as any);
        await wb.xlsx.load(arrayBuffer);
        setWorkbook(wb as any);
        const sheetNames = (wb.worksheets || []).map((ws: any) => ws.name);
        setAvailableSheets(sheetNames);
        setSelectedSheet(sheetNames[0]);
        await handleExcelSheetParsing(wb, sheetNames[0]);
      } catch (err: any) {
        showToast('Failed to load Excel library', 'error');
      } finally {
        setAnalyzing(false);
      }
    } else if (uploadedFile.name.endsWith('.json')) {
      try {
        const text = await uploadedFile.text();
        setRawTextContent(text);
        const parsed = JSON.parse(text);
        const rows = Array.isArray(parsed) ? parsed : [parsed];
        if (rows.length > 0) {
          const fileHeaders = Object.keys(rows[0] as any);
          setHeaders(fileHeaders);
          setRawRows(rows);
          setColumnMapping({
            description: fileHeaders.find(h => /desc|name|merchant|payee/i.test(h)) || fileHeaders[0] || '',
            amount: fileHeaders.find(h => /amount|cost|val|price|debit/i.test(h)) || fileHeaders[1] || '',
            date: fileHeaders.find(h => /date|time/i.test(h)) || fileHeaders[2] || '',
            category: fileHeaders.find(h => /cat/i.test(h)) || '',
            notes: fileHeaders.find(h => /note|memo/i.test(h)) || ''
          });
          setShowMapping(true);
        }
      } catch (e) {
        showToast('Invalid JSON file', 'error');
      }
    } else if (uploadedFile.name.endsWith('.pdf')) {
      setRawTextContent('');
      setHeaders(['description', 'amount', 'date']);
      setRawRows([{ description: 'PDF Transaction Extraction', amount: 125.50, date: '2026-03-25' }]);
      setColumnMapping({ description: 'description', amount: 'amount', date: 'date', category: '', notes: '' });
      setShowMapping(true);
    } else {
      try {
        const text = await uploadedFile.text();
        setRawTextContent(text);
        const Papa = (await import('papaparse')).default;
        Papa.parse(uploadedFile, {
          header: true,
          skipEmptyLines: true,
          complete: (results) => {
            if (results?.data && results.data.length > 0) {
              const fileHeaders = Object.keys(results.data[0] as any);
              setHeaders(fileHeaders);
              setRawRows(results.data);
              setColumnMapping({
                description: fileHeaders.find(h => /desc|name|merchant|payee/i.test(h)) || fileHeaders[0] || '',
                amount: fileHeaders.find(h => /amount|cost|val|price|debit/i.test(h)) || fileHeaders[1] || '',
                date: fileHeaders.find(h => /date|time/i.test(h)) || fileHeaders[2] || '',
                category: fileHeaders.find(h => /cat/i.test(h)) || '',
                notes: fileHeaders.find(h => /note|memo/i.test(h)) || ''
              });
              setShowMapping(true);
            }
          }
        });
      } catch (err: any) {
        showToast('Failed to load CSV library', 'error');
      }
    }
  }

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const uploadedFile = e.target.files[0];
      setFile(uploadedFile);
      setReviewItems([]);
      setShowMapping(false);
      setStep('select-mode');
    }
  };

  const handleSelectExcelSheet = async (sheet: string) => {
    setSelectedSheet(sheet);
    if (workbook) {
      await handleExcelSheetParsing(workbook, sheet);
    }
  };

  const parseCellCoordinate = (coord: string) => {
    const match = coord.toUpperCase().match(/^([A-Z]+)([0-9]+)$/);
    if (!match) return null;
    const colStr = match[1];
    const rowStr = match[2];

    let colIdx = 0;
    for (let i = 0; i < colStr.length; i++) {
      colIdx = colIdx * 26 + (colStr.charCodeAt(i) - 64);
    }
    colIdx -= 1; // 0-indexed
    const rowIdx = parseInt(rowStr) - 1; // 0-indexed
    return { colIdx, rowIdx };
  };

  const handleAnalyze = () => {
    if (rawRows.length === 0) return;
    setAnalyzing(true);

    const applyPattern = (val: string, pattern: string) => {
      if (!pattern) return val;
      try {
        const rx = new RegExp(pattern);
        const match = val.match(rx);
        if (match) {
          return match[1] || match[0];
        }
      } catch (e) {
        // Ignore bad regex
      }
      return val;
    };

    const getCellValue = (coord: string) => {
      if (!coord) return '';
      if (file?.name.endsWith('.xlsx') && workbook) {
        const ws = workbook.getWorksheet(selectedSheet);
        if (ws) {
          const cell = ws.getCell(coord);
          return cell ? String(cell.value ?? '') : '';
        }
      }
      const parsed = parseCellCoordinate(coord);
      if (!parsed) return '';
      const row = rawRows[parsed.rowIdx];
      if (!row) return '';
      const keys = Object.keys(row as any);
      const key = keys[parsed.colIdx];
      return key ? String(row[key] ?? '') : '';
    };

    try {
      if (layoutMode === 'cells') {
        // Parse coordinate mapping
        let rawDesc = getCellValue(columnMapping.description);
        rawDesc = applyPattern(rawDesc, fieldPatterns.description);

        let rawAmtStr = getCellValue(columnMapping.amount);
        rawAmtStr = applyPattern(rawAmtStr, fieldPatterns.amount);
        const parsedAmount = parseFloat(rawAmtStr.replace(/[^0-9.-]/g, '')) || 0;

        let rawDateStr = getCellValue(columnMapping.date);
        rawDateStr = applyPattern(rawDateStr, fieldPatterns.date);
        const parsedDate = rawDateStr || staticDate || new Date().toISOString().split('T')[0];

        let notesParts = [columnMapping.notes ? getCellValue(columnMapping.notes) : ''];
        additionalFields.forEach(f => {
          if (f.column) {
            let fVal = getCellValue(f.column);
            if (f.pattern) fVal = applyPattern(fVal, f.pattern);
            if (fVal) notesParts.push(`${f.fieldName}: ${fVal}`);
          }
        });

        const record = {
          id: `rev-0-${crypto.randomUUID().slice(0, 8)}`,
          description: rawDesc || 'Cell Extraction Record',
          amount: parsedAmount,
          date: parsedDate,
          category: columnMapping.category ? getCellValue(columnMapping.category) : 'Uncategorized',
          notes: notesParts.filter(Boolean).join(' | '),
          ownerId: staticTargetUser || null,
          ownerName: ''
        };

        setReviewItems([record]);
        setShowMapping(false);
        // Entity extraction for cells mode
        const cats = [record.category].filter(Boolean) as string[]
        const provs = [record.description].filter(Boolean) as string[]
        const cellInputs: EntityInput[] = []
        if (cats.length) cellInputs.push({ group: 'category', names: cats })
        if (provs.length) cellInputs.push({ group: 'provider', names: provs })
        setEntityInputs(cellInputs)
        setStep('match')
      } else {
        // Tabular rows mode
        const mapped = rawRows.map((r: any, i: number) => {
          let rawDesc = String(r[columnMapping.description] || 'Unknown Transaction');
          rawDesc = applyPattern(rawDesc, fieldPatterns.description);

          const rawAmount = r[columnMapping.amount];
          let amtStr = typeof rawAmount === 'number' ? String(rawAmount) : String(rawAmount || '0');
          amtStr = applyPattern(amtStr, fieldPatterns.amount);
          const parsedAmount = parseFloat(amtStr.replace(/[^0-9.-]/g, '')) || 0;

          let rawDate = r[columnMapping.date];
          let dateStr = rawDate instanceof Date 
            ? rawDate.toISOString().split('T')[0] 
            : String(rawDate || '');
          dateStr = applyPattern(dateStr, fieldPatterns.date);
          const parsedDate = dateStr || staticDate || new Date().toISOString().split('T')[0];

          let notesParts = [columnMapping.notes ? String(r[columnMapping.notes] || '') : ''];
          additionalFields.forEach(f => {
            if (f.column) {
              let fVal = String(r[f.column] || '');
              if (f.pattern) fVal = applyPattern(fVal, f.pattern);
              if (fVal) notesParts.push(`${f.fieldName}: ${fVal}`);
            }
          });

          return {
            id: `rev-${i}-${crypto.randomUUID().slice(0, 8)}`,
            description: rawDesc,
            amount: parsedAmount,
            date: parsedDate,
            category: columnMapping.category ? String(r[columnMapping.category] || 'Uncategorized') : 'Uncategorized',
            notes: notesParts.filter(Boolean).join(' | '),
            ownerId: staticTargetUser || null,
            ownerName: ''
          };
        });

        setReviewItems(mapped);
        setShowMapping(false);
        // Entity extraction for tabular mode
        const cats = [...new Set(mapped.map((r: any) => r.category).filter(Boolean))] as string[]
        const provs = [...new Set(mapped.map((r: any) => r.description).filter(Boolean))] as string[]
        const tabInputs: EntityInput[] = []
        if (cats.length) tabInputs.push({ group: 'category', names: cats })
        if (provs.length) tabInputs.push({ group: 'provider', names: provs })
        setEntityInputs(tabInputs)
        setStep('match')
      }
    } catch (e) {
      showToast('Error mapping file. Please check cell coordinates or column config.', 'error');
    } finally {
      setAnalyzing(false);
    }
  };

  const handleMatchConfirm = useCallback(() => {
    const mapping = match.getFinalMapping()
    const updated = reviewItems.map((item: any) => ({
      ...item,
      category: mapping.categoryMap[item.category] || item.category,
      providerId: mapping.providerMap[item.description] || null,
    }))
    setReviewItems(updated)
    setStep('review')
