                <thead>
                  <tr className="bg-white/5 border-b border-white/5 sticky top-0 z-10">
                    {headers.map(h => (
                      <th key={h} className="px-4 py-3 font-black text-slate-400 tracking-wider whitespace-nowrap bg-black/80">{h}</th>
