  return (
    <div
      onDrop={handleDrop}
      onDragOver={(e) => e.preventDefault()}
      className="border-2 border-dashed border-white/10 rounded-3xl p-16 text-center hover:border-emerald-500/30 transition-all cursor-pointer group"
