  return (
    <motion.div 
      initial={{ opacity: 0, y: 10 }}
      animate={{ opacity: 1, y: 0 }}
      className="card mb-6 reveal"
      style={{ borderLeft: '4px solid var(--primary)' }}
    >
      {content}
    </motion.div>
  )
