};

import React from 'react';
import { Check, X } from 'lucide-react';

interface Requirement {
  label: string;
  test: (p: string) => boolean;
}

interface PasswordChecklistProps {
  password: string;
}

export const PasswordChecklist: React.FC<PasswordChecklistProps> = ({ password }) => {
  const requirements: Requirement[] = [
    { label: 'Minimum 8 characters', test: (p) => p.length >= 8 },
    { label: 'At least one uppercase letter', test: (p) => /[A-Z]/.test(p) },
    { label: 'At least one lowercase letter', test: (p) => /[a-z]/.test(p) },
    { label: 'At least one number', test: (p) => /[0-9]/.test(p) },
    { label: 'At least one special character', test: (p) => /[^A-Za-z0-9]/.test(p) },
  ];

  return (
    <div className="space-y-2 p-6 bg-white/5 border border-white/5 rounded-2xl reveal">
      <div className="flex flex-col gap-1 mb-4">
        <div className="text-xs font-black tracking-[0.2em] text-secondary">Security Standards</div>
        <div className="text-[10px] font-bold text-slate-500 tracking-wider">All special characters are accepted</div>
      </div>
      <div className="grid grid-cols-1 gap-3">
        {requirements.map((req, i) => {
          const met = req.test(password);
          return (
            <div key={i} className={`flex items-center gap-3 transition-all ${met ? 'text-primary' : 'text-slate-500'}`}>
              <div className={`w-5 h-5 rounded-full flex items-center justify-center border ${met ? 'bg-primary/20 border-primary/40' : 'bg-white/5 border-white/10'}`}>
                {met ? <Check size={12} strokeWidth={4} /> : <X size={10} className="opacity-40" />}
              </div>
              <span className="text-sm font-bold tracking-tight">{req.label}</span>
            </div>
          );
        })}
      </div>
    </div>
  );
};

import React from 'react';
import { Price } from './Price';
import { groupLiabilitiesByCycle } from '../utils/payCycleUtils';
import { Wallet, ArrowRight, Calendar as CalendarIcon, AlertCircle, MessageSquare, Shield } from 'lucide-react';
import { format, parseISO, isAfter } from 'date-fns';

interface PayCycleTimelineProps {
  paydays: any[];
  liabilities: any[]; // Combined bills & subscriptions
}

export const PayCycleTimeline: React.FC<PayCycleTimelineProps> = ({ paydays, liabilities }) => {
  const cycles = groupLiabilitiesByCycle(liabilities, paydays);
  const now = new Date();

  return (
    <section className="card animate-in fade-in duration-700">
      <div>
        <h3 className="text-lg font-black tracking-tighter italic flex items-center gap-2 mb-1">
          <Wallet size={18} className="text-primary" /> Pay Cycle Timeline
        </h3>
        <p className="text-xs text-secondary font-medium">Bills grouped by the paychecks that cover them, showing disposable balance after each cycle.</p>
      </div>

      <div className="relative space-y-8 pl-4 border-l border-dashed border-white/10 ml-2">
        {cycles.map((cycle, idx) => {
          const isCurrent = isAfter(parseISO(cycle.payday.date), now) || idx === 0;
          const remainderCents = (cycle.payday.amountCents || 0) - cycle.totalCents;

          return (
            <div key={cycle.payday.date + cycle.payday.name} className="relative">
              {/* Payday Node */}
              <div className="absolute -left-[21px] top-0 w-10 h-10 rounded-full bg-black border border-white/10 flex items-center justify-center shadow-2xl z-10">
                <div className={`w-3 h-3 rounded-full ${isCurrent ? 'bg-primary animate-pulse' : 'bg-blue-500'}`} />
              </div>

              <div className="ml-8 space-y-4">
                <div className="flex flex-col sm:flex-row sm:items-center gap-4 justify-between bg-white/5 border border-white/10 p-4 rounded-2xl backdrop-blur-xl">
                  <div>
                    <div className="text-xs font-black tracking-widest text-blue-500 mb-1">
                      {format(parseISO(cycle.payday.date), 'EEEE, MMM do')}
                    </div>
                    <div className="flex items-center gap-2">
                       <h4 className="text-lg font-black italic tracking-tighter">{cycle.payday.name}</h4>
                       {cycle.payday.isOverride && (
                         <span className="flex items-center gap-1.5 px-2 py-0.5 bg-indigo-500/10 border border-indigo-500/20 rounded-md">
                           <Shield size={10} className="text-indigo-400" />
                           <span className="text-[11px] font-black tracking-widest text-indigo-400">Personal Override</span>
                         </span>
                       )}
                    </div>
                  </div>
                  <div className="text-right">
                    <Price amountCents={cycle.payday.amountCents} className="text-2xl font-black tracking-tighter text-white" />
                    <div className="text-xs font-black tracking-widest text-white/30">Estimated Deposit</div>
                  </div>
                </div>

                {cycle.payday.notes && (
                  <div className="flex gap-3 p-3 bg-indigo-500/5 border border-indigo-500/10 rounded-xl">
                    <MessageSquare size={14} className="text-indigo-400 shrink-0 mt-0.5" />
                    <p className="text-[11px] text-indigo-200/60 italic leading-relaxed">
                      {cycle.payday.notes}
                    </p>
                  </div>
                )}

                {/* Bills List for this cycle */}
                <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                  {cycle.items.length > 0 ? cycle.items.map((item: any) => (
                    <div key={item.id} className="flex items-center justify-between p-3 rounded-xl bg-white/[0.02] border border-white/5 group hover:bg-white/[0.05] transition-all">
                      <div className="flex items-center gap-3">
                        <div className={`w-1.5 h-1.5 rounded-full ${item.nextPayDate ? 'bg-indigo-500' : item.dueDate ? 'bg-amber-500' : 'bg-primary'}`} />
                        <div>
                          <div className="text-xs font-bold text-white group-hover:text-primary transition-colors">{item.name || item.description}</div>
                          <div className="text-[11px] font-black tracking-widest text-white/30 truncate max-w-[120px]">
                            {item.dueDate || item.nextBillingDate || item.nextPayDate}
                          </div>
                        </div>
                      </div>
                      <Price amountCents={item.amountCents || item.installmentAmountCents} className="text-xs font-black tracking-widest" />
                    </div>
                  )) : (
                    <div className="col-span-full py-4 text-center border border-dashed border-white/5 rounded-xl text-xs font-black tracking-widest text-white/20">
                      No liabilities detected in this cycle
                    </div>
                  )}
                </div>

                {/* Summary Footer */}
                <div className="flex items-center justify-between p-4 bg-primary/5 border border-primary/20 rounded-2xl">
                  <div className="flex items-center gap-2">
                    <ArrowRight size={14} className="text-primary" />
                    <span className="text-xs font-black tracking-[0.1em] text-white/60">Disposable Balance</span>
                  </div>
                  <div className="flex flex-col items-end">
                    <Price 
                        amountCents={remainderCents} 
                        className={`text-lg font-black tracking-tighter ${remainderCents < 0 ? 'text-red-500' : 'text-primary'}`} 
                    />
                    <div className="text-[11px] font-black tracking-widest opacity-40 italic">After Liabilities</div>
                  </div>
                </div>
