                    ) : <div />}
                    <div className="flex gap-3">
                        <button
                            onClick={onClose}
                        className="px-6 py-2 rounded-xl text-[10px] font-black tracking-widest text-white/40 hover:bg-white/5 transition-all"
                    >
                        Cancel
                    </button>
                    <button
                        onClick={handleSave}
                        disabled={loading}
                        className="px-8 py-2 bg-primary text-white rounded-xl text-[10px] font-black tracking-widest hover:scale-105 active:scale-95 transition-all shadow-lg shadow-primary/20"
                    >
                        {loading ? 'Saving...' : (schedule ? 'Update Income' : 'Add Income Source')}
                    </button>
                </div>
                </div>
            </div>
        </Modal>
    );
};

import React, { useState } from 'react';
import { InlineToast } from './ui/InlineToast';
import { useApi } from '../hooks/useApi';
import { useAuth } from '../context/AuthContext';
import { useToast } from '../context/ToastContext';
import { getApiUrl } from '../utils/api';
import { Price } from './Price';
import { Wallet, Plus, Edit3, Trash2, Calendar, User, TrendingUp, ChevronDown } from 'lucide-react';
import { PayScheduleModal } from './PayScheduleModal';

export const PaySchedulesList: React.FC = () => {
    const { token } = useAuth();
    const { showToast } = useToast();
    const { data: schedules = [], mutate: mutateSchedules } = (useApi('/api/planning/pay-schedules') as any);
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [editingSchedule, setEditingSchedule] = useState<any>(null);
    const [confirmDeleteId, setConfirmDeleteId] = useState<string | null>(null);
    const [expandedId, setExpandedId] = useState<string | null>(null);

    const handleDelete = async (id: string) => {
        if (!token) return;

        const apiUrl = getApiUrl().replace(/\/$/, '');
        const res = (await fetch(`${apiUrl}/api/planning/pay-schedules/${id}`, {
                    method: 'DELETE',
                    headers: { 'Authorization': `Bearer ${token}` }
                }) as any);

        if (res.ok) {
            showToast('Income source removed');
            mutateSchedules();
            setConfirmDeleteId(null);
        }
    };

    // Calculate Projected Monthly Income (Rough estimate based on frequency)
    const projectedMonthlyCents = schedules?.reduce((acc: number, s: any) => {
        const amount = s.estimatedAmountCents || 0;
        switch (s.frequency) {
            case 'weekly': return acc + (amount * 4.33);
            case 'biweekly': return acc + (amount * 2.16);
            case 'semi-monthly': return acc + (amount * 2);
            case 'monthly': return acc + amount;
            case 'quarterly': return acc + (amount / 3);
            case 'biannual': return acc + (amount / 6);
            case 'annually': return acc + (amount / 12);
            case 'biennial': return acc + (amount / 24);
            default: return acc;
        }
    }, 0) || 0;

    return (
        <>
          <section className="card space-y-6">
            <div className="flex flex-wrap items-center justify-between gap-3 mb-2">
                <div className="flex items-center gap-3">
                    <div className="w-10 h-10 rounded-xl bg-primary/10 flex items-center justify-center text-primary flex-shrink-0">
                        <Wallet size={20} />
                    </div>
                    <h3 className="text-lg font-black tracking-tighter italic">Income Pipeline</h3>
                </div>
                <button 
                    onClick={() => { setEditingSchedule(null); setIsModalOpen(true); }}
                    className="flex items-center gap-2 px-4 py-2 bg-primary rounded-xl text-[10px] font-black tracking-widest text-white hover:scale-105 active:scale-95 transition-all shadow-lg shadow-primary/20"
                >
                    <Plus size={14} /> Add Source
                </button>
            </div>
            <p className="text-[10px] text-white/30 font-black tracking-widest w-full">Active Pay Schedules</p>
            <p className="text-xs text-secondary font-medium mt-0.5 w-full">Set up recurring paychecks to forecast cash flow and calculate budget intervals.</p>

            {/* Income Summary Card */}
            <div className="bg-primary/5 border border-primary/20 rounded-2xl p-6 flex flex-col sm:flex-row justify-between items-center gap-6">
                <div className="space-y-1">
                    <div className="flex items-center gap-2 text-[10px] font-black tracking-widest text-primary">
                        <TrendingUp size={14} /> Projected Monthly Total
                    </div>
                    <div className="text-4xl font-black tracking-tighter text-white">
                        <Price amountCents={Math.round(projectedMonthlyCents)} />
                    </div>
                    <p className="text-[10px] text-white/30 italic">Estimated net inflow across all active schedules</p>
                </div>
                <div className="h-20 w-px bg-white/5 hidden sm:block" />
                <div className="text-right">
                    <div className="text-[10px] font-black tracking-widest text-white/40 mb-1">Active Sources</div>
                    <div className="text-2xl font-black text-white">{schedules?.length || 0}</div>
                </div>
            </div>

            <div className="space-y-3">
                {schedules?.map((s: any) => (
                    <div key={s.id} className="group relative flex flex-col p-4 bg-white/[0.02] border border-white/5 rounded-2xl hover:bg-white/[0.05] hover:border-white/10 transition-all">
                        <div className="flex items-center justify-between w-full">
                            <div className="flex items-center gap-4">
                                <div className="w-2 h-8 rounded-full bg-blue-500/20 group-hover:bg-blue-500 transition-all" />
                                <div>
                                    <h4 className="font-bold text-white group-hover:text-primary transition-colors">{s.name}</h4>
                                    <div className="flex flex-wrap items-center gap-3 mt-1">
                                        <div className="flex items-center gap-1 text-[10px] font-black tracking-widest text-white/30">
                                            <Calendar size={10} /> {s.frequency}
                                        </div>
                                        {s.userId && (
                                            <div className="flex items-center gap-1 text-[10px] font-black tracking-widest text-primary/60">
                                                <User size={10} /> Assigned
                                            </div>
                                        )}
                                    </div>
                                </div>
                            </div>

                            <div className="flex items-center gap-6">
                                {(s.upcomingEffectiveDate || s.upcomingAmountCents) && (
                                    <div className="hidden lg:flex flex-col items-end px-3 py-1 bg-emerald-500/10 border border-emerald-500/20 rounded-lg animate-in fade-in slide-in-from-right-2">
                                        <div className="text-[10px] font-bold tracking-wider uppercase text-emerald-400/80">Planned Adjustment</div>
                                        <div className="flex items-center gap-1.5">
                                            <Price amountCents={s.upcomingAmountCents} className="text-xs font-black text-emerald-400" />
                                            <span className="text-[10px] text-emerald-400/60 font-bold">@ {s.upcomingEffectiveDate}</span>
                                        </div>
                                    </div>
                                )}
                                <div className="text-right">
                                    <Price amountCents={s.estimatedAmountCents} className="text-lg font-black tracking-tighter" />
                                    <div className="text-xs font-bold tracking-wider text-white/40">Next: {s.nextPayDate || 'N/A'}</div>
                                </div>

                                <div className="flex items-center">
                                    <button 
                                        onClick={() => setExpandedId(expandedId === s.id ? null : s.id)}
                                        className="p-2 hover:bg-white/10 rounded-xl transition-all text-secondary hover:text-white"
                                        aria-label={expandedId === s.id ? `Collapse ${s.name}` : `Expand ${s.name}`}
                                    >
                                        <ChevronDown size={18} className={`transition-transform duration-200 ${expandedId === s.id ? 'rotate-180' : ''}`} />
                                    </button>
                                </div>
                            </div>
                        </div>

                        {expandedId === s.id && (
                            <div className="mt-3 pt-3 border-t border-white/5 flex justify-between items-center w-full animate-in fade-in slide-in-from-top-1">
                                <div>
                                    {confirmDeleteId === s.id ? (
                                        <InlineToast 
                                            message="Remove schedule?" 
                                            type="confirm" 
                                            onConfirm={() => handleDelete(s.id)} 
                                            onCancel={() => setConfirmDeleteId(null)} 
                                        />
                                    ) : (
                                        <button 
                                            onClick={() => setConfirmDeleteId(s.id)}
                                            className="flex items-center gap-1.5 px-3 py-1.5 bg-red-500/10 text-red-500 hover:bg-red-500/20 rounded-lg text-xs transition-colors"
                                        >
                                            <Trash2 size={14} /> Delete
                                        </button>
                                    )}
                                </div>
                                <div className="flex gap-2">
                                    <button 
                                        onClick={() => { setEditingSchedule(s); setIsModalOpen(true); }}
                                        className="flex items-center gap-1.5 px-3 py-1.5 bg-white/5 border border-white/10 text-white rounded-lg text-xs hover:bg-white/10 transition-colors"
                                    >
                                        <Edit3 size={14} /> Edit details
                                    </button>
                                </div>
                            </div>
                        )}
                    </div>
                ))}

                {(!schedules || schedules.length === 0) && (
                    <div className="py-12 text-center border border-dashed border-white/5 rounded-3xl">
                        <p className="text-sm text-white/20 italic">No income sources configured yet.</p>
                    </div>
                )}
            </div>

        </section>
        <PayScheduleModal 
            isOpen={isModalOpen} 
            onClose={() => setIsModalOpen(false)} 
            onUpdate={() => mutateSchedules()}
            schedule={editingSchedule}
        />
        </>
    );
};

import React from 'react';
import { useAuth } from '../context/AuthContext';
import { useToast } from '../context/ToastContext';
import { Modal } from './ui/Modal';
import { getApiUrl } from '../utils/api';
import { CurrencyInput } from './ui/CurrencyInput';
import { Calendar, DollarSign, MessageSquare, Trash2, Shield, Info } from 'lucide-react';
import { Price } from './Price';

interface PaydayExceptionModalProps {
    payday: {
        id?: string;
        payScheduleId: string;
        date: string;
        originalDate: string;
        name: string;
        amountCents: number;
        notes?: string;
        is_override?: boolean;
    };
    isOpen: boolean;
    onClose: () => void;
    onUpdate: () => void;
}

export const PaydayExceptionModal: React.FC<PaydayExceptionModalProps> = ({ payday, isOpen, onClose, onUpdate }) => {
    const { token } = useAuth();
    const { showToast } = useToast();
    const [loading, setLoading] = React.useState(false);

    // Form State
    const [note, setNote] = React.useState(payday.notes || '');
    const [overrideAmountCents, setOverrideAmountCents] = React.useState<number | null>(payday.is_override ? payday.amountCents : null);
    const [overrideDate, setOverrideDate] = React.useState<string | null>(payday.is_override ? payday.date : null);

    React.useEffect(() => {
        setNote(payday.notes || '');
        setOverrideAmountCents(payday.is_override ? payday.amountCents : null);
        setOverrideDate(payday.is_override ? payday.date : null);
    }, [payday]);

    const handleSave = async () => {
        if (!token) return;
        setLoading(true);

        const apiUrl = getApiUrl().replace(/\/$/, '');
        const res = (await fetch(`${apiUrl}/api/planning/pay-exceptions`, {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json',
                        'Authorization': `Bearer ${token}`
                    },
                    body: JSON.stringify({
                        payScheduleId: payday.payScheduleId,
                        originalDate: payday.originalDate,
                        overrideDate: overrideDate || null,
                        overrideAmountCents: overrideAmountCents || null,
                        note: note || null
                    })
                }) as any);

        if (res.ok) {
            showToast('Private payday exception saved');
            onUpdate();
            onClose();
        } else {
            showToast('Failed to save exception', 'error');
        }
        setLoading(false);
    };

    const handleDelete = async () => {
        if (!payday.id || !token) return;
        setLoading(true);

        const apiUrl = getApiUrl().replace(/\/$/, '');
        const res = (await fetch(`${apiUrl}/api/planning/pay-exceptions/${payday.id}`, {
                    method: 'DELETE',
                    headers: {
                        'Authorization': `Bearer ${token}`
                    }
                }) as any);

        if (res.ok) {
            showToast('Exception cleared - reverted to projected data');
            onUpdate();
            onClose();
        }
        setLoading(false);
    };

    return (
        <Modal isOpen={isOpen} onClose={onClose} title={`Payday: ${payday.name}`}>
            <div className="space-y-6">
                {/* Privacy Badge */}
                <div className="flex items-center gap-2 px-3 py-2 bg-indigo-500/10 border border-indigo-500/20 rounded-xl">
                    <Shield size={14} className="text-indigo-400" />
                    <span className="text-[10px] font-black tracking-widest text-indigo-400">Private Exception</span>
                    <span className="text-[10px] text-indigo-400/60 font-medium italic">— Only visible to you</span>
                </div>

                <div className="grid grid-cols-2 gap-4">
                    <div className="bg-white/5 p-3 rounded-xl border border-white/10">
                        <div className="text-[9px] font-black tracking-widest text-white/40 mb-1">Projected Date</div>
                        <div className="text-sm font-bold text-white/80">{payday.originalDate}</div>
                    </div>
                    <div className="bg-white/5 p-3 rounded-xl border border-white/10">
                        <div className="text-[9px] font-black tracking-widest text-white/40 mb-1">Projected Amount</div>
                        <Price amountCents={payday.amountCents} className="text-sm font-bold" />
                    </div>
                </div>

                <div className="space-y-4">
                    {/* Note Field */}
                    <div className="space-y-2">
                        <label className="text-[10px] font-black tracking-widest text-white/40 flex items-center gap-2">
                            <MessageSquare size={12} /> Personal Note
                        </label>
                        <textarea
                            value={note}
                            onChange={(e) => setNote(e.target.value)}
                            className="w-full bg-black/40 border border-white/10 rounded-xl p-3 text-sm focus:border-indigo-500/50 outline-none transition-all min-h-[100px]"
                            placeholder="Add a bonus note, raise reminder, etc..."
                        />
                    </div>

                    <div className="grid grid-cols-2 gap-4">
                        {/* Amount Override */}
                        <div className="space-y-2">
                            <label className="text-[10px] font-black tracking-widest text-white/40 flex items-center gap-2">
                                <DollarSign size={12} /> Override Amount
                            </label>
                            <CurrencyInput
                                valueCents={overrideAmountCents || 0}
                                onChangeCents={cents => setOverrideAmountCents(cents || null)}
                                placeholder="Optional"
                                className="bg-black/40 border-white/10 focus:border-indigo-500/50"
                            />
                        </div>

                        {/* Date Override */}
                        <div className="space-y-2">
                            <label className="text-[10px] font-black tracking-widest text-white/40 flex items-center gap-2">
                                <Calendar size={12} /> Override Date
                            </label>
                            <input
                                type="date"
                                value={overrideDate || ''}
                                onChange={(e) => setOverrideDate(e.target.value || null)}
                                className="w-full bg-black/40 border border-white/10 rounded-xl p-3 text-sm focus:border-indigo-500/50 outline-none transition-all"
                            />
                        </div>
                    </div>
                </div>

                {/* Info Tip */}
                <div className="flex gap-3 p-3 bg-white/5 rounded-xl border border-dashed border-white/10">
                    <Info size={16} className="text-white/40 shrink-0" />
                    <p className="text-[10px] text-white/40 italic leading-relaxed">
                        Setting an exception will replace the projected payday data on your dashboard.
                        This will not affect other household members' views.
                    </p>
                </div>

                <div className="flex items-center justify-between pt-4 border-t border-white/10">
                    {payday.id ? (
                        <button
                            onClick={handleDelete}
                            disabled={loading}
                            className="flex items-center gap-2 text-[10px] font-black tracking-widest text-red-500 hover:text-red-400 transition-colors"
                        >
                            <Trash2 size={14} /> Clear Exception
                        </button>
                    ) : <div />}

                    <div className="flex gap-3">
                        <button
                            onClick={onClose}
                            className="px-6 py-2 rounded-xl text-[10px] font-black tracking-widest text-white/40 hover:bg-white/5 transition-all"
                        >
                            Cancel
                        </button>
                        <button
                            onClick={handleSave}
                            disabled={loading}
                            className="px-8 py-2 bg-indigo-500 text-white rounded-xl text-[10px] font-black tracking-widest hover:scale-105 active:scale-95 transition-all shadow-lg shadow-indigo-500/20"
                        >
                            {loading ? 'Saving...' : 'Save Exception'}
                        </button>
                    </div>
                </div>
            </div>
        </Modal>
    );
};

import React from 'react'
import { useCurrency } from '../context/CurrencyContext'
import { Masked } from './ui/Masked'

interface PriceProps {
  amountCents: number
  className?: string
  hideCents?: boolean
  options?: Intl.NumberFormatOptions
}

export const Price: React.FC<PriceProps> = ({ amountCents, className, hideCents, options }) => {
  const { formatPrice } = useCurrency()

  const formatted = formatPrice(amountCents, hideCents ? {
    minimumFractionDigits: 0,
    maximumFractionDigits: 0,
    ...options
  } : options)

  return (
    <Masked>
      <span className={className}>{formatted}</span>
    </Masked>
  )
}

import React, { useState } from 'react';
import { Card } from './ui/Card';
import { Button } from './ui/Button';
import { useAuth } from '../context/AuthContext';
import { useToast } from '../context/ToastContext';
import { BookLock } from 'lucide-react';
import { getApiUrl } from '../utils/api';

export const PrivacySettings: React.FC = () => {
  const { token, user } = useAuth();
  const { showToast } = useToast();
  const [isExporting, setIsExporting] = useState(false);
  const [shredMonths, setShredMonths] = useState(12);
  const [shredReason, setShredReason] = useState('');
  const [showShredConfirm, setShowShredConfirm] = useState(false);

  const handleExport = async () => {
    setIsExporting(true);
    try {
      const res = (await fetch(`${getApiUrl()}/api/financials/transactions/export/full`, {
              headers: { 'Authorization': `Bearer ${token}` }
            }) as any);
      const blob = (await res.blob() as any);
      const url = window.URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `ledger-export-${user?.id}.json`;
      a.click();
      showToast('Data export complete', 'success');
    } catch (e: any) {
      showToast('Export failed', 'error');
    } finally {
      setIsExporting(false);
    }
  };

  const handleShred = async () => {
    if (!shredReason) {
      showToast('Please provide a reason for data shredding', 'error');
      return;
    }
    try {
      const res = (await fetch(`${getApiUrl()}/api/privacy/shred`, {
              method: 'POST',
              headers: { 
                'Authorization': `Bearer ${token}`,
                'Content-Type': 'application/json' 
              },
              body: JSON.stringify({ months: shredMonths, reason: shredReason })
            }) as any);
      if (res.ok) {
        showToast(`Successfully shredded data older than ${shredMonths} months`, 'success');
        setShowShredConfirm(false);
        setShredReason('');
      } else {
        throw new Error();
      }
    } catch (e: any) {
      showToast('Shredding failed', 'error');
    }
  };

  return (
    <div className="space-y-6 reveal">
      <Card className="p-8">
        <div className="flex items-center gap-4 mb-2">
          <BookLock className="text-secondary" />
          <h2 className="text-xl font-bold tracking-tight">Privacy & Data Ownership</h2>
        </div>
        <p className="text-sm text-secondary opacity-60 mb-8 font-medium">Download or permanently erase your financial history from the LEDGER platform.</p>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
          {/* Export */}
          <div className="space-y-4">
            <div className="text-xs tracking-widest text-emerald-500 font-bold">Portability</div>
            <h4 className="font-bold">Export My Data</h4>
            <p className="text-sm text-secondary opacity-50">Generate a comprehensive JSON package containing your accounts, transactions, and audit history.</p>
            <Button 
              onClick={handleExport} 
              loading={isExporting}
              className="w-full bg-emerald-500/10 text-emerald-500 hover:bg-emerald-500/20 border-emerald-500/20"
            >
              Request Export
            </Button>
          </div>

          {/* Shred */}
          <div className="space-y-4">
            <div className="text-xs tracking-widest text-red-500 font-bold">Erasure</div>
            <h4 className="font-bold">Privacy Shredder</h4>
            <p className="text-sm text-secondary opacity-50">Permanently delete historical transactions and scrub associated logs. This action is irreversible.</p>

            <div className="flex gap-2">
               {[3, 6, 12, 24].map(m => (
                 <button 
                   key={m}
                   onClick={() => setShredMonths(m)}
                   className={`flex-1 py-1 rounded-lg text-xs font-bold border transition-all ${shredMonths === m ? 'bg-red-500 border-red-500 text-white' : 'bg-white/5 border-white/10 text-secondary'}`}
                 >
                   {m}M+
                 </button>
               ))}
            </div>

            <Button 
              onClick={() => setShowShredConfirm(true)}
              className="w-full bg-red-500/10 text-red-500 hover:bg-red-500/20 border-red-500/20"
            >
              Open Shredder
            </Button>
          </div>
        </div>
      </Card>

      {showShredConfirm && (
          <Card className="max-w-md w-full p-8 border-red-500/50 shadow-[0_0_50px_rgba(239,68,68,0.2)]">
            <h3 className="text-2xl font-black text-red-500 mb-4">Confirm Shredding</h3>
            <p className="text-sm font-medium mb-6">Are you sure you want to delete all data older than **{shredMonths} months**? This cannot be undone.</p>

            <div className="space-y-4">
               <div>
                  <label className="text-xs font-black tracking-widest text-secondary opacity-50 ml-1">Reason for audit log</label>
                  <input 
                    type="text"
                    value={shredReason}
                    onChange={e => setShredReason(e.target.value)}
                    placeholder="e.g., General Privacy Cleanup"
                    className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-sm focus:border-red-500/50 outline-none transition-all"
                  />
               </div>

               <div className="flex gap-3 pt-2">
                 <Button onClick={() => setShowShredConfirm(false)} className="flex-1 bg-white/5 border-white/10">Cancel</Button>
                 <Button onClick={handleShred} className="flex-1 bg-red-600 hover:bg-red-700 text-white border-none">Shred Data</Button>
               </div>
            </div>
          </Card>
      )}
    </div>
  );
};

import React from 'react'
import { Modal } from './ui/Modal'
import { SearchableSelect, SearchableOption } from './ui/SearchableSelect'
import { Price } from './Price'
import { Calendar, Send, CreditCard, Tag, FileText } from 'lucide-react'
import { useApi } from '../hooks/useApi'

interface LedgerDetails {
  accountId: string
  categoryId: string
  transactionDate: string
  status: string
  chargeDescriptorId: string
  billId?: string
}

