          </div>
        ) : (
          <div className="bg-orange-500/5 border border-orange-500/10 rounded-2xl p-4">
            <p className="text-sm text-orange-200/80 font-medium">
              Moving {items.length} items to the transaction ledger.
            </p>
          </div>
        )}

        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div>
            <label className="text-xs font-black tracking-widest text-secondary mb-1 flex items-center gap-1.5">
              <FileText size={14} className="text-orange-500" /> Charge Descriptor
            </label>
            <p className="text-[10px] text-slate-500 font-bold mb-2">
              Optional — label to standardize descriptions.
            </p>
            <SearchableSelect
              options={chargeDescriptorOptions}
              value={ledgerDetails.chargeDescriptorId || ''}
              onChange={(id) => {
                setLedgerDetails({ ...ledgerDetails, chargeDescriptorId: id || '' })
              }}
              placeholder="Select or create descriptor..."
              onCreate={handleCreateChargeDescriptor}
            />
          </div>
          <div>
            <label className="text-xs font-black tracking-widest text-secondary mb-1 flex items-center justify-between">
              <span className="flex items-center gap-1.5"><span className="text-sm">🔗</span> Linked Bill / Instance</span>
              <span className="text-[9px] text-orange-400 font-normal">Layer 2</span>
            </label>
            <p className="text-[10px] text-slate-500 font-bold mb-2">
              Link directly to a specific member's bill instance.
            </p>
            <SearchableSelect
              options={billInstanceOptions}
              value={ledgerDetails.billId || ''}
              onChange={(id) => {
                setLedgerDetails({ ...ledgerDetails, billId: id || '' })
              }}
              placeholder="Select bill instance..."
            />
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div>
            <label className="text-xs font-black tracking-widest text-secondary mb-1 flex items-center gap-1.5">
              <CreditCard size={14} className="text-orange-500" /> Payment Account
            </label>
            <p className="text-[10px] text-slate-500 font-bold mb-2">
              The account used for payment. Type a name to create a new one.
            </p>
            <SearchableSelect
              options={accountOptions}
              value={ledgerDetails.accountId}
              onChange={(val) => setLedgerDetails({ ...ledgerDetails, accountId: val })}
              placeholder="Choose or create Account..."
              onCreate={handleCreateAccount}
            />
          </div>
          <div>
            <label className="text-xs font-black tracking-widest text-secondary mb-1 flex items-center gap-1.5">
              <Tag size={14} className="text-orange-500" /> Budget Category
            </label>
            <p className="text-[10px] text-slate-500 font-bold mb-2">
              Category for expense reports. Type a name to create a new one.
            </p>
            <SearchableSelect
              options={categoryOptions}
              value={ledgerDetails.categoryId}
              onChange={(val) => setLedgerDetails({ ...ledgerDetails, categoryId: val })}
              placeholder="Choose or create Category..."
              onCreate={handleCreateCategory}
            />
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div>
            <label className="text-xs font-black tracking-widest text-secondary mb-1 flex items-center gap-1.5">
              <Calendar size={14} className="text-orange-500" /> Transaction Date
            </label>
            <p className="text-[10px] text-slate-500 font-bold mb-2">
              The date the transaction cleared or occurred.
            </p>
            <input
              type="date"
              value={ledgerDetails.transactionDate}
              onChange={(e) =>
                setLedgerDetails({ ...ledgerDetails, transactionDate: e.target.value })
              }
              className="w-full bg-black/60 border border-white/10 rounded-xl p-3 text-sm text-white focus:border-orange-500/50 outline-none font-bold"
            />
          </div>
          <div>
            <label className="text-xs font-black tracking-widest text-secondary mb-1 flex items-center gap-1.5">
              Reconciliation Status
            </label>
            <p className="text-[10px] text-slate-500 font-bold mb-2">
              Set whether this transaction has settled in your account.
            </p>
            <div className="flex gap-2">
              {[
                { value: 'paid', label: 'Paid / Cleared' },
                { value: 'pending', label: 'Pending / Uncleared' },
              ].map((s) => (
                <button
                  key={s.value}
                  type="button"
                  onClick={() => setLedgerDetails({ ...ledgerDetails, status: s.value })}
                  className={`flex-1 py-3 rounded-xl text-[10px] font-black tracking-widest transition-all border ${
                    ledgerDetails.status === s.value
                      ? 'bg-orange-500 border-orange-400 text-white'
                      : 'bg-black/40 border-white/10 text-secondary'
                  }`}
                >
                  {s.label}
                </button>
              ))}
            </div>
          </div>
        </div>

        <button
          onClick={onSubmit}
          disabled={!ledgerDetails.accountId}
          className="w-full bg-orange-500 hover:bg-orange-600 disabled:opacity-50 disabled:cursor-not-allowed text-white font-black tracking-widest py-4 rounded-2xl transition-all shadow-xl shadow-orange-500/20 flex items-center justify-center gap-2"
        >
          <Send size={18} />
          Move to Ledger
        </button>
      </div>
    </Modal>
  )
}

import React, { useState } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import { useApi, globalMutate } from '../hooks/useApi'
import { useAuth } from '../context/AuthContext'
import { Flag, ShieldAlert, ArrowRightLeft, HandCoins, Copy, Trash2, Plus, Hash } from 'lucide-react'
import { getApiUrl } from '../utils/api'
import { TrackedExpenseList } from './TrackedExpenseList'
import { CurrencyInput } from './ui/CurrencyInput'
import { SearchableSelect, SearchableOption } from './ui/SearchableSelect'
import { Checkbox } from './ui/Checkbox'
import { ConfirmationNumberBuilder, ConfirmationNumberItem } from './ui/ConfirmationNumberBuilder'

interface QuickAttentionAddProps {
  onAdded: () => void;
}

interface FormInstance {
  id: string;
  description: string;
  amountCents: number;
  chargeDescriptorId: string;
  billId: string;
  confirmationNumber: string;
  confirmationNumbers: ConfirmationNumberItem[];
  attentionRequired: boolean;
  needsBalanceTransfer: boolean;
  transferTiming: string; // 'same_day' | 'future'
  isBorrowed: boolean;
  borrowType: 'member' | 'external';
  borrowUserId: string;
  borrowCustomName: string;
  borrowPaybackDate: string;
  borrowPaybackMethod: string;
  borrowNotes: string;
  recordHouseholdIou: boolean;
  borrowSource: string;
  transactionDate: string;
  createdAt: string;
}

const TRANSFER_TIMING_OPTIONS: SearchableOption[] = [
  { value: 'same_day', label: 'Must do Same Day (Default)' },
  { value: 'future', label: 'Can do in Future' }
];

const DEFAULT_REIMBURSEMENT_METHODS: SearchableOption[] = [
  { value: 'venmo', label: 'Venmo' },
  { value: 'zelle', label: 'Zelle' },
  { value: 'bank_transfer', label: 'Bank Transfer' },
  { value: 'cash', label: 'Cash' },
  { value: 'manual', label: 'Manual' },
  { value: 'paypal', label: 'PayPal' },
  { value: 'cashapp', label: 'Cash App' },
  { value: 'apple_pay', label: 'Apple Pay' }
];

export const QuickAttentionAdd: React.FC<QuickAttentionAddProps> = ({ onAdded }) => {
  const { householdId, user } = useAuth()
  const { data: chargeDescriptors = [] } = (useApi('/api/financials/charge-descriptors') as any)
  const { data: bills = [] } = (useApi('/api/planning/bills') as any)
  const { data: subscriptions = [] } = (useApi('/api/planning/subscriptions') as any)
  const { data: members = [] } = (useApi(householdId ? `/api/user/households/${householdId}/members` : null) as any)

  const otherMembers = (members || []).filter((m: any) => (m.user?.id || m.id) !== user?.id)

  const [customLenders, setCustomLenders] = useState<string[]>(['Parent', 'Friend', 'Bank Loan'])
  const [customReimbursementMethods, setCustomReimbursementMethods] = useState<SearchableOption[]>(DEFAULT_REIMBURSEMENT_METHODS)

  const createEmptyInstance = (): FormInstance => ({
    id: Math.random().toString(36).substr(2, 9),
    description: '',
    amountCents: 0,
    chargeDescriptorId: '',
    billId: '',
    confirmationNumber: '',
    confirmationNumbers: [],
    attentionRequired: false,
    needsBalanceTransfer: false,
    transferTiming: 'same_day', // Default to Must do Same Day
    isBorrowed: false,
    borrowType: otherMembers.length > 0 ? 'member' : 'external',
    borrowUserId: otherMembers[0]?.user?.id || otherMembers[0]?.id || '',
    borrowCustomName: '',
    borrowPaybackDate: '',
    borrowPaybackMethod: 'venmo',
    borrowNotes: '',
    recordHouseholdIou: true,
    borrowSource: '',
    transactionDate: (() => { const d = new Date(); return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}` })(),
    createdAt: (() => { const d = new Date(); return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}` })()
  });

  const [instances, setInstances] = useState<FormInstance[]>(() => [createEmptyInstance()]);
  const [loading, setLoading] = useState(false)
  const [refreshTrigger, setRefreshTrigger] = useState(0)
  const [showInfo, setShowInfo] = useState(false)

  const handleDuplicate = (index: number) => {
    const source = instances[index];
    const copy: FormInstance = {
      ...source,
      id: Math.random().toString(36).substr(2, 9)
    };
    setInstances(prev => {
      const next = [...prev];
      next.splice(index + 1, 0, copy);
      return next;
    });
  };

  const handleRemove = (index: number) => {
    setInstances(prev => prev.filter((_, idx) => idx !== index));
  };

  const handleUpdate = (index: number, updates: Partial<FormInstance>) => {
    setInstances(prev => prev.map((inst, idx) => idx === index ? { ...inst, ...updates } : inst));
  };

  const handleAddBlank = () => {
    setInstances(prev => [...prev, createEmptyInstance()]);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    const validInstances = instances.filter(inst => inst.amountCents > 0 && inst.description.trim() !== '');
    if (validInstances.length === 0) {
      return;
    }
    setLoading(true)

    try {
      const promises = validInstances.map(inst => {
        let formattedBorrowSource = inst.borrowSource
        let targetUserId: string | null = null

        if (inst.isBorrowed) {
          if (inst.borrowType === 'member') {
            const memberObj = (members || []).find((m: any) => (m.user?.id || m.id) === inst.borrowUserId)
            const lenderName = memberObj?.displayName || memberObj?.user?.displayName || memberObj?.user?.username || memberObj?.email || 'Household Member'
            targetUserId = inst.borrowUserId || null
            formattedBorrowSource = `IOU: ${lenderName}${inst.borrowPaybackDate ? ` • Repay by ${inst.borrowPaybackDate}` : ''}${inst.borrowPaybackMethod ? ` via ${inst.borrowPaybackMethod.toUpperCase()}` : ''}${inst.borrowNotes ? ` (${inst.borrowNotes})` : ''}`
          } else {
            const lenderName = inst.borrowCustomName.trim() || 'External Lender'
            formattedBorrowSource = `Borrowed from ${lenderName}${inst.borrowPaybackDate ? ` • Repay by ${inst.borrowPaybackDate}` : ''}${inst.borrowPaybackMethod ? ` via ${inst.borrowPaybackMethod.toUpperCase()}` : ''}${inst.borrowNotes ? ` (${inst.borrowNotes})` : ''}`
          }
        }

        const validConfirmationNumbers = (inst.confirmationNumbers || []).filter(cn => cn.value && cn.value.trim() !== '').map((cn, i) => ({
          id: crypto.randomUUID(),
          category: cn.category,
          customCategoryLabel: cn.category === 'custom' ? (cn.customCategoryLabel || null) : null,
          value: cn.value.trim(),
          isPrimary: i === 0,
          sortOrder: i
        }))

        const primaryConfirmationNumber = inst.confirmationNumber?.trim() || validConfirmationNumbers[0]?.value || null

        return fetch(`${getApiUrl()}/api/tracked-expenses`, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'Authorization': `Bearer ${localStorage.getItem('ledger_token')}`,
            'x-household-id': localStorage.getItem('ledger_householdId') || ''
          },
          body: JSON.stringify({
            description: inst.description,
            amountCents: inst.amountCents,
            chargeDescriptorId: inst.chargeDescriptorId || null,
            billId: inst.billId || null,
            confirmationNumber: primaryConfirmationNumber,
            confirmationNumbers: validConfirmationNumbers,
            attentionRequired: inst.attentionRequired,
            needsBalanceTransfer: inst.needsBalanceTransfer,
            transferTiming: inst.needsBalanceTransfer ? (inst.transferTiming || 'same_day') : null,
            isBorrowed: inst.isBorrowed,
            borrowSource: inst.isBorrowed ? formattedBorrowSource : null,
            recordHouseholdIou: inst.isBorrowed && inst.borrowType === 'member' && inst.recordHouseholdIou,
            iouToUserId: targetUserId,
            iouAmountCents: inst.amountCents,
            iouNotes: inst.borrowNotes || `Borrowed funds for: ${inst.description}`,
            createdAt: inst.transactionDate,
          })
        })
      });

      await Promise.all(promises);

      setInstances([createEmptyInstance()]);
      setRefreshTrigger(prev => prev + 1);
      globalMutate();
      onAdded();
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  }

  const billInstanceOptions: SearchableOption[] = useMemo(() => {
    const list: SearchableOption[] = []

    // Process Subscriptions
    const subList = Array.isArray(subscriptions) ? subscriptions : subscriptions?.data || []
    for (const sub of subList) {
      const owner = (members || []).find((m: any) => (m.user?.id || m.id) === sub.ownerId)
      const ownerName = owner?.displayName || owner?.user?.displayName || owner?.user?.username || (sub.ownerId === user?.id ? 'You' : 'Household')
      const formattedAmount = sub.amountCents ? `$${(sub.amountCents / 100).toFixed(2)}` : ''
      const cycle = sub.billingCycle ? `/${sub.billingCycle.replace('ly', '')}` : ''
      const renew = sub.nextBillingDate ? ` • Renews ${sub.nextBillingDate}` : ''
      list.push({
        value: sub.id,
        label: `${sub.name} • ${ownerName}`,
        icon: <span className="text-base leading-none">🔁</span>,
        metadata: {
          subtext: `${formattedAmount}${cycle}${renew}`
        }
      })
    }

    // Process Recurring / Single Bills
    const billList = Array.isArray(bills) ? bills : bills?.data || []
    for (const bill of billList) {
      const owner = (members || []).find((m: any) => (m.user?.id || m.id) === bill.ownerId)
      const ownerName = owner?.displayName || owner?.user?.displayName || owner?.user?.username || (bill.ownerId === user?.id ? 'You' : 'Household')
      const formattedAmount = bill.amountCents ? `$${(bill.amountCents / 100).toFixed(2)}` : ''
      const due = bill.dueDate ? ` • Due ${bill.dueDate}` : ''
      list.push({
        value: bill.id,
        label: `${bill.name} • ${ownerName}`,
        icon: <span className="text-base leading-none">🧾</span>,
        metadata: {
          subtext: `${formattedAmount}${due}`
        }
      })
    }

    return list.sort((a, b) => a.label.localeCompare(b.label))
  }, [subscriptions, bills, members, user?.id])

  return (
    <div className="card mb-6 border-l-4 border-l-orange-500 overflow-hidden relative">
      <div className="absolute top-0 right-0 w-32 h-32 bg-orange-500/10 blur-3xl rounded-full"></div>

      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-2 mb-3 relative z-20">
        <div className="flex items-center gap-2">
          <Flag className="text-orange-500" size={18} />
          <h3 className="font-bold text-white tracking-widest text-sm text-orange-100">Add Tracked Expense</h3>
        </div>
        <div className="flex items-center gap-2 self-start sm:self-auto">
          <button 
            type="button"
            onClick={handleAddBlank}
            className="text-[10px] font-black tracking-widest text-emerald-400 hover:text-white px-2.5 py-1 rounded-xl bg-emerald-500/10 hover:bg-emerald-500/20 transition-all border border-emerald-500/20 flex items-center gap-1 cursor-pointer"
          >
            <Plus size={10} /> Add Instance
          </button>
          <button 
            type="button"
            onClick={() => setShowInfo(!showInfo)}
            className="text-[10px] font-black tracking-widest text-orange-400 hover:text-white px-2.5 py-1 rounded-xl bg-orange-500/10 hover:bg-orange-500/20 transition-all border border-orange-500/20 cursor-pointer"
          >
            {showInfo ? 'Hide Guide' : 'Show Guide'}
          </button>
        </div>
      </div>

      {showInfo && (
        <div className="mb-5 p-4 bg-orange-500/5 border border-orange-500/10 rounded-2xl text-xs space-y-2.5 leading-relaxed text-orange-200/80 animate-in slide-in-from-top-2 duration-300">
          <p className="font-bold text-orange-400">
            💡 What are Tracked Expenses?
          </p>
          <p>
            Tracked Expenses serve as a "staging area" to draft pending items, log upcoming bills, or flag transactions that require verification before committing them permanently to the main ledger.
          </p>
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 pt-1">
            <div className="space-y-1">
              <span className="font-black tracking-wider text-[9px] text-orange-300">Use Cases</span>
              <ul className="list-disc pl-4 space-y-0.5 text-[11px]">
                <li>Logging borrowed funds needing repayment.</li>
                <li>Staging items requiring a balance transfer.</li>
                <li>Drafting quick payments to audit/reconcile later.</li>
              </ul>
            </div>
            <div className="space-y-1">
              <span className="font-black tracking-wider text-[9px] text-orange-300">Quick Guide</span>
              <ul className="list-decimal pl-4 space-y-0.5 text-[11px]">
                <li>Enter the Amount and Description.</li>
                <li>Toggle optional flags (attention, borrow, transfer).</li>
                <li>Click Add to place it in the Pending Staging List.</li>
              </ul>
            </div>
          </div>
        </div>
      )}

      <form onSubmit={handleSubmit} className="space-y-6 relative z-10">
        <div className="space-y-6">
          {instances.map((inst, index) => (
            <div 
              key={inst.id} 
              className={`p-4 bg-black/20 border rounded-2xl relative transition-all ${
                instances.length > 1 ? 'border-white/10 hover:border-orange-500/20' : 'border-transparent'
              }`}
            >
              {/* Instance Control Buttons */}
              <div className="absolute top-3 right-3 flex items-center gap-1.5 z-20">
                <button
                  type="button"
                  onClick={() => handleDuplicate(index)}
                  className="p-1.5 text-secondary hover:text-primary hover:bg-white/5 rounded-lg transition-all cursor-pointer animate-in fade-in"
                  title="Duplicate this instance"
                >
                  <Copy size={13} />
                </button>
                {instances.length > 1 && (
                  <button
                    type="button"
                    onClick={() => handleRemove(index)}
                    className="p-1.5 text-red-400 hover:text-red-300 hover:bg-red-500/10 rounded-lg transition-all cursor-pointer animate-in fade-in"
                    title="Remove this instance"
                  >
                    <Trash2 size={13} />
                  </button>
                )}
              </div>

              {instances.length > 1 && (
                <div className="text-[9px] tracking-widest text-orange-400/60 font-black mb-3">
                  Instance #{index + 1}
                </div>
              )}

              <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                <div>
                  <label className="text-xs tracking-widest text-secondary mb-1 flex">Amount</label>
                  <CurrencyInput 
                    valueCents={inst.amountCents} 
                    onChangeCents={cents => handleUpdate(index, { amountCents: cents })}
                    placeholder="0.00" 
                    required 
                    className="focus:border-orange-500/50"
                  />
                </div>
                <div>
                  <label className="text-xs tracking-widest text-secondary mb-1 flex">Transaction date</label>
                  <input 
                    type="date" 
                    value={inst.transactionDate} 
                    onChange={e => handleUpdate(index, { transactionDate: e.target.value })}
                    style={{ colorScheme: 'dark' }}
                    className="w-full bg-black/40 border border-white/10 rounded-xl p-3 text-white focus:outline-none focus:border-orange-500/50 transition-colors animate-in"
                    required
                  />
                </div>
                <div className="md:col-span-2">
                  <label className="text-xs tracking-widest text-secondary mb-1 flex">Charge Descriptor</label>
                  <SearchableSelect
                    options={(chargeDescriptors || []).map((cd: any) => ({ value: cd.id, label: cd.name }))}
                    value={inst.chargeDescriptorId}
                    onChange={(val) => {
                      const cd = (chargeDescriptors || []).find((c: any) => c.id === val)
                      handleUpdate(index, { chargeDescriptorId: val, description: cd?.name || inst.description })
                    }}
                    placeholder="Choose or create descriptor..."
                  />
                </div>
                <div className="md:col-span-2">
                  <label className="text-xs tracking-widest text-secondary mb-1 flex items-center justify-between">
                    <span>Linked Bill / Subscription</span>
                    <span className="text-[10px] text-orange-400/80 font-normal">Layer 2 Instance</span>
                  </label>
                  <SearchableSelect
                    options={billInstanceOptions}
                    value={inst.billId || ''}
                    onChange={(val) => {
                      const subList = Array.isArray(subscriptions) ? subscriptions : subscriptions?.data || []
                      const billList = Array.isArray(bills) ? bills : bills?.data || []
                      const matched = [...subList, ...billList].find((b: any) => b.id === val)
                      const updates: Partial<FormInstance> = { billId: val }
                      if (matched && (!inst.amountCents || inst.amountCents === 0)) {
                        updates.amountCents = matched.amountCents || 0
                      }
                      if (matched && !inst.description) {
                        updates.description = matched.name
                      }
                      handleUpdate(index, updates)
                    }}
                    placeholder="Select specific bill instance..."
                  />
                </div>
                <div className="md:col-span-4">
                  <label className="text-xs tracking-widest text-secondary mb-1 flex">Description</label>
                  <input 
                    type="text" 
                    value={inst.description} 
                    onChange={e => handleUpdate(index, { description: e.target.value })}
                    placeholder="What was this for?" 
                    required 
                    className="w-full bg-black/40 border border-white/10 rounded-xl p-3 text-white focus:outline-none focus:border-orange-500/50 transition-colors"
                  />
                </div>
                {/* Enhanced Categorized Confirmation Numbers */}
                <div className="md:col-span-4">
                  <ConfirmationNumberBuilder
                    value={inst.confirmationNumber}
                    onChangeValue={val => handleUpdate(index, { confirmationNumber: val })}
                    confirmationNumbers={inst.confirmationNumbers}
                    onChangeNumbers={items => handleUpdate(index, { confirmationNumbers: items })}
                    accentColor="orange"
                    compact={true}
                  />
                </div>
              </div>

              <div className="flex items-center gap-4 py-2 mt-3 border-y border-white/5">
                <label className="flex items-center gap-2 cursor-pointer group">
                  <Checkbox 
                    checked={inst.attentionRequired} 
                    onChange={v => handleUpdate(index, { attentionRequired: v })} 
                    iconClassName="text-orange-500"
                  />
                  <span className="text-sm font-bold opacity-80 group-hover:opacity-100 transition-opacity flex items-center gap-1.5">
                    <ShieldAlert size={14} className={inst.attentionRequired ? "text-orange-400" : ""} />
                    Flag for Future Attention
                  </span>
                </label>
              </div>

              <AnimatePresence>
                {inst.attentionRequired && (
                  <motion.div 
                    initial={{ height: 0, opacity: 0 }}
                    animate={{ height: 'auto', opacity: 1 }}
                    exit={{ height: 0, opacity: 0 }}
                    className="overflow-hidden"
                  >
                    <div className="bg-orange-500/5 border border-orange-500/10 rounded-2xl p-4 mt-2 space-y-5">

                      {/* Requires Balance Transfer */}
                      <div className="flex flex-col sm:flex-row gap-3 items-start sm:items-center justify-between">
                        <label className="flex items-center gap-2 cursor-pointer flex-1">
                          <Checkbox 
                            checked={inst.needsBalanceTransfer} 
                            onChange={v => handleUpdate(index, { 
                              needsBalanceTransfer: v,
                              transferTiming: inst.transferTiming || 'same_day'
                            })}
                            iconClassName="text-orange-500"
                          />
                          <span className="text-xs sm:text-sm font-bold flex items-center gap-1.5 text-orange-200">
                            <ArrowRightLeft size={16} /> Requires Balance Transfer
                          </span>
                        </label>

                        {inst.needsBalanceTransfer && (
                          <div className="flex items-center gap-2 w-full sm:w-auto min-w-[240px]">
                            <span className="text-[10px] font-black uppercase tracking-wider text-orange-300/70 hidden sm:inline">Timing:</span>
                            <div className="w-full sm:w-64">
                              <SearchableSelect 
                                options={TRANSFER_TIMING_OPTIONS}
                                value={inst.transferTiming || 'same_day'} 
                                onChange={val => handleUpdate(index, { transferTiming: val })}
                                placeholder="Select transfer timing..."
                              />
                            </div>
                          </div>
                        )}
                      </div>

                      <div className="w-full h-px bg-white/5"></div>

                      {/* Funds Were Borrowed (Linked to IOU & Payback Details) */}
                      <div className="space-y-3">
                        <label className="flex items-center gap-2 cursor-pointer">
                          <Checkbox 
                            checked={inst.isBorrowed} 
                            onChange={v => handleUpdate(index, { isBorrowed: v })}
                            iconClassName="text-orange-500"
                          />
                          <span className="text-xs sm:text-sm font-bold flex items-center gap-1.5 text-orange-200">
                            <HandCoins size={16} /> Funds were Borrowed
                          </span>
                        </label>

                        {inst.isBorrowed && (
                          <div className="p-3.5 bg-black/40 border border-orange-500/20 rounded-xl space-y-4 animate-in slide-in-from-top-1 duration-200">
                            <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-2 border-b border-white/5 pb-2">
                              <span className="text-[10px] font-black uppercase tracking-wider text-orange-300">
                                Who to Reimburse & Payback Details
                              </span>
                              {otherMembers.length > 0 && (
                                <div className="flex bg-black/40 rounded-lg p-0.5 border border-white/10 self-start sm:self-auto">
                                  <button
                                    type="button"
                                    onClick={() => handleUpdate(index, { borrowType: 'member' })}
                                    className={`px-2.5 py-1 text-[10px] font-black rounded-md transition-all cursor-pointer ${
                                      inst.borrowType === 'member' ? 'bg-orange-500 text-black shadow-sm' : 'text-white/60 hover:text-white'
                                    }`}
                                  >
                                    Household Member
                                  </button>
                                  <button
                                    type="button"
                                    onClick={() => handleUpdate(index, { borrowType: 'external' })}
                                    className={`px-2.5 py-1 text-[10px] font-black rounded-md transition-all cursor-pointer ${
                                      inst.borrowType === 'external' ? 'bg-orange-500 text-black shadow-sm' : 'text-white/60 hover:text-white'
                                    }`}
                                  >
                                    External / Other
                                  </button>
                                </div>
                              )}
                            </div>

                            {/* Lender Selection */}
                            <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                              {inst.borrowType === 'member' && otherMembers.length > 0 ? (
                                <div className="space-y-1">
                                  <label className="text-[10px] font-bold text-secondary uppercase tracking-wider block">
                                    Household Member (IOU Recipient)
                                  </label>
                                  <SearchableSelect
                                    options={memberOptions}
                                    value={inst.borrowUserId || otherMembers[0]?.user?.id || otherMembers[0]?.id || ''}
                                    onChange={val => handleUpdate(index, { borrowUserId: val })}
                                    placeholder="Search household member..."
                                  />
                                </div>
                              ) : (
                                <div className="space-y-1">
                                  <label className="text-[10px] font-bold text-secondary uppercase tracking-wider block">
                                    Lender / Entity Name
                                  </label>
                                  <SearchableSelect
                                    options={lenderOptions}
                                    value={inst.borrowCustomName}
                                    onChange={val => handleUpdate(index, { borrowCustomName: val })}
                                    onCreate={(search) => {
                                      const trimmed = search.trim()
                                      if (trimmed) {
                                        setCustomLenders(prev => Array.from(new Set([...prev, trimmed])))
                                        handleUpdate(index, { borrowCustomName: trimmed })
                                        return trimmed
                                      }
                                    }}
                                    placeholder="Search or enter lender/entity name..."
                                  />
                                </div>
                              )}

                              {/* Target Payback Date */}
                              <div className="space-y-1">
                                <label className="text-[10px] font-bold text-secondary uppercase tracking-wider block">
                                  Target Payback Date (Optional)
                                </label>
                                <input
                                  type="date"
                                  value={inst.borrowPaybackDate}
                                  onChange={e => handleUpdate(index, { borrowPaybackDate: e.target.value })}
                                  style={{ colorScheme: 'dark' }}
                                  className="w-full bg-black/60 border border-white/10 rounded-xl p-2.5 text-xs font-bold text-white outline-none focus:border-orange-400"
                                />
                              </div>
                            </div>

                            {/* Payback Method & Terms */}
                            <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                              <div className="space-y-1">
                                <label className="text-[10px] font-bold text-secondary uppercase tracking-wider block">
                                  Reimbursement Method
                                </label>
                                <SearchableSelect
                                  options={customReimbursementMethods}
                                  value={inst.borrowPaybackMethod || 'venmo'}
                                  onChange={val => handleUpdate(index, { borrowPaybackMethod: val })}
                                  onCreate={(search) => {
                                    const trimmed = search.trim()
                                    if (trimmed) {
                                      const newOpt: SearchableOption = { value: trimmed.toLowerCase().replace(/\s+/g, '_'), label: trimmed }
                                      setCustomReimbursementMethods(prev => [...prev, newOpt])
                                      handleUpdate(index, { borrowPaybackMethod: newOpt.value })
                                      return newOpt.value
                                    }
                                  }}
                                  placeholder="Select or add method..."
                                />
                              </div>

                              <div className="space-y-1">
                                <label className="text-[10px] font-bold text-secondary uppercase tracking-wider block">
                                  Payback Terms / Notes
                                </label>
                                <input
                                  type="text"
                                  value={inst.borrowNotes}
                                  onChange={e => handleUpdate(index, { borrowNotes: e.target.value })}
                                  placeholder="e.g. Repay from next Friday paycheck"
                                  className="w-full bg-black/60 border border-white/10 rounded-xl p-2.5 text-xs font-bold text-white outline-none focus:border-orange-400"
                                />
                              </div>
                            </div>

                            {/* Auto-record Household IOU Option */}
                            {inst.borrowType === 'member' && otherMembers.length > 0 && (
                              <label className="flex items-center gap-2 p-2.5 bg-orange-500/10 border border-orange-500/20 rounded-xl cursor-pointer">
                                <Checkbox
                                  checked={inst.recordHouseholdIou}
                                  onChange={v => handleUpdate(index, { recordHouseholdIou: v })}
                                  iconClassName="text-orange-400"
                                />
                                <span className="text-xs font-bold text-orange-200">
                                  Automatically sync to Household IOU & Shared Balances Ledger
                                </span>
                              </label>
                            )}
                          </div>
                        )}
                      </div>

                    </div>
                  </motion.div>
                )}
              </AnimatePresence>
            </div>
          ))}
        </div>

        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3 pt-2 border-t border-white/5">
          <div className="text-xs text-secondary font-semibold order-2 sm:order-1">
            {instances.length > 1 && `${instances.length} items staged to add`}
          </div>
          <button 
            type="submit" 
            disabled={loading}
            className="px-6 py-2.5 bg-white text-black font-black tracking-widest text-xs rounded-xl hover:scale-105 transition-transform cursor-pointer"
          >
            {loading ? 'Adding...' : instances.length > 1 ? `Save All Transactions (${instances.length})` : 'Save Transaction'}
          </button>
        </div>
      </form>

      <TrackedExpenseList refreshTrigger={refreshTrigger} />
    </div>
  )
}

import React, { useState, useEffect } from 'react'
import { useApi, globalMutate } from '../hooks/useApi'
import { useAuth } from '../context/AuthContext'
import { useToast } from '../context/ToastContext'
import { getApiUrl } from '../utils/api'
import { Bell, Trash2, X } from 'lucide-react'

const CHANNEL_LABELS: Record<string, string> = {
  discord_dm: 'Discord DM',
  discord_webhook: 'Discord Webhook',
  email: 'Email',
  pushover: 'Pushover',
  gotify: 'Gotify',
  telegram: 'Telegram',
}

interface ReminderManagerProps {
  targetId: string
  targetType: string
  targetName: string
  onClose: () => void
}

export const ReminderManager: React.FC<ReminderManagerProps> = ({ targetId, targetType, targetName, onClose }) => {
  const { token, householdId } = useAuth()
  const { showToast } = useToast()
  const { data: reminders, loading, mutate } = (useApi(`/api/planning/reminders/${targetType}/${targetId}`) as any)
  const [showAdd, setShowAdd] = useState(false)

  const [deliveryType, setDeliveryType] = useState('discord_dm')
  const [deliveryTarget, setDeliveryTarget] = useState('')
  const [frequencyDays, setFrequencyDays] = useState(3)
  const [note, setNote] = useState('')

  const handleAdd = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!token) return
    const apiUrl = getApiUrl().replace(/\/$/, '')

    const res = (await fetch(`${apiUrl}/api/planning/reminders`, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'Authorization': `Bearer ${token}`,
            'x-household-id': householdId || ''
          },
          body: JSON.stringify({
            targetId: targetId,
            targetType: targetType,
            deliveryType: deliveryType,
            deliveryTarget: deliveryTarget,
            frequencyDays: Number(frequencyDays),
            note: note
          })
        }) as any)

    if (res.ok) {
      showToast('Reminder added successfully!', 'success')
      setShowAdd(false)
      setDeliveryTarget('')
      setNote('')
      mutate();
      globalMutate();
    } else {
      showToast('Failed to add reminder', 'error')
    }
  }

  const handleDelete = async (id: string) => {
    if (!token) return
    const apiUrl = getApiUrl().replace(/\/$/, '')

    const res = (await fetch(`${apiUrl}/api/planning/reminders/${id}`, {
          method: 'DELETE',
          headers: {
            'Authorization': `Bearer ${token}`,
            'x-household-id': householdId || ''
          }
        }) as any)

    if (res.ok) {
      showToast('Reminder deleted', 'success')
      mutate();
      globalMutate();
    }
  }

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm">
      <div className="bg-black border border-white/10 rounded-2xl w-full max-w-md overflow-hidden relative">
        <div className="p-4 border-b border-white/5 flex justify-between items-center bg-white/5">
          <div>
            <h3 className="font-black tracking-widest text-sm flex items-center gap-2">
              <Bell size={14} className="text-primary" /> Reminders
            </h3>
            <p className="text-[10px] text-white/50 tracking-widest">{targetName}</p>
          </div>
          <button onClick={onClose} className="p-1 hover:bg-white/10 rounded-full transition-colors">
            <X size={16} />
          </button>
        </div>

        <div className="p-4 max-h-[60vh] overflow-y-auto scrollable-list">
          {loading ? (
            <p className="text-xs text-white/50 text-center py-4">Loading reminders...</p>
          ) : (
            <div className="space-y-3">
              {reminders && reminders.length > 0 ? reminders.map((r: any) => (
                <div key={r.id} className="bg-white/5 border border-white/10 rounded-xl p-3 flex justify-between items-center">
                  <div>
                    <div className="text-xs font-bold font-mono text-primary flex items-center gap-1.5">
                      {CHANNEL_LABELS[r.deliveryType] || r.deliveryType}
                      <span className="text-[9px] bg-white/10 text-white/70 px-1.5 py-0.5 rounded-sm tracking-widest">
                        {r.frequencyDays} Days Prior
                      </span>
                    </div>
                    {r.note && <div className="text-[11px] text-white/60 mt-1">{r.note}</div>}
                  </div>
                  <button onClick={() => handleDelete(r.id)} className="text-red-400 hover:text-red-300 p-2 hover:bg-red-500/10 rounded-lg transition-colors">
                    <Trash2 size={14} />
                  </button>
                </div>
              )) : (
                <p className="text-xs text-white/30 text-center py-8 italic font-serif">No custom reminders configured.</p>
              )}
            </div>
          )}

          {!showAdd ? (
            <button 
              onClick={() => setShowAdd(true)} 
              className="w-full mt-4 py-3 border border-dashed border-white/20 rounded-xl text-xs font-black tracking-widest text-white/60 hover:text-white hover:bg-white/5 hover:border-white/40 transition-all"
            >
              + Create Reminder
            </button>
          ) : (
            <form onSubmit={handleAdd} className="mt-4 p-3 bg-primary/5 border border-primary/20 rounded-xl space-y-3">
              <div>
                <label className="text-[10px] font-black tracking-widest text-white/40 block mb-1">Delivery Method</label>
                <select 
                  value={deliveryType} 
                  onChange={(e) => setDeliveryType(e.target.value)}
                  className="w-full bg-black/50 border border-white/10 rounded-lg p-2 text-xs text-white outline-none focus:border-primary/50"
                  required
                >
                  <option value="discord_dm">Discord Direct Message</option>
                  <option value="discord_webhook">Discord Webhook</option>
                  <option value="email">Email</option>
                  <option value="pushover">Pushover</option>
                  <option value="gotify">Gotify</option>
                  <option value="telegram">Telegram</option>
                </select>
              </div>

              {deliveryType === 'discord_webhook' && (
                <div>
                  <label className="text-[10px] font-black tracking-widest text-white/40 block mb-1">Webhook URL</label>
                  <input 
                    type="url" 
                    value={deliveryTarget}
                    onChange={(e) => setDeliveryTarget(e.target.value)}
                    placeholder="https://discord.com/api/webhooks/..."
                    className="w-full bg-black/50 border border-white/10 rounded-lg p-2 text-xs text-white outline-none focus:border-primary/50"
                    required
                  />
                </div>
              )}

              {deliveryType === 'email' && (
                <div>
                  <label className="text-[10px] font-black tracking-widest text-white/40 block mb-1">Email Address</label>
                  <input 
                    type="email" 
                    value={deliveryTarget}
                    onChange={(e) => setDeliveryTarget(e.target.value)}
                    placeholder="you@example.com"
                    className="w-full bg-black/50 border border-white/10 rounded-lg p-2 text-xs text-white outline-none focus:border-primary/50"
                    required
                  />
                </div>
              )}

              {deliveryType === 'pushover' && (
                <div>
                  <label className="text-[10px] font-black tracking-widest text-white/40 block mb-1">Pushover User Key</label>
                  <input 
                    type="text" 
                    value={deliveryTarget}
                    onChange={(e) => setDeliveryTarget(e.target.value)}
                    placeholder="Your Pushover user key"
                    className="w-full bg-black/50 border border-white/10 rounded-lg p-2 text-xs text-white outline-none focus:border-primary/50"
                    required
                  />
                </div>
              )}

              {deliveryType === 'gotify' && (
                <div>
                  <label className="text-[10px] font-black tracking-widest text-white/40 block mb-1">Gotify URL (with token)</label>
                  <input 
                    type="text" 
                    value={deliveryTarget}
                    onChange={(e) => setDeliveryTarget(e.target.value)}
                    placeholder="https://gotify.example.org/message?token=xxx"
                    className="w-full bg-black/50 border border-white/10 rounded-lg p-2 text-xs text-white outline-none focus:border-primary/50"
                    required
                  />
                </div>
              )}

              {deliveryType === 'telegram' && (
                <div>
                  <label className="text-[10px] font-black tracking-widest text-white/40 block mb-1">Telegram Chat ID</label>
                  <input 
                    type="text" 
                    value={deliveryTarget}
                    onChange={(e) => setDeliveryTarget(e.target.value)}
                    placeholder="Chat ID (numeric or @username)"
                    className="w-full bg-black/50 border border-white/10 rounded-lg p-2 text-xs text-white outline-none focus:border-primary/50"
                    required
                  />
                </div>
              )}

              <div>
                <label className="text-[10px] font-black tracking-widest text-white/40 block mb-1">Alert Timing</label>
                <select 
                  value={frequencyDays} 
                  onChange={(e) => setFrequencyDays(Number(e.target.value))}
                  className="w-full bg-black/50 border border-white/10 rounded-lg p-2 text-xs text-white outline-none focus:border-primary/50"
                  required
                >
                  <option value={0}>On the Due Date (0 Days)</option>
                  <option value={1}>1 Day Before</option>
                  <option value={3}>3 Days Before</option>
                  <option value={7}>1 Week Before (7 Days)</option>
                </select>
              </div>

              <div>
                <label className="text-[10px] font-black tracking-widest text-white/40 block mb-1">Custom Note (Optional)</label>
                <input 
                  type="text" 
                  value={note}
                  onChange={(e) => setNote(e.target.value)}
                  placeholder="e.g. Ensure $50 is in Checking"
                  className="w-full bg-black/50 border border-white/10 rounded-lg p-2 text-xs text-white outline-none focus:border-primary/50"
                />
              </div>

              <div className="flex gap-2 pt-2">
                <button type="button" onClick={() => setShowAdd(false)} className="flex-1 py-2 text-xs font-black tracking-widest border border-white/10 rounded-lg hover:bg-white/5">Cancel</button>
                <button type="submit" className="flex-1 py-2 text-xs font-black tracking-widest bg-primary text-black rounded-lg hover:bg-primary/90">Save</button>
              </div>
            </form>
          )}
        </div>
      </div>
    </div>
  )
}

import React from 'react'
import { Price } from './Price'
import { useApi, globalMutate } from '../hooks/useApi'
import { getApiUrl } from '../utils/api'
import { CurrencyInput } from './ui/CurrencyInput'
import { PiggyBank } from 'lucide-react'

const API_URL = getApiUrl()

const SavingsBuckets: React.FC = () => {
  const { data: buckets = [], mutate } = (useApi('/api/financials/buckets') as any)
  const [isAdding, setIsAdding] = React.useState(false)
  const [name, setName] = React.useState('')
  const [amount, setAmount] = React.useState('')

  const handleCreate = async () => {
    if (!name || !amount) return
    const targetCents = parseInt(amount) || 0
    await fetch(`${API_URL}/api/financials/buckets`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${localStorage.getItem('ledger_token')}` },
      body: JSON.stringify({ name, target_cents: targetCents })
    })
    setIsAdding(false)
    setName('')
    setAmount('')
    mutate();
    globalMutate();
  }

  return (
    <section className="card">
      <h3 className="text-lg font-black tracking-tighter italic flex items-center gap-2 mb-1">
        <PiggyBank size={18} className="text-primary" /> Savings Buckets
      </h3>
      <p className="text-xs text-secondary font-medium mb-6">Allocate parts of your balance to specific goals like a vacation or emergency fund.</p>
      <div className="space-y-4">
        {Array.isArray(buckets) && buckets.map((b: any) => {
          const percent = b.target_cents > 0 ? Math.round((b.current_cents / b.target_cents) * 100) : 0;
          return (
            <div key={b.id}>
              <div className="flex items-center justify-between text-sm mb-1.5">
                <span className="font-bold text-white">{b.name}</span>
                <span className="font-black text-primary">{percent}%</span>
              </div>
              <div className="h-2 bg-black/40 rounded-full overflow-hidden border border-white/5">
                <div
                  className="h-full bg-primary rounded-full transition-all duration-500"
                  style={{ width: `${Math.min(100, percent)}%` }}
                />
              </div>
              <div className="text-[10px] text-white/40 font-medium mt-1">
                Goal: <Price amountCents={b.target_cents} options={{ minimumFractionDigits: 0 }} />
              </div>
            </div>
          );
        }) || <p className="text-sm text-white/40 font-medium">No buckets yet.</p>}
        {isAdding ? (
          <div className="space-y-3 p-4 bg-white/5 rounded-xl border border-white/10">
            <input type="text" placeholder="Bucket Name" value={name} onChange={e => setName(e.target.value)} className="w-full bg-black/40 text-white text-sm px-3 py-2 rounded-lg border border-white/10 outline-none focus:border-primary" />
            <CurrencyInput
              valueCents={parseInt(amount) || 0}
              onChangeCents={cents => setAmount(cents.toString())}
              placeholder="Target Goal"
              showSymbol={true}
              className="bg-black/40"
            />
            <div className="flex gap-2">
              <button onClick={handleCreate} className="flex-1 py-2 border border-emerald-500/30 text-emerald-500 font-black rounded-lg text-xs tracking-widest hover:bg-emerald-500/10 transition-all">Save</button>
              <button onClick={() => setIsAdding(false)} className="flex-1 py-2 bg-white/5 text-slate-400 font-black rounded-lg text-xs tracking-widest hover:bg-white/10 transition-all">Cancel</button>
            </div>
          </div>
        ) : (
          <button
            onClick={() => setIsAdding(true)}
            className="w-full py-3 mt-2 bg-white/5 border border-dashed border-white/10 rounded-xl text-xs font-black tracking-widest text-white/40 hover:bg-white/10 hover:text-white transition-all"
          >
            + Create New Bucket
          </button>
        )}
      </div>
    </section>
  )
}

export default SavingsBuckets

import React from 'react';
import { Clock, RotateCcw } from 'lucide-react';

export type FrequencyType = 'daily' | 'weekly' | 'biweekly' | 'monthly' | 'yearly';

interface SchedulingPickerProps {
  value: {
    frequency_type: FrequencyType;
    frequency_interval: number;
    day_of_month?: number;
    days_of_week?: string;
    totalInstallments?: number;
  };
  onChange: (value: any) => void;
}

const SchedulingPicker: React.FC<SchedulingPickerProps> = ({ value, onChange }) => {
  const frequencies: { id: FrequencyType; label: string }[] = [
    { id: 'daily', label: 'Daily' },
    { id: 'weekly', label: 'Weekly' },
    { id: 'biweekly', label: 'Bi-Weekly' },
    { id: 'monthly', label: 'Monthly' },
    { id: 'yearly', label: 'Yearly' },
  ];

  const updateField = (field: string, val: any) => {
    onChange({ ...value, [field]: val });
  };

  return (
    <div className="space-y-6">
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        {/* Frequency Type */}
        <div className="space-y-2">
          <label className="text-xs tracking-widest font-black text-secondary flex items-center gap-2">
            <RotateCcw size={12} className="text-primary" />
            Frequency
          </label>
          <select
            value={value.frequency_type}
            onChange={(e) => updateField('frequency_type', e.target.value)}
            className="w-full p-3 bg-white/5 border border-glass-border rounded-xl text-sm font-bold focus:outline-none focus:border-primary transition-all"
          >
            {frequencies.map((f) => (
              <option key={f.id} value={f.id}>{f.label}</option>
            ))}
          </select>
        </div>

        {/* Interval */}
        <div className="space-y-2">
          <label className="text-xs tracking-widest font-black text-secondary flex items-center gap-2">
            <Clock size={12} className="text-secondary" />
            Every X Intervals
          </label>
          <input
            type="number"
            min="1"
            max="100"
            value={value.frequency_interval}
            onChange={(e) => updateField('frequency_interval', parseInt(e.target.value) || 1)}
            className="w-full p-3 bg-white/5 border border-glass-border rounded-xl text-sm font-bold focus:outline-none focus:border-primary transition-all"
          />
        </div>
      </div>

      {/* Monthly specific options */}
      {value.frequency_type === 'monthly' && (
        <div className="p-4 bg-primary/5 border border-primary/20 rounded-2xl animate-in fade-in slide-in-from-top-2">
          <label className="text-xs tracking-widest font-black text-primary mb-3 block">Day of the Month</label>
          <div className="grid grid-cols-7 gap-1">
            {Array.from({ length: 31 }, (_, i) => i + 1).map((day) => (
              <button
                key={day}
                type="button"
                onClick={() => updateField('day_of_month', day)}
                className={`p-2 text-xs font-bold rounded-lg transition-all ${
                  value.day_of_month === day 
                    ? 'bg-primary text-white shadow-[0_0_10px_rgba(var(--primary-rgb),0.3)]' 
                    : 'bg-white/5 text-secondary hover:bg-white/10'
                }`}
              >
                {day}
              </button>
            ))}
          </div>
        </div>
      )}

      {/* Weekly/Bi-Weekly specific options */}
      {(value.frequency_type === 'weekly' || value.frequency_type === 'biweekly') && (
        <div className="p-4 bg-primary/5 border border-primary/20 rounded-2xl animate-in fade-in slide-in-from-top-2">
          <label className="text-xs tracking-widest font-black text-primary mb-3 block">Days of the Week</label>
          <div className="flex flex-wrap gap-2">
            {['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'].map((day, i) => (
              <button
                key={day}
                type="button"
                onClick={() => {
                  const days = value.days_of_week ? value.days_of_week.split(',') : [];
                  const dayStr = i.toString();
                  const newDays = days.includes(dayStr) 
                    ? days.filter(d => d !== dayStr) 
                    : [...days, dayStr];
                  updateField('days_of_week', newDays.sort().join(','));
                }}
                className={`flex-1 p-2 text-xs font-bold rounded-lg transition-all ${
                  (value.days_of_week || '').split(',').includes(i.toString())
                    ? 'bg-primary text-white shadow-[0_0_10px_rgba(var(--primary-rgb),0.3)]' 
                    : 'bg-white/5 text-secondary hover:bg-white/10'
                }`}
              >
                {day}
              </button>
            ))}
          </div>
        </div>
      )}

      {/* Termination logic */}
      <div className="pt-4 border-t border-white/5">
        <label className="flex items-center gap-3 cursor-pointer group">
          <input 
            type="checkbox" 
            checked={!!value.totalInstallments} 
            onChange={(e) => updateField('totalInstallments', e.target.checked ? 12 : undefined)}
            className="hidden"
          />
          <div className={`w-10 h-6 rounded-full transition-all relative ${value.totalInstallments ? 'bg-primary' : 'bg-white/10'}`}>
            <div className={`absolute top-1 w-4 h-4 bg-white rounded-full transition-all ${value.totalInstallments ? 'right-1' : 'left-1'}`} />
          </div>
          <span className="text-sm font-bold text-secondary group-hover:text-white transition-colors">Terminate after fixed number of occurrences</span>
        </label>

        {value.totalInstallments && (
           <div className="mt-4 animate-in zoom-in-95 duration-200">
             <input
                type="number"
                min="1"
                placeholder="Number of installments (e.g. 12)"
                value={value.totalInstallments}
                onChange={(e) => updateField('totalInstallments', parseInt(e.target.value) || 1)}
                className="w-full p-3 bg-white/5 border border-glass-border rounded-xl text-sm font-bold focus:outline-none focus:border-primary transition-all"
              />
           </div>
        )}
      </div>
    </div>
  );
};

export default SchedulingPicker;

import React from 'react'

const SeasonalAssets: React.FC = () => {
  const now = new Date()
  const month = now.getMonth() // 0-indexed (0 = Jan, 9 = Oct, 11 = Dec)
  const day = now.getDate()

  // 1. Spooky Mode (Oct 25 - Oct 31)
  const isSpooky = (month === 9 && day >= 25)

  // 2. Frost Mode (Dec 15 - Dec 31)
  const isFrost = (month === 11 && day >= 15)

  if (isSpooky) {
    return (
      <div 
        style={{ 
          position: 'fixed', 
          bottom: '2rem', 
          right: '2rem', 
          fontSize: '3rem', 
          pointerEvents: 'none', 
          zIndex: 5000,
          opacity: 0.8,
          filter: 'drop-shadow(0 0 10px rgba(249, 115, 22, 0.5))'
        }}
        className="pulse"
      >
        🎃
      </div>
    )
  }

  if (isFrost) {
    return (
      <div 
        style={{ 
          position: 'fixed', 
          top: '1rem', 
          right: '50%', 
          fontSize: '2rem', 
          pointerEvents: 'none', 
          zIndex: 5000,
          opacity: 0.6
        }}
        className="pulse"
      >
        ❄️
      </div>
    )
  }

  return null
}

export default SeasonalAssets

import React, { useEffect, useState } from 'react';
import { Shield, Smartphone, Monitor, Trash2, ShieldAlert, ShieldOff } from 'lucide-react';
import { Card } from './ui/Card';
import { Button } from './ui/Button';
import { useAuth } from '../context/AuthContext';
import { useToast } from '../context/ToastContext';
import { getApiUrl } from '../utils/api';
import { InlineToast } from './ui/InlineToast';

interface Session {
  id: string;
  deviceName: string;
  os: string;
  browser: string;
  ipAddress: string;
  lastActiveAt: string;
}

export function SecurityDashboard() {
  const { token } = useAuth();
  const { showToast } = useToast();
  const [sessions, setSessions] = useState<Session[]>([]);
  const [loading, setLoading] = useState(true);
  const [revokingAll, setRevokingAll] = useState(false);
  const [showLegend, setShowLegend] = useState(false);
  const [confirmRevokeId, setConfirmRevokeId] = useState<string | null>(null);
  const [confirmRevokeAll, setConfirmRevokeAll] = useState(false);

  const fetchSessions = async () => {
    if (!token) return;
    try {
      const apiUrl = (getApiUrl() || '').replace(/\/$/, '');
      const res = (await fetch(`${apiUrl}/api/user/sessions`, {
              headers: { 'Authorization': `Bearer ${token}` }
            }) as any);
      if (res.ok) {
        const json = (await res.json() as any);
        setSessions(Array.isArray(json.data) ? json.data : []);
      }
    } catch (e: any) {
      console.error('Failed to load sessions', e);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchSessions();
  }, [token]);

  const revokeSession = async (id: string) => {
    try {
      const apiUrl = (getApiUrl() || '').replace(/\/$/, '');
      const res = (await fetch(`${apiUrl}/api/user/sessions/${id}`, {
              method: 'DELETE',
              headers: { 'Authorization': `Bearer ${token}` }
            }) as any);
      if (res.ok) {
        setSessions(s => s.filter(x => x.id !== id));
        showToast('Session revoked successfully', 'success');
        setConfirmRevokeId(null);
      } else {
        showToast('Failed to revoke session', 'error');
      }
    } catch (e: any) {
      showToast('Error revoking session', 'error');
    }
  };

  const revokeAllOtherSessions = async () => {

    setRevokingAll(true);
    try {
      const apiUrl = (getApiUrl() || '').replace(/\/$/, '');
      const res = (await fetch(`${apiUrl}/api/user/sessions`, {
              method: 'DELETE',
              headers: { 'Authorization': `Bearer ${token}` }
            }) as any);
      if (res.ok) {
        // Keep only the first session (current)
        setSessions(s => s.length > 0 ? [s[0]] : []);
        showToast('All other sessions revoked', 'success');
      } else {
        showToast('Failed to revoke sessions', 'error');
      }
    } catch (e: any) {
      showToast('Error revoking sessions', 'error');
    } finally {
      setRevokingAll(false);
    }
  };

  if (loading) return <div className="text-gray-400 p-8">Loading Security Details...</div>;

  return (
    <div className="space-y-6">
      <Card className="bg-[#121212] border-white/5" title="Active Device Sessions" subtitle="Manage and revoke unauthorized logins across your network.">
        <div className="px-5 pb-4 flex items-center justify-between">
          <div className="flex items-center gap-6">
            <div className="flex items-center gap-2">
              <div className="w-2 h-2 rounded-full bg-emerald-500 shadow-[0_0_8px_rgba(16,185,129,0.5)]"></div>
              <span className="text-[10px] font-black text-slate-500 tracking-widest">Current Session</span>
            </div>
          </div>
          <button 
            onClick={() => setShowLegend(!showLegend)}
            className="text-[10px] font-black text-slate-500 hover:text-white tracking-widest flex items-center gap-1.5 transition-colors"
          >
            Security Legend
          </button>
        </div>

        {showLegend && (
          <div className="mx-5 mb-5 p-5 rounded-2xl bg-white/[0.02] border border-white/5 grid grid-cols-1 md:grid-cols-2 gap-6 animate-in fade-in slide-in-from-top-2">
            <div className="space-y-1">
              <div className="flex items-center gap-2">
                <span className="px-1.5 py-0.5 rounded-[4px] bg-emerald-500/10 text-emerald-500 text-[9px] font-black tracking-wider">Persistent</span>
                <span className="text-xs font-bold text-slate-200">30 Day Multi-Device Session</span>
              </div>
              <p className="text-[11px] text-slate-500 leading-relaxed">Standard "Remember Me" session. Survives browser restarts and system reboots.</p>
            </div>
            <div className="space-y-1">
              <div className="flex items-center gap-2">
                <span className="px-1.5 py-0.5 rounded-[4px] bg-amber-500/10 text-amber-500 text-[9px] font-black tracking-wider">Temporary</span>
                <span className="text-xs font-bold text-slate-200">24 Hour Volatile Session</span>
              </div>
              <p className="text-[11px] text-slate-500 leading-relaxed">Single-use secure session. Automatically purged after 24 hours of inactivity.</p>
            </div>
          </div>
        )}

        {sessions.length > 1 && (
          <div className="mx-5 mb-5 p-6 rounded-2xl bg-red-500/5 border border-red-500/10">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-3">
                <ShieldOff className="w-5 h-5 text-red-500 shrink-0" />
                <div>
                  <p className="text-sm font-bold text-red-400">Bulk Session Revocation</p>
                  <p className="text-xs text-red-500/60">Sign out from all other devices immediately. Only your current session will remain active.</p>
                </div>
              </div>
              {confirmRevokeAll ? (
                <InlineToast
                  message="Revoke all other devices?"
                  type="confirm"
                  onConfirm={revokeAllOtherSessions}
                  onCancel={() => setConfirmRevokeAll(false)}
                />
              ) : (
                <Button
                  variant="glass"
                  size="sm"
                  onClick={() => setConfirmRevokeAll(true)}
                  disabled={revokingAll}
                  className="bg-red-500/10 text-red-400 border-red-500/20 hover:bg-red-500/20 font-bold shrink-0"
                >
                  {revokingAll ? 'Revoking...' : `Revoke All (${sessions.length - 1})`}
                </Button>
              )}
            </div>
          </div>
        )}

        <div className="divide-y divide-white/5">
          {(sessions || []).map((s: any, idx: number) => (
            <div key={s.id} className="p-5 flex items-center justify-between hover:bg-white/[0.02] transition-colors">
              <div className="flex items-center gap-4">
                <div className="w-12 h-12 rounded-xl bg-white/5 flex items-center justify-center border border-white/5">
                  {s.os?.toLowerCase().includes('mac') || s.os?.toLowerCase().includes('windows') ? (
                    <Monitor className="w-6 h-6 text-gray-400" />
                  ) : (
                    <Smartphone className="w-6 h-6 text-gray-400" />
                  )}
                </div>
                <div>
                  <div className="flex items-center gap-2 mb-1">
                    <h3 className="text-slate-200 font-bold">
                      {s.deviceName} ({s.browser})
                    </h3>
                    {idx === 0 && (
                      <span className="px-2 py-0.5 rounded text-[10px] font-black tracking-wider bg-emerald-500 text-black shadow-[0_0_10px_rgba(16,185,129,0.3)]">
                        Current
                      </span>
                    )}
                    {s.isPersistent ? (
                      <span className="px-1.5 py-0.5 rounded-[4px] bg-emerald-500/10 text-emerald-500 text-[9px] font-black tracking-wider">Persistent</span>
                    ) : (
                      <span className="px-1.5 py-0.5 rounded-[4px] bg-amber-500/10 text-amber-500 text-[9px] font-black tracking-wider">Temporary</span>
                    )}
                  </div>
                   <div className="flex flex-col gap-0.5">
                    <p className="text-xs text-slate-500 font-medium">
                      {(() => {
                        const ips = [];
                        if (s.ipV4) ips.push({ label: 'IPv4', value: s.ipV4 });
                        if (s.ipV6) ips.push({ label: 'IPv6', value: s.ipV6 });

                        if (ips.length === 0 && s.ipAddress) {
                          ips.push({ 
                            label: s.ipAddress.includes(':') ? 'IPv6' : 'IPv4', 
                            value: s.ipAddress 
                          });
                        }

                        return ips.map((ip, idx) => (
                          <span key={idx} className={idx > 0 ? 'ml-3' : ''}>
                            <span className="text-slate-400 font-black tracking-tighter mr-1">{ip.label}:</span>
                            <span className="font-mono">{ip.value}</span>
                          </span>
                        ));
                      })()}
                    </p>
                    <p className="text-[11px] text-slate-600">Last Active: {new Date(s.lastActiveAt).toLocaleString()} • {s.location || 'Unknown Location'}</p>
                  </div>
                </div>
              </div>
                {idx !== 0 && (
                  <div className="flex items-center">
                    {confirmRevokeId === s.id ? (
                      <InlineToast 
                        message="Revoke session?" 
                        type="confirm" 
                        onConfirm={() => revokeSession(s.id)} 
                        onCancel={() => setConfirmRevokeId(null)} 
                      />
                    ) : (
                      <Button 
                        variant="glass" 
                        size="sm" 
                        onClick={() => setConfirmRevokeId(s.id)}
                        className="text-red-400 hover:text-red-300 hover:bg-red-400/10"
                      >
                        <Trash2 className="w-4 h-4 mr-2" /> Revoke
                      </Button>
                    )}
                  </div>
                )}
              </div>
            ))}
            {sessions.length === 0 && (
              <div className="p-8 text-center text-gray-500">
                <ShieldAlert className="w-8 h-8 opacity-20 mx-auto mb-2" />
                No active device history.
              </div>
            )}
          </div>

      </Card>
    </div>
  );
}

import React, { useState, useEffect } from 'react'
import { InlineToast } from './ui/InlineToast'
import { useAuth } from '../context/AuthContext'
import { useToast } from '../context/ToastContext'
import { useApi } from '../hooks/useApi'
import { getApiUrl } from '../utils/api'
import { ArrowRightLeft, Plus, Trash2, Handshake, Users } from 'lucide-react'
import { Modal } from './ui/Modal'
import { Button } from './ui/Button'
import { CurrencyInput } from './ui/CurrencyInput'
import { sanitizeImageUrl } from '../utils/security'
import { SettleBalancesModal } from './shared/SettleBalancesModal'

interface SharedBalance {
  id: string
  fromUserId: string
  toUserId: string
  amountCents: number
  transactionId: string | null
  fromDisplayName: string
  toDisplayName: string
  fromAvatarUrl: string | null
  toAvatarUrl: string | null
  transactionDescription: string | null
}

interface BalanceSummary {
  fromUserId: string
  toUserId: string
  netCents: number
  fromName: string
  toName: string
  fromAvatar: string | null
  toAvatar: string | null
}

export default function SharedBalances() {
  const { token, user, householdId } = useAuth()
  const { showToast } = useToast()
  const { data: balances = [], mutate: mutateBalances } = (useApi('/api/financials/shared-balances') as any)
  const { data: summary = [], mutate: mutateSummary } = (useApi('/api/financials/shared-balances/summary') as any)
  const { data: members = [] } = (useApi(householdId ? `/api/user/households/${householdId}/members` : null) as any)
  const { data: accounts = [] } = (useApi('/api/financials/accounts') as any)

  const [showAddModal, setShowAddModal] = useState(false)
  const [newIOU, setNewIOU] = useState({ toUserId: '', amountCents: 0, description: '' })
  const [adding, setAdding] = useState(false)
  const [confirmDeleteId, setConfirmDeleteId] = useState<string | null>(null)
  const [settleTarget, setSettleTarget] = useState<{
    id: string
    displayName: string
    avatarUrl?: string
    balanceCents: number
  } | null>(null)

  const createIOU = async () => {
    if (!newIOU.toUserId || !newIOU.amountCents) return
    setAdding(true)
    try {
      const apiUrl = getApiUrl()
      const res = (await fetch(`${apiUrl}/api/financials/shared-balances`, {
              method: 'POST',
              headers: {
                'Content-Type': 'application/json',
                'Authorization': `Bearer ${token}`,
                'x-household-id': householdId || ''
              },
              body: JSON.stringify({
                toUserId: newIOU.toUserId,
                amountCents: newIOU.amountCents,
                description: newIOU.description || undefined
              })
            }) as any)
      if (res.ok) {
        showToast('IOU recorded', 'success')
        setShowAddModal(false)
        setNewIOU({ toUserId: '', amountCents: 0, description: '' })
        mutateBalances()
        mutateSummary()
      } else {
        showToast('Failed to record IOU', 'error')
      }
    } catch (err: any) {
      showToast('Error creating IOU', 'error')
    } finally {
      setAdding(false)
    }
  }

  const deleteBalance = async (id: string) => {
    try {
      const apiUrl = getApiUrl()
      await fetch(`${apiUrl}/api/financials/shared-balances/${id}`, {
        method: 'DELETE',
        headers: {
          'Authorization': `Bearer ${token}`,
          'x-household-id': householdId || ''
        }
      })
      showToast('Entry deleted', 'success')
      setConfirmDeleteId(null)
      mutateBalances()
      mutateSummary()
    } catch (err: any) {
      showToast('Failed to delete', 'error')
    }
  }

  const settleWith = async (withUserId: string) => {
    try {
      const apiUrl = getApiUrl()
      const res = (await fetch(`${apiUrl}/api/financials/shared-balances/settle`, {
              method: 'POST',
              headers: {
                'Content-Type': 'application/json',
                'Authorization': `Bearer ${token}`,
                'x-household-id': householdId || ''
              },
              body: JSON.stringify({ withUserId: withUserId })
            }) as any)
      if (res.ok) {
        showToast('All settled!', 'success')
        mutateBalances()
        mutateSummary()
      }
    } catch (err: any) {
      showToast('Settlement failed', 'error')
    }
  }

  const otherMembers = (members || []).filter((m: any) => m.id !== user?.id)
  const summaryList = Array.isArray(summary) ? summary : []
  const balanceList = Array.isArray(balances) ? balances : []

  return (
    <section className="card" style={{ gridColumn: 'span 2' }}>
      <div className="flex items-start justify-between gap-4 mb-6">
        <div className="flex items-center gap-3 flex-1">
          <div className="w-10 h-10 rounded-xl bg-violet-500/10 flex items-center justify-center flex-shrink-0">
            <ArrowRightLeft className="w-5 h-5 text-violet-400" />
          </div>
          <div>
            <h3 className="text-lg font-black tracking-tighter italic">Shared Balances</h3>
            <p className="text-xs text-secondary font-medium">Track IOUs and shared costs with household members, and settle debts.</p>
          </div>
        </div>
        <button 
          onClick={() => setShowAddModal(true)}
          className="flex items-center gap-2 px-4 py-2 rounded-xl bg-violet-500 text-white font-bold text-sm hover:bg-violet-600 transition-all shadow-[0_0_15px_rgba(139,92,246,0.3)]"
        >
          <Plus className="w-4 h-4" /> Record IOU
        </button>
      </div>

      {/* Net Summary */}
      {summaryList.length > 0 && (
        <div className="mb-6 space-y-3">
          <h4 className="text-[10px] font-black text-slate-500 tracking-widest">Net Balances</h4>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
            {summaryList.map((s: BalanceSummary, idx: number) => {
              const isOwed = s.fromUserId === user?.id
              return (
                <div key={idx} className="flex items-center justify-between p-4 rounded-2xl bg-white/5 border border-white/5 hover:border-violet-500/20 transition-all">
                  <div className="flex items-center gap-3">
                    <div className="flex -space-x-2">
                      <img src={sanitizeImageUrl(s.fromAvatar) || `https://api.dicebear.com/7.x/bottts/svg?seed=${encodeURIComponent(s.fromUserId)}`} className="w-8 h-8 rounded-lg border-2 border-black" alt="" />
                      <img src={sanitizeImageUrl(s.toAvatar) || `https://api.dicebear.com/7.x/bottts/svg?seed=${encodeURIComponent(s.toUserId)}`} className="w-8 h-8 rounded-lg border-2 border-black" alt="" />
                    </div>
                    <div>
                      <p className="text-sm font-bold text-white">
                        {s.fromName} → {s.toName}
                      </p>
                      <p className={`text-xs font-black tracking-widest ${isOwed ? 'text-red-400' : 'text-emerald-400'}`}>
                        {isOwed ? 'You owe' : 'Owes you'}
                      </p>
                    </div>
                  </div>
                  <div className="flex items-center gap-3">
                    <span className={`text-lg font-black ${isOwed ? 'text-red-400' : 'text-emerald-400'}`}>
                      ${(Math.abs(s.netCents) / 100).toFixed(2)}
                    </span>
                    <button
                      onClick={() => setSettleTarget({
                        id: isOwed ? s.toUserId : s.fromUserId,
                        displayName: isOwed ? s.toName : s.fromName,
                        avatarUrl: (isOwed ? s.toAvatar : s.fromAvatar) || undefined,
                        balanceCents: isOwed ? -Math.abs(s.netCents) : Math.abs(s.netCents)
                      })}
                      className="flex items-center gap-1.5 px-3 py-1.5 rounded-xl bg-emerald-500/10 hover:bg-emerald-500/20 text-emerald-400 text-xs font-black tracking-wider transition-all cursor-pointer border border-emerald-500/20 shadow-sm"
                      title="Open Settlement Wizard"
                    >
                      <Handshake className="w-3.5 h-3.5" /> Settle
                    </button>
                  </div>
                </div>
              )
            })}
          </div>
        </div>
      )}

      {/* History */}
      <div className="space-y-2">
        <h4 className="text-[10px] font-black text-slate-500 tracking-widest">History</h4>
        {balanceList.length === 0 ? (
          <div className="py-12 text-center">
            <Users className="w-10 h-10 text-slate-700 mx-auto mb-3" />
            <p className="text-sm text-slate-500 font-bold">No shared balances yet</p>
            <p className="text-xs text-slate-600 mt-1">Record an IOU when someone covers a shared expense</p>
          </div>
        ) : (
          <div className="max-h-[300px] overflow-y-auto pr-2 custom-scrollbar space-y-2">
            {balanceList.map((b: SharedBalance) => (
              <div key={b.id} className="flex items-center justify-between p-4 rounded-2xl bg-black/40 border border-white/5 hover:border-white/10 transition-all group">
                <div className="flex items-center gap-3">
                  <div className="flex -space-x-2">
                    <img src={sanitizeImageUrl(b.fromAvatarUrl) || `https://api.dicebear.com/7.x/bottts/svg?seed=${encodeURIComponent(b.fromUserId)}`} className="w-7 h-7 rounded-lg border-2 border-black" alt="" />
                    <img src={sanitizeImageUrl(b.toAvatarUrl) || `https://api.dicebear.com/7.x/bottts/svg?seed=${encodeURIComponent(b.toUserId)}`} className="w-7 h-7 rounded-lg border-2 border-black" alt="" />
                  </div>
                  <div>
                    <p className="text-sm font-bold text-white">
                      {b.fromDisplayName} → {b.toDisplayName}
                    </p>
                    {b.transactionDescription && (
                      <p className="text-[10px] text-slate-500 font-mono truncate max-w-[200px]">
                        {b.transactionDescription}
                      </p>
                    )}
                  </div>
                </div>
                <div className="flex items-center gap-3">
                  <span className="text-sm font-black text-violet-400">
                    ${(b.amountCents / 100).toFixed(2)}
                  </span>
                  {confirmDeleteId === b.id ? (
                    <InlineToast 
                      message="Delete entry?" 
                      type="confirm" 
                      onConfirm={() => deleteBalance(b.id)} 
                      onCancel={() => setConfirmDeleteId(null)} 
                    />
                  ) : (
                    <button
                      onClick={() => setConfirmDeleteId(b.id)}
                      className="p-1.5 rounded-lg text-red-500/60 hover:text-red-400 hover:bg-red-500/10 transition-all"
                    >
                      <Trash2 className="w-3.5 h-3.5" />
                    </button>
                  )}
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* Add IOU Modal */}
      <Modal
        isOpen={showAddModal}
        onClose={() => setShowAddModal(false)}
        title="Record an IOU"
        footer={
          <>
            <Button variant="secondary" onClick={() => setShowAddModal(false)}>Cancel</Button>
            <Button variant="primary" onClick={createIOU} disabled={adding || !newIOU.toUserId || !newIOU.amountCents}>
              {adding ? 'Recording...' : 'Record IOU'}
            </Button>
          </>
        }
      >
        <div className="space-y-4">
          <div>
            <label className="text-[10px] font-black text-slate-500 tracking-widest mb-2 block">Who do you owe?</label>
            <select
              value={newIOU.toUserId}
              onChange={(e) => setNewIOU({ ...newIOU, toUserId: e.target.value })}
              className="w-full bg-white/5 border border-white/10 p-3 rounded-xl text-sm font-bold outline-none focus:border-violet-500/50 transition-all"
            >
              <option value="">Select a member...</option>
              {otherMembers.map((m: any) => (
                <option key={m.id} value={m.id}>{m.displayName || m.email}</option>
              ))}
            </select>
          </div>
          <div>
            <label className="text-[10px] font-black text-slate-500 tracking-widest mb-2 block">Amount</label>
            <CurrencyInput 
              valueCents={newIOU.amountCents || 0} 
              onChangeCents={cents => setNewIOU({ ...newIOU, amountCents: cents })}
              placeholder="0.00"
              className="focus:border-violet-500/50"
            />
          </div>
          <div>
            <label className="text-[10px] font-black text-slate-500 tracking-widest mb-2 block">Description (optional)</label>
            <input
              type="text"
              value={newIOU.description}
              onChange={(e) => setNewIOU({ ...newIOU, description: e.target.value })}
              placeholder="e.g., Dinner last Thursday"
              className="w-full bg-white/5 border border-white/10 p-3 rounded-xl text-sm font-bold outline-none focus:border-violet-500/50 transition-all"
            />
          </div>
        </div>
      </Modal>

      <SettleBalancesModal
        isOpen={!!settleTarget}
        onClose={() => setSettleTarget(null)}
        targetUser={settleTarget}
        accounts={accounts || []}
        onSettled={() => {
          mutateBalances()
          mutateSummary()
        }}
      />
    </section>
  )
}

