// ─── Cancel Subscription Modal ──────────────────────────────────────

interface CancelSubscriptionModalProps {
  sub: any
  onConfirm: (endDate: string) => Promise<void>
  onClose: () => void
}

const CancelSubscriptionModal: React.FC<CancelSubscriptionModalProps> = ({ sub, onConfirm, onClose }) => {
  const today = new Date().toISOString().split('T')[0]
  const [endDate, setEndDate] = useState(today)
  const [loading, setLoading] = useState(false)

  const handleConfirm = async () => {
    setLoading(true)
    await onConfirm(endDate)
    setLoading(false)
  }

  return (
    <div className="fixed inset-0 z-[10001] flex items-center justify-center p-4 bg-black/80 backdrop-blur-xl" onClick={onClose}>
      <div className="card w-full max-w-sm p-6 space-y-4 relative" onClick={e => e.stopPropagation()}>
        <div className="flex items-center justify-between">
          <h3 className="text-lg font-black tracking-tighter">Cancel <span className="text-primary">{sub.name}</span></h3>
          <button onClick={onClose} className="w-8 h-8 flex items-center justify-center hover:bg-white/5 rounded-full transition-all">
            <X size={18} />
          </button>
        </div>
        <p className="text-sm text-secondary font-medium">
          Set the date when this subscription will end. Future payments after this date will not be tracked.
        </p>
        <div className="space-y-1">
          <label className="text-[10px] font-black tracking-widest text-secondary">Cancellation Date</label>
          <input
            type="date"
            value={endDate}
            onChange={e => setEndDate(e.target.value)}
            className="w-full p-3 bg-white/5 border border-glass-border rounded-xl text-white outline-none focus:border-primary transition-all text-sm font-bold"
          />
        </div>
        <div className="flex gap-3">
          <button onClick={onClose} className="flex-1 py-3 bg-white/5 border border-white/10 rounded-xl text-xs font-black tracking-widest hover:bg-white/10 transition-all">
            Keep Active
          </button>
          <button
            onClick={handleConfirm}
            disabled={loading || !endDate}
            className="flex-1 py-3 text-slate-400 border border-slate-500/30 rounded-xl text-xs font-black tracking-widest hover:bg-slate-500/10 transition-all disabled:opacity-40"
          >
            {loading ? 'Cancelling...' : 'Confirm Cancellation'}
          </button>
        </div>
      </div>
    </div>
  )
}

export default SubscriptionManager

import React, { useState } from 'react';
import { useAuth } from '../context/AuthContext';
import { useApi, globalMutate } from '../hooks/useApi';
import { useToast } from '../context/ToastContext';
import { Send, MessageSquare, Clock, AlertCircle, CheckCircle2 } from 'lucide-react';
import { Price } from './Price';
import { getApiUrl } from '../utils/api';

const GithubIcon = ({ size = 20, className = "" }: { size?: number, className?: string }) => (
  <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={className}>
    <path d="M15 22v-4a4.8 4.8 0 0 0-1-3.5c3 0 6-2 6-5.5.08-1.25-.27-2.48-1-3.5.28-1.15.28-2.35 0-3.5 0 0-1 0-3 1.5-2.64-.5-5.36-.5-8 0C6 2 5 2 5 2c-.3 1.15-.3 2.35 0 3.5A5.403 5.403 0 0 0 4 9c0 3.5 3 5.5 6 5.5-.39.49-.68 1.05-.85 1.65-.17.6-.22 1.23-.15 1.85v4" />
    <path d="M9 18c-4.51 2-5-2-7-2" />
  </svg>
);

const SupportPortal: React.FC = () => {
  const { token, householdId } = useAuth();
  const { showToast } = useToast();
  const { data: issues = [], mutate } = (useApi('/api/support/issues') as any);

  const [isSubmitting, setIsSubmitting] = useState(false);
  const [formData, setFormData] = useState({
    title: '',
    description: '',
    category: 'General',
    priority: 'medium'
  });

  const [selectedIssueId, setSelectedIssueId] = useState<string | null>(null);
  const { data: comments = [], mutate: mutateComments } = (useApi(selectedIssueId ? `/api/support/issues/${selectedIssueId}/comments` : '') as any);
  const [commentBody, setCommentBody] = useState('');
  const [isCommenting, setIsCommenting] = useState(false);

  const selectedIssue = issues.find((i: any) => i.id === selectedIssueId);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);

    try {
      const res = (await fetch(`${getApiUrl()}/api/support/issues`, {
              method: 'POST',
              headers: {
                'Content-Type': 'application/json',
                'Authorization': `Bearer ${token}`,
                'x-household-id': householdId || ''
              },
              body: JSON.stringify({
                ...formData,
                metadata: {
                  url: window.location.href,
                  userAgent: navigator.userAgent,
                  timestamp: new Date().toISOString()
                }
              })
            }) as any);

      if (res.ok) {
        showToast('Support Request Sent', 'success');
        setFormData({ title: '', description: '', category: 'General', priority: 'medium' });
        mutate();
        globalMutate();
      } else {
        throw new Error('Failed to send request');
      }
    } finally {
      setIsSubmitting(false);
    }
  };

  const handlePostComment = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedIssueId || !commentBody.trim()) return;
    setIsCommenting(true);

    try {
      const res = (await fetch(`${getApiUrl()}/api/support/issues/${selectedIssueId}/comments`, {
              method: 'POST',
              headers: {
                'Content-Type': 'application/json',
                'Authorization': `Bearer ${token}`
              },
              body: JSON.stringify({ body: commentBody })
            }) as any);

      if (res.ok) {
        setCommentBody('');
        mutateComments();
        globalMutate();
        showToast('Comment posted', 'success');
      }
    } catch (err: any) {
      showToast('Error posting comment', 'error');
    } finally {
      setIsCommenting(false);
    }
  };

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-700">
      <header className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-3xl font-black italic tracking-tighter text-white mb-2">High-Priority Support</h2>
          <p className="text-secondary text-sm tracking-widest font-bold opacity-60">Report issues or request system enhancements</p>
        </div>
        <div className="flex items-center gap-3">
           <div className="px-4 py-2 bg-white/5 border border-glass-border rounded-xl flex items-center gap-2">
             <GithubIcon size={16} className="text-primary" />
             <span className="text-[10px] font-black tracking-widest opacity-60">GitHub Synced</span>
           </div>
        </div>
      </header>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        {/* Submission Form */}
        <section className="lg:col-span-2 space-y-6">
          {!selectedIssueId ? (
            <div className="card p-6 bg-deep/40 backdrop-blur-3xl border-glass-border relative overflow-hidden">
              <div className="absolute top-0 right-0 w-64 h-64 bg-primary/10 blur-[100px] rounded-full -mr-32 -mt-32" />

              <h3 className="text-lg font-bold mb-6 flex items-center gap-2 border-b border-glass-border pb-4 tracking-tight">
                <MessageSquare size={18} className="text-primary" />
                New Service Ticket
              </h3>

              <form onSubmit={handleSubmit} className="space-y-6 relative z-10">
                <div className="space-y-2">
                  <label className="text-[10px] font-black tracking-widest text-secondary ml-1">Subject / Headline</label>
                  <input 
                    value={formData.title}
                    onChange={e => setFormData({...formData, title: e.target.value})}
                    placeholder="Briefly describe the issue..."
                    className="w-full bg-black/40 border border-glass-border rounded-xl p-4 text-sm font-bold focus:outline-none focus:border-primary transition-all"
                    required
                    minLength={5}
                  />
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div className="space-y-2">
                    <label className="text-[10px] font-black tracking-widest text-secondary ml-1">Classification</label>
                    <select 
                      value={formData.category}
                      onChange={e => setFormData({...formData, category: e.target.value})}
                      className="w-full bg-black/40 border border-glass-border rounded-xl p-4 text-sm font-bold focus:outline-none focus:border-primary transition-all appearance-none"
                    >
                      <option value="General">General Inquiry</option>
                      <option value="Bug">Bug Report</option>
                      <option value="Feature">Feature Request</option>
                      <option value="Billing">Billing Issue</option>
                      <option value="Account">Account Security</option>
                    </select>
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-black tracking-widest text-secondary ml-1">Priority Intake</label>
                    <select 
                      value={formData.priority}
                      onChange={e => setFormData({...formData, priority: e.target.value})}
                      className="w-full bg-black/40 border border-glass-border rounded-xl p-4 text-sm font-bold focus:outline-none focus:border-primary transition-all appearance-none"
                    >
                      <option value="low">Low - Future Polish</option>
                      <option value="medium">Medium - Standard Request</option>
                      <option value="high">High - Urgent Issue</option>
                      <option value="critical">Critical - System Blocker</option>
                    </select>
                  </div>
                </div>

                <div className="space-y-2">
                  <label className="text-[10px] font-black tracking-widest text-secondary ml-1">Support Details</label>
                  <textarea 
                    value={formData.description}
                    onChange={e => setFormData({...formData, description: e.target.value})}
                    rows={6}
                    placeholder="What happened? Steps to reproduce?"
                    className="w-full bg-black/40 border border-glass-border rounded-2xl p-4 text-sm font-bold focus:outline-none focus:border-primary transition-all resize-none"
                    required
                    minLength={10}
                  />
                </div>

                <button 
                  type="submit" 
                  disabled={isSubmitting}
                  className="w-full bg-gradient-to-r from-primary to-secondary text-white font-black tracking-widest py-4 rounded-xl shadow-lg hover:shadow-primary/25 hover:scale-[1.01] transition-all disabled:opacity-50 flex items-center justify-center gap-2"
                >
                  <Send size={16} />
                  {isSubmitting ? 'Submitting...' : 'Submit Support Ticket'}
                </button>
              </form>
            </div>
          ) : (
            <div className="space-y-6 animate-in slide-in-from-right-4 duration-500">
              <button 
                onClick={() => setSelectedIssueId(null)}
                className="text-[10px] font-black tracking-widest text-secondary hover:text-white flex items-center gap-2 mb-4"
              >
                ← Back to New Ticket
              </button>

              <div className="card p-6 bg-deep/40 backdrop-blur-3xl border-glass-border relative overflow-hidden">
                <div className="flex justify-between items-start mb-6 border-b border-glass-border pb-4">
                  <div>
                    <h3 className="text-xl font-bold tracking-tight mb-1">{selectedIssue.title}</h3>
                    <div className="flex items-center gap-3 text-[10px] font-black tracking-widest opacity-40">
                      <span className="text-primary">{selectedIssue.category}</span>
                      <span className="text-secondary">•</span>
                      <span>{new Date(selectedIssue.createdAt).toLocaleString()}</span>
                    </div>
                  </div>
                  <div className={`px-4 py-2 rounded-xl border text-[10px] font-black tracking-widest ${selectedIssue.status === 'open' ? 'bg-amber-500/10 border-amber-500/20 text-amber-500' : 'bg-emerald-500/10 border-emerald-500/20 text-emerald-500'}`}>
                    {selectedIssue.status}
                  </div>
                </div>

                <div className="bg-black/20 rounded-xl p-4 text-sm font-medium mb-8 leading-relaxed">
                  {selectedIssue.description}
                </div>

                <div className="space-y-6">
                  <h4 className="text-xs font-black tracking-widest text-secondary flex items-center gap-2">
                    <MessageSquare size={14} />
                    Conversation History
                  </h4>

                  <div className="space-y-4 max-h-[400px] overflow-y-auto pr-2 custom-scrollbar">
                    {comments && comments.length > 0 ? (
                      comments.map((comment: any) => (
                        <div key={comment.id} className={`p-4 rounded-xl border ${comment.userId ? 'bg-primary/5 border-primary/20' : 'bg-white/5 border-glass-border'}`}>
                          <div className="flex justify-between items-center mb-2">
                            <span className="text-[10px] font-black tracking-widest text-primary">{comment.authorName}</span>
                            <span className="text-[10px] opacity-40">{new Date(comment.createdAt).toLocaleDateString()}</span>
                          </div>
                          <p className="text-sm">{comment.body}</p>
                        </div>
                      ))
                    ) : (
                      <p className="text-xs text-secondary italic opacity-40 text-center py-8">No responses yet</p>
                    )}
                  </div>

                  {selectedIssue.status === 'open' && (
                    <form onSubmit={handlePostComment} className="mt-8 space-y-4 pt-6 border-t border-glass-border">
                      <textarea 
                        value={commentBody}
                        onChange={e => setCommentBody(e.target.value)}
                        placeholder="Add a comment or update..."
                        className="w-full bg-black/40 border border-glass-border rounded-xl p-4 text-sm font-bold focus:outline-none focus:border-primary transition-all resize-none"
                        rows={3}
                        required
                      />
                      <button 
                        type="submit"
                        disabled={isCommenting}
                        className="px-6 py-3 bg-primary text-white font-black tracking-widest text-[10px] rounded-lg hover:brightness-110 transition-all flex items-center gap-2"
                      >
                        <Send size={12} />
                        {isCommenting ? 'Posting...' : 'Post Update'}
                      </button>
                    </form>
                  )}
                </div>
              </div>
            </div>
          )}
        </section>

        {/* Previous Tickets */}
        <section className="space-y-6">
          <h3 className="text-secondary tracking-widest text-xs font-black px-2 mt-2 flex items-center justify-between">
            Active Tickets
            <span className="bg-primary/20 text-primary px-2 py-0.5 rounded-full text-[10px]">{issues?.length || 0}</span>
          </h3>

          <div className="space-y-4 max-h-[600px] overflow-y-auto pr-2 custom-scrollbar">
            {issues && issues.length > 0 ? (
              issues.map((issue: any) => (
                <div 
                  key={issue.id} 
                  onClick={() => setSelectedIssueId(issue.id)}
                  className={`card p-4 border-l-4 hover:bg-white/5 transition-all cursor-pointer group ${selectedIssueId === issue.id ? 'border-l-secondary bg-white/5' : 'border-l-primary'}`}
                >
                  <div className="flex justify-between items-start mb-2">
                    <h4 className="font-bold text-sm truncate pr-2">{issue.title}</h4>
                    {issue.status === 'open' ? (
                      <Clock size={14} className="text-amber-500 shrink-0" />
                    ) : (
                      <CheckCircle2 size={14} className="text-emerald-500 shrink-0" />
                    )}
                  </div>
                  <div className="flex items-center gap-3 text-[10px] font-black tracking-widest opacity-40 mb-3">
                    <span className="text-primary">{issue.category}</span>
                    <span className="text-secondary">•</span>
                    <span>{new Date(issue.createdAt).toLocaleDateString()}</span>
                  </div>
                  {issue.githubIssueUrl && (
                    <a 
                      href={issue.githubIssueUrl} 
                      target="_blank" 
                      rel="noopener noreferrer"
                      className="inline-flex items-center gap-2 text-[10px] font-black tracking-widest text-primary hover:text-white transition-colors bg-primary/10 px-3 py-1.5 rounded-lg border border-primary/20"
                    >
                      <GithubIcon size={12} />
                      View on GitHub
                    </a>
                  )}
                </div>
              ))
            ) : (
              <div className="text-center py-12 card bg-white/5 border-dashed">
                <AlertCircle size={32} className="mx-auto text-secondary opacity-20 mb-3" />
                <p className="text-xs text-secondary italic opacity-40 tracking-widest">No active tickets</p>
              </div>
            )}
          </div>
        </section>
      </div>
    </div>
  );
};

export default SupportPortal;

import React from 'react'
