  'admin-dashboard': 'text-emerald-500', 'admin-users': 'text-primary',
  'admin-households': 'text-emerald-400', 'admin-entity-manager': 'text-orange-400',
  'admin-providers': 'text-cyan-400', 'admin-processors': 'text-rose-500',
