import React, { createContext, useContext, useState, useCallback } from 'react'
import { ReportFilters } from '../types'

function defaultFilters(): ReportFilters {
  const now = new Date()
  const to = now.toISOString().split('T')[0]
  const from = new Date(now.getFullYear(), now.getMonth(), 1).toISOString().split('T')[0]
  return { from, to, preset: 'thisMonth', accountIds: [], categoryIds: [], type: 'all', compareFrom: '', compareTo: '' }
}

interface ReportFilterContextValue {
  filters: ReportFilters
  setFilters: React.Dispatch<React.SetStateAction<ReportFilters>>
  setDateRange: (preset: string, from: string, to: string) => void
  resetFilters: () => void
}

const ReportFilterContext = createContext<ReportFilterContextValue | null>(null)

export const ReportFilterProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [filters, setFilters] = useState<ReportFilters>(defaultFilters)

  const setDateRange = useCallback((preset: string, from: string, to: string) => {
    const now = new Date()
    let compareFrom = ''
    let compareTo = ''
    const days = Math.ceil((new Date(to).getTime() - new Date(from).getTime()) / 86400000)
    const compareEnd = new Date(new Date(from).getTime() - 86400000)
    const compareStart = new Date(compareEnd.getTime() - days * 86400000)
    compareFrom = compareStart.toISOString().split('T')[0]
    compareTo = compareEnd.toISOString().split('T')[0]

    setFilters(prev => ({ ...prev, preset, from, to, compareFrom, compareTo }))
  }, [])

  const resetFilters = useCallback(() => setFilters(defaultFilters()), [])

  return (
    <ReportFilterContext.Provider value={{ filters, setFilters, setDateRange, resetFilters }}>
      {children}
    </ReportFilterContext.Provider>
  )
}

export function useReportFilters() {
  const ctx = useContext(ReportFilterContext)
  if (!ctx) throw new Error('useReportFilters must be used within ReportFilterProvider')
  return ctx
}

import React, { useState, useEffect } from 'react'
import { X } from 'lucide-react'
import { useAuth } from '../../../context/AuthContext'
import { getApiUrl } from '../../../utils/api'
import { Price } from '../../Price'
import { DrillDownPayload } from '../types'

interface DrillDownModalProps {
  payload: DrillDownPayload
  onClose: () => void
}

export const DrillDownModal: React.FC<DrillDownModalProps> = ({ payload, onClose }) => {
  const { token } = useAuth()
  const [txns, setTxns] = useState<any[]>([])
  const [loading, setLoading] = useState(true)

  useEffect(() => {
    const load = async () => {
      setLoading(true)
      try {
        const params = new URLSearchParams()
        if (payload.from) params.set('from', payload.from)
        if (payload.to) params.set('to', payload.to)
        if (payload.categoryIds?.length) params.set('category_ids', payload.categoryIds.join(','))
        if (payload.description) params.set('q', payload.description)
        if (payload.type && payload.type !== 'all') params.set('type', payload.type)
        params.set('limit', '50')

        const res = await fetch(`${getApiUrl()}/api/financials/transactions?${params}`, {
          headers: { Authorization: `Bearer ${token}` },
        })
        if (res.ok) {
          const json: any = await res.json()
          setTxns(json.success ? json.data : json)
        }
      } catch { /* ignore */ }
      setLoading(false)
    }
    if (token) load()
  }, [payload, token])

  return (
    <div className="fixed inset-0 z-[10001] flex items-center justify-center p-4 bg-black/80 backdrop-blur-xl" onClick={onClose}>
      <div className="card w-full max-w-2xl max-h-[80vh] flex flex-col relative" onClick={e => e.stopPropagation()}>
        <div className="flex items-center justify-between p-5 border-b border-white/5">
          <div>
            <h3 className="text-sm font-black tracking-tighter">{payload.title}</h3>
            <p className="text-[10px] text-white/40 font-medium mt-0.5">{txns.length} transactions</p>
          </div>
          <button onClick={onClose} className="w-8 h-8 flex items-center justify-center hover:bg-white/5 rounded-full transition-all">
            <X size={16} />
          </button>
        </div>
        <div className="flex-1 overflow-y-auto p-4 custom-scrollbar space-y-1">
          {loading ? (
            <div className="text-center py-8 text-xs text-white/30 font-black tracking-widest">Loading...</div>
          ) : txns.length === 0 ? (
            <div className="text-center py-8 text-xs text-white/30 italic font-medium">No transactions found</div>
          ) : (
            txns.map((tx: any) => (
              <div key={tx.id} className="flex items-center justify-between py-2.5 px-3 hover:bg-white/[0.02] rounded-lg transition-all">
                <div className="min-w-0 flex-1">
                  <div className="text-xs font-bold text-white/80 truncate">{tx.description || 'Untitled'}</div>
                  <div className="text-[10px] text-white/30 font-medium">{tx.transactionDate}</div>
                </div>
                <div className="flex-shrink-0 ml-3">
                  <Price amountCents={tx.amountCents} className={`text-xs font-black ${tx.amountCents < 0 ? 'text-red-400' : 'text-emerald-400'}`} />
                </div>
              </div>
            ))
          )}
        </div>
      </div>
    </div>
  )
}

import React, { useRef, useState } from 'react'
import { Download } from 'lucide-react'
import { TabId } from '../types'
import { useApi } from '../../../hooks/useApi'
import { useReportFilters } from '../context/ReportFilterContext'
import { formatCsv } from './csvFormatter'
import { formatXlsx } from './xlsxFormatter'
import { formatPdf } from './pdfFormatter'
import { useToast } from '../../../context/ToastContext'

interface ExportMenuProps {
  tabId: TabId
  reportRef: React.RefObject<HTMLDivElement | null>
}

export const ExportMenu: React.FC<ExportMenuProps> = ({ tabId, reportRef }) => {
  const [open, setOpen] = useState(false)
  const [loading, setLoading] = useState<string | null>(null)
  const { showToast } = useToast()
  const { data: raw } = useApi<any>(`/api/reports/${tabId}`)
  const { filters } = useReportFilters()

  const d = raw as any
  const data = d?.success ? d.data : d

  const downloadBlob = (blob: Blob, filename: string) => {
    const url = URL.createObjectURL(blob)
    const a = document.createElement('a')
    a.href = url
    a.download = filename
    a.click()
    URL.revokeObjectURL(url)
  }

  const handleCsv = () => {
    if (!data) return
    const { headers, rows } = formatCsv(tabId, data)
    const csv = [headers.join(','), ...rows.map((r: any) => r.join(','))].join('\n')
    downloadBlob(new Blob([csv], { type: 'text/csv' }), `ledger-${tabId}-${filters.from}-${filters.to}.csv`)
    showToast('CSV exported', 'success')
    setOpen(false)
  }

  const handleXlsx = async () => {
    if (!data) return
    setLoading('xlsx')
    try {
      const blob = await formatXlsx(tabId, data, `ledger-${tabId}-${filters.from}-${filters.to}.xlsx`)
      downloadBlob(blob, `ledger-${tabId}-${filters.from}-${filters.to}.xlsx`)
      showToast('XLSX exported', 'success')
    } catch { showToast('XLSX export failed', 'error') }
    setLoading(null)
    setOpen(false)
  }

  const handlePdf = async () => {
    if (!reportRef.current) return
    setLoading('pdf')
    try {
      const blob = await formatPdf(reportRef.current, `ledger-${tabId}-${filters.from}-${filters.to}.pdf`)
      downloadBlob(blob, `ledger-${tabId}-${filters.from}-${filters.to}.pdf`)
      showToast('PDF exported', 'success')
    } catch { showToast('PDF export failed', 'error') }
    setLoading(null)
    setOpen(false)
  }

  return (
    <div className="relative">
      <button onClick={() => setOpen(!open)} disabled={!!loading}
        className="flex items-center gap-1.5 px-3 py-2 bg-white/5 hover:bg-white/10 border border-white/10 rounded-xl text-xs font-black tracking-widest transition-all disabled:opacity-40"
      >
        <Download size={12} /> {loading ? `Exporting ${loading}...` : 'Export'}
      </button>
      {open && (
        <>
          <div className="fixed inset-0 z-10" onClick={() => setOpen(false)} />
          <div className="absolute right-0 top-full mt-1 z-20 bg-deep border border-white/10 rounded-xl shadow-2xl shadow-black/50 overflow-hidden min-w-[140px]">
            <button onClick={handleCsv} className="w-full text-left px-4 py-2.5 text-xs font-bold text-white/80 hover:bg-white/10 transition-all">CSV</button>
            <button onClick={handleXlsx} className="w-full text-left px-4 py-2.5 text-xs font-bold text-white/80 hover:bg-white/10 transition-all">XLSX</button>
            <button onClick={handlePdf} className="w-full text-left px-4 py-2.5 text-xs font-bold text-white/80 hover:bg-white/10 transition-all">PDF</button>
          </div>
        </>
      )}
    </div>
  )
}

import { TabId, DashboardData, SpendingData, BudgetData, CashFlowData, CompareData } from '../types'

interface CsvOutput { headers: string[]; rows: any[][] }

function formatCents(c: number): string { return (c / 100).toFixed(2) }

const FORMATTERS: Record<TabId, (data: any) => CsvOutput> = {
  overview: (data: DashboardData) => {
    const headers = ['Date', 'Net Worth']
    const rows = (data.history || []).map((h: any) => [h.date, formatCents(h.value)])
    return { headers, rows }
  },
  spending: (data: SpendingData) => {
    const headers = ['Category', 'Spend', 'Percentage']
    const rows = (data.categories || []).map((c: any) => [c.name, formatCents(c.totalCents), `${c.percentage}%`])
    return { headers, rows }
  },
  budget: (data: BudgetData) => {
    const headers = ['Category', 'Budget', 'Spent', 'Remaining', 'Utilization']
    const rows = (data.budgets || []).map((b: any) => {
      const pct = b.monthlyBudgetCents > 0 ? Math.round((b.spendCents / b.monthlyBudgetCents) * 100) : 0
      return [b.name, formatCents(b.monthlyBudgetCents), formatCents(b.spendCents), formatCents(b.remainingCents), `${pct}%`]
    })
    return { headers, rows }
  },
  cashflow: (data: CashFlowData) => {
    const headers = ['Month', 'Income', 'Expenses', 'Net']
    const rows = (data.monthlyTotals || []).map((m: any) => [m.month, formatCents(m.incomeCents), formatCents(m.expenseCents), formatCents(m.incomeCents - m.expenseCents)])
    return { headers, rows }
  },
  compare: (data: CompareData) => {
    const headers = ['Category', 'Previous', 'Current', 'Change', 'Change %']
    const rows = (data.categoryDeltas || []).map((c: any) => [c.name, formatCents(c.compareCents), formatCents(c.primaryCents), formatCents(c.changeCents), `${c.changePct}%`])
    return { headers, rows }
  },
}

export function formatCsv(tabId: TabId, data: any): CsvOutput {
  return FORMATTERS[tabId]?.(data) || { headers: [], rows: [] }
}

export async function formatPdf(element: HTMLElement, filename: string): Promise<Blob> {
  const { default: html2canvas } = await import('html2canvas')
  const { default: jsPDF } = await import('jspdf')

  const canvas = await html2canvas(element, {
    backgroundColor: '#0a0a0f',
    scale: 2,
    logging: false,
    useCORS: true,
  })

  const imgData = canvas.toDataURL('image/png')
  const pdf = new jsPDF('landscape', 'mm', 'a4')
  const pageWidth = pdf.internal.pageSize.getWidth()
  const pageHeight = (canvas.height * pageWidth) / canvas.width
  pdf.addImage(imgData, 'PNG', 0, 0, pageWidth, pageHeight)
  return pdf.output('blob')
}

import { TabId } from '../types'
import { formatCsv } from './csvFormatter'

export async function formatXlsx(tabId: TabId, data: any, filename: string): Promise<Blob> {
  const { headers, rows } = formatCsv(tabId, data)
  const { default: Excel } = await import('exceljs')
  const wb = new Excel.Workbook()
  const ws = wb.addWorksheet(tabId.charAt(0).toUpperCase() + tabId.slice(1))
  ws.columns = headers.map(h => ({ header: h, key: h, width: 20 }))
  ws.getRow(1).font = { bold: true, color: { argb: 'FFFFFFFF' } }
  ws.getRow(1).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF1a1a2e' } }
  rows.forEach(r => ws.addRow(r))
  const buffer = await wb.xlsx.writeBuffer()
  return new Blob([buffer], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' })
}

import React, { useMemo } from 'react'
import { useApi } from '../../../hooks/useApi'
import { useReportFilters } from '../context/ReportFilterContext'

const PRESETS = [
  { id: 'thisMonth', label: 'This Month', days: 0 },
  { id: 'lastMonth', label: 'Last Month', days: -1 },
  { id: 'last30', label: 'Last 30d', days: 30 },
  { id: 'last90', label: 'Last 90d', days: 90 },
  { id: 'thisYear', label: 'This Year', days: 0 },
  { id: 'custom', label: 'Custom', days: 0 },
]

function computePresetRange(preset: string): { from: string; to: string } {
  const now = new Date()
  const to = now.toISOString().split('T')[0]
  if (preset === 'thisMonth') {
    const from = new Date(now.getFullYear(), now.getMonth(), 1).toISOString().split('T')[0]
    return { from, to }
  }
  if (preset === 'lastMonth') {
    const first = new Date(now.getFullYear(), now.getMonth() - 1, 1)
    const last = new Date(now.getFullYear(), now.getMonth(), 0)
    return { from: first.toISOString().split('T')[0], to: last.toISOString().split('T')[0] }
  }
  if (preset === 'last30') {
    const from = new Date(now.getTime() - 30 * 86400000).toISOString().split('T')[0]
    return { from, to }
  }
  if (preset === 'last90') {
    const from = new Date(now.getTime() - 90 * 86400000).toISOString().split('T')[0]
    return { from, to }
  }
  if (preset === 'thisYear') {
    const from = new Date(now.getFullYear(), 0, 1).toISOString().split('T')[0]
    return { from, to }
  }
  return { from: to, to }
}

export const ReportFilters: React.FC = () => {
  const { filters, setDateRange, setFilters } = useReportFilters()
  const { data: accountsData } = useApi('/api/financials/accounts') as any
  const { data: categoriesData } = useApi('/api/financials/categories') as any

  const accounts: any[] = Array.isArray(accountsData) ? accountsData : []
  const categories: any[] = Array.isArray(categoriesData) ? categoriesData : []

  const handlePreset = (id: string) => {
    if (id === 'custom') {
      setFilters(prev => ({ ...prev, preset: 'custom' }))
      return
    }
    const range = computePresetRange(id)
    setDateRange(id, range.from, range.to)
  }

  const handleAccountToggle = (id: string) => {
    setFilters(prev => ({
      ...prev,
      accountIds: prev.accountIds.includes(id)
        ? prev.accountIds.filter(a => a !== id)
        : [...prev.accountIds, id],
    }))
  }

  const handleCategoryToggle = (id: string) => {
    setFilters(prev => ({
      ...prev,
      categoryIds: prev.categoryIds.includes(id)
        ? prev.categoryIds.filter(c => c !== id)
        : [...prev.categoryIds, id],
    }))
  }

  return (
    <div className="flex flex-wrap items-center gap-2">
      {/* Date Presets */}
      <div className="flex gap-1 bg-white/5 rounded-xl p-1">
        {PRESETS.map(p => (
          <button key={p.id} onClick={() => handlePreset(p.id)}
            className={`text-[10px] font-black tracking-widest px-2.5 py-1.5 rounded-lg transition-all ${filters.preset === p.id ? 'bg-primary text-black' : 'text-white/50 hover:text-white'}`}
          >
            {p.label}
          </button>
        ))}
      </div>

      {/* Custom date inputs */}
      {filters.preset === 'custom' && (
        <div className="flex items-center gap-2">
          <input type="date" value={filters.from} onChange={e => setFilters(prev => ({ ...prev, from: e.target.value }))}
            className="bg-white/5 border border-white/10 rounded-lg px-2 py-1.5 text-xs text-white outline-none" />
          <span className="text-[10px] text-white/30">→</span>
          <input type="date" value={filters.to} onChange={e => setFilters(prev => ({ ...prev, to: e.target.value }))}
            className="bg-white/5 border border-white/10 rounded-lg px-2 py-1.5 text-xs text-white outline-none" />
        </div>
      )}

      {/* Type filter */}
      <select value={filters.type} onChange={e => setFilters(prev => ({ ...prev, type: e.target.value as any }))}
        className="bg-white/5 border border-white/10 text-[10px] font-black tracking-widest px-2.5 py-1.5 rounded-xl text-secondary outline-none"
      >
        <option value="all">All</option>
        <option value="income">Income</option>
        <option value="expense">Expenses</option>
      </select>

      {/* Account filter */}
      {accounts.length > 0 && (
        <div className="relative group">
          <button className="bg-white/5 border border-white/10 text-[10px] font-black tracking-widest px-2.5 py-1.5 rounded-xl text-secondary hover:text-white transition-all">
            Accounts {filters.accountIds.length > 0 ? `(${filters.accountIds.length})` : ''}
          </button>
          <div className="absolute top-full left-0 mt-1 w-48 bg-deep border border-white/10 rounded-xl p-2 shadow-2xl z-20 hidden group-hover:block">
            {accounts.map((a: any) => (
              <label key={a.id} className="flex items-center gap-2 py-1 px-2 hover:bg-white/5 rounded-lg cursor-pointer text-xs">
                <input type="checkbox" checked={filters.accountIds.includes(a.id)} onChange={() => handleAccountToggle(a.id)}
                  className="rounded border-white/20 bg-white/5" />
                {a.name}
              </label>
            ))}
          </div>
        </div>
      )}

      {/* Category filter */}
      {categories.length > 0 && (
        <div className="relative group">
          <button className="bg-white/5 border border-white/10 text-[10px] font-black tracking-widest px-2.5 py-1.5 rounded-xl text-secondary hover:text-white transition-all">
            Categories {filters.categoryIds.length > 0 ? `(${filters.categoryIds.length})` : ''}
          </button>
          <div className="absolute top-full left-0 mt-1 w-48 bg-deep border border-white/10 rounded-xl p-2 shadow-2xl z-20 hidden group-hover:block">
            {categories.map((c: any) => (
              <label key={c.id} className="flex items-center gap-2 py-1 px-2 hover:bg-white/5 rounded-lg cursor-pointer text-xs">
                <input type="checkbox" checked={filters.categoryIds.includes(c.id)} onChange={() => handleCategoryToggle(c.id)}
                  className="rounded border-white/20 bg-white/5" />
                <span className="w-2 h-2 rounded-full" style={{ background: c.color }} />
                {c.name}
              </label>
            ))}
          </div>
        </div>
      )}
    </div>
  )
}

import { useMemo } from 'react'
import { useApi } from '../../../hooks/useApi'
import { useReportFilters } from '../context/ReportFilterContext'
import { getApiUrl } from '../../../utils/api'
import { ReportFilters } from '../types'

function buildQuery(filters: ReportFilters): string {
  const params = new URLSearchParams()
  if (filters.from) params.set('from', filters.from)
  if (filters.to) params.set('to', filters.to)
  if (filters.accountIds.length) params.set('account_ids', filters.accountIds.join(','))
  if (filters.categoryIds.length) params.set('category_ids', filters.categoryIds.join(','))
  if (filters.type !== 'all') params.set('type', filters.type)
  if (filters.compareFrom) params.set('compare_from', filters.compareFrom)
  if (filters.compareTo) params.set('compare_to', filters.compareTo)
  const qs = params.toString()
  return qs ? `?${qs}` : ''
}

export function useReportData<T>(endpoint: string) {
  const { filters } = useReportFilters()
  const query = useMemo(() => buildQuery(filters), [filters])
  return useApi<T>(`${endpoint}${query}` as any)
}

