interface ConfirmationNumberBuilderProps {
  value?: string
  onChangeValue?: (val: string) => void
  confirmationNumbers?: ConfirmationNumberItem[]
  onChangeNumbers?: (items: ConfirmationNumberItem[]) => void
  label?: string
  accentColor?: 'orange' | 'blue' | 'primary'
  compact?: boolean
  helperText?: string
}

export const ConfirmationNumberBuilder: React.FC<ConfirmationNumberBuilderProps> = ({
  value = '',
  onChangeValue,
  confirmationNumbers = [],
  onChangeNumbers,
  label = 'Categorized Confirmation Numbers & References',
  accentColor = 'primary',
  compact = false,
  helperText
}) => {
  const isOrange = accentColor === 'orange'
  const isBlue = accentColor === 'blue'

  const focusBorderClass = isOrange 
    ? 'focus:border-orange-500/50' 
    : isBlue 
    ? 'focus:border-blue-400' 
    : 'focus:border-primary'

  const badgeTextClass = isOrange
    ? 'text-orange-400'
    : isBlue
    ? 'text-blue-400'
    : 'text-primary'

  const badgeBgClass = isOrange
    ? 'bg-orange-500/10 hover:bg-orange-500/20 border-orange-500/20'
    : isBlue
    ? 'bg-blue-500/10 hover:bg-blue-500/20 border-blue-500/20'
    : 'bg-primary/10 hover:bg-primary/20 border-primary/20'

  const handleAddInstance = () => {
    if (!onChangeNumbers) return
    const next: ConfirmationNumberItem[] = [
      ...confirmationNumbers,
      { category: 'confirmation', value: '', customCategoryLabel: '' }
    ]
    onChangeNumbers(next)
  }

  const handleUpdateInstance = (idx: number, updates: Partial<ConfirmationNumberItem>) => {
    if (!onChangeNumbers) return
    const next = [...confirmationNumbers]
    next[idx] = { ...next[idx], ...updates }
    onChangeNumbers(next)
  }

  const handleRemoveInstance = (idx: number) => {
    if (!onChangeNumbers) return
    const next = confirmationNumbers.filter((_, i) => i !== idx)
    onChangeNumbers(next)
  }

  return (
    <div className={`bg-black/30 border border-white/10 rounded-2xl ${compact ? 'p-3' : 'p-4'} space-y-3`}>
      <div className="flex items-center justify-between gap-2 flex-wrap">
        <label className="text-xs font-bold tracking-wider text-secondary flex items-center gap-1.5">
          <Hash size={13} className={badgeTextClass} /> {label}
        </label>
        {onChangeNumbers && (
          <button
            type="button"
            onClick={handleAddInstance}
            className={`text-[10px] font-black tracking-wider ${badgeTextClass} hover:text-white px-2.5 py-1 rounded-xl ${badgeBgClass} border flex items-center gap-1 cursor-pointer transition-all`}
          >
            <Plus size={11} /> Add Reference Number
          </button>
        )}
      </div>

      {helperText && (
        <p className="text-[10px] text-slate-400 font-medium leading-relaxed">{helperText}</p>
      )}

      {/* Primary Reference Row */}
      <div className="grid grid-cols-1 sm:grid-cols-12 gap-2.5 items-center">
        <div className="sm:col-span-4">
          <SearchableSelect
            options={CONFIRMATION_NUMBER_CATEGORIES}
            value="confirmation"
            onChange={(cat) => {
              if (cat !== 'confirmation' && onChangeNumbers) {
                const next: ConfirmationNumberItem[] = [
                  { category: cat, value: value, customCategoryLabel: '' },
                  ...confirmationNumbers
                ]
                onChangeNumbers(next)
                if (onChangeValue) onChangeValue('')
              }
            }}
            placeholder="Category..."
          />
        </div>
        <div className="sm:col-span-8">
          <input
            type="text"
            value={value}
            onChange={(e) => onChangeValue && onChangeValue(e.target.value)}
            placeholder="e.g. TXN-12345, Auth #, Receipt ID, Ref #..."
            className={`w-full bg-black/40 border border-white/10 rounded-xl p-2.5 text-xs text-white focus:outline-none ${focusBorderClass} transition-colors placeholder:text-white/20`}
          />
        </div>
      </div>

      {/* Multi-instance Rows */}
      {confirmationNumbers.map((cn, idx) => (
        <div key={idx} className="grid grid-cols-1 sm:grid-cols-12 gap-2.5 items-center pt-2.5 border-t border-white/5">
          <div className="sm:col-span-4">
            <SearchableSelect
              options={CONFIRMATION_NUMBER_CATEGORIES}
              value={cn.category || 'confirmation'}
              onChange={(cat) => handleUpdateInstance(idx, { category: cat })}
              placeholder="Category..."
            />
          </div>
          <div className={cn.category === 'custom' ? 'sm:col-span-3' : 'sm:col-span-7'}>
            <input
              type="text"
              value={cn.value}
              onChange={(e) => handleUpdateInstance(idx, { value: e.target.value })}
              placeholder="Reference Value..."
              className={`w-full bg-black/40 border border-white/10 rounded-xl p-2.5 text-xs text-white focus:outline-none ${focusBorderClass} transition-colors placeholder:text-white/20`}
            />
          </div>
          {cn.category === 'custom' && (
            <div className="sm:col-span-4">
              <input
                type="text"
                value={cn.customCategoryLabel || ''}
                onChange={(e) => handleUpdateInstance(idx, { customCategoryLabel: e.target.value })}
                placeholder="Custom Label..."
                className={`w-full bg-black/40 border border-white/10 rounded-xl p-2.5 text-xs text-white focus:outline-none ${focusBorderClass} transition-colors placeholder:text-white/20`}
              />
            </div>
          )}
          <div className="sm:col-span-1 flex justify-end">
            <button
              type="button"
              onClick={() => handleRemoveInstance(idx)}
              className="p-1.5 text-red-400 hover:text-red-300 hover:bg-red-500/10 rounded-lg transition-all cursor-pointer"
              title="Remove reference number"
            >
              <Trash2 size={13} />
            </button>
          </div>
        </div>
      ))}
    </div>
  )
}

import React from 'react';

interface CurrencyInputProps extends Omit<React.InputHTMLAttributes<HTMLInputElement>, 'value' | 'onChange'> {
  valueCents: number;
  onChangeCents: (cents: number) => void;
  showSymbol?: boolean;
}

export const CurrencyInput: React.FC<CurrencyInputProps> = ({
  valueCents,
  onChangeCents,
  showSymbol = true,
  className = '',
  ...props
}) => {
  const displayValue = (valueCents / 100).toFixed(2);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const digits = e.target.value.replace(/\D/g, '');
    if (!digits) {
      onChangeCents(0);
      return;
    }
    const cents = parseInt(digits, 10);
    onChangeCents(cents);
  };

  return (
    <div className="relative">
      {showSymbol && (
        <span className="absolute left-3 top-1/2 -translate-y-1/2 text-secondary font-black text-sm pointer-events-none">
          $
        </span>
      )}
      <input
        type="text"
        inputMode="numeric"
        value={displayValue}
        onChange={handleChange}
        className={`w-full bg-black/40 border border-white/10 rounded-xl p-3 ${showSymbol ? 'pl-8' : ''} text-white focus:outline-none focus:border-primary transition-colors ${className}`}
        {...props}
      />
    </div>
  );
};
export default CurrencyInput;

import React, { useState, useEffect } from 'react'
import { Clock } from 'lucide-react'

interface DateTimeInputProps {
  /** ISO date string ("YYYY-MM-DD") or datetime-local string ("YYYY-MM-DDTHH:MM") */
  value: string
  onChange: (value: string) => void
  className?: string
  required?: boolean
}

/** Splits a stored value into its date and time parts */
const splitValue = (v: string): { date: string; time: string } => {
  if (!v) return { date: '', time: '' }
  const parts = v.split('T')
  return { date: parts[0] ?? '', time: parts[1] ?? '' }
}

export const DateTimeInput: React.FC<DateTimeInputProps> = ({
  value,
  onChange,
  className = '',
  required
}) => {
  const [date, setDate] = useState(splitValue(value).date)
  const [time, setTime] = useState(splitValue(value).time)
  const [showTime, setShowTime] = useState(!!splitValue(value).time)

  // Sync internal state when the external value changes
  useEffect(() => {
    const parts = splitValue(value)
    setDate(parts.date)
    setTime(parts.time)
    setShowTime(!!parts.time)
  }, [value])

  const handleDateChange = (newDate: string) => {
    setDate(newDate)
    onChange(time && showTime ? `${newDate}T${time}` : newDate)
  }

  const handleTimeChange = (newTime: string) => {
    setTime(newTime)
    onChange(date ? `${date}T${newTime}` : newTime)
  }

  const handleToggleTime = () => {
    if (showTime) {
      // Removing time — collapse back to date-only
      setShowTime(false)
      setTime('')
      if (date) onChange(date)
    } else {
      setShowTime(true)
    }
  }

  const baseInput = `bg-black/60 border border-white/10 rounded-xl p-2 text-sm text-white focus:border-blue-400/50 outline-none ${className}`

  return (
    <div className="space-y-2">
      <div className="flex items-center gap-2">
        <input
          type="date"
          value={date}
          onChange={e => handleDateChange(e.target.value)}
          required={required}
          style={{ colorScheme: 'dark' }}
          className={`flex-1 ${baseInput}`}
        />
        <button
          type="button"
          onClick={handleToggleTime}
          title={showTime ? 'Remove time' : 'Add specific time'}
          className={`p-2 rounded-lg border transition-colors flex-shrink-0 ${
            showTime
              ? 'bg-blue-500/20 border-blue-500/40 text-blue-400'
              : 'bg-white/5 border-white/10 text-secondary hover:text-white hover:border-white/30'
          }`}
        >
          <Clock size={14} />
        </button>
      </div>
      {showTime && (
        <input
          type="time"
          value={time}
          onChange={e => handleTimeChange(e.target.value)}
          style={{ colorScheme: 'dark' }}
          className={`w-full ${baseInput}`}
          placeholder="HH:MM (optional)"
        />
      )}
      {(date || time) && (
        <p className="text-[10px] text-secondary/60">
          {date && !showTime && `Date: ${date}`}
          {date && showTime && time && `Scheduled: ${date} at ${time}`}
          {date && showTime && !time && `Date: ${date} — select a time above`}
        </p>
      )}
    </div>
  )
}

