import React, { useEffect, useRef } from 'react';
import { createPortal } from 'react-dom';
import { motion, AnimatePresence } from 'framer-motion';
import { X } from 'lucide-react';
import { useReducedMotion } from '../../hooks/useReducedMotion';

interface ModalProps {
  isOpen: boolean;
  onClose: () => void;
  title: string;
  children: React.ReactNode;
  footer?: React.ReactNode;
  maxWidth?: string;
}

export const Modal: React.FC<ModalProps> = ({ isOpen, onClose, title, children, footer, maxWidth = 'max-w-lg' }) => {
  const modalRef = useRef<HTMLDivElement>(null);
  const reduced = useReducedMotion();

  useEffect(() => {
    if (!isOpen) return;
    document.body.style.overflow = 'hidden';
    return () => { document.body.style.overflow = '' };
  }, [isOpen]);

  useEffect(() => {
    if (!isOpen) return;
    const modal = modalRef.current;
    if (!modal) return;
    const focusable = modal.querySelectorAll<HTMLElement>(
      'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])'
    );
    const first = focusable[0];
    const last = focusable[focusable.length - 1];
    first?.focus();
    const handleTab = (e: KeyboardEvent) => {
      if (e.key === 'Tab') {
        if (e.shiftKey) {
          if (document.activeElement === first) {
            e.preventDefault();
            last?.focus();
          }
        } else {
          if (document.activeElement === last) {
            e.preventDefault();
            first?.focus();
          }
        }
      }
    };
    modal.addEventListener('keydown', handleTab);
    return () => modal.removeEventListener('keydown', handleTab);
  }, [isOpen]);

  const ModalContainer = reduced ? 'div' : motion.div;
  const containerProps = reduced ? {} : {
    initial: { opacity: 0, scale: 0.92, y: 24 },
    animate: { opacity: 1, scale: 1, y: 0 },
    transition: { duration: 0.2, ease: 'easeOut' }
  };

  if (!isOpen) return null;

  const modalContent = (
    <div className="fixed inset-0 z-[10000] flex items-center justify-center p-4 sm:p-6">
      <div
        className="absolute inset-0 bg-black/80 backdrop-blur-xl"
        onClick={onClose}
      />
      {/* @ts-ignore */}
      <ModalContainer
        {...containerProps}
        ref={modalRef}
        role="dialog"
        aria-modal="true"
        aria-labelledby="modal-title"
        className={`relative w-full ${maxWidth} bg-slate-900/95 backdrop-blur-xl border border-glass-border rounded-3xl shadow-2xl overflow-hidden`}
      >
        <div className="flex items-center justify-between p-6 border-b border-glass-border">
          <h3 id="modal-title" className="text-xl font-black tracking-tight">{title}</h3>
          <button
            onClick={onClose}
            className="w-10 h-10 flex items-center justify-center hover:bg-white/5 rounded-full transition-all text-slate-500 hover:text-white"
          >
            <X size={20} />
          </button>
        </div>

        <div className="p-8 overflow-y-auto max-h-[calc(100vh-200px)]">
          {children}
        </div>

        {footer && (
          <div className="flex justify-end gap-4 p-6 bg-white/5 border-t border-glass-border">
            {footer}
          </div>
        )}
      </ModalContainer>
    </div>
  );

  return createPortal(modalContent, document.body);
};

import React, { useState, useRef, useEffect, useMemo, useCallback } from 'react';
import { createPortal } from 'react-dom';
import { Search, ChevronDown, Check, Plus } from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';
import { useReducedMotion } from '../../hooks/useReducedMotion';

export interface SearchableOption {
  value: string;
  label: string;
  icon?: React.ReactNode;
  metadata?: any;
}

interface SearchableSelectProps {
  options: SearchableOption[];
  value: string;
  onChange: (value: string) => void;
  placeholder?: string;
  className?: string;
  icon?: React.ReactNode;
  onCreate?: (search: string) => Promise<string | void> | string | void;
}

// ─────────────────────────────────────────────────────────
// Portal-based dropdown — renders into document.body so it
// cannot be clipped or stacked-under by any ancestor transform,
// overflow:hidden, or stacking context.
// ─────────────────────────────────────────────────────────

interface DropdownPortalProps {
  triggerRef: React.RefObject<HTMLDivElement | null>;
  portalRef: React.RefObject<HTMLDivElement | null>;
  children: React.ReactNode;
}

const DropdownPortal: React.FC<DropdownPortalProps> = ({ triggerRef, portalRef, children }) => {
  const [style, setStyle] = useState<React.CSSProperties>({});

  useEffect(() => {
    const position = () => {
      if (!triggerRef.current) return;
      const rect = triggerRef.current.getBoundingClientRect();
      const spaceBelow = window.innerHeight - rect.bottom;
      const dropdownHeight = 380; // approximate max-height
      const above = spaceBelow < dropdownHeight && rect.top > dropdownHeight;

      const dropdownWidth = Math.max(rect.width, 240);
      // Ensure left doesn't overflow right viewport edge
      const maxLeft = window.innerWidth - dropdownWidth - 12;
      const clampedLeft = Math.max(12, Math.min(rect.left, maxLeft));

      setStyle({
        position: 'fixed',
        zIndex: 50000,
        left: clampedLeft,
        width: Math.min(dropdownWidth, window.innerWidth - 24),
        ...(above
          ? { bottom: window.innerHeight - rect.top + 4 }
          : { top: rect.bottom + 4 }),
      });
    };

    position();

    window.addEventListener('scroll', position, true);
    window.addEventListener('resize', position);
    return () => {
      window.removeEventListener('scroll', position, true);
      window.removeEventListener('resize', position);
    };
  }, [triggerRef]);

  return createPortal(
    // Attach the portalRef so the parent can detect clicks inside the portal
    <div style={style} ref={portalRef}>{children}</div>,
    document.body
  );
};

// ─────────────────────────────────────────────────────────
// Shared dropdown content (used in both animated/reduced branches)
// ─────────────────────────────────────────────────────────

interface DropdownContentProps {
  inputRef: React.RefObject<HTMLInputElement | null>;
  search: string;
  setSearch: (v: string) => void;
  filteredOptions: SearchableOption[];
  showCreateOption: boolean;
  activeIndex: number;
  setActiveIndex: (i: number) => void;
  value: string;
  onChange: (v: string) => void;
  setIsOpen: (v: boolean) => void;
  onCreate?: SearchableSelectProps['onCreate'];
}

const DropdownContent: React.FC<DropdownContentProps> = ({
  inputRef, search, setSearch, filteredOptions, showCreateOption,
  activeIndex, setActiveIndex, value, onChange, setIsOpen, onCreate,
}) => (
  <>
    {/* Search Input */}
    <div className="p-3 border-b border-white/5 bg-white/2">
      <div className="relative flex items-center">
        <Search size={14} className="absolute left-3 text-slate-500" />
        <input
          ref={inputRef}
          type="text"
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          placeholder="Typing to suggest..."
          className="w-full bg-black/40 border border-white/10 rounded-xl pl-9 pr-4 py-2.5 text-sm text-white placeholder:text-slate-600 focus:border-amber-500/30 transition-all"
          // prevent the input click from bubbling up to the trigger toggle
          onClick={(e) => e.stopPropagation()}
          // prevent mousedown from triggering the outside-click handler
          onMouseDown={(e) => e.stopPropagation()}
        />
      </div>
    </div>

    {/* Options List */}
    <div className="max-h-[300px] overflow-y-auto scrollbar-thin scrollbar-thumb-white/10" role="listbox">
      {showCreateOption && (
        <div
          role="option"
          onMouseDown={(e) => e.preventDefault()} // keep focus on input, prevent outside-click
          onClick={async (e) => {
            e.stopPropagation();
            const newId = await onCreate!(search.trim());
            if (newId) onChange(newId);
            setSearch('');
            setIsOpen(false);
          }}
          className="flex items-center gap-4 px-5 py-4 cursor-pointer transition-all hover:bg-white/5 text-amber-500 font-bold"
        >
          <div className="w-10 h-10 rounded-xl bg-amber-500/10 flex items-center justify-center border border-amber-500/20 overflow-hidden">
            <Plus size={16} className="text-amber-500" />
          </div>
          <div className="flex-1 flex flex-col">
            <span className="text-sm font-bold tracking-tight">Create "{search.trim()}"</span>
          </div>
        </div>
      )}

      {filteredOptions.length === 0 && !search ? (
        <div className="p-8 text-center text-slate-400">
          <p className="text-xs font-black tracking-widest text-amber-500/80 mb-1.5">No options created yet</p>
          <p className="text-[11px] text-slate-500 font-bold leading-normal">Type a name in the search box above to create one dynamically!</p>
        </div>
      ) : filteredOptions.length > 0 ? (
        filteredOptions.map((option, idx) => {
          const isActive = idx === activeIndex;
          const isSelected = option.value === value;
          return (
            <div
              key={option.value}
              role="option"
              aria-selected={isSelected}
              // Use onMouseDown + preventDefault to register the selection
              // BEFORE the document mousedown outside-click handler fires,
              // without losing focus or closing the dropdown prematurely.
              onMouseDown={(e) => {
                e.preventDefault(); // prevents focus loss & outside-click
                onChange(option.value);
                setIsOpen(false);
              }}
              onMouseEnter={() => setActiveIndex(idx)}
              className={`flex items-center gap-4 px-5 py-4 cursor-pointer transition-all ${
                isActive ? 'bg-white/5' : ''
              } ${isSelected ? 'text-amber-500' : 'text-slate-300'}`}
            >
              <div className="w-10 h-10 rounded-xl bg-black/40 flex items-center justify-center border border-white/5 overflow-hidden">
                {option.icon || <div className="text-sm font-black italic">{option.label.charAt(0)}</div>}
              </div>
              <div className="flex-1 flex flex-col">
                <span className="text-sm font-bold tracking-tight">{option.label}</span>
                {option.metadata?.email && (
                  <span className="text-xs text-slate-500 font-medium">{option.metadata.email}</span>
                )}
              </div>
              {isSelected && <Check size={16} className="text-amber-500" />}
            </div>
          );
        })
      ) : (
        <div className="p-12 text-center">
          <p className="text-sm text-slate-600 font-black tracking-[0.2em] italic">No Matches Found</p>
        </div>
      )}
    </div>
  </>
);

// ─────────────────────────────────────────────────────────
// Main SearchableSelect component
// ─────────────────────────────────────────────────────────

const DROPDOWN_CLASSES = 'bg-bg-dark border border-white/10 rounded-[1.5rem] shadow-2xl overflow-hidden';

export const SearchableSelect: React.FC<SearchableSelectProps> = ({
  options,
  value,
  onChange,
  placeholder = 'Select option...',
  className = '',
  icon: LeadingIcon,
  onCreate,
}) => {
  const reduced = useReducedMotion();
  const [isOpen, setIsOpen] = useState(false);
  const [search, setSearch] = useState('');
  const [activeIndex, setActiveIndex] = useState(0);
  const triggerRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  // Ref to the portal wrapper div — used to detect clicks inside the portal
  const portalRef = useRef<HTMLDivElement>(null);

  const sortedOptions = useMemo(() => [...options].sort((a, b) => a.label.localeCompare(b.label)), [options]);
  const selectedOption = useMemo(() => sortedOptions.find(o => o.value === value), [sortedOptions, value]);

  const showCreateOption = useMemo(() => {
    if (!onCreate || !search.trim()) return false;
    return !sortedOptions.some(opt => opt.label.toLowerCase() === search.trim().toLowerCase());
  }, [sortedOptions, search, onCreate]);

  const filteredOptions = useMemo(() => {
    if (!search) return sortedOptions;
    return sortedOptions.filter(opt =>
      opt.label.toLowerCase().includes(search.toLowerCase()) ||
      (opt.metadata?.email && opt.metadata.email.toLowerCase().includes(search.toLowerCase()))
    );
  }, [sortedOptions, search]);

  useEffect(() => { setActiveIndex(0); }, [search]);

  // Close on outside click — correctly excludes clicks inside the portal
  const handleClickOutside = useCallback((e: MouseEvent) => {
    const target = e.target as Node;
    // If click is inside the trigger or inside the portal dropdown, ignore
    if (triggerRef.current?.contains(target)) return;
    if (portalRef.current?.contains(target)) return;
    setIsOpen(false);
  }, []);

  useEffect(() => {
    if (isOpen) {
      document.addEventListener('mousedown', handleClickOutside);
    }
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, [isOpen, handleClickOutside]);

  // Clear search when closed
  useEffect(() => {
    if (!isOpen) setSearch('');
  }, [isOpen]);

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (!isOpen) {
      if (e.key === 'Enter' || e.key === ' ' || e.key === 'ArrowDown') setIsOpen(true);
      return;
    }
    switch (e.key) {
      case 'ArrowDown':
        e.preventDefault();
        setActiveIndex(prev => (prev + 1) % filteredOptions.length);
        break;
      case 'ArrowUp':
        e.preventDefault();
        setActiveIndex(prev => (prev - 1 + filteredOptions.length) % filteredOptions.length);
        break;
      case 'Enter':
        e.preventDefault();
        if (filteredOptions[activeIndex]) {
          onChange(filteredOptions[activeIndex].value);
          setIsOpen(false);
        }
        break;
      case 'Escape':
        setIsOpen(false);
        break;
    }
  };

  const contentProps: DropdownContentProps = {
    inputRef, search, setSearch, filteredOptions, showCreateOption,
    activeIndex, setActiveIndex, value, onChange, setIsOpen, onCreate,
  };

  return (
    <div className={`relative ${className}`} ref={triggerRef} onKeyDown={handleKeyDown}>
      {/* Trigger button */}
      <div
        onClick={(e) => {
          e.stopPropagation();
          setIsOpen(!isOpen);
          if (!isOpen) setTimeout(() => inputRef.current?.focus(), 50);
        }}
        aria-expanded={isOpen}
        aria-haspopup="listbox"
        className={`flex items-center gap-3 px-4 py-3 bg-black/40 border rounded-xl cursor-pointer transition-all duration-300 group ${
          isOpen ? 'border-amber-500/50 ring-1 ring-amber-500/20' : 'border-white/10 hover:border-white/20'
        }`}
      >
        <div className="flex-1 flex items-center gap-3 overflow-hidden">
          {selectedOption?.icon || LeadingIcon || <Search size={16} className="text-slate-500 group-hover:text-amber-500/50 transition-colors" />}
          <div className="flex flex-col overflow-hidden">
            <span className={`text-sm tracking-tight truncate ${selectedOption ? 'text-white font-medium' : 'text-slate-500'}`}>
              {selectedOption ? selectedOption.label : placeholder}
            </span>
            {selectedOption?.metadata?.subtext && (
              <span className="text-[12px] text-slate-500 font-black tracking-widest truncate">
                {selectedOption.metadata.subtext}
              </span>
            )}
          </div>
        </div>
        <ChevronDown size={16} className={`text-slate-500 transition-transform duration-300 ${isOpen ? 'rotate-180' : ''}`} />
      </div>

      {/* Portal dropdown — escapes all ancestor stacking contexts */}
      {isOpen && (
        <DropdownPortal triggerRef={triggerRef} portalRef={portalRef}>
          {reduced ? (
            <div
              className={DROPDOWN_CLASSES}
              style={{ backfaceVisibility: 'hidden' }}
            >
              <DropdownContent {...contentProps} />
            </div>
          ) : (
            <AnimatePresence>
              <motion.div
                initial={{ opacity: 0, y: -8, scale: 0.97 }}
                animate={{ opacity: 1, y: 0, scale: 1 }}
                exit={{ opacity: 0, y: -8, scale: 0.97 }}
                transition={{ duration: 0.15, ease: 'easeOut' }}
                className={DROPDOWN_CLASSES}
                style={{ backfaceVisibility: 'hidden' }}
              >
                <DropdownContent {...contentProps} />
              </motion.div>
            </AnimatePresence>
          )}
        </DropdownPortal>
      )}
    </div>
  );
};

import React, { useState, useRef, useEffect, useMemo } from 'react';
import { Search, ChevronDown, Check, Plus } from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';
import { useReducedMotion } from '../../hooks/useReducedMotion';

export interface TypeableOption {
  value: string;
  label: string;
  description?: string;
  icon?: React.ReactNode;
  metadata?: any;
}

interface TypeableSelectProps {
  options: TypeableOption[];
  value: string;
  onChange: (value: string) => void;
  placeholder?: string;
  className?: string;
  icon?: React.ReactNode;
}

export const TypeableSelect: React.FC<TypeableSelectProps> = ({ 
  options, 
  value, 
  onChange, 
  placeholder = "Select or type...", 
  className = "",
  icon: LeadingIcon
}) => {
  const reduced = useReducedMotion();
  const [isOpen, setIsOpen] = useState(false);
  const [search, setSearch] = useState('');
  const [activeIndex, setActiveIndex] = useState(0);
  const containerRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  const sortedOptions = useMemo(() => {
    return [...options].sort((a, b) => a.label.localeCompare(b.label));
  }, [options]);

  const selectedOption = useMemo(() => sortedOptions.find(o => o.value === value) || { value, label: value }, [sortedOptions, value]);

  const filteredOptions = useMemo(() => {
    const filtered = sortedOptions.filter(opt => 
      opt.label.toLowerCase().includes(search.toLowerCase())
    );

    // Add "custom" option if search doesn't exactly match any label
    if (search && !sortedOptions.some(opt => opt.label.toLowerCase() === search.toLowerCase())) {
      filtered.unshift({
        value: search,
        label: `Use "${search}"`,
        icon: <Plus size={14} className="text-amber-500" />,
        metadata: { isCustom: true }
      });
    }

    return filtered;
  }, [sortedOptions, search]);

  useEffect(() => {
    setActiveIndex(0);
  }, [search]);

  useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => {
      if (containerRef.current && !containerRef.current.contains(e.target as Node)) {
        setIsOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (!isOpen) {
      if (e.key === 'Enter' || e.key === ' ' || e.key === 'ArrowDown') {
        setIsOpen(true);
      }
      return;
    }

    switch (e.key) {
      case 'ArrowDown':
        e.preventDefault();
        setActiveIndex(prev => (prev + 1) % filteredOptions.length);
        break;
      case 'ArrowUp':
        e.preventDefault();
        setActiveIndex(prev => (prev - 1 + filteredOptions.length) % filteredOptions.length);
        break;
      case 'Enter':
        e.preventDefault();
        if (filteredOptions[activeIndex]) {
          onChange(filteredOptions[activeIndex].value);
          setIsOpen(false);
          setSearch('');
        }
        break;
      case 'Escape':
        setIsOpen(false);
        break;
    }
  };

  return (
    <div className={`relative ${className}`} ref={containerRef} onKeyDown={handleKeyDown}>
      {/* Trigger */}
      <div 
        onClick={() => {
          setIsOpen(!isOpen);
          if (!isOpen) setTimeout(() => inputRef.current?.focus(), 50);
        }}
        aria-expanded={isOpen}
        aria-haspopup="listbox"
        className={`flex items-center gap-3 px-4 py-3 bg-black/40 border rounded-xl cursor-pointer transition-all duration-300 group ${
          isOpen ? 'border-amber-500/50 ring-1 ring-amber-500/20' : 'border-white/10 hover:border-white/20'
        }`}
      >
        <div className="flex-1 flex items-center gap-3 overflow-hidden">
            {selectedOption?.icon || LeadingIcon || <Search size={16} className="text-slate-500 group-hover:text-amber-500/50 transition-colors" />}
            <div className="flex flex-col overflow-hidden">
              <span className={`text-sm tracking-tight truncate font-black ${selectedOption ? 'text-white' : 'text-slate-500'}`}>
                {selectedOption ? selectedOption.label : placeholder}
              </span>
            </div>
        </div>
        <ChevronDown size={16} className={`text-slate-500 transition-transform duration-300 ${isOpen ? 'rotate-180' : ''}`} />
      </div>

      {/* Dropdown Menu */}
      {reduced ? (
        isOpen && (
          <div className="absolute z-[3000] left-0 right-0 mt-2 bg-[#121212]/95 backdrop-blur-2xl border border-white/10 rounded-[1.5rem] shadow-2xl overflow-hidden shadow-[0_20px_50px_rgba(0,0,0,0.5)]">
            {/* Search Input */}
            <div className="p-3 border-b border-white/5 bg-white/2">
              <div className="relative flex items-center">
                <Search size={14} className="absolute left-3 text-slate-500" />
                <input 
                  ref={inputRef}
                  type="text" 
                  value={search}
                  onChange={(e) => setSearch(e.target.value)}
                  placeholder="Type to find or add..."
                  className="w-full bg-black/40 border border-white/10 rounded-xl pl-9 pr-4 py-2.5 text-sm text-white placeholder:text-slate-600 focus:border-amber-500/30 transition-all font-medium"
                  onClick={(e) => e.stopPropagation()}
                />
              </div>
            </div>

            {/* Options List */}
            <div className="max-h-[300px] overflow-y-auto scrollbar-thin scrollbar-thumb-white/10" role="listbox">
              {filteredOptions.length > 0 ? (
                filteredOptions.map((option, idx) => {
                  const isActive = idx === activeIndex;
                  const isSelected = option.value === value;

                  return (
                    <div
                      key={option.value}
                      role="option"
                      aria-selected={isSelected}
                      title={option.description}
                      onClick={(e) => {
                        e.stopPropagation();
                        onChange(option.value);
                        setIsOpen(false);
                        setSearch('');
                      }}
                      onMouseEnter={() => setActiveIndex(idx)}
                      className={`flex items-center gap-4 px-5 py-3 cursor-pointer transition-all ${
                        isActive ? 'bg-white/5' : ''
                      } ${isSelected ? 'text-amber-500' : 'text-slate-300'}`}
                    >
                      <div className="w-8 h-8 rounded-lg bg-black/40 flex items-center justify-center border border-white/5 overflow-hidden">
                        {option.icon || <div className="text-[10px] font-black italic">{option.label.charAt(0)}</div>}
                      </div>
                      <div className="flex-1 flex flex-col">
                        <span className={`text-sm font-black tracking-tight ${option.metadata?.isCustom ? 'italic text-amber-500/80' : ''}`}>{option.label}</span>
                          {option.description && (
                            <span className="text-[10px] text-slate-500 font-medium tracking-tight mt-0.5 leading-normal">{option.description}</span>
                          )}
                        </div>
                        {isSelected && <Check size={16} className="text-amber-500" />}
                      </div>
                    );
                  })
                ) : (
                  <div className="p-12 text-center">
                     <p className="text-sm text-slate-600 font-black tracking-[0.2em] italic">No Matches Found</p>
                </div>
              )}
            </div>
          </div>
        )
      ) : (
        <AnimatePresence>
          {isOpen && (
            <motion.div
              initial={{ opacity: 0, y: -10, scale: 0.95 }}
              animate={{ opacity: 1, y: 0, scale: 1 }}
              exit={{ opacity: 0, y: -10, scale: 0.95 }}
              transition={{ duration: 0.2, ease: "easeOut" }}
              className="absolute z-[3000] left-0 right-0 mt-2 bg-[#121212]/95 backdrop-blur-2xl border border-white/10 rounded-[1.5rem] shadow-2xl overflow-hidden shadow-[0_20px_50px_rgba(0,0,0,0.5)]"
            >
              {/* Search Input */}
              <div className="p-3 border-b border-white/5 bg-white/2">
                <div className="relative flex items-center">
                  <Search size={14} className="absolute left-3 text-slate-500" />
                  <input 
                    ref={inputRef}
                    type="text" 
                    value={search}
                    onChange={(e) => setSearch(e.target.value)}
                    placeholder="Type to find or add..."
                    className="w-full bg-black/40 border border-white/10 rounded-xl pl-9 pr-4 py-2.5 text-sm text-white placeholder:text-slate-600 focus:border-amber-500/30 transition-all font-medium"
                    onClick={(e) => e.stopPropagation()}
                  />
                </div>
              </div>

              {/* Options List */}
              <div className="max-h-[300px] overflow-y-auto scrollbar-thin scrollbar-thumb-white/10" role="listbox">
                {filteredOptions.length > 0 ? (
                  filteredOptions.map((option, idx) => {
                    const isActive = idx === activeIndex;
                    const isSelected = option.value === value;

                    return (
                      <div
                        key={option.value}
                        role="option"
                        aria-selected={isSelected}
                        title={option.description}
                        onClick={(e) => {
                          e.stopPropagation();
                          onChange(option.value);
                          setIsOpen(false);
                          setSearch('');
                        }}
                        onMouseEnter={() => setActiveIndex(idx)}
                        className={`flex items-center gap-4 px-5 py-3 cursor-pointer transition-all ${
                          isActive ? 'bg-white/5' : ''
                        } ${isSelected ? 'text-amber-500' : 'text-slate-300'}`}
                      >
                        <div className="w-8 h-8 rounded-lg bg-black/40 flex items-center justify-center border border-white/5 overflow-hidden">
                          {option.icon || <div className="text-[10px] font-black italic">{option.label.charAt(0)}</div>}
                        </div>
                        <div className="flex-1 flex flex-col">
                        <span className={`text-sm font-black tracking-tight ${option.metadata?.isCustom ? 'italic text-amber-500/80' : ''}`}>{option.label}</span>
                          {option.description && (
                            <span className="text-[10px] text-slate-500 font-medium tracking-tight mt-0.5 leading-normal">{option.description}</span>
                          )}
                        </div>
                        {isSelected && <Check size={16} className="text-amber-500" />}
                      </div>
                    );
                  })
                ) : (
                  <div className="p-12 text-center">
                   <p className="text-sm text-slate-600 font-black tracking-[0.2em] italic">No Matches Found</p>
                  </div>
                )}
              </div>
            </motion.div>
          )}
        </AnimatePresence>
      )}
    </div>
  );
};

import React from 'react'
import { FieldDef } from '../../lib/entity-field-defs'
import { Lock, Unlock } from 'lucide-react'

interface TypedFieldInputProps {
  def: FieldDef
  value: any
  onChange: (value: any) => void
  disabled?: boolean
  onToggleLock?: () => void
}

export const TypedFieldInput: React.FC<TypedFieldInputProps> = ({ def, value, onChange, disabled, onToggleLock }) => {
  const showPadlock = def.locked && onToggleLock

  if (def.type === 'boolean') {
    return (
      <div className="flex items-center gap-3">
        <label className="flex items-center gap-3 cursor-pointer">
          <input
            type="checkbox"
            checked={value === true || value === 'true' || value === 1}
            onChange={e => onChange(e.target.checked)}
            disabled={disabled}
            className="sr-only peer"
          />
          <div className={`w-10 h-5 rounded-full transition-colors relative after:content-[''] after:absolute after:top-0.5 after:left-0.5 after:rounded-full after:h-4 after:w-4 after:transition-all peer-checked:after:translate-x-5 ${disabled ? 'bg-white/5' : 'bg-white/10 peer-checked:bg-primary'} ${disabled ? 'after:bg-white/20' : 'after:bg-white/40 peer-checked:after:bg-white'}`} />
          <span className="text-sm text-white/60">{value ? 'Enabled' : 'Disabled'}</span>
        </label>
        {showPadlock && (
          <button type="button" onClick={onToggleLock} className="text-white/30 hover:text-white transition-colors" title={disabled ? 'Unlock to edit' : 'Lock'}>
            {disabled ? <Lock size={14} /> : <Unlock size={14} />}
          </button>
        )}
      </div>
    )
  }

  if (def.type === 'select') {
    return (
      <div className="relative">
        <select
          value={value ?? ''}
          onChange={e => onChange(e.target.value)}
          disabled={disabled}
          className="w-full p-2.5 bg-black/40 border border-white/10 rounded-xl text-sm font-mono disabled:opacity-50 disabled:cursor-not-allowed appearance-none"
        >
          <option value="">Select...</option>
          {def.options?.map(o => (
            <option key={o.value} value={o.value}>{o.label}</option>
          ))}
        </select>
        {showPadlock && (
          <button type="button" onClick={onToggleLock} className="absolute right-3 top-1/2 -translate-y-1/2 text-white/30 hover:text-white transition-colors" title={disabled ? 'Unlock to edit' : 'Lock'}>
            {disabled ? <Lock size={14} /> : <Unlock size={14} />}
          </button>
        )}
      </div>
    )
  }

  if (def.type === 'textarea') {
    return (
      <div className="relative">
        <textarea
          value={value ?? ''}
          onChange={e => onChange(e.target.value)}
          disabled={disabled}
          placeholder={def.placeholder || def.label}
          rows={3}
          className="w-full p-2.5 bg-black/40 border border-white/10 rounded-xl text-sm font-mono disabled:opacity-50 disabled:cursor-not-allowed resize-none"
        />
        {showPadlock && (
          <button type="button" onClick={onToggleLock} className="absolute right-3 top-3 text-white/30 hover:text-white transition-colors" title={disabled ? 'Unlock to edit' : 'Lock'}>
            {disabled ? <Lock size={14} /> : <Unlock size={14} />}
          </button>
        )}
      </div>
    )
  }

  if (def.type === 'cents') {
    const displayValue = value !== undefined && value !== null && value !== '' ? (value / 100).toFixed(2) : ''
    return (
      <div className="relative">
        <input
          type="number"
          step="0.01"
          value={displayValue}
          onChange={e => {
            const raw = e.target.value
            const cents = raw === '' ? '' : Math.round(parseFloat(raw) * 100)
            onChange(cents)
          }}
          disabled={disabled}
          placeholder={def.placeholder || def.label}
          className={`w-full p-2.5 bg-black/40 border border-white/10 rounded-xl text-sm font-mono disabled:opacity-50 disabled:cursor-not-allowed ${showPadlock ? 'pr-10' : ''}`}
        />
        {showPadlock && (
          <button type="button" onClick={onToggleLock} className="absolute right-3 top-1/2 -translate-y-1/2 text-white/30 hover:text-white transition-colors" title={disabled ? 'Unlock to edit' : 'Lock'}>
            {disabled ? <Lock size={14} /> : <Unlock size={14} />}
          </button>
        )}
      </div>
    )
  }

  if (def.type === 'date') {
    return (
      <div className="relative">
        <input
          type="date"
          value={value ?? ''}
          onChange={e => onChange(e.target.value)}
          disabled={disabled}
          className={`w-full p-2.5 bg-black/40 border border-white/10 rounded-xl text-sm font-mono disabled:opacity-50 disabled:cursor-not-allowed ${showPadlock ? 'pr-10' : ''}`}
        />
        {showPadlock && (
          <button type="button" onClick={onToggleLock} className="absolute right-3 top-1/2 -translate-y-1/2 text-white/30 hover:text-white transition-colors" title={disabled ? 'Unlock to edit' : 'Lock'}>
            {disabled ? <Lock size={14} /> : <Unlock size={14} />}
          </button>
        )}
      </div>
    )
  }

  return (
    <div className="relative">
      <input
        type={def.type === 'number' ? 'number' : 'text'}
        step={def.type === 'number' ? 'any' : undefined}
        value={value ?? ''}
        onChange={e => onChange(def.type === 'number' ? parseFloat(e.target.value) || '' : e.target.value)}
        disabled={disabled}
        placeholder={def.placeholder || def.label}
        className={`w-full p-2.5 bg-black/40 border border-white/10 rounded-xl text-sm font-mono disabled:opacity-50 disabled:cursor-not-allowed ${showPadlock ? 'pr-10' : ''}`}
      />
      {showPadlock && (
        <button type="button" onClick={onToggleLock} className="absolute right-3 top-1/2 -translate-y-1/2 text-white/30 hover:text-white transition-colors" title={disabled ? 'Unlock to edit' : 'Lock'}>
          {disabled ? <Lock size={14} /> : <Unlock size={14} />}
        </button>
      )}
    </div>
  )
}

export default TypedFieldInput

import { useState, useEffect } from 'react';
import * as Icons from './Icons';
import { motion, AnimatePresence } from 'framer-motion';
import { LogDetailsModal } from './LogDetailsModal';
import { apiRequest } from '../utils/api';
import { ExpandableValue } from './ui/ExpandableValue';

export const AuditLogTable = () => {
  const [logs, setLogs] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [offset, setOffset] = useState(0);
  const [hasMore, setHasMore] = useState(true);
  const [selectedLog, setSelectedLog] = useState<any | null>(null);
  const [search, setSearch] = useState('');
  const [action, setAction] = useState('');
  const [severity, setSeverity] = useState('');
  const LIMIT = 10;

  const fetchLogs = async (newOffset: number, currentSearch = search, currentAction = action, currentSeverity = severity) => {
    setLoading(true);
    try {
      const queryParams = new URLSearchParams();
      queryParams.append('limit', String(LIMIT));
      queryParams.append('offset', String(newOffset));
      if (currentSearch) queryParams.append('search', currentSearch);
      if (currentAction) queryParams.append('action', currentAction);
      if (currentSeverity) queryParams.append('severity', currentSeverity);

      const data = await apiRequest(`/api/logs?${queryParams.toString()}`) as any[];
      if (newOffset === 0) {
        setLogs(data);
      } else {
        setLogs(prev => [...prev, ...data]);
      }
      setHasMore(data?.length === LIMIT);
    } catch (err) {
      console.error('Failed to fetch logs:', err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    setOffset(0);
    fetchLogs(0, search, action, severity);
  }, [search, action, severity]);

  const loadMore = () => {
    const nextOffset = offset + LIMIT;
    setOffset(nextOffset);
    fetchLogs(nextOffset, search, action, severity);
  };

  return (
    <div id="system-audit-log" className="bg-[#313338] rounded-xl border border-[#2B2D31] overflow-hidden shadow-2xl">
      <div className="p-4 border-b border-[#2B2D31] bg-[#2B2D31]/50 flex items-center justify-between">
        <div className="flex items-center gap-2">
          <Icons.Shield className="text-[#5865F2]" size={18} />
          <h3 className="text-sm font-black text-white uppercase tracking-widest">System Activity History</h3>
        </div>
        <button 
          onClick={() => { setOffset(0); fetchLogs(0, search, action, severity); }}
          className="p-1.5 hover:bg-white/5 rounded-lg text-[#949BA4] hover:text-white transition-all"
        >
          <Icons.RotateCw size={16} className={loading ? 'animate-spin' : ''} />
        </button>
      </div>

      <div className="p-4 border-b border-[#2B2D31] bg-[#2B2D31]/30 grid grid-cols-1 md:grid-cols-3 gap-3">
        <input 
          type="text" 
          placeholder="Search activity..."
          className="bg-[#1E1F22] text-white text-xs rounded-xl px-4 py-2 border border-white/5 focus:border-primary outline-none"
          value={search}
          onChange={e => setSearch(e.target.value)}
        />
        <select 
          className="bg-[#1E1F22] text-white text-xs rounded-xl px-4 py-2 border border-white/5 focus:border-primary outline-none cursor-pointer"
          value={action}
          onChange={e => setAction(e.target.value)}
        >
          <option value="">All Action Types</option>
          <option value="USER_CREATE_MANUAL">Manual User Creation</option>
          <option value="ROLE_UPDATE">Role Updates</option>
          <option value="USER_DELETE">User Deletions</option>
          <option value="USER_MERGE">User Merges</option>
          <option value="TOGGLE_MAINTENANCE">Maintenance Toggles</option>
          <option value="CALENDAR_EVENT_CREATE">Calendar Create</option>
          <option value="CONNECTION_UNLINK">Account Unlinks</option>
          <option value="ROLE_SUB_REQ_CREATE_UPDATE">Role Requirements Set</option>
          <option value="ROLE_SUB_REQ_DELETE">Role Requirements Delete</option>
          <option value="SUBSCRIPTION_STATUS_CHANGE">Sub Status Changes</option>
        </select>
        <select 
          className="bg-[#1E1F22] text-white text-xs rounded-xl px-4 py-2 border border-white/5 focus:border-primary outline-none cursor-pointer"
          value={severity}
          onChange={e => setSeverity(e.target.value)}
        >
          <option value="">All Severities</option>
          <option value="INFO">INFO</option>
          <option value="CRITICAL">CRITICAL</option>
        </select>
      </div>

      <div className="overflow-x-auto custom-scrollbar">
        <table className="w-full text-left">
          <thead>
            <tr className="bg-[#2B2D31] text-[#949BA4] uppercase text-[10px] font-black tracking-widest">
              <th className="px-6 py-4">Event</th>
              <th className="px-6 py-4">Performed By</th>
              <th className="px-6 py-4">Time</th>
              <th className="px-6 py-4 text-right">More Info</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-[#1E1F22]">
            {logs.map((log, idx) => (
              <motion.tr 
                initial={{ opacity: 0, y: 5 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: (idx % 10) * 0.05 }}
                key={log.id} 
                className="hover:bg-[#2B2D31]/30 transition-all group"
              >
                <td className="px-6 py-4">
                  <span className="text-xs font-black text-[#5865F2] tracking-tight">
                    <ExpandableValue value={log.action} maxLength={25} />
                  </span>
                </td>
                <td className="px-6 py-4">
                  <div className="flex items-center gap-2">
                    <div className="w-5 h-5 rounded-full bg-white/5 flex items-center justify-center text-[8px] font-bold text-[#949BA4]">
                      {(log.actorName || log.actorUsername || log.actorId || 'S')[0].toUpperCase()}
                    </div>
                    <span className="text-xs font-bold text-[#DBDEE1]">
                      <ExpandableValue value={log.actorName || log.actorUsername || 'System'} maxLength={15} />
                    </span>
                  </div>
                </td>
                <td className="px-6 py-4">
                  <span className="text-[10px] font-bold font-mono text-[#949BA4]">
                    {log.createdAt ? new Date(log.createdAt).toLocaleString() : 'Invalid Date'}
                  </span>
                </td>
                <td className="px-6 py-4 text-right">
                  <button 
                    onClick={() => setSelectedLog(log)}
                    className="p-2 bg-white/5 hover:bg-[#5865F2]/20 text-[#949BA4] hover:text-[#5865F2] rounded-lg transition-all"
                  >
                    <Icons.Info size={14} />
                  </button>
                </td>
              </motion.tr>
            ))}
            {logs.length === 0 && !loading && (
              <tr>
                <td colSpan={4} className="px-6 py-12 text-center text-[#949BA4] uppercase text-[10px] font-black tracking-widest">
                  No activity history found
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>

      {hasMore && (
        <div className="p-4 border-t border-[#1E1F22] flex justify-center bg-[#2B2D31]/20">
          <button 
            onClick={loadMore}
            disabled={loading}
            className="px-6 py-2 bg-[#232428] hover:bg-[#2B2D31] text-[10px] font-black text-[#DBDEE1] uppercase tracking-[0.2em] border border-[#1E1F22] rounded-lg transition-all flex items-center gap-2"
          >
            {loading ? <Icons.RotateCw size={12} className="animate-spin" /> : <Icons.ChevronDown size={12} />}
            Load Previous Records
          </button>
        </div>
      )}

      <AnimatePresence>
        {selectedLog && (
          <LogDetailsModal 
            log={selectedLog} 
            onClose={() => setSelectedLog(null)} 
          />
        )}
      </AnimatePresence>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import * as Icons from './Icons';
import { motion, AnimatePresence } from 'framer-motion';

interface SearchResult {
  id: string;
  title: string;
  type: string;
  link: string;
}

interface CommandPaletteProps {
  isOpen: boolean;
  onClose: () => void;
  apiRequest: (url: string, options?: any) => Promise<any>;
  onNavigate: (path: string) => void;
}

const CommandPalette: React.FC<CommandPaletteProps> = ({ isOpen, onClose, apiRequest, onNavigate }) => {
  const [query, setQuery] = useState('');
  const [results, setResults] = useState<SearchResult[]>([]);
  const [loading, setLoading] = useState(false);
  const [selectedIndex, setSelectedIndex] = useState(0);
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (isOpen) {
      setTimeout(() => inputRef.current?.focus(), 100);
      setQuery('');
      setResults([]);
    }
  }, [isOpen]);

  useEffect(() => {
    const search = async () => {
      if (!query.trim()) {
        setResults([]);
        return;
      }

      setLoading(true);
      try {
        const data = await apiRequest(`/api/admin/search?q=${encodeURIComponent(query)}`);
        setResults(data || []);
        setSelectedIndex(0);
      } catch (err) {
        console.error('Search failed:', err);
      } finally {
        setLoading(false);
      }
    };

    const debounce = setTimeout(search, 300);
    return () => clearTimeout(debounce);
  }, [query]);

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'ArrowDown') {
      e.preventDefault();
      setSelectedIndex(prev => (prev + 1) % (results?.length || 1));
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      setSelectedIndex(prev => (prev - 1 + (results?.length || 1)) % (results?.length || 1));
    } else if (e.key === 'Enter') {
      if (results[selectedIndex]) {
        onNavigate(results[selectedIndex].link);
        onClose();
      }
    } else if (e.key === 'Escape') {
      onClose();
    }
  };

  return (
    <AnimatePresence>
      {isOpen && (
        <div className="fixed inset-0 z-[100] flex items-start justify-center pt-[15vh] px-4 pointer-events-none">
          <motion.div 
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            onClick={onClose}
            className="fixed inset-0 bg-black/40 backdrop-blur-md pointer-events-auto"
          />

          <motion.div
            initial={{ opacity: 0, scale: 0.95, y: -20 }}
            animate={{ opacity: 1, scale: 1, y: 0 }}
            exit={{ opacity: 0, scale: 0.95, y: -20 }}
            className="bg-[#1E1F22]/90 border border-white/10 w-full max-w-2xl rounded-2xl shadow-2xl overflow-hidden pointer-events-auto flex flex-col"
            onKeyDown={handleKeyDown}
          >
            <div className="flex items-center px-4 py-4 border-b border-white/5 bg-white/5">
              <Icons.Search className="text-[#949BA4] mr-3" size={20} />
              <input
                ref={inputRef}
                type="text"
                placeholder="Search users, campaigns, events..."
                value={query}
                onChange={e => setQuery(e.target.value)}
                className="w-full bg-transparent border-none text-white text-lg outline-none placeholder-[#4F545C]"
              />
              <div className="flex items-center space-x-1 px-2 py-1 bg-white/5 border border-white/10 rounded text-[10px] text-[#949BA4] font-bold">
                <span>ESC</span>
              </div>
            </div>

            <div className="max-h-[60vh] overflow-y-auto custom-scrollbar p-2">
              {loading ? (
                <div className="flex items-center justify-center py-12">
                  <div className="w-6 h-6 border-2 border-[#5865F2] border-t-transparent rounded-full animate-spin" />
                </div>
              ) : results.length === 0 ? (
                <div className="py-12 text-center">
                  <Icons.Zap className="mx-auto text-[#4F545C] mb-2" size={32} />
                  <p className="text-[#949BA4] text-sm">
                    {query.trim() ? 'No results found for that query.' : 'Type something to search the global index.'}
                  </p>
                </div>
              ) : (
                <div className="space-y-1">
                  {results.map((result, idx) => (
                    <button
                      key={`${result.type}-${result.id}`}
                      onClick={() => {
                        onNavigate(result.link);
                        onClose();
                      }}
                      onMouseEnter={() => setSelectedIndex(idx)}
                      className={`w-full flex items-center justify-between p-3 rounded-xl transition-all ${
                        selectedIndex === idx ? 'bg-[#5865F2] text-white' : 'hover:bg-white/5 text-[#DBDEE1]'
                      }`}
                    >
                      <div className="flex items-center space-x-3">
                        <div className={`p-2 rounded-lg ${selectedIndex === idx ? 'bg-white/20' : 'bg-white/5'}`}>
                          {result.type === 'user' && <Icons.User size={18} />}
                          {result.type === 'campaign' && <Icons.Megaphone size={18} />}
                          {result.type === 'event' && <Icons.Calendar size={18} />}
                          {result.type === 'link' && <Icons.Link size={18} />}
                        </div>
                        <div className="text-left">
                          <p className="font-bold text-sm leading-tight">{result.title}</p>
                          <p className={`text-[10px] uppercase font-bold tracking-wider ${
                            selectedIndex === idx ? 'text-white/70' : 'text-[#949BA4]'
                          }`}>{result.type}</p>
                        </div>
                      </div>
                      <Icons.ChevronRight size={16} className={selectedIndex === idx ? 'opacity-100' : 'opacity-0'} />
                    </button>
                  ))}
                </div>
              )}
            </div>

            <div className="p-3 border-t border-white/5 bg-[#111214]/50 flex items-center justify-between text-[10px] text-[#4F545C] font-bold uppercase tracking-widest">
              <div className="flex items-center space-x-4">
                <span className="flex items-center"><Icons.ArrowDown size={12} className="mr-1" /> Select</span>
