import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import * as Icons from './Icons';
import { useToast } from '../contexts/ToastContext';

interface GovernanceManagerProps {
  apiRequest: (url: string, options?: any) => Promise<any>;
  onUpdate: () => void;
}

const ROLE_OPTIONS = ['user', 'mod', 'admin', 'owner'];

const parseRoles = (val: any): string[] => {
  if (Array.isArray(val)) return val;
  if (typeof val === 'string') {
    try {
      const parsed = JSON.parse(val);
      if (Array.isArray(parsed)) return parsed;
    } catch (_) {}
    return val.split(',').map(s => s.trim()).filter(Boolean);
  }
  return [];
};

export default function GovernanceManager({ apiRequest, onUpdate }: GovernanceManagerProps) {
  const { addToast, confirm: toastConfirm } = useToast();
  const [isVerified, setIsVerified] = useState(false);
  const [activeTab, setActiveTab] = useState<'nav' | 'help' | 'categories'>('nav');
  const [navItems, setNavItems] = useState<any[]>([]);
  const [navCategories, setNavCategories] = useState<any[]>([]);
  const [helpCategories, setHelpCategories] = useState<any[]>([]);
  const [helpArticles, setHelpArticles] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [editingItem, setEditingItem] = useState<any>(null);
  const [itemType, setItemType] = useState<'nav' | 'cat' | 'art' | 'navcat' | null>(null);

  const fetchData = async () => {
    setLoading(true);
    try {
      const [nav, categories, helpData] = await Promise.all([
        apiRequest('/api/admin/governance/ui'),
        apiRequest('/api/admin/governance/categories'),
        apiRequest('/api/admin/governance/help/categories').then(async cats => ({
          categories: cats,
          articles: await apiRequest('/api/admin/governance/help/articles')
        }))
      ]);
      setNavItems(nav);
      setNavCategories(categories || []);
      setHelpCategories(helpData.categories);
      setHelpArticles(helpData.articles);
    } catch (err) {
      console.error('Rules fetch failed:', err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
  }, []);

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!itemType || !editingItem) return;

    if (itemType === 'navcat') {
      try {
        let newCats = [...navCategories];
        if (editingItem._isNew) {
          newCats.push({ id: editingItem.id, label: editingItem.label, display_order: Number(editingItem.display_order) });
        } else {
          const oldCat = navCategories.find(c => c.id === editingItem.id);
          if (oldCat && oldCat.label !== editingItem.label) {
            const affectedItems = navItems.filter(item => item.category === oldCat.label);
            for (const item of affectedItems) {
              await apiRequest(`/api/admin/governance/ui/${item.id}`, {
                method: 'PATCH',
                body: { ...item, category: editingItem.label }
              });
            }
          }
          newCats = navCategories.map(c => c.id === editingItem.id ? { ...c, label: editingItem.label, display_order: Number(editingItem.display_order) } : c);
        }
        await apiRequest('/api/admin/governance/categories', { method: 'POST', body: newCats });
        addToast('Menu category saved successfully!', 'success');
        setEditingItem(null);
        setItemType(null);
        fetchData();
        onUpdate();
        return;
      } catch (err) {
        addToast('Failed to save menu category.', 'error');
        return;
      }
    }

    let url = '';
    let payload = { ...editingItem };
    if (itemType === 'nav') {
      url = '/api/admin/governance/ui';
      if (payload.id === 'system') {
        const roles = Array.isArray(payload.required_roles) ? payload.required_roles : [];
        if (!roles.includes('owner')) {
          payload.required_roles = [...roles, 'owner'];
        }
      }
    }
    if (itemType === 'cat') url = '/api/admin/governance/help/categories';
    if (itemType === 'art') url = '/api/admin/governance/help/articles';

    try {
      if (payload._isNew) {
        const { _isNew, ...data } = payload;
        await apiRequest(url, { method: 'POST', body: data });
        addToast('Item created successfully!', 'success');
      } else {
        await apiRequest(`${url}/${payload.id}`, { method: 'PATCH', body: payload });
        addToast('Item updated successfully!', 'success');
      }
      setEditingItem(null);
      setItemType(null);
      fetchData();
      onUpdate();
    } catch (err) {
      addToast('Failed to save item.', 'error');
    }
  };

  const handleDelete = async (type: 'nav' | 'cat' | 'art' | 'navcat', id: string) => {
    if (type === 'navcat') {
      const isConfirmed = await toastConfirm('Are you sure you want to delete this menu category? All navigation items in this category will fall back to "Overview".');
      if (!isConfirmed) return;
      try {
        const deletedCat = navCategories.find(c => c.id === id);
        if (deletedCat) {
          const affectedItems = navItems.filter(item => item.category === deletedCat.label);
          for (const item of affectedItems) {
            await apiRequest(`/api/admin/governance/ui/${item.id}`, {
              method: 'PATCH',
              body: { ...item, category: 'Overview' }
            });
          }
        }
        const newCats = navCategories.filter(c => c.id !== id);
        await apiRequest('/api/admin/governance/categories', { method: 'POST', body: newCats });
        addToast('Menu category deleted!', 'success');
        fetchData();
        onUpdate();
      } catch (err) {
        addToast('Failed to delete category.', 'error');
      }
      return;
    }

    const isConfirmed = await toastConfirm('Are you sure you want to delete this item?');
    if (!isConfirmed) return;
    let url = '';
    if (type === 'nav') url = `/api/admin/governance/ui/${id}`;
    if (type === 'cat') url = `/api/admin/governance/help/categories/${id}`;
    if (type === 'art') url = `/api/admin/governance/help/articles/${id}`;

    try {
      await apiRequest(url, { method: 'DELETE' });
      addToast('Item deleted successfully!', 'success');
      fetchData();
      onUpdate();
    } catch (err) {
      addToast('Failed to delete item.', 'error');
    }
  };

  const openNewModal = (type: 'nav' | 'cat' | 'art' | 'navcat') => {
    setItemType(type);
    if (type === 'nav') setEditingItem({ id: '', label: '', icon_name: 'Home', required_roles: ['user'], category: 'Overview', display_order: 0, is_active: 1, _isNew: true });
    if (type === 'cat') setEditingItem({ id: '', label: '', icon_name: 'Book', required_roles: ['user'], display_order: 0, is_active: 1, _isNew: true });
    if (type === 'art') setEditingItem({ id: '', category_id: helpCategories[0]?.id || '', title: '', content: '', required_roles: ['user'], display_order: 0, is_active: 1, _isNew: true });
    if (type === 'navcat') setEditingItem({ id: '', label: '', display_order: navCategories.length + 1, _isNew: true });
  };


  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between mb-8">
        <div>
          <h2 className="text-3xl font-black text-white">Rules & Permissions Studio</h2>
          <p className="text-text-muted text-sm uppercase tracking-widest font-bold mt-1">Role Management & App Architecture</p>
        </div>
        <div className="flex bg-white/5 p-1 rounded-xl border border-white/5">
          <button 
            id="gov-nav-editor"
            onClick={() => setActiveTab('nav')}
            className={`px-6 py-2 rounded-lg text-xs font-black uppercase tracking-widest transition-all ${activeTab === 'nav' ? 'bg-primary text-white shadow-lg shadow-primary/20' : 'text-text-muted hover:text-white'}`}
          >
            Navigation
          </button>
          <button 
            id="gov-categories-editor"
            onClick={() => setActiveTab('categories')}
            className={`px-6 py-2 rounded-lg text-xs font-black uppercase tracking-widest transition-all ${activeTab === 'categories' ? 'bg-primary text-white shadow-lg shadow-primary/20' : 'text-text-muted hover:text-white'}`}
          >
            Categories
          </button>
          <button 
            id="gov-help-editor"
            onClick={() => setActiveTab('help')}
            className={`px-6 py-2 rounded-lg text-xs font-black uppercase tracking-widest transition-all ${activeTab === 'help' ? 'bg-primary text-white shadow-lg shadow-primary/20' : 'text-text-muted hover:text-white'}`}
          >
            Help Center
          </button>
        </div>
      </div>

      {loading ? (
        <div className="flex justify-center p-20">
          <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary"></div>
        </div>
      ) : (
        <AnimatePresence mode="wait">
          {activeTab === 'nav' ? (
            <motion.div 
              key="nav"
              initial={{ opacity: 0, y: 10 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -10 }}
              className="space-y-4"
            >
              <div className="flex justify-between items-center mb-4">
                <h3 className="text-lg font-bold text-white">Navigation Menu Items</h3>
                <button 
                  onClick={() => openNewModal('nav')}
                  className="px-4 py-2 bg-emerald-500 hover:bg-emerald-400 text-white text-[10px] font-black uppercase tracking-widest rounded-lg flex items-center transition-all"
                >
                  <Icons.Plus className="mr-2 w-4 h-4" /> Add Item
                </button>
              </div>

              {(() => {
                const groupedMap: Record<string, any[]> = {};
                (navItems || []).forEach(item => {
                  const cat = item.category || 'Overview';
                  if (!groupedMap[cat]) groupedMap[cat] = [];
                  groupedMap[cat].push(item);
                });

                const grouped = Object.keys(groupedMap).map(catLabel => {
                  const items = groupedMap[catLabel];
                  items.sort((a, b) => (a.display_order || 0) - (b.display_order || 0));
                  return { label: catLabel, items };
                });

                return (
                  <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                    {grouped.map(group => (
