const GuidedTour = ({ type = 'onboarding', onComplete, onSkip }: { type?: string, onComplete: () => void, onSkip?: () => void }) => {
  const steps = tourPaths[type] || tourPaths.onboarding;
  const [currentStep, setCurrentStep] = useState(0);
  const [targetRect, setTargetRect] = useState<DOMRect | null>(null);
  const [coords, setCoords] = useState({ top: 0, left: 0 });
  const [isCalculated, setIsCalculated] = useState(false);
  const tooltipRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const updatePosition = () => {
      const element = document.getElementById(steps[currentStep].target);
      if (element) {
        element.scrollIntoView({ behavior: 'auto', block: 'center' });

        // Use a re-calculation loop or requestAnimationFrame to ensure the hole 
        // matches the final position after scroll/browser layout.
        requestAnimationFrame(() => {
          const finalRect = element.getBoundingClientRect();
          setTargetRect(finalRect);

          const offset = 16;
          const tooltipWidth = 320;
          const tooltipHeight = 220;

          let top = 0;
          let left = 0;
          const step = steps[currentStep];

          if (step.position === 'bottom') {
            top = finalRect.bottom + offset;
            left = finalRect.left + finalRect.width / 2 - tooltipWidth / 2;
          } else if (step.position === 'top') {
            top = finalRect.top - tooltipHeight - offset;
            left = finalRect.left + finalRect.width / 2 - tooltipWidth / 2;
          } else if (step.position === 'left') {
            top = finalRect.top + finalRect.height / 2 - tooltipHeight / 2;
            left = finalRect.left - tooltipWidth - offset;
          } else {
            top = finalRect.top + finalRect.height / 2 - tooltipHeight / 2;
            left = finalRect.right + offset;
          }

          const padding = 20;
          left = Math.max(padding, Math.min(left, window.innerWidth - tooltipWidth - padding));
          top = Math.max(padding, Math.min(top, window.innerHeight - tooltipHeight - padding));

          setCoords({ top, left });
          setIsCalculated(true);
        });
      }
    };

    updatePosition();
    window.addEventListener('resize', updatePosition);
    return () => window.removeEventListener('resize', updatePosition);
  }, [currentStep, steps]);

  const handleNext = () => {
    setIsCalculated(false);
    if (currentStep < steps.length - 1) {
      setCurrentStep(currentStep + 1);
    } else {
      onComplete();
    }
  };

  if (!targetRect) return null;
  const step = steps[currentStep];

  return (
    <div className="fixed inset-0 z-[100] pointer-events-none overflow-hidden">
      <AnimatePresence>
        {/* Backdrop with hole */}
        <motion.div 
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          exit={{ opacity: 0 }}
          className="absolute inset-0 bg-black/60 pointer-events-auto cursor-help" 
          style={{
            clipPath: `polygon(
              0% 0%, 0% 100%, 
              ${targetRect.left}px 100%, ${targetRect.left}px ${targetRect.top}px, 
              ${targetRect.right}px ${targetRect.top}px, ${targetRect.right}px ${targetRect.bottom}px, 
              ${targetRect.left}px ${targetRect.bottom}px, ${targetRect.left}px 100%, 
              100% 100%, 100% 0%
            )`
          }} 
        />
      </AnimatePresence>

      {/* Pulse effect on target */}
      <div className="absolute border-2 border-[#5865F2] rounded-lg animate-ping" style={{
        top: targetRect.top - 4,
        left: targetRect.left - 4,
        width: targetRect.width + 8,
        height: targetRect.height + 8
      }} />

      {/* Draggable Tooltip */}
      <motion.div 
        ref={tooltipRef}
        drag
        dragMomentum={false}
        initial={false}
        animate={isCalculated ? { top: coords.top, left: coords.left, opacity: 1, scale: 1 } : { opacity: 0, scale: 0.9 }}
        className="absolute pointer-events-auto w-80 bg-[#313338] border border-[#5865F2]/50 rounded-2xl shadow-[0_20px_50px_rgba(0,0,0,0.5)] p-6 backdrop-blur-xl cursor-grab active:cursor-grabbing"
      >
        <div className="flex items-center justify-between mb-4">
          <div className="flex items-center space-x-2">
            <div className="w-2 h-2 bg-[#5865F2] rounded-full animate-pulse" />
            <span className="text-[10px] font-black text-[#5865F2] uppercase tracking-[0.2em]">Step {currentStep + 1} of {steps.length}</span>
          </div>
          <button onClick={onComplete} className="text-[#949BA4] hover:text-white transition-colors p-1">
            <Icons.Close size={18} />
          </button>
        </div>

        <h4 className="text-white font-black text-xl mb-2 tracking-tight">{step.title}</h4>
        <p className="text-sm text-[#B5BAC1] font-medium leading-relaxed mb-6">{step.content}</p>

        <div className="flex items-center justify-between pt-4 border-t border-white/5">
          <div className="flex gap-1.5 items-center">
            {steps.map((_, i) => (
              <div 
                key={i} 
                className={`h-1.5 rounded-full transition-all duration-500 ${i === currentStep ? 'w-6 bg-[#5865F2]' : 'w-2 bg-[#1E1F22]'}`} 
              />
            ))}
            <button 
              onClick={onSkip || onComplete}
              className="ml-4 text-[10px] font-black text-[#949BA4] hover:text-white uppercase tracking-widest transition-colors border-b border-transparent hover:border-white/20"
            >
              Skip
            </button>
          </div>
          <button 
            onClick={handleNext}
            className="flex items-center px-5 py-2.5 bg-[#5865F2] hover:bg-[#4752C4] text-white text-sm font-black rounded-xl transition-all shadow-lg shadow-[#5865F2]/20 active:scale-95 group"
          >
            {currentStep === steps.length - 1 ? 'Finish' : 'Next'}
            <Icons.Zap size={14} className="ml-2 group-hover:scale-125 transition-transform" />
          </button>
        </div>

        {/* Drag Indicator Overlay (Subtle) */}
        <div className="absolute top-0 left-1/2 -translate-x-1/2 w-12 h-1 bg-white/5 rounded-full mt-1" />
      </motion.div>
    </div>
  );
};

