import { useState, useEffect, useRef } from 'react';
import * as Icons from './Icons';
import { motion, AnimatePresence } from 'framer-motion';
import { API_BASE } from '../utils/api';

interface LogEntry {
  id: string;
  actorId?: string;
  action: string;
  severity?: string;
  targetType?: string;
  recordId?: string;
  metadataJson?: any;
  createdAt?: string;
}

const severityColor: Record<string, string> = {
  INFO: 'bg-primary/10 text-primary border-primary/20',
  WARNING: 'bg-amber-500/10 text-amber-400 border-amber-500/20',
  CRITICAL: 'bg-red-500/10 text-red-400 border-red-500/20',
};

export const LiveLogStream = () => {
  const [entries, setEntries] = useState<LogEntry[]>([]);
  const [status, setStatus] = useState<'connecting' | 'connected' | 'disconnected'>('connecting');
  const [paused, setPaused] = useState(false);
  const [severityFilter, setSeverityFilter] = useState('');
  const [search, setSearch] = useState('');
  const wsRef = useRef<WebSocket | null>(null);
  const pausedBuffer = useRef<LogEntry[]>([]);

  useEffect(() => {
    let reconnectTimeout: ReturnType<typeof setTimeout>;
    let shouldReconnect = true;

    const connect = () => {
      const wsUrl = new URL(API_BASE || window.location.origin);
      const protocol = wsUrl.protocol === 'https:' ? 'wss:' : 'ws:';
      const host = wsUrl.host;
      const token = localStorage.getItem('GLOBOT_AUTH_TOKEN');

      const socket = new WebSocket(`${protocol}//${host}/api/logs/stream${token ? `?token=${token}` : ''}`);

      socket.onopen = () => setStatus('connected');

      socket.onmessage = (event) => {
        const data = JSON.parse(event.data);
        if (data.type === 'system') return;
        if (data.type === 'log_entry' && data.data) {
          if (paused) {
            pausedBuffer.current = [...pausedBuffer.current, data.data].slice(-200);
          } else {
            setEntries(prev => [data.data, ...prev].slice(-200));
          }
        }
      };

      socket.onclose = () => {
        setStatus('disconnected');
        if (shouldReconnect) {
          reconnectTimeout = setTimeout(connect, 3000);
        }
      };

      socket.onerror = () => socket.close();

      wsRef.current = socket;
    };

    connect();

    return () => {
      shouldReconnect = false;
      clearTimeout(reconnectTimeout);
      if (wsRef.current) wsRef.current.close();
    };
  }, []);

  const togglePause = () => {
    setPaused(prev => {
      const next = !prev;
      if (!next && pausedBuffer.current.length > 0) {
        setEntries(prevEntries => [...pausedBuffer.current, ...prevEntries].slice(-200));
        pausedBuffer.current = [];
      }
      return next;
    });
  };

  const clearLogs = () => {
    setEntries([]);
    pausedBuffer.current = [];
  };

  const filtered = entries.filter(e => {
    if (severityFilter && (e.severity || 'INFO') !== severityFilter) return false;
    if (search) {
      const q = search.toLowerCase();
      return (e.action || '').toLowerCase().includes(q)
        || (e.actorId || '').toLowerCase().includes(q)
        || (e.targetType || '').toLowerCase().includes(q);
    }
    return true;
  });

  return (
    <div id="live-log-stream" className="bg-[#313338] rounded-xl border border-[#2B2D31] overflow-hidden shadow-2xl">
      <div className="p-4 border-b border-[#2B2D31] bg-[#2B2D31]/50 flex items-center justify-between gap-4 flex-wrap">
        <div className="flex items-center gap-2">
          <Icons.Activity className="text-[#5865F2]" size={18} />
          <h3 className="text-sm font-black text-white uppercase tracking-widest">Live Log Stream</h3>
          <span className={`flex items-center px-2 py-0.5 rounded-full text-[9px] font-black uppercase tracking-widest border ${
            status === 'connected'
              ? 'bg-green-500/10 text-green-400 border-green-500/20'
              : status === 'connecting'
              ? 'bg-amber-500/10 text-amber-400 border-amber-500/20'
              : 'bg-red-500/10 text-red-400 border-red-500/20'
          }`}>
            <span className={`w-1.5 h-1.5 rounded-full mr-1.5 ${
              status === 'connected' ? 'bg-green-400 animate-pulse' : status === 'connecting' ? 'bg-amber-400 animate-pulse' : 'bg-red-400'
            }`} />
            {status}
          </span>
        </div>

        <div className="flex items-center gap-2 flex-wrap">
          <input
            value={search}
            onChange={e => setSearch(e.target.value)}
            placeholder="Filter logs..."
            className="bg-[#1E1F22] border border-[#2B2D31] rounded-lg px-3 py-1.5 text-xs text-white outline-none focus:ring-2 focus:ring-[#5865F2]/20 w-44"
          />
          <select
            value={severityFilter}
            onChange={e => setSeverityFilter(e.target.value)}
            className="bg-[#1E1F22] border border-[#2B2D31] rounded-lg px-3 py-1.5 text-xs text-white outline-none"
          >
            <option value="">All Severities</option>
            <option value="INFO">INFO</option>
            <option value="WARNING">WARNING</option>
            <option value="CRITICAL">CRITICAL</option>
          </select>
          <button
            onClick={togglePause}
            className={`px-3 py-1.5 rounded-lg text-[10px] font-black uppercase tracking-widest border transition-all ${
              paused ? 'bg-amber-500/10 text-amber-400 border-amber-500/20' : 'bg-white/5 text-[#949BA4] border-white/10 hover:text-white'
            }`}
          >
            {paused ? 'Resume' : 'Pause'}
          </button>
          <button
            onClick={clearLogs}
            className="px-3 py-1.5 rounded-lg text-[10px] font-black uppercase tracking-widest border border-white/10 bg-white/5 text-[#949BA4] hover:text-red-400 hover:border-red-500/20 transition-all"
          >
            Clear
          </button>
        </div>
      </div>

      <div className="h-96 overflow-y-auto custom-scrollbar bg-[#1E1F22]/40">
        {filtered.length === 0 ? (
          <div className="flex flex-col items-center justify-center h-full space-y-3 text-center px-6">
            <div className={`w-10 h-10 rounded-full flex items-center justify-center border ${
              status === 'connected' ? 'bg-primary/10 border-primary/20 text-primary' : 'bg-white/5 border-white/5 text-white/20'
            }`}>
              <Icons.Activity size={18} />
            </div>
            <p className="text-[10px] text-text-muted font-black uppercase tracking-widest">
              {status === 'connected' ? 'Awaiting log events...' : status === 'connecting' ? 'Connecting to live feed...' : 'Disconnected — reconnecting...'}
            </p>
            <p className="text-[10px] text-text-muted/60 max-w-xs">
              {paused ? 'Stream paused. Buffered events will be flushed on resume.' : 'New audit and security events will appear here in real time.'}
            </p>
          </div>
        ) : (
          <AnimatePresence initial={false}>
            {filtered.map(entry => (
              <motion.div
                key={entry.id}
                initial={{ opacity: 0, y: -8 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ duration: 0.2 }}
                className="flex items-start gap-3 px-4 py-2.5 border-b border-[#2B2D31]/60 hover:bg-white/[0.02] transition-colors font-mono"
              >
                <span className={`shrink-0 mt-0.5 px-2 py-0.5 rounded border text-[9px] font-black uppercase tracking-widest ${severityColor[entry.severity || 'INFO'] || severityColor.INFO}`}>
                  {entry.severity || 'INFO'}
                </span>
                <span className="shrink-0 text-[10px] text-text-muted mt-0.5">
                  {entry.createdAt ? new Date(entry.createdAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' }) : '--:--:--'}
                </span>
                <div className="min-w-0 flex-1">
                  <span className="text-[#E1E9F1] text-xs font-bold">{entry.action}</span>
                  <span className="text-text-muted/70 text-[10px] ml-2">
                    {entry.actorId ? `by ${entry.actorId}` : ''}
                    {entry.targetType ? ` · ${entry.targetType}` : ''}
                  </span>
                  {entry.metadataJson?.message && (
                    <p className="text-text-muted/60 text-[10px] truncate">{entry.metadataJson.message}</p>
                  )}
                </div>
              </motion.div>
            ))}
          </AnimatePresence>
        )}
      </div>
    </div>
  );
};

