import { useState, useEffect } from 'react';
import { motion } from 'framer-motion';

interface LoadingScreenProps {
  image1: string;
  image2: string;
  userAvatar: string;
  onComplete?: () => void;
}

export default function LoadingScreen({ image1, image2, userAvatar, onComplete }: LoadingScreenProps) {
  const [phase, setPhase] = useState(0);

  useEffect(() => {
    // Phase 0: Show Image 1 (0s - 1.5s)
    // Phase 1: Crossfade to Image 2 (1.5s - 3.5s)
    // Phase 2: Spin, Spawn Avatar, and Separate (3.5s - 5.5s)
    // Phase 3: Pause facing forward (5.5s - 6.5s)
    // Phase 4: Trigger Glide to Navbar (6.5s)

    const timer1 = setTimeout(() => setPhase(1), 1500);
    const timer2 = setTimeout(() => setPhase(2), 3500);
    const timer3 = setTimeout(() => {
      if (onComplete) onComplete();
    }, 6500);

    return () => {
      clearTimeout(timer1);
      clearTimeout(timer2);
      clearTimeout(timer3);
    };
  }, [onComplete]);

  return (
    <motion.div 
      className="fixed inset-0 flex flex-col items-center justify-center z-50 overflow-hidden pointer-events-none"
    >
      {/* Background ambient glow - fades out on exit so layoutId elements can glide over the app */}
      <motion.div 
        className="absolute inset-0 bg-[#050814]"
        initial={{ opacity: 1 }}
        exit={{ opacity: 0 }}
        transition={{ duration: 0.8 }}
      >
        <motion.div 
          className="absolute inset-0 flex items-center justify-center opacity-40"
          animate={{
            background: phase === 0 
              ? 'radial-gradient(circle at center, rgba(30, 64, 175, 0.4) 0%, transparent 60%)' 
              : phase === 1
              ? 'radial-gradient(circle at center, rgba(14, 165, 233, 0.4) 0%, transparent 60%)'
              : 'radial-gradient(circle at center, rgba(16, 185, 129, 0.4) 0%, transparent 60%)'
          }}
          transition={{ duration: 1 }}
        />
      </motion.div>

      <div className="relative w-full max-w-2xl h-96 flex items-center justify-center" style={{ perspective: 1200 }}>

        {/* Image 1: Fades out during Phase 1 - Restored to original scale */}
        <motion.img
          src={image1}
          alt="Loading 1"
          className="absolute w-64 h-64 md:w-80 md:h-80 object-contain drop-shadow-2xl"
          initial={{ opacity: 1 }}
          animate={{ opacity: phase >= 1 ? 0 : 1 }}
          transition={{ duration: 1.5, ease: "easeInOut" }}
        />

        {/* Image 2 (Logo): Fades in, then spins powerfully and moves left */}
        <motion.img
          layoutId="logo-glide"
          src={image2}
          alt="Loading 2"
          className="absolute w-64 h-64 md:w-80 md:h-80 object-contain drop-shadow-2xl z-10"
          initial={{ opacity: 0, x: 0, rotateY: 0, scale: 0.8 }}
          animate={{ 
            opacity: phase >= 1 ? 1 : 0,
            x: phase >= 2 ? -140 : 0,
            rotateY: phase >= 2 ? 1080 : 0, // 3 full powerful spins
            scale: phase >= 2 ? 1 : 1
          }}
          transition={{ 
            opacity: { duration: 1.5, ease: "easeInOut" },
            x: { duration: 1.5, type: "spring", stiffness: 90, damping: 12 },
            rotateY: { duration: 2.2, type: "spring", stiffness: 60, damping: 10 }, 
            scale: { duration: 1.5, type: "spring", stiffness: 90, damping: 12 }
          }}
        />

        {/* User Avatar: Spawns from center, spins powerfully, and moves right */}
        <motion.img
          layoutId="user-avatar-glide"
          src={userAvatar}
          alt="User Avatar"
          className="absolute w-40 h-40 md:w-48 md:h-48 rounded-full border-4 border-primary object-cover drop-shadow-2xl z-20"
          initial={{ opacity: 0, x: 0, rotateY: -1080, scale: 0 }} 
          animate={{ 
            opacity: phase >= 2 ? 1 : 0, 
            x: phase >= 2 ? 140 : 0, 
            rotateY: phase >= 2 ? 0 : -1080, 
            scale: phase >= 2 ? 1 : 0 
          }}
          transition={{ 
            x: { duration: 1.5, type: "spring", stiffness: 90, damping: 12 },
            scale: { duration: 1.5, type: "spring", stiffness: 90, damping: 12 },
            rotateY: { duration: 2.2, type: "spring", stiffness: 60, damping: 10 }, 
            opacity: { duration: 0.3 } 
          }}
        />
      </div>

      {/* Loading Progress Bar */}
      <motion.div 
        className="absolute bottom-16 left-1/2 transform -translate-x-1/2 w-48 md:w-64 h-1 bg-gray-800/50 rounded-full overflow-hidden backdrop-blur-sm"
        exit={{ opacity: 0 }}
      >
        <motion.div 
          className="h-full bg-gradient-to-r from-blue-600 to-emerald-400 rounded-full"
          initial={{ width: '0%' }}
          animate={{ width: '100%' }}
          transition={{ duration: 6, ease: "linear" }}
        />
      </motion.div>

      {/* Loading Text */}
      <motion.div 
        className="absolute bottom-8 left-1/2 transform -translate-x-1/2 text-gray-400 text-sm font-medium tracking-widest uppercase"
        animate={{ opacity: [0.5, 1, 0.5] }}
        exit={{ opacity: 0 }}
        transition={{ duration: 2, repeat: Infinity, ease: "easeInOut" }}
      >
        {phase === 0 ? 'Initializing' : phase === 1 ? 'Connecting' : 'Welcome'}
      </motion.div>
    </motion.div>
  );
}

import React from 'react';
import * as Icons from './Icons';
import { ExpandableValue } from './ui/ExpandableValue';

const renderJSONDetails = (details: any) => {
  if (!details) return <p className="text-xs text-[#949BA4] italic">No details available.</p>;
  let parsed = details;
  if (typeof details === 'string') {
    try {
      parsed = JSON.parse(details);
    } catch {
      return <p className="text-xs text-[#DBDEE1] font-mono break-all">{details}</p>;
    }
  }

  if (typeof parsed !== 'object' || parsed === null) {
    return <p className="text-xs text-[#DBDEE1] font-mono break-all">{String(parsed)}</p>;
  }

  const entries = Object.entries(parsed);
  if (entries.length === 0) return <p className="text-xs text-[#949BA4] italic">No details available.</p>;

  return (
    <div className="space-y-2 font-sans">
      {entries.map(([key, val]) => {
        let valStr = '';
        if (typeof val === 'object' && val !== null) {
          valStr = JSON.stringify(val, null, 2);
        } else {
          valStr = String(val);
        }

        const friendlyKey = key
          .replace(/_/g, ' ')
          .replace(/([A-Z])/g, ' $1')
          .replace(/^./, str => str.toUpperCase())
          .trim();

        return (
          <div key={key} className="flex flex-col sm:flex-row sm:items-start text-xs justify-between gap-1 py-1.5 border-b border-white/5 last:border-b-0">
            <span className="font-bold text-[#949BA4] shrink-0 sm:mr-4">{friendlyKey}:</span>
            <span className="text-[#DBDEE1] font-mono select-all break-all whitespace-pre-wrap text-right">{valStr}</span>
          </div>
        );
      })}
    </div>
  );
};

