  const hasNewValues = log.newValuesJson && typeof log.newValuesJson === 'object' && Object.keys(log.newValuesJson).length > 0;
  const hasOldValues = log.oldValuesJson && typeof log.oldValuesJson === 'object' && Object.keys(log.oldValuesJson).length > 0;
  const hasMetadata = log.metadataJson && typeof log.metadataJson === 'object' && Object.keys(log.metadataJson).length > 0;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-in fade-in">
      <div className="bg-[#1E1F22] rounded-xl shadow-2xl max-w-lg w-full overflow-hidden border border-[#2B2D31] animate-in zoom-in-95 duration-200">
        <div className="flex items-center justify-between p-4 border-b border-[#2B2D31] bg-[#2B2D31]">
          <div className="flex items-center space-x-2">
            <Icons.Shield className="text-[#5865F2]" size={20} />
            <h2 className="text-white font-bold">Activity Details</h2>
          </div>
          <button onClick={onClose} className="text-[#949BA4] hover:text-white transition-colors p-1 rounded-lg hover:bg-white/5">
