              <p className="text-[#949BA4] text-[10px] font-bold uppercase tracking-wider mb-1">Event Action</p>
              <p className="text-white font-medium">
                <ExpandableValue value={log.action || 'Unknown Event'} maxLength={25} />
              </p>
            </div>
            <div>
              <p className="text-[#949BA4] text-[10px] font-bold uppercase tracking-wider mb-1">Timestamp</p>
              <p className="text-white">{log.createdAt ? new Date(log.createdAt).toLocaleString() : 'Invalid Date'}</p>
            </div>
            <div>
              <p className="text-[#949BA4] text-[10px] font-bold uppercase tracking-wider mb-1">Performed By</p>
              <p className="text-white font-semibold bg-[#2B2D31] px-2.5 py-1 rounded inline-block text-xs max-w-full">
                <ExpandableValue value={log.actorName || log.actorUsername || log.actorId || 'System'} maxLength={25} />
              </p>
            </div>
            <div>
              <p className="text-[#949BA4] text-[10px] font-bold uppercase tracking-wider mb-1">Affected Item</p>
              <p className="text-white font-mono bg-[#2B2D31] px-2.5 py-1 rounded inline-block text-xs max-w-full">
                <ExpandableValue value={log.targetDisplay || log.targetId || 'System'} maxLength={25} />
              </p>
            </div>
          </div>

          {hasNewValues && (
            <div>
              <p className="text-[#949BA4] text-[10px] font-bold uppercase tracking-wider mb-2">New Configuration / Value</p>
              <div className="bg-[#18191C] p-4 rounded-lg border border-[#2B2D31]">
                {renderJSONDetails(log.newValuesJson)}
              </div>
            </div>
          )}

          {hasOldValues && (
            <div>
              <p className="text-[#949BA4] text-[10px] font-bold uppercase tracking-wider mb-2">Previous Configuration / Value</p>
              <div className="bg-[#18191C] p-4 rounded-lg border border-[#2B2D31]">
                {renderJSONDetails(log.oldValuesJson)}
              </div>
            </div>
          )}

          {hasMetadata && (
            <div>
              <p className="text-[#949BA4] text-[10px] font-bold uppercase tracking-wider mb-2">Additional Metadata</p>
              <div className="bg-[#18191C] p-4 rounded-lg border border-[#2B2D31]">
                {renderJSONDetails(log.metadataJson)}
              </div>
            </div>
          )}

          {!hasNewValues && !hasOldValues && !hasMetadata && (
            <div className="text-center py-4 text-[#949BA4] text-xs italic">
              No additional payload data available for this activity log.
            </div>
          )}
