import { motion, AnimatePresence } from 'framer-motion';
import * as Icons from './Icons';

interface Notification {
  id: string;
  type: string;
  title: string;
  message: string;
  link?: string;
  isRead: boolean;
  createdAt: string;
}

interface Props {
