  onClose: () => void;
  notifications: Notification[];
  onMarkRead: (id: string) => void;
  onClearAll: () => void;
  onNavigate: (tab: string) => void;
}

export default function NotificationCenter({ isOpen, onClose, notifications, onMarkRead, onClearAll, onNavigate }: Props) {
  const unreadCount = (notifications || []).filter(n => !n.isRead).length;

  const getTypeIcon = (type: string) => {
    switch (type) {
      case 'ai_insight': return <Icons.Cpu className="text-primary" />;
      case 'campaign': return <Icons.Zap className="text-purple-400" />;
      case 'alert': return <Icons.AlertTriangle className="text-red-400" />;
      default: return <Icons.Info className="text-blue-400" />;
    }
  };

  return (
    <AnimatePresence>
      {isOpen && (
        <>
          {/* Backdrop */}
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            onClick={onClose}
            className="fixed inset-0 bg-black/60 backdrop-blur-sm z-[100]"
          />

          {/* Slide-over Panel */}
          <motion.div
            initial={{ x: '100%' }}
            animate={{ x: 0 }}
            exit={{ x: '100%' }}
            transition={{ type: 'spring', damping: 25, stiffness: 200 }}
            className="fixed top-0 right-0 bottom-0 w-full max-w-md bg-bg/80 backdrop-blur-2xl border-l border-white/5 z-[101] shadow-2xl flex flex-col"
          >
            {/* Header */}
            <div className="p-8 border-b border-white/5 flex items-center justify-between">
              <div>
                <h2 className="text-2xl font-black text-white flex items-center gap-3">
                  Notifications
                  {unreadCount > 0 && (
                    <span className="px-2 py-0.5 bg-primary rounded-full text-[10px] font-black">{unreadCount}</span>
                  )}
                </h2>
                <p className="text-text-muted text-xs font-medium mt-1">Updates from your GloBot ecosystem.</p>
              </div>
              <button 
                onClick={onClose}
                className="p-2 hover:bg-white/5 rounded-xl text-text-muted hover:text-white transition-colors"
              >
                <Icons.X className="w-6 h-6" />
              </button>
            </div>

            {/* List */}
            <div className="flex-1 overflow-y-auto p-4 space-y-3 custom-scrollbar">
              {(notifications || []).length === 0 ? (
                <div className="h-full flex flex-col items-center justify-center text-center opacity-50 px-8">
                  <div className="w-16 h-16 bg-white/5 rounded-full flex items-center justify-center mb-4">
                    <Icons.BellOff className="w-8 h-8 text-white/20" />
                  </div>
                  <p className="text-white font-bold text-lg mb-2">Systems Nominal</p>
                  <p className="text-xs font-medium text-text-muted">No new alerts or activity updates at this time.</p>
                </div>
              ) : (
                (notifications || []).map((n) => (
                  <motion.div
                    key={n.id}
                    layout
                    initial={{ opacity: 0, y: 10 }}
                    animate={{ opacity: 1, y: 0 }}
                    onClick={() => {
                      if (!n.isRead) onMarkRead(n.id);
                      if (n.link) {
                        onNavigate(n.link);
                        onClose();
                      }
                    }}
                    className={`p-5 rounded-3xl border transition-all cursor-pointer group ${
                      n.isRead 
                        ? 'bg-white/[0.02] border-white/5 opacity-60' 
                        : 'bg-white/5 border-primary/20 shadow-xl shadow-primary/5'
                    }`}
                  >
                    <div className="flex gap-4">
                      <div className={`p-3 rounded-2xl shrink-0 ${
                        n.isRead ? 'bg-white/5' : 'bg-primary/10'
                      }`}>
                        {getTypeIcon(n.type)}
                      </div>
                      <div className="flex-1 min-w-0">
                        <div className="flex items-start justify-between gap-2 mb-1">
                          <h4 className="text-sm font-bold text-white truncate">{n.title}</h4>
                          <span className="text-[10px] text-text-muted whitespace-nowrap">
                            {(() => {
                              const rawDate = n.createdAt || (n as any).created_at;
                              if (!rawDate) return '';
                              const parsed = new Date(typeof rawDate === 'string' ? rawDate.replace(' ', 'T') : rawDate);
                              return isNaN(parsed.getTime()) ? '' : parsed.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
                            })()}
                          </span>
                        </div>
                        <p className="text-xs text-text-muted line-clamp-2 leading-relaxed">{n.message}</p>

                        {!n.isRead && (
                          <div className="mt-3 flex items-center gap-2">
                            <div className="w-1.5 h-1.5 bg-primary rounded-full" />
                            <span className="text-[10px] font-black uppercase tracking-widest text-primary">New Alert</span>
                          </div>
                        )}
                      </div>
                    </div>
                  </motion.div>
                ))
              )}
            </div>

            {/* Footer */}
            {(notifications || []).length > 0 && (
              <div className="p-6 border-t border-white/5 bg-black/20 flex items-center justify-between gap-4">
                <button 
                  onClick={onClearAll}
                  className="text-xs font-bold text-text-muted hover:text-red-400 transition-colors uppercase tracking-widest"
                >
                  Clear Archive
