export const PasskeyManager = () => {
  const [passkeys, setPasskeys] = useState<Passkey[]>([]);
  const [loading, setLoading] = useState(true);
  const [registering, setRegistering] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editName, setEditName] = useState('');
  const { addToast, confirm: toastConfirm } = useToast();

  const fetchPasskeys = async () => {
    try {
      const data = await apiRequest('/api/admin/webauthn/passkeys') as any;
      setPasskeys(data.passkeys || []);
    } catch (err) {
      console.error('Failed to fetch passkeys:', err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchPasskeys();
  }, []);

  const handleRegister = async () => {
    setRegistering(true);
    try {
      const options = await apiRequest('/api/admin/webauthn/generate-registration', { method: 'POST' }) as any;
      const attestation = await startRegistration({ optionsJSON: options });
      await apiRequest('/api/admin/webauthn/verify-registration', {
        method: 'POST',
        body: { attestation, name: `Passkey ${passkeys.length + 1}` }
      });
      addToast('Passkey registered successfully!', 'success');
      fetchPasskeys();
    } catch (err: any) {
      console.error('Registration failed:', err);
      addToast(err.message || 'Passkey registration failed', 'error');
    } finally {
      setRegistering(false);
    }
  };

  const handleRevoke = async (id: string) => {
    const isConfirmed = await toastConfirm('Are you sure you want to revoke this passkey? You will lose access to administrative routes using this key.');
    if (!isConfirmed) return;
    try {
      await apiRequest(`/api/admin/webauthn/passkeys/${id}`, { method: 'DELETE' });
      addToast('Passkey revoked', 'success');
      fetchPasskeys();
    } catch (err: any) {
      addToast('Failed to revoke passkey', 'error');
    }
  };

  const handleRename = async (id: string, currentName: string, newName: string) => {
    if (!newName || newName === currentName) return;
    try {
      await apiRequest(`/api/admin/webauthn/passkeys/${id}`, {
        method: 'PUT',
        body: { name: newName }
      });
      addToast('Passkey renamed', 'success');
      fetchPasskeys();
    } catch (err: any) {
      addToast('Failed to rename passkey', 'error');
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h3 className="text-lg font-semibold text-white">My Security Keys</h3>
          <p className="text-sm text-gray-400">Manage your passkeys for secure, password-free access to dashboard settings.</p>
        </div>
        <button
          onClick={handleRegister}
          disabled={registering}
          className="flex items-center space-x-2 px-4 py-2 bg-primary/20 hover:bg-primary/30 text-primary rounded-lg transition-colors border border-primary/30"
        >
          {registering ? <Icons.RotateCw className="w-4 h-4 animate-spin" /> : <Icons.Plus className="w-4 h-4" />}
          <span>{registering ? 'Registering...' : 'Add Passkey'}</span>
        </button>
      </div>

      <div className="grid gap-5">
        {loading ? (
          <div className="h-32 flex items-center justify-center bg-white/5 rounded-xl border border-white/10">
            <Icons.RotateCw className="w-6 h-6 text-primary animate-spin" />
          </div>
        ) : passkeys.length === 0 ? (
          <div className="h-32 flex flex-col items-center justify-center bg-white/5 rounded-xl border border-white/10 text-gray-400">
            <Icons.Shield className="w-8 h-8 mb-2 opacity-20" />
            <p>No passkeys registered.</p>
          </div>
        ) : (
          <AnimatePresence>
            {passkeys.map((pk) => {
              const branding = getBranding(pk.providerName);
              return (
                <motion.div
                  key={pk.id}
                  initial={{ opacity: 0, y: 10 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0, scale: 0.95 }}
                  className={`p-6 rounded-xl border transition-all ${branding.bg} ${branding.border}`}
                >
                  <div className="flex items-start justify-between">
                    <div className="flex items-start space-x-5 min-w-0 flex-1">
                      <div className={`p-3 rounded-xl border ${branding.border} ${branding.badgeBg} shrink-0`}>
                        <ProviderLogo icon={pk.icon} logo={pk.logo} />
                      </div>
                      <div className="min-w-0 flex-1">
                        <div className="flex items-center space-x-2 flex-wrap gap-y-1">
                          {editingId === pk.id ? (
                            <div className="flex items-center space-x-2">
                              <input
                                type="text"
                                value={editName}
                                onChange={(e) => setEditName(e.target.value)}
                                className="bg-[#1E1F22] text-white border border-[#2B2D31] rounded px-3 py-1 text-sm outline-none focus:border-primary"
                                autoFocus
                              />
                              <button onClick={() => { handleRename(pk.id, pk.name, editName); setEditingId(null); }} className="p-1.5 text-green-400 hover:text-green-300"><Icons.Check className="w-4 h-4" /></button>
                              <button onClick={() => setEditingId(null)} className="p-1.5 text-red-400 hover:text-red-300"><Icons.Close className="w-4 h-4" /></button>
                            </div>
                          ) : (
                            <>
                              <h4 className="font-bold text-white text-lg">{pk.name}</h4>
                              <span className={`text-xs px-3 py-0.5 rounded-full border font-bold uppercase tracking-tighter ${branding.badgeBg} ${branding.badgeText} ${branding.border}`}>
                                {pk.securityLevel || 'Protected'}
                              </span>
                              <button onClick={() => { setEditingId(pk.id); setEditName(pk.name); }} className="p-1.5 text-gray-500 hover:text-white transition-colors"><Icons.Edit className="w-4 h-4" /></button>
                            </>
                          )}
                        </div>
                        <p className="text-base text-gray-400 mt-1">{pk.providerName} <span className="text-gray-600">by</span> {pk.manufacturer}</p>

                        {/* AAGUID Metadata Block */}
                        {pk.aaguid && (
                          <div className="mt-4 p-4 bg-black/20 rounded-lg border border-white/5">
                            <div className="flex items-center space-x-2 mb-2">
                              <Icons.Info className="w-4 h-4 text-gray-500" />
                              <span className="text-xs font-bold uppercase tracking-wider text-gray-500">Authenticator Attestation GUID</span>
                            </div>
                            <p className="text-sm font-mono text-gray-400 break-all">{pk.aaguid}</p>
                          </div>
                        )}

                        {/* Metadata Grid */}
                        <div className="mt-5 grid grid-cols-2 md:grid-cols-4 gap-4">
                          <div className="flex items-center space-x-2 text-xs uppercase tracking-wider text-gray-500">
                            <Icons.Clock className="w-4 h-4 shrink-0" />
                            <span className="truncate">Last used: {pk.lastUsedAt ? new Date(pk.lastUsedAt).toLocaleDateString() : 'Never'}</span>
                          </div>
                          <div className="flex items-center space-x-2 text-xs uppercase tracking-wider text-gray-500">
                            <Icons.Globe className="w-4 h-4 shrink-0" />
                            <span className="truncate">{pk.lastUsedCity || 'Unknown'}, {pk.lastUsedCountry || 'Unknown'}</span>
                          </div>
                          <div className="flex items-center space-x-2 text-xs uppercase tracking-wider text-gray-500">
                            <Icons.Globe className="w-4 h-4 shrink-0" />
                            <span className="truncate">{pk.lastUsedIpV4 || 'No IP'}</span>
                          </div>
                          <div className="flex items-center space-x-2 text-xs uppercase tracking-wider text-gray-500">
                            <Icons.Info className="w-4 h-4 shrink-0" />
                            <span className="truncate">Uses: {pk.counter}</span>
                          </div>
                        </div>
                      </div>
                    </div>

                    <button
                      onClick={() => handleRevoke(pk.id)}
                      className="p-2 text-gray-500 hover:text-red-500 hover:bg-red-500/10 rounded-lg transition-all shrink-0 ml-4"
                      title="Revoke Passkey"
                    >
                      <Icons.Trash className="w-5 h-5" />
                    </button>
                  </div>
                </motion.div>
              );
            })}
          </AnimatePresence>
        )}
      </div>
    </div>
  );
};

