import React from 'react';
import { motion, AnimatePresence } from 'motion/react';
import { useToast } from '../contexts/ToastContext';
import type { Toast as ToastType } from '../contexts/ToastContext';
import * as Icons from './Icons';

const ToastIcon = ({ type }: { type: string }) => {
  switch (type) {
    case 'success': return <Icons.Check className="text-emerald-400" size={18} />;
    case 'error': return <Icons.Shield className="text-red-400" size={18} />;
    case 'warning': return <Icons.Info className="text-yellow-400" size={18} />;
    default: return <Icons.Bell className="text-primary" size={18} />;
  }
};

const ToastItem: React.FC<{ toast: ToastType }> = ({ toast }) => {
  const { removeToast } = useToast();

  return (
    <motion.div
      layout
      initial={{ opacity: 0, y: 50, scale: 0.9, filter: 'blur(10px)' }}
      animate={{ opacity: 1, y: 0, scale: 1, filter: 'blur(0px)' }}
      exit={{ opacity: 0, scale: 0.9, transition: { duration: 0.2 } }}
      className="glass-card mb-3 p-4 pr-12 min-w-[320px] max-w-[420px] shadow-2xl relative pointer-events-auto group overflow-hidden border-white/10"
    >
      <div className="absolute top-0 left-0 w-1 h-full opacity-50 bg-current" style={{ color: 
        toast.type === 'success' ? '#10b981' : 
        toast.type === 'error' ? '#ef4444' : 
        toast.type === 'warning' ? '#fbbf24' : '#5865F2' 
      }} />

      <div className="flex items-start space-x-4">
        <div className="shrink-0 mt-0.5">
          <ToastIcon type={toast.type} />
        </div>
        <div className="flex-1 min-w-0">
          <p className="text-sm font-bold text-white tracking-tight leading-tight">
            {toast.isConfirmation ? 'Action Required' : (
             toast.type === 'error' ? 'Security Notice' : 
             toast.type === 'success' ? 'Task Complete' : 
             toast.type === 'warning' ? 'System Warning' : 'Update'
            )}
          </p>
          <p className="text-xs text-text-muted mt-1 font-medium leading-relaxed">
            {toast.message}
          </p>

          {toast.isConfirmation && (
            <div className="mt-4 flex items-center space-x-3">
              <button 
                onClick={() => {
                  toast.resolve?.(true);
                  removeToast(toast.id);
                }}
                className="px-4 py-1.5 bg-[#43b581] hover:bg-[#3ca374] text-white text-[10px] font-black uppercase tracking-widest rounded-lg transition-all shadow-lg active:scale-95"
              >
                Confirm
              </button>
              <button 
                onClick={() => {
                  toast.resolve?.(false);
                  removeToast(toast.id);
                }}
                className="px-4 py-1.5 bg-white/5 hover:bg-white/10 text-white text-[10px] font-black uppercase tracking-widest rounded-lg transition-all border border-white/10 active:scale-95"
              >
                Cancel
              </button>
            </div>
          )}
        </div>
      </div>

      {!toast.isConfirmation && (
        <button
          onClick={() => removeToast(toast.id)}
          className={`absolute top-4 right-4 p-1 rounded-lg hover:bg-white/5 text-text-muted hover:text-white transition-all ${!toast.duration || toast.type === 'error' ? 'opacity-100' : 'opacity-0 group-hover:opacity-100'}`}
        >
          <Icons.Close size={14} />
        </button>
      )}

      {/* Progress Bar */}
      {!toast.isConfirmation && toast.duration && toast.duration > 0 && (
        <motion.div 
          className="absolute bottom-0 left-0 h-[2px] bg-white/20"
          initial={{ width: '100%' }}
          animate={{ width: 0 }}
          transition={{ duration: toast.duration / 1000, ease: 'linear' }}
        />
      )}
    </motion.div>
  );
};

export const ToastContainer: React.FC = () => {
  const { toasts } = useToast();

  return (
    <div className="fixed bottom-8 right-8 z-[100] flex flex-col items-end pointer-events-none">
      <AnimatePresence mode="popLayout">
        {toasts.map((toast) => (
          <ToastItem key={toast.id} toast={toast} />
        ))}
      </AnimatePresence>
    </div>
  );
};

import React, { useState, useEffect, useCallback } from 'react';
import { startRegistration } from '@simplewebauthn/browser';
import { toast } from 'sonner';
import { useToast } from '../../contexts/ToastContext';

interface PasskeyRecord {
  id: string;
  name: string | null;
  aaguid: string | null;
  created_at: string;
  counter: number;
}

export const AuthVault: React.FC = () => {
  const { confirm: toastConfirm } = useToast();

  const [passkeys, setPasskeys] = useState<PasskeyRecord[]>([]);
  const [loading, setLoading] = useState(true);
  const [registering, setRegistering] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editName, setEditName] = useState('');

  const fetchPasskeys = useCallback(async () => {
    try {
      const resp = await fetch('/api/admin/webauthn/passkeys');
      if (!resp.ok) return;
      const data = await resp.json() as any;
      setPasskeys(data.passkeys || []);
    } catch {
      // silent fail on load
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchPasskeys();
  }, [fetchPasskeys]);

  const handleRegisterPasskey = async () => {
    setRegistering(true);
    try {
      toast.info('Requesting security challenge...');

      const genResp = await fetch('/api/admin/webauthn/generate-registration', { method: 'POST' });
      if (!genResp.ok) {
        const data = await genResp.json().catch(() => ({ error: `Server error ${genResp.status}` }));
        throw new Error((data as any).error || 'Failed to generate registration challenge');
      }
      const options = await genResp.json() as any;

      toast.info('Action required: touch your security key or sensor.');
      const attResp = await startRegistration({ optionsJSON: options });

      const verifyResp = await fetch('/api/admin/webauthn/verify-registration', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(attResp),
      });

      if (verifyResp.ok) {
        toast.success('Security key registered.');
        await fetchPasskeys();
      } else {
        const data = await verifyResp.json().catch(() => ({ error: 'Verification failed' }));
        throw new Error((data as any).error || 'Registration verification failed');
      }
    } catch (e: any) {
      toast.error(`Error: ${e.message || 'Security key connection failed.'}`);
    } finally {
      setRegistering(false);
    }
  };

  const handleRename = async (id: string) => {
    try {
      const resp = await fetch(`/api/admin/webauthn/passkeys/${id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name: editName }),
      });
      if (resp.ok) {
        toast.success('Key renamed.');
        setEditingId(null);
        await fetchPasskeys();
      }
    } catch {
      toast.error('Failed to rename key.');
    }
  };

  const handleRevoke = async (id: string, name: string | null) => {
    const isConfirmed = await toastConfirm(`Revoke passkey "${name || 'Unnamed'}"? This cannot be undone.`);
    if (!isConfirmed) return;
    try {
      const resp = await fetch(`/api/admin/webauthn/passkeys/${id}`, { method: 'DELETE' });
      if (resp.ok) {
        toast.success(`Passkey "${name || 'Unnamed'}" revoked.`);
        await fetchPasskeys();
      }
    } catch {
      toast.error('Failed to revoke passkey.');
    }
  };

  const formatDate = (dateStr: string | null) => {
    if (!dateStr) return '—';
    try {
      return new Date(dateStr).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
    } catch { return dateStr; }
  };

  return (
    <div className="p-6 bg-white/5 backdrop-blur-md rounded-2xl border border-white/10 shadow-2xl transition-all hover:border-white/20">
      <div className="flex justify-between items-start mb-6">
        <div>
          <h2 className="text-xl font-bold text-white mb-2 flex items-center gap-2">
            <span>🛡️</span> Security Keys
          </h2>
          <p className="text-white/60 text-sm font-medium leading-relaxed">
            Manage security keys for your account.
          </p>
        </div>
        <div className="text-[10px] font-mono text-white/30 uppercase tracking-widest">
          {passkeys.length} key{passkeys.length !== 1 ? 's' : ''}
        </div>
      </div>

      <div className="space-y-3">
        {loading ? (
          <div className="flex items-center justify-center p-8">
            <div className="w-5 h-5 border-2 border-white/20 border-t-white/60 rounded-full animate-spin" />
          </div>
        ) : passkeys.length === 0 ? (
          <div className="text-center p-6 text-white/40 text-sm">
            No passkeys registered. Register your first hardware key below.
          </div>
        ) : (
          passkeys.map((pk) => (
            <div key={pk.id} className="flex items-center justify-between p-4 rounded-xl bg-white/5 border border-white/5 transition-all hover:bg-slate-900 group">
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 rounded-full bg-blue-500/20 flex items-center justify-center text-blue-400 border border-blue-500/30">
                  🔒
                </div>
                <div>
                  {editingId === pk.id ? (
                    <div className="flex items-center gap-2">
                      <input
                        type="text"
                        value={editName}
                        onChange={(e) => setEditName(e.target.value)}
                        onKeyDown={(e) => e.key === 'Enter' && handleRename(pk.id)}
                        className="bg-white/10 border border-white/20 rounded px-2 py-1 text-sm text-white outline-none focus:border-blue-400"
                        autoFocus
                      />
                      <button onClick={() => handleRename(pk.id)} className="text-[10px] text-blue-400 font-bold uppercase">Save</button>
                      <button onClick={() => setEditingId(null)} className="text-[10px] text-white/40 font-bold uppercase">Cancel</button>
                    </div>
                  ) : (
                    <>
                      <div className="text-sm font-black text-white uppercase tracking-tight">
                        {pk.name || 'Unnamed Key'}
                      </div>
                      <div className="text-[10px] text-white/40 font-mono uppercase tracking-[0.2em]">
                        {formatDate(pk.created_at)} · Counter: {pk.counter}
                      </div>
                    </>
                  )}
                </div>
              </div>
              <div className="flex items-center gap-3 opacity-0 group-hover:opacity-100 transition-all">
                <button
                  onClick={() => { setEditingId(pk.id); setEditName(pk.name || ''); }}
                  className="text-[10px] font-black uppercase tracking-widest text-white/50 hover:text-white hover:underline"
                >
                  Rename
                </button>
                <button 
                  onClick={() => handleRevoke(pk.id, pk.name)}
                  className="text-[10px] font-black uppercase tracking-widest text-red-400 hover:underline"
                >
                  Revoke
                </button>
              </div>
            </div>
          ))
        )}

        {/* Register Button */}
        <button 
          onClick={handleRegisterPasskey}
          disabled={registering}
          className="w-full mt-4 py-4 rounded-xl bg-blue-600/10 border border-blue-500/30 text-blue-400 font-black text-xs uppercase tracking-[0.2em] transition-all hover:bg-blue-600/20 hover:shadow-[0_0_30px_0_rgba(59,130,246,0.2)] active:scale-95 disabled:opacity-50 disabled:cursor-not-allowed"
        >
          {registering ? 'Registering...' : 'Register New Passkey'}
        </button>
      </div>
    </div>
  );
};

import React, { useEffect } from 'react';
import toast from 'react-hot-toast';

interface Props {
  appName: string;
}

export const AuthGate: React.FC<Props> = ({ appName }) => {
  useEffect(() => {
    const hash = window.location.hash;
    const params = new URLSearchParams(hash.split('?')[1]);
    const error = params.get('error');
    if (error) {
      toast.error(`Login failed: ${decodeURIComponent(params.get('message') || error)}`);
      window.location.hash = '#/';
    }
  }, []);

  const handleDiscordAuth = () => {
    window.location.href = '/api/auth/login/discord';
  };

  const handleGoogleAuth = () => {
    window.location.href = '/api/auth/login/google';
  };

  return (
    <div className="landing-container min-h-screen bg-slate-950 flex flex-col items-center justify-center">
      <h1 className="text-4xl font-bold text-white mb-8">Sign in to {appName}</h1>
      <div className="flex flex-col gap-4 w-72">
        <button onClick={handleDiscordAuth} className="bg-indigo-600 hover:bg-indigo-700 text-white p-3 rounded-lg flex justify-center items-center">
          Continue with Discord
        </button>
        <button onClick={handleGoogleAuth} className="bg-slate-800 hover:bg-slate-700 text-white p-3 rounded-lg flex justify-center items-center">
          Continue with Google
        </button>
      </div>
      <button onClick={() => window.location.hash = '#/'} className="mt-8 text-slate-400 hover:text-white">
        Return to Home
      </button>
    </div>
  );
};

import React from 'react';
