import React, { useState, useEffect, useRef } from 'react';
import * as Icons from '../Icons';
import { SearchableSelect } from '../ui/SearchableSelect';
import { fitImage } from './fitImage';

const BANNER_SUPPORTED: Record<string, { width: number; height: number; maxBytes: number; label: string }> = {
  'YouTube': { width: 1280, height: 720, maxBytes: 2 * 1024 * 1024, label: 'YouTube (1280×720, max 2 MB)' },
  'Discord': { width: 1920, height: 1080, maxBytes: 10 * 1024 * 1024, label: 'Discord Event (1920×1080, max 10 MB)' },
};

const PLATFORM_FIELDS: Record<string, {
  channel: boolean;
  stream: boolean;
  chat: boolean;
  banner: boolean;
  location: boolean;
  category: boolean;
  tags: boolean;
  privacy: boolean;
  duration: boolean;
  timezone: boolean;
  recurring: boolean;
}> = {
  'Twitch':     { channel: true,  stream: true,  chat: true,  banner: false, location: false, category: true,  tags: true,  privacy: false, duration: true,  timezone: true,  recurring: true  },
  'YouTube':    { channel: true,  stream: true,  chat: true,  banner: true,  location: false, category: false, tags: true,  privacy: true,  duration: false, timezone: false, recurring: false },
  'StreamYard': { channel: true,  stream: false, chat: false, banner: false, location: false, category: false, tags: false, privacy: false, duration: false, timezone: false, recurring: false },
  'Discord':    { channel: true,  stream: false, chat: false, banner: true,  location: true,  category: false, tags: false, privacy: false, duration: false, timezone: false, recurring: true  },
};

const DISCORD_ENTITY_TYPES = [
  { value: 'stage_instance', label: 'Stage Instance' },
  { value: 'voice', label: 'Voice Channel' },
  { value: 'external', label: 'External (Online / In-Person)' },
];

const TIMEZONES = [
  'America/New_York', 'America/Chicago', 'America/Denver', 'America/Los_Angeles',
  'America/Anchorage', 'Pacific/Honolulu', 'Europe/London', 'Europe/Paris',
  'Europe/Berlin', 'Asia/Tokyo', 'Asia/Shanghai', 'Asia/Kolkata',
  'Australia/Sydney', 'Pacific/Auckland',
];

interface EventFormProps {
  event: any;
  onSave: (e: React.FormEvent) => void;
  onCancel: () => void;
  onChange: (updates: any) => void;
  apiRequest: (url: string, options?: any) => Promise<any>;
}

export const EventForm = ({ event, onSave, onCancel, onChange, apiRequest }: EventFormProps) => {
  const selectedPlatformSpec = event.platform ? BANNER_SUPPORTED[event.platform] : null;
  const platformFields = event.platform ? PLATFORM_FIELDS[event.platform] : null;
  const isDiscord = event.platform === 'Discord';
  const isExternal = isDiscord && event.entity_type === 'external';

  // Banner state
  const [bannerPreview, setBannerPreview] = useState<string | null>(event.banner_url || null);
  const [bannerAdjusted, setBannerAdjusted] = useState(false);
  const [bannerSizeKB, setBannerSizeKB] = useState<number | null>(null);
  const [bannerProcessing, setBannerProcessing] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Data fetching state
  const [discordChannels, setDiscordChannels] = useState<any[]>([]);
  const [broadcasters, setBroadcasters] = useState<any[]>([]);
  const [chatMappings, setChatMappings] = useState<any[]>([]);
  const [streams, setStreams] = useState<any[]>([]);
  const [streamsLoading, setStreamsLoading] = useState(false);
  const [linkChat, setLinkChat] = useState(!!event.chat_mapping_id);

  // Sync linkChat with event
  useEffect(() => {
    setLinkChat(!!event.chat_mapping_id);
  }, [event.chat_mapping_id]);

  // Clear banner when switching to non-supported platform
  useEffect(() => {
    if (!selectedPlatformSpec && event.banner_url !== undefined) {
      setBannerPreview(null);
      setBannerAdjusted(false);
      setBannerSizeKB(null);
      onChange({ banner_url: undefined });
    }
  }, [event.platform]);

  // Fetch Discord channels — filtered by entity type
  useEffect(() => {
    if (isDiscord && event.guild_id) {
      const entityType = event.entity_type || 'voice';
      let types = '2'; // default voice
      if (entityType === 'stage_instance') types = '13';
      else if (entityType === 'external') types = ''; // no channel needed
      if (types) {
        apiRequest(`/api/admin/discord/channels?guild_id=${event.guild_id}&types=${types}`)
          .then(setDiscordChannels)
          .catch(() => setDiscordChannels([]));
      } else {
        setDiscordChannels([]);
      }
    } else {
      setDiscordChannels([]);
    }
  }, [event.platform, event.entity_type, event.guild_id]);

  // Fetch broadcasters
  useEffect(() => {
    if (event.platform === 'Twitch' || event.platform === 'YouTube') {
      apiRequest('/api/admin/broadcasters')
        .then((list: any[]) => setBroadcasters(list.filter((b: any) => b.platform === event.platform?.toLowerCase())))
        .catch(() => setBroadcasters([]));
    } else {
      setBroadcasters([]);
    }
  }, [event.platform]);

  // Fetch chat mappings
  useEffect(() => {
    if (event.guild_id) {
      apiRequest(`/api/admin/chat/mappings?guild_id=${event.guild_id}`)
        .then(setChatMappings)
        .catch(() => setChatMappings([]));
    }
  }, [event.guild_id]);

  // Fetch streams when broadcaster selected
  useEffect(() => {
    if (event.channel_id && (event.platform === 'Twitch' || event.platform === 'YouTube') && event.channel_id.length > 5) {
      const bc = broadcasters.find((b: any) => b.channel_id === event.channel_id || b.id === event.channel_id);
      if (bc?.id) {
        setStreamsLoading(true);
        apiRequest(`/api/admin/broadcasters/${bc.id}/streams`)
          .then((data: any) => setStreams(data.streams || []))
          .catch(() => setStreams([]))
          .finally(() => setStreamsLoading(false));
      }
    } else {
      setStreams([]);
    }
  }, [event.channel_id, event.platform]);

  const handleBannerFile = async (file: File) => {
    if (!selectedPlatformSpec) return;
    setBannerProcessing(true);
    try {
      const { dataUrl, adjusted, finalSizeKB } = await fitImage(file, selectedPlatformSpec.width, selectedPlatformSpec.height, selectedPlatformSpec.maxBytes);
      setBannerPreview(dataUrl);
      setBannerAdjusted(adjusted);
      setBannerSizeKB(finalSizeKB);
      onChange({ banner_url: dataUrl });
    } catch {
      // Silently fail
    } finally {
      setBannerProcessing(false);
    }
  };

  // Convert a stored UTC ISO string to local datetime-local input value
  const toLocalInputValue = (iso: string | null | undefined): string => {
    if (!iso) return '';
    const d = new Date(iso);
    if (isNaN(d.getTime())) return '';
    const pad = (n: number) => String(n).padStart(2, '0');
    return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`;
  };

  // Convert datetime-local input value (local time) to UTC ISO string
  const fromLocalInputValue = (val: string): string | null => {
    if (!val) return null;
    const d = new Date(val);
    return isNaN(d.getTime()) ? null : d.toISOString();
  };

  // Compute default end_time: 1 hour after start_time
  const getDefaultEndTime = () => {
    if (event.end_time) return toLocalInputValue(event.end_time);
    if (event.start_time) {
      const start = new Date(event.start_time);
      start.setHours(start.getHours() + 1);
      return toLocalInputValue(start.toISOString());
    }
    return '';
  };

  // Info box text per platform
  const getInfoText = () => {
    if (isDiscord) return 'This event will be synced as a Discord Scheduled Event in the linked server.';
    if (event.platform === 'Twitch' || event.platform === 'YouTube') return 'Link this event to a live stream. Connect it to Discord chat for real-time mirroring.';
    if (event.platform === 'StreamYard') return 'This event will appear on the community calendar.';
    return '';
  };

  return (
    <div className="fixed inset-0 bg-black/50 backdrop-blur-sm flex items-center justify-center z-50 p-4">
      <form onSubmit={onSave} className="bg-[#313338] w-full max-w-2xl rounded-xl border border-[#2B2D31] shadow-2xl overflow-hidden animate-in fade-in zoom-in duration-200">
        <div className="p-6 border-b border-[#1E1F22] flex items-center justify-between">
          <h3 className="text-xl font-bold text-white">{event.id ? 'Edit Event' : 'Create New Event'}</h3>
          <button type="button" onClick={onCancel} className="text-[#949BA4] hover:text-white"><Icons.Close /></button>
        </div>

        <div className="p-6 space-y-4 max-h-[70vh] overflow-y-auto custom-scrollbar">
          {/* Title */}
          <div className="space-y-1">
            <label className="text-xs font-bold text-[#949BA4] uppercase">Event Title</label>
            <input type="text" required value={event.title} onChange={e => onChange({ title: e.target.value })}
              className="w-full bg-[#1E1F22] text-white border border-[#2B2D31] rounded-lg p-3 outline-none focus:border-[#5865F2] transition-colors"
              placeholder="e.g. Weekly Community Podcast" />
