export async function fitImage(
  file: File,
  targetW: number,
  targetH: number,
  maxBytes: number
): Promise<{ dataUrl: string; adjusted: boolean; finalSizeKB: number }> {
  return new Promise((resolve, reject) => {
    const url = URL.createObjectURL(file);
    const img = new Image();
    img.onload = () => {
      URL.revokeObjectURL(url);
      const scale = Math.min(targetW / img.naturalWidth, targetH / img.naturalHeight);
      const drawW = img.naturalWidth * scale;
      const drawH = img.naturalHeight * scale;
      const offsetX = (targetW - drawW) / 2;
      const offsetY = (targetH - drawH) / 2;

      const canvas = document.createElement('canvas');
      canvas.width = targetW;
      canvas.height = targetH;
      const ctx = canvas.getContext('2d')!;
      ctx.clearRect(0, 0, targetW, targetH);
      ctx.drawImage(img, offsetX, offsetY, drawW, drawH);

      const dimensionsChanged = img.naturalWidth !== targetW || img.naturalHeight !== targetH;

      let dataUrl = canvas.toDataURL('image/png');
      let byteSize = Math.round((dataUrl.length - 'data:image/png;base64,'.length) * 0.75);

      if (byteSize > maxBytes) {
        const ctx2 = canvas.getContext('2d')!;
        ctx2.fillStyle = '#000000';
        ctx2.fillRect(0, 0, targetW, targetH);
        ctx2.drawImage(img, offsetX, offsetY, drawW, drawH);
        let quality = 0.92;
        do {
          dataUrl = canvas.toDataURL('image/jpeg', quality);
          byteSize = Math.round((dataUrl.length - 'data:image/jpeg;base64,'.length) * 0.75);
          quality -= 0.05;
        } while (byteSize > maxBytes && quality > 0.4);
      }

      const adjusted = dimensionsChanged || file.size > maxBytes;
      resolve({ dataUrl, adjusted, finalSizeKB: Math.round(byteSize / 1024) });
    };
    img.onerror = reject;
    img.src = url;
  });
}

