  const [saving, setSaving] = useState(false);

  const fetchUsers = async () => {
    setLoading(true);
    try {
      const res = await fetch('/api/admin/project-roles?projectId=globot');
      if (res.ok) {
        const json = await res.json();
        if (json.success) {
          setUsers(json.data || []);
        }
      }
    } catch (err) {
      console.error('[UserManager] Failed to fetch users from Foundation Neon DB:', err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchUsers();
  }, []);

  const handleUpdateRole = async (userId: string, roleId: string, customTitle?: string, customDisplayName?: string) => {
    setSaving(true);
    try {
      const res = await fetch('/api/admin/project-roles', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          userId,
          projectId: 'globot',
          roleId,
          customRoleTitle: customTitle,
          customDisplayName: customDisplayName,
          foundationAccess: 'false',
          permissions: []
        })
      });
      if (res.ok) {
        await fetchUsers();
        setEditingUser(null);
      }
