  apiRequest: any;
  selectedGuildId?: string;
  addToast: any;
  confirm: any;
  isOwner: boolean;
}

const PERMISSION_GROUPS: { label: string; actions: { key: string; label: string }[] }[] = [
  { label: 'Community', actions: [
    { key: 'users', label: 'Users' },
    { key: 'calendar', label: 'Calendar' },
  ]},
  { label: 'Engagement', actions: [
    { key: 'giveaways', label: 'Giveaways' },
    { key: 'polls', label: 'Polls' },
  ]},
  { label: 'Content', actions: [
    { key: 'streams', label: 'Streams' },
    { key: 'chat', label: 'Chat' },
    { key: 'fields', label: 'Field Unlock' },
  ]},
  { label: 'Admin', actions: [
    { key: 'settings', label: 'Settings' },
    { key: 'presence', label: 'Bot Status' },
    { key: 'impersonation', label: 'Impersonation' },
  ]},
];

function SegmentedPermissionPill({
  value,
  onChange,
  disabled,
  allowRead = true,
}: {
  value: string;
  onChange: (val: 'none' | 'read' | 'write') => void;
  disabled?: boolean;
  allowRead?: boolean;
}) {
  const levels = (allowRead ? ['none', 'read', 'write'] : ['none', 'write']) as ('none' | 'read' | 'write')[];
  const activeStyles: Record<string, string> = {
    none: 'bg-[#3A3C40] text-red-400',
    read: 'bg-[#4B5DF6]/20 text-blue-300',
    write: 'bg-[#3BA55D]/20 text-emerald-300',
  };
  return (
    <div className={`inline-flex rounded-lg border border-[#35373C] overflow-hidden ${disabled ? 'opacity-50' : ''}`}>
      {levels.map(level => (
        <button
          key={level}
          type="button"
          disabled={disabled}
          onClick={() => onChange(level)}
          className={`px-3 py-1.5 text-[11px] font-bold uppercase tracking-wider transition-colors first:rounded-l-lg last:rounded-r-lg ${
            value === level
              ? activeStyles[level]
              : 'bg-[#2B2D31] text-[#949BA4] hover:bg-white/5 hover:text-white'
          }`}
          title={level === 'none' ? 'No access' : level === 'read' ? 'Read-only access' : 'Full read/write access'}
        >
          {level === 'none' ? 'None' : level === 'read' ? 'Read' : 'Write'}
        </button>
      ))}
    </div>
  );
}

export default function AccessControlManager({
  apiRequest,
  selectedGuildId,
  addToast,
  confirm,
  isOwner
}: AccessControlManagerProps) {
  const [activeTab, setActiveTab] = useState<'mappings' | 'permissions' | 'domains' | 'owners'>('mappings');

  // Data States
  const [rolesList, setRolesList] = useState<Role[]>([]);
  const [primaryGuildRoles, setPrimaryGuildRoles] = useState<any[]>([]);
  const [guildOptions, setGuildOptions] = useState<any[]>([]);
  const [domainConfigs, setDomainConfigs] = useState<DomainConfig[]>([]);
  const [ownerUsers, setOwnerUsers] = useState<any[]>([]);
  const [rolePermissions, setRolePermissions] = useState<Record<string, Record<string, 'none' | 'read' | 'write'>>>({});
  const [loading, setLoading] = useState(true);

  // Forms / Editing states
  const [newRoleForm, setNewRoleForm] = useState({ name: '', discord_role_id: '' });
  const [editingRoleName, setEditingRoleName] = useState<string | null>(null);
  const [editingDiscordRoleId, setEditingDiscordRoleId] = useState<string>('');

  const [isUpdatingPermissions, setIsUpdatingPermissions] = useState(false);
  const [isSavingDomain, setIsSavingDomain] = useState(false);

  // Domain Config Forms
  const [editingDomain, setEditingDomain] = useState<string | null>(null);
  const [editingFields, setEditingFields] = useState<Partial<DomainConfig>>({});
  const [newConfig, setNewConfig] = useState<DomainConfig>({ domain: '', guild_id: '', role_id: '' });
  const [showAddConfig, setShowAddConfig] = useState(false);

  // Mapping of roles by Guild ID
  const [mappingRolesMap, setMappingRolesMap] = useState<Record<string, any[]>>({});
  const [domainRoleMappings, setDomainRoleMappings] = useState<any[]>([]);
  const [newMapping, setNewMapping] = useState({ domain: '', discord_role_id: '', system_role: 'mod' });
  const [editingDomainConfig, setEditingDomainConfig] = useState<string | null>(null);
  const [editDomainFields, setEditDomainFields] = useState<Partial<DomainConfig>>({});

  // Domain verification state
  const [isVerifyingDomains, setIsVerifyingDomains] = useState(false);
  const [verifyResults, setVerifyResults] = useState<any[] | null>(null);

  const fetchData = async () => {
    try {
      const [rolesData, guildsData, domainData, permissionsData, usersData, mappingsData] = await Promise.all([
        apiRequest('/api/admin/roles').catch(() => []),
        apiRequest('/api/admin/discord/guilds').catch(() => []),
        apiRequest('/api/admin/domain-configs').catch(() => []),
        apiRequest('/api/admin/role-permissions').catch(() => ({})),
        apiRequest('/api/admin/users').catch(() => []),
        apiRequest('/api/admin/domain-role-mappings').catch(() => [])
      ]);

      setRolesList(rolesData || []);
      setGuildOptions(guildsData || []);
      setDomainConfigs(domainData || []);
      setRolePermissions(permissionsData || {});
      setOwnerUsers((usersData || []).filter((u: any) => u.globalRole === 'owner' || u.role === 'owner'));
      setDomainRoleMappings(mappingsData || []);

      // Fetch roles for the primary guild if possible
      const primaryGuildSetting = await apiRequest('/api/admin/settings').catch(() => null);
      const primaryGuildId = primaryGuildSetting?.primary_guild_id || primaryGuildSetting?.settings?.primary_guild_id;

      if (primaryGuildId) {
        const guildRoles = await apiRequest(`/api/admin/discord/roles?guild_id=${primaryGuildId}`).catch(() => []);
        setPrimaryGuildRoles(guildRoles.map((r: any) => ({ value: r.value || r.id, label: r.label || r.name })));
      }

      // Pre-fetch roles for each configured guild in the overrides list
      const domainsList = domainData || [];
      const distinctGuildIds = Array.from(new Set(domainsList.map((d: any) => d.guild_id))) as string[];

      const rolesMaps: Record<string, any[]> = {};
      await Promise.all(
        distinctGuildIds.map(async (gid) => {
          if (gid) {
            const groles = await apiRequest(`/api/admin/discord/roles?guild_id=${gid}`).catch(() => []);
            rolesMaps[gid] = groles.map((r: any) => ({ value: r.value || r.id, label: r.label || r.name }));
          }
        })
      );
      setMappingRolesMap(rolesMaps);
    } catch (e) {
      console.error('Failed to load access control config details:', e);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
  }, []);

  // Update mapping roles map when adding/editing overrides
  const fetchGuildRolesForMap = async (gid: string) => {
    if (!gid || mappingRolesMap[gid]) return;
    try {
      const groles = await apiRequest(`/api/admin/discord/roles?guild_id=${gid}`).catch(() => []);
      setMappingRolesMap(prev => ({
        ...prev,
        [gid]: groles
      }));
    } catch (e) {
      console.warn('Failed to fetch guild roles for override selection:', e);
    }
  };

  // CRUD for Roles List
  const handleCreateRole = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newRoleForm.name) {
      addToast('Role name is required.', 'error');
      return;
    }
    try {
      await apiRequest('/api/admin/roles', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(newRoleForm)
      });
      addToast(`Role "${newRoleForm.name}" created successfully.`, 'success');
      setNewRoleForm({ name: '', discord_role_id: '' });
      fetchData();
    } catch (err: any) {
      addToast(err.message || 'Failed to create role.', 'error');
    }
  };

  const handleUpdateRoleMapping = async (roleName: string) => {
    try {
      await apiRequest(`/api/admin/roles/${roleName}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ discord_role_id: editingDiscordRoleId })
      });
      addToast(`Successfully updated Discord role mapping for ${roleName}.`, 'success');
      setEditingRoleName(null);
      fetchData();
    } catch (err: any) {
      addToast(err.message || 'Failed to update mapping.', 'error');
    }
  };

  const handleDeleteRole = async (roleName: string) => {
    const isConfirmed = await confirm({
      title: 'Delete Custom Role',
      message: `Are you sure you want to delete the custom role "${roleName}"? This will clear its Discord role mappings.`
    });
    if (!isConfirmed) return;

    try {
      await apiRequest(`/api/admin/roles/${roleName}`, {
        method: 'DELETE'
      });
      addToast(`Role "${roleName}" deleted.`, 'success');
      fetchData();
    } catch (err: any) {
      addToast(err.message || 'Failed to delete role.', 'error');
    }
  };

  // Granular Permissions
  const handleSavePermissions = async () => {
    setIsUpdatingPermissions(true);
    try {
      await apiRequest('/api/admin/role-permissions', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(rolePermissions)
      });
      addToast('Granular permissions saved successfully.', 'success');
      window.dispatchEvent(new CustomEvent('globot-api-mutate', { detail: { path: '/api/admin/role-permissions' } }));
    } catch (err: any) {
      addToast(err.message || 'Failed to save permissions map.', 'error');
    } finally {
      setIsUpdatingPermissions(false);
    }
  };

  // CRUD for Domain configs
  const handleAddDomainConfig = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newConfig.domain || !newConfig.guild_id || !newConfig.role_id) {
      addToast('All config override fields are required.', 'error');
      return;
    }
    setIsSavingDomain(true);
    try {
      await apiRequest('/api/admin/domain-configs', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(newConfig)
      });
      addToast('Domain configuration override added.', 'success');
      setNewConfig({ domain: '', guild_id: '', role_id: '' });
      setShowAddConfig(false);
      fetchData();
    } catch (e: any) {
      addToast(e.message || 'Failed to add override config.', 'error');
    } finally {
      setIsSavingDomain(false);
    }
  };

  const handleDeleteDomainConfig = async (domain: string) => {
    const isConfirmed = await confirm({
      title: 'Remove Configuration Override',
      message: `Are you sure you want to remove the domain config override for "${domain}"?`
    });
    if (!isConfirmed) return;

    try {
      await apiRequest(`/api/admin/domain-configs?domain=${encodeURIComponent(domain)}`, {
        method: 'DELETE'
      });
      addToast('Domain configuration override removed.', 'success');
      fetchData();
    } catch (e: any) {
      addToast(e.message || 'Failed to delete config override.', 'error');
    }
  };

  const handleUpdateDomainConfig = async (domain: string) => {
    const fields = editDomainFields;
    if (!fields.guild_id || !fields.role_id) {
      addToast('Please fill in all configuration fields.', 'error');
      return;
    }
    try {
      await apiRequest('/api/admin/domain-configs', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          domain,
          guild_id: fields.guild_id,
          role_id: fields.role_id
        })
      });
      addToast('Domain configuration override updated.', 'success');
      setEditingDomainConfig(null);
      fetchData();
    } catch (e: any) {
      addToast(e.message || 'Failed to update domain configuration.', 'error');
    }
  };

  const handleAddMapping = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newMapping.domain || !newMapping.discord_role_id || !newMapping.system_role) {
      addToast('Please fill in all mapping fields.', 'error');
      return;
    }
    try {
      await apiRequest('/api/admin/domain-role-mappings', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(newMapping)
      });
      addToast('Role mapping added.', 'success');
      setNewMapping({ domain: '', discord_role_id: '', system_role: 'mod' });
      fetchData();
    } catch (e: any) {
      addToast(e.message || 'Failed to add role mapping.', 'error');
    }
  };

  const handleDeleteMapping = async (id: string) => {
    const isConfirmed = await confirm({
      title: 'Delete Role Mapping',
      message: 'Are you sure you want to remove this domain-specific role mapping?'
    });
    if (!isConfirmed) return;
    try {
      await apiRequest(`/api/admin/domain-role-mappings?id=${id}`, {
        method: 'DELETE'
      });
      addToast('Role mapping removed.', 'success');
      fetchData();
    } catch (e: any) {
      addToast(e.message || 'Failed to delete role mapping.', 'error');
    }
  };

  const handleVerifyDomainOverrides = async () => {
    if (!isOwner) {
      addToast('Domain override verification is restricted to Owner.', 'error');
      return;
    }
    setIsVerifyingDomains(true);
    setVerifyResults(null);
    addToast('Verifying domain overrides and applying role assignments...', 'info');
    try {
      const data = await apiRequest('/api/admin/users/verify-domain-overrides', { method: 'POST' });
      if (data.success) {
        setVerifyResults(data.results || []);
        const totalAssigned = (data.results || []).reduce((sum: number, r: any) => sum + (r.assigned || 0), 0);
        addToast(`Verification complete! ${totalAssigned} role assignment(s) applied.`, 'success');
      } else {
        addToast(data.error || 'Verification failed.', 'error');
      }
    } catch (e: any) {
      addToast(e.message || 'Failed to verify domain overrides.', 'error');
    } finally {
      setIsVerifyingDomains(false);
    }
  };

  if (loading) {
    return <div className="text-xs text-[#949BA4] animate-pulse">Loading access control components...</div>;
  }

  const allPermissionKeys = PERMISSION_GROUPS.flatMap(g => g.actions.map(a => a.key));
  const permissionSummary = (['mod', 'admin', 'owner'] as const).reduce((acc: Record<string, { write: number; read: number; none: number }>, role) => {
    const counts = { write: 0, read: 0, none: 0 };
    for (const key of allPermissionKeys) {
      const val = rolePermissions[role]?.[key] || 'none';
      counts[val === 'write' ? 'write' : val === 'read' ? 'read' : 'none']++;
    }
    acc[role] = counts;
    return acc;
  }, {});

  return (
    <div className="bg-[#313338] p-6 rounded-xl border border-[#2B2D31] shadow-sm space-y-6 md:col-span-2">
      {/* Panel Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between pb-4 border-b border-white/5 gap-4">
        <div className="flex items-center space-x-3">
          <div className="p-2 bg-purple-500/10 rounded-lg text-purple-400">
            <Icons.Shield size={20} />
          </div>
          <div>
            <h3 className="text-lg font-bold text-white">Access & Authorization Manager</h3>
            <p className="text-xs text-[#949BA4] font-medium">Unified management for system roles, permissions, server mappings, and active domain configurations.</p>
          </div>
        </div>

        {/* Tab Selector Toggle Buttons */}
        <div className="flex bg-[#1E1F22] p-1 rounded-lg border border-white/5 self-start sm:self-center shrink-0">
          <button
            onClick={() => setActiveTab('mappings')}
            className={`px-3 py-1.5 rounded-md text-xs font-bold transition-all uppercase tracking-wider ${
              activeTab === 'mappings' ? 'bg-[#5865F2] text-white' : 'text-[#949BA4] hover:text-white'
            }`}
          >
            Role Mappings
          </button>
          <button
            onClick={() => setActiveTab('permissions')}
            className={`px-3 py-1.5 rounded-md text-xs font-bold transition-all uppercase tracking-wider ${
              activeTab === 'permissions' ? 'bg-[#5865F2] text-white' : 'text-[#949BA4] hover:text-white'
            }`}
          >
            Permissions Map
          </button>
          <button
            onClick={() => setActiveTab('domains')}
            className={`px-3 py-1.5 rounded-md text-xs font-bold transition-all uppercase tracking-wider ${
              activeTab === 'domains' ? 'bg-[#5865F2] text-white' : 'text-[#949BA4] hover:text-white'
            }`}
          >
            Domain Overrides
          </button>
          <button
            onClick={() => setActiveTab('owners')}
            className={`px-3 py-1.5 rounded-md text-xs font-bold transition-all uppercase tracking-wider ${
              activeTab === 'owners' ? 'bg-[#5865F2] text-white' : 'text-[#949BA4] hover:text-white'
            }`}
          >
            Owners
          </button>
        </div>
      </div>

      {/* Tabs Container */}
      <div className="overflow-visible min-h-[300px]">

        {/* TAB 1: ROLE MAPPINGS & CREATION */}
        {activeTab === 'mappings' && (
          <div className="space-y-4 animate-in fade-in duration-200 overflow-visible">
            {isOwner && (
              <form onSubmit={handleCreateRole} className="flex flex-col sm:flex-row gap-2 border-b border-white/5 pb-4 overflow-visible">
                <div className="flex-1">
                  <input 
                    type="text"
                    value={newRoleForm.name}
                    onChange={e => setNewRoleForm({ ...newRoleForm, name: e.target.value.toLowerCase() })}
                    placeholder="New Role Name (e.g. coach, helper)"
                    className="w-full bg-[#2B2D31] text-white placeholder-[#949BA4] text-xs border border-[#35373C] rounded-lg p-2 outline-none focus:border-purple-500"
                  />
                </div>
                <div className="w-full sm:w-64 overflow-visible">
                  <SearchableSelect 
                    options={primaryGuildRoles}
                    value={newRoleForm.discord_role_id}
                    onChange={val => setNewRoleForm({ ...newRoleForm, discord_role_id: val })}
                    placeholder="Linked Discord Role"
                    className="w-full text-xs"
                  />
                </div>
                <button 
                  type="submit" 
                  className="px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white font-medium rounded-lg text-xs transition-colors shrink-0 flex items-center space-x-1.5"
                >
                  <Icons.Plus size={14} />
                  <span>Create Role</span>
                </button>
              </form>
            )}

            <div className="space-y-2 overflow-visible">
              {rolesList.map(role => {
                const isEditing = editingRoleName === role.name;
                const discordRoleName = primaryGuildRoles.find(r => r.value === role.discord_role_id)?.label || role.discord_role_id || 'Not Linked';
                return (
                  <div key={role.name} className="flex flex-col sm:flex-row sm:items-center justify-between p-3 bg-[#1E1F22] rounded-lg border border-[#2B2D31] text-xs text-white gap-2 overflow-visible">
                    {isEditing ? (
                      <div className="flex flex-1 flex-col sm:flex-row items-stretch sm:items-center gap-2 w-full overflow-visible">
                        <span className="font-bold uppercase text-primary shrink-0 self-center">
                          {role.name === 'mod' ? 'Coach' : role.name === 'admin' ? 'Admin' : role.name === 'owner' ? 'Owner' : role.name === 'user' ? 'Player' : role.name}
                        </span>
                        <div className="flex-1 min-w-[200px] overflow-visible">
                          <SearchableSelect 
                            options={primaryGuildRoles}
                            value={editingDiscordRoleId}
                            onChange={setEditingDiscordRoleId}
                            placeholder="Linked Discord Role"
                            className="w-full text-xs"
                          />
                        </div>
                        <div className="flex items-center space-x-2 shrink-0 self-end sm:self-center">
                          <button
                            type="button"
                            onClick={() => handleUpdateRoleMapping(role.name)}
                            className="p-1.5 bg-green-600 hover:bg-green-700 text-white rounded transition-colors"
                            title="Save Changes"
                          >
                            <Icons.Check size={12} />
                          </button>
                          <button
                            type="button"
                            onClick={() => setEditingRoleName(null)}
                            className="p-1.5 bg-white/10 hover:bg-white/20 text-[#DBDEE1] rounded transition-colors"
                          >
                            <Icons.Plus className="rotate-45" size={12} />
                          </button>
                        </div>
                      </div>
                    ) : (
                      <>
                        <div className="min-w-0 flex-1">
                          <span className="font-bold uppercase text-primary mr-2">
                            {role.name === 'mod' ? 'Coach' : role.name === 'admin' ? 'Admin' : role.name === 'owner' ? 'Owner' : role.name === 'user' ? 'Player' : role.name}
                          </span>
                          <span className="text-xs text-[#949BA4]">Linked Discord Role: <span className="text-purple-400 font-semibold">{discordRoleName}</span></span>
                        </div>
                        {isOwner && (
                          <div className="flex items-center space-x-2 shrink-0">
                            <button
                              type="button"
                              onClick={() => {
                                setEditingRoleName(role.name);
                                setEditingDiscordRoleId(role.discord_role_id || '');
                              }}
                              className="text-blue-400 hover:text-blue-300 transition-colors p-1"
                              title="Edit Mapping"
                            >
                              <Icons.Settings size={14} />
                            </button>
                            {role.is_custom && (
                              <button
                                type="button"
                                onClick={() => handleDeleteRole(role.name)}
                                className="text-red-400 hover:text-red-300 transition-colors p-1"
                                title="Delete Custom Role"
                              >
                                <Icons.Trash2 size={14} />
                              </button>
                            )}
                          </div>
                        )}
                      </>
                    )}
                  </div>
                );
              })}
            </div>
          </div>
        )}

        {/* TAB 2: GRANULAR ACTION PERMISSIONS */}
        {activeTab === 'permissions' && (
          <div className="space-y-4 animate-in fade-in duration-200">
            <div className="overflow-x-auto bg-[#1E1F22] rounded-xl border border-[#2B2D31] p-4">
              <table className="w-full text-left text-sm">
                <thead>
                  <tr>
                    <th rowSpan={2} className="font-bold uppercase tracking-wider border-b border-white/10 pb-1 pr-2 w-28">
                      Role
                    </th>
                    {PERMISSION_GROUPS.map(group => (
                      <th key={group.label} colSpan={group.actions.length} className="font-bold uppercase tracking-wider text-center border-b border-white/10 pb-1 border-l-2 border-[#35373C]">
                        <span className="text-purple-400">{group.label}</span>
                      </th>
                    ))}
                  </tr>
                  <tr>
                    {PERMISSION_GROUPS.map(group => group.actions.map(action => (
                      <th key={action.key} className="font-bold uppercase text-center border-b border-white/10 pb-1 text-[#949BA4] border-l-2 border-[#35373C]">
                        {action.label}
                      </th>
                    )))}
                  </tr>
                </thead>
                <tbody className="divide-y divide-white/5">
                  {['mod', 'admin', 'owner'].map(role => (
                    <tr key={role} className="text-white">
                      <td className="py-3 font-semibold uppercase text-primary">
                        <div className="flex flex-col">
                          <span>{role === 'mod' ? 'Coach' : role === 'admin' ? 'Admin' : 'Owner'}</span>
                          <span className={`text-[11px] font-bold mt-0.5 uppercase tracking-wider ${permissionSummary[role]?.write > 0 ? 'text-emerald-400' : 'text-[#949BA4]'}`}>
                            {permissionSummary[role]?.write || 0} write · {permissionSummary[role]?.read || 0} read · {permissionSummary[role]?.none || 0} none
                          </span>
                        </div>
                      </td>
                      {PERMISSION_GROUPS.flatMap(group => group.actions.map(action => (
                        <td key={action.key} className="py-3 text-center border-l-2 border-[#35373C]">
                          <SegmentedPermissionPill
                            value={rolePermissions[role]?.[action.key] || 'none'}
                            disabled={role === 'owner' || !isOwner}
                            allowRead={action.key !== 'fields'}
                            onChange={val => {
                              setRolePermissions({
                                ...rolePermissions,
                                [role]: {
                                  ...rolePermissions[role],
                                  [action.key]: val
                                }
                              });
                            }}
                          />
                        </td>
                      )))}
                    </tr>
                  ))}
                </tbody>
              </table>
              <div className="flex items-center justify-between mt-3 border-t border-white/5 pt-2">
