import { useState, useEffect } from 'react';
import * as Icons from '../Icons';
import { useToast } from '../../contexts/ToastContext';

interface Presence {
  status: string;
  activity_name: string;
  activity_type: number;
}

interface BotPresenceManagerProps {
  apiRequest: any;
  hasPermission: boolean;
}

export default function BotPresenceManager({ apiRequest, hasPermission }: BotPresenceManagerProps) {
  const { addToast } = useToast();
  const [presence, setPresence] = useState<Presence>({
    status: 'online',
    activity_name: 'GloBot Stable',
    activity_type: 0
  });
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    async function loadPresence() {
      try {
        const data = await apiRequest('/api/admin/presence');
        if (data) {
          setPresence({
            status: data.status || 'online',
            activity_name: data.activity_name || '',
            activity_type: data.activity_type || 0
          });
        }
      } catch (err) {
        console.warn('Failed to load bot presence:', err);
      } finally {
        setLoading(false);
      }
    }
    loadPresence();
  }, [apiRequest]);

  const handleUpdatePresence = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!hasPermission) return;
    try {
      await apiRequest('/api/admin/presence', {
        method: 'POST',
        body: JSON.stringify(presence)
      });
      addToast('Bot presence status updated successfully!', 'success');
    } catch (err) {
      addToast('Failed to update bot presence status', 'error');
    }
  };

  if (loading) {
    return <div className="text-xs text-[#949BA4] animate-pulse">Loading status controls...</div>;
  }

  return (
    <form onSubmit={handleUpdatePresence} className="space-y-4">
      <div className="grid grid-cols-2 gap-4">
        <div>
          <label className="block text-sm font-medium text-[#949BA4] mb-1">Status</label>
          <select 
            value={presence.status}
            onChange={(e) => setPresence({...presence, status: e.target.value})}
            disabled={!hasPermission}
            className="w-full bg-[#1E1F22] text-white border border-[#2B2D31] rounded-lg p-2 outline-none focus:border-[#5865F2] disabled:opacity-50 text-xs"
          >
            <option value="online">Online</option>
            <option value="idle">Idle</option>
            <option value="dnd">Do Not Disturb</option>
          </select>
        </div>
        <div>
          <label className="block text-sm font-medium text-[#949BA4] mb-1">Activity Type</label>
          <select 
            value={presence.activity_type}
            onChange={(e) => setPresence({...presence, activity_type: parseInt(e.target.value)})}
            disabled={!hasPermission}
            className="w-full bg-[#1E1F22] text-white border border-[#2B2D31] rounded-lg p-2 outline-none focus:border-[#5865F2] disabled:opacity-50 text-xs"
          >
            <option value={0}>Playing</option>
            <option value={1}>Streaming</option>
            <option value={2}>Listening</option>
            <option value={3}>Watching</option>
            <option value={5}>Competing</option>
          </select>
        </div>
      </div>
      <div>
        <label className="block text-sm font-medium text-[#949BA4] mb-1">Activity Name</label>
        <input 
          type="text"
          value={presence.activity_name}
          onChange={(e) => setPresence({...presence, activity_name: e.target.value})}
          disabled={!hasPermission}
          className="w-full bg-[#1E1F22] text-white border border-[#2B2D31] rounded-lg p-2 outline-none focus:border-[#5865F2] disabled:opacity-50 text-xs"
          placeholder="e.g. GloBot"
        />
      </div>
      <button 
        type="submit" 
        disabled={!hasPermission}
        className="w-full py-2 bg-[#5865F2] hover:bg-[#4752C4] text-white font-medium rounded-lg transition-colors disabled:opacity-50 text-xs flex items-center justify-center space-x-1.5"
      >
        <Icons.RotateCw size={12} className="animate-pulse" />
        <span>Update Status</span>
      </button>
    </form>
  );
}

