export const SearchableSelect: React.FC<SearchableSelectProps> = ({
  options,
  value,
  onChange,
  placeholder = 'Select an option...',
  disabled = false,
  className = ''
}) => {
  const [isOpen, setIsOpen] = useState(false);
  const [search, setSearch] = useState('');
  const containerRef = useRef<HTMLDivElement>(null);

  const selectedOption = options.find(o => o.value === value);

  useEffect(() => {
    const handleOutsideClick = (e: MouseEvent) => {
      if (containerRef.current && !containerRef.current.contains(e.target as Node)) {
        setIsOpen(false);
      }
    };
    document.addEventListener('mousedown', handleOutsideClick);
    return () => document.removeEventListener('mousedown', handleOutsideClick);
  }, []);

  const filteredOptions = options.filter(o =>
    (o.label || '').toLowerCase().includes(search.toLowerCase())
  );

  return (
    <div ref={containerRef} className={`relative min-w-[160px] ${className}`}>
      <button
        type="button"
        disabled={disabled}
        onClick={() => {
          if (!disabled) {
            setIsOpen(!isOpen);
            setSearch('');
          }
        }}
        className="w-full flex items-center justify-between bg-[#1E1F22] text-white text-xs rounded-xl px-4 py-2 border border-white/5 focus:border-primary outline-none cursor-pointer disabled:opacity-50 disabled:cursor-not-allowed select-none"
      >
        <span className="truncate flex items-center space-x-2">
          {selectedOption?.iconUrl && (
            <img src={selectedOption.iconUrl} className="w-4 h-4 rounded-full object-cover shrink-0" onError={(e) => { (e.target as HTMLImageElement).style.display = 'none'; }} />
          )}
          {selectedOption?.platform && (
            <span className="shrink-0 flex items-center"><PlatformLogo platform={selectedOption.platform} size={12} /></span>
          )}
          <span className="truncate" style={{ color: '#ffffff' }}>{selectedOption ? selectedOption.label : placeholder}</span>
          {selectedOption?.badge && <BadgeChip badge={selectedOption.badge} />}
        </span>
        <Icons.ChevronDown size={14} className={`text-[#949BA4] transition-transform ${isOpen ? 'rotate-180' : ''}`} />
      </button>

      <AnimatePresence>
        {isOpen && (
          <motion.div
            initial={{ opacity: 0, y: 5 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: 5 }}
            transition={{ duration: 0.15 }}
            className="absolute z-[90] w-full mt-1 bg-[#1E1F22] border border-[#2B2D31] rounded-xl shadow-2xl overflow-hidden"
          >
            <div className="p-2 border-b border-[#2B2D31]">
              <div className="relative flex items-center">
                <input
                  type="text"
                  autoFocus
                  placeholder="Type to filter..."
                  value={search}
                  onChange={(e) => setSearch(e.target.value)}
                  className="w-full bg-[#313338] text-white text-[11px] rounded-lg pl-8 pr-3 py-1.5 border border-white/5 focus:border-primary outline-none" style={{ color: '#ffffff' }}
                />
                <Icons.Search size={12} className="absolute left-2.5 text-[#949BA4]" />
              </div>
            </div>
            <div className="max-h-60 overflow-y-auto custom-scrollbar p-1 space-y-0.5">
              {filteredOptions.length === 0 ? (
                <div className="p-3 text-center text-xs text-[#949BA4] italic">
                  No options found
                </div>
              ) : (
                filteredOptions.map((opt) => (
                  <button
                    key={String(opt.value)}
                    type="button"
                    onClick={() => {
                      onChange(opt.value);
                      setIsOpen(false);
                    }}
                    className={`w-full text-left px-3 py-2 rounded-lg text-xs font-medium transition-all flex items-center justify-between ${
                      opt.value === value
                        ? 'bg-[#5865F2] text-white'
                        : 'text-[#DBDEE1] hover:bg-[#35373C] hover:text-white'
                    }`}
                  >
                    <span className="flex items-center space-x-2 truncate">
                      {opt.iconUrl && (
                        <img src={opt.iconUrl} className="w-4 h-4 rounded-full object-cover shrink-0" onError={(e) => { (e.target as HTMLImageElement).style.display = 'none'; }} />
                      )}
                      <span className="truncate" style={{ color: opt.value === value ? '#ffffff' : '#DBDEE1' }}>{opt.label}</span>
                    </span>
                    {opt.platform && (
                      <span className="flex items-center space-x-1 shrink-0 ml-2 opacity-80 bg-black/20 px-1.5 py-0.5 rounded text-[10px] uppercase font-bold text-white/70">
                        <PlatformLogo platform={opt.platform} size={10} />
                        <span>{opt.platform}</span>
                      </span>
                    )}
                    {opt.badge && <BadgeChip badge={opt.badge} />}
                  </button>
                ))
              )}
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { User, Users as UsersIcon, Shield, ShieldCheck, Apple, Clock, Globe, Trash2, Settings, Monitor, MessageSquare, Zap, Loader2, Key, Activity, Download, Palette, Layers, Layout, PlusCircle, Check, CheckCircle2, HelpCircle, ChevronUp, ChevronDown, Menu, Smartphone, Lock, Fingerprint, QrCode, Droplets, MapPin, Compass, HardDrive, ShieldAlert } from 'lucide-react';
import { useData } from '../contexts/DataContext';
import { useAuth } from '../contexts/AuthContext';
