import { toast } from 'react-hot-toast';
import { toastConfirm } from './common';
import { startRegistration } from '@simplewebauthn/browser';
import { getPasskeyMetadata } from '../utils/passkey-metadata';
import { QRCodeSVG } from 'qrcode.react';

const parseUserAgent = (ua: string) => {
    if (!ua || ua === 'Unknown') return 'Unknown Device';

    const browser = 
        ua.includes('Firefox') ? 'Firefox' :
        ua.includes('Edg') ? 'Edge' :
        ua.includes('Chrome') ? 'Chrome' :
        ua.includes('Safari') ? 'Safari' :
        ua.includes('Opera') ? 'Opera' : 'Browser';

    const os = 
        ua.includes('Windows') ? 'Windows' :
        ua.includes('Macintosh') || ua.includes('Mac OS') ? 'macOS' :
        ua.includes('iPhone') || ua.includes('iPad') ? 'iOS' :
        ua.includes('Android') ? 'Android' :
        ua.includes('Linux') ? 'Linux' : 'OS';

    return `${browser} on ${os}`;
};

interface AccountSettingsProps {
    user: UserInfo | null;
    token: string | null;
    onClose: () => void;
}

type TabType = 'overview' | 'personalization' | 'workflows' | 'security' | 'regional' | 'history';

export const AccountSettings: React.FC<AccountSettingsProps> = ({ user, token, onClose }) => {
    const { userSettings, updateUserSettings } = useData();
    const refreshData = () => {};
    const { logout, refreshUser: refreshAuth } = useAuth();

    const [activeTab, setActiveTab] = useState<TabType>('overview');

    // States for various actions and listings
    const [sessions, setSessions] = useState<any[]>([]);
    const [auditLogs, setAuditLogs] = useState<any[]>([]);
    const [passkeys, setPasskeys] = useState<any[]>([]);
    const [isLoadingSessions, setIsLoadingSessions] = useState(false);
    const [isLoadingLogs, setIsLoadingLogs] = useState(false);
    const [isLoadingPasskeys, setIsLoadingPasskeys] = useState(false);
    const [isExporting, setIsExporting] = useState(false);
    const [isTestingDM, setIsTestingDM] = useState(false);
    const [isSaving, setIsSaving] = useState(false);

    const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);
    const [isDeleting, setIsDeleting] = useState(false);
    const [showSessionLegend, setShowSessionLegend] = useState(false);

    // Passkey renaming
    const [editingPasskeyId, setEditingPasskeyId] = useState<string | null>(null);
    const [editPasskeyName, setEditPasskeyName] = useState('');

    // Regional
    const [timezone, setTimezone] = useState(user?.timezone || 'UTC');
    const [locale, setLocale] = useState(user?.locale || 'en-US');

    // System Status (Migrated from FloatingHeader)
    const [dmConnectivity, setDmConnectivity] = useState<'checking' | 'ok' | 'blocked' | 'error'>('checking');
    const [dmEnabled, setDmEnabled] = useState(false);

    const { botStatus, refreshStatus } = useData();

    useEffect(() => {
        if (token) {
            // Initial DM check
            checkDmStatus(true);

            // Get initial DM toggle state
            fetch('/api/me/onboarding', { headers: { 'Authorization': `Bearer ${token}` } })
                .then(res => res.json() as any)
                .then(data => {
                    if (data && typeof data.dmNotifications !== 'undefined') {
                        setDmEnabled(!!data.dmNotifications);
                    }
                })
                .catch(console.error);
        }
    }, [token]);

    const checkDmStatus = async (isSilent: boolean = false) => {
        if (!token) return;
        setDmConnectivity('checking');
        try {
            const res = await fetch('/api/me/dm-status', {
                method: 'POST',
                headers: {
                    'Authorization': `Bearer ${token}`,
                    'Content-Type': 'application/json'
                },
                body: JSON.stringify({ silent: isSilent })
            });
            const data = await res.json() as any;
            if (data.status) {
                setDmConnectivity(data.status);
                if (!isSilent) {
                    if (data.status === 'ok') toast.success("Messaging Status Verified!");
                    else if (data.status === 'blocked') toast.error("Bot is blocked or DMs are disabled.");
                    else toast.error("Unable to verify DM status.");
                }
            }
        } catch {
            setDmConnectivity('error');
        }
    };

    const toggleDm = async () => {
        if (!token) return;
        const newVal = !dmEnabled;
        setDmEnabled(newVal);
        try {
            await fetch('/api/me/profile', {
                method: 'PATCH',
                headers: { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json' },
                body: JSON.stringify({ dmNotifications: newVal })
            });
            toast.success(newVal ? 'DM Reply Alerts Enabled' : 'DM Reply Alerts Disabled');
            refreshAuth();
        } catch {
            toast.error('Failed to update preference');
            setDmEnabled(!newVal);
        }
    };

    useEffect(() => {
        if (token) {
            if (activeTab === 'security') {
                fetchSessions();
                fetchPasskeys();
            }
            if (activeTab === 'history') {
                fetchAuditLogs();
            }
        }
    }, [token, activeTab]);

    useEffect(() => {
        console.log("[AccountSettings] Mounted. User ID:", user?.id);
        return () => console.log("[AccountSettings] Unmounting...");
    }, []);

    const fetchSessions = async () => {
        setIsLoadingSessions(true);
        try {
            const res = await fetch('/api/me/sessions', { headers: { 'Authorization': `Bearer ${token}` } });
            if (res.ok) setSessions(await res.json() as any);
        } finally { setIsLoadingSessions(false); }
    };

    const fetchAuditLogs = async () => {
        setIsLoadingLogs(true);
        try {
            const res = await fetch('/api/me/audit-logs', { headers: { 'Authorization': `Bearer ${token}` } });
            if (res.ok) setAuditLogs(await res.json() as any);
        } finally { setIsLoadingLogs(false); }
    };

    const fetchPasskeys = async () => {
        setIsLoadingPasskeys(true);
        try {
            const res = await fetch('/api/auth/webauthn/passkeys', { headers: { 'Authorization': `Bearer ${token}` } });
            if (res.ok) {
                const data = await res.json() as any;
                setPasskeys(data.passkeys || data || []);
            }
        } catch (err) {
            console.error("Failed to fetch passkeys", err);
        } finally { 
            setIsLoadingPasskeys(false); 
        }
    };

    const handleRegisterPasskey = async () => {
        if (!token) return;
        try {
            const resp = await fetch('/api/auth/webauthn/generate-registration', {
                method: 'POST',
                headers: { 'Authorization': `Bearer ${token}` }
            });
            if (!resp.ok) throw new Error('Failed to get options');
            const options = await resp.json();

            const attestation = await startRegistration({ optionsJSON: options as any });

            const verifyResp = await fetch('/api/auth/webauthn/verify-registration', {
                method: 'POST',
                headers: { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json' },
                body: JSON.stringify({ attestation, name: 'Primary Device' })
            });

            if (verifyResp.ok) {
                toast.success('Passkey registered successfully');
                await fetchPasskeys();
                await refreshAuth();
            } else {
                toast.error('Passkey verification failed');
            }
        } catch (err) {
            console.error(err);
            toast.error('Passkey registration cancelled or failed');
        }
    };

    const handleRenamePasskey = async (id: string) => {
        if (!token) return;
        try {
            const res = await fetch(`/api/auth/webauthn/passkeys/${id}`, {
                method: 'PATCH',
                headers: { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json' },
                body: JSON.stringify({ name: editPasskeyName })
            });
            if (res.ok) {
                toast.success('Passkey renamed');
                setEditingPasskeyId(null);
                await fetchPasskeys();
                await refreshAuth();
            } else {
                toast.error('Failed to rename passkey');
            }
        } catch (err) {
            toast.error('Failed to rename passkey');
        }
    };

    const handleDeletePasskey = async (id: string) => {
        if (!token) return;
        if (!(await toastConfirm('Are you sure you want to remove this passkey?', { isDanger: true }))) return;

        try {
            const res = await fetch(`/api/auth/webauthn/passkeys/${id}`, {
                method: 'DELETE',
                headers: { 'Authorization': `Bearer ${token}` }
            });
            if (res.ok) {
                toast.success('Passkey removed');
                await fetchPasskeys();
                await refreshAuth();
            }
        } catch (err) {
            toast.error('Failed to remove passkey');
        }
    };

    const handleTestDM = async () => {
        if (!token) return;
        setIsTestingDM(true);
        try {
            const res = await fetch('/api/me/dm-status', {
                method: 'POST',
                headers: { 'Authorization': `Bearer ${token}` }
            });
            const data = await res.json() as any;
            if (data.status === 'ok') toast.success('Connectivity test successful!');
            else if (data.status === 'blocked') toast.error('You have blocked DMs from the bot.');
            else toast.error('Connectivity check failed');
        } finally { setIsTestingDM(false); }
    };

    const handleRevokeSession = async (hash: string) => {
        if (!token) return;
        try {
            const res = await fetch(`/api/me/sessions/${hash}`, {
                method: 'DELETE',
                headers: { 'Authorization': `Bearer ${token}` }
            });
            if (res.ok) {
                toast.success('Session revoked');
                fetchSessions();
            }
        } catch (err) { toast.error('Failed to revoke session'); }
    };

    const handleRevokeAllOtherSessions = async () => {
        if (!token) return;
        if (!(await toastConfirm('Are you sure you want to sign out of all other devices?', { isDanger: true }))) return;

        try {
            const res = await fetch('/api/me/sessions', {
                method: 'DELETE',
                headers: { 'Authorization': `Bearer ${token}` }
            });
            if (res.ok) {
                toast.success('All other sessions revoked');
                fetchSessions();
            }
        } catch (err) { toast.error('Failed to revoke sessions'); }
    };

    const handleExportData = async () => {
        if (!token) return;
        setIsExporting(true);
        try {
            const res = await fetch('/api/me/export', { headers: { 'Authorization': `Bearer ${token}` } });
            if (res.ok) {
                const blob = await res.blob();
                const url = window.URL.createObjectURL(blob);
                const a = document.createElement('a');
                a.href = url;
                a.download = `iam-export-${new Date().toISOString().slice(0, 10)}.json`;
                document.body.appendChild(a);
                a.click();
                window.URL.revokeObjectURL(url);
                toast.success('Data export started');
            }
        } finally { setIsExporting(false); }
    };

    const handleSaveRegional = async () => {
        if (!token) return;
        setIsSaving(true);
        try {
            const res = await fetch('/api/me/profile', {
                method: 'PATCH',
                headers: { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json' },
                body: JSON.stringify({ timezone, locale })
            });
            if (res.ok) {
                toast.success('Regional settings updated');
                await refreshAuth();
            } else toast.error('Failed to update regional settings');
        } finally { setIsSaving(false); }
    };

    const handleDeleteAccount = async () => {
        if (!token) return;
        setIsDeleting(true);
        try {
            const res = await fetch('/api/me/profile', {
                method: 'DELETE',
                headers: { 'Authorization': `Bearer ${token}` }
            });
            if (res.ok) {
                toast.success('All your data has been removed. Goodbye!');
                logout();
            } else toast.error('Failed to remove data');
        } finally { setIsDeleting(false); }
    };

    const toggleMenuItemView = (itemId: string) => {
        const currentConfig = userSettings.menuCustomization || [];
        const updated = currentConfig.map(item => item.id === itemId ? { ...item, visible: !item.visible } : item);
        updateUserSettings({ menuCustomization: updated });
    };

    const moveMenuItem = (itemId: string, direction: 'up' | 'down') => {
        const currentConfig = [...(userSettings.menuCustomization || [])];
        const index = currentConfig.findIndex(item => item.id === itemId);
        if (index === -1) return;

        if (direction === 'up' && index > 0) {
            [currentConfig[index], currentConfig[index - 1]] = [currentConfig[index - 1], currentConfig[index]];
        } else if (direction === 'down' && index < currentConfig.length - 1) {
            [currentConfig[index], currentConfig[index + 1]] = [currentConfig[index + 1], currentConfig[index]];
        }
        const reordered = currentConfig.map((item, i) => ({ ...item, order: i + 1 }));
        updateUserSettings({ menuCustomization: reordered });
    };

    if (!user) return null;

    const tabs: { id: TabType, label: string, icon: any }[] = [
        { id: 'overview', label: 'Overview', icon: User },
        { id: 'personalization', label: 'Personalization', icon: Palette },
        { id: 'workflows', label: 'Workflows', icon: Layers },
        { id: 'security', label: 'Security', icon: Shield },
        { id: 'regional', label: 'Regional', icon: Globe },
        { id: 'history', label: 'History', icon: Activity }
    ];

