                                                                    </div>
                                                                    <div style={{ display: 'flex', alignItems: 'center', gap: '6px' }}>
                                                                        <span style={{ fontSize: '0.7rem', padding: '2px 6px', background: 'rgba(255,255,255,0.05)', borderRadius: '4px', color: 'var(--accent)' }}>IPv6</span>
                                                                        <span style={{ fontSize: '0.8rem', color: '#fff', fontFamily: 'monospace' }}>{pk.lastUsedIpV6 || 'N/A'}</span>
                                                                    </div>
                                                                </div>
                                                            </div>

                                                            {/* Geographic Forensics */}
