                                        background: 'rgba(88, 101, 242, 0.03)', borderRadius: '16px', 
                                        border: '1px solid rgba(88, 101, 242, 0.1)',
                                        display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: '1.5rem'
