                                                                        background: session.isPersistent ? 'rgba(16, 185, 129, 0.1)' : 'rgba(245, 158, 11, 0.1)', 
                                                                        color: session.isPersistent ? '#10b981' : '#f59e0b',
                                                                        fontSize: '0.6rem', padding: '2px 8px', borderRadius: '4px', fontWeight: 800, textTransform: 'uppercase', border: `1px solid ${session.isPersistent ? 'rgba(16, 185, 129, 0.2)' : 'rgba(245, 158, 11, 0.2)'}`
