                                                                    <div style={{ width: '40px', height: '40px', borderRadius: '8px', background: 'rgba(255,255,255,0.03)', display: 'flex', alignItems: 'center', justifyContent: 'center', opacity: 0.6 }}>
                                                                        {session.os?.toLowerCase().includes('mac') || session.os?.toLowerCase().includes('ios') ? <Apple size={20} /> : <Monitor size={20} />}
