                                                                                fontSize: '0.55rem', padding: '1px 6px', borderRadius: '4px', fontWeight: 800, textTransform: 'uppercase', opacity: 0.8
                                                                            }}>
                                                                                {session.isPersistent ? 'P' : 'T'}
                                                                            </span>
