                                                                                    if (session.ipV6) ips.push({ label: 'IPv6', value: session.ipV6 });
                                                                                    if (ips.length === 0 && session.ipAddress) ips.push({ label: session.ipAddress.includes(':') ? 'IPv6' : 'IPv4', value: session.ipAddress });

                                                                                    return (ips || []).map((ip, idx) => (
                                                                                        <span key={idx}>{ip.label}: {ip.value}</span>
