                                                                <button className="btn-icon" onClick={() => handleRevokeSession(session.id)} style={{ alignSelf: 'center' }} title="Revoke Session">
                                                                    <Trash2 size={18} color="#ed4245" />
                                                                </button>
                                                            </div>
                                                        ))}
                                                    </div>
                                                </div>
                                            )}

                                            {sessions.length === 0 && (
                                                <p style={{ fontSize: '0.8rem', color: 'var(--text-muted)', textAlign: 'center', padding: '1rem' }}>No other active sessions found.</p>
                                            )}
                                        </div>
                                    )}
                                 </div>
                            </div>
                        </div>
                )}

                {activeTab === 'regional' && (
                    <div className="settings-tab-pane animate-fade-in">
                        <div className="settings-section-card">
                            <div className="section-header" style={{ display: 'flex', alignItems: 'center', gap: '0.75rem', marginBottom: '1.5rem' }}>
