const formatAuditAction = (action: string): string => {
    const mapping: Record<string, string> = {
        'ADMIN_STEP_UP_VERIFY': 'Passkey Step-Up Success',
        'TOGGLE_MAINTENANCE': 'Maintenance Mode Toggled',
        'ADMIN_SECURITY_WIPE_PASSKEYS': 'Security Wipe: Passkeys',
        'ADMIN_SECURITY_WIPE_SESSIONS': 'Security Wipe: Active Sessions',
        'CREATE_POST': 'New Post Created',
        'REVOKE_SESSION': 'Session Ended',
        'USER_LOGIN_SUCCESS': 'User Signed In',
        'USER_LOGOUT': 'User Signed Out',
        'UPDATE_SETTINGS': 'System Settings Updated',
        'DELETE_POST': 'Post Removed',
        'ADMIN_SECURITY_RESET_PASSWORD': 'Security Reset: Password',
        'AUDIT_LOG_EXPORT': 'Activity History Exported',
        'ADMIN_INVITE_SENT': 'Admin Invitation Sent',
        'ADMIN_PASSKEY_REGISTER': 'Security: Passkey Registered',
        'ADMIN_MERGE_USERS': 'Admin: Users Merged',
        'ADMIN_UPDATE_USER': 'Admin: User Updated',
        'ADMIN_UPDATE_USER_SETTINGS': 'Admin: User Settings Updated',
        'ADMIN_SECURITY_FORCE_PASSWORD_RESET': 'Security: Password Reset Forced',
        'UPDATE_REPORT': 'Incident Report Updated',
        'DELETE_REPORT': 'Incident Report Removed',
        'RESCAN_GUILD': 'Discord Server Rescanned',
        'UPDATE_POST': 'Post Updated',
        'DELETE_RESPONSE': 'Response Removed',
        'UPDATE_PRESENCE': 'System Presence Updated',
        'REVOKE_ALL_SESSIONS': 'Security: All Sessions Ended',
        'CREATE_CONTACT_GROUP': 'Contact Cluster Created',
        'UPDATE_CONTACT_STATUS': 'Contact Status Updated',
        'REGISTER_COMMANDS': 'Chat Commands Registered'
    };

    if (!action) return 'Unknown Action';
    if (mapping[action]) return mapping[action];

    // Fallback: Humanize snake_case
    try {
        return action
            .split('_')
            .map(word => word.charAt(0).toUpperCase() + (word.slice(1)?.toLowerCase() || ''))
            .join(' ');
    } catch (e) {
        return action || 'Unknown Action';
    }
};

