const MergeAccountModal: React.FC<{ 
    token: string, 
    sourceUser: User, 
    allUsers: User[], 
    onClose: () => void, 
    onMerged: () => void 
}> = ({ token, sourceUser, allUsers, onClose, onMerged }) => {
    const [targetId, setTargetId] = useState('');
    const [loading, setLoading] = useState(false);
    const [searchTerm, setSearchTerm] = useState('');

    const filteredUsers = allUsers.filter(u => 
        u.id !== sourceUser.id && 
        (u.username.toLowerCase().includes(searchTerm.toLowerCase()) || u.id.includes(searchTerm))
    );

    const handleMerge = async () => {
        if (!targetId) return;

        const targetUser = allUsers.find(u => u.id === targetId);
        if (!targetUser) return;

        if (!await toastConfirm(`Are you absolutely sure you want to merge ${sourceUser.username} into ${targetUser.username}?\n\nThis will DELETE ${sourceUser.username} and transfer all their data to ${targetUser.username}. This cannot be undone.`, { isDanger: true, title: 'Confirm User Merge' })) {
            return;
        }

        setLoading(true);
        try {
            const res = await fetch('/api/admin/users/merge', {
                method: 'POST',
                headers: { 
                    'Authorization': `Bearer ${token}`,
                    'Content-Type': 'application/json'
                },
                body: JSON.stringify({ sourceId: sourceUser.id, targetId })
            });
            const data = await res.json() as any as any;
            if (res.ok) {
                toast.success(data.message || "Accounts merged successfully!");
                onMerged();
            } else {
                toast.error(data.error || "Failed to merge accounts");
            }
        } catch (err) {
            toast.error("Network error during merge");
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="onboarding-overlay" style={{
            position: 'fixed', inset: 0, backgroundColor: 'rgba(0,0,0,0.85)',
            backdropFilter: 'blur(4px)', zIndex: 9999, display: 'flex',
            alignItems: 'center', justifyContent: 'center', padding: '1rem'
        }}>
            <div className="onboarding-modal" style={{
                background: '#1e1f22', borderRadius: '12px', padding: '2rem',
                maxWidth: '500px', width: '100%', position: 'relative',
                boxShadow: '0 10px 30px rgba(0,0,0,0.5)', border: '1px solid #ed4245'
            }}>
                <button onClick={onClose} style={{ position: 'absolute', top: '1rem', right: '1rem', background: 'transparent', border: 'none', color: '#949ba4', cursor: 'pointer' }}>
                    <X size={24} />
                </button>

                <div style={{ textAlign: 'center', marginBottom: '1.5rem' }}>
                    <AlertCircle size={48} color="#ed4245" style={{ marginBottom: '1rem' }} />
                    <h2 style={{ margin: 0, color: '#f2f3f5' }}>Merge Accounts</h2>
                    <p style={{ color: '#949ba4', fontSize: '0.9rem', marginTop: '0.5rem' }}>
                        Consolidate <strong>{sourceUser.username}</strong> into a target account.
                    </p>
                </div>

                <div style={{ background: 'rgba(237, 66, 69, 0.1)', border: '1px solid rgba(237, 66, 69, 0.3)', padding: '1rem', borderRadius: '8px', marginBottom: '1.5rem' }}>
                    <p style={{ color: '#f2f3f5', fontSize: '0.85rem', margin: 0 }}>
                        <strong>Warning:</strong> The source account will be deleted. All posts, logs, and identities will be transferred to the target. All active sessions will be invalidated.
                    </p>
                </div>

                <div style={{ marginBottom: '1.5rem' }}>
                    <label style={{ display: 'block', color: '#b5bac1', fontSize: '0.75rem', textTransform: 'uppercase', fontWeight: 700, marginBottom: '0.5rem' }}>
                        Search Target User
                    </label>
                    <input 
                        type="text" 
                        placeholder="Username or ID..."
                        value={searchTerm}
                        onChange={(e) => setSearchTerm(e.target.value)}
                        style={{ width: '100%', background: '#1e1f22', border: '1px solid #313338', color: 'white', padding: '0.75rem', borderRadius: '4px', marginBottom: '0.5rem' }}
                    />
                    <div style={{ maxHeight: '150px', overflowY: 'auto', background: '#2b2d31', borderRadius: '4px', border: '1px solid #313338', textAlign: 'left' }}>
                        {filteredUsers.length === 0 && <div style={{ padding: '1rem', color: '#949ba4', fontSize: '0.85rem' }}>No other users found...</div>}
                        {filteredUsers.map(u => (
                            <div 
                                key={u.id} 
                                onClick={() => setTargetId(u.id)}
                                style={{ 
                                    padding: '0.75rem', 
                                    display: 'flex', 
                                    alignItems: 'center', 
                                    gap: '0.75rem', 
                                    cursor: 'pointer',
                                    background: targetId === u.id ? 'rgba(88, 101, 242, 0.2)' : 'transparent',
                                    borderBottom: '1px solid #313338'
                                }}
                            >
                                <img src={`https://cdn.discordapp.com/avatars/${u.id}/${u.avatar}.png`} alt="" style={{ width: '24px', height: '24px', borderRadius: '50%' }} />
                                <div style={{ fontSize: '0.85rem', color: '#f2f3f5' }}>{u.username} <span style={{ opacity: 0.5, fontSize: '0.7rem' }}>({u.id})</span></div>
                            </div>
                        ))}
                    </div>
                </div>

                <div style={{ display: 'flex', gap: '1rem' }}>
                    <button 
                        onClick={onClose} 
                        className="btn-secondary" 
                        style={{ flex: 1, padding: '0.75rem' }}
                    >
                        Cancel
                    </button>
                    <button 
                        onClick={handleMerge} 
                        disabled={!targetId || loading}
                        className="btn-hero-danger" 
                        style={{ flex: 1, padding: '0.75rem', opacity: (!targetId || loading) ? 0.5 : 1 }}
                    >
                        {loading ? <RefreshCw className="spin" size={18} /> : "Finalize Merge"}
                    </button>
                </div>
            </div>
        </div>
    );
};


export const AdminPanel: React.FC<AdminPanelProps> = ({ token, user, guilds, channels, selectedGuild, initialTab }) => {
    const [activeTab, setActiveTab] = useState<'users' | 'logs' | 'settings' | 'presence' | 'reports' | 'contacts' | 'moderation' | 'groups'>(() => {
        if (typeof window === 'undefined') return 'users';
        return (localStorage.getItem('adminTab') as any) || 'users';
    });
    const [inspectingUser, setInspectingUser] = useState<User | null>(null);
    const [mergingUser, setMergingUser] = useState<User | null>(null);
    const [previewPostData, setPreviewPostData] = useState<any>(null);
    const [fetchingPostId, setFetchingPostId] = useState<number | null>(null);
    const { userSettings, updateUserSettings, refreshData } = useData();
    const [refreshingServer, setRefreshingServer] = useState(false);

    const [users, setUsers] = useState<User[]>([]);
    const [logs, setLogs] = useState<AuditLog[]>([]);
    const [reports, setReports] = useState<TroubleshootingReport[]>([]);
    const [adminContacts, setAdminContacts] = useState<any[]>([]);
    const [platformSettings, setPlatformSettings] = useState({
        defaultGuildId: '',
        defaultChannelId: '',
        defaultWebhookUrl: '',
        giphyApiKey: '',
        timezone: 'UTC',
        ogTitle: '',
        ogDescription: '',
        ogImageUrl: '',
        ogShareText: 'Check out this post on {{appName}}!',
        testModeChannelId: '',
        maintenanceMode: 'false',
        scheduledPostNotice: ''
    });
    const [systemStats, setSystemStats] = useState<{ totalPosts: number, sentPosts: number, totalGuilds: number } | null>(null);
    const [savingSettings, setSavingSettings] = useState(false);
    const [registeringCommands, setRegisteringCommands] = useState(false);
    const [storageStats, setStorageStats] = useState<any>(null);
    const [platformTab, setPlatformTab] = useState<'general' | 'seo' | 'integrations' | 'ux'>('general');
    const [lastFocusedOgField, setLastFocusedOgField] = useState<'ogTitle' | 'ogDescription' | 'ogImageUrl' | 'ogShareText' | 'scheduledPostNotice' | null>(null);

    const ogTitleRef = useRef<HTMLInputElement>(null);
    const ogDescriptionRef = useRef<HTMLTextAreaElement>(null);
    const ogImageUrlRef = useRef<HTMLInputElement>(null);
    const ogShareTextRef = useRef<HTMLInputElement>(null);
    const scheduledPostNoticeRef = useRef<HTMLTextAreaElement>(null);

    const handleInsertVariable = (tag: string) => {
        if (!lastFocusedOgField) {
            toast.error("Click an input field first to choose where to insert");
            return;
        }

        const fieldMap = {
            ogTitle: ogTitleRef,
            ogDescription: ogDescriptionRef,
            ogImageUrl: ogImageUrlRef,
            ogShareText: ogShareTextRef,
            scheduledPostNotice: scheduledPostNoticeRef
        };

        const ref = fieldMap[lastFocusedOgField];
        if (!ref.current) return;

        const input = ref.current;
        const start = input.selectionStart || 0;
        const end = input.selectionEnd || 0;
        const value = platformSettings[lastFocusedOgField] || '';

        const newValue = value.substring(0, start) + tag + value.substring(end);

        setPlatformSettings(prev => ({
            ...prev,
            [lastFocusedOgField]: newValue
        }));

        // Focus and set cursor after state update
        setTimeout(() => {
            if (ref.current) {
                ref.current.focus();
                const newPos = start + tag.length;
                ref.current.setSelectionRange(newPos, newPos);
            }
        }, 10);
    };

    const resolveOgTemplate = (text: string, type: 'title' | 'description' | 'image' = 'title') => {
        if (!text) return '';

        // Sample data for preview representation
        const sampleData: Record<string, string> = {
            appName: "I AM",
            appDescription: "Your daily spiritual companion. Discover timeless wisdom, engage with your faith, and grow within your community.",
            greeting: "Morning Grace",
            contents: "Today's meditation is on the power of stillness and the peace that surpasses understanding. Join us in this daily reflection...",
            attachments: '/brand/social-header.png',
            username: "Devon",
            postUrl: "https://i-am.gpnet.dev/posts/sample-slug",
            postId: "post_12345",
            bibleRef: "Psalm 23:1",
            timeStr: "Tuesday, May 12 at 09:00 AM"
        };

        const resolved = text.replace(/{{(\w+)}}/g, (match, key) => {
            return sampleData[key] || match;
        });

        if (type === 'image' && text === '{{attachments}}') {
            return sampleData.attachments;
        }

        return resolved;
    };


    const applyOgPresets = () => {
        setPlatformSettings(prev => ({
            ...prev,
            ogTitle: '{{greeting}} | I AM',
            ogDescription: '{{contents}}',
            ogImageUrl: '{{attachments}}',
            ogShareText: 'Check out this post on {{appName}}!'
        }));
        toast("Dynamic presets applied! Check the preview.");
    };

    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);
    const { isStepUpRequired } = useAuth();
    const prevStepUpRequired = useRef(isStepUpRequired);

    useEffect(() => {
        // Automatically retry fetch if step-up was just cleared
        if (prevStepUpRequired.current && !isStepUpRequired && error && error.includes('Security verification required')) {
            fetchData();
        }
        prevStepUpRequired.current = isStepUpRequired;
    }, [isStepUpRequired, error]);

    const getChannelDisplayValue = (id?: string) => {
        if (!id) return '';
        const channel = channels.find(c => c.id === id);
        return channel ? `${channel.name} (${id})` : id;
    };

    const fetchData = async () => {
        setLoading(true);
        setError(null);
        try {
            let endpoint = '/api/admin/users';
            if (activeTab === 'logs') endpoint = '/api/admin/audit-logs';
            else if (activeTab === 'settings') endpoint = '/api/admin/settings';
            else if (activeTab === 'reports') endpoint = '/api/admin/reports';
            else if (activeTab === 'contacts') endpoint = '/api/admin/contacts';

            const res = await fetch(endpoint, {
                headers: { 'Authorization': `Bearer ${token}` }
            });
            if (!res.ok) throw new Error('Failed to fetch data');
            const data = await res.json() as any;

            if (activeTab === 'users') {
                const processedUsers = (data || []).map((u: any) => ({
                    ...u,
                    userSettings: typeof u.userSettings === 'string' ? JSON.parse(u.userSettings) : u.userSettings
                }));
                setUsers(processedUsers);
            }
            else if (activeTab === 'logs') setLogs(data);
            else if (activeTab === 'reports') setReports(data);
            else if (activeTab === 'contacts') setAdminContacts(data);
            else if (activeTab === 'settings') {
                setPlatformSettings(prev => ({
                    ...prev,
                    ...data,
                    ogImageUrl: data.ogImageUrl || '/brand/social-header.png',
                    maintenanceMode: data.maintenanceMode || 'false'
                }));

                // Fetch expanded system intelligence
                const [storageRes, systemRes] = await Promise.all([
                    fetch('/api/admin/storage/stats', { headers: { 'Authorization': `Bearer ${token}` } }),
                    fetch('/api/stats/system', { headers: { 'Authorization': `Bearer ${token}` } })
                ]);

                if (storageRes.ok) setStorageStats(await storageRes.json());
                if (systemRes.ok) setSystemStats(await systemRes.json());
            }
        } catch (err: any) {
            if (isStepUpRequired) {
                setError('Security verification required. Please complete the passkey prompt to continue.');
            } else {
                setError(err.message);
            }
        } finally {
            setLoading(false);
        }
    };

    const toggleContactStatus = async (contactId: number, currentStatus: string) => {
        const newStatus = currentStatus === 'APPROVED' ? 'PENDING' : 'APPROVED';
        try {
            const res = await fetch(`/api/admin/contacts/${contactId}/status`, {
                method: 'POST',
                headers: {
                    'Authorization': `Bearer ${token}`,
                    'Content-Type': 'application/json'
                },
                body: JSON.stringify({ status: newStatus })
            });
            if (res.ok) {
                setAdminContacts(adminContacts?.map(c => c.id === contactId ? { ...c, status: newStatus } : c));
                toast.success(`Contact status set to ${newStatus}`);
            }
        } catch {
            toast.error("Failed to update status");
        }
    };

    const toggleUserSimpleMode = async (targetUser: User) => {
        if (user?.role !== 'OWNER') {
            toast.error("Only Owners can manage user UX modes.");
            return;
        }

        const currentSettings = targetUser.userSettings || {
            fontSize: 16,
            reducedMotion: false,
            highContrast: false,
            simpleMode: false,
            features: { bible: true, media: true, riddles: true, auditLogs: true, help: true, guidedSteps: true }
        };

        const newSettings = {
            ...currentSettings,
            simpleMode: !currentSettings.simpleMode,
            // When enabling simple mode, we also apply the defaults
            ...( (!currentSettings.simpleMode) ? { fontSize: 20, features: { ...currentSettings.features, help: true, guidedSteps: true } } : {} )
        };

        try {
            const res = await fetch(`/api/admin/users/${targetUser.id}/settings`, {
                method: 'POST',
                headers: {
                    'Authorization': `Bearer ${token}`,
                    'Content-Type': 'application/json'
                },
                body: JSON.stringify({ userSettings: newSettings })
            });

            if (res.ok) {
                toast.success(`Simple Mode ${newSettings.simpleMode ? 'enabled' : 'disabled'} for ${targetUser.username}`);
                fetchData(); // Refresh list
            } else {
                const err = await res.json() as any;
                throw new Error(err.error || 'Failed to update settings');
            }
        } catch (err: any) {
            toast.error(err.message);
        }
    };

    const toggleSmsFeature = async (targetUser: User) => {
        if (user?.role !== 'OWNER') {
            toast.error("Only Owners can manage SMS feature access.");
            return;
        }

        const newValue = !targetUser.smsFeatureEnabled;
        try {
            const res = await fetch(`/api/admin/users/${targetUser.id}`, {
                method: 'PATCH',
                headers: {
                    'Authorization': `Bearer ${token}`,
                    'Content-Type': 'application/json'
                },
                body: JSON.stringify({ smsFeatureEnabled: newValue })
            });

            if (res.ok) {
                toast.success(`SMS tools ${newValue ? 'enabled' : 'disabled'} for ${targetUser.username}`);
                setUsers(users?.map(u => u.id === targetUser.id ? { ...u, smsFeatureEnabled: newValue } : u));
            } else {
                const data = await res.json() as any;
                throw new Error(data.error || 'Failed to update SMS feature status');
            }
        } catch (err: any) {
            toast.error(err.message);
        }
    };

    useEffect(() => {
        fetchData();
    }, [activeTab]);

    const handleRoleChange = async (userId: string, newRole: string) => {
        try {
            const res = await fetch(`/api/admin/users/${userId}`, {
                method: 'PATCH',
                headers: {
                    'Authorization': `Bearer ${token}`,
                    'Content-Type': 'application/json'
                },
                body: JSON.stringify({ role: newRole })
            });
            if (res.ok) {
                setUsers(users?.map(u => u.id === userId ? { ...u, role: newRole } : u));
                fetchData(); // Refresh logs
            }
        } catch (err) {
            toast.error('Failed to update role');
        }
    };

    const handleSaveSettings = async () => {
        setSavingSettings(true);
        try {
            const payload = [
                { key: 'defaultGuildId', value: platformSettings.defaultGuildId },
                { key: 'defaultChannelId', value: platformSettings.defaultChannelId },
                { key: 'defaultWebhookUrl', value: platformSettings.defaultWebhookUrl },
                { key: 'giphyApiKey', value: platformSettings.giphyApiKey },
                { key: 'timezone', value: platformSettings.timezone },
                { key: 'ogTitle', value: platformSettings.ogTitle },
                { key: 'ogDescription', value: platformSettings.ogDescription },
                { key: 'ogImageUrl', value: platformSettings.ogImageUrl },
                { key: 'ogShareText', value: platformSettings.ogShareText },
                { key: 'testModeChannelId', value: platformSettings.testModeChannelId },
                { key: 'scheduledPostNotice', value: platformSettings.scheduledPostNotice }
            ];
            const res = await fetch('/api/admin/settings', {
                method: 'POST',
                headers: {
                    'Authorization': `Bearer ${token}`,
                    'Content-Type': 'application/json'
                },
                body: JSON.stringify(payload)
            });
            if (res.ok) {
                toast.success('Platform settings saved!');
            } else {
                toast.error('Failed to save settings');
            }
        } catch (err) {
            toast.error('Network error saving settings');
        } finally {
            setSavingSettings(false);
        }
    };

    const handleRegisterCommands = async () => {
        toast((t) => (
            <div style={{ padding: '0.25rem 0.5rem', display: 'flex', flexDirection: 'column', gap: '0.75rem' }}>
                <span style={{ fontSize: '0.9rem', color: '#f2f3f5' }}>
                    <b>Sync Slash Commands?</b> This updates the bot's commands on Discord.
                </span>
                <div style={{ display: 'flex', gap: '0.5rem' }}>
                    <button
                        onClick={async () => {
                            toast.dismiss(t.id);
                            setRegisteringCommands(true);
                            try {
                                const res = await fetch('/api/admin/commands/register', {
                                    method: 'POST',
                                    headers: { 'Authorization': `Bearer ${token}` }
                                });
                                if (res.ok) {
                                    toast.success('Slash commands registered!');
                                } else {
                                    toast.error('Failed to register commands');
                                }
                            } catch {
                                toast.error('Network error');
                            } finally {
                                setRegisteringCommands(false);
                            }
                        }}
                        style={{ padding: '8px 16px', fontSize: '0.85rem', border: 'none', borderRadius: '4px', background: 'var(--discord-blurple)', color: 'white', cursor: 'pointer', fontWeight: 600 }}
                    >
                        Sync
                    </button>
                    <button
                        onClick={() => toast.dismiss(t.id)}
                        style={{ padding: '8px 16px', fontSize: '0.85rem', border: 'none', borderRadius: '4px', background: 'rgba(255,255,255,0.1)', color: '#f2f3f5', cursor: 'pointer', fontWeight: 600 }}
                    >
                        Cancel
                    </button>
                </div>
            </div>
        ), { duration: Infinity, position: 'top-center' });
    };

    const handleUpdateReport = async (reportId: number, status: string) => {
        try {
            const res = await fetch(`/api/admin/reports/${reportId}`, {
                method: 'PATCH',
                headers: { 
                    'Authorization': `Bearer ${token}`,
                    'Content-Type': 'application/json'
                },
                body: JSON.stringify({ status })
            });
            if (res.ok) {
                toast.success(`Report marked as ${status.toLowerCase()}`);
                fetchData();
            } else {
                toast.error('Failed to update report');
            }
        } catch {
            toast.error('Network error');
        }
    };

    const handleDeleteReport = (reportId: number) => {
        toast((t) => (
            <div style={{ padding: '4px' }}>
                <span style={{ fontWeight: 600, display: 'block', marginBottom: '4px' }}>Delete Report?</span>
                <p style={{ margin: '0 0 12px 0', fontSize: '0.8rem', opacity: 0.8 }}>Are you sure you want to permanently delete this report?</p>
                <div style={{ display: 'flex', gap: '8px' }}>
                    <button 
                        onClick={async () => {
                            toast.dismiss(t.id);
                            await executeDeleteReport(reportId);
                        }}
                        style={{ background: '#ed4245', color: 'white', border: 'none', padding: '6px 12px', borderRadius: '4px', cursor: 'pointer', fontSize: '0.75rem', fontWeight: 600 }}
                    >
                        DELETE
                    </button>
                    <button 
                        onClick={() => toast.dismiss(t.id)}
                        style={{ background: 'rgba(255,255,255,0.1)', color: 'white', border: 'none', padding: '6px 12px', borderRadius: '4px', cursor: 'pointer', fontSize: '0.75rem', fontWeight: 600 }}
                    >
                        CANCEL
                    </button>
                </div>
            </div>
        ), { duration: 6000 });
    };

    const executeDeleteReport = async (reportId: number) => {
        try {
            const res = await fetch(`/api/admin/reports/${reportId}`, {
                method: 'DELETE',
                headers: { 'Authorization': `Bearer ${token}` }
            });
            if (res.ok) {
                toast.success('Report deleted');
                fetchData();
            } else {
                toast.error('Failed to delete report');
            }
        } catch {
            toast.error('Network error');
        }
    };

    const handlePreviewLogPost = async (postId: number) => {
        setFetchingPostId(postId);
        try {
            const res = await fetch(`/api/admin/posts/${postId}`, {
                headers: { 'Authorization': `Bearer ${token}` }
            });
            if (res.ok) {
                setPreviewPostData(await res.json() as any);
            } else {
                toast.error("Post not found or deleted");
            }
        } catch {
            toast.error("Network error fetching post");
        } finally {
            setFetchingPostId(null);
        }
    };

    const handleRescanServer = async () => {
        if (!platformSettings.defaultGuildId) {
            toast.error("Please select a primary server first.");
            return;
        }

        setRefreshingServer(true);
        try {
            const res = await fetch(`/api/guilds/${platformSettings.defaultGuildId}/rescan`, {
                method: 'POST',
                headers: { 'Authorization': `Bearer ${token}` }
            });

            if (res.ok) {
                await refreshData();
                toast.success("Server rescan complete! Data refreshed.");
            } else {
                toast.error("Failed to rescan server.");
            }
        } catch (err) {
            toast.error("Network error during rescan.");
        } finally {
            setRefreshingServer(false);
        }
    };

    return (
        <div className="admin-panel animate-in">
            {inspectingUser && <UserProfileModal token={token} user={inspectingUser} currentUser={user} onClose={() => setInspectingUser(null)} />}
            {mergingUser && (
                <MergeAccountModal 
                    token={token} 
                    sourceUser={mergingUser} 
                    allUsers={users} 
                    onClose={() => setMergingUser(null)} 
                    onMerged={() => {
                        setMergingUser(null);
                        fetchData();
                    }}
                />
            )}
            {previewPostData && <SharedPostView post={previewPostData} onClose={() => setPreviewPostData(null)} />}
            <div className="admin-header">
                <div className="admin-title">
                    <ShieldIcon size={24} className="text-primary" />
                    <h1>Administration Panel</h1>
                </div>
                <div className="admin-tabs">
                    <button
                        className={`admin-tab ${activeTab === 'users' ? 'active' : ''}`}
                        onClick={() => setActiveTab('users')}
                    >
                        <UsersIcon size={18} /> User Management
                    </button>
                    <button
                        className={`admin-tab ${activeTab === 'logs' ? 'active' : ''}`}
                        onClick={() => setActiveTab('logs')}
                    >
                        <Activity size={18} /> Audit Logs
                    </button>
                    <button
                        className={`admin-tab ${activeTab === 'settings' ? 'active' : ''}`}
                        onClick={() => setActiveTab('settings')}
                    >
                        <SettingsIcon size={18} /> Platform Settings
                    </button>
                    <button
                        className={`admin-tab ${activeTab === 'moderation' ? 'active' : ''}`}
                        onClick={() => setActiveTab('moderation')}
                    >
                        <Activity size={18} /> Global Moderation
                    </button>
                    <button
                        className={`admin-tab ${activeTab === 'groups' ? 'active' : ''}`}
                        onClick={() => setActiveTab('groups')}
                    >
                        <Layout size={18} /> Contact Clusters
                    </button>
                    {user?.role === 'OWNER' && (
                        <button
                            className={`admin-tab ${activeTab === 'contacts' ? 'active' : ''}`}
                            onClick={() => setActiveTab('contacts')}
                        >
                            <UsersIcon size={18} /> Community Contacts
                        </button>
                    )}
                    {user?.role === 'OWNER' && (
                        <button
                            className={`admin-tab tour-reports-tab ${activeTab === 'reports' ? 'active' : ''}`}
                            onClick={() => setActiveTab('reports')}
                        >
                            <AlertCircle size={18} /> Reported Issues
                        </button>
                    )}
                </div>
            </div>

            <div className="admin-content">
                {loading ? (
                    <div className="admin-loading">
                        <RefreshCw size={32} className="spin" />
                        <p>Loading data...</p>
                    </div>
                ) : error ? (
                    <div className="admin-error">
                        <AlertCircle size={32} />
                        <p>{error}</p>
                        <button onClick={fetchData} className="btn-retry">Try Again</button>
