import React from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { useData } from '../contexts/DataContext';

interface AnimatedCounterProps {
    value: number | string;
    className?: string;
    style?: React.CSSProperties;
}

export const AnimatedCounter: React.FC<AnimatedCounterProps> = ({ value, className, style }) => {
    const { userSettings } = useData();
    const reducedMotion = userSettings.reducedMotion;

    return (
        <span style={{ position: 'relative', display: 'inline-flex', overflow: 'hidden', alignItems: 'center', justifyContent: 'center', ...style }} className={className}>
            <AnimatePresence mode="popLayout" initial={false}>
                <motion.span
                    key={value}
                    initial={reducedMotion ? { opacity: 1 } : { y: 15, opacity: 0, scale: 0.8 }}
                    animate={reducedMotion ? { opacity: 1 } : { y: 0, opacity: 1, scale: 1 }}
                    exit={reducedMotion ? { opacity: 1 } : { y: -15, opacity: 0, scale: 0.8 }}
                    transition={reducedMotion ? { duration: 0 } : { duration: 0.25, type: 'spring', bounce: 0.4 }}
                >
                    {value}
                </motion.span>
            </AnimatePresence>
        </span>
    );
};

import React, { useState, useEffect } from 'react';
import { Loader2 } from 'lucide-react';
import { toast } from 'react-hot-toast';

interface BibleVerseSelectorProps {
    token: string | null;
    onVerseFetched: (content: string) => void;
    onReferenceChange: (ref: string) => void;
}

export const BibleVerseSelector: React.FC<BibleVerseSelectorProps> = ({
    token, onVerseFetched, onReferenceChange
}) => {
    const [bibleVersion, setBibleVersion] = useState('111'); // 111 = NIV, 1 = KJV, 206 = WEB
    const [bibleBook, setBibleBook] = useState('');
    const [bibleChapter, setBibleChapter] = useState('');
    const [bibleVerse, setBibleVerse] = useState('');
    const [bibleEndVerse, setBibleEndVerse] = useState('');

    const [availableBooks, setAvailableBooks] = useState<any[]>([]);
    const [availableChapters, setAvailableChapters] = useState<any[]>([]);
    const [availableVerses, setAvailableVerses] = useState<any[]>([]);
    const [fetchingVerse, setFetchingVerse] = useState(false);

    const bookTitle = availableBooks.find(b => b.id === bibleBook || b.title === bibleBook)?.title || bibleBook;

    useEffect(() => {
        const ref = bibleVerse
            ? (bibleEndVerse && bibleEndVerse !== bibleVerse)
                ? `${bookTitle} ${bibleChapter}:${bibleVerse.split('.').pop()}-${bibleEndVerse.split('.').pop()}`
                : `${bookTitle} ${bibleChapter}:${bibleVerse.split('.').pop()}`
            : '';
        onReferenceChange(ref);
    }, [bibleBook, bibleChapter, bibleVerse, bibleEndVerse, bookTitle]);

    useEffect(() => {
        fetch(`/api/services/bible/${bibleVersion}/books`, { headers: { 'Authorization': `Bearer ${token}` } })
            .then(async res => {
                if (!res.ok) {
                    const err = await res.json().catch(() => ({}));
                    throw new Error((err as any).error || `Error ${res.status}`);
                }
                return res.json() as any as any;
            })
            .then(data => {
                const books = data.books || data.data;
                if (books && Array.isArray(books)) {
                    setAvailableBooks(books);
                } else {
                    console.error("No books in response", data);
                }
                setBibleBook('');
                setBibleChapter('');
                setBibleVerse('');
                setBibleEndVerse('');
                setAvailableChapters([]);
                setAvailableVerses([]);
            })
            .catch(err => {
                console.error("Failed to load books:", err);
                toast.error(`Failed to load books: ${err.message}`);
            });
    }, [bibleVersion, token]);

    useEffect(() => {
        if (!bibleBook) return;

        const book = availableBooks.find(b => b.id === bibleBook || b.title === bibleBook);
        if (!book) return;

        const bookCode = book.id;

        fetch(`/api/services/bible/${bibleVersion}/books/${bookCode}/chapters`, { headers: { 'Authorization': `Bearer ${token}` } })
            .then(async res => {
                if (!res.ok) {
                    const err = await res.json().catch(() => ({}));
                    throw new Error((err as any).error || `Error ${res.status}`);
                }
                return res.json() as any as any;
            })
            .then(data => {
                const chapters = data.chapters || data.data;
                if (chapters && Array.isArray(chapters)) {
                    setAvailableChapters(chapters);
                } else {
                    console.error("No chapters in response", data);
                }
                setBibleChapter('');
                setBibleVerse('');
                setBibleEndVerse('');
                setAvailableVerses([]);
            })
            .catch(err => {
                console.error("Failed to load chapters:", err);
                toast.error(`Failed to load chapters: ${err.message}`);
            });
    }, [bibleBook, bibleVersion, token, availableBooks]);

    useEffect(() => {
        if (!bibleChapter || !bibleBook) {
            setAvailableVerses([]);
            return;
        }

        const book = availableBooks.find(b => b.id === bibleBook || b.title === bibleBook);
        if (!book) return;

        const bookCode = book.id;

        fetch(`/api/services/bible/${bibleVersion}/books/${bookCode}/chapters/${bibleChapter}/verses`, { 
            headers: { 'Authorization': `Bearer ${token}` } 
        })
            .then(async res => {
                if (!res.ok) {
                    const err = await res.json().catch(() => ({}));
                    throw new Error((err as any).error || `Error ${res.status}`);
                }
                return res.json() as any;
            })
            .then(data => {
                const verses = data.verses || data.data;
                if (verses && Array.isArray(verses)) {
                    setAvailableVerses(verses);
                } else {
                    console.error("No verses in response", data);
                }
                setBibleVerse('');
                setBibleEndVerse('');
            })
            .catch(err => {
                console.error("Failed to load verses:", err);
                toast.error(`Failed to load verses: ${err.message}`);
            });
    }, [bibleChapter, bibleVersion, token, availableBooks]);

    const fetchVerse = async () => {
        if (!bibleVerse) return;
        if (!bibleVerse.includes('.')) {
            toast.error('Please select a valid verse from the dropdown list.');
            return;
        }
        setFetchingVerse(true);
        try {
            const usfm = (bibleEndVerse && bibleEndVerse !== bibleVerse)
                ? `${bibleVerse}-${bibleEndVerse.split('.').pop()}`
                : bibleVerse;

            const res = await fetch(`/api/services/bible/${bibleVersion}/passages/${usfm}`, {
                headers: { 'Authorization': `Bearer ${token}` }
            });

            if (!res.ok) {
                const err = await res.json().catch(() => ({}));
                throw new Error((err as any).error || `Error ${res.status}`);
            }

            const data = await res.json() as any;
            if (data.content) {
                onVerseFetched(data.content);
            } else if (data.error || data.message) {
                toast.error(`API Error: ${data.error || data.message}`);
            }
        } catch (err: any) {
            console.error("Failed to fetch verse:", err);
            toast.error(`Failed to fetch verse: ${err.message}`);
        } finally {
            setFetchingVerse(false);
        }
    };

    return (
        <div className="bible-selector-container">
            <div className="input-group">
                <label>Bible Translation</label>
                <div className="greeting-options">
                    {['111', '1', '206'].map(v => (
                        <button
                            key={v}
                            className={`greet-btn ${bibleVersion === v ? 'active' : ''}`}
                            onClick={() => {
                                if (v === '1') toast.error('King James Version is currently unavailable');
                                else setBibleVersion(v);
                            }}
                            style={v === '1' ? { opacity: 0.6 } : {}}
                        >
                            {v === '111' ? 'NIV' : v === '1' ? 'KJV' : 'WEB'}
                        </button>
                    ))}
                </div>
            </div>

            <div className="input-group">
                <label>Bible Reference (Optional)</label>
                <div className="bible-dropdown-group" style={{ display: 'grid', gridTemplateColumns: '1.5fr 1fr 1fr 1fr auto', gap: '0.4rem' }}>
                    <div style={{ position: 'relative' }}>
                        <input
                            type="text"
                            className="dropdown-select"
                            placeholder="Book (e.g. John)"
                            list="bible-books-list"
                            value={bibleBook}
                            onChange={(e) => setBibleBook(e.target.value)}
                            style={{ padding: '0.5rem', width: '100%' }}
                        />
                        <datalist id="bible-books-list">
                            {availableBooks.map(b => (
                                <option key={b.id} value={b.title}>{b.id}</option>
                            ))}
                        </datalist>
                    </div>

                    <div style={{ position: 'relative' }}>
                        <input
                            type="text"
                            className="dropdown-select"
                            placeholder="Chap"
                            list="bible-chapters-list"
                            value={bibleChapter}
                            onChange={(e) => setBibleChapter(e.target.value)}
                            disabled={!bibleBook}
                            style={{ padding: '0.5rem', width: '100%' }}
                        />
                        <datalist id="bible-chapters-list">
                            {availableChapters.map((c: any) => <option key={c.id} value={c.id}>{c.title}</option>)}
                        </datalist>
                    </div>

                    <div style={{ position: 'relative' }}>
                        <input
                            type="text"
                            className="dropdown-select"
                            placeholder="Start"
                            list="bible-start-verse-list"
                            value={bibleVerse}
                            onChange={(e) => setBibleVerse(e.target.value)}
                            disabled={!bibleChapter}
                            style={{ padding: '0.5rem', width: '100%' }}
                        />
                        <datalist id="bible-start-verse-list">
                            {availableVerses.map((v: any) => <option key={v.passage_id} value={v.passage_id}>{v.title}</option>)}
                        </datalist>
                    </div>

                    <div style={{ position: 'relative' }}>
                        <input
                            type="text"
                            className="dropdown-select"
                            placeholder="End"
                            list="bible-end-verse-list"
                            value={bibleEndVerse}
                            onChange={(e) => setBibleEndVerse(e.target.value)}
                            disabled={!bibleVerse}
                            style={{ padding: '0.5rem', width: '100%' }}
                        />
                        <datalist id="bible-end-verse-list">
                            {availableVerses.map((v: any) => (
                                <option
                                    key={`end-${v.passage_id}`}
                                    value={v.passage_id}
                                >
                                    {v.title}
                                </option>
                            ))}
                        </datalist>
                    </div>

                    <button
                        onClick={fetchVerse}
                        disabled={fetchingVerse || !bibleVerse}
                        className="btn-primary"
                        style={{ width: '60px', padding: '0.5rem' }}
                    >
                        {fetchingVerse ? <Loader2 className="animate-spin shrink" size={16} /> : 'Fetch'}
                    </button>
                </div>
            </div>
        </div>
    );
};

import React, { useState, useEffect } from 'react';
import { 
    Users as UsersIcon, Smartphone, CheckCircle, 
    ArrowLeft, Send, CheckCircle2, RefreshCw, Layers
} from 'lucide-react';
import { toast } from 'react-hot-toast';

interface Contact {
    id: number;
    name: string;
    phoneNumber: string;
    deviceOs: 'ANDROID' | 'IOS' | 'UNKNOWN';
}

interface BulkMessengerProps {
    token: string;
    content: string;
    groupId: number;
    onClose: () => void;
}

export const BulkMessenger: React.FC<BulkMessengerProps> = ({ token, content, groupId, onClose }) => {
    const [contacts, setContacts] = useState<Contact[]>([]);
    const [currentIndex, setCurrentIndex] = useState(0);
    const [sentIds, setSentIds] = useState<Set<number>>(new Set());
    const [loading, setLoading] = useState(true);
    const [groupName, setGroupName] = useState('');

    useEffect(() => {
        fetchContacts();
    }, [groupId]);

    const fetchContacts = async () => {
        setLoading(true);
        try {
            const res = await fetch(`/api/me/contacts/groups/${groupId}/members`, {
                headers: { 'Authorization': `Bearer ${token}` }
            });
            if (!res.ok) throw new Error(`Server returned ${res.status}`);
            const data = await res.json() as any;
            setContacts(Array.isArray(data.members) ? data.members : []);
            setGroupName(data.group?.name || 'Group');
        } catch (err) {
            toast.error('Failed to load group members');
        } finally {
            setLoading(false);
        }
    };

    const currentContact = contacts[currentIndex];
    const progress = contacts.length > 0 ? (sentIds.size / contacts.length) * 100 : 0;

    const handleSendCurrent = () => {
        if (!currentContact) return;

        const phone = currentContact.phoneNumber;
        const isIOS = currentContact.deviceOs === 'IOS' || /iPad|iPhone|iPod/.test(navigator.userAgent);

        // Protocol: ios uses &body, android/others use ?body
        const smsUrl = isIOS 
            ? `sms:${phone}&body=${encodeURIComponent(content)}` 
            : `sms:${phone}?body=${encodeURIComponent(content)}`;

        window.location.href = smsUrl;

        // Mark as sent
        setSentIds(prev => new Set(prev).add(currentContact.id));

        // Auto-advance if not at the end
        if (currentIndex < contacts.length - 1) {
            setTimeout(() => {
                setCurrentIndex(prev => prev + 1);
            }, 1000);
        }
    };

    const handleSkip = () => {
        if (currentIndex < contacts.length - 1) {
            setCurrentIndex(prev => prev + 1);
        }
    };

    if (loading) {
        return (
            <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', padding: '10rem 0', opacity: 0.5 }}>
                <RefreshCw size={48} className="spin" style={{ color: 'var(--discord-blurple)' }} />
                <p style={{ marginTop: '1.5rem', fontWeight: 600 }}>Gathering your contacts...</p>
            </div>
        );
    }

    if (contacts.length === 0) {
        return (
            <div style={{ textAlign: 'center', padding: '10rem 2rem', background: 'rgba(255,255,255,0.02)', borderRadius: '24px', border: '2px dashed rgba(255,255,255,0.05)' }}>
                <UsersIcon size={64} style={{ opacity: 0.1, marginBottom: '1.5rem' }} />
                <h3 style={{ marginBottom: '0.5rem' }}>No contacts in this group</h3>
                <p className="text-secondary" style={{ marginBottom: '2rem' }}>Add some contacts to the "{groupName}" group before sending.</p>
                <button className="btn-secondary" onClick={onClose}>Go Back</button>
            </div>
        );
    }

    const isFinished = sentIds.size === contacts.length;

    return (
        <div className="bulk-messenger-container animate-entrance" style={{ maxWidth: '900px', margin: '0 auto' }}>
            <div className="bulk-messenger-header" style={{ marginBottom: '2.5rem', display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
                <div>
                    <h2 style={{ margin: 0, fontSize: '1.75rem' }}>Individual Bulk Messenger</h2>
                    <p className="text-secondary" style={{ marginTop: '0.25rem' }}>Sending to: <strong style={{ color: 'white' }}>{groupName}</strong></p>
                </div>
                <button className="btn-secondary" onClick={onClose} style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', border: 'none', background: 'rgba(255,255,255,0.05)' }}>
                    <ArrowLeft size={16} /> Exit Tool
                </button>
            </div>

            <div className="progress-section" style={{ background: 'rgba(255,255,255,0.03)', padding: '1.5rem', borderRadius: '20px', border: '1px solid rgba(255,255,255,0.08)', marginBottom: '2.5rem', boxShadow: '0 8px 32px rgba(0,0,0,0.2)' }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '1rem', alignItems: 'flex-end' }}>
                    <div>
                        <span style={{ fontSize: '0.7rem', textTransform: 'uppercase', fontWeight: 800, opacity: 0.5, letterSpacing: '0.05em' }}>Delivery Progress</span>
                        <div style={{ fontSize: '1.25rem', fontWeight: 700 }}>{sentIds.size} / {contacts.length} Successfully Triggered</div>
                    </div>
                    <span style={{ fontSize: '1.25rem', fontWeight: 700, color: 'var(--discord-blurple)' }}>{Math.round(progress)}%</span>
                </div>
                <div style={{ height: '10px', background: 'rgba(255,255,255,0.05)', borderRadius: '5px', overflow: 'hidden' }}>
                    <div 
                        style={{ 
                            height: '100%', 
                            width: `${progress}%`, 
                            background: 'linear-gradient(90deg, var(--discord-blurple), #7289da)', 
                            transition: 'width 0.6s cubic-bezier(0.34, 1.56, 0.64, 1)',
                            boxShadow: '0 0 15px rgba(88,101,242,0.4)'
                        }} 
                    />
                </div>
            </div>

            {isFinished ? (
                <div className="completion-card animate-scale-up" style={{ textAlign: 'center', padding: '5rem 2rem', background: 'rgba(35, 165, 90, 0.03)', borderRadius: '32px', border: '1px solid rgba(35, 165, 90, 0.2)', boxShadow: '0 24px 48px rgba(0,0,0,0.4)' }}>
                    <div style={{ width: '90px', height: '90px', borderRadius: '50%', background: '#23a55a', color: 'white', display: 'flex', alignItems: 'center', justifyContent: 'center', margin: '0 auto 2rem', boxShadow: '0 0 30px rgba(35,165,90,0.4)' }}>
                        <CheckCircle2 size={48} />
                    </div>
                    <h2 style={{ fontSize: '2rem', marginBottom: '1rem' }}>Mission Accomplished!</h2>
                    <p className="text-secondary" style={{ fontSize: '1.1rem', marginBottom: '3rem', maxWidth: '500px', margin: '0 auto 3rem' }}>All contacts in this group have been queued for sending. You can now close this tool or review your results.</p>
                    <div style={{ display: 'flex', justifyContent: 'center', gap: '1rem' }}>
                        <button className="btn-secondary" onClick={() => window.location.reload()} style={{ padding: '1.25rem 2rem' }}>Start New Group</button>
                        <button className="btn-hero-primary" onClick={onClose} style={{ padding: '1.25rem 3rem', fontSize: '1.1rem' }}>Finish & Return</button>
                    </div>
                </div>
            ) : (
                <div className="messenger-workflow" style={{ display: 'grid', gridTemplateColumns: 'minmax(0, 1fr) 320px', gap: '2.5rem', alignItems: 'start' }}>
                    <div className="current-contact-focus" style={{ background: 'var(--bg-darker)', padding: '3rem', borderRadius: '32px', border: '1px solid rgba(255,255,255,0.08)', boxShadow: '0 32px 64px rgba(0,0,0,0.5)', textAlign: 'center' }}>
                        <div style={{ width: '120px', height: '120px', borderRadius: '32px', background: 'linear-gradient(135deg, var(--discord-blurple), #7289da)', color: 'white', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '3.5rem', fontWeight: 800, margin: '0 auto 2rem', boxShadow: '0 16px 32px rgba(88,101,242,0.3)' }}>
                            {currentContact.name.charAt(0)}
                        </div>
                        <h3 style={{ fontSize: '2.25rem', margin: '0 0 0.5rem 0', fontWeight: 800 }}>{currentContact.name}</h3>
                        <p className="text-secondary" style={{ fontSize: '1.25rem', marginBottom: '1.5rem', opacity: 0.8 }}>{currentContact.phoneNumber}</p>

                        <div style={{ display: 'flex', justifyContent: 'center', gap: '0.75rem', marginBottom: '3rem' }}>
                            <span style={{ fontSize: '0.85rem', padding: '6px 16px', borderRadius: '8px', background: 'rgba(255,255,255,0.05)', border: '1px solid rgba(255,255,255,0.05)', display: 'flex', alignItems: 'center', gap: '8px', color: '#949ba4' }}>
                                <Smartphone size={16} /> {currentContact.deviceOs}
                            </span>
                        </div>

                        <div style={{ background: 'rgba(0,0,0,0.3)', padding: '2rem', borderRadius: '24px', textAlign: 'left', marginBottom: '3rem', border: '1px solid rgba(255,255,255,0.05)' }}>
                            <label style={{ fontSize: '0.7rem', textTransform: 'uppercase', fontWeight: 900, opacity: 0.3, display: 'block', marginBottom: '1rem', letterSpacing: '0.1em' }}>Message Payload</label>
                            <p style={{ margin: 0, fontSize: '1rem', color: '#dbdee1', whiteSpace: 'pre-wrap', lineHeight: 1.6 }}>{content}</p>
                        </div>

                        <div style={{ display: 'flex', gap: '1.5rem' }}>
                            <button 
                                className="btn-secondary" 
                                style={{ flex: 1, padding: '1.5rem', borderRadius: '16px', fontWeight: 700 }} 
                                onClick={handleSkip}
                            >
                                Skip Contact
                            </button>
                            <button 
                                className="btn-hero-primary" 
                                style={{ flex: 2, padding: '1.5rem', borderRadius: '16px', fontSize: '1.25rem', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '1rem', boxShadow: '0 10px 20px rgba(88,101,242,0.3)' }}
                                onClick={handleSendCurrent}
                            >
                                <Send size={24} /> Trigger SMS App
                            </button>
                        </div>
                    </div>

                    <div className="queue-sidebar" style={{ background: 'rgba(255,255,255,0.02)', borderRadius: '24px', padding: '1.5rem', border: '1px solid rgba(255,255,255,0.05)', display: 'flex', flexDirection: 'column', gap: '1rem' }}>
                        <h4 style={{ margin: 0, fontSize: '0.9rem', textTransform: 'uppercase', opacity: 0.5, fontWeight: 800, letterSpacing: '0.05em', display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
                            <Layers size={16} /> Recipient Queue
                        </h4>
                        <div style={{ flex: 1, overflowY: 'auto', maxHeight: '600px', display: 'flex', flexDirection: 'column', gap: '0.75rem', paddingRight: '0.5rem' }}>
                            {contacts.map((c, index) => (
                                <div 
                                    key={c.id} 
                                    onClick={() => setCurrentIndex(index)}
                                    style={{ 
                                        padding: '1.25rem', 
                                        borderRadius: '16px', 
                                        background: index === currentIndex ? 'rgba(88, 101, 242, 0.15)' : sentIds.has(c.id) ? 'rgba(35, 165, 90, 0.05)' : 'rgba(255,255,255,0.02)',
                                        border: `1px solid ${index === currentIndex ? 'var(--discord-blurple)' : sentIds.has(c.id) ? 'rgba(35, 165, 90, 0.1)' : 'rgba(255,255,255,0.05)'}`,
                                        cursor: 'pointer',
                                        display: 'flex',
                                        alignItems: 'center',
                                        gap: '1rem',
                                        opacity: sentIds.has(c.id) ? 0.4 : 1,
                                        transition: 'all 0.2s',
                                        transform: index === currentIndex ? 'scale(1.02)' : 'none'
                                    }}
                                >
                                    <div style={{ width: '40px', height: '40px', borderRadius: '12px', background: 'rgba(255,255,255,0.05)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '1rem', fontWeight: 800 }}>
                                        {c.name.charAt(0)}
                                    </div>
                                    <div style={{ flex: 1, overflow: 'hidden' }}>
                                        <div style={{ fontSize: '0.95rem', fontWeight: 600, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{c.name}</div>
                                        <div style={{ fontSize: '0.8rem', opacity: 0.5 }}>{c.phoneNumber}</div>
