                                        <div style={{ width: '8px', height: '8px', borderRadius: '50%', background: 'var(--discord-blurple)', boxShadow: '0 0 10px var(--discord-blurple)' }} />
                                    ) : null}
                                </div>
                            ))}
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

import React, { useMemo } from 'react';
import { Calendar, ArrowLeft, Tag, Sparkles, Send, Clock, ChevronRight } from 'lucide-react';
import { SPECIAL_DATES, SpecialDate } from '../utils/specialDates';

interface CalendarViewProps {
    onClose: () => void;
    onSelectDate: (date: SpecialDate & { dateObj: Date }) => void;
}

export const CalendarView: React.FC<CalendarViewProps> = ({ onClose, onSelectDate }) => {
    const upcomingDates = useMemo(() => {
        const now = new Date();
        const currentYear = now.getFullYear();

        return [...SPECIAL_DATES]
            .map(d => {
                const [month, day] = d.date.split('-').map(Number);
                let dateObj = new Date(currentYear, month - 1, day);

                // If the date has passed this year, look at next year
                const today = new Date(currentYear, now.getMonth(), now.getDate());
                if (dateObj < today) {
                    dateObj = new Date(currentYear + 1, month - 1, day);
                }

                return { ...d, dateObj };
            })
            .sort((a, b) => a.dateObj.getTime() - b.dateObj.getTime());
    }, []);

    return (
        <div className="calendar-view animate-entrance">
            <div className="flex items-center gap-4 mb-8">
                <button 
                    className="w-10 h-10 rounded-full flex items-center justify-center bg-white/5 border border-white/10 hover:bg-white/10 transition-all cursor-pointer"
                    onClick={onClose}
                >
                    <ArrowLeft size={20} />
                </button>
                <div>
                    <div className="flex items-center gap-2 mb-1">
                        <span className="text-[var(--accent)] text-[10px] font-black uppercase tracking-[0.2em]">Opportunities</span>
                        <div className="h-px w-8 bg-[var(--accent)] opacity-30"></div>
                    </div>
                    <h2 className="text-3xl font-black m-0 tracking-tight">Community Calendar</h2>
                </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
                {upcomingDates.map((date, index) => {
                    const daysAway = Math.ceil((date.dateObj.getTime() - new Date().getTime()) / (1000 * 60 * 60 * 24));

                    return (
                        <div 
                            key={index} 
                            className="bento-card p-6 bg-white/[0.02] border border-white/10 rounded-3xl hover:border-[var(--accent)] transition-all group cursor-pointer"
                            onClick={() => onSelectDate(date)}
                        >
                            <div className="flex justify-between items-start mb-4">
                                <div className="flex flex-col">
                                    <span className="text-[var(--accent)] text-xs font-black uppercase tracking-widest mb-1">{date.date}</span>
                                    <h3 className="text-xl font-black group-hover:text-[var(--accent)] transition-colors">{date.name}</h3>
                                </div>
                                <div className="p-2 rounded-xl bg-white/5 group-hover:bg-[var(--accent-glow)] group-hover:text-[var(--accent)] transition-all">
                                    <Calendar size={20} />
                                </div>
                            </div>

                            <p className="text-sm text-[var(--text-secondary)] line-clamp-2 mb-6 min-h-[2.8rem]">
                                {date.desc}
                            </p>

                            <div className="flex items-center justify-between mt-auto pt-4 border-top border-white/5">
                                <div className="flex items-center gap-2 text-[10px] font-black uppercase tracking-widest text-muted">
                                    <Clock size={12} className="text-blue-400" />
                                    {daysAway === 0 ? 'Today' : `${daysAway} days away`}
                                </div>
                                <div className="flex items-center gap-1 text-[var(--accent)] text-xs font-bold opacity-0 group-hover:opacity-100 transition-opacity">
                                    Details <ChevronRight size={14} />
                                </div>
                            </div>
                        </div>
                    );
                })}
            </div>
        </div>
    );
};

import React from 'react';

interface CharacterCounterProps {
  current: number;
  limit: number;
  showAlways?: boolean;
}

export const CharacterCounter: React.FC<CharacterCounterProps> = ({ current, limit, showAlways = false }) => {
  if (!showAlways && current === 0) return null;

  const percentage = (current / limit) * 100;
  let color = 'rgba(255, 255, 255, 0.4)';

  if (percentage >= 100) {
    color = '#ed4245'; // Discord Red
  } else if (percentage >= 90) {
    color = '#f1c40f'; // Discord Yellow
  }

  return (
    <div style={{ 
      fontSize: '0.7rem', 
      textAlign: 'right', 
      color, 
      marginTop: '0.25rem',
      fontWeight: percentage >= 90 ? 700 : 400,
      transition: 'color 0.2s ease'
    }}>
      {current} / {limit}
    </div>
  );
};

import React from 'react';
import { MessageSquare, Trash2 } from 'lucide-react';
import { toast } from 'react-hot-toast';
import { Response } from '../types';
import { useAuth } from '../contexts/AuthContext';
import { useData } from '../contexts/DataContext';
import { DiscordMessages, DiscordMessage } from './discord/DiscordUi';

interface CommunityProps {
  responses: Response[];
}

export const Community: React.FC<CommunityProps> = ({ responses }) => {
  const { isAdmin, isHost, token } = useAuth();
  const { setView } = useData();

  const handleDelete = async (id: number) => {
    if (!token) return;

    toast((t) => (
      <div style={{ padding: '0.25rem 0.5rem', display: 'flex', flexDirection: 'column', gap: '0.75rem' }}>
        <span style={{ fontSize: '0.9rem', color: '#f2f3f5', display: 'flex', alignItems: 'center', gap: '8px' }}>
          <b>Delete this response?</b> This action cannot be undone.
        </span>
        <div style={{ display: 'flex', gap: '0.5rem' }}>
          <button
            onClick={async () => {
              toast.dismiss(t.id);
              try {
                const res = await fetch(`/api/posts/responses/${id}`, {
                  method: 'DELETE',
                  headers: { 'Authorization': `Bearer ${token}` }
                });
                if (res.ok) {
                  toast.success('Response deleted');
                  setView('dashboard');
                  setTimeout(() => setView('community'), 50);
                } else {
                  toast.error('Failed to delete response');
                }
              } catch (e) {
                toast.error('Error connecting to API');
              }
            }}
            style={{ backgroundColor: '#ed4245', padding: '8px 16px', fontSize: '0.85rem', border: 'none', borderRadius: '4px', color: 'white', cursor: 'pointer', fontWeight: 600 }}
          >
            Delete
          </button>
          <button
            onClick={() => toast.dismiss(t.id)}
            style={{ padding: '8px 16px', fontSize: '0.85rem', border: 'none', borderRadius: '4px', background: 'rgba(255,255,255,0.1)', color: '#f2f3f5', cursor: 'pointer', fontWeight: 600 }}
          >
            Cancel
          </button>
        </div>
      </div>
    ), { duration: Infinity, position: 'top-center' });
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '2rem' }}>
      <CommunityStats />

      <div style={{ display: 'flex', flexDirection: 'column', gap: '0.5rem' }}>
        {responses.length === 0 ? (
          <div className="empty-state">
            <MessageSquare size={48} />
            <p>No community responses yet.</p>
          </div>
        ) : (
          responses.map(res => {
            const isGuest = res.userId === 'GUEST';
            return (
              <div key={res.id} className="tour-responses-grid" style={{ padding: '0.5rem', background: 'rgba(30,31,34,0.4)', borderRadius: '8px', border: '1px solid rgba(255,255,255,0.05)', position: 'relative' }}>
                <DiscordMessages>
                  <DiscordMessage 
                    author={`${res.userTag}${isGuest ? ' (Guest)' : ''}`}
                    roleColor={isGuest ? '#949ba4' : '#f2f3f5'}
                    timestamp={new Date(res.createdAt).toLocaleString('en-US', {
                      month: 'short', day: 'numeric', year: 'numeric',
                      hour: 'numeric', minute: '2-digit'
                    })}
                  >
                    {res.responseText}
                  </DiscordMessage>
                </DiscordMessages>
                  {(isAdmin || isHost) && (
                    <button
                      onClick={() => handleDelete(res.id)}
                      title="Delete response"
                      style={{
                        background: 'transparent',
                        border: 'none',
                        color: '#949ba4',
                        cursor: 'pointer',
                        padding: '4px',
                        borderRadius: '4px',
                        opacity: 0.5,
                        transition: 'all 0.15s',
                        flexShrink: 0,
                        alignSelf: 'flex-start'
                      }}
                      onMouseEnter={e => { e.currentTarget.style.opacity = '1'; e.currentTarget.style.color = '#ed4245'; }}
                      onMouseLeave={e => { e.currentTarget.style.opacity = '0.5'; e.currentTarget.style.color = '#949ba4'; }}
                    >
                      <Trash2 size={14} />
                    </button>
                  )}
                </div>
            );
          })
        )}
      </div>
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { useAuth } from '../contexts/AuthContext';
import { Users as UsersIcon, BarChart } from 'lucide-react';
import { AnimatedCounter } from './AnimatedCounter';

export const CommunityStats: React.FC = () => {
    const { token, isAdmin, isHost } = useAuth();
    const [participants, setParticipants] = useState<any[]>([]);
    const [postStats, setPostStats] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        if (!token || (!isAdmin && !isHost)) return;

        const fetchStats = async () => {
            try {
                const [partRes, postRes] = await Promise.all([
                    fetch('/api/stats/participants', { headers: { 'Authorization': `Bearer ${token}` } }),
                    fetch('/api/stats/posts_interactions', { headers: { 'Authorization': `Bearer ${token}` } })
                ]);
                const partData = await partRes.json() as any;
                const postData = await postRes.json() as any;

                if (Array.isArray(partData)) setParticipants(partData);
                if (Array.isArray(postData)) setPostStats(postData);
            } catch (err) {
                console.error("Failed to fetch community stats", err);
            } finally {
                setLoading(false);
            }
        };

        fetchStats();
    }, [token, isAdmin, isHost]);

    if (!isAdmin && !isHost) return null;
    if (loading) return <div>Loading statistics...</div>;

    return (
        <div className="stats-container" style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(300px, 1fr))', gap: '1.5rem', marginBottom: '2rem' }}>
            <div className="stat-card" style={{ background: 'var(--bg-dark)', padding: '1.5rem', borderRadius: '8px', border: '1px solid rgba(255,255,255,0.05)' }}>
                <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem', marginBottom: '1rem', color: 'var(--discord-blurple)' }}>
                    <UsersIcon size={24} />
                    <h3 style={{ margin: 0 }}>Top Participants</h3>
                </div>
                {participants.length === 0 ? <p style={{ color: 'var(--text-secondary)' }}>No participation data yet.</p> : (
                    <div className="stats-list" style={{ display: 'flex', flexDirection: 'column', gap: '0.75rem' }}>
                        {participants.slice(0, 5).map(p => (
                            <div key={p.userId} style={{ display: 'flex', justifyContent: 'space-between', padding: '0.75rem', background: 'rgba(255,255,255,0.02)', borderRadius: '6px' }}>
                                <span>{p.userTag}</span>
                                <strong style={{ color: 'var(--discord-blurple)' }}><AnimatedCounter value={p.replyCount} /> Replies</strong>
                            </div>
                        ))}
                    </div>
                )}
            </div>

            <div className="stat-card" style={{ background: 'var(--bg-dark)', padding: '1.5rem', borderRadius: '8px', border: '1px solid rgba(255,255,255,0.05)' }}>
                <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem', marginBottom: '1rem', color: '#57F287' }}>
                    <BarChart size={24} />
                    <h3 style={{ margin: 0 }}>High Engagement Posts</h3>
                </div>
                {postStats.length === 0 ? <p style={{ color: 'var(--text-secondary)' }}>No post interaction data yet.</p> : (
                    <div className="stats-list" style={{ display: 'flex', flexDirection: 'column', gap: '0.75rem' }}>
                        {postStats.filter(p => p.responseCount > 0).slice(0, 5).map(p => (
                            <div key={p.postId} style={{ display: 'flex', justifyContent: 'space-between', padding: '0.75rem', background: 'rgba(255,255,255,0.02)', borderRadius: '6px' }}>
                                <span style={{ whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis', maxWidth: '200px' }}>{p.content || p.bibleReference || 'Message'}</span>
                                <strong style={{ color: '#57F287' }}><AnimatedCounter value={p.responseCount} /> Hits</strong>
                            </div>
                        ))}
                    </div>
                )}
            </div>
        </div>
    );
};

import React, { useState } from 'react';
import { ChevronDown, ChevronRight } from 'lucide-react';

interface ComposerSectionProps {
    label: string;
    children: React.ReactNode;
    controls?: React.ReactNode;
    collapsible?: boolean;
    defaultExpanded?: boolean;
    icon?: React.ReactNode;
    status?: string;
    onMoveUp?: () => void;
    onMoveDown?: () => void;
}

const getStatusLabel = (status: string) => {
    switch (status) {
        case 'valid': return 'Valid';
        case 'incomplete': return 'Incomplete';
        case 'invalid': return 'Invalid';
        case 'not-required': return 'Optional';
        default: return '';
    }
};

const getStatusColor = (status: string) => {
    switch (status) {
        case 'valid': return '#23a55a';
        case 'incomplete': return '#f0b232';
        case 'invalid': return '#f23f43';
        case 'not-required': return '#b5bac1';
        default: return '#b5bac1';
    }
};

export const ComposerSection: React.FC<ComposerSectionProps> = ({
    label, children, controls, collapsible = false, defaultExpanded = true, icon, status, onMoveUp, onMoveDown
}) => {
    const [isExpanded, setIsExpanded] = useState(defaultExpanded);

    return (
        <div className={`composer-section ${collapsible ? 'is-collapsible' : ''} ${isExpanded ? 'is-expanded' : 'is-collapsed'}`}>
            <div
                className="section-header"
                onClick={() => collapsible && setIsExpanded(!isExpanded)}
                style={{ cursor: collapsible ? 'pointer' : 'default' }}
            >
                <div className="section-title">
                    {icon && <span className="section-icon">{icon}</span>}
                    <span className="section-label">{label}</span>
                    {status && (
                        <span style={{ display: 'inline-flex', alignItems: 'center', gap: '0.35rem', marginLeft: '0.5rem' }}>
                            <span className={`status-indicator indicator-${status}`} title={status}></span>
                            <span style={{ fontSize: '0.65rem', fontWeight: 600, color: getStatusColor(status), textTransform: 'uppercase', letterSpacing: '0.03em' }}>
                                {getStatusLabel(status)}
                            </span>
                        </span>
                    )}
                    {collapsible && (
                        <span className="section-chevron">
                            {isExpanded ? <ChevronDown size={14} /> : <ChevronRight size={14} />}
                        </span>
                    )}
                    <div className="section-reorder-btns" style={{ display: 'flex', gap: '2px', marginLeft: 'auto', marginRight: '0.5rem' }}>
                        {onMoveUp && (
                            <button 
                                onClick={(e) => { e.stopPropagation(); onMoveUp(); }} 
                                style={{ background: 'transparent', border: 'none', color: 'rgba(255,255,255,0.3)', cursor: 'pointer', padding: '2px' }}
                                title="Move Section Up"
                                onMouseEnter={(e) => e.currentTarget.style.color = 'white'}
                                onMouseLeave={(e) => e.currentTarget.style.color = 'rgba(255,255,255,0.3)'}
                            >
                                <ChevronDown size={16} style={{ transform: 'rotate(180deg)' }} />
                            </button>
                        )}
                        {onMoveDown && (
                            <button 
                                onClick={(e) => { e.stopPropagation(); onMoveDown(); }} 
                                style={{ background: 'transparent', border: 'none', color: 'rgba(255,255,255,0.3)', cursor: 'pointer', padding: '2px' }}
                                title="Move Section Down"
                                onMouseEnter={(e) => e.currentTarget.style.color = 'white'}
                                onMouseLeave={(e) => e.currentTarget.style.color = 'rgba(255,255,255,0.3)'}
                            >
                                <ChevronDown size={16} />
                            </button>
                        )}
                    </div>
                </div>
                {controls && <div className="section-controls" onClick={(e) => e.stopPropagation()}>{controls}</div>}
            </div>
            {(!collapsible || isExpanded) && (
                <div className="section-content animate-fade-in">
                    {children}
                </div>
            )}
        </div>
    );
};

import React, { useState, useEffect } from 'react';
import { 
  Users, Plus, Trash2, UserPlus, Check, X, 
  Search, Loader2, ArrowLeft, Layers, Save
} from 'lucide-react';
import { toast } from 'react-hot-toast';

interface Contact {
  id: number;
  name: string;
  phoneNumber: string;
}

interface ContactGroup {
  id: number;
  name: string;
  memberCount: number;
}

interface ContactGroupManagerProps {
  token: string;
}

export const ContactGroupManager: React.FC<ContactGroupManagerProps> = ({ token }) => {
  const [groups, setGroups] = useState<ContactGroup[]>([]);
  const [allContacts, setAllContacts] = useState<Contact[]>([]);
  const [loading, setLoading] = useState(true);
  const [view, setView] = useState<'LIST' | 'CREATE' | 'ADD_MEMBERS'>('LIST');
  const [selectedGroup, setSelectedGroup] = useState<ContactGroup | null>(null);
  const [newGroupName, setNewGroupName] = useState('');
  const [search, setSearch] = useState('');
  const [selectedContactIds, setSelectedContactIds] = useState<number[]>([]);

  const fetchGroups = async () => {
    setLoading(true);
    try {
      const res = await fetch('/api/me/contacts/groups', {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      if (!res.ok) throw new Error(`Server returned ${res.status}`);
      const data = await res.json() as any;
      setGroups(Array.isArray(data) ? data : []);
    } catch (err) {
      console.error('Fetch groups error:', err);
      toast.error('Failed to sync groups');
    } finally {
      setLoading(false);
    }
  };

  const fetchContacts = async () => {
    try {
      const res = await fetch('/api/me/contacts', {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      if (!res.ok) throw new Error(`Server returned ${res.status}`);
      const data = await res.json() as any;
      setAllContacts(Array.isArray(data) ? data : []);
    } catch (err) {
      console.error('Fetch contacts error:', err);
      toast.error('Failed to sync contacts');
    }
  };

  useEffect(() => {
    fetchGroups();
    fetchContacts();
  }, []);

  const handleCreateGroup = async () => {
    if (!newGroupName.trim()) return toast.error('Name required');
    try {
      const res = await fetch('/api/me/contacts/groups', {
        method: 'POST',
        headers: { 
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({ name: newGroupName })
      });
      if (!res.ok) throw new Error('Creation failed');
      toast.success('Group initialized');
      setNewGroupName('');
      setView('LIST');
      fetchGroups();
    } catch (err) {
      toast.error('Failed to create group');
    }
  };

  const handleAddMembers = async () => {
    if (!selectedGroup || selectedContactIds.length === 0) return;
    try {
      const res = await fetch(`/api/me/contacts/groups/${selectedGroup.id}/members`, {
        method: 'POST',
        headers: { 
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({ contactIds: selectedContactIds })
      });
      if (!res.ok) throw new Error('Bulk add failed');
      toast.success(`${selectedContactIds.length} members assigned`);
      setSelectedContactIds([]);
      setView('LIST');
      fetchGroups();
    } catch (err) {
      toast.error('Failed to add members');
    }
  };

  const filteredContacts = Array.isArray(allContacts) ? allContacts.filter(c => 
    (c.name || '').toLowerCase().includes(search.toLowerCase()) || 
    (c.phoneNumber || '').includes(search)
  ) : [];

  if (loading && groups.length === 0) {
    return (
      <div className="flex-center py-20 opacity-50">
        <Loader2 className="animate-spin mr-3" size={24} />
        <span className="font-black uppercase tracking-widest text-xs">Loading Groups...</span>
      </div>
    );
  }

  return (
    <div className="contact-group-manager text-white">
      <div className="manager-header flex justify-between items-center mb-8">
        <div className="flex items-center gap-4">
          <div className="p-3 bg-blue-500/10 rounded-xl text-blue-500 border border-blue-500/20">
            <Layers size={24} />
          </div>
          <div>
            <h2 className="text-xl font-black italic tracking-tighter">CONTACT GROUPS</h2>
            <p className="text-[10px] font-bold uppercase tracking-[0.2em] opacity-40">Group Management</p>
          </div>
        </div>

        {view === 'LIST' && (
          <button 
            onClick={() => setView('CREATE')}
            className="group flex items-center gap-2 px-5 py-2.5 bg-blue-600 hover:bg-blue-500 rounded-xl font-black text-xs uppercase tracking-widest transition-all shadow-lg shadow-blue-600/20"
          >
            <Plus size={16} className="group-hover:rotate-90 transition-transform" /> 
            Create New Group
          </button>
        )}
      </div>

      {view === 'CREATE' && (
        <div className="create-view max-w-md mx-auto p-8 bg-white/5 border border-white/10 rounded-3xl animate-entrance">
          <h3 className="text-lg font-black italic mb-6">CREATE GROUP</h3>
          <div className="space-y-4">
            <div>
              <label className="block text-[10px] font-black uppercase tracking-widest opacity-40 mb-2">Group Name</label>
              <input 
                type="text" 
                value={newGroupName}
                onChange={(e) => setNewGroupName(e.target.value)}
                placeholder="e.g. Family, Work, etc."
                className="w-100 bg-black/40 border border-white/10 rounded-xl px-4 py-3 text-sm focus:border-blue-500 outline-none transition-all placeholder:opacity-20"
              />
            </div>
            <div className="flex gap-3 pt-4">
              <button onClick={() => setView('LIST')} className="flex-1 py-3 bg-white/5 hover:bg-white/10 rounded-xl font-black text-[10px] uppercase tracking-widest transition-all">Cancel</button>
              <button 
                onClick={handleCreateGroup}
                className="flex-1 py-3 bg-blue-600 hover:bg-blue-500 rounded-xl font-black text-[10px] uppercase tracking-widest transition-all shadow-lg shadow-blue-600/20"
              >
                Create Group
              </button>
            </div>
          </div>
        </div>
      )}

      {view === 'ADD_MEMBERS' && selectedGroup && (
        <div className="add-members-view animate-entrance">
          <button onClick={() => setView('LIST')} className="flex items-center gap-2 text-xs font-bold opacity-50 hover:opacity-100 transition-opacity mb-6">
            <ArrowLeft size={16} /> BACK TO LIST
          </button>

          <div className="flex justify-between items-end mb-6">
            <div>
              <h3 className="text-lg font-black italic">ASSIGNING TO: {selectedGroup.name.toUpperCase()}</h3>
              <p className="text-[10px] font-bold opacity-40 uppercase tracking-widest">{selectedContactIds.length} Contacts Selected</p>
            </div>
            <button 
              disabled={selectedContactIds.length === 0}
              onClick={handleAddMembers}
              className="px-6 py-3 bg-green-600 hover:bg-green-500 disabled:opacity-20 disabled:grayscale rounded-xl font-black text-[10px] uppercase tracking-widest transition-all flex items-center gap-2"
            >
              <Save size={16} /> Save Membership
            </button>
          </div>

          <div className="search-box relative mb-6">
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 opacity-20" size={18} />
            <input 
              type="text" 
              placeholder="Filter contacts for assignment..."
              className="w-100 bg-white/5 border border-white/10 rounded-2xl pl-12 pr-4 py-4 text-sm focus:bg-white/10 outline-none transition-all"
              value={search}
              onChange={(e) => setSearch(e.target.value)}
            />
          </div>

          <div className="contacts-grid grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-3">
            {filteredContacts.map(contact => {
              const isSelected = selectedContactIds.includes(contact.id);
              return (
                <div 
                  key={contact.id} 
                  onClick={() => {
                    setSelectedContactIds(prev => 
                      isSelected ? prev.filter(id => id !== contact.id) : [...prev, contact.id]
                    );
                  }}
                  className={`contact-item p-4 rounded-2xl border cursor-pointer transition-all flex items-center justify-between ${
                    isSelected ? 'bg-blue-600/20 border-blue-500' : 'bg-white/5 border-white/5 hover:border-white/20'
                  }`}
                >
                  <div className="flex items-center gap-3">
                    <div className={`w-8 h-8 rounded-lg flex items-center justify-center font-black text-xs ${
                      isSelected ? 'bg-blue-600 text-white' : 'bg-white/10 text-white/40'
                    }`}>
                      {contact.name[0]?.toUpperCase()}
                    </div>
                    <div>
                      <div className="text-xs font-black uppercase tracking-wider">{contact.name}</div>
                      <div className="text-[10px] opacity-40">{contact.phoneNumber}</div>
                    </div>
                  </div>
                  <div className={`w-5 h-5 rounded-full border-2 flex items-center justify-center transition-all ${
                    isSelected ? 'bg-blue-600 border-blue-600 scale-110' : 'border-white/10'
                  }`}>
                    {isSelected && <Check size={12} strokeWidth={4} />}
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      )}

      {view === 'LIST' && (
        <div className="groups-list grid gap-4 grid-cols-1 md:grid-cols-2 xl:grid-cols-3">
          {groups.map(group => (
            <div key={group.id} className="group-card p-6 bg-white/5 border border-white/10 rounded-3xl hover:border-white/20 transition-all group">
              <div className="flex justify-between items-start mb-4">
                <div className="p-3 bg-blue-500/10 rounded-2xl text-blue-400">
                  <Users size={20} />
                </div>
                <div className="text-right">
                  <div className="text-2xl font-black italic">{group.memberCount}</div>
                  <div className="text-[10px] font-bold opacity-30 uppercase tracking-widest">Members</div>
                </div>
              </div>

              <h3 className="text-md font-black uppercase tracking-wider mb-6 group-hover:text-blue-400 transition-colors">{group.name}</h3>

              <div className="flex gap-2">
                <button 
                  onClick={() => {
                    setSelectedGroup(group);
                    setSelectedContactIds([]);
                    setView('ADD_MEMBERS');
                  }}
                  className="flex-1 py-2.5 bg-white/5 hover:bg-white/10 rounded-xl font-black text-[10px] uppercase tracking-widest transition-all flex items-center justify-center gap-2"
                >
                  <UserPlus size={14} /> Assign Members
                </button>
                <button className="p-2.5 bg-red-500/10 hover:bg-red-500/20 text-red-500/60 hover:text-red-500 rounded-xl transition-all">
                  <Trash2 size={14} />
                </button>
              </div>
            </div>
          ))}

          {groups.length === 0 && (
            <div className="col-span-full py-20 bg-white/5 border-2 border-dashed border-white/10 rounded-3xl text-center opacity-30">
              <Layers className="mx-auto mb-4" size={48} />
              <p className="font-black uppercase tracking-widest">No Contact Groups Defined</p>
              <p className="text-xs">Create a group to start organizing your contacts.</p>
            </div>
          )}
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { 
    Users as UsersIcon, UserPlus, Share2, Smartphone, 
    CheckCircle, XCircle, MoreVertical, Layers, ArrowLeft, Search, RefreshCw
} from 'lucide-react';
import { toast } from 'react-hot-toast';

interface Contact {
    id: number;
    name: string;
    phoneNumber: string;
    deviceOs: 'ANDROID' | 'IOS' | 'UNKNOWN';
    status: 'PENDING' | 'APPROVED';
    createdAt: string;
}

interface ContactGroup {
    id: number;
    name: string;
    createdAt: string;
    memberCount: number;
}

interface ContactManagerProps {
    token: string;
    user: any;
}

export const ContactManager: React.FC<ContactManagerProps> = ({ token, user }) => {
    const [contacts, setContacts] = useState<Contact[]>([]);
    const [groups, setGroups] = useState<ContactGroup[]>([]);
    const [loading, setLoading] = useState(true);
    const [view, setView] = useState<'CONTACTS' | 'GROUPS' | 'INVITE' | 'GROUP_DETAIL'>('CONTACTS');
    const [selectedGroup, setSelectedGroup] = useState<ContactGroup | null>(null);
    const [groupMembers, setGroupMembers] = useState<Contact[]>([]);
    const [search, setSearch] = useState('');

    const inviteLink = `${window.location.origin}/register?ref=${user.id}`;

    useEffect(() => {
        if (view !== 'GROUP_DETAIL') {
            fetchData();
        }
    }, [view]);

    const fetchData = async () => {
        setLoading(true);
        try {
            const endpoint = view === 'GROUPS' ? '/api/me/contacts/groups' : '/api/me/contacts';
            const res = await fetch(endpoint, {
                headers: { 'Authorization': `Bearer ${token}` }
            });
            if (!res.ok) throw new Error(`Server returned ${res.status}`);
            const data = await res.json() as any;

            if (view === 'GROUPS') {
                setGroups(Array.isArray(data) ? data : []);
            } else {
                setContacts(Array.isArray(data) ? data : []);
            }
        } catch (err) {
            console.error('Fetch error:', err);
            toast.error('Failed to fetch contact data');
        } finally {
            setLoading(false);
        }
    };

    const fetchGroupMembers = async (groupId: number) => {
        setLoading(true);
        try {
            const res = await fetch(`/api/me/contacts/groups/${groupId}/members`, {
                headers: { 'Authorization': `Bearer ${token}` }
            });
            if (!res.ok) throw new Error(`Server returned ${res.status}`);
            const data = await res.json() as any;
            setGroupMembers(Array.isArray(data.members) ? data.members : []);
        } catch (err) {
            console.error('Fetch members error:', err);
            toast.error('Failed to fetch group members');
        } finally {
            setLoading(false);
        }
    };

    const handleManageGroup = (group: ContactGroup) => {
        setSelectedGroup(group);
        setView('GROUP_DETAIL');
        fetchGroupMembers(group.id);
    };

    const handleRemoveMember = (contactId: number) => {
        if (!selectedGroup) return;

        toast((t) => (
            <div style={{ padding: '4px' }}>
                <span style={{ fontWeight: 600, display: 'block', marginBottom: '4px' }}>Remove member?</span>
                <p style={{ margin: '0 0 12px 0', fontSize: '0.8rem', opacity: 0.8 }}>Are you sure you want to remove this contact from the group?</p>
                <div style={{ display: 'flex', gap: '8px' }}>
                    <button 
                        onClick={async () => {
                            toast.dismiss(t.id);
                            await executeRemoveMember(contactId);
                        }}
                        style={{ background: '#ed4245', color: 'white', border: 'none', padding: '6px 12px', borderRadius: '4px', cursor: 'pointer', fontSize: '0.75rem', fontWeight: 600 }}
                    >
                        REMOVE
                    </button>
                    <button 
                        onClick={() => toast.dismiss(t.id)}
                        style={{ background: 'rgba(255,255,255,0.1)', color: 'white', border: 'none', padding: '6px 12px', borderRadius: '4px', cursor: 'pointer', fontSize: '0.75rem', fontWeight: 600 }}
                    >
                        CANCEL
                    </button>
                </div>
            </div>
        ), { duration: 6000 });
    };

    const executeRemoveMember = async (contactId: number) => {
        if (!selectedGroup) return;
        try {
            const res = await fetch(`/api/me/contacts/groups/${selectedGroup.id}/members/${contactId}`, {
                method: 'DELETE',
                headers: { 'Authorization': `Bearer ${token}` }
            });
            if (res.ok) {
                toast.success('Member removed');
                fetchGroupMembers(selectedGroup.id);
            } else {
                toast.error('Failed to remove member');
            }
        } catch (err) {
            toast.error('Error removing member');
        }
    };

    const handleDeleteGroup = () => {
        if (!selectedGroup) return;

        toast((t) => (
            <div style={{ padding: '4px' }}>
                <span style={{ fontWeight: 600, display: 'block', marginBottom: '4px' }}>Delete Group?</span>
                <p style={{ margin: '0 0 12px 0', fontSize: '0.8rem', opacity: 0.8 }}>Are you sure you want to delete the group "{selectedGroup.name}"? This action cannot be undone.</p>
                <div style={{ display: 'flex', gap: '8px' }}>
                    <button 
                        onClick={async () => {
                            toast.dismiss(t.id);
                            await executeDeleteGroup();
                        }}
                        style={{ background: '#ed4245', color: 'white', border: 'none', padding: '6px 12px', borderRadius: '4px', cursor: 'pointer', fontSize: '0.75rem', fontWeight: 600 }}
                    >
                        DELETE GROUP
                    </button>
                    <button 
                        onClick={() => toast.dismiss(t.id)}
                        style={{ background: 'rgba(255,255,255,0.1)', color: 'white', border: 'none', padding: '6px 12px', borderRadius: '4px', cursor: 'pointer', fontSize: '0.75rem', fontWeight: 600 }}
                    >
                        CANCEL
                    </button>
                </div>
            </div>
        ), { duration: 8000 });
    };

    const executeDeleteGroup = async () => {
        if (!selectedGroup) return;
        try {
            const res = await fetch(`/api/me/contacts/groups/${selectedGroup.id}`, {
                method: 'DELETE',
                headers: { 'Authorization': `Bearer ${token}` }
            });
            if (res.ok) {
                toast.success('Group deleted');
                setView('GROUPS');
            } else {
                toast.error('Failed to delete group');
            }
        } catch (err) {
            toast.error('Error deleting group');
        }
    };

    const handleLinkWithDevice = async (contact: Contact) => {
        if (!('contacts' in navigator && 'ContactsManager' in window)) {
            toast.error('Contact selection is not supported on this browser.');
            return;
        }

        try {
            // @ts-ignore - Contact Picker API is relatively new
            const props = ['name', 'tel'];
            const opts = { multiple: false };
            const selection = await (navigator as any).contacts.select(props, opts);

            if (selection && selection.length > 0) {
                const picked = selection[0];
                const newName = picked.name?.[0] || contact.name;
                const newPhone = picked.tel?.[0]?.replace(/\D/g, '') || contact.phoneNumber;

                if (newName === contact.name && newPhone === contact.phoneNumber) {
                    toast.success('Contact matches device info.');
                    return;
                }

                const res = await fetch(`/api/me/contacts/${contact.id}`, {
                    method: 'PATCH',
                    headers: { 
                        'Authorization': `Bearer ${token}`,
                        'Content-Type': 'application/json' 
                    },
                    body: JSON.stringify({ name: newName, phoneNumber: newPhone })
                });

                if (res.ok) {
                    toast.success(`Synced with ${newName}`);
                    fetchData(); // Refresh list
                } else {
                    toast.error('Failed to update contact info');
                }
            }
