interface CreatePostProps {
  user: UserInfo | null;
  token: string | null;
  setView: (view: 'dashboard' | 'create' | 'community') => void;
  selectedGuild: string;
  selectedChannel: string;
  setSelectedChannel: (id: string) => void;
  guilds: Guild[];
  channels: any[];
  initialPost?: any | null;
  platformSettings?: any;
  deletePost?: (id: number) => void;
  onRefreshDefaults?: () => void;
  onStartBulkMessenger?: (data: { content: string; groupId: number; initialPost?: any }) => void;
}

export const CreatePost: React.FC<CreatePostProps> = ({
  user, token, setView, selectedGuild, selectedChannel, setSelectedChannel, guilds, channels, initialPost, platformSettings, deletePost, onRefreshDefaults, onStartBulkMessenger
}) => {
  const { userSettings } = useData();
  const [content, setContent] = useState(initialPost?.content || '');
  const [customMessage, setCustomMessage] = useState(initialPost?.customMessage || '');
  const [customMessagePosition, setCustomMessagePosition] = useState<'ABOVE' | 'BELOW'>(initialPost?.customMessagePosition || 'ABOVE');
  const [riddleText, setRiddleText] = useState(initialPost?.riddleText || '');
  const [riddleAnswer, setRiddleAnswer] = useState(initialPost?.riddleAnswer || '');
  const [riddleNotifyCorrect, setRiddleNotifyCorrect] = useState(initialPost?.riddleNotifyCorrect === 1);
  const [riddleAliases, setRiddleAliases] = useState(initialPost?.riddleAliases || '');
  const [isVerseLocked, setIsVerseLocked] = useState(true);
  const [isRiddleLocked, setIsRiddleLocked] = useState(true);
  const [isAnswerLocked, setIsAnswerLocked] = useState(true);
  const [sendNow, setSendNow] = useState(false);
  const [greeting, setGreeting] = useState(initialPost?.greeting || '');
  const [customGreeting, setCustomGreeting] = useState(initialPost?.customGreeting || '');
  const [closing, setClosing] = useState(initialPost?.closing || '');
  const [customClosing, setCustomClosing] = useState('');
  const [closingPosition, setClosingPosition] = useState<'ABOVE' | 'BELOW'>(initialPost?.closingPosition || 'BELOW');
  const [recurrence, setRecurrence] = useState<'NONE' | 'DAILY' | 'WEEKLY' | 'MONTHLY'>(initialPost?.recurrence || 'NONE');
  const formatDateForPicker = (date: Date) => {
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const day = String(date.getDate()).padStart(2, '0');
    const hours = String(date.getHours()).padStart(2, '0');
    const minutes = String(date.getMinutes()).padStart(2, '0');
    return `${year}-${month}-${day}T${hours}:${minutes}`;
  };

  const [scheduledAt, setScheduledAt] = useState(initialPost?.scheduledAt ? formatDateForPicker(new Date(initialPost.scheduledAt)) : '');
  const [updateType, setUpdateType] = useState<'single' | 'series'>('single');
  const [sectionOrder, setSectionOrder] = useState<string[]>(
    initialPost?.sectionOrder 
      ? JSON.parse(initialPost.sectionOrder) 
      : ['GREETING', 'RIDDLE', 'BIBLE', 'CUSTOM', 'MEDIA', 'CLOSING']
  );
  const [showSeriesChoice, setShowSeriesChoice] = useState(false);
  const [showGifPicker, setShowGifPicker] = useState(false);
  const [autoShare, setAutoShare] = useState(false);
  const [lastCreatedPost, setLastCreatedPost] = useState<{ id: number, shareSlug?: string, customMessage?: string, bibleReference?: string, content?: string, scheduledAt?: string } | null>(null);
  const [shareOnly, setShareOnly] = useState(initialPost?.shareOnly === 1);
  const [isTestMode, setIsTestMode] = useState(initialPost?.isTestMode === 1);

  // Collapse sidebar state
  const [isSidebarCollapsed, setIsSidebarCollapsed] = useState(true);
  const [showSuccessModal, setShowSuccessModal] = useState(false);
  const [showSharePrompt, setShowSharePrompt] = useState(false);
  const [isSidebarMinimized, setIsSidebarMinimized] = useState(false);
  const [showWizardPreview, setShowWizardPreview] = useState(true);
  const [showTemplateTools, setShowTemplateTools] = useState(false);
  const [grammarMatches, setGrammarMatches] = useState<any[]>([]);
  const [isCheckingGrammar, setIsCheckingGrammar] = useState(false);

  // Dynamic Upcoming Dates logic
  const upcomingDates = React.useMemo(() => {
    const today = new Date();
    // Use a fixed reference time to avoid hydration mismatches if possible, 
    // or just calculate based on current date.
    return SPECIAL_DATES
      .map(d => {
        const [month, day] = d.date.split('-').map(Number);
        // Create date for this year
        let dateObj = new Date(today.getFullYear(), month - 1, day);
        // If it already passed this year, move to next year
        if (dateObj < new Date(today.getFullYear(), today.getMonth(), today.getDate())) {
          dateObj = new Date(today.getFullYear() + 1, month - 1, day);
        }
        return { ...d, dateObj };
      })
      .sort((a, b) => a.dateObj.getTime() - b.dateObj.getTime())
      .slice(0, 5); // Only show the next 5 upcoming opportunities
  }, []);

  const [promptSlug, setPromptSlug] = useState('');
  const [deliveryType, setDeliveryType] = useState<'DISCORD' | 'SMS'>('DISCORD');
  const [selectedGroupId, setSelectedGroupId] = useState<number | null>(null);
  const [contactGroups, setContactGroups] = useState<any[]>([]);

  useEffect(() => {
    if (user?.smsFeatureEnabled && token) {
      fetch('/api/me/contacts/groups', {
        headers: { 'Authorization': `Bearer ${token}` }
      })
      .then(res => res.json() as any)
      .then(data => {
        if (Array.isArray(data)) setContactGroups(data);
        else setContactGroups([]);
      })
      .catch(err => {
        console.error("SMS groups load failed", err);
        setContactGroups([]);
      });
    }
  }, [user, token]);



