  }, [userSettings]);

  const handleSaveTextSetting = async (type: 'greetings' | 'closings', text: string, action: 'add' | 'remove') => {
    if (!text.trim()) return;

    // Update local state first for snappiness
    let newArray: string[];
    const currentState = type === 'greetings' ? savedGreetings : savedClosings;

    if (action === 'add') {
      if (currentState.includes(text.trim())) {
        toast.error('This text is already saved.');
        return;
      }
      newArray = [...currentState, text.trim()];
    } else {
      newArray = currentState.filter(t => t !== text);
    }

    if (type === 'greetings') setSavedGreetings(newArray);
    else setSavedClosings(newArray);

    try {
      const res = await fetch('/api/me/profile', {
        method: 'PATCH',
        headers: {
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({
          userSettings: {
            ...userSettings,
            [type === 'greetings' ? 'savedGreetings' : 'savedClosings']: newArray
          }
        })
      });
      if (!res.ok) {
        toast.error(`Failed to ${action} ${(type || 'item').slice(0, -1)}.`);
      } else {
        toast.success(`Successfully ${action === 'add' ? 'saved' : 'deleted'} text.`);
      }
    } catch (err) {
      console.error(err);
      toast.error(`Error processing request.`);
    }
  };

  const handleGrammarCheck = async () => {
    if (!customMessage.trim()) {
      toast.error('Please enter some text to check.');
      return;
    }

    setIsCheckingGrammar(true);
    try {
      const res = await fetch('/api/services/grammar/check', {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({ text: customMessage })
      });

      if (res.ok) {
        const data = await res.json() as { matches: any[] };
        setGrammarMatches(data.matches || []);
        if (data.matches?.length === 0) {
          toast.success('No grammar or spelling issues found!');
        } else {
          toast.success(`Found ${data.matches.length} suggestions.`);
        }
      } else {
        toast.error('Grammar check failed. Service may be unavailable.');
      }
    } catch (err) {
      console.error(err);
      toast.error('Error connecting to grammar service.');
    } finally {
      setIsCheckingGrammar(false);
    }
  };

  const applyReplacement = (offset: number, length: number, replacement: string) => {
    const before = customMessage.substring(0, offset);
    const after = customMessage.substring(offset + length);
    setCustomMessage(before + replacement + after);
