  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = Array.from(e.target.files || []);
    if (files.length === 0) return;

    if (attachments.length + files.length > 4) {
      toast.error('You can only attach a maximum of 4 images.');
      return;
    }

    setIsUploading(true);
    const newUploads: string[] = [];

    for (const file of files) {
      if (file.size > 5 * 1024 * 1024) {
        toast.error(`${file.name} is too large. Max size is 5MB.`);
        continue;
      }

      const { optimizeImage, blobToBase64 } = await import('../utils/imageOptimizer');

      try {
        const { blob } = await optimizeImage(file);
        const base64 = await blobToBase64(blob);
        const fileNameWebp = file.name.replace(/\.[^/.]+$/, "") + ".webp";

        const res = await fetch('/api/posts/upload', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'Authorization': `Bearer ${token}`
          },
          body: JSON.stringify({ file: base64, filename: fileNameWebp, isPrivate: isPrivateUpload })
        });
        const data = await res.json() as any;
        if (data.url) {
          // Convert relative API URL to absolute for Discord compatibility
          const absoluteUrl = data.url.startsWith('http') 
            ? data.url 
            : `${window.location.origin}${data.url}`;
          newUploads.push(absoluteUrl);
        }
      } catch (err) {
        console.error("Upload failed", err);
      }
    }

    setAttachments(prev => [...prev, ...newUploads]);
    setIsUploading(false);
  };

  const removeAttachment = (index: number) => {
