  };

  const handleRcsShare = async (slug: string) => {
    const finalSlug = slug || lastCreatedPost?.shareSlug;
    if (!finalSlug) return;

    const url = `${window.location.origin}/share/${finalSlug}`;
    const siteTitle = platformSettings?.ogTitle || 'I AM';
    const siteDesc = platformSettings?.ogDescription || `Check out this inspiration from ${siteTitle}!`;

    let displayTitle = siteTitle;
    let shareText = siteDesc;

    // Logic for scheduled posts: append a notice if it's in the future
    const postToUse = lastCreatedPost || initialPost;

    if (postToUse?.customMessage) {
        displayTitle = postToUse.customMessage;
        shareText = postToUse.bibleReference ? `📖 ${postToUse.bibleReference} — ${postToUse.content?.slice(0, 100)}...` : (postToUse.content || shareText);
    } else if (postToUse?.bibleReference) {
        displayTitle = `${siteTitle}: ${postToUse.bibleReference}`;
        shareText = postToUse.content || shareText;
    }


    shareText += getScheduledPostWarning(postToUse?.scheduledAt, platformSettings?.scheduledPostNotice);

    const fullMsg = `${displayTitle}\n\n${shareText}\n\n${url}`;

    if ('contacts' in navigator && 'ContactsManager' in window) {
      try {
        const props = await (navigator as any).contacts.getProperties();
        if (props.includes('tel')) {
          const contacts = await (navigator as any).contacts.select(['name', 'tel'], { multiple: false });
          if (contacts.length > 0 && contacts[0].tel && contacts[0].tel.length > 0) {
            const phone = contacts[0].tel[0];
            const isIOS = /iPad|iPhone|iPod/.test(navigator.userAgent);
            const smsUrl = isIOS 
              ? `sms:${phone}&body=${encodeURIComponent(fullMsg)}` 
              : `sms:${phone}?body=${encodeURIComponent(fullMsg)}`;
            window.location.href = smsUrl;
            return;
          }
        }
      } catch (err) {
        console.error("Contact picker failed", err);
      }
    }

    const isIOS = /iPad|iPhone|iPod/.test(navigator.userAgent);
    const smsUrl = isIOS 
      ? `sms:&body=${encodeURIComponent(fullMsg)}` 
      : `sms:?body=${encodeURIComponent(fullMsg)}`;
    window.location.href = smsUrl;
  };

  const handleDeletePost = () => {
