  const handleSchedule = async (isDraftOverride = false) => {
    const hasVerseContent = verses.some(v => v.content.trim() !== '');
    if ((!hasVerseContent && !content && !customMessage && attachments.length === 0 && !riddleText) || !user) return;

    if (initialPost && initialPost.recurrence !== 'NONE' && !showSeriesChoice && !sendNow) {
      setShowSeriesChoice(true);
      return;
    }

      // Combine verse content with any standalone content
      const verseContent = verses.map(v => v.content).filter(Boolean).join('\n\n');
      const baseContent = verseContent || content;
      let finalContent = baseContent;

      const bibleRefString = verses.map(v => v.ref).filter(Boolean).join(', ');

      const greetingPart = customGreeting || (greeting && greeting !== 'NONE' ? greeting : '');
      const closingPart = (closing === 'custom' ? customClosing : closing) || '';


      let fullMessageForSms = [greetingPart, finalContent, closingPart].filter(Boolean).join('\n\n');

      // Append warning if scheduled in future
      const scheduledDate = scheduledAt ? new Date(scheduledAt) : null;
      if (scheduledDate && scheduledDate.getTime() > Date.now()) {
        fullMessageForSms += getScheduledPostWarning(scheduledAt, platformSettings?.scheduledPostNotice);
      }

      if (deliveryType === 'SMS') {
        if (!selectedGroupId) {
          toast.error('Please select a contact group first!');
          return;
        }
        onStartBulkMessenger?.({
          content: fullMessageForSms,
          groupId: selectedGroupId,
          initialPost
        });
        return;
      }

      setIsSubmitting(true);
      try {
        let finalGuildId = selectedGuild;
        let finalChannelId = selectedChannel;
        const finalWebhookUrl = platformSettings?.defaultWebhookUrl || null;

        if (finalGuildId === 'GLOBAL' && platformSettings?.defaultGuildId) {
          finalGuildId = platformSettings.defaultGuildId;
        }

        if (!finalChannelId && platformSettings?.defaultChannelId) {
          finalChannelId = platformSettings.defaultChannelId;
        }

        if (!shareOnly && finalGuildId === 'GLOBAL' && !finalChannelId && !finalWebhookUrl) {
          toast.error('No Server Selected! Please select a target server in the header menu (top-right) before posting.', {
            icon: '⚠️',
            duration: 4000
          });
          setIsSubmitting(false);
          return;
        }

        const isEdit = !!(initialPost && initialPost.id);
        const url = isEdit ? `/api/posts/${initialPost.id}` : '/api/posts';
        const method = isEdit ? 'PATCH' : 'POST';

      const payload = {
        guildId: finalGuildId,
        channelId: finalChannelId || null,
        webhookUrl: finalWebhookUrl || null,
        content: finalContent,
        bibleReference: bibleRefString,
        imageUrl: attachments.length > 0 ? attachments[0] : null,
        attachments: attachments,
        scheduledAt: scheduledAt ? new Date(scheduledAt).toISOString() : null,
        recurrence: recurrence,
        privateReplyEnabled: privateReplyEnabled,
        riddleButtonEnabled: riddleButtonEnabled,
        customMessage: customMessage || null,
        customMessagePosition: customMessagePosition,
        riddleText: riddleText || null,
        riddleAnswer: riddleAnswer || null,
        riddleAliases: riddleAliases || null,
        riddleNotifyCorrect: !!riddleNotifyCorrect,
        sendNow: isDraftOverride ? false : sendNow,
        seriesId: initialPost?.seriesId,
        isOverride: !!initialPost?.isOverride,
        updateType: updateType,
        closing: (closing === 'custom' ? customClosing : closing) || null,
        closingPosition: closingPosition,
        greeting: greeting || null,
        customGreeting: customGreeting || null,
        sectionOrder: JSON.stringify(sectionOrder),
        shareOnly: shareOnly,
        isTestMode: isTestMode
      };

      const res = await fetch(url, {
        method,
        headers: {
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'application/json'
        },
        body: JSON.stringify(payload)
      });

      const data = await res.json().catch(() => ({})) as any;

      if (!res.ok) {
        let errorMsg = 'An error occurred';
        if (typeof data.error === 'string') errorMsg = data.error;
        else if (data.error && typeof data.error === 'object' && data.error.message) errorMsg = data.error.message;
        else if (typeof data.message === 'string') errorMsg = data.message;
        else errorMsg = `Error: ${res.status} ${res.statusText}`;

        toast.error(errorMsg);
        setIsSubmitting(false);
        return;
      }

      if (data.success) {
        setLastCreatedPost({ id: data.id, shareSlug: data.shareSlug, scheduledAt: data.scheduledAt });

        if (data.warning) {
          toast(data.warning, { icon: '⚠️', duration: 5000 });
        }

        const isSharePromptEnabled = userSettings.sharePreference === 'PROMPT';

        if (shareOnly || autoShare) {
          setShowSuccessModal(true);
        } else if (isSharePromptEnabled && data.shareSlug) {
          setPromptSlug(data.shareSlug);
          setShowSharePrompt(true);
        } else {
          toast.success(isEdit ? 'Post updated successfully!' : (isDraftOverride ? 'Draft saved successfully!' : (sendNow ? 'Post sent successfully!' : 'Post scheduled successfully!')));
          if (!isEdit) {
            setView('dashboard');
          }
        }

        if (!isEdit) {
          setContent('');
          setGreeting('');
          setCustomGreeting('');
          setVerses([]);
          setScheduledAt('');
          setAttachments([]);
          setCustomMessage('');
          setRiddleText('');
          setRiddleAnswer('');
          setRiddleNotifyCorrect(false);
          setClosing('');
          setCustomClosing('');
          setSendNow(false);
        }
      } else {
        const errorMsg = typeof data.error === 'string' 
          ? data.error 
          : (data.error?.message || data.message || 'An unexpected error occurred while saving.');
        toast.error(errorMsg);
      }
    } catch (err) {
      console.error("Failed to save post", err);
      const errorMessage = err instanceof Error ? err.message : String(err);
      toast.error(`Error: ${errorMessage}`);
    } finally {
      setIsSubmitting(false);
    }
  };

