  const handleLoadTemplate = (template: Template) => {
    setContent(template.content || '');
    if (template.bibleReference) {
      setVerses([{ id: '1', ref: template.bibleReference, content: template.content || '' }]);
    } else {
      setVerses([]);
    }
    setCustomMessage(template.customMessage || '');
    setCustomMessagePosition(template.customMessagePosition || 'ABOVE');

    if (template.attachments) {
      try {
        setAttachments(JSON.parse(template.attachments));
      } catch {
        setAttachments(template.imageUrl ? [template.imageUrl] : []);
      }
    } else {
      setAttachments(template.imageUrl ? [template.imageUrl] : []);
    }

    setRiddleText(template.riddleText || '');
    setRiddleAnswer(template.riddleAnswer || '');
    setRiddleAliases(template.riddleAliases || '');
    setRiddleNotifyCorrect(!!template.riddleNotifyCorrect);
    setPrivateReplyEnabled(!!template.privateReplyEnabled);
    setRiddleButtonEnabled(!!template.riddleButtonEnabled);

    if (template.closing) {
      if (['Blessings,', 'Peace be with you,', 'Trust the process.'].includes(template.closing)) {
        setClosing(template.closing);
        setCustomClosing('');
      } else {
        setClosing('custom');
        setCustomClosing(template.closing);
      }
    } else {
      setClosing('');
      setCustomClosing('');
    }

    setClosingPosition(template.closingPosition || 'BELOW');
    setSectionOrder(template.sectionOrder ? JSON.parse(template.sectionOrder) : ['GREETING', 'RIDDLE', 'BIBLE', 'CUSTOM', 'MEDIA', 'CLOSING']);
    setShareOnly(!!template.shareOnly);

    setShowTemplateTools(false);
    toast.success(`Template loaded: ${template.name}`);
  };

  const handleDeleteTemplate = (e: React.MouseEvent, id: number) => {
    e.stopPropagation();

    toast((t) => (
      <div style={{ padding: '0.25rem 0.5rem', display: 'flex', flexDirection: 'column', gap: '0.75rem' }}>
        <span style={{ fontSize: '0.9rem', color: '#f2f3f5', display: 'flex', alignItems: 'center', gap: '8px' }}>
          <b>Delete this template?</b>
        </span>
        <div style={{ display: 'flex', gap: '0.5rem' }}>
          <button
            onClick={async () => {
              toast.dismiss(t.id);
              try {
                const res = await fetch(`/api/posts/templates/${id}`, {
                  method: 'DELETE',
                  headers: { 'Authorization': `Bearer ${token}` }
                });

                const data = await res.json().catch(() => ({})) as any;

                if (res.ok) {
                  toast.success('Template deleted.');
                  fetchTemplates();
                } else {
                  let errorMsg = 'Failed to delete template.';
                  if (typeof data.error === 'string') errorMsg = data.error;
                  else if (data.error && typeof data.error === 'object' && data.error.message) errorMsg = data.error.message;
                  else if (typeof data.message === 'string') errorMsg = data.message;

                  toast.error(errorMsg);
                }
              } catch (err) {
                console.error("Failed to delete template", err);
                const errorMessage = err instanceof Error ? err.message : String(err);
                toast.error(`Delete failed: ${errorMessage}`);
              }
            }}
            style={{ backgroundColor: '#ed4245', padding: '8px 16px', fontSize: '0.85rem', border: 'none', borderRadius: '4px', color: 'white', cursor: 'pointer', fontWeight: 600 }}
          >
            Delete
          </button>
          <button
            onClick={() => toast.dismiss(t.id)}
            style={{ padding: '8px 16px', fontSize: '0.85rem', border: 'none', borderRadius: '4px', background: 'rgba(255,255,255,0.1)', color: '#f2f3f5', cursor: 'pointer', fontWeight: 600 }}
          >
            Cancel
          </button>
        </div>
      </div>
    ), { duration: Infinity, position: 'top-center' });
  };

  const getSectionStatus = (section: string) => {
    const hasVerses = verses.some(v => v.content.trim() !== '');
    const hasCustom = customMessage.trim() !== '';
    const hasMedia = attachments.length > 0;
    const hasRiddle = riddleText.trim() !== '' && riddleAnswer.trim() !== '';
    const anyComplete = hasVerses || hasCustom || hasMedia || hasRiddle;

    switch (section) {
      case 'header':
        return 'valid';
      case 'bible':
        return hasVerses ? 'valid' : (anyComplete ? 'not-required' : 'incomplete');
      case 'custom':
        return hasCustom ? 'valid' : (anyComplete ? 'not-required' : 'incomplete');
      case 'media':
        return hasMedia ? 'valid' : 'not-required';
      case 'riddle':
        if (!riddleText.trim() && !riddleAnswer.trim()) return anyComplete ? 'not-required' : 'incomplete';
        return hasRiddle ? 'valid' : 'invalid';
      default:
        return 'incomplete';
    }
  };

  const isFormValid =
    verses.some(v => v.content.trim() !== '') ||
    customMessage.trim() !== '' ||
    attachments.length > 0 ||
    (riddleText.trim() !== '' && riddleAnswer.trim() !== '');

  const renderWizard = () => {
