                    onClick={() => setCurrentStep(prev => Math.min(steps.length - 1, prev + 1))}
                    style={{ padding: '0.75rem 2rem' }}
                  >
                    Next Step
                  </button>
                ) : null}
              </div>
            </div>
          </div>

          {showWizardPreview && (
            <div className={`wizard-preview-sidebar animate-fade-in ${isSidebarMinimized ? 'is-minimized' : ''}`}>
              {!isSidebarMinimized ? (
