              <Bookmark size={18} fill="currentColor" style={{ opacity: 0.6 }} />
              <h3 style={{ margin: 0, fontSize: '0.8rem', fontWeight: 700, textTransform: 'uppercase', letterSpacing: '0.05em' }}>Message Templates</h3>
            </div>
            <button 
