                fontWeight: 700,
                background: showTemplateTools ? 'rgba(255,255,255,0.05)' : 'var(--discord-blurple)', 
                color: 'white', 
                borderRadius: '6px',
                border: 'none',
                cursor: 'pointer',
                transition: 'all 0.2s ease',
                textTransform: 'uppercase',
                letterSpacing: '0.02em'
              }}
            >
              {showTemplateTools ? 'Close Library' : 'Open Library'}
            </button>
          </div>

          {showTemplateTools && (
            <div className="animate-fade-in" style={{ marginTop: '0.5rem', maxHeight: '300px', overflowY: 'auto', paddingRight: '0.5rem' }}>
              <div className="templates-grid" style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(200px, 1fr))', gap: '0.75rem' }}>
                {isLoadingTemplates ? (
                  <div style={{ padding: '1rem', textAlign: 'center', gridColumn: '1 / -1' }}><Loader2 className="animate-spin inline" size={16}/> Loading templates...</div>
                ) : templates.length === 0 ? (
