import React, { useState, useEffect, useMemo } from 'react';
import {
  Calendar, MessageSquare,
  PlusCircle, Users as UsersIcon, Globe, ArrowRight,
  Zap, Clock, Heart, Share2, Sparkles
} from 'lucide-react';
import { SPECIAL_DATES } from '../utils/specialDates';
import { CommunityStats } from './CommunityStats';
import { AnimatedCounter } from './AnimatedCounter';
import { useData } from '../contexts/DataContext';
import { PendingPostsList } from './PendingPostsList';

interface DashboardProps {
  setView: (view: any) => void;
  onSelectDate: (date: any) => void;
  onEditPost: (post: any) => void;
  token: string;
}

interface Stats {
  published: number;
  scheduled: number;
  drafts: number;
  responses: number;
}

export const Dashboard: React.FC<DashboardProps> = ({ setView, onSelectDate, onEditPost, token }) => {
  const { responses, posts, handleNavigateToCreate, selectedGuild } = useData();
  const [stats, setStats] = useState<Stats | null>(null);

  useEffect(() => {
    const url = new URL('/api/stats', window.location.origin);
    if (selectedGuild) {
      url.searchParams.append('guildId', selectedGuild);
    }

    fetch(url.toString(), {
      headers: { 'Authorization': `Bearer ${token}` }
    })
      .then(res => res.json() as any)
      .then(data => setStats(data))
      .catch(err => console.error("Failed to fetch stats", err));
  }, [token, selectedGuild]);

  const upcomingDates = useMemo(() => {
    const now = new Date();
    const currentYear = now.getFullYear();

    return [...SPECIAL_DATES]
      .map(d => {
        const [month, day] = d.date.split('-').map(Number);
        let dateObj = new Date(currentYear, month - 1, day);

        const today = new Date(currentYear, now.getMonth(), now.getDate());
        if (dateObj < today) {
          dateObj = new Date(currentYear + 1, month - 1, day);
        }

        return { ...d, dateObj };
      })
      .sort((a, b) => a.dateObj.getTime() - b.dateObj.getTime())
      .slice(0, 4);
  }, []);

  const pendingPosts = useMemo(() => {
    return posts
      .filter(p => p.status === 'DRAFT' || p.status === 'SCHEDULED')
      .sort((a, b) => {
        // Priority 1: Status (DRAFT first)
        if (a.status !== b.status) {
          return a.status === 'DRAFT' ? -1 : 1;
        }

        // Priority 2: Date/Time (Oldest to Newest)
        const dateA = a.status === 'SCHEDULED' ? new Date(a.scheduledAt!) : new Date(a.createdAt!);
        const dateB = b.status === 'SCHEDULED' ? new Date(b.scheduledAt!) : new Date(b.createdAt!);
        return dateA.getTime() - dateB.getTime();
      });
  }, [posts]);

  return (
    <div className="dashboard-bento">
      {/* Row 1: Global Analytics Overview */}
      <div className="bento-card span-4" style={{ padding: 0 }}>
        <CommunityStats />
      </div>

      {/* Row 2: Interaction Metrics & Messages - 3 Column Layout */}
      <div className="span-4" style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '1.5rem' }}>
        <div className="bento-card messages-bento" onClick={() => setView('posts')} style={{ cursor: 'pointer', position: 'relative', overflow: 'hidden' }}>
          <div className="bento-glow" style={{ position: 'absolute', top: 0, left: 0, right: 0, height: '4px', background: 'var(--accent)' }} />
