import React from 'react';
import { renderDiscordMarkdown } from '../utils/markdown';
import {
  DiscordMessages,
  DiscordMessage,
  DiscordAttachments,
  DiscordImageAttachment,
  DiscordEmbed,
  DiscordEmbedDescription,
  DiscordActionRow,
  DiscordButton
} from './discord/DiscordUi';

interface DiscordPreviewProps {
  verses: { id: string; ref: string; content: string }[];
  customMessage: string;
  greeting: string;
  customGreeting: string;
  closing: string;
  customClosing: string;
  closingPosition?: 'ABOVE' | 'BELOW';
  attachments: string[];
  scheduledAt: string;
  privateReplyEnabled: boolean;
  riddleButtonEnabled: boolean;
  riddleText?: string;
  sectionOrder?: string[];
}

export const DiscordPreview: React.FC<DiscordPreviewProps> = ({
  verses,
  customMessage,
  greeting,
  customGreeting,
  closing,
  customClosing,
  closingPosition = 'BELOW',
  attachments,
  scheduledAt,
  privateReplyEnabled,
  riddleButtonEnabled,
  riddleText,
  sectionOrder = ['GREETING', 'RIDDLE', 'BIBLE', 'CUSTOM', 'MEDIA', 'CLOSING']
}) => {
  const getGreetingText = () => {
    if (greeting === 'dynamic-day') {
      try {
        const date = scheduledAt ? new Date(scheduledAt) : new Date();
        if (isNaN(date.getTime())) return "Hello!"; 
        const day = new Intl.DateTimeFormat('en-US', { weekday: 'long' }).format(date);
        return `Hello, Happy ${day}!`;
      } catch {
        return "Hello!";
      }
    }
    if (greeting === 'dynamic-time') {
      try {
        const date = scheduledAt ? new Date(scheduledAt) : new Date();
        if (isNaN(date.getTime())) return "Hello!";
        const hour = date.getHours();
        let timeOfDay = 'Evening';
        if (hour < 12) timeOfDay = 'Morning';
        else if (hour < 17) timeOfDay = 'Afternoon';

        const day = new Intl.DateTimeFormat('en-US', { weekday: 'long' }).format(date);
        return `Good ${timeOfDay}, ${day}!`;
      } catch {
        return "Hello!";
      }
    }
    if (greeting === 'custom') return customGreeting;
    return greeting;
  };

  const getClosingText = () => {
    if (closing === 'custom') return customClosing;
    return closing;
  };

   const gText = getGreetingText();
  const cText = getClosingText();
  const bText = verses.map(v => v.ref ? `**${v.ref}**\n\n${v.content}` : v.content).join('\n\n');

  const sectionMap: Record<string, string> = {
    'GREETING': gText,
    'RIDDLE': riddleText ? `🧩 **Riddle:** ${riddleText}` : '',
    'BIBLE': bText,
    'CUSTOM': customMessage,
    'CLOSING': closingPosition === 'ABOVE' ? cText : ''
  };

  const sections: string[] = [];
  for (const type of sectionOrder) {
    const content = sectionMap[type];
    if (!content) continue;
    sections.push(content);
  }

  const fullMsg = sections.filter(Boolean).join('\n\n');

  const html = renderDiscordMarkdown(fullMsg);

  let closingHtml = '';
  if (cText && closingPosition === 'BELOW') {
    closingHtml = renderDiscordMarkdown(cText);
  }

  return (
    <div className="preview-container">
      <label>Discord Preview (Render)</label>
      <DiscordMessages>
        <DiscordMessage 
          author="I AM" 
          avatar="/brand/logo-circle.png" 
          bot={true} 
          verified={true}
          timestamp={new Date(scheduledAt || Date.now()).toLocaleString('en-US', {
            month: 'short', day: 'numeric', year: 'numeric',
            hour: 'numeric', minute: '2-digit'
          })}
        >
          <div dangerouslySetInnerHTML={{ __html: html }} />

          {attachments && attachments.length > 0 && (
            <DiscordAttachments slot="attachments">
              {attachments.map((url, i) => (
                <DiscordImageAttachment key={i} url={url} alt={`Attachment ${i}`} />
              ))}
            </DiscordAttachments>
          )}

          {closingHtml && closingPosition === 'BELOW' && (
            <DiscordEmbed slot="embeds" color="#5865f2">
              <DiscordEmbedDescription slot="description">
                <div dangerouslySetInnerHTML={{ __html: closingHtml }} />
              </DiscordEmbedDescription>
            </DiscordEmbed>
          )}

          {(privateReplyEnabled || riddleButtonEnabled) && (
            <DiscordActionRow slot="components">
              {privateReplyEnabled && <DiscordButton disabled type="secondary">Private Reply</DiscordButton>}
              {riddleButtonEnabled && <DiscordButton disabled type="secondary">Answer Riddle</DiscordButton>}
            </DiscordActionRow>
          )}
        </DiscordMessage>
      </DiscordMessages>
    </div>
  );
};

