  onNavigateToSettings?: () => void;
  view?: string;
  showWelcomeAnimation?: boolean;
}

export const FloatingHeader: React.FC<FloatingHeaderProps> = ({
  user,
  isAdmin,
  isHost,
  botStatus,
  guilds,
  selectedGuild,
  setSelectedGuild,
  isLoadingGuilds,
  guildsError,
  selectedChannel,
  setSelectedChannel,
  token,
  onStatusUpdate,
  setView,
  channels,
  isLoadingChannels,
  onToggleMobileSidebar,
  isMobileSidebarOpen,
  platformSettings,
  onNavigateToSettings,
  view,
  showWelcomeAnimation
}) => {
  const { unreadRepliesCount, userSettings, handleNavigateToCreate } = useData();
  const { logout } = useAuth();
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [dmConnectivity, setDmConnectivity] = useState<'checking' | 'ok' | 'blocked' | 'error'>('checking');
  const [dmEnabled, setDmEnabled] = useState(false);
  const [showQrModal, setShowQrModal] = useState(false);
  const [showTroubleshootModal, setShowTroubleshootModal] = useState(false);
  const [troubleshootUrl, setTroubleshootUrl] = useState('');
  const menuRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (typeof window !== 'undefined') {
      setTroubleshootUrl(`${window.location.origin}/troubleshoot`);
    }
  }, []);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      const target = event.target as Node;

      // Handle user menu click outside
      if (menuRef.current && !menuRef.current.contains(target)) {
        setIsMenuOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  useEffect(() => {
    if (token) {
      fetch('/api/me/onboarding', { headers: { 'Authorization': `Bearer ${token}` } })
        .then(res => res.json() as any)
        .then(data => {
          if (data && typeof data.dmNotifications !== 'undefined') {
            setDmEnabled(!!data.dmNotifications);
          }
        })
        .catch(console.error);
    }
  }, [token]);

  const checkDmStatus = async (isSilent: boolean = false) => {
    if (!token) return;
    setDmConnectivity('checking');
    try {
      const res = await fetch('/api/me/dm-status', {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({ silent: isSilent })
      });
      const data = await res.json() as any;
      if (data.status) {
        setDmConnectivity(data.status);
        if (!isSilent) {
          if (data.status === 'ok') toast.success("Messaging Status Verified! Check your Discord messages.");
          else if (data.status === 'blocked') toast.error("Bot is blocked or DMs are disabled in your settings.");
          else toast.error("Unable to verify DM status.");
        }
      }
    } catch {
      setDmConnectivity('error');
    }
  };

  useEffect(() => {
    if (token) {
      checkDmStatus(true);
    }
  }, [token]);

  const toggleDm = async () => {
    if (!token) return;
    const newVal = !dmEnabled;
    setDmEnabled(newVal);
    try {
      await fetch('/api/me/profile', {
        method: 'PATCH',
        headers: { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json' },
        body: JSON.stringify({ dmNotifications: newVal })
      });
      toast.success(newVal ? 'DM Reply Alerts Enabled' : 'DM Reply Alerts Disabled');
    } catch {
      toast.error('Failed to update preference');
      setDmEnabled(!newVal);
    }
  };

