import React, { useState } from 'react';
import { Search, Loader2, Image as ImageIcon, X } from 'lucide-react';
import { toast } from 'react-hot-toast';

interface GifPickerProps {
    token: string | null;
    onSelect: (url: string) => void;
    onClose: () => void;
}

export const GifPicker: React.FC<GifPickerProps> = ({ token, onSelect, onClose }) => {
    const [query, setQuery] = useState('');
    const [gifs, setGifs] = useState<any[]>([]);
    const [loading, setLoading] = useState(false);

    const searchGifs = async () => {
        if (!query.trim()) return;
        setLoading(true);
        try {
            const res = await fetch(`/api/services/gifs/search?q=${encodeURIComponent(query)}`, {

                headers: {
                    'Authorization': `Bearer ${token}`
                }
            });
            const data = await res.json() as any;
            if (!res.ok) {
                toast.error(data.error || 'Failed to search GIFs.');
                setGifs([]);
                return;
            }
            setGifs(data.data || []);
        } catch (err) {
            console.error('Failed to fetch GIFs:', err);
            toast.error('Network error while loading GIFs.');
        } finally {
            setLoading(false);
        }
    };

    const getUrl = (gif: any) => {
        return gif.images?.original?.url;
    };

    return (
        <div className="gif-modal-overlay" style={{ position: 'fixed', inset: 0, backgroundColor: 'rgba(0,0,0,0.8)', zIndex: 9999, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
            <div className="gif-modal" style={{ background: '#313338', padding: '1.5rem', borderRadius: '12px', width: '90%', maxWidth: '500px', display: 'flex', flexDirection: 'column', gap: '1rem', maxHeight: '80vh' }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                    <h3 style={{ margin: 0, display: 'flex', alignItems: 'center', gap: '0.5rem' }}><ImageIcon size={18} /> Search GIFs</h3>
                    <button onClick={onClose} style={{ background: 'transparent', border: 'none', color: '#b5bac1', cursor: 'pointer' }}><X size={20} /></button>
                </div>

                <div style={{ display: 'flex', gap: '0.5rem' }}>
                    <input
                        type="text"
                        placeholder="Search for GIFs..."
                        value={query}
                        onChange={(e) => setQuery(e.target.value)}
                        onKeyDown={(e) => e.key === 'Enter' && searchGifs()}
                        style={{ flex: 1, padding: '0.5rem', borderRadius: '4px', border: '1px solid rgba(255,255,255,0.1)', background: '#1e1f22', color: 'white' }}
                    />
                    <button onClick={searchGifs} className="btn-primary" style={{ margin: 0, padding: '0.5rem 1rem' }}>
                        {loading ? <Loader2 size={18} className="animate-spin" /> : <Search size={18} />}
                    </button>
                </div>

                <div className="gif-grid" style={{ flex: 1, overflowY: 'auto', display: 'grid', gridTemplateColumns: 'repeat(2, 1fr)', gap: '0.5rem', marginTop: '1rem' }}>
                    {gifs.map((g, i) => (
                        <div key={i} onClick={() => onSelect(getUrl(g))} style={{ cursor: 'pointer', borderRadius: '8px', overflow: 'hidden', height: '120px', background: '#2b2d31' }}>
                            <img src={getUrl(g)} alt="gif" style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
                        </div>
                    ))}
                    {gifs.length === 0 && !loading && <div style={{ gridColumn: '1 / -1', textAlign: 'center', color: '#b5bac1', padding: '2rem 0' }}>Search to find GIFs...</div>}
                </div>
            </div>
        </div>
    );
};

import React, { useState, useEffect } from 'react';
import { ChevronLeft, ChevronRight, Loader2, AlertCircle, RefreshCw, Trash2, Pencil, ExternalLink } from 'lucide-react';
import { Post } from '../types';
import { toast } from 'react-hot-toast';
import { toastConfirm } from './common';
import { DiscordPreview } from './DiscordPreview';
import { useData } from '../contexts/DataContext';

interface GlobalModerationFeedProps {
  onEdit?: (post: Post) => void;
}

export const GlobalModerationFeed: React.FC<GlobalModerationFeedProps> = ({ onEdit }) => {
  const { globalMutate } = useData();
  const [posts, setPosts] = useState<Post[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [page, setPage] = useState(1);
  const limit = 50;

  const fetchPosts = async () => {
    setLoading(true);
    setError(null);
    try {
      const res = await fetch(`/api/posts?page=${page}&limit=${limit}`);
      if (!res.ok) throw new Error('Failed to fetch global feed');
      const data = await res.json() as any;
      setPosts(data);
    } catch (err: any) {
      setError(err.message);
      toast.error('Moderation feed check failed');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchPosts();
  }, [page]);

  const deletePost = async (id: number) => {
    try {
      const res = await fetch(`/api/posts/${id}`, { method: 'DELETE' });
      if (!res.ok) throw new Error('Deletion failed');
      setPosts(prev => prev.filter(p => p.id !== id));
      globalMutate('/api/posts');
      toast.success('Post removed from system');
    } catch (err: any) {
      toast.error(err.message);
    }
  };

  if (loading && posts.length === 0) {
    return (
      <div className="flex-center p-20">
        <Loader2 className="animate-spin" size={32} />
        <span className="ml-4 opacity-70">Synthesizing Global Feed...</span>
      </div>
    );
  }

  if (error) {
    return (
      <div className="error-state p-10 bg-red-900/10 border border-red-900/30 rounded-lg">
        <AlertCircle className="text-red-500 mb-2" size={32} />
        <p className="font-bold text-red-500">Access Denied or Connection Failure</p>
        <p className="text-sm opacity-70">{error}</p>
        <button onClick={() => fetchPosts()} className="mt-4 flex items-center gap-2 text-xs font-bold uppercase tracking-widest text-blue-400 hover:text-white transition-colors">
          <RefreshCw size={14} /> Retry Sync
        </button>
      </div>
    );
  }

  return (
    <div className="global-moderation-feed">
      <div className="feed-header flex justify-between items-center mb-6">
        <div>
          <h2 className="text-xl font-black italic tracking-tighter">GLOBAL MODERATION</h2>
          <p className="text-sm opacity-50 font-bold uppercase tracking-widest">Master Feed Control</p>
        </div>

        <div className="pagination-controls flex items-center gap-4 bg-white/5 border border-white/10 rounded-full p-1 pl-4">
          <span className="text-xs font-black uppercase tracking-widest opacity-40">
            Page {page}
          </span>
          <div className="flex gap-1">
            <button 
              onClick={() => setPage(p => Math.max(1, p - 1))}
              disabled={page === 1}
              className="p-2 rounded-full hover:bg-white/10 disabled:opacity-20 disabled:cursor-not-allowed transition-all"
            >
              <ChevronLeft size={18} />
            </button>
            <button 
              onClick={() => setPage(p => p + 1)}
              disabled={posts.length < limit}
              className="p-2 rounded-full hover:bg-white/10 disabled:opacity-20 disabled:cursor-not-allowed transition-all"
            >
              <ChevronRight size={18} />
            </button>
          </div>
        </div>
      </div>

      <div className="grid gap-6 grid-cols-1 xl:grid-cols-2">
        {posts.map(post => (
          <div key={post.id} className="mod-card bg-white/5 border border-white/10 rounded-xl overflow-hidden shadow-2xl transition-all hover:border-white/20 hover:bg-white/[0.07]">
            <div className="card-top p-4 flex justify-between items-center border-b border-white/5 bg-black/20">
              <div className="user-info flex items-center gap-3">
                <div className="avatar w-8 h-8 bg-blue-600 rounded-full flex items-center justify-center font-black text-xs ring-2 ring-blue-600/20">
                  {post.authorName?.[0].toUpperCase() || '?'}
                </div>
                <div>
                  <div className="text-xs font-black uppercase tracking-widest text-blue-400">{post.authorName || 'Unknown User'}</div>
                  <div className="text-[10px] opacity-40 font-bold">{new Date(post.createdAt || '').toLocaleString()}</div>
                </div>
              </div>
              <div className="actions flex gap-2">
                {onEdit && (
                  <button onClick={() => onEdit(post)} className="p-2 rounded-lg bg-white/5 hover:bg-white/10 text-white/60 hover:text-white transition-all shadow-sm">
                    <Pencil size={14} />
                  </button>
                )}
                <button 
                  onClick={async () => {
                    if (await toastConfirm('Permanently remove this post from the global database?', { isDanger: true })) {
                      deletePost(post.id);
                    }
                  }} 
                  className="p-2 rounded-lg bg-red-500/10 hover:bg-red-500/20 text-red-500/60 hover:text-red-500 transition-all shadow-sm"
                >
                  <Trash2 size={14} />
                </button>
              </div>
            </div>

            <div className="card-body p-4 scale-[0.9] origin-top-left overflow-hidden max-h-[400px]">
              <DiscordPreview
                verses={[{ id: '1', ref: post.bibleReference || '', content: post.content || '' }]}
                customMessage={post.customMessage || ''}
                greeting={post.greeting || ''}
                customGreeting={post.customGreeting || ''}
                closing={post.closing || ''}
                customClosing={''}
                closingPosition={post.closingPosition || 'BELOW'}
                attachments={post.attachments ? JSON.parse(post.attachments) : []}
                scheduledAt={post.scheduledAt || post.createdAt || ''}
                privateReplyEnabled={!!post.privateReplyEnabled}
                riddleButtonEnabled={!!post.riddleButtonEnabled}
                riddleText={post.riddleText || ''}
              />
            </div>

            <div className="card-footer px-4 py-2 bg-black/40 flex justify-between items-center border-t border-white/5">
              <span className={`status-pill text-[10px] font-black uppercase tracking-widest px-2 py-0.5 rounded-full ${
                post.status === 'PUBLISHED' ? 'bg-green-500/10 text-green-500 border border-green-500/20' : 
                post.status === 'SCHEDULED' ? 'bg-blue-500/10 text-blue-500 border border-blue-500/20' : 
                'bg-white/10 text-white/40 border border-white/20'
              }`}>
                {post.status}
              </span>

              {post.shareSlug && (
                <a 
                  href={`/share/${post.shareSlug}`} 
                  target="_blank" 
                  rel="noreferrer"
                  className="text-[10px] font-black uppercase tracking-widest text-white/30 hover:text-white flex items-center gap-1 transition-colors"
                >
                  View Landing <ExternalLink size={10} />
                </a>
              )}
            </div>
          </div>
        ))}
      </div>

      {posts.length === 0 && (
        <div className="text-center py-20 opacity-30">
          <p className="font-black uppercase tracking-widest">Digital Silence</p>
          <p className="text-xs">No entries found for this segment.</p>
        </div>
      )}

      <div className="feed-footer mt-10 p-6 border-t border-white/5 text-center flex flex-col items-center">
        <p className="text-[10px] font-black uppercase tracking-[0.3em] opacity-20 mb-4">End of Transmission Sequence</p>
        <div className="pagination-controls flex items-center gap-4 bg-white/5 border border-white/10 rounded-full p-1 pl-4">
          <span className="text-xs font-black uppercase tracking-widest opacity-40">
            Page {page}
          </span>
          <div className="flex gap-1">
            <button 
              onClick={() => {
                setPage(p => Math.max(1, p - 1));
                window.scrollTo({ top: 0, behavior: 'smooth' });
              }}
              disabled={page === 1}
              className="p-2 rounded-full hover:bg-white/10 disabled:opacity-20 disabled:cursor-not-allowed transition-all"
            >
              <ChevronLeft size={18} />
            </button>
            <button 
              onClick={() => {
                setPage(p => p + 1);
                window.scrollTo({ top: 0, behavior: 'smooth' });
              }}
              disabled={posts.length < limit}
              className="p-2 rounded-full hover:bg-white/10 disabled:opacity-20 disabled:cursor-not-allowed transition-all"
            >
              <ChevronRight size={18} />
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

