import React, { useState, useEffect, useRef } from 'react';
import { motion } from 'framer-motion';

interface LoadingScreenProps {
  image1?: string | null;
  image2: string;
  userAvatar: string;
  mode: 'crossfade' | 'single';
  onComplete?: () => void;
}

export default function LoadingScreen({ image1, image2, userAvatar, mode, onComplete }: LoadingScreenProps) {
  const [phase, setPhase] = useState(mode === 'single' ? 1 : 0);
  const onCompleteRef = useRef(onComplete);

  useEffect(() => {
    onCompleteRef.current = onComplete;
  }, [onComplete]);

  useEffect(() => {
    let timer1: ReturnType<typeof setTimeout>;
    let timer2: ReturnType<typeof setTimeout>;
    let timer3: ReturnType<typeof setTimeout>;

    if (mode === 'crossfade') {
      // Phase 0: Show Image 1 (0s - 1.5s)
      // Phase 1: Crossfade to Image 2 (1.5s - 3.5s)
      // Phase 2: Spin, Spawn Avatar, and Separate (3.5s - 5.5s)
      // Phase 3: Pause facing forward (5.5s - 6.5s)
      // Phase 4: Trigger Glide to Navbar (6.5s)
      timer1 = setTimeout(() => setPhase(1), 1500);
      timer2 = setTimeout(() => setPhase(2), 3500);
      timer3 = setTimeout(() => {
        if (onCompleteRef.current) onCompleteRef.current();
      }, 6500);
    } else {
      // Single mode
      // Phase 1: Show Image 2 (0s - 2.5s)
      // Phase 2: Spin, Spawn Avatar, and Separate (2.5s - 4.5s)
      // Phase 3: Pause facing forward (4.5s - 5.5s)
      // Phase 4: Trigger Glide to Navbar (5.5s)
      timer2 = setTimeout(() => setPhase(2), 2500);
      timer3 = setTimeout(() => {
        if (onCompleteRef.current) onCompleteRef.current();
      }, 5500);
    }

    return () => {
      clearTimeout(timer1);
      clearTimeout(timer2);
      clearTimeout(timer3);
    };
  }, [mode]);

  return (
    <motion.div 
      className="fixed inset-0 flex flex-col items-center justify-center z-50 overflow-hidden"
    >
      {/* Background ambient glow - fades out on exit so layoutId elements can glide over the app */}
      <motion.div 
        className="absolute inset-0 bg-[#050814]"
        initial={{ opacity: 1 }}
        exit={{ opacity: 0 }}
        transition={{ duration: 0.8 }}
      >
        <motion.div 
          className="absolute inset-0 flex items-center justify-center opacity-40"
          animate={{
            background: phase === 0 
              ? 'radial-gradient(circle at center, rgba(30, 64, 175, 0.4) 0%, transparent 60%)' 
              : phase === 1
              ? 'radial-gradient(circle at center, rgba(14, 165, 233, 0.4) 0%, transparent 60%)'
              : 'radial-gradient(circle at center, rgba(16, 185, 129, 0.4) 0%, transparent 60%)'
          }}
          transition={{ duration: 1 }}
        />
      </motion.div>

      <div className="relative w-full max-w-2xl h-96 flex items-center justify-center" style={{ perspective: 1200 }}>

        {/* Image 1: Fades out during Phase 1 */}
        {mode === 'crossfade' && image1 && (
          <motion.img
            src={image1}
            alt="Loading 1"
            className="absolute w-64 h-64 md:w-80 md:h-80 object-contain drop-shadow-2xl"
            initial={{ opacity: 1 }}
            animate={{ opacity: phase >= 1 ? 0 : 1 }}
            transition={{ duration: 1.5, ease: "easeInOut" }}
          />
        )}

        {/* Image 2 (Logo): Fades in, then spins powerfully and moves left */}
        <motion.img
          layoutId="logo-glide"
          src={image2}
          alt="Loading 2"
          className="absolute w-64 h-64 md:w-80 md:h-80 object-contain drop-shadow-2xl z-10"
          initial={{ opacity: mode === 'single' ? 1 : 0, x: 0, rotateY: 0, scale: 1 }}
          animate={{ 
            opacity: phase >= 1 ? 1 : 0,
            x: phase >= 2 ? -180 : 0,
            rotateY: phase >= 2 ? 1080 : 0, // 3 full powerful spins
            scale: phase >= 2 ? 0.8 : 1
          }}
          transition={{ 
            opacity: { duration: 1.5, ease: "easeInOut" },
            x: { duration: 1.5, type: "spring", stiffness: 90, damping: 12 },
            rotateY: { duration: 2.2, type: "spring", stiffness: 60, damping: 10 }, // Elastic, powerful spin
            scale: { duration: 1.5, type: "spring", stiffness: 90, damping: 12 }
          }}
        />

        {/* User Avatar: Spawns from center, spins powerfully, and moves right */}
        <motion.img
          layoutId="user-avatar-glide"
          src={userAvatar}
          alt="User Avatar"
          className="absolute w-40 h-40 md:w-48 md:h-48 rounded-full border-4 border-emerald-500 object-cover drop-shadow-2xl z-20 bg-[#b6e3f4]"
          initial={{ opacity: 0, x: 0, rotateY: 0, scale: 0 }} // Start at 0
          animate={{ 
            opacity: phase >= 2 ? 1 : 0, 
            x: phase >= 2 ? 180 : 0, 
            rotateY: phase >= 2 ? -1080 : 0, // Spin to -1080
            scale: phase >= 2 ? 1 : 0 
          }}
          transition={{ 
            x: { duration: 1.5, type: "spring", stiffness: 90, damping: 12 },
            scale: { duration: 1.5, type: "spring", stiffness: 90, damping: 12 },
            rotateY: { duration: 2.2, type: "spring", stiffness: 60, damping: 10 }, // Elastic, powerful spin
            opacity: { duration: 0.3 } // Fade in quickly while spinning out
          }}
        />
      </div>

      {/* Loading Progress Bar */}
      <motion.div 
        className="absolute bottom-16 left-1/2 transform -translate-x-1/2 w-48 md:w-64 h-1 bg-gray-800/50 rounded-full overflow-hidden backdrop-blur-sm"
        exit={{ opacity: 0, transition: { duration: 0.3 } }}
      >
        <motion.div 
          className="h-full bg-gradient-to-r from-blue-600 to-emerald-400 rounded-full"
          initial={{ width: '0%' }}
          animate={{ width: '100%' }}
          transition={{ duration: mode === 'single' ? 5.5 : 6.5, ease: "linear" }}
        />
      </motion.div>

      {/* Loading Text */}
      <motion.div 
        className="absolute bottom-8 left-1/2 transform -translate-x-1/2 text-gray-400 text-sm font-medium tracking-widest uppercase"
        animate={{ opacity: [0.5, 1, 0.5] }}
        exit={{ opacity: 0, transition: { duration: 0.3 } }}
        transition={{ duration: 2, repeat: Infinity, ease: "easeInOut" }}
      >
        {phase === 0 ? 'Initializing' : phase === 1 ? (mode === 'single' ? 'Initializing' : 'Connecting') : 'Welcome'}
      </motion.div>
    </motion.div>
  );
}

