import React, { useState } from 'react';
import { Share2, Pencil, Trash2, MessageSquare, ChevronDown, RefreshCw, Shield as ShieldIcon } from 'lucide-react';
import { getScheduledPostWarning } from '../utils/share';
import { Post } from '../types';
import { toast } from 'react-hot-toast';
import { renderDiscordMarkdown } from '../utils/markdown';
import { DiscordPreview } from './DiscordPreview';
import { useData } from '../contexts/DataContext';
import { useAuth } from '../contexts/AuthContext';
import { resolveTemplate } from '../utils/template';

interface PostListProps {
    posts: Post[];
    setView: (view: any) => void;
    deletePost: (id: number) => void;
    isAdmin: boolean;
    isHost: boolean;
    onEdit: (post: Post) => void;
    onCopy: (post: Post) => void;
    clearPostsByStatus: (status: string) => void;
}

export const PostList: React.FC<PostListProps> = ({
    posts, setView, deletePost, isAdmin, isHost, onEdit, onCopy, clearPostsByStatus
}) => {
    const { platformSettings } = useData();
    const { user } = useAuth();
    const [activeTab, setActiveTab] = useState<'DRAFT' | 'SCHEDULED' | 'FAILED' | 'PUBLISHED'>('SCHEDULED');
    const [sortOption, setSortOption] = useState<'NEWEST' | 'OLDEST'>('NEWEST');
    const [currentPage, setCurrentPage] = useState<Record<string, number>>({
        DRAFT: 1,
        SCHEDULED: 1,
        FAILED: 1,
        PUBLISHED: 1
    });

    const ITEMS_PER_PAGE = 10;

    React.useEffect(() => {
        setCurrentPage({
            DRAFT: 1,
            SCHEDULED: 1,
            FAILED: 1,
            PUBLISHED: 1
        });
    }, [posts]);

    const sharePost = async (post: Post) => {
        if (!post.shareSlug) return;
        const url = `${window.location.origin}/share/${post.shareSlug}`;

        const templateData = {
            appName: 'I AM',
            appDescription: platformSettings?.ogDescription || 'A spiritual growth platform',
            greeting: post.customMessage || '',
            contents: post.content || '',
            username: user?.username || 'A community member',
            postUrl: url,
            postId: post.id.toString(),
            bibleRef: post.bibleReference || '',
            attachments: post.imageUrl || ''
        };

        const displayTitle = resolveTemplate(platformSettings?.ogTitle || '{{appName}}: {{bibleRef}}', templateData);
        let shareText = resolveTemplate(platformSettings?.ogShareText || 'Check out my post on {{appName}}! {{bibleRef}}', templateData);

        // Logic for scheduled posts: append a notice if it's in the future
        shareText += getScheduledPostWarning(post.scheduledAt, platformSettings?.scheduledPostNotice);

        const shareData = {
            title: displayTitle,
            text: shareText,
            url: url,
        };

        if (navigator.share && navigator.canShare && navigator.canShare(shareData)) {
            try {
                await navigator.share(shareData);
                return;
            } catch (err) {
                if ((err as Error).name !== 'AbortError') {
                    console.error('Share failed', err);
                } else {
                    return; // User cancelled
                }
            }
        }

        // Fallback to clipboard
        navigator.clipboard.writeText(url).then(() => {
            toast.success('Public link copied to clipboard!');
        }).catch(err => {
            console.error('Failed to copy link', err);
            toast.error('Failed to copy link');
        });
    };

    const handleRcsShare = async (post: Post) => {
        if (!post.shareSlug) return;

        const url = `${window.location.origin}/share/${post.shareSlug}`;
        const siteTitle = platformSettings?.ogTitle || 'I AM';
        const siteDesc = platformSettings?.ogDescription || `Check out this inspiration from ${siteTitle}!`;

        let displayTitle = siteTitle;
        let shareText = siteDesc;

        if (post.customMessage) {
            displayTitle = post.customMessage;
            shareText = post.bibleReference ? `📖 ${post.bibleReference} — ${post.content?.slice(0, 100)}...` : (post.content || shareText);
        } else if (post.bibleReference) {
            displayTitle = `${siteTitle}: ${post.bibleReference}`;
            shareText = post.content || shareText;
        }

        shareText += getScheduledPostWarning(post.scheduledAt, platformSettings?.scheduledPostNotice);

        const fullMsg = `${displayTitle}\n\n${shareText}\n\n${url}`;

        if ('contacts' in navigator && 'ContactsManager' in window) {
            try {
                const props = await (navigator as any).contacts.getProperties();
                if (props.includes('tel')) {
                    const contacts = await (navigator as any).contacts.select(['name', 'tel'], { multiple: false });
                    if (contacts.length > 0 && contacts[0].tel && contacts[0].tel.length > 0) {
                        const phone = contacts[0].tel[0];
                        const isIOS = /iPad|iPhone|iPod/.test(navigator.userAgent);
                        const smsUrl = isIOS 
                            ? `sms:${phone}&body=${encodeURIComponent(fullMsg)}` 
                            : `sms:${phone}?body=${encodeURIComponent(fullMsg)}`;
                        window.location.href = smsUrl;
                        return;
                    }
                }
            } catch (err) {
                console.error("Contact picker failed", err);
            }
        }

        const isIOS = /iPad|iPhone|iPod/.test(navigator.userAgent);
        const smsUrl = isIOS 
            ? `sms:&body=${encodeURIComponent(fullMsg)}` 
            : `sms:?body=${encodeURIComponent(fullMsg)}`;
        window.location.href = smsUrl;
    };

    const sortPosts = (postsToSort: Post[]) => {
        return [...postsToSort].sort((a, b) => {
            const timeA = new Date(a.scheduledAt || a.createdAt || 0).getTime();
            const timeB = new Date(b.scheduledAt || b.createdAt || 0).getTime();

            return sortOption === 'NEWEST' ? timeB - timeA : timeA - timeB;
        });
    };

    const groupedPosts = {
        DRAFT: sortPosts((posts || []).filter(p => p.status === 'DRAFT')),
        SCHEDULED: sortPosts((posts || []).filter(p => p.status === 'SCHEDULED')),
        FAILED: sortPosts((posts || []).filter(p => p.status === 'FAILED')),
        PUBLISHED: sortPosts((posts || []).filter(p => p.status === 'PUBLISHED')),
    };

    // Auto-switch tab if current is empty but others are not
    React.useEffect(() => {
        if (groupedPosts[activeTab].length === 0) {
            const firstNotEmpty = (['SCHEDULED', 'PUBLISHED', 'DRAFT', 'FAILED'] as const).find(s => groupedPosts[s].length > 0);
            if (firstNotEmpty) setActiveTab(firstNotEmpty);
        }
    }, [posts]);

    const hasAnyPosts = posts?.length > 0;

    return (
        <div className="post-management-view">
            {!hasAnyPosts ? (
                <div className="empty-state">
                    <MessageSquare size={48} />
                    <p>No messages found.</p>
                    <button onClick={() => setView('create')} className="btn-primary">
                        Create your first message
                    </button>
                </div>
            ) : (
                <>
                    <div className="summary-cards" style={{
                        display: 'grid',
                        gridTemplateColumns: 'repeat(auto-fit, minmax(150px, 1fr))',
                        gap: '1rem',
                        marginBottom: '2rem'
                    }}>
                        {(['DRAFT', 'SCHEDULED', 'FAILED', 'PUBLISHED'] as const).map(status => {
                            const count = groupedPosts[status].length;
                            const isActive = activeTab === status;
                            const colors = {
                                DRAFT: { bg: 'rgba(255, 255, 255, 0.05)', border: 'rgba(255, 255, 255, 0.1)', text: 'rgba(255, 255, 255, 0.8)', activeBorder: 'rgba(255,255,255,0.4)' },
                                SCHEDULED: { bg: 'rgba(88, 101, 242, 0.1)', border: 'rgba(88, 101, 242, 0.3)', text: '#5865f2', activeBorder: '#5865f2' },
                                FAILED: { bg: 'rgba(237, 66, 69, 0.1)', border: 'rgba(237, 66, 69, 0.3)', text: '#ed4245', activeBorder: '#ed4245' },
                                PUBLISHED: { bg: 'rgba(59, 165, 92, 0.1)', border: 'rgba(59, 165, 92, 0.3)', text: '#3ba55c', activeBorder: '#3ba55c' }
                            };
                            const config = colors[status];

                            return (
                                <div
                                    key={status}
                                    className={`summary-card status-card tour-status-${status} ${isActive ? 'active' : ''}`}
                                    data-status={status}
                                    onClick={() => setActiveTab(status)}
                                    style={{
                                        background: config.bg,
                                        border: `1px solid ${isActive ? config.activeBorder : config.border}`,
                                        padding: '1.25rem',
                                        borderRadius: '12px',
                                        cursor: 'pointer',
                                        transition: 'all 0.2s ease',
                                        display: 'flex',
                                        flexDirection: 'column',
                                        gap: '0.5rem',
                                        opacity: count === 0 && !isActive ? 0.3 : 1,
                                        transform: isActive ? 'translateY(-2px)' : 'none',
                                        boxShadow: isActive ? `0 8px 24px -8px ${config.text}44` : 'none'
                                    }}
                                >
                                    <span style={{ fontSize: '0.7rem', fontWeight: 800, textTransform: 'uppercase', letterSpacing: '0.05em', color: isActive ? 'white' : 'rgba(255,255,255,0.4)' }}>
                                        {status.toLowerCase()}
                                    </span>
                                    <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
                                        <span style={{ fontSize: '1.75rem', fontWeight: 800, color: config.text }}>{count}</span>
                                        <div style={{
                                            padding: '4px 8px',
                                            borderRadius: '6px',
                                            background: 'rgba(0,0,0,0.2)',
                                            fontSize: '0.7rem',
                                            color: 'rgba(255,255,255,0.6)'
                                        }}>
                                            {count === 1 ? 'Post' : 'Posts'}
                                        </div>
                                    </div>
                                </div>
                            );
                        })}
                    </div>

                    <div className="tab-controls" style={{
                        display: 'flex',
                        justifyContent: 'space-between',
                        alignItems: 'center',
                        marginBottom: '1.5rem',
                        padding: '0 0.5rem'
                    }}>
                        <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem' }}>
                            <span style={{ fontSize: '0.75rem', fontWeight: 800, textTransform: 'uppercase', opacity: 0.4 }}>Sort By:</span>
                            <div className="select-wrapper-mini" style={{ position: 'relative' }}>
                                <select 
                                    value={sortOption} 
                                    onChange={(e) => setSortOption(e.target.value as any)}
                                    style={{
                                        background: 'rgba(255,255,255,0.05)',
                                        border: '1px solid rgba(255,255,255,0.1)',
                                        color: 'white',
                                        padding: '4px 24px 4px 10px',
                                        borderRadius: '6px',
                                        fontSize: '0.8rem',
                                        fontWeight: 600,
                                        appearance: 'none',
                                        cursor: 'pointer'
                                    }}
                                >
                                    <option value="NEWEST">Newest First</option>
                                    <option value="OLDEST">Oldest First</option>
                                </select>
                                <ChevronDown size={14} style={{ position: 'absolute', right: '6px', top: '50%', transform: 'translateY(-50%)', pointerEvents: 'none', opacity: 0.5 }} />
                            </div>
                        </div>

                        {activeTab === 'FAILED' && groupedPosts.FAILED.length > 0 && (
                            <button
                                className="btn-clear-all"
                                onClick={() => clearPostsByStatus('FAILED')}
                                style={{
                                    background: 'rgba(237, 66, 69, 0.1)',
                                    border: '1px solid rgba(237, 66, 69, 0.2)',
                                    color: '#ed4245',
                                    padding: '4px 12px',
                                    borderRadius: '6px',
                                    fontSize: '0.75rem',
                                    fontWeight: 800,
                                    textTransform: 'uppercase',
                                    letterSpacing: '0.05em',
                                    cursor: 'pointer',
                                    transition: 'all 0.2s'
                                }}
                            >
                                Clear All Failures
                            </button>
                        )}
                    </div>

                    {(() => {
                        const group = groupedPosts[activeTab];
                        if (group.length === 0) {
                            return (
                                <div className="empty-state-mini" style={{ padding: '4rem 2rem', textAlign: 'center', background: 'rgba(255,255,255,0.02)', borderRadius: '16px', border: '1px dashed rgba(255,255,255,0.1)' }}>
                                    <MessageSquare size={32} style={{ opacity: 0.2, marginBottom: '1rem' }} />
                                    <p style={{ opacity: 0.5 }}>No {activeTab.toLowerCase()} messages yet.</p>
                                </div>
                            );
                        }

                        return (
                            <section key={activeTab} className={`status-group active-tab-section`}>
                                <div className="dashboard-grid">
                                    {(group || [])
                                        .slice(((currentPage[activeTab] || 1) - 1) * ITEMS_PER_PAGE, (currentPage[activeTab] || 1) * ITEMS_PER_PAGE)
                                            .map(post => {
                                            const bibleRef = post.bibleReference;
                                            const content = post.content || '';
                                            const customMsg = post.customMessage;
                                            const pos = post.customMessagePosition || 'ABOVE';

                                            let coreMessage = bibleRef ? `**${bibleRef}**\n\n${content}` : content;
                                            let fullMsg = coreMessage;
                                            if (post.riddleText) {
                                                fullMsg = `🧩 **Riddle:** ${post.riddleText}\n\n${fullMsg}`;
                                            }
                                            if (customMsg) {
                                                fullMsg = pos === 'BELOW' ? `${fullMsg}\n\n${customMsg}` : `${customMsg}\n\n${fullMsg}`;
                                            }

                                            let attachmentsList: string[] = [];
                                            if (post.attachments) {
                                                try {
                                                    attachmentsList = JSON.parse(post.attachments);
                                                } catch {
                                                    attachmentsList = post.imageUrl ? [post.imageUrl] : [];
                                                }
                                            } else if (post.imageUrl) {
                                                attachmentsList = [post.imageUrl];
                                            }

                                            return (
                                                <div key={post.id} className="post-card discord-themed-card">
                                                    <div className="discord-mock-mini" style={{ position: 'relative' }}>
                                                        {post.isTestMode && (
                                                            <div className="test-mode-badge" style={{
                                                                position: 'absolute',
                                                                top: '8px',
                                                                left: '8px',
                                                                background: 'var(--discord-blurple)',
                                                                color: 'white',
                                                                padding: '1px 6px',
                                                                borderRadius: '4px',
                                                                fontSize: '0.6rem',
                                                                fontWeight: 800,
                                                                zIndex: 10,
                                                                boxShadow: '0 2px 4px rgba(0,0,0,0.3)',
                                                                display: 'flex',
                                                                alignItems: 'center',
                                                                gap: '4px',
                                                                textTransform: 'uppercase',
                                                                letterSpacing: '0.05em'
                                                            }}>
                                                                <ShieldIcon size={10} /> Test Mode
                                                            </div>
                                                        )}
                                                        <div className="card-actions-inline">
                                                            {(isAdmin || isHost) && (post.status === 'PUBLISHED' || post.status === 'SCHEDULED') && post.shareSlug && (
                                                                <>
                                                                    <button onClick={() => sharePost(post)} className="action-button-modern share tour-share-btn" title="Share via Web Share">
                                                                        <Share2 size={14} /> SHARE
                                                                    </button>
                                                                    <button onClick={() => handleRcsShare(post)} className="action-button-modern share tour-rcs-btn" title="Share via RCS/SMS">
                                                                        <MessageSquare size={14} /> RCS
                                                                    </button>
                                                                    {post.status === 'PUBLISHED' && (
                                                                        <button onClick={() => onCopy(post)} className="action-button-modern tour-resend-btn" title="Send Again">
                                                                            <RefreshCw size={14} /> REPOST
                                                                        </button>
                                                                    )}
                                                                </>
                                                            )}
                                                            {(isAdmin || isHost) && (post.status !== 'PUBLISHED' || (post.recurrence && post.recurrence !== 'NONE')) && (
                                                                <button onClick={() => onEdit(post)} className="action-button-modern tour-edit-btn" title="Edit Message">
                                                                    <Pencil size={14} /> EDIT
                                                                </button>
                                                            )}
                                                            <button 
                                                                onClick={() => {
                                                                    toast((t) => (
                                                                        <div style={{ padding: '4px' }}>
                                                                            <span style={{ fontWeight: 600, display: 'block', marginBottom: '4px' }}>Delete message?</span>
                                                                            <p style={{ margin: '0 0 12px 0', fontSize: '0.8rem', opacity: 0.8 }}>Are you sure you want to delete this message?</p>
                                                                            <div style={{ display: 'flex', gap: '8px' }}>
                                                                                <button 
                                                                                    onClick={() => {
                                                                                        toast.dismiss(t.id);
                                                                                        deletePost(post.id);
                                                                                    }}
                                                                                    style={{ background: '#ed4245', color: 'white', border: 'none', padding: '6px 12px', borderRadius: '4px', cursor: 'pointer', fontSize: '0.75rem', fontWeight: 600 }}
                                                                                >
                                                                                    DELETE
                                                                                </button>
                                                                                <button 
                                                                                    onClick={() => toast.dismiss(t.id)}
                                                                                    style={{ background: 'rgba(255,255,255,0.1)', color: 'white', border: 'none', padding: '6px 12px', borderRadius: '4px', cursor: 'pointer', fontSize: '0.75rem', fontWeight: 600 }}
                                                                                >
                                                                                    CANCEL
                                                                                </button>
                                                                            </div>
                                                                        </div>
                                                                    ), { duration: 5000 });
                                                                }} 
                                                                className="action-button-modern delete" 
                                                                title="Delete Message"
                                                            >
                                                                <Trash2 size={14} /> DELETE
                                                            </button>
                                                        </div>

                                                        {post.status === 'FAILED' && post.errorMessage && (
                                                            <div className="failed-notice" style={{
                                                                margin: '0 1rem 1rem 1rem',
                                                                padding: '0.75rem',
                                                                background: 'rgba(237, 66, 69, 0.1)',
                                                                border: '1px solid rgba(237, 66, 69, 0.3)',
                                                                borderRadius: '6px',
                                                                display: 'flex',
                                                                flexDirection: 'column',
                                                                gap: '0.25rem'
                                                            }}>
                                                                <span style={{ fontSize: '0.7rem', fontWeight: 800, color: '#ff7b72', textTransform: 'uppercase', letterSpacing: '0.05em' }}>Delivery Error</span>
                                                                <span style={{ fontSize: '0.85rem', color: '#fff' }}>{post.errorMessage}</span>
                                                                <p style={{ fontSize: '0.75rem', color: 'rgba(255,255,255,0.6)', margin: 0 }}>Tip: Check bot permissions in your Discord server.</p>
                                                            </div>
                                                        )}

                                                        <div className="discord-message-wrapped">
                                                            <DiscordPreview
                                                                verses={[{ id: '1', ref: post.bibleReference || '', content: post.content || '' }]}
                                                                customMessage={post.customMessage || ''}
                                                                greeting={post.greeting || ''}
                                                                customGreeting={post.customGreeting || ''}
                                                                closing={post.closing || ''}
                                                                customClosing={''}
                                                                closingPosition={post.closingPosition || 'BELOW'}
                                                                attachments={attachmentsList}
                                                                scheduledAt={post.scheduledAt || post.createdAt || ''}
                                                                privateReplyEnabled={post.privateReplyEnabled === true}
                                                                riddleButtonEnabled={post.riddleButtonEnabled === true}
                                                                riddleText={post.riddleText || ''}
                                                                sectionOrder={post.sectionOrder ? JSON.parse(post.sectionOrder) : undefined}
                                                            />
                                                        </div>
                                                                <div className="discord-footer-status">
                                                                    <div style={{ display: 'flex', alignItems: 'center', gap: '8px', flexWrap: 'wrap' }}>
                                                                        <span className={`status-badge-inline ${post.status?.toLowerCase()}`}>{post.status}</span>
                                                                        {post.authorName && (
                                                                            <span className="author-badge" style={{ fontSize: '0.7rem', color: 'rgba(255,255,255,0.4)', fontWeight: 600 }}>
                                                                                by {post.authorName}
                                                                            </span>
                                                                        )}
                                                                    </div>
                                                                    {post.status === 'PUBLISHED' && post.scheduledAt && (
                                                                        <span className="discord-timestamp">Sent: {new Date(post.scheduledAt).toLocaleString()}</span>
                                                                    )}
                                                                    {post.status === 'SCHEDULED' && post.scheduledAt && (
                                                                        <span className="discord-timestamp">Scheduled: {new Date(post.scheduledAt).toLocaleString()}</span>
                                                                    )}
                                                                    {post.recurrence && post.recurrence !== 'NONE' && (
                                                                        <span className="recurrence-badge" style={{
                                                                            fontSize: '0.65rem',
                                                                            background: 'rgba(88, 101, 242, 0.15)',
                                                                            color: '#5865F2',
                                                                            padding: '2px 6px',
                                                                            borderRadius: '10px',
                                                                            fontWeight: 700,
                                                                            display: 'flex',
                                                                            alignItems: 'center',
                                                                            gap: '4px'
                                                                        }}>
                                                                            <RefreshCw size={10} /> {post.recurrence}
                                                                        </span>
                                                                    )}
                                                                </div>
                                                            </div>
                                                        </div>
                                                    );
                                        })}
                                    {group.length > ITEMS_PER_PAGE && (
                                        <div className="pagination-controls" style={{
                                            display: 'flex',
                                            alignItems: 'center',
                                            justifyContent: 'center',
                                            gap: '1.5rem',
                                            marginTop: '1.5rem',
                                            padding: '1rem',
                                            background: 'rgba(255,255,255,0.02)',
                                            borderRadius: '12px'
                                        }}>
                                            <button 
                                                onClick={() => setCurrentPage(prev => ({ ...prev, [activeTab]: Math.max(1, (prev[activeTab] || 1) - 1) }))}
                                                disabled={(currentPage[activeTab] || 1) === 1}
                                                className="btn-pagination"
                                                style={{
                                                    background: 'rgba(255,255,255,0.05)',
                                                    border: '1px solid rgba(255,255,255,0.1)',
                                                    color: 'white',
                                                    padding: '6px 16px',
                                                    borderRadius: '6px',
                                                    fontSize: '0.8rem',
                                                    fontWeight: 600,
                                                    cursor: (currentPage[activeTab] || 1) === 1 ? 'not-allowed' : 'pointer',
                                                    opacity: (currentPage[activeTab] || 1) === 1 ? 0.3 : 1
                                                }}
                                            >
                                                Previous
                                            </button>
                                            <span style={{ fontSize: '0.85rem', fontWeight: 700, opacity: 0.8 }}>
                                                Page {currentPage[activeTab] || 1} of {Math.ceil(group.length / ITEMS_PER_PAGE)}
                                            </span>
                                            <button 
                                                onClick={() => setCurrentPage(prev => ({ ...prev, [activeTab]: Math.min(Math.ceil(group.length / ITEMS_PER_PAGE), (prev[activeTab] || 1) + 1) }))}
                                                disabled={(currentPage[activeTab] || 1) >= Math.ceil(group.length / ITEMS_PER_PAGE)}
                                                className="btn-pagination"
                                                style={{
                                                    background: 'rgba(255,255,255,0.05)',
                                                    border: '1px solid rgba(255,255,255,0.1)',
                                                    color: 'white',
                                                    padding: '6px 16px',
                                                    borderRadius: '6px',
                                                    fontSize: '0.8rem',
                                                    fontWeight: 600,
                                                    cursor: (currentPage[activeTab] || 1) >= Math.ceil(group.length / ITEMS_PER_PAGE) ? 'not-allowed' : 'pointer',
                                                    opacity: (currentPage[activeTab] || 1) >= Math.ceil(group.length / ITEMS_PER_PAGE) ? 0.3 : 1
                                                }}
                                            >
                                                Next
                                            </button>
                                        </div>
                                    )}
                                </div>
                            </section>
                        );
                    })()}
                </>
            )}
        </div>
    );
};

import React, { useState, useEffect } from 'react';
import { Play, Radio, Headphones, Trophy, Eye, Shield, RefreshCw, Save, Activity } from 'lucide-react';
import { toast } from 'react-hot-toast';
import { useData } from '../contexts/DataContext';
import { useAuth } from '../contexts/AuthContext';

export const PresenceManager: React.FC = () => {
    const { botStatus, refreshStatus } = useData();
    const { token } = useAuth();

    const [presenceMsg, setPresenceMsg] = useState(botStatus?.message || '');
    const [activityType, setActivityType] = useState(botStatus?.type ?? 3);
    const [activityUrl, setActivityUrl] = useState(botStatus?.url || '');
    const [discordStatus, setDiscordStatus] = useState(botStatus?.status || 'online');
    const [isUpdating, setIsUpdating] = useState(false);

    useEffect(() => {
        if (botStatus) {
            setPresenceMsg(botStatus.message || '');
            setActivityType(botStatus.type ?? 3);
            setActivityUrl(botStatus.url || '');
            setDiscordStatus(botStatus.status || 'online');
        }
    }, [botStatus]);

    const getActivityIcon = (type: number) => {
        switch (type) {
            case 0: return <Play size={14} />;
            case 1: return <Radio size={14} />;
            case 2: return <Headphones size={14} />;
            case 3: return <Eye size={14} />;
            case 4: return <Shield size={14} />;
            case 5: return <Trophy size={14} />;
            default: return <Play size={14} />;
        }
    };

    const getActivityLabel = (type: number) => {
        switch (type) {
            case 0: return 'Playing';
            case 1: return 'Streaming';
            case 2: return 'Listening to';
            case 3: return 'Watching';
            case 4: return 'Trusting';
            case 5: return 'Competing in';
            default: return 'Playing';
        }
    };

    const getStatusColor = (status: string) => {
        switch (status) {
            case 'online': return '#3ba55c';
            case 'idle': return '#faa61a';
            case 'dnd': return '#ed4245';
            case 'invisible': return '#747f8d';
            default: return '#3ba55c';
        }
    };

    const handleUpdate = async () => {
        if (!token) return;

        setIsUpdating(true);
        try {
            const res = await fetch('/api/services/presence', {
                method: 'POST',
                headers: {
                    'Authorization': `Bearer ${token}`,
                    'Content-Type': 'application/json'
                },
                body: JSON.stringify({
                    message: presenceMsg,
                    type: activityType,
                    status: discordStatus,
                    activityUrl: activityType === 1 ? activityUrl : undefined
                })
            });
            const data = await res.json() as any;
            if (data.success) {
                refreshStatus();
                toast.success('Bot presence updated!');
            } else {
                toast.error('Failed to update: ' + (data.error || 'Unknown error'));
            }
        } catch {
            toast.error('Error connecting to API');
        } finally {
            setIsUpdating(false);
        }
    };

    return (
        <div className="admin-card" style={{ background: 'rgba(255, 255, 255, 0.02)', border: '1px solid rgba(255, 255, 255, 0.08)', borderRadius: '12px', padding: '1.5rem' }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem', marginBottom: '1.25rem' }}>
                <div style={{ background: 'rgba(88, 101, 242, 0.1)', color: 'var(--discord-blurple)', padding: '0.5rem', borderRadius: '8px' }}>
                    <Activity size={20} />
                </div>
                <div style={{ flex: 1 }}>
                    <h3 style={{ margin: 0, fontSize: '1.1rem' }}>Bot Discovery & Presence</h3>
                    <p className="text-secondary" style={{ fontSize: '0.8rem', margin: 0 }}>Configure how the bot appears to users on Discord.</p>
                </div>
            </div>

            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '1.5rem' }}>
                <div style={{ display: 'flex', flexDirection: 'column', gap: '1rem' }}>
                    <div className="input-group">
                        <label>Discord Status</label>
                        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: '0.5rem' }}>
                            {['online', 'idle', 'dnd', 'invisible'].map(s => (
                                <button
                                    key={s}
                                    onClick={() => setDiscordStatus(s)}
                                    style={{
                                        background: discordStatus === s ? 'rgba(255,255,255,0.1)' : 'transparent',
                                        border: '1px solid',
                                        borderColor: discordStatus === s ? getStatusColor(s) : 'transparent',
                                        borderRadius: '4px', padding: '0.6rem', cursor: 'pointer',
                                        display: 'flex', justifyContent: 'center', transition: 'all 0.2s'
                                    }}
                                    title={s.toUpperCase()}
                                >
                                    <div style={{ width: '14px', height: '14px', borderRadius: '50%', background: getStatusColor(s) }}></div>
                                </button>
                            ))}
                        </div>
                    </div>

                    <div className="input-group">
                        <label>Activity Type</label>
                        <select
                            className="dropdown-select"
                            value={activityType}
                            onChange={(e) => setActivityType(parseInt(e.target.value))}
                        >
                            <option value={0}>Playing</option>
                            <option value={1}>Streaming</option>
                            <option value={2}>Listening to</option>
                            <option value={3}>Watching</option>
                            <option value={4}>Trusting</option>
                            <option value={5}>Competing in</option>
                        </select>
                    </div>

                    <div className="input-group">
                        <label>Status Message</label>
                        <input
                            type="text"
                            className="text-input"
                            value={presenceMsg}
                            onChange={(e) => setPresenceMsg(e.target.value)}
                            placeholder="e.target the scriptures..."
                        />
                    </div>

                    {activityType === 1 && (
                        <div className="input-group animate-in">
                            <label>Streaming URL</label>
                            <input
                                type="url"
                                className="text-input"
                                value={activityUrl}
                                onChange={(e) => setActivityUrl(e.target.value)}
                                placeholder="https://twitch.tv/..."
                            />
                        </div>
                    )}
                </div>

                <div style={{ display: 'flex', flexDirection: 'column', gap: '1rem' }}>
                    <div style={{ background: '#1e1f22', borderRadius: '8px', padding: '1rem', border: '1px solid #111214', height: 'fit-content' }}>
                        <div style={{ fontSize: '0.65rem', color: '#949ba4', textTransform: 'uppercase', fontWeight: 'bold', marginBottom: '0.75rem', letterSpacing: '0.05em' }}>Discord Preview</div>
                        <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
