import React from 'react';
import { Sparkles } from 'lucide-react';
import { CharacterCounter } from './CharacterCounter';

interface RiddleManagerProps {
    riddleText: string;
    setRiddleText: (text: string) => void;
    riddleAnswer: string;
    setRiddleAnswer: (answer: string) => void;
    riddleAliases: string;
    setRiddleAliases: (aliases: string) => void;
    isRiddleLocked: boolean;
    setIsRiddleLocked: (locked: boolean) => void;
    isAnswerLocked: boolean;
    setIsAnswerLocked: (locked: boolean) => void;
}

export const RiddleManager: React.FC<RiddleManagerProps> = ({
    riddleText, setRiddleText,
    riddleAnswer, setRiddleAnswer,
    riddleAliases, setRiddleAliases,
    isRiddleLocked, setIsRiddleLocked,
    isAnswerLocked, setIsAnswerLocked
}) => {
    const generateRiddle = (type: 'spiritual' | 'general') => {
        const riddles = {
            spiritual: [
                { q: "I was not born, but I was created. I was not a child, but I was a man. Who am I?", a: "Adam" },
                { q: "I have no voice, yet I speak to all. I have no pages, yet I tell a story. What am I?", a: "Creation" },
                { q: "I am the beginning of eternity, the end of time and space. What am I?", a: "The letter E" }
            ],
            general: [
                { q: "The more of this there is, the less you see. What is it?", a: "Darkness" },
                { q: "I speak without a mouth and hear without ears. I have no body, but I come alive with wind. What am I?", a: "An Echo" },
                { q: "What comes once in a minute, twice in a moment, but never in a thousand years?", a: "The letter M" }
            ]
        };
        const pool = riddles[type];
        const picked = pool[Math.floor(Math.random() * pool.length)];
        setRiddleText(picked.q);
        setRiddleAnswer(picked.a);
    };

    return (
        <div className="riddle-manager-container">
            <div className="input-group">
                <label>Generate Riddle (Optional)</label>
                <div className="greeting-options">
                    <button className="greet-btn" onClick={() => generateRiddle('spiritual')}>
                        <Sparkles size={14} className="mr-1" /> Spiritual
                    </button>
                    <button className="greet-btn" onClick={() => generateRiddle('general')}>
                        <Sparkles size={14} className="mr-1" /> General
                    </button>
                </div>
            </div>

            <div className="input-group">
                <label className="input-label-vertical">
                    <span>Riddle Content</span>
                    <label className="toggle-switch mini" style={{ marginTop: '0.25rem' }}>
                        <input
                            type="checkbox"
                            checked={isRiddleLocked}
                            onChange={() => setIsRiddleLocked(!isRiddleLocked)}
                        />
                        <span className="toggle-slider"></span>
                        <span className="toggle-label" style={{ fontSize: '0.7rem' }}>
                            {isRiddleLocked ? 'Locked' : 'Unlocked'}
                        </span>
                    </label>
                </label>
                <textarea
                    placeholder="A riddle that appears above the answer button..."
                    rows={3}
                    value={riddleText}
                    disabled={isRiddleLocked}
                    onChange={(e) => setRiddleText(e.target.value)}
                    style={{
                        opacity: isRiddleLocked ? 0.7 : 1,
                        cursor: isRiddleLocked ? 'not-allowed' : 'text',
                        marginBottom: '0.25rem'
                    }}
                ></textarea>
                <CharacterCounter current={riddleText.length} limit={2048} showAlways />
            </div>

            <div className="input-group">
                <label className="input-label-vertical">
                    <span>Riddle Answer</span>
                    <label className="toggle-switch mini" style={{ marginTop: '0.25rem' }}>
                        <input
                            type="checkbox"
                            checked={isAnswerLocked}
                            onChange={() => setIsAnswerLocked(!isAnswerLocked)}
                        />
                        <span className="toggle-slider"></span>
                        <span className="toggle-label" style={{ fontSize: '0.7rem' }}>
                            {isAnswerLocked ? 'Locked' : 'Unlocked'}
                        </span>
                    </label>
                </label>
                <textarea
                    placeholder="The correct answer to the riddle..."
                    rows={2}
                    value={riddleAnswer}
                    disabled={isAnswerLocked}
                    onChange={(e) => setRiddleAnswer(e.target.value)}
                    style={{ opacity: isAnswerLocked ? 0.7 : 1, cursor: isAnswerLocked ? 'not-allowed' : 'text', marginBottom: '0.25rem' }}
                ></textarea>
                <CharacterCounter current={riddleAnswer.length} limit={1024} showAlways />
            </div>

            <div className="input-group">
                <label className="input-label-vertical">
                    <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', width: '100%' }}>
                        <span>Acceptable Alternate Answers</span>
                        <button
                            className="greet-btn mini tour-suggest-btn"
                            onClick={() => {
                                const answer = riddleAnswer.trim().toLowerCase();
                                let suggestions: string[] = [];

                                // Common biblical/riddle suggestion logic
                                if (answer === 'adam') suggestions = ['The first man', 'First man'];
                                if (answer === 'creation') suggestions = ['Nature', 'God\'s creation', 'The universe'];
                                if (answer === 'darkness') suggestions = ['Dark', 'The dark', 'Night'];
                                if (answer === 'echo') suggestions = ['An Echo', 'Sound'];
                                if (answer.includes('letter')) suggestions = [answer.split(' ').pop() || ''];

                                if (suggestions.length > 0) {
                                    const current = riddleAliases ? riddleAliases.split(',').map(s => s.trim()) : [];
                                    const unique = Array.from(new Set([...current, ...suggestions])).filter(Boolean);
                                    setRiddleAliases(unique.join(', '));
                                }
                            }}
                            style={{ padding: '2px 8px', fontSize: '0.65rem' }}
                            disabled={!riddleAnswer || isAnswerLocked}
                        >
                            Suggest
                        </button>
                    </div>
                    <span style={{ fontSize: '0.65rem', color: 'rgba(255,255,255,0.4)', fontWeight: 400 }}>Comma-separated alternatives (case-insensitive)</span>
                </label>
                <textarea
                    className="tour-alternate-answers"
                    placeholder="e.g. Jesus Christ, The Messiah, Savior"
                    rows={2}
                    value={riddleAliases}
                    disabled={isAnswerLocked}
                    onChange={(e) => setRiddleAliases(e.target.value)}
                    style={{
                        opacity: isAnswerLocked ? 0.7 : 1,
                        cursor: isAnswerLocked ? 'not-allowed' : 'text',
                        marginTop: '0.5rem',
                        marginBottom: '0.25rem'
                    }}
                ></textarea>
                <CharacterCounter current={riddleAliases.length} limit={1024} />
            </div>
        </div>
    );
};

import React from 'react';
import { Book, X, Sparkles, MessageSquare, Eye } from 'lucide-react';
import { Post } from '../types';
import { renderDiscordMarkdown } from '../utils/markdown';
import {
  DiscordMessages,
  DiscordMessage,
  DiscordAttachments,
  DiscordImageAttachment,
  DiscordEmbed,
  DiscordEmbedDescription
} from './discord/DiscordUi';

interface SharedPostViewProps {
    post: Post;
    onClose: () => void;
}

export const SharedPostView: React.FC<SharedPostViewProps> = ({ post, onClose }) => {

    const getGreetingText = () => {
        if (post.greeting === 'dynamic-day') {
            try {
                const date = post.scheduledAt ? new Date(post.scheduledAt) : new Date();
                if (isNaN(date.getTime())) return "Hello!";
                const day = new Intl.DateTimeFormat('en-US', { weekday: 'long' }).format(date);
                return `**Hello, Happy ${day}!**`;
            } catch {
                return "Hello!";
            }
        }
        if (post.greeting === 'dynamic-time') {
            try {
                const date = post.scheduledAt ? new Date(post.scheduledAt) : new Date();
                if (isNaN(date.getTime())) return "Hello!";
                const hour = date.getHours();
                let timeOfDay = 'Evening';
                if (hour < 12) timeOfDay = 'Morning';
                else if (hour < 17) timeOfDay = 'Afternoon';

                const day = new Intl.DateTimeFormat('en-US', { weekday: 'long' }).format(date);
                return `**Good ${timeOfDay}, ${day}!**`;
            } catch {
                return "Hello!";
            }
        }
        if (post.greeting === 'custom') return post.customGreeting;
        return post.greeting;
    };

    const getFullContent = () => {
        const gText = getGreetingText();
        const cText = post.closing;
        const bText = (post.bibleReference && post.content)
            ? `**${post.bibleReference}**\n\n${post.content}`
            : (post.bibleReference ? `**${post.bibleReference}**` : post.content);

        const sectionOrder = post.sectionOrder ? JSON.parse(post.sectionOrder) : ['GREETING', 'RIDDLE', 'BIBLE', 'CUSTOM', 'MEDIA', 'CLOSING'];

        const sectionMap: Record<string, string> = {
            'GREETING': gText || '',
            'RIDDLE': post.riddleText ? `🧩 **Riddle Challenge**\n${post.riddleText}` : '',
            'BIBLE': bText || '',
            'CUSTOM': post.customMessage || '',
            'CLOSING': post.closingPosition === 'ABOVE' ? cText || '' : ''
        };

        const sections: string[] = [];
        for (const type of sectionOrder) {
            const content = sectionMap[type];
            if (!content) continue;
            sections.push(content);
        }

        return sections.filter(Boolean).join('\n\n');
    };

    const getBelowClosing = () => {
        if (post.closing && post.closingPosition === 'BELOW') {
            return post.closing;
        }
        return null;
    };

    const attachments = post.attachments ? JSON.parse(post.attachments as string) : (post.imageUrl ? [post.imageUrl] : []);

    return (
        <div className="onboarding-overlay" style={{
            position: 'fixed', inset: 0, backgroundColor: 'rgba(0,0,0,0.85)',
            backdropFilter: 'blur(4px)', zIndex: 9999, display: 'flex',
            alignItems: 'flex-start', justifyContent: 'center', padding: '2rem 1rem',
            overflowY: 'auto'
        }}>
            <div className="onboarding-modal" style={{
                background: '#1e1f22', borderRadius: '12px', padding: '2rem',
                maxWidth: '600px', width: '100%', position: 'relative',
                boxShadow: '0 10px 30px rgba(0,0,0,0.5)', border: '1px solid #313338',
                margin: 'auto'
            }}>
                <button onClick={onClose} style={{ position: 'absolute', top: '1rem', right: '1rem', background: 'transparent', border: 'none', color: '#949ba4', cursor: 'pointer' }}>
                    <X size={24} />
                </button>

                <div style={{ marginBottom: '1.5rem' }}>
                    <h2 style={{ fontSize: '1.25rem', margin: 0, color: '#f2f3f5', display: 'flex', alignItems: 'center', gap: '8px' }}>
                        <Eye size={20} className="text-primary" /> Shared Post
                    </h2>
                    <p style={{ color: '#b5bac1', margin: '4px 0 0', fontSize: '0.85rem' }}>
                        Viewing post ID: {post.id}
                    </p>
                </div>

                <div className="animate-entrance" style={{ 
                    padding: '1.5rem',
                    borderRadius: '12px',
                    boxShadow: '0 10px 30px rgba(0,0,0,0.3)',
                    border: '1px solid rgba(212, 175, 55, 0.1)',
                    marginBottom: '1rem'
                }}>
                    <DiscordMessages>
                        <DiscordMessage 
                            author="I AM" 
                            avatar="/brand/logo-circle.png" 
                            bot={true} 
                            verified={true}
                            timestamp={new Date(post.scheduledAt || post.createdAt || Date.now()).toLocaleString('en-US', {
                                month: 'short', day: 'numeric', year: 'numeric',
                                hour: 'numeric', minute: '2-digit'
                            })}
                        >
                            <div dangerouslySetInnerHTML={{ __html: renderDiscordMarkdown(getFullContent()) }} />

                            {attachments && attachments.length > 0 && (
                                <DiscordAttachments slot="attachments">
                                    {attachments.map((url: string, i: number) => (
                                        <DiscordImageAttachment key={i} url={url} alt={`Attachment ${i}`} />
                                    ))}
                                </DiscordAttachments>
                            )}

                            {getBelowClosing() && (
                                <DiscordEmbed slot="embeds" color="#d4af37">
                                    <DiscordEmbedDescription slot="description">
                                        <div dangerouslySetInnerHTML={{ __html: renderDiscordMarkdown(getBelowClosing()!) }} />
                                    </DiscordEmbedDescription>
                                </DiscordEmbed>
                            )}
                        </DiscordMessage>
                    </DiscordMessages>
                </div>

                <div style={{ marginTop: '2rem' }}>
                    <button onClick={onClose} className="btn-primary" style={{ width: '100%' }}>
                        Close Post
                    </button>
                </div>
            </div>
        </div>
    );
};

