import React, { useState, useEffect } from 'react';
import { startRegistration, startAuthentication } from '@simplewebauthn/browser';
import { Fingerprint, Loader2, ShieldAlert } from 'lucide-react';
import { useAuth } from '../../contexts/AuthContext';

interface PasskeyChallengeProps {
  onSuccess: () => void;
  onCancel?: () => void;
  appName?: string;
  children?: React.ReactNode;
}

export function PasskeyChallenge({ onSuccess, onCancel, appName, children }: PasskeyChallengeProps) {
  const { token, setToken, user } = useAuth();
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [mode, setMode] = useState<'auth' | 'register'>('auth');
  const [verified, setVerified] = useState(false);
  const [preFetchedOptions, setPreFetchedOptions] = useState<any>(null);

  // Pre-fetch challenge to ensure clean user gesture on click
  useEffect(() => {
    const preFetch = async () => {
      try {
        const endpoint = mode === 'auth' ? '/api/admin/webauthn/generate-auth' : '/api/admin/webauthn/generate-registration';
        const resp = await fetch(endpoint, { 
          method: 'POST',
          headers: { 'Authorization': `Bearer ${token}` }
        });

        if (resp.status === 404 && mode === 'auth') {
          setMode('register');
          return;
        }

        if (resp.ok) {
          const options = await resp.json();
          console.log(`[PasskeyChallenge] Pre-fetched ${mode} options:`, options);
          setPreFetchedOptions(options);
        }
      } catch (err) {
        console.warn('[PasskeyChallenge] Failed to pre-fetch options:', err);
      }
    };

    preFetch();
  }, [mode, token]);

  const initiateChallenge = async () => {
    console.log(`[PasskeyChallenge] Initiating ${mode} challenge...`);
    setLoading(true);
    setError(null);
    try {
      if (mode === 'auth') {
        let options = preFetchedOptions;

        if (!options) {
          console.log('[PasskeyChallenge] No pre-fetched options, fetching now...');
          const resp = await fetch('/api/admin/webauthn/generate-auth', { 
            method: 'POST',
            headers: { 'Authorization': `Bearer ${token}` }
          });
          if (resp.status === 404) {
            setMode('register');
            return;
          }
          if (!resp.ok) {
            const data = await resp.json().catch(() => ({ error: `Server error ${resp.status}` }));
            throw new Error((data as any).error || 'Failed to generate auth challenge');
          }
          options = await resp.json();
        }

        console.log('[PasskeyChallenge] Starting biometric prompt with options:', options);
        const asseResp = await startAuthentication({ 
          optionsJSON: options,
          mediation: 'optional'
        } as any);
        console.log('[PasskeyChallenge] Authentication successful, verifying with server...');

        const verificationResp = await fetch('/api/admin/webauthn/verify-auth', {
          method: 'POST',
          headers: { 
            'Content-Type': 'application/json',
            'Authorization': `Bearer ${token}`
          },
          body: JSON.stringify({ assertion: asseResp }),
        });

        if (verificationResp.ok) {
          const data = await verificationResp.json() as any;
          if (data.token) {
            setToken(data.token);
          }
          setVerified(true);
          onSuccess();
        } else {
          const data = (await verificationResp.json().catch(() => ({ error: 'Verification failed' }))) as any;
          setError((data as any).error || 'Verification failed');
        }
      } else {
        let options = preFetchedOptions;

        if (!options) {
          const resp = await fetch('/api/admin/webauthn/generate-registration', { 
            method: 'POST',
            headers: { 'Authorization': `Bearer ${token}` }
          });
          if (!resp.ok) {
            const data = await resp.json().catch(() => ({ error: `Server error ${resp.status}` }));
            throw new Error((data as any).error || 'Failed to generate registration challenge');
          }
          options = await resp.json();
        }

        console.log('[PasskeyChallenge] Starting registration prompt with options:', options);
        const attResp = await startRegistration({ optionsJSON: options });
        console.log('[PasskeyChallenge] Registration successful, verifying with server...');

        const verificationResp = await fetch('/api/admin/webauthn/verify-registration', {
          method: 'POST',
          headers: { 
            'Content-Type': 'application/json',
            'Authorization': `Bearer ${token}`
          },
          body: JSON.stringify({ attestation: attResp, name: 'Admin Step-Up Key' }),
        });

        if (verificationResp.ok) {
          setVerified(true);
          onSuccess();
        } else {
          const data = (await verificationResp.json().catch(() => ({ error: 'Registration failed' }))) as any;
          setError((data as any).error || 'Registration failed');
        }
      }
    } catch (err: any) {
      console.error('[PasskeyChallenge] Error during challenge:', err);

      // Handle specific WebAuthn errors
      if (err.name === 'NotAllowedError') {
        setError('The operation either timed out or was not allowed. Please ensure your passkey manager (like 1Password) is ready and try again.');
      } else if (err.name === 'SecurityError') {
        setError('A security error occurred. This often happens if the domain does not match your passkey.');
      } else if (err.name === 'AbortError') {
        // Silently handle aborts (user cancelled)
      } else {
        setError(err.message || 'Passkey verification failed or cancelled');
      }
    } finally {
      setLoading(false);
    }
  };

  if (verified && children) {
    return <>{children}</>;
  }

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/60 backdrop-blur-md">
      <div className="bg-white dark:bg-zinc-900 border border-zinc-200 dark:border-zinc-800 rounded-2xl p-8 max-w-sm w-full mx-4 shadow-2xl relative overflow-hidden">
        {/* Subtle glow effect */}
        <div className="absolute top-0 left-1/2 -translate-x-1/2 w-32 h-32 bg-indigo-500/20 rounded-full blur-3xl pointer-events-none" />

        <div className="relative flex flex-col items-center text-center">
          <div className="w-16 h-16 rounded-full bg-indigo-100 dark:bg-indigo-900/30 flex items-center justify-center mb-6 ring-4 ring-white dark:ring-zinc-900 border border-indigo-200 dark:border-indigo-800/50">
            <Fingerprint className="w-8 h-8 text-indigo-600 dark:text-indigo-400" strokeWidth={1.5} />
          </div>

          <h3 className="text-xl font-medium text-zinc-900 dark:text-zinc-100 mb-2 font-display tracking-tight">
            Secure Access
          </h3>
          <p className="text-sm text-zinc-500 dark:text-zinc-400 mb-8 max-w-[260px] leading-relaxed">
            {mode === 'auth' 
              ? `Verify your account with a passkey to access ${appName || 'Admin Tools'}.` 
              : 'Secure your account by registering a hardware passkey.'}
          </p>

          {error && (
            <div className="w-full bg-red-50 dark:bg-red-900/10 border border-red-200 dark:border-red-900/30 rounded-xl p-3 flex items-start gap-3 mb-6 text-left">
              <ShieldAlert className="w-5 h-5 text-red-500 dark:text-red-400 shrink-0 mt-0.5" />
              <p className="text-sm text-red-600 dark:text-red-400 font-medium">Authentication Failed<br/><span className="text-xs opacity-80 break-words">{error}</span></p>
            </div>
          )}

            <div className="w-full space-y-4">
              <button
                onClick={initiateChallenge}
                disabled={loading}
                className="w-full h-11 rounded-full bg-zinc-900 dark:bg-white text-white dark:text-zinc-900 font-medium text-sm flex items-center justify-center gap-2 hover:bg-zinc-800 dark:hover:bg-zinc-100 transition-all focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-zinc-900 dark:focus:ring-white dark:focus:ring-offset-zinc-900 disabled:opacity-50 disabled:cursor-not-allowed group shadow-sm active:scale-[0.98]"
              >
                {loading ? (
                  <Loader2 className="w-4 h-4 animate-spin" />
                ) : (
                  <>
                    Use Passkey
                    <Fingerprint className="w-4 h-4 opacity-50 group-hover:opacity-100 transition-opacity" />
                  </>
                )}
              </button>
            </div>

          <button 
            type="button"
            onClick={() => onCancel ? onCancel() : window.history.back()}
            className="mt-6 text-xs font-medium text-zinc-500 hover:text-zinc-800 dark:hover:text-zinc-300 transition-colors"
          >
            Cancel and Return
          </button>
        </div>
      </div>
    </div>
  );
}

/** @jsxImportSource react */
import React, { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import { Shield, Key, Fingerprint, Trash2, Plus, RefreshCw, AlertTriangle } from 'lucide-react';
import { startRegistration } from '@simplewebauthn/browser';
import { toast } from 'react-hot-toast';
import { toastConfirm } from '../common';
import { useAuth } from '@/contexts/AuthContext';
import { getPasskeyMetadata } from '@/utils/passkey-metadata';

const rawApiUrl = import.meta.env.VITE_API_URL;
const API_URL = rawApiUrl === 'undefined' || !rawApiUrl ? '' : rawApiUrl;

interface Passkey {
  id: string;
  name: string | null;
  aaguid: string | null;
  createdAt: string;
  counter: number;
  backedUp?: boolean | number;
  lastUsedAt?: string | null;
}

export const PasskeyModule = () => {
  const { token } = useAuth();
  const [passkeys, setPasskeys] = useState<Passkey[]>([]);
  const [loading, setLoading] = useState(true);
  const [registering, setRegistering] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editName, setEditName] = useState('');

  useEffect(() => {
    fetchPasskeys();
  }, [token]);

  const fetchPasskeys = async () => {
    try {
      const res = await fetch(`${API_URL}/api/auth/webauthn/passkeys`, {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      if (!res.ok) throw new Error('Failed to fetch passkeys');
      const data = await res.json() as any as any;
      setPasskeys(data.passkeys || []);
    } catch (err) {
      toast.error('Error: Could not load passkeys.');
    } finally {
      setLoading(false);
    }
  };

  const saveName = async (id: string) => {
    try {
      const res = await fetch(`${API_URL}/api/auth/webauthn/passkeys/${id}`, { 
        method: 'PATCH',
        headers: { 
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify({ name: editName })
      });
      if (!res.ok) throw new Error('Failed to rename parameter');

      setPasskeys(p => p.map(k => k.id === id ? { ...k, name: editName } : k));
      setEditingId(null);
      toast.success('Name Updated: Your passkey label was updated.');
    } catch (err) {
      toast.error('Update Failed: Unable to rename the passkey.');
    }
  };

  const deletePasskey = async (id: string) => {
    if (!await toastConfirm('Are you sure you want to delete this passkey? If this is your last one, you might lose access to administrative features.', { isDanger: true })) return;

    try {
      const res = await fetch(`${API_URL}/api/auth/webauthn/passkeys/${id}`, { 
        method: 'DELETE',
        headers: { 'Authorization': `Bearer ${token}` }
      });
      if (!res.ok) throw new Error('Failed to revoke passkey');

      setPasskeys(p => p.filter(k => k.id !== id));
      toast.success('Passkey Deleted: The selected passkey has been removed.');
    } catch (err) {
      toast.error('Delete Failed: Could not remove the passkey.');
    }
  };

  const generatePasskey = async () => {
    setRegistering(true);
    try {
      // 1. Get Challenge
      const challengeRes = await fetch(`${API_URL}/api/auth/webauthn/generate-registration`, { 
        method: 'POST',
        headers: { 'Authorization': `Bearer ${token}` }
      });
      const options = await challengeRes.json() as any;

      if (!challengeRes.ok) {
        throw new Error(options.error || 'Challenge generation failed');
      }

      // 2. Invoke Biometric Hardware
      const attResp = await startRegistration({ optionsJSON: options });

      // 3. Verify Hardware Response
      const verifyRes = await fetch(`${API_URL}/api/auth/webauthn/verify-registration`, {
        method: 'POST',
        headers: { 
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify(attResp),
      });

      if (!verifyRes.ok) {
        let errMsg = 'Passkey verification failed.';
        try {
          const bodyJson = await verifyRes.json() as any;
          if (bodyJson.error) errMsg = bodyJson.error;
        } catch(e) {}
        throw new Error(errMsg);
      }

      toast.success('Security Updated: Successfully added a new passkey to your account.');
      fetchPasskeys(); // Refresh the list
    } catch (err: any) {
      console.error(err);
      toast.error(err.message || 'Registration Cancelled: The process was interrupted.');
    } finally {
      setRegistering(false);
    }
  };

  return (
