import React from 'react';
import { createPortal } from 'react-dom';
import { toast } from 'react-hot-toast';
import { ShieldAlert, AlertCircle, CheckCircle2 } from 'lucide-react';

export const toastAlert = (msg: string, type: 'success' | 'error' | 'info' = 'info') => {
  if (type === 'error') {
    toast.error(msg);
  } else if (type === 'success') {
    toast.success(msg);
  } else {
    toast(msg);
  }
};

export interface ConfirmOptions {
  confirmText?: string;
  cancelText?: string;
  isDanger?: boolean;
  title?: string;
}

export const toastConfirm = (message: string, options: ConfirmOptions = {}): Promise<boolean> => {
  const { confirmText = 'Confirm', cancelText = 'Cancel', isDanger = false, title = 'Confirm Action' } = options;

  return new Promise((resolve) => {
    toast.custom((t) => createPortal(
      <div 
        className={`${t.visible ? 'animate-in' : 'animate-out'}`}
        style={{
          position: 'fixed',
          top: 0,
          left: 0,
          right: 0,
          bottom: 0,
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          zIndex: 10001,
          pointerEvents: 'none'
        }}
      >
        {/* Semi-transparent backdrop */}
        <div 
          style={{
            position: 'fixed',
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            background: 'rgba(0, 0, 0, 0.7)',
            backdropFilter: 'blur(4px)',
            pointerEvents: 'auto',
            zIndex: 10001
          }}
          onClick={() => {
            toast.dismiss(t.id);
            resolve(false);
          }}
        />

        <div className="confirm-toast-container" style={{ pointerEvents: 'auto', position: 'relative', zIndex: 10002 }}>
          <div className="confirm-toast-header">
            {isDanger ? <ShieldAlert size={20} /> : <AlertCircle size={20} />}
            <span style={{ fontWeight: 800, textTransform: 'uppercase', letterSpacing: '0.05em', fontSize: '0.85rem' }}>
              {title}
            </span>
          </div>

          <div className="confirm-toast-body">
            {message}
          </div>

          <div className="confirm-toast-actions">
            <button 
              className="confirm-toast-cancel"
              onClick={() => {
                toast.dismiss(t.id);
                resolve(false);
              }}
            >
              {cancelText}
            </button>
            <button 
              className={`confirm-toast-confirm ${isDanger ? 'danger' : ''}`}
              onClick={() => {
                toast.dismiss(t.id);
                resolve(true);
              }}
            >
              {confirmText}
            </button>
          </div>
        </div>
      </div>,
      document.body
    ), { duration: Infinity });
  });
};

export const useToast = () => ({
  addToast: (msg: any, type?: any) => {
    if (type === "error") {
      console.error(msg);
      toast.error(msg);
    } else if (type === "success") {
      toast.success(msg);
    } else {
      toast(msg);
    }
  }
});

