 */
export const OnboardingTour = (props: any) => {
  const { steps = [], tourKey = 'default' } = props;
  useEffect(() => {
    const hasCompletedTour = localStorage.getItem(`gp_tour_complete_${tourKey}`);

    if (!hasCompletedTour) {
      const driverObj = driver({
