import React, { useState, useEffect } from 'react';

interface InlineToastProps {
  message: string;
  type?: 'success' | 'error' | 'confirm' | 'info';
  show?: boolean;
  onConfirm?: () => void;
  onCancel?: () => void;
  duration?: number;
}

export const InlineToast: React.FC<InlineToastProps> = ({ 
  message, 
  type = 'info', 
  show,
  onConfirm, 
  onCancel,
  duration = 3000 
}) => {
  const [isVisible, setIsVisible] = useState(true);

  useEffect(() => {
    if (type !== 'confirm' && duration > 0) {
      const timer = setTimeout(() => setIsVisible(false), duration);
      return () => clearTimeout(timer);
    }
  }, [type, duration]);

  // If 'show' prop is provided, use it to control visibility; otherwise use internal state
  const shouldRender = show !== undefined ? show : isVisible;
  if (!shouldRender) return null;

  const bgClass = 
    type === 'success' ? 'bg-emerald-500/10 border-emerald-500/20 text-emerald-400' :
    type === 'error' ? 'bg-red-500/10 border-red-500/20 text-red-400' :
    type === 'confirm' ? 'bg-amber-500/10 border-amber-500/20 text-amber-400' :
    'bg-blue-500/10 border-blue-500/20 text-blue-400';

  return (
    <div className={`inline-flex items-center px-3 py-1.5 rounded-lg border text-xs font-bold uppercase tracking-wider animate-in fade-in zoom-in duration-200 ${bgClass}`}>
      <span>{message}</span>

      {type === 'confirm' && (
        <div className="flex items-center ml-3 pl-3 border-l border-current/20 space-x-3">
          <button 
            onClick={(e) => {
              e.preventDefault();
              e.stopPropagation();
              onConfirm?.();
            }}
            className="hover:text-white transition-colors"
          >
            Confirm
          </button>
          <button 
            onClick={(e) => {
              e.preventDefault();
              e.stopPropagation();
              onCancel?.();
            }}
            className="opacity-50 hover:opacity-100 hover:text-white transition-opacity"
          >
            Cancel
          </button>
        </div>
      )}
    </div>
  );
};

