export const PasskeyModule = () => {
  const { addToast } = useToast();
  const [passkeys, setPasskeys] = useState<Passkey[]>([]);
  const [loading, setLoading] = useState(true);
  const [registering, setRegistering] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editName, setEditName] = useState('');

  useEffect(() => {
    fetchPasskeys();
  }, []);

  const fetchPasskeys = async () => {
    try {
      const res = await fetch(`/api/auth/webauthn/passkeys`);
      if (!res.ok) throw new Error('Failed to fetch passkeys');
      const data = await res.json() as any;
      setPasskeys(data.passkeys || []);
    } catch (err) {
      addToast('Error: Could not retrieve security keys.', 'error');
    } finally {
      setLoading(false);
    }
  };

  const saveName = async (id: string) => {
    try {
      const res = await fetch(`/api/auth/webauthn/passkeys/${id}`, { 
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name: editName })
      });
      if (!res.ok) throw new Error('Failed to rename key');

      setPasskeys(p => p.map(k => k.id === id ? { ...k, name: editName } : k));
      setEditingId(null);
      addToast('Key renamed.', 'success');
    } catch (err) {
      addToast('Failed to rename key.', 'error');
    }
  };

  const deletePasskey = async (id: string) => {
    if (!confirm('Are you sure you want to remove this security key? Biometric data will be permanently removed from the vault.')) return;

    try {
      const res = await fetch(`/api/auth/webauthn/passkeys/${id}`, { 
        method: 'DELETE'
      });
      if (!res.ok) throw new Error('Failed to revoke passkey');

      setPasskeys(p => p.filter(k => k.id !== id));
      addToast('Security key removed.', 'success');
    } catch (err) {
      addToast('Failed to remove key.', 'error');
    }
  };

  const generatePasskey = async () => {
    setRegistering(true);
    try {
      const challengeRes = await fetch(`/api/auth/webauthn/generate-registration`, { method: 'POST' });
      const options = await challengeRes.json() as any;
      if (!challengeRes.ok) throw new Error(options.error || 'Challenge generation failed');

      const attResp = await startRegistration({ optionsJSON: options });

      const verifyRes = await fetch(`/api/auth/webauthn/verify-registration`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ attestation: attResp, name: 'Primary Device' }),
      });

      if (!verifyRes.ok) throw new Error('Security key verification failed.');

      addToast('Security key added.', 'success');
      fetchPasskeys();
    } catch (err: any) {
      console.error(err);
      addToast(err.message || 'Security key registration failed.', 'error');
    } finally {
      setRegistering(false);
    }
