               <Shield className="w-5 h-5 text-blue-500" />
            </div>
            <span className="text-[10px] font-black uppercase tracking-widest text-blue-400">Security Standard v6.1</span>
          </motion.div>
          <h3 className="text-3xl font-black text-white tracking-tight">Passkey Management</h3>
          <p className="text-sm text-slate-400 mt-1">Unified biometric forensic auditing and secure hardware isolation.</p>
        </div>

        <button 
          onClick={generatePasskey}
          disabled={registering}
          className="flex items-center gap-3 bg-blue-500 hover:bg-blue-600 text-white px-6 py-3 rounded-2xl text-xs font-black uppercase tracking-widest transition-all shadow-[0_0_25px_rgba(59,130,246,0.3)] disabled:opacity-50"
        >
          {registering ? <RefreshCw className="w-4 h-4 animate-spin" /> : <Plus className="w-4 h-4" />}
          <span>Add New Passkey</span>
