import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { startRegistration, startAuthentication } from '@simplewebauthn/browser';
import { Fingerprint, Loader2, ShieldAlert } from 'lucide-react';
import { FocusTrap } from './FocusTrap';

interface PasskeyChallengeProps {
  onSuccess: () => void;
  appName?: string;
  children?: React.ReactNode;
}

export function PasskeyChallenge({ onSuccess, appName, children }: PasskeyChallengeProps) {
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [mode, setMode] = useState<'auth' | 'register'>('auth');
  const [verified, setVerified] = useState(false);

  useEffect(() => {
    if (!verified) {
      initiateChallenge();
    }
  }, [mode]);

  const initiateChallenge = async () => {
    setLoading(true);
    setError(null);
    try {
      if (mode === 'auth') {
        const resp = await fetch('/api/admin/webauthn/generate-auth', { method: 'POST' });
        if (resp.status === 404) {
          // No passkeys registered, switch to registration mode if authorized
          setMode('register');
          return;
        }
        if (!resp.ok) {
          const data = await resp.json().catch(() => ({ error: `Server error ${resp.status}` }));
          throw new Error((data as any).error || 'Failed to generate auth challenge');
        }
        const options = await resp.json() as any;
        const asseResp = await startAuthentication({ optionsJSON: options });

        const verificationResp = await fetch('/api/admin/webauthn/verify-auth', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(asseResp),
        });

        if (verificationResp.ok) {
          setVerified(true);
          onSuccess();
        } else {
          const data = await verificationResp.json().catch(() => ({ error: 'Verification failed' }));
          setError((data as any).error || 'Verification failed');
        }
      } else {
        const resp = await fetch('/api/admin/webauthn/generate-registration', { method: 'POST' });
        if (!resp.ok) {
          const data = await resp.json().catch(() => ({ error: `Server error ${resp.status}` }));
          throw new Error((data as any).error || 'Failed to generate registration challenge');
        }
        const options = await resp.json() as any;

        const attResp = await startRegistration({ optionsJSON: options });

        const verificationResp = await fetch('/api/admin/webauthn/verify-registration', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(attResp),
        });

        if (verificationResp.ok) {
          setVerified(true);
          onSuccess();
        } else {
          const data = await verificationResp.json().catch(() => ({ error: 'Registration failed' }));
          setError((data as any).error || 'Registration failed');
        }
      }
    } catch (err: any) {
      console.error('[PasskeyChallenge]', err);
      setError(err.message || 'Security check failed or was cancelled.');
    } finally {
      setLoading(false);
    }
  };

  if (verified && children) {
    return <>{children}</>;
  }

  return (
    <AnimatePresence>
      <motion.div
        className="fixed inset-0 z-[100] flex items-center justify-center bg-black/60 backdrop-blur-md"
        role="dialog"
        aria-modal="true"
        aria-label="Security key authentication"
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        exit={{ opacity: 0 }}
      >
        <motion.div
          className="bg-slate-900/40 backdrop-blur-lg border border-slate-900 rounded-[2.5rem] p-8 max-w-sm w-full mx-4 relative overflow-hidden shadow-2xl"
          initial={{ opacity: 0, scale: 0.92, y: 20 }}
          animate={{ opacity: 1, scale: 1, y: 0 }}
          exit={{ opacity: 0, scale: 0.92, y: 20 }}
          transition={{ type: "spring", stiffness: 350, damping: 25 }}
        >
          <div className="absolute top-0 left-1/2 -translate-x-1/2 w-32 h-32 bg-cyan-500/10 rounded-full blur-3xl pointer-events-none" />

          <div className="relative flex flex-col items-center text-center">
            <div className="w-16 h-16 rounded-full bg-gradient-to-b from-cyan-500/15 to-cyan-500/5 flex items-center justify-center mb-6 ring-4 ring-slate-900 border border-cyan-500/20 shadow-[0_0_8px_rgba(6,182,212,0.1)]">
              <Fingerprint className="w-8 h-8 text-cyan-500" strokeWidth={1.5} />
            </div>

            <h3 className="text-xl font-bold text-white mb-2 font-display tracking-tight">
              Secure Login
            </h3>
            <p className="text-sm text-slate-400 mb-8 max-w-[260px] leading-relaxed">
              {mode === 'auth' 
                ? `Verify your identity using a security key to access ${appName || 'Admin'}.` 
                : 'Secure your account by registering a security key.'}
            </p>

            {error && (
              <div className="w-full bg-gradient-to-b from-red-900/15 to-red-900/5 border border-red-900/30 rounded-xl p-3 flex items-start gap-3 mb-6 text-left shadow-[0_0_8px_rgba(239,68,68,0.1)]">
                <ShieldAlert className="w-5 h-5 text-red-400 shrink-0 mt-0.5" />
                <p className="text-sm text-red-400 font-medium">Authentication Failed<br/><span className="text-xs opacity-80 break-words">{error}</span></p>
              </div>
            )}

            <button
              onClick={initiateChallenge}
              disabled={loading}
              className="w-full bg-gradient-to-b from-cyan-600 to-cyan-700 hover:from-cyan-500 hover:to-cyan-600 text-white font-black uppercase text-xs tracking-widest py-3 px-6 rounded-[1.25rem] transition-all active:scale-95 shadow-[0_8px_25px_rgba(8,145,178,0.3)] flex items-center justify-center gap-2 group"
            >
              {loading ? (
                <Loader2 className="w-4 h-4 animate-spin" />
              ) : (
                <>
                  Verify with Security Key
                  <Fingerprint className="w-4 h-4 opacity-60 group-hover:opacity-100 transition-opacity" />
                </>
              )}
            </button>

            <button 
              type="button"
              onClick={() => window.history.back()}
              className="mt-4 text-xs font-medium text-slate-500 hover:text-slate-300 transition-colors"
            >
              Cancel and Return
            </button>
          </div>
        </motion.div>
      </motion.div>
    </AnimatePresence>
  );
}

/** @jsxImportSource react */
import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { 
  Shield, 
  Key, 
  Fingerprint, 
  Trash2, 
  Plus, 
  RefreshCw, 
  AlertTriangle, 
  ShieldCheck, 
  Activity, 
  Globe, 
  MapPin, 
  Clock, 
  Cpu,
  Edit2,
  Check,
  X
} from 'lucide-react';
import { startRegistration } from '@simplewebauthn/browser';
import { useToast } from './common';

interface Passkey {
  id: string;
  name: string | null;
  aaguid: string | null;
  createdAt: string;
  lastUsedAt: string | null;
  counter: number;
  manufacturer: string | null;
  securityLevel: string | null;
  logo: string | null;
  providerName: string | null;
  lastUsedIpV4: string | null;
  lastUsedIpV6: string | null;
  lastUsedCity: string | null;
  lastUsedCountry: string | null;
  lastUsedUa: string | null;
}

export const PasskeyModule = () => {
  const { addToast } = useToast();
  const [passkeys, setPasskeys] = useState<Passkey[]>([]);
  const [loading, setLoading] = useState(true);
  const [registering, setRegistering] = useState(false);
  const [expandedId, setExpandedId] = useState<string | null>(null);

  // Inline Rename State
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editName, setEditName] = useState('');

  // Inline Delete State
  const [confirmDeleteId, setConfirmDeleteId] = useState<string | null>(null);

  useEffect(() => {
    fetchPasskeys();
  }, []);

  const fetchPasskeys = async () => {
    try {
      const res = await fetch(`/api/admin/webauthn/passkeys`);
      if (!res.ok) throw new Error('Failed to fetch passkeys');
      const data = await res.json() as any;
      setPasskeys(data.passkeys || []);
    } catch (err) {
      addToast('Error: Could not retrieve security keys.', 'error');
    } finally {
      setLoading(false);
    }
  };

  const deletePasskey = async (id: string) => {
    try {
      const res = await fetch(`/api/admin/webauthn/passkeys/${id}`, { method: 'DELETE' });
      if (!res.ok) throw new Error('Failed to revoke passkey');
      setPasskeys(p => p.filter(k => k.id !== id));
      addToast('Security key revoked.', 'success');
    } catch (err) {
      addToast('Revocation Failed.', 'error');
    }
  };

  const saveRename = async (id: string) => {
    if (!editName.trim()) return;
    try {
      const res = await fetch(`/api/admin/webauthn/passkeys/${id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name: editName.trim() }),
      });
      if (!res.ok) throw new Error('Failed to rename');
      setPasskeys(p => p.map(k => k.id === id ? { ...k, name: editName.trim() } : k));
      setEditingId(null);
      addToast('Passkey renamed.', 'success');
    } catch (err) {
      addToast('Renaming failed.', 'error');
    }
  };

  const generatePasskey = async () => {
    setRegistering(true);
    try {
      const challengeRes = await fetch(`/api/admin/webauthn/generate-registration`, { method: 'POST' });
      const options = await challengeRes.json() as any;
      if (!challengeRes.ok) throw new Error(options.error || 'Challenge failed');

      const attResp = await startRegistration({ optionsJSON: options });

      // Auto-generate a default name to avoid prompt dialogs
      const defaultName = `Hardware Key ${new Date().toLocaleDateString()}`;

      const verifyRes = await fetch(`/api/admin/webauthn/verify-registration`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ attestation: attResp, name: defaultName }),
      });

      if (!verifyRes.ok) throw new Error('Verification failed');
      const verifyData = await verifyRes.json() as any;

      addToast('Hardware signature anchored to identity.', 'success');
      await fetchPasskeys();

      // Automatically open inline renaming for the new key
      if (verifyData.id) {
        setEditingId(verifyData.id);
        setEditName(defaultName);
      }
    } catch (err: any) {
      console.error(err);
      addToast(err.message || 'Registration failed.', 'error');
    } finally {
      setRegistering(false);
    }
  };

  return (
    <div className="space-y-8">
      <div className="flex items-center justify-between pb-6 border-b border-white/5">
        <button 
          onClick={generatePasskey}
          disabled={registering}
          className="flex items-center gap-2.5 bg-gradient-to-b from-cyan-600 to-cyan-700 hover:from-cyan-500 hover:to-cyan-600 text-white px-6 py-3.5 rounded-xl text-sm font-black uppercase tracking-wider transition-all shadow-[0_0_15px_rgba(8,145,178,0.3)] disabled:opacity-50 cursor-pointer"
        >
          {registering ? <RefreshCw className="w-4 h-4 animate-spin" /> : <Plus className="w-4 h-4" />}
          <span>Register Key</span>
        </button>
      </div>

      <div className="grid grid-cols-1 gap-8">
        {loading ? (
          <div className="py-20 flex justify-center"><RefreshCw className="w-8 h-8 text-blue-500 animate-spin" /></div>
        ) : passkeys.length === 0 ? (
          <div className="p-20 bg-slate-900/40 border border-slate-800 border-dashed rounded-3xl flex flex-col items-center text-center">
            <Fingerprint className="w-16 h-16 text-slate-700 mb-6 animate-pulse-slow" />
            <p className="text-zinc-400 font-medium text-base">No hardware signatures detected.<br/>Enroll a passkey to enable administrative access.</p>
          </div>
        ) : (
          passkeys.map(pk => (
            <motion.div 
              key={pk.id} 
              layout
              className="bg-slate-950/40 backdrop-blur-xl border border-white/5 rounded-3xl overflow-hidden hover:border-cyan-500/25 transition-all duration-300 shadow-xl"
            >
              <div className="p-8 space-y-8">
                {confirmDeleteId === pk.id ? (
                  // Inline Deletion Confirmation (No browser prompts)
                  <div className="bg-red-500/10 border border-red-500/20 p-6 rounded-2xl flex flex-col md:flex-row md:items-center justify-between gap-6">
                    <div className="flex items-start gap-4">
                      <div className="p-3 bg-red-500/20 rounded-xl">
                        <AlertTriangle className="w-6 h-6 text-red-400 shrink-0" />
                      </div>
                      <div>
                        <h5 className="text-white text-base font-black uppercase tracking-wider">Revoke Hardware Key?</h5>
                        <p className="text-sm text-zinc-400 mt-2 leading-relaxed">Irreversible: removing this key means this physical device will lose admin access.</p>
                      </div>
                    </div>
                    <div className="flex gap-4 shrink-0">
                        <button 
                          onClick={() => deletePasskey(pk.id)}
                          className="bg-gradient-to-b from-red-500 to-red-600 hover:from-red-600 hover:to-red-700 text-white text-xs font-black uppercase tracking-widest px-6 py-3 rounded-xl transition-colors cursor-pointer shadow-[0_4px_15px_rgba(239,68,68,0.3)]"
                        >
                          Confirm Revoke
                        </button>
                        <button 
                          onClick={() => setConfirmDeleteId(null)}
                          className="bg-gradient-to-b from-white/10 to-white/5 hover:from-white/15 hover:to-white/10 text-white text-xs font-black uppercase tracking-widest px-6 py-3 rounded-xl transition-colors cursor-pointer shadow-[0_0_10px_rgba(0,0,0,0.15)]"
                        >
                        Cancel
                      </button>
                    </div>
                  </div>
                ) : (
                  // Normal Passkey Card UI
                  <>
                    <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-6">
                      <div className="flex items-center gap-5">
                        <div className="w-16 h-16 rounded-2xl bg-zinc-900 border border-zinc-800 flex items-center justify-center p-2.5 shadow-inner shrink-0">
                          {pk.logo ? (
                            <img src={pk.logo} alt={pk.providerName || "Brand Logo"} className="w-full h-full object-contain transition-all" />
                          ) : (
                            <Fingerprint className="w-8 h-8 text-blue-400" />
                          )}
                        </div>
                        <div className="space-y-1.5">
                          <div className="flex items-center gap-3 flex-wrap">
                            {editingId === pk.id ? (
                              <div className="flex items-center gap-2">
                                <input 
                                  type="text" 
                                  value={editName}
                                  onChange={e => setEditName(e.target.value)}
                                  onKeyDown={e => e.key === 'Enter' && saveRename(pk.id)}
                                  className="bg-slate-900 border border-slate-700 text-white text-base rounded-lg px-4 py-2 focus:outline-none focus:ring-1 focus:ring-cyan-500"
                                />
                                <button onClick={() => saveRename(pk.id)} className="p-2 bg-green-500/20 text-green-400 hover:bg-green-500/30 rounded-lg transition-colors"><Check className="w-4 h-4" /></button>
                                <button onClick={() => setEditingId(null)} className="p-2 bg-white/5 text-zinc-400 hover:bg-white/10 rounded-lg transition-colors"><X className="w-4 h-4" /></button>
                              </div>
                            ) : (
                              <div className="flex items-center gap-2 group/title">
                                <h4 className="text-white font-black text-xl tracking-tight">{pk.name || 'Unnamed Signature'}</h4>
                                <button 
                                  onClick={() => {
                                    setEditingId(pk.id);
                                    setEditName(pk.name || '');
                                  }}
                                  className="opacity-0 group-hover/title:opacity-100 p-1.5 hover:bg-white/5 text-zinc-400 hover:text-white rounded transition-all"
                                >
                                  <Edit2 className="w-4 h-4" />
                                </button>
                              </div>
                            )}
                            <span className="px-2.5 py-1 bg-gradient-to-b from-cyan-500/15 to-cyan-500/5 text-cyan-400 text-[10px] font-black uppercase tracking-wider rounded border border-cyan-500/20 shadow-[0_0_8px_rgba(6,182,212,0.1)]">
                              {pk.securityLevel?.includes('SE') ? 'FIDO2 L2+' : 'FIDO2 L1'}
                            </span>
                          </div>
                          <p className="text-xs text-zinc-500 font-bold uppercase tracking-[0.2em]">{pk.manufacturer || 'Generic'} • {pk.providerName || 'Authenticator'}</p>
                        </div>
                      </div>

                      <div className="flex items-center gap-3 self-end sm:self-center">
                        <button 
                          onClick={() => setExpandedId(expandedId === pk.id ? null : pk.id)}
                          className={`p-3.5 rounded-xl transition-all cursor-pointer ${expandedId === pk.id ? 'bg-gradient-to-b from-cyan-500/25 to-cyan-500/15 text-cyan-500 border border-cyan-500/30' : 'bg-gradient-to-b from-white/10 to-white/5 text-zinc-500 hover:text-white border border-transparent'}`}
                        >
                          <Activity className="w-5 h-5" />
