import React from 'react';
import { Link, useRevalidator } from 'react-router';
import { motion } from "framer-motion";
import { apiFetch } from "../services/toast";
import { useKeyClick } from "../hooks/useKeyClick";

interface RaffleCardProps {
  raffle: {
    id: string;
    name: string;
    mode: string;
    entryCount: number;
    maxSpots: number;
    eliminatedCount: number;
    isJoined: boolean;
    status?: string;
    winnerName?: string;
    locked?: boolean;
    paused?: boolean;
  };
  layout?: 'card' | 'list';
  userRole?: string | null;
  onClick?: () => void;
}

const TERMINAL_STATUSES = ['completed', 'archived', 'no_winner', 'cancelled'];

export const RaffleCard: React.FC<RaffleCardProps> = ({ raffle, layout = 'card', userRole, onClick }) => {
  const isTerminal = raffle.status ? TERMINAL_STATUSES.includes(raffle.status) : false;
  const isIdle = raffle.status === 'idle';
  const isActive = raffle.status === 'active';
  const isLocked = !!raffle.locked;
  const isPaused = !!raffle.paused;
  const isEditable = userRole === 'admin' || userRole === 'owner';
  const showEditLink = (!isTerminal && (userRole === 'admin' || userRole === 'owner')) || (isTerminal && userRole === 'owner');
  const joinDisabled = isLocked || isPaused;

  const activeCount = Math.max(0, raffle.entryCount - raffle.eliminatedCount);
  const totalSpots = raffle.maxSpots > 0 ? raffle.maxSpots : Math.max(raffle.entryCount + 1, 20);

  const activePct = Math.min(100, (activeCount / totalSpots) * 100);
  const elimPct = Math.min(100 - activePct, (raffle.eliminatedCount / totalSpots) * 100);

  const [isJoining, setIsJoining] = React.useState(false);
  const [isActing, setIsActing] = React.useState(false);
  const revalidator = useRevalidator();

  const handleJoin = async (e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setIsJoining(true);
    const { ok } = await apiFetch("/api/raffle/join", {
      method: "POST",
      body: { raffleId: raffle.id },
      loadingMessage: "Submitting entry request...",
      successMessage: "Joined successfully!",
    });
    if (ok) revalidator.revalidate();
    setIsJoining(false);
  };

  const handleLifecycle = async (action: string, successMsg: string) => {
    setIsActing(true);
    const { ok } = await apiFetch("/api/admin/raffle/lifecycle", {
      method: "POST",
      body: { raffle_id: parseInt(raffle.id), action },
      loadingMessage: `${action === 'start' ? 'Starting' : action}...`,
      successMessage: successMsg,
    });
    if (ok) revalidator.revalidate();
    setIsActing(false);
  };

  const handleLockToggle = async () => {
    const nextLocked = !isLocked;
    const { ok } = await apiFetch("/api/admin/raffle/save-rules", {
      method: "POST",
      body: { raffle_id: parseInt(raffle.id), locked: nextLocked },
      loadingMessage: nextLocked ? "Locking raffle..." : "Unlocking raffle...",
      successMessage: nextLocked ? "Raffle locked!" : "Raffle unlocked!",
    });
    if (ok) revalidator.revalidate();
  };

  const handleCancel = async () => {
    const { ok } = await apiFetch("/api/admin/raffle/lifecycle", {
      method: "POST",
      body: { raffle_id: parseInt(raffle.id), action: 'cancel' },
      loadingMessage: "Cancelling raffle...",
      successMessage: "Raffle cancelled.",
    });
    if (ok) revalidator.revalidate();
  };

  const handlePauseResume = async () => {
    const action = isPaused ? 'resume' : 'pause';
    const { ok } = await apiFetch("/api/admin/raffle/lifecycle", {
      method: "POST",
      body: { raffle_id: parseInt(raffle.id), action },
      loadingMessage: isPaused ? "Resuming raffle..." : "Pausing raffle...",
      successMessage: isPaused ? "Raffle resumed!" : "Raffle paused!",
    });
    if (ok) revalidator.revalidate();
  };

  const borderColor = isTerminal ? 'border-l-slate-700' : raffle.isJoined ? 'border-l-cyan-500' : 'border-l-slate-800';

  // --- LIST LAYOUT ---
  if (layout === 'list') {
    return (
      <motion.article
        whileHover={{ x: 4, boxShadow: "0 0 30px rgba(6,182,212,0.15)" }}
        transition={{ type: "spring", stiffness: 300, damping: 20 }}
        onClick={onClick}
        {...(onClick ? useKeyClick(onClick) : {})}
        className={`bg-slate-900/40 backdrop-blur-lg border border-slate-900 rounded-[2.5rem] grid grid-cols-1 md:grid-cols-[200px_1fr_auto] gap-4 p-6 items-center ${borderColor} border-t-0 ${onClick ? 'cursor-pointer' : ''}`}
      >
        <div className="flex flex-col text-center items-center min-w-[200px]">
          <h3 className="text-sm font-bold text-white mb-1.5 leading-tight">{raffle.name}</h3>
