import React, { useEffect, useRef } from 'react';
import { motion } from 'framer-motion';

interface TurnstileProps {
  sitekey: string;
  onVerify: (token: string) => void;
}

export const Turnstile: React.FC<TurnstileProps> = ({ sitekey, onVerify }) => {
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const script = document.createElement("script");
    script.src = "https://challenges.cloudflare.com/turnstile/v0/api.js";
    script.async = true;
    script.defer = true;
    document.head.appendChild(script);

    (window as any).onTurnstileLoad = () => {
      (window as any).turnstile.render(containerRef.current, {
        sitekey,
        callback: onVerify,
      });
    };

    return () => {
      document.head.removeChild(script);
      delete (window as any).onTurnstileLoad;
    };
  }, [sitekey, onVerify]);

  return (
    <motion.div
      initial={{ opacity: 0, scale: 0.95 }}
      animate={{ opacity: 1, scale: 1 }}
      transition={{ type: "spring", stiffness: 300, damping: 25 }}
      className="flex justify-center py-4"
    >
      <div className="bg-slate-900/40 backdrop-blur-lg border border-slate-900 rounded-[1.25rem] p-4 inline-flex" ref={containerRef} />
    </motion.div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { 
  LayoutDashboard, 
  Plus, 
  Users, 
  ScrollText, 
  Settings, 
  LogOut, 
  Shield, 
  ChevronDown, 
  ExternalLink,
  PlusCircle,
  Trash2,
  Bookmark
} from 'lucide-react';

interface QuickLink {
  id: string;
  label: string;
  href: string;
}

const DEFAULT_LINKS: QuickLink[] = [
  { id: 'dashboard', label: 'Dashboard', href: '/admin' },
  { id: 'create_raffle', label: 'Create Raffle', href: '/admin/raffle/create' },
  { id: 'users', label: 'Users', href: '/admin/users' },
  { id: 'logs', label: 'Audit Logs', href: '/admin/logs' },
  { id: 'system', label: 'System Settings', href: '/admin/system' }
];

interface UserMenuProps {
  user: {
    username: string;
    avatarUrl: string;
    role: string;
  };
}

export const UserMenu: React.FC<UserMenuProps> = ({ user }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [isEditingLinks, setIsEditingLinks] = useState(false);
  const [quickLinks, setQuickLinks] = useState<QuickLink[]>(DEFAULT_LINKS);
  const [newLinkLabel, setNewLinkLabel] = useState('');
  const [newLinkHref, setNewLinkHref] = useState('');
  const menuRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    try {
      const stored = localStorage.getItem(`ldd_quick_links_${user.username}`);
      if (stored) {
        setQuickLinks(JSON.parse(stored));
      }
    } catch {}
  }, [user.username]);

  const saveLinks = (links: QuickLink[]) => {
    setQuickLinks(links);
    try {
      localStorage.setItem(`ldd_quick_links_${user.username}`, JSON.stringify(links));
    } catch {}
  };

  const handleAddLink = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newLinkLabel.trim() || !newLinkHref.trim()) return;
    const updated = [
      ...quickLinks,
      {
        id: `custom_${Date.now()}`,
        label: newLinkLabel.trim(),
        href: newLinkHref.trim()
      }
    ];
    saveLinks(updated);
    setNewLinkLabel('');
    setNewLinkHref('');
  };

  const handleRemoveLink = (id: string) => {
    const updated = quickLinks.filter(l => l.id !== id);
    saveLinks(updated);
  };

  const handleResetLinks = () => {
    saveLinks(DEFAULT_LINKS);
  };

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
        setIsOpen(false);
        setIsEditingLinks(false);
      }
    };
    const handleEscape = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        setIsOpen(false);
        setIsEditingLinks(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    document.addEventListener('keydown', handleEscape);
    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
      document.removeEventListener('keydown', handleEscape);
    };
  }, []);

  const isOwner = user.role === 'Owner';

  return (
    <div className="relative" ref={menuRef}>
      <button
        onClick={() => setIsOpen(!isOpen)}
        aria-expanded={isOpen}
        aria-haspopup="menu"
        className="flex items-center space-x-2 rounded-full border border-white/10 bg-gradient-to-b from-white/10 to-white/5 hover:from-white/15 hover:to-white/10 transition-all p-1 focus:outline-none shadow-[0_0_10px_rgba(0,0,0,0.15)] cursor-pointer"
      >
        <div className="relative">
          <img
            src={user.avatarUrl}
            alt={user.username}
            className="w-10 h-10 rounded-full object-cover shadow-lg border-2 border-cyan-500/20"
          />
        </div>
        <ChevronDown className={`w-4 h-4 text-slate-500 transition-transform duration-300 ${isOpen ? 'rotate-180' : ''}`} />
      </button>

      <AnimatePresence>
        {isOpen && (
          <motion.div
            initial={{ opacity: 0, y: 10, scale: 0.95 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, y: 10, scale: 0.95 }}
            transition={{ duration: 0.2, ease: "easeOut" }}
            className="absolute top-full right-0 mt-2 w-72 z-50 bg-slate-900/95 backdrop-blur-2xl border border-white/10 rounded-[2rem] shadow-2xl p-2 max-h-[85vh] overflow-y-auto overscroll-behavior-contain"
            role="menu"
          >
            {/* User header */}
            <div className="px-4 py-3 border-b border-white/5">
              <div className="flex items-center justify-between gap-2">
                <p className="text-base font-semibold text-white truncate">{user.username}</p>
                <span className={`text-xs font-semibold px-2 py-0.5 rounded-full border shrink-0 ${
                  isOwner
                    ? 'bg-gradient-to-b from-red-500/15 to-red-500/5 text-red-500 border-red-500/20 shadow-[0_0_8px_rgba(239,68,68,0.1)]'
                    : 'bg-gradient-to-b from-cyan-500/15 to-cyan-500/5 text-cyan-500 border-cyan-500/20 shadow-[0_0_8px_rgba(6,182,212,0.1)]'
                }`}>
                  {user.role.toLowerCase()}
                </span>
              </div>
            </div>

            {/* Quick links header & edit toggle */}
            <div className="px-3 pt-2.5 pb-1 flex items-center justify-between">
              <span className="text-[10px] font-black uppercase tracking-widest text-slate-500">Quick Links</span>
              <button
                type="button"
                onClick={() => setIsEditingLinks(!isEditingLinks)}
                className="text-[10px] font-bold text-cyan-400 hover:text-cyan-300 uppercase tracking-wider cursor-pointer"
              >
                {isEditingLinks ? 'Done' : 'Customize'}
              </button>
            </div>

            {/* Menu items / Quick links customizer */}
            {isEditingLinks ? (
              <div className="p-2 space-y-3 bg-slate-950/60 rounded-xl border border-slate-800/80 mb-2 text-left">
                <div className="space-y-1.5 max-h-36 overflow-y-auto">
                  {quickLinks.map(link => (
                    <div key={link.id} className="flex items-center justify-between p-1.5 bg-slate-900 rounded-lg text-xs">
                      <span className="text-white truncate font-medium">{link.label}</span>
                      <button
                        type="button"
                        onClick={() => handleRemoveLink(link.id)}
                        className="text-slate-500 hover:text-red-400 p-1 cursor-pointer"
                        title="Remove link"
                      >
                        <Trash2 size={12} />
                      </button>
                    </div>
                  ))}
                </div>

                <form onSubmit={handleAddLink} className="space-y-2 pt-2 border-t border-slate-850">
                  <input
                    type="text"
                    placeholder="Link label (e.g. My Raffle)"
                    value={newLinkLabel}
                    onChange={(e) => setNewLinkLabel(e.target.value)}
                    className="w-full bg-slate-900 border border-slate-800 rounded-lg px-2 py-1 text-xs text-white placeholder-slate-600 outline-none focus:border-cyan-500/50"
                  />
                  <input
                    type="text"
                    placeholder="URL (e.g. /admin/raffle/manage/1)"
                    value={newLinkHref}
                    onChange={(e) => setNewLinkHref(e.target.value)}
                    className="w-full bg-slate-900 border border-slate-800 rounded-lg px-2 py-1 text-xs text-white placeholder-slate-600 outline-none focus:border-cyan-500/50"
                  />
                  <div className="flex items-center justify-between pt-1">
                    <button
                      type="button"
                      onClick={handleResetLinks}
                      className="text-[10px] text-slate-500 hover:text-slate-300 cursor-pointer"
                    >
                      Reset Defaults
                    </button>
                    <button
                      type="submit"
                      disabled={!newLinkLabel.trim() || !newLinkHref.trim()}
                      className="px-2.5 py-1 bg-cyan-600 hover:bg-cyan-500 disabled:opacity-40 text-white text-xs font-bold rounded-lg cursor-pointer"
                    >
                      Add Link
                    </button>
                  </div>
                </form>
              </div>
            ) : (
              <div className="py-1">
                {quickLinks.map((link) => (
                  <MenuLink 
                    key={link.id} 
                    href={link.href} 
                    icon={<Bookmark size={14} />} 
                    label={link.label} 
                  />
                ))}
              </div>
            )}

            <div className="mx-3 my-1 border-t border-white/5" />
            <MenuLink href="/settings" icon={<Settings size={14} />} label="Account Settings" />
            <MenuLink href="/privacy" icon={<Shield size={14} />} label="My Data" />

            {/* Log out */}
            <div className="px-2 py-2 border-t border-white/5">
              <a
                href="/logout"
                className="flex items-center gap-3 px-3 py-2 text-sm font-medium text-red-400 hover:text-red-300 hover:bg-gradient-to-b hover:from-red-500/15 hover:to-red-500/5 rounded-xl transition-all w-full cursor-pointer"
              >
                <LogOut size={14} className="text-red-400/70" />
                Log Out
              </a>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
};

const MenuLink: React.FC<{ href: string; icon: React.ReactNode; label: string }> = ({ href, icon, label }) => (
  <a 
