    role="menuitem" 
    className="flex items-center gap-3 px-3 py-2 text-sm font-medium text-slate-400 hover:text-white hover:bg-gradient-to-b hover:from-white/10 hover:to-white/5 rounded-xl transition-all w-full"
  >
    <span className="text-slate-500">{icon}</span>
    <span className="truncate">{label}</span>
