import React, { useState, useEffect, useCallback } from 'react';
import { startRegistration } from '@simplewebauthn/browser';
import { useToast } from '../common';
import { 
  Fingerprint, 
  Key, 
  Plus, 
  RefreshCw, 
  Trash2, 
  ShieldCheck, 
  Activity, 
  Globe, 
  MapPin, 
  Clock, 
  Shield, 
  Cpu,
  Edit2,
  Check,
  X,
  AlertTriangle
} from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';

interface PasskeyRecord {
  id: string;
  name: string | null;
  aaguid: string | null;
  createdAt: string;
  lastUsedAt: string | null;
  counter: number;
  manufacturer: string | null;
  securityLevel: string | null;
  logo: string | null;
  providerName: string | null;
  lastUsedIpV4: string | null;
  lastUsedIpV6: string | null;
  lastUsedCity: string | null;
  lastUsedCountry: string | null;
  lastUsedUa: string | null;
}

export const AuthVault: React.FC = () => {
  const { addToast } = useToast();
  const [passkeys, setPasskeys] = useState<PasskeyRecord[]>([]);
  const [loading, setLoading] = useState(true);
  const [registering, setRegistering] = useState(false);
  const [expandedId, setExpandedId] = useState<string | null>(null);

  // Inline Rename State
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editName, setEditName] = useState('');

  // Inline Delete State
  const [confirmDeleteId, setConfirmDeleteId] = useState<string | null>(null);

  const fetchPasskeys = useCallback(async () => {
    try {
      const resp = await fetch('/api/admin/webauthn/passkeys');
      if (!resp.ok) return;
      const data = await resp.json() as any;
      setPasskeys(data.passkeys || []);
    } catch {
      // silent fail
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchPasskeys();
  }, [fetchPasskeys]);

  const handleRegisterPasskey = async () => {
    setRegistering(true);
    try {
      const genResp = await fetch('/api/admin/webauthn/generate-registration', { method: 'POST' });
      const options = await genResp.json() as any;
      if (!genResp.ok) throw new Error('Challenge failed');

      const attResp = await startRegistration({ optionsJSON: options });

      // Auto-generate a default name to avoid prompt dialogs
      const defaultName = `Hardware Key ${new Date().toLocaleDateString()}`;

      const verifyResp = await fetch('/api/admin/webauthn/verify-registration', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ attestation: attResp, name: defaultName }),
      });

      if (verifyResp.ok) {
        addToast('Administrative passkey anchored to hardware.', 'success');
        const verifyData = await verifyResp.json() as any;
        await fetchPasskeys();

        // Enter edit mode for the new key immediately
        if (verifyData.id) {
          setEditingId(verifyData.id);
          setEditName(defaultName);
        }
      } else {
        throw new Error('Verification failed');
      }
    } catch (e: any) {
      addToast(`Authentication Failure: ${e.message}`, 'error');
    } finally {
      setRegistering(false);
    }
  };

  const saveRename = async (id: string) => {
    if (!editName.trim()) return;
    try {
      const res = await fetch(`/api/admin/webauthn/passkeys/${id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name: editName.trim() }),
      });
      if (!res.ok) throw new Error();
      setPasskeys(p => p.map(k => k.id === id ? { ...k, name: editName.trim() } : k));
      setEditingId(null);
      addToast('Passkey renamed.', 'success');
    } catch {
      addToast('Failed to rename passkey.', 'error');
    }
  };

  const handleRevoke = async (id: string) => {
    try {
      const resp = await fetch(`/api/admin/webauthn/passkeys/${id}`, { method: 'DELETE' });
      if (resp.ok) {
        addToast(`Passkey revoked.`, 'success');
        await fetchPasskeys();
      }
    } catch {
      addToast('Failed to revoke passkey.', 'error');
    }
  };

  return (
    <div className="bg-slate-900/40 backdrop-blur-xl border border-white/5 rounded-[2.5rem] p-8 shadow-2xl relative overflow-hidden">
      <div className="absolute top-0 right-0 w-64 h-64 bg-blue-500/5 blur-3xl rounded-full translate-x-1/2 -translate-y-1/2" />

      <div className="relative z-10">
        <div className="flex justify-between items-start mb-8">
          <div className="flex items-center gap-4">
            <div className="w-12 h-12 bg-blue-500/20 rounded-2xl flex items-center justify-center border border-blue-500/30">
              <ShieldCheck className="w-6 h-6 text-blue-400" />
            </div>
            <div>
              <h2 className="text-2xl font-black text-white tracking-tight">Authentication Vault</h2>
              <p className="text-[10px] text-slate-500 font-bold uppercase tracking-[0.2em] mt-1">Fleet Security Standard v6.1 • Biometric Isolation</p>
            </div>
          </div>
          <button 
            onClick={handleRegisterPasskey}
            disabled={registering}
            className="flex items-center gap-2 bg-blue-500 hover:bg-blue-600 text-white px-6 py-3 rounded-xl text-xs font-black uppercase tracking-widest transition-all shadow-[0_0_20px_rgba(59,130,246,0.3)] disabled:opacity-50"
          >
            {registering ? <RefreshCw className="w-4 h-4 animate-spin" /> : <Plus className="w-4 h-4" />}
            <span>Register Key</span>
          </button>
        </div>

        <div className="space-y-4">
          {loading ? (
            <div className="flex justify-center py-12"><RefreshCw className="w-8 h-8 text-blue-500 animate-spin" /></div>
          ) : passkeys.length === 0 ? (
            <div className="text-center p-12 bg-slate-950/50 rounded-3xl border border-white/5 border-dashed">
              <Fingerprint className="w-12 h-12 text-slate-700 mx-auto mb-4" />
              <p className="text-slate-500 text-sm font-medium">No hardware signatures detected in vault.</p>
            </div>
          ) : (
            passkeys.map((pk) => (
