import React, { useEffect, useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { apiFetch } from '../../services/toast';

interface UserSecurityModalProps {
  isOpen: boolean;
  onClose: () => void;
  user: any;
  currentActorRoleLevel?: number;
}

export const UserSecurityModal: React.FC<UserSecurityModalProps> = ({
  isOpen,
  onClose,
  user,
  currentActorRoleLevel = 20
}) => {
  const [securityData, setSecurityData] = useState<any>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [actionInProgress, setActionInProgress] = useState<string | null>(null);

  useEffect(() => {
    if (!isOpen || !user) return;
    setIsLoading(true);
    fetch(`/api/admin/users/${user.id}/security`)
      .then(res => res.json())
      .then((data: any) => {
        if (data.success) {
          setSecurityData(data);
        }
      })
      .catch(err => console.error("Failed to load security details:", err))
      .finally(() => setIsLoading(false));
  }, [isOpen, user]);

  if (!isOpen || !user) return null;

  const isOwner = currentActorRoleLevel === 0;

  const handleRevokePasskeys = async () => {
    if (!confirm(`Are you sure you want to revoke all security passkeys for @${user.username}? The user will be required to re-enroll a device.`)) return;
    setActionInProgress('passkeys');
    const { ok } = await apiFetch(`/api/admin/users/${user.id}/reset-passkeys`, {
      method: 'POST',
      toastId: 'revoke-passkeys',
      loadingMessage: 'Revoking passkeys...',
      successMessage: 'All passkeys have been revoked.'
    });
    if (ok) {
      setSecurityData((prev: any) => ({ ...prev, passkeys: [] }));
    }
    setActionInProgress(null);
  };

  const handleForcePasswordReset = async () => {
    setActionInProgress('password');
    const { ok } = await apiFetch(`/api/admin/users/${user.id}/force-password-reset`, {
      method: 'POST',
      toastId: 'force-password-reset',
      loadingMessage: 'Flagging account...',
      successMessage: 'Account flagged. User must reset password on next login.'
    });
    if (ok) {
      setSecurityData((prev: any) => ({
        ...prev,
        user: { ...prev.user, forcePasswordChange: 1 }
      }));
    }
    setActionInProgress(null);
  };

  return (
    <AnimatePresence>
      <div className="fixed inset-0 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4 z-50">
        <motion.div
          initial={{ scale: 0.95, opacity: 0 }}
          animate={{ scale: 1, opacity: 1, transition: { type: "spring", stiffness: 350, damping: 25 } }}
          exit={{ scale: 0.95, opacity: 0 }}
          className="bg-slate-900/90 backdrop-blur-xl border border-slate-800 rounded-[2.5rem] max-w-2xl w-full p-6 md:p-8 text-left shadow-2xl overflow-hidden max-h-[90vh] flex flex-col"
        >
          {/* Header */}
          <div className="flex justify-between items-start mb-6">
            <div>
              <span className="text-[10px] font-black uppercase tracking-widest text-cyan-400">🛡️ Security & Credentials</span>
              <h3 className="text-2xl font-black text-white mt-1">
                Account Forensics: <span className="text-cyan-400">@{user.username}</span>
              </h3>
              <p className="text-slate-400 text-xs mt-1">User ID: <code className="text-slate-300">{user.id}</code></p>
            </div>
            <button
              onClick={onClose}
              className="px-3 py-1.5 rounded-xl border border-slate-800 text-slate-400 hover:text-white text-xs font-semibold cursor-pointer"
            >
              ✕ Close
            </button>
          </div>

          {/* Body */}
          <div className="flex-1 overflow-y-auto pr-1 space-y-6">
            {isLoading ? (
              <div className="py-12 text-center text-slate-500 text-sm">
                Retrieving biometric credentials and security forensics...
              </div>
            ) : (
              <>
                {/* Linked OAuth Identities */}
                <div className="bg-slate-950/60 border border-slate-800/80 rounded-2xl p-4">
                  <h4 className="text-xs font-bold uppercase tracking-wider text-slate-400 mb-3 flex items-center gap-2">
                    🔗 Linked Social Identities (SOP Delegates)
                  </h4>
                  {securityData?.linkedIdentities?.length > 0 ? (
                    <div className="space-y-2">
                      {securityData.linkedIdentities.map((ident: any) => (
                        <div key={ident.id} className="flex items-center justify-between bg-slate-900/60 border border-slate-800 rounded-xl p-3 text-xs">
                          <div className="flex items-center gap-3">
                            <span className="text-base">{ident.provider === 'discord' ? '👾' : '🌐'}</span>
                            <div>
                              <span className="font-bold text-white capitalize">{ident.provider}</span>
                              <p className="text-slate-500 text-[11px]">Provider ID: {ident.providerUserId} {ident.name ? `(${ident.name})` : ''}</p>
                            </div>
                          </div>
                          <span className="text-[10px] text-cyan-400 font-mono">Linked</span>
                        </div>
                      ))}
                    </div>
                  ) : (
                    <p className="text-slate-500 text-xs italic">No third-party delegates linked.</p>
                  )}
                </div>

                {/* Enrolled Passkeys & Biometrics */}
                <div className="bg-slate-950/60 border border-slate-800/80 rounded-2xl p-4">
                  <div className="flex justify-between items-center mb-3">
                    <h4 className="text-xs font-bold uppercase tracking-wider text-slate-400 flex items-center gap-2">
                      🔑 Enrolled Passkeys ({securityData?.passkeys?.length || 0})
                    </h4>
                    {isOwner && securityData?.passkeys?.length > 0 && (
                      <button
                        onClick={handleRevokePasskeys}
                        disabled={actionInProgress === 'passkeys'}
                        className="text-[10px] uppercase tracking-wider font-bold text-red-400 hover:text-red-300 border border-red-900/40 bg-red-950/30 px-2.5 py-1 rounded-lg transition-colors cursor-pointer"
                      >
                        {actionInProgress === 'passkeys' ? 'Revoking...' : 'Revoke All Keys'}
                      </button>
                    )}
                  </div>

                  {securityData?.passkeys?.length > 0 ? (
                    <div className="space-y-2.5">
                      {securityData.passkeys.map((pk: any) => (
                        <div key={pk.id} className="bg-slate-900/60 border border-slate-800 rounded-xl p-3 text-xs space-y-1.5">
                          <div className="flex justify-between items-center">
                            <span className="font-bold text-white flex items-center gap-2">
                              📱 {pk.name || 'Security Key'}
                            </span>
                            <span className="text-[10px] text-slate-500 font-mono">Uses: {pk.counter || 0}</span>
                          </div>
                          <div className="text-[11px] text-slate-400 grid grid-cols-2 gap-2">
                            <div><span className="text-slate-600">Created:</span> {pk.createdAt ? new Date(pk.createdAt).toLocaleDateString() : 'N/A'}</div>
                            <div><span className="text-slate-600">Last Used:</span> {pk.lastUsedAt ? new Date(pk.lastUsedAt).toLocaleDateString() : 'Never'}</div>
                            {pk.registrationLocation && <div><span className="text-slate-600">Reg Location:</span> {pk.registrationLocation}</div>}
                            {pk.lastUsedLocation && <div><span className="text-slate-600">Last Location:</span> {pk.lastUsedLocation}</div>}
                          </div>
                        </div>
                      ))}
                    </div>
                  ) : (
                    <p className="text-slate-500 text-xs italic">No hardware passkeys enrolled.</p>
                  )}
                </div>

                {/* Account Security Flags & Actions */}
                <div className="bg-slate-950/60 border border-slate-800/80 rounded-2xl p-4">
                  <h4 className="text-xs font-bold uppercase tracking-wider text-slate-400 mb-3 flex items-center gap-2">
                    ⚡ Security Actions
                  </h4>
                  <div className="flex items-center justify-between bg-slate-900/60 border border-slate-800 rounded-xl p-3 text-xs">
                    <div>
                      <span className="font-bold text-white">Forced Password Reset</span>
                      <p className="text-slate-500 text-[11px]">Require the user to change password immediately on subsequent login.</p>
                    </div>
                    <button
                      onClick={handleForcePasswordReset}
                      disabled={actionInProgress === 'password' || securityData?.user?.forcePasswordChange === 1}
                      className={`px-3 py-1.5 rounded-lg text-xs font-bold cursor-pointer transition-colors ${
                        securityData?.user?.forcePasswordChange === 1
                          ? 'bg-amber-950/40 text-amber-400 border border-amber-800/50 cursor-not-allowed'
                          : 'bg-cyan-950/40 text-cyan-400 border border-cyan-800/50 hover:bg-cyan-900/40'
                      }`}
                    >
                      {securityData?.user?.forcePasswordChange === 1 ? 'Reset Pending' : 'Force Reset'}
                    </button>
                  </div>
                </div>
              </>
            )}
          </div>

          {/* Footer */}
          <div className="mt-6 pt-4 border-t border-slate-800 flex justify-end">
            <button
              type="button"
              onClick={onClose}
              className="px-5 py-2.5 rounded-xl text-xs font-bold bg-slate-800 hover:bg-slate-700 text-white cursor-pointer transition-all"
            >
              Done
            </button>
          </div>
        </motion.div>
      </div>
    </AnimatePresence>
  );
};

import { useState, useEffect } from "react";

export interface Wrestler {
  name: string;
  nickname?: string;
  headshotUrl?: string;
}

export function WrestlerAutocomplete({ value, onChange, superstars }: { value: string; onChange: (val: string) => void; superstars: Wrestler[] }) {
  const [isOpen, setIsOpen] = useState(false);
  const [search, setSearch] = useState(value);

  useEffect(() => {
    setSearch(value);
  }, [value]);

  const filtered = superstars.filter(s => {
    const nameMatch = (s.name || "").toLowerCase().includes(search.toLowerCase());
    const nickMatch = (s.nickname || "").toLowerCase().includes(search.toLowerCase());
    return nameMatch || nickMatch;
  });

  return (
    <div className="relative w-full">
      <input
        type="text"
        value={search}
        onChange={(e) => {
          setSearch(e.target.value);
          onChange(e.target.value);
          setIsOpen(true);
        }}
        onFocus={() => setIsOpen(true)}
        onBlur={() => {
          setTimeout(() => setIsOpen(false), 200);
        }}
        placeholder="Search or enter wrestler..."
        className="w-full bg-slate-950 border border-slate-800 rounded px-2.5 py-1.5 text-white text-xs focus:outline-none focus:border-cyan-500/50"
      />
      {isOpen && filtered.length > 0 && (
        <div className="absolute left-0 right-0 z-50 bg-slate-950 border border-slate-800 rounded-xl mt-1 max-h-60 overflow-y-auto w-full shadow-2xl divide-y divide-slate-900">
          {filtered.map((s: any) => {
            const avatar = s.headshotUrl || "https://cdn.discordapp.com/embed/avatars/0.png";
            return (
              <button
                key={s.name}
                type="button"
                onMouseDown={() => {
                  setSearch(s.name);
                  onChange(s.name);
                  setIsOpen(false);
                }}
                className="flex items-center gap-3 w-full px-3 py-2 text-left hover:bg-slate-900 transition-colors text-white"
              >
                <img 
                  src={avatar} 
                  alt="" 
                  className="w-6 h-6 rounded-full object-cover border border-slate-800 bg-slate-900" 
                  onError={(e) => { e.currentTarget.src = "https://cdn.discordapp.com/embed/avatars/0.png"; }}
                />
                <div className="flex flex-col leading-tight">
                  <span className="text-xs font-bold">{s.name}</span>
                  {s.nickname && (
                    <span className="text-[10px] text-slate-500 font-medium italic">"{s.nickname}"</span>
                  )}
                </div>
              </button>
            );
          })}
        </div>
      )}
    </div>
  );
}

import React, { useEffect } from 'react';
import { motion } from 'framer-motion';
import toast from 'react-hot-toast';

interface Props {
  appName: string;
}

export const FleetAuthGate: React.FC<Props> = ({ appName }) => {
  useEffect(() => {
    const hash = window.location.hash;
    const params = new URLSearchParams(hash.split('?')[1]);
    const error = params.get('error');
    if (error) {
      const msg = params.get('message') || error;
      const readable = msg === 'access_denied' ? 'Sign-in was cancelled or denied.' :
        msg === 'auth_failed' ? 'Authentication failed. Please try signing in again.' :
        decodeURIComponent(msg);
      toast.error(`Login failed: ${readable}`);
      window.location.hash = '#/';
    }
  }, []);

  const handleDiscordAuth = () => {
    window.location.href = '/api/auth/login/discord';
  };

  const handleGoogleAuth = () => {
    window.location.href = '/api/auth/login/google';
  };

