 * Supports custom steps and state-tracked play (localStorage check).
 */
export const OnboardingTour = (props: any) => {
  const { steps = [], tourKey = 'default' } = props;
  useEffect(() => {
    const hasCompletedTour = localStorage.getItem(`gp_tour_complete_${tourKey}`);

    if (!hasCompletedTour) {
      const driverObj = driver({
        showProgress: true,
        steps: steps,
        onDestroyed: () => {
          localStorage.setItem(`gp_tour_complete_${tourKey}`, 'true');
        },
      });

      driverObj.drive();
    }
  }, [steps, tourKey]);

  return null; // Side-effect only component
};

import { useState, useRef, useEffect } from "react";

export interface Option {
  value: string;
  label: string;
  badge?: string;
}

interface SearchableSelectProps {
  value: string;
  onChange: (val: string) => void;
  options: Option[];
  placeholder?: string;
  searchPlaceholder?: string;
  className?: string;
  compact?: boolean;
}

export function SearchableSelect({
  value,
  onChange,
  options,
  placeholder = "Select an option...",
  searchPlaceholder = "Search options...",
  className = "",
  compact = false,
}: SearchableSelectProps) {
  const [isOpen, setIsOpen] = useState(false);
  const [search, setSearch] = useState("");
  const containerRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  const selectedOption = options.find((opt) => opt.value === value);

  const filteredOptions = options.filter((opt) =>
    opt.label.toLowerCase().includes(search.toLowerCase()) ||
    opt.value.toLowerCase().includes(search.toLowerCase())
  );

  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      if (containerRef.current && !containerRef.current.contains(event.target as Node)) {
        setIsOpen(false);
        setSearch("");
      }
    }
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  const handleOpen = () => {
    setIsOpen(true);
    setSearch("");
    setTimeout(() => {
      inputRef.current?.focus();
    }, 50);
  };

  const handleSelect = (val: string) => {
    onChange(val);
    setIsOpen(false);
    setSearch("");
  };

  return (
    <div ref={containerRef} className={`relative w-full ${className}`}>
      {/* Trigger Button */}
      <button
        type="button"
        onClick={() => (isOpen ? setIsOpen(false) : handleOpen())}
        className={`w-full bg-slate-950 border border-slate-800 text-left text-white flex items-center justify-between focus:outline-none focus:border-cyan-500/50 cursor-pointer transition-all hover:border-slate-700 ${
          compact ? "px-3 py-2 rounded-xl text-xs" : "px-5 py-4 rounded-2xl text-base"
        }`}
      >
        <span className={`truncate ${selectedOption ? "text-white font-medium" : "text-slate-500"}`}>
          {selectedOption ? selectedOption.label : placeholder}
        </span>
        <span className="text-slate-500 text-xs ml-2 shrink-0 pointer-events-none">
          {isOpen ? "▲" : "▼"}
        </span>
      </button>

      {/* Floating Searchable Menu */}
      {isOpen && (
        <div className="absolute left-0 right-0 top-full mt-2 z-50 bg-slate-950 border border-slate-800 rounded-2xl shadow-2xl overflow-hidden divide-y divide-slate-900 animate-in fade-in zoom-in-95 duration-100">
          <div className="p-2.5 bg-slate-950/90 sticky top-0 z-10">
            <input
              ref={inputRef}
              type="text"
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              placeholder={searchPlaceholder}
              className="w-full bg-slate-900 border border-slate-800 rounded-xl px-3 py-2 text-xs text-white focus:outline-none focus:border-cyan-500/50 placeholder-slate-500"
            />
          </div>

          <div className="max-h-60 overflow-y-auto divide-y divide-slate-900/50">
            {filteredOptions.length > 0 ? (
              filteredOptions.map((opt) => {
                const isSelected = opt.value === value;
                return (
                  <button
                    key={opt.value}
                    type="button"
                    onMouseDown={() => handleSelect(opt.value)}
                    className={`w-full px-4 py-2.5 text-left text-xs flex items-center justify-between hover:bg-slate-900 transition-colors cursor-pointer ${
                      isSelected ? "bg-cyan-500/10 text-cyan-400 font-bold" : "text-slate-200"
                    }`}
                  >
                    <span className="truncate">{opt.label}</span>
                    {opt.badge && (
                      <span className="text-[10px] px-2 py-0.5 rounded bg-slate-800 text-slate-400 font-mono ml-2 shrink-0">
                        {opt.badge}
                      </span>
                    )}
                  </button>
                );
              })
            ) : (
              <div className="px-4 py-3 text-xs text-slate-500 text-center italic">
                No matching options
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

