export const AuthVault: React.FC = () => {
  const [passkeys, setPasskeys] = useState<PasskeyRecord[]>([]);
  const [loading, setLoading] = useState(true);
  const [registering, setRegistering] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editName, setEditName] = useState('');

  const fetchPasskeys = useCallback(async () => {
    try {
      const resp = await fetch('/api/admin/webauthn/passkeys');
      if (!resp.ok) return;
      const data = await resp.json() as any;
      setPasskeys(data.passkeys || []);
    } catch {
      // silent fail on load
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchPasskeys();
  }, [fetchPasskeys]);

  const handleRegisterPasskey = async () => {
    setRegistering(true);
    try {
      toast.info('Requesting biometric challenge...');
      const genResp = await fetch('/api/admin/webauthn/generate-registration', { method: 'POST' });
      if (!genResp.ok) throw new Error('Failed to generate challenge');
      const options = await genResp.json() as any;

      toast.info('Hardware interaction required.');
      const attResp = await startRegistration({ optionsJSON: options });

      const verifyResp = await fetch('/api/admin/webauthn/verify-registration', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ attestation: attResp, name: 'Admin Terminal Key' }),
      });

      if (verifyResp.ok) {
        toast.success('Passkey anchored to vault.');
        await fetchPasskeys();
      } else {
        throw new Error('Verification failed');
      }
    } catch (e: any) {
      toast.error(`Registration failed: ${e.message}`);
    } finally {
      setRegistering(false);
    }
  };

  const handleRename = async (id: string) => {
    try {
      const resp = await fetch(`/api/admin/webauthn/passkeys/${id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name: editName }),
      });
      if (resp.ok) {
        toast.success('Key renamed.');
        setEditingId(null);
        await fetchPasskeys();
      }
    } catch {
      toast.error('Failed to rename key.');
    }
  };

  const handleRevoke = async (id: string) => {
    if (!confirm('Revoke this security key? Biometric data will be purged from the vault.')) return;
    try {
      const resp = await fetch(`/api/admin/webauthn/passkeys/${id}`, { method: 'DELETE' });
      if (resp.ok) {
        toast.success('Passkey revoked.');
        await fetchPasskeys();
      }
    } catch {
      toast.error('Failed to revoke passkey.');
    }
  };

  return (
