          </div>
          <h2 className="text-3xl font-black text-white tracking-tight">Biometric Vault</h2>
          <p className="text-sm text-slate-400 mt-1 font-medium">Standardized forensic audit trail and hardware isolation.</p>
        </div>

        <button 
          onClick={handleRegisterPasskey}
          disabled={registering}
          className="flex items-center gap-3 bg-blue-600 hover:bg-blue-500 text-white px-8 py-4 rounded-2xl text-xs font-black uppercase tracking-widest transition-all shadow-[0_0_30px_rgba(37,99,235,0.3)] disabled:opacity-50"
        >
          {registering ? <RefreshCw className="w-4 h-4 animate-spin" /> : <Plus className="w-4 h-4" />}
          <span>Register Hardware Key</span>
        </button>
