        {loading ? (
          <div className="flex justify-center items-center py-20">
            <RefreshCw className="w-8 h-8 text-blue-500/20 animate-spin" />
          </div>
        ) : passkeys.length === 0 ? (
          <div className="text-center p-12 bg-slate-900/20 rounded-[2rem] border border-white/5 border-dashed">
            <Fingerprint className="w-12 h-12 text-slate-700 mx-auto mb-4" />
            <p className="text-slate-500 font-bold">No active biometric signatures detected.</p>
          </div>
        ) : (
          <AnimatePresence mode="popLayout">
            {passkeys.map((pk, idx) => {
              const metadata = getPasskeyMetadata(pk.aaguid);
              return (
                <motion.div
                  key={pk.id}
                  initial={{ opacity: 0, y: 20 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ delay: idx * 0.1 }}
                  className="bg-slate-900/40 backdrop-blur-2xl border border-white/5 rounded-[2.5rem] overflow-hidden group hover:border-blue-500/30 transition-all duration-500"
                >
                  <div className="p-8">
                    {/* Header */}
                    <div className="flex flex-col md:flex-row md:items-center gap-6 mb-8">
                      <div className="relative">
                        <div className="w-16 h-16 rounded-2xl bg-white flex items-center justify-center p-3 shadow-2xl relative z-10">
                          {pk.logo || metadata.logo ? (
                            <img src={pk.logo || metadata.logo} alt="" className="w-full h-full object-contain" />
                          ) : (
                            <Fingerprint className="w-8 h-8 text-blue-500" />
                          )}
                        </div>
                        <div className="absolute inset-0 bg-blue-500/20 blur-2xl rounded-full scale-150 opacity-0 group-hover:opacity-100 transition-opacity" />
                      </div>

                      <div className="flex-1">
                        <div className="flex items-center gap-3">
                          {editingId === pk.id ? (
                            <div className="flex items-center gap-2">
                              <input 
                                type="text" 
                                value={editName}
                                onChange={(e) => setEditName(e.target.value)}
                                onKeyDown={(e) => e.key === 'Enter' && handleRename(pk.id)}
                                autoFocus
                                className="bg-slate-950 border border-blue-500 outline-none text-white text-lg font-black px-4 py-2 rounded-xl"
                              />
                              <button onClick={() => handleRename(pk.id)} className="bg-blue-500 text-white p-2 rounded-xl"><Check className="w-5 h-5" /></button>
                              <button onClick={() => setEditingId(null)} className="text-slate-500 hover:text-white p-2"><X className="w-5 h-5" /></button>
                            </div>
                          ) : (
                            <>
                              <h4 className="text-xl font-black text-white tracking-tight">{pk.name || 'Unnamed Signature'}</h4>
                              <button onClick={() => { setEditingId(pk.id); setEditName(pk.name || ''); }} className="opacity-0 group-hover:opacity-100 transition-opacity text-slate-500 hover:text-white">
                                <Settings className="w-4 h-4" />
                              </button>
                            </>
                          )}
                        </div>
                        <div className="flex flex-wrap items-center gap-4 mt-2">
                          <span className="text-[10px] font-black uppercase tracking-widest text-blue-400">
                            {pk.providerName || metadata.name}
                          </span>
                          <div className="w-1 h-1 bg-slate-700 rounded-full" />
                          <span className="flex items-center gap-1.5 text-[9px] font-black uppercase tracking-widest text-emerald-400 bg-emerald-500/10 px-2 py-0.5 rounded-md border border-emerald-500/20">
                            <ShieldCheck className="w-3 h-3" />
                            {pk.securityLevel || metadata.securityLevel}
                          </span>
                        </div>
                      </div>

                      <button 
                        onClick={() => handleRevoke(pk.id)}
                        className="self-start md:self-auto p-4 bg-rose-500/5 hover:bg-rose-500 text-rose-500 hover:text-white rounded-2xl border border-rose-500/10 transition-all"
                      >
                        <Trash2 className="w-5 h-5" />
                      </button>
                    </div>

                    {/* Forensic Panel */}
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-8 pt-8 border-t border-white/5">
                      <div className="space-y-4">
                        <div className="flex items-center gap-2 text-slate-500">
                          <HardDrive className="w-4 h-4" />
                          <span className="text-[10px] font-black uppercase tracking-widest">Hardware</span>
                        </div>
                        <div className="space-y-2">
                          <div className="flex flex-col">
                            <span className="text-[10px] font-bold text-slate-500 uppercase">Manufacturer</span>
                            <span className="text-sm font-bold text-white">{pk.manufacturer || metadata.manufacturer}</span>
                          </div>
                          <div className="flex flex-col">
                            <span className="text-[10px] font-bold text-slate-500 uppercase">Usage Counter</span>
                            <span className="text-sm font-bold text-blue-400">{pk.counter} Auth Events</span>
                          </div>
                        </div>
                      </div>

                      <div className="space-y-4">
                        <div className="flex items-center gap-2 text-slate-500">
                          <Activity className="w-4 h-4" />
                          <span className="text-[10px] font-black uppercase tracking-widest">Network</span>
                        </div>
                        <div className="space-y-2">
                          <div className="flex items-center gap-3">
                            <span className="text-[9px] font-black px-1.5 py-0.5 bg-white/5 rounded text-slate-400">IPv4</span>
                            <span className="text-xs font-mono text-white">{pk.lastUsedIpV4 || '—'}</span>
                          </div>
                          <div className="flex items-center gap-3">
                            <span className="text-[9px] font-black px-1.5 py-0.5 bg-white/5 rounded text-slate-400">IPv6</span>
                            <span className="text-xs font-mono text-white truncate max-w-[120px]">{pk.lastUsedIpV6 || '—'}</span>
                          </div>
                        </div>
                      </div>

                      <div className="space-y-4">
                        <div className="flex items-center gap-2 text-slate-500">
                          <MapPin className="w-4 h-4" />
                          <span className="text-[10px] font-black uppercase tracking-widest">Geolocation</span>
                        </div>
                        <div className="space-y-2">
                          <div className="flex flex-col">
                            <span className="text-sm font-bold text-white">{pk.city ? `${pk.city}, ${pk.country}` : 'Unknown Location'}</span>
                            <div className="flex items-center gap-1.5 text-[10px] font-bold text-slate-500 mt-0.5">
                              <Compass className="w-3 h-3" /> {pk.latitude || '0.0'}, {pk.longitude || '0.0'}
                            </div>
                          </div>
                          <div className="flex flex-col">
                            <span className="text-[10px] font-bold text-slate-500 uppercase">Last Verification</span>
                            <span className="text-xs font-bold text-blue-400">{pk.lastUsedAt ? new Date(pk.lastUsedAt).toLocaleString() : 'Never'}</span>
                          </div>
                        </div>
                      </div>
                    </div>
                  </div>
                </motion.div>
              );
            })}
          </AnimatePresence>
        )}
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import toast from 'react-hot-toast';
import { ArrowLeft, Check, KeyRound, Lock, Mail, ShieldCheck, Sparkles, User, Fingerprint } from 'lucide-react';
import { startAuthentication, startRegistration } from '@simplewebauthn/browser';
import { DiscordLogo, GoogleIcon } from './brand-icons';
import { Footer } from '../foundation/common/Footer';

interface Props {
  appName: string;
}

export const FleetAuthGate: React.FC<Props> = ({ appName }) => {
  const [authMode, setAuthMode] = useState<'options' | 'password' | 'register' | 'passkey'>('options');
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [email, setEmail] = useState('');
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    const hash = window.location.hash;
    const params = new URLSearchParams(hash.split('?')[1]);
    const error = params.get('error');
    if (error) {
      toast.error(`Identity check failed: ${decodeURIComponent(params.get('message') || error)}`);
      window.location.hash = '#/';
    }
  }, []);

  const handleDiscordAuth = () => {
    window.location.href = '/api/auth/login/discord';
  };

  const handleGoogleAuth = () => {
    window.location.href = '/api/auth/login/google';
  };

  const handlePasswordLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!username || !password) {
      toast.error('Please enter your username and password');
      return;
    }

    setLoading(true);
    try {
      const res = await fetch('/api/auth/login/password', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ username, password }),
      });

      const data = await res.json() as any;
      if (!res.ok) {
        throw new Error(data.error || 'Authentication failed');
      }

      if (data.token) {
        localStorage.setItem('FOOD_AUTH_TOKEN', data.token);
      }
      toast.success('Successfully authenticated!');
      window.location.hash = '#/';
      window.location.reload();
    } catch (err: any) {
      toast.error(err.message || 'Login failed');
    } finally {
      setLoading(false);
    }
  };

  const handleRegister = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!username || !password || !email || !confirmPassword) {
      toast.error('Please fill in all registration fields');
      return;
    }

    if (password !== confirmPassword) {
      toast.error('Passwords do not match');
      return;
    }

    if (password.length < 8) {
      toast.error('Password must be at least 8 characters');
      return;
    }

    setLoading(true);
    try {
      const res = await fetch('/api/auth/register', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ username, password, email }),
      });

      const data = await res.json() as any;
      if (!res.ok) {
        throw new Error(data.error || 'Registration failed');
      }

      if (data.token) {
        localStorage.setItem('FOOD_AUTH_TOKEN', data.token);
      }
      toast.success('Account created successfully!');
      window.location.hash = '#/';
      window.location.reload();
    } catch (err: any) {
      toast.error(err.message || 'Registration failed');
    } finally {
      setLoading(false);
    }
  };

  const handlePasskeyAuth = async () => {
    setLoading(true);
    try {
      const optRes = await fetch('/api/auth/passkey/login-options');
      const optData = await optRes.json() as any;
      if (!optRes.ok) throw new Error(optData.error || 'Failed to initiate passkey');

      const authResp = await startAuthentication(optData);
      const verifyRes = await fetch('/api/auth/passkey/login-verify', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ response: authResp }),
      });

      const verifyData = await verifyRes.json() as any;
      if (!verifyRes.ok) throw new Error(verifyData.error || 'Passkey verification failed');

      if (verifyData.token) {
        localStorage.setItem('FOOD_AUTH_TOKEN', verifyData.token);
      }
      toast.success('Passkey authentication successful!');
      window.location.hash = '#/';
      window.location.reload();
    } catch (err: any) {
      toast.error(err.message || 'Passkey login failed');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="relative min-h-screen flex flex-col justify-between bg-[radial-gradient(ellipse_80%_80%_at_50%_-20%,rgba(6,182,212,0.18),rgba(255,255,255,0))] text-white selection:bg-cyan-500/30">
      {/* Background ambient orbs */}
      <div className="absolute top-1/4 left-1/4 -translate-x-1/2 -translate-y-1/2 w-96 h-96 bg-cyan-500/10 rounded-full blur-3xl pointer-events-none" />
      <div className="absolute bottom-1/4 right-1/4 translate-x-1/2 translate-y-1/2 w-96 h-96 bg-emerald-500/10 rounded-full blur-3xl pointer-events-none" />

      {/* Top Bar */}
      <header className="relative z-20 flex items-center justify-between p-6 max-w-7xl mx-auto w-full">
        <button
          onClick={() => window.location.hash = '#/'}
          className="inline-flex items-center gap-2 px-3.5 py-1.5 rounded-xl glass-panel border border-white/10 text-xs font-bold text-slate-300 hover:text-white hover:border-cyan-500/30 transition cursor-pointer"
        >
          <ArrowLeft className="w-4 h-4 text-cyan-400" />
          <span>Back to Landing</span>
        </button>
        <div className="flex items-center gap-2">
          <ShieldCheck className="w-4 h-4 text-emerald-400" />
          <span className="text-[11px] font-black uppercase tracking-widest text-slate-400">Fleet Identity Security</span>
        </div>
      </header>

      {/* Center Authentication Card */}
      <main className="relative z-10 flex flex-1 items-center justify-center px-4 py-8">
        <div className="w-full max-w-md glass-panel p-8 sm:p-10 rounded-3xl border border-white/10 shadow-2xl backdrop-blur-2xl space-y-6">
          {/* Header Branding */}
          <div className="text-center space-y-2">
            <div className="mx-auto flex h-20 w-20 items-center justify-center rounded-3xl border border-orange-500/30 bg-black/80 p-1 shadow-2xl shadow-orange-500/20 backdrop-blur-xl">
              <img
                src="/brand/logo.png"
                alt={`${appName} Logo`}
                className="h-full w-full object-cover rounded-2xl drop-shadow-lg"
              />
            </div>
            <h1 className="text-2xl sm:text-3xl font-black tracking-tight uppercase italic text-white pt-2">
              Sign In to {appName}
            </h1>
            <p className="text-xs font-medium text-slate-400 max-w-xs mx-auto">
              Secure dining coordination, potluck rosters, and dietary safety protocols.
            </p>
          </div>

          {/* Mode Tabs */}
          <div className="grid grid-cols-3 gap-1 p-1 bg-slate-950/70 border border-white/10 rounded-xl text-xs font-black">
            <button
              onClick={() => setAuthMode('options')}
              className={`py-2 rounded-lg transition-all cursor-pointer ${authMode === 'options' ? 'bg-cyan-500 text-slate-950 shadow-md' : 'text-slate-400 hover:text-white'}`}
            >
              SSO
            </button>
            <button
              onClick={() => setAuthMode('password')}
              className={`py-2 rounded-lg transition-all cursor-pointer ${authMode === 'password' ? 'bg-cyan-500 text-slate-950 shadow-md' : 'text-slate-400 hover:text-white'}`}
            >
              Password
            </button>
            <button
              onClick={() => setAuthMode('register')}
              className={`py-2 rounded-lg transition-all cursor-pointer ${authMode === 'register' ? 'bg-cyan-500 text-slate-950 shadow-md' : 'text-slate-400 hover:text-white'}`}
            >
              Register
            </button>
          </div>

          {/* Mode 1: SSO & Passkey Options */}
          {authMode === 'options' && (
            <div className="space-y-3 pt-2">
              <button
                onClick={handleDiscordAuth}
                className="group flex h-12 w-full items-center justify-center gap-3 rounded-2xl bg-[#5865F2] hover:bg-[#4752C4] active:bg-[#3c45a5] px-4 text-xs font-black uppercase tracking-wider text-white transition shadow-lg shadow-[#5865F2]/20 hover:scale-[1.01] active:scale-[0.99] cursor-pointer"
              >
                <DiscordLogo className="h-5 w-5 group-hover:scale-110 transition-transform" />
                <span>Continue with Discord</span>
              </button>

              <button
                onClick={handleGoogleAuth}
                className="flex h-12 w-full items-center justify-center gap-3 rounded-2xl border border-white/10 bg-white hover:bg-slate-100 active:bg-slate-200 px-4 text-xs font-black uppercase tracking-wider text-zinc-950 transition shadow-lg shadow-white/5 hover:scale-[1.01] active:scale-[0.99] cursor-pointer"
              >
                <GoogleIcon className="h-5 w-5" />
                <span>Continue with Google</span>
              </button>

              <div className="relative my-4 flex items-center justify-center">
                <div className="border-t border-white/10 w-full" />
                <span className="bg-slate-900 px-3 text-[10px] font-black uppercase tracking-widest text-slate-500 absolute">
                  Or Passkey
                </span>
              </div>

              <button
                onClick={handlePasskeyAuth}
                disabled={loading}
                className="flex h-12 w-full items-center justify-center gap-3 rounded-2xl border border-cyan-500/30 bg-cyan-500/10 hover:bg-cyan-500/20 active:bg-cyan-500/30 px-4 text-xs font-black uppercase tracking-wider text-cyan-300 transition shadow-lg shadow-cyan-500/10 hover:scale-[1.01] active:scale-[0.99] cursor-pointer disabled:opacity-50"
              >
                <Fingerprint className="h-5 w-5 text-cyan-400" />
                <span>{loading ? 'Authenticating...' : 'Sign In with Passkey / Biometrics'}</span>
              </button>
            </div>
          )}

          {/* Mode 2: Password Login */}
          {authMode === 'password' && (
            <form onSubmit={handlePasswordLogin} className="space-y-4 pt-2">
              <div className="space-y-1">
                <label htmlFor="login-username" className="text-[11px] font-black uppercase tracking-wider text-slate-400 flex items-center gap-1.5">
                  <User className="w-3.5 h-3.5 text-cyan-400" />
                  Username
                </label>
                <input
                  id="login-username"
                  name="username"
                  type="text"
                  autoComplete="username"
                  value={username}
                  onChange={(e) => setUsername(e.target.value)}
                  placeholder="e.g. food_master"
                  className="w-full bg-slate-950/80 border border-white/10 rounded-xl px-4 py-2.5 text-xs text-white placeholder-slate-600 focus:border-cyan-500 focus:ring-1 focus:ring-cyan-500"
                  required
                />
              </div>

              <div className="space-y-1">
                <label htmlFor="login-password" className="text-[11px] font-black uppercase tracking-wider text-slate-400 flex items-center gap-1.5">
                  <Lock className="w-3.5 h-3.5 text-cyan-400" />
                  Password
                </label>
                <input
                  id="login-password"
                  name="password"
                  type="password"
                  autoComplete="current-password"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  placeholder="••••••••••••"
                  className="w-full bg-slate-950/80 border border-white/10 rounded-xl px-4 py-2.5 text-xs text-white placeholder-slate-600 focus:border-cyan-500 focus:ring-1 focus:ring-cyan-500"
                  required
                />
              </div>

              <button
                type="submit"
                disabled={loading}
                className="flex h-12 w-full items-center justify-center gap-2 rounded-2xl bg-gradient-to-r from-cyan-400 to-emerald-400 text-slate-950 px-4 text-xs font-black uppercase tracking-wider transition hover:opacity-90 shadow-lg shadow-cyan-500/20 active:scale-[0.99] cursor-pointer disabled:opacity-50"
              >
                <KeyRound className="w-4 h-4" />
                <span>{loading ? 'Authenticating...' : 'Sign In with Password'}</span>
              </button>
            </form>
          )}

          {/* Mode 3: Registration */}
          {authMode === 'register' && (
            <form onSubmit={handleRegister} className="space-y-4 pt-2">
              <div className="space-y-1">
                <label htmlFor="register-username" className="text-[11px] font-black uppercase tracking-wider text-slate-400 flex items-center gap-1.5">
                  <User className="w-3.5 h-3.5 text-cyan-400" />
                  Desired Username
                </label>
                <input
                  id="register-username"
                  name="username"
                  type="text"
                  autoComplete="username"
                  value={username}
                  onChange={(e) => setUsername(e.target.value)}
                  placeholder="e.g. host_jane"
                  className="w-full bg-slate-950/80 border border-white/10 rounded-xl px-4 py-2.5 text-xs text-white placeholder-slate-600 focus:border-cyan-500 focus:ring-1 focus:ring-cyan-500"
                  required
                />
              </div>

              <div className="space-y-1">
                <label htmlFor="register-email" className="text-[11px] font-black uppercase tracking-wider text-slate-400 flex items-center gap-1.5">
                  <Mail className="w-3.5 h-3.5 text-emerald-400" />
                  Email Address
                </label>
                <input
                  id="register-email"
                  name="email"
                  type="email"
                  autoComplete="email"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  placeholder="jane@example.com"
                  className="w-full bg-slate-950/80 border border-white/10 rounded-xl px-4 py-2.5 text-xs text-white placeholder-slate-600 focus:border-cyan-500 focus:ring-1 focus:ring-cyan-500"
                  required
                />
              </div>

              <div className="space-y-1">
                <label htmlFor="register-password" className="text-[11px] font-black uppercase tracking-wider text-slate-400 flex items-center gap-1.5">
                  <Lock className="w-3.5 h-3.5 text-cyan-400" />
                  Password
                </label>
                <input
                  id="register-password"
                  name="password"
                  type="password"
                  autoComplete="new-password"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  placeholder="••••••••••••"
                  className="w-full bg-slate-950/80 border border-white/10 rounded-xl px-4 py-2.5 text-xs text-white placeholder-slate-600 focus:border-cyan-500 focus:ring-1 focus:ring-cyan-500"
                  required
                />
              </div>

              {/* Dynamic Password Checklist */}
              {password.length > 0 && (
                <div className="p-3 bg-slate-950/60 border border-white/5 rounded-2xl space-y-1.5 animate-fadeIn">
                  <p className="text-[10px] font-black uppercase tracking-wider text-slate-400">Password Strength</p>
                  <div className="grid grid-cols-2 gap-1.5 text-[11px]">
                    <div className={`flex items-center gap-1.5 ${password.length >= 8 ? 'text-emerald-400' : 'text-slate-500'}`}>
                      <Check className={`w-3.5 h-3.5 ${password.length >= 8 ? 'text-emerald-400' : 'text-slate-600'}`} />
                      <span>8+ characters</span>
                    </div>
                    <div className={`flex items-center gap-1.5 ${/[A-Z]/.test(password) ? 'text-emerald-400' : 'text-slate-500'}`}>
                      <Check className={`w-3.5 h-3.5 ${/[A-Z]/.test(password) ? 'text-emerald-400' : 'text-slate-600'}`} />
                      <span>Uppercase letter</span>
                    </div>
                    <div className={`flex items-center gap-1.5 ${/[0-9]/.test(password) ? 'text-emerald-400' : 'text-slate-500'}`}>
                      <Check className={`w-3.5 h-3.5 ${/[0-9]/.test(password) ? 'text-emerald-400' : 'text-slate-600'}`} />
                      <span>Number</span>
                    </div>
                    <div className={`flex items-center gap-1.5 ${/[^A-Za-z0-9]/.test(password) ? 'text-emerald-400' : 'text-slate-500'}`}>
                      <Check className={`w-3.5 h-3.5 ${/[^A-Za-z0-9]/.test(password) ? 'text-emerald-400' : 'text-slate-600'}`} />
                      <span>Special character</span>
                    </div>
                  </div>
                </div>
              )}

              <div className="space-y-1">
                <div className="flex items-center justify-between">
                  <label htmlFor="register-confirm-password" className="text-[11px] font-black uppercase tracking-wider text-slate-400 flex items-center gap-1.5">
                    <ShieldCheck className="w-3.5 h-3.5 text-emerald-400" />
                    Confirm Password
                  </label>
                  {confirmPassword.length > 0 && (
                    <span className={`text-[10px] font-bold ${password === confirmPassword ? 'text-emerald-400' : 'text-rose-400'}`}>
                      {password === confirmPassword ? 'Passwords match' : 'Passwords do not match'}
                    </span>
                  )}
                </div>
                <input
                  id="register-confirm-password"
                  name="confirmPassword"
                  type="password"
                  autoComplete="new-password"
                  value={confirmPassword}
                  onChange={(e) => setConfirmPassword(e.target.value)}
                  placeholder="••••••••••••"
                  className={`w-full bg-slate-950/80 border rounded-xl px-4 py-2.5 text-xs text-white placeholder-slate-600 focus:ring-1 ${
