import React, { useEffect, useState } from 'react';
import { CalendarDays, Download, Globe, Share2 } from 'lucide-react';
import toast from 'react-hot-toast';

export interface ShareableEvent {
  id: number;
  title: string;
  description?: string | null;
  location?: string | null;
  eventDate?: string | null;
  startTime?: string | null;
  endTime?: string | null;
}

interface ShareBundle {
  calendar: string;
  outlook: string;
  yahoo: string;
  maps: string;
  icsUrl: string;
}

/**
 * Calendar export (.ics) + external calendar links + native device sharing.
 */
export function CalendarExport({ event }: { event: ShareableEvent }) {
  const [bundle, setBundle] = useState<ShareBundle | null>(null);

  useEffect(() => {
    let alive = true;
    fetch(`/api/events/${event.id}/share`)
      .then((r) => r.json())
      .then((json: any) => {
        if (alive && json.success) setBundle(json.data);
      })
      .catch(() => {});
    return () => {
      alive = false;
    };
  }, [event.id]);

  const nativeShare = async () => {
    const text = `${event.title}${event.eventDate ? ` — ${event.eventDate}` : ''}${event.location ? ` @ ${event.location}` : ''}`;
    if (navigator.share) {
      try {
        await navigator.share({ title: event.title, text, url: bundle?.icsUrl || window.location.href });
        return;
      } catch {
        /* fall through to clipboard */
      }
    }
    try {
      await navigator.clipboard.writeText(`${text} — ${window.location.href}`);
      toast.success('Event copied to clipboard');
    } catch {
      toast.error('Unable to share');
    }
  };

  return (
    <div className="flex flex-wrap gap-2">
      {bundle?.icsUrl && (
        <a href={bundle.icsUrl} download className="inline-flex items-center gap-2 rounded-lg border border-white/10 px-3 py-2 text-sm font-bold text-slate-200 hover:border-cyan-300/40">
          <Download className="h-4 w-4" />
          Calendar file
        </a>
      )}
      {bundle && (
        <>
          <a href={bundle.calendar} target="_blank" rel="noreferrer" title="Add to Google Calendar" className="inline-flex items-center gap-2 rounded-lg border border-white/10 px-3 py-2 text-sm font-bold text-slate-200 hover:border-cyan-300/40">
            <CalendarDays className="h-4 w-4" /> Google
          </a>
          <a href={bundle.outlook} target="_blank" rel="noreferrer" title="Add to Outlook" className="inline-flex items-center gap-2 rounded-lg border border-white/10 px-3 py-2 text-sm font-bold text-slate-200 hover:border-cyan-300/40">
            <Globe className="h-4 w-4" /> Outlook
          </a>
        </>
      )}
      <button onClick={nativeShare} className="inline-flex items-center gap-2 rounded-lg border border-cyan-300/30 px-3 py-2 text-sm font-bold text-cyan-200 hover:bg-cyan-500/10">
        <Share2 className="h-4 w-4" />
        Share
      </button>
    </div>
  );
}

