/**
 * Public guest invite landing — RSVP and claim without an account.
 * Access via #/invite/:id?token=...
 */
export function GuestInviteOverview({ token }: { token: string }) {
  const { user } = useAuth();
  const { canInstall, promptInstall } = useBeforeInstallPrompt();
  const [invite, setInvite] = useState<GuestInviteData | null>(null);
  const [status, setStatus] = useState<'going' | 'maybe' | 'declined'>('going');
  const [name, setName] = useState('');
  const [loading, setLoading] = useState(true);
  const [done, setDone] = useState(false);

  useEffect(() => {
    fetch(`/api/auth/guest/invite?token=${encodeURIComponent(token)}`)
      .then((r) => r.json())
      .then((json: any) => {
        if (json.success) {
          setInvite(json.data);
          setName(json.data.name || '');
        } else {
          toast.error(json?.message || 'Invalid invitation.');
        }
      })
      .catch(() => toast.error('Could not load invitation.'))
      .finally(() => setLoading(false));
  }, [token]);

  const rsvp = async () => {
    const res = await fetch('/api/auth/guest/rsvp', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ inviteToken: token, status, name, ...(invite?.email ? { email: invite.email } : {}) }),
    });
    const json: any = await res.json();
    if (!json.success) return toast.error(json?.message || 'RSVP failed');
    setDone(true);
    toast.success('See you there!');
  };

  if (loading) {
    return <div className="min-h-screen bg-slate-950 text-slate-50" />;
  }

  if (!invite) {
    return (
      <div className="flex min-h-screen items-center justify-center bg-slate-950 text-slate-50">
        <div className="text-center">
          <h1 className="text-2xl font-black">Invitation unavailable</h1>
          <p className="mt-2 text-sm text-slate-400">This link may be revoked or expired.</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-950 text-slate-50 antialiased flex flex-col">
      <div className="flex-1 w-full">
      <div className="mx-auto max-w-lg px-4 py-16">
        <div className="rounded-lg border border-white/10 bg-zinc-950/70 p-6">
          <div className="inline-flex items-center gap-2 rounded-lg border border-emerald-300/20 bg-emerald-400/10 px-3 py-1 text-xs font-black uppercase tracking-widest text-emerald-200">
            <CheckCircle2 className="h-4 w-4" /> You're invited
          </div>
          <h1 className="mt-4 text-3xl font-black tracking-tight">{invite.potluckTitle}</h1>
          <div className="mt-4 grid gap-2 text-sm font-bold text-slate-300">
            <span className="inline-flex items-center gap-2"><CalendarDays className="h-4 w-4 text-cyan-300" />{invite.potluckDate || 'Date pending'}</span>
            <span className="inline-flex items-center gap-2"><MapPin className="h-4 w-4 text-emerald-300" />{invite.potluckLocation || 'Location pending'}</span>
          </div>
          {invite.message && <p className="mt-4 text-sm font-medium leading-relaxed text-slate-400">{invite.message}</p>}

          {canInstall && (
            <button
              onClick={promptInstall}
              className="mt-5 inline-flex w-full items-center justify-center gap-2 rounded-lg border border-cyan-400/30 px-4 py-2.5 text-sm font-black text-cyan-200 transition hover:bg-cyan-500/10"
            >
              <Smartphone className="h-4 w-4" />
              Add to home screen
            </button>
          )}

          {done ? (
            <div className="mt-6 rounded-lg border border-emerald-400/30 bg-emerald-500/10 p-4 text-sm font-bold text-emerald-200">
              RSVP recorded. See you there!
            </div>
          ) : (
            <div className="mt-6 space-y-4">
              {!user && (
                <div className="grid gap-2 md:grid-cols-2">
                  <label className="text-xs font-bold uppercase text-slate-500">Your name
                    <input value={name} onChange={(e) => setName(e.target.value)} className="mt-1 w-full rounded-lg border border-white/10 bg-black/30 px-3 py-2 text-sm font-medium text-white outline-none focus:border-emerald-400" />
                  </label>
                </div>
              )}
              <div className="flex gap-2">
                {(['going', 'maybe', 'declined'] as const).map((s) => (
                  <button key={s} onClick={() => setStatus(s)} className={`flex-1 rounded-lg border px-4 py-2.5 text-sm font-black capitalize ${status === s ? 'border-emerald-400 bg-emerald-400 text-zinc-950' : 'border-white/10 text-slate-300 hover:border-white/20'}`}>{s}</button>
                ))}
              </div>
              <button onClick={rsvp} className="w-full rounded-lg bg-emerald-400 px-4 py-3 text-sm font-black text-zinc-950 hover:bg-emerald-300">RSVP</button>
            </div>
          )}
        </div>
      </div>
      </div>

      <Footer appName="FOOD" version="Stable" />
    </div>
  );
}

