export const GuestCheckInKiosk: React.FC<{ potluckId: number }> = ({ potluckId }) => {
  const [guests, setGuests] = useState<GuestRecord[]>([]);
  const [search, setSearch] = useState('');
  const [loading, setLoading] = useState(true);

  const fetchGuests = async () => {
    try {
      const res = await fetch(`/api/potlucks/${potluckId}/rsvps`);
      if (res.ok) {
        const data = (await res.json()) as GuestRecord[];
        setGuests(data);
      }
    } catch {
      toast.error('Failed to load guest list');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchGuests();

    const onMutation = (event: Event) => {
      const detail = (event as CustomEvent).detail;
      if (!detail?.resource || String(detail.resource).includes('rsvps') || String(detail.resource).includes('potlucks')) {
        fetchGuests();
      }
    };
    window.addEventListener('food-api-mutate', onMutation);

    const livePoll = setInterval(() => {
      if (document.visibilityState === 'visible') {
        fetchGuests();
      }
    }, 5000);

    return () => {
      window.removeEventListener('food-api-mutate', onMutation);
      clearInterval(livePoll);
    };
  }, [potluckId]);

  const handleCheckIn = async (guestId: number) => {
    try {
      const res = await fetch(`/api/potlucks/${potluckId}/rsvps/${guestId}/checkin`, {
        method: 'POST',
      });
      if (res.ok) {
        toast.success('Guest Checked In! 🎉');
        setGuests(prev => prev.map(g => g.id === guestId ? { ...g, checkedIn: 1 } : g));
      }
    } catch {
      toast.error('Check-in failed');
    }
  };

  const filteredGuests = guests.filter(g => {
    const name = (g.displayName || g.guestName || '').toLowerCase();
    return name.includes(search.toLowerCase());
  });

  const checkedInCount = guests.filter(g => g.checkedIn === 1).length;

  return (
    <div className="rounded-2xl border border-slate-800 bg-slate-900/60 p-6 backdrop-blur-xl shadow-xl space-y-6">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <div className="flex items-center space-x-2 text-cyan-400">
            <UserCheck className="w-5 h-5" />
            <h2 className="text-lg font-black uppercase tracking-wider text-white">Event Check-In Kiosk</h2>
          </div>
          <p className="text-xs text-slate-400 mt-1">1-Tap arrival scanner & guest list manager</p>
        </div>

        <div className="flex items-center gap-3">
          <div className="px-4 py-2 bg-slate-950 border border-slate-800 rounded-xl text-center">
            <span className="text-[10px] uppercase font-bold text-slate-500 block">Checked In</span>
            <span className="text-sm font-black text-cyan-400">{checkedInCount} / {guests.length}</span>
          </div>
        </div>
      </div>

      {/* Search Bar */}
      <div className="relative">
        <Search className="w-4 h-4 text-slate-500 absolute left-3 top-3.5" />
        <input
          type="text"
          value={search}
          onChange={e => setSearch(e.target.value)}
          placeholder="Search attendee by name..."
          className="w-full pl-9 pr-4 py-2.5 bg-slate-950/80 border border-slate-800 rounded-xl text-sm text-white focus:border-cyan-500 outline-none"
        />
      </div>

      {/* Guest List */}
      <div className="divide-y divide-slate-800/60 max-h-96 overflow-y-auto pr-1">
        {filteredGuests.map(guest => {
          const name = guest.displayName || guest.guestName || 'Anonymous Guest';
          const totalHeads = (guest.adultCount || 1) + (guest.kidCount || 0) + (guest.infantCount || 0);

          return (
            <div key={guest.id} className="py-3.5 flex items-center justify-between gap-4">
              <div className="space-y-1">
                <div className="flex items-center space-x-2">
                  <span className="text-sm font-bold text-white">{name}</span>
                  {totalHeads > 1 && (
                    <span className="px-2 py-0.5 bg-slate-800 text-slate-300 text-[10px] font-bold rounded-md">
                      +{totalHeads - 1} Guests
                    </span>
                  )}
                  {guest.tableAssignment && (
                    <span className="px-2 py-0.5 bg-cyan-950 text-cyan-300 border border-cyan-800 text-[10px] font-bold rounded-md">
                      {guest.tableAssignment}
                    </span>
                  )}
                </div>

                <div className="flex flex-wrap gap-2 text-[10px] text-slate-400 font-medium">
                  <span>Adults: {guest.adultCount || 1}</span>
                  {guest.kidCount > 0 && <span>Kids: {guest.kidCount}</span>}
                  {guest.isBringingAnimals === 1 && (
                    <span className="text-amber-400 flex items-center gap-1 font-bold">
                      <Dog className="w-3 h-3" /> Animal Accompanying
                    </span>
                  )}
                </div>
              </div>

              <div>
                {guest.checkedIn === 1 ? (
                  <span className="inline-flex items-center gap-1.5 px-3 py-1.5 bg-emerald-500/10 border border-emerald-500/30 text-emerald-400 text-xs font-black uppercase tracking-wider rounded-xl">
                    <CheckCircle2 className="w-3.5 h-3.5" /> Arrived
                  </span>
                ) : (
                  <button
                    onClick={() => handleCheckIn(guest.id)}
                    className="px-4 py-1.5 bg-cyan-500 hover:bg-cyan-400 text-black text-xs font-black uppercase tracking-wider rounded-xl shadow-lg transition-all cursor-pointer"
                  >
                    Check In
                  </button>
                )}
