function statusTone(status: string) {
  if (status === 'completed') return 'border-emerald-400/30 bg-emerald-500/10 text-emerald-300';
  if (status === 'cancelled') return 'border-rose-400/30 bg-rose-500/10 text-rose-300';
  if (status === 'active') return 'border-amber-400/30 bg-amber-500/10 text-amber-300';
  return 'border-cyan-400/30 bg-cyan-500/10 text-cyan-300';
}

function formatEventDate(value?: string | null) {
  if (!value) return 'Date pending';
  const parsed = new Date(value);
  if (Number.isNaN(parsed.getTime())) return value;
  return parsed.toLocaleString([], { dateStyle: 'medium', timeStyle: 'short' });
}

function groupedDishes(dishes: PotluckDish[]) {
  return DISH_CATEGORIES.reduce((acc: Record<string, PotluckDish[]>, category) => {
    acc[category] = dishes.filter((dish) => dish.category === category);
    return acc;
  }, {});
}

