          onChange={(event) => setForm({ ...form, description: event.target.value })} 
          placeholder="Theme, allergies, parking, arrival notes" 
          className="min-h-20 rounded-xl border border-white/10 bg-slate-950/80 px-3.5 py-2.5 text-sm text-white placeholder-slate-500 outline-none transition focus:border-cyan-400 focus:bg-slate-900" 
        />
        <button 
          disabled={saving} 
          className="inline-flex items-center justify-center gap-2 rounded-xl bg-gradient-to-r from-cyan-500 to-emerald-400 px-4 py-2.5 text-xs font-black uppercase tracking-wider text-slate-950 transition hover:opacity-90 active:scale-[0.98] disabled:opacity-50 shadow-lg shadow-cyan-500/20"
        >
          <Plus className="h-4 w-4" />
          Create Event
        </button>
      </div>
    </form>
  );
}

function DishComposer({
  onSubmit,
  saving,
}: {
  onSubmit: (form: DishForm) => Promise<unknown>;
  saving: boolean;
}) {
  const [form, setForm] = useState<DishForm>(EMPTY_DISH);

  const submit = async (event: React.FormEvent) => {
    event.preventDefault();
    if (!form.name.trim()) return toast.error('Name the item first');
    await onSubmit(form);
    setForm(EMPTY_DISH);
  };

  return (
    <form onSubmit={submit} className="glass-card p-5 border border-white/10 bg-slate-900/40">
      <div className="grid gap-3 lg:grid-cols-[1fr_160px_auto]">
        <input 
          value={form.name} 
          onChange={(event) => setForm({ ...form, name: event.target.value })} 
          placeholder="Add food, drinks, or supplies" 
          className="rounded-xl border border-white/10 bg-slate-950/80 px-3.5 py-2.5 text-sm text-white placeholder-slate-500 outline-none transition focus:border-emerald-400 focus:bg-slate-900" 
        />
        <select 
          value={form.category} 
          onChange={(event) => setForm({ ...form, category: event.target.value })} 
          className="rounded-xl border border-white/10 bg-slate-950/80 px-3.5 py-2.5 text-sm text-white outline-none transition focus:border-emerald-400 focus:bg-slate-900"
        >
          {DISH_CATEGORIES.map((category) => <option key={category} value={category}>{CATEGORY_LABELS[category]}</option>)}
        </select>
        <button 
          disabled={saving} 
          className="inline-flex items-center justify-center gap-2 rounded-xl bg-emerald-400 px-5 py-2.5 text-xs font-black uppercase tracking-wider text-slate-950 transition hover:bg-emerald-300 active:scale-[0.98] disabled:opacity-60 shadow-lg shadow-emerald-500/20"
        >
          <Plus className="h-4 w-4" />
          Add Item
        </button>
      </div>
      <div className="mt-3 grid gap-3 lg:grid-cols-[1fr_auto]">
        <input 
          value={form.notes} 
          onChange={(event) => setForm({ ...form, notes: event.target.value })} 
          placeholder="Notes, dietary details (e.g. GF, vegan, contains nuts)" 
          className="rounded-xl border border-white/10 bg-slate-950/80 px-3.5 py-2 text-xs text-white placeholder-slate-500 outline-none transition focus:border-emerald-400 focus:bg-slate-900" 
        />
        <label className="inline-flex cursor-pointer items-center gap-2 rounded-xl border border-white/10 bg-slate-950/50 px-3.5 py-2 text-xs font-bold text-slate-300 hover:border-emerald-500/40">
          <input 
            type="checkbox" 
            checked={form.assignedToMe} 
            onChange={(event) => setForm({ ...form, assignedToMe: event.target.checked })} 
            className="rounded text-emerald-400 focus:ring-0"
          />
          I will bring this
        </label>
      </div>
      <div className="mt-3 flex flex-wrap gap-2">
        {QUICK_DISHES.map((item) => (
          <button 
            key={item.name} 
            type="button" 
            onClick={() => setForm({ ...form, ...item })} 
            className="rounded-lg border border-white/5 bg-white/5 px-2.5 py-1 text-[11px] font-bold text-slate-400 hover:border-emerald-400/40 hover:bg-emerald-500/10 hover:text-emerald-300 transition"
          >
            + {item.name}
          </button>
        ))}
      </div>
    </form>
  );
}

function DishRow({
  dish,
  mine,
  canManage,
  onClaim,
  onOpen,
  onSave,
  onDelete,
}: {
  dish: PotluckDish;
  mine: boolean;
  canManage: boolean;
  onClaim: () => void;
  onOpen: () => void;
  onSave: (form: Partial<DishForm>) => Promise<unknown>;
  onDelete: () => void;
}) {
  const [editing, setEditing] = useState(false);
  const [form, setForm] = useState({
    name: dish.name,
    category: dish.category,
    notes: dish.notes || '',
  });
  const contributor = dish.contributorName || dish.contributorUsername;

  useEffect(() => {
    setForm({
      name: dish.name,
      category: dish.category,
      notes: dish.notes || '',
    });
  }, [dish.id, dish.name, dish.category, dish.notes]);

  const save = async () => {
    if (!form.name.trim()) return toast.error('Name the item first');
    await onSave(form);
    setEditing(false);
  };

  return (
    <div className="rounded-2xl border border-white/5 bg-slate-950/70 p-3.5 transition hover:border-white/10 hover:bg-slate-900/60">
      {editing ? (
        <div className="space-y-3">
          <input 
            value={form.name} 
            onChange={(event) => setForm({ ...form, name: event.target.value })} 
            className="w-full rounded-xl border border-white/10 bg-slate-950 px-3 py-2 text-sm font-bold text-white outline-none focus:border-emerald-400" 
          />
          <div className="grid gap-2 md:grid-cols-[140px_1fr]">
            <select 
              value={form.category} 
              onChange={(event) => setForm({ ...form, category: event.target.value })} 
              className="rounded-xl border border-white/10 bg-slate-950 px-3 py-2 text-xs text-white outline-none focus:border-emerald-400"
            >
              {DISH_CATEGORIES.map((category) => <option key={category} value={category}>{CATEGORY_LABELS[category]}</option>)}
            </select>
            <input 
              value={form.notes} 
              onChange={(event) => setForm({ ...form, notes: event.target.value })} 
              placeholder="Notes" 
              className="rounded-xl border border-white/10 bg-slate-950 px-3 py-2 text-xs text-white outline-none focus:border-emerald-400" 
            />
          </div>
          <div className="flex justify-end gap-2">
            <button onClick={() => setEditing(false)} className="rounded-xl border border-white/10 px-3 py-1.5 text-xs font-bold text-slate-400 hover:text-white">Cancel</button>
            <button onClick={save} className="rounded-xl bg-emerald-400 px-4 py-1.5 text-xs font-black text-slate-950 hover:bg-emerald-300">Save</button>
          </div>
        </div>
      ) : (
        <div className="flex items-start justify-between gap-3">
          <div>
            <h4 className="font-bold text-white text-sm">{dish.name}</h4>
            {dish.notes && <p className="mt-1 text-xs font-medium text-slate-400">{dish.notes}</p>}
            <div className="mt-2.5 inline-flex items-center gap-1.5 rounded-lg bg-white/5 px-2 py-0.5 text-[11px] font-bold text-slate-300">
              <Users className="h-3 w-3 text-cyan-400" />
              {contributor ? (
                <span className={mine ? "text-cyan-300 font-black" : "text-slate-300"}>
                  {mine ? 'Claimed by you' : `Claimed by ${contributor}`}
                </span>
              ) : (
                <span className="text-amber-400/80 font-bold">Unclaimed / Needed</span>
              )}
            </div>
          </div>
          <div className="flex items-center gap-1">
            {dish.contributorId ? (
              (mine || canManage) && (
                <button onClick={onOpen} title="Mark unclaimed" className="rounded-lg border border-white/5 bg-white/5 p-1.5 text-slate-400 hover:bg-amber-500/20 hover:text-amber-300 transition">
                  <X className="h-3.5 w-3.5" />
                </button>
              )
            ) : (
              <button onClick={onClaim} title="I'll bring this" className="rounded-lg border border-emerald-500/20 bg-emerald-500/10 p-1.5 text-emerald-400 hover:bg-emerald-500/20 hover:scale-105 transition">
                <Check className="h-3.5 w-3.5" />
              </button>
            )}
            {(mine || canManage) && (
              <button onClick={() => setEditing(true)} title="Edit item" className="rounded-lg border border-white/5 bg-white/5 p-1.5 text-slate-400 hover:bg-cyan-500/20 hover:text-cyan-300 transition">
                <Pencil className="h-3.5 w-3.5" />
              </button>
            )}
            {(mine || canManage) && (
              <button onClick={onDelete} title="Remove item" className="rounded-lg border border-white/5 bg-white/5 p-1.5 text-slate-400 hover:bg-rose-500/20 hover:text-rose-300 transition">
                <Trash2 className="h-3.5 w-3.5" />
              </button>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

function PotluckBoard({
  potluck,
  canManage,
  userId,
  saving,
  onUpdatePotluck,
  onCreateDish,
  onUpdateDish,
  onDeleteDish,
  onDeletePotluck,
}: {
  potluck: PotluckRecord;
  canManage: boolean;
  userId?: string;
  saving: boolean;
  onUpdatePotluck: (id: number, form: Partial<PotluckForm>) => Promise<unknown>;
  onCreateDish: (potluckId: number, form: DishForm) => Promise<unknown>;
  onUpdateDish: (id: number, form: Partial<DishForm>) => Promise<unknown>;
  onDeleteDish: (id: number) => Promise<unknown>;
  onDeletePotluck: (id: number) => Promise<unknown>;
}) {
  const [pendingDelete, setPendingDelete] = useState(false);
  const [editingDetails, setEditingDetails] = useState(false);
  const [detailsForm, setDetailsForm] = useState<PotluckForm>({
    title: potluck.title,
    description: potluck.description || '',
    eventDate: potluck.eventDate || '',
    location: potluck.location || '',
    status: potluck.status,
  });
  const groups = useMemo(() => groupedDishes(potluck.dishes), [potluck.dishes]);
  const neededCategories = DISH_CATEGORIES.filter((category) => !potluck.summary.categoryCounts[category]);
  const progress = potluck.summary.totalDishes ? Math.round((potluck.summary.claimedDishes / potluck.summary.totalDishes) * 100) : 0;

  useEffect(() => {
    setEditingDetails(false);
    setDetailsForm({
      title: potluck.title,
      description: potluck.description || '',
      eventDate: potluck.eventDate || '',
      location: potluck.location || '',
      status: potluck.status,
    });
  }, [potluck.id, potluck.title, potluck.description, potluck.eventDate, potluck.location, potluck.status]);

  const copySummary = async () => {
    const lines = [
      potluck.title,
      `${formatEventDate(potluck.eventDate)} at ${potluck.location || 'Location pending'}`,
      '',
      ...DISH_CATEGORIES.map((category) => {
        const names = groups[category].map((dish) => `${dish.name}${dish.contributorId ? ' - claimed' : ' - open'}`);
        return `${CATEGORY_LABELS[category]}: ${names.length ? names.join(', ') : 'needed'}`;
      }),
    ];
    try {
      await navigator.clipboard.writeText(lines.join('\n'));
      toast.success('Plan copied');
    } catch {
      toast.error('Unable to copy plan');
    }
  };

  const saveDetails = async () => {
    if (!detailsForm.title.trim()) return toast.error('Name the potluck first');
    await onUpdatePotluck(potluck.id, detailsForm);
    setEditingDetails(false);
  };

  return (
    <section className="space-y-6">
      <div className="glass-panel rounded-3xl p-6 lg:p-8 relative overflow-hidden border border-white/10">
        <div className="absolute top-0 right-0 h-48 w-48 bg-cyan-500/5 blur-3xl pointer-events-none rounded-full" />
        <div className="flex flex-col gap-6 lg:flex-row lg:items-start lg:justify-between relative z-10">
          <div>
            <div className={`mb-3 inline-flex rounded-full border px-3.5 py-1 text-[11px] font-black uppercase tracking-widest ${statusTone(potluck.status)}`}>
              {STATUS_LABELS[potluck.status] || potluck.status}
            </div>
            <h2 className="text-3xl lg:text-4xl font-black tracking-tight text-white">{potluck.title}</h2>
            <p className="mt-2.5 max-w-2xl text-sm font-medium text-slate-400 leading-relaxed">{potluck.description || 'No host notes provided yet.'}</p>
            <div className="mt-5 flex flex-wrap gap-4 text-xs font-bold text-slate-300">
              <span className="inline-flex items-center gap-2 rounded-xl bg-white/5 px-3 py-1.5 border border-white/5">
                <CalendarDays className="h-4 w-4 text-cyan-400" />
                {formatEventDate(potluck.eventDate)}
              </span>
              <span className="inline-flex items-center gap-2 rounded-xl bg-white/5 px-3 py-1.5 border border-white/5">
                <MapPin className="h-4 w-4 text-emerald-400" />
                {potluck.location || 'Location pending'}
              </span>
            </div>
          </div>
          <div className="flex flex-wrap items-center gap-2">
            <button onClick={copySummary} className="inline-flex items-center gap-2 rounded-xl border border-white/10 bg-slate-900/60 px-3.5 py-2 text-xs font-bold text-slate-200 hover:border-cyan-400/40 hover:bg-slate-800 transition">
              <Share2 className="h-3.5 w-3.5 text-cyan-400" />
              Share Plan
            </button>
            {canManage && <InviteGuests potluckId={potluck.id} />}
            <CalendarExport event={potluck} />
            {canManage && (
              <>
                <button onClick={() => setEditingDetails(true)} className="inline-flex items-center gap-2 rounded-xl border border-white/10 bg-slate-900/60 px-3.5 py-2 text-xs font-bold text-slate-200 hover:border-cyan-400/40 hover:bg-slate-800 transition">
                  <Pencil className="h-3.5 w-3.5 text-cyan-400" />
                  Edit
                </button>
                <button onClick={() => setPendingDelete(true)} className="inline-flex items-center gap-2 rounded-xl border border-rose-500/20 bg-rose-500/10 px-3.5 py-2 text-xs font-bold text-rose-300 hover:bg-rose-500/20 transition">
                  <Trash2 className="h-3.5 w-3.5" />
                  Delete
                </button>
              </>
            )}
          </div>
        </div>

        {editingDetails && (
          <div className="mt-6 grid gap-3.5 rounded-2xl border border-white/10 bg-slate-950/80 p-5 shadow-2xl">
            <input 
              value={detailsForm.title} 
              onChange={(event) => setDetailsForm({ ...detailsForm, title: event.target.value })} 
              className="rounded-xl border border-white/10 bg-slate-900 px-3.5 py-2.5 text-sm text-white outline-none focus:border-cyan-400" 
            />
            <div className="grid gap-3 md:grid-cols-2">
              <input 
                value={detailsForm.eventDate} 
                onChange={(event) => setDetailsForm({ ...detailsForm, eventDate: event.target.value })} 
                className="rounded-xl border border-white/10 bg-slate-900 px-3.5 py-2.5 text-sm text-white outline-none focus:border-cyan-400" 
              />
              <LocationField value={detailsForm.location} onChange={(v) => setDetailsForm({ ...detailsForm, location: v })} />
            </div>
            <textarea 
              value={detailsForm.description} 
              onChange={(event) => setDetailsForm({ ...detailsForm, description: event.target.value })} 
              className="min-h-20 rounded-xl border border-white/10 bg-slate-900 px-3.5 py-2.5 text-sm text-white outline-none focus:border-cyan-400" 
            />
            <div className="flex justify-end gap-2.5">
              <button onClick={() => setEditingDetails(false)} className="rounded-xl border border-white/10 px-4 py-2 text-xs font-bold text-slate-400 hover:text-white">Cancel</button>
              <button onClick={saveDetails} className="rounded-xl bg-cyan-400 px-5 py-2 text-xs font-black text-slate-950 hover:bg-cyan-300 shadow-lg shadow-cyan-500/20">Save Details</button>
            </div>
          </div>
        )}

        {canManage && (
          <div className="mt-6 flex flex-wrap items-center gap-2 border-t border-white/5 pt-4">
            <span className="text-[11px] font-black uppercase tracking-wider text-slate-500 mr-2">Status:</span>
            {POTLUCK_STATUSES.map((status) => (
              <button 
                key={status} 
                onClick={() => onUpdatePotluck(potluck.id, { status })} 
                className={`rounded-xl border px-3 py-1.5 text-xs font-black uppercase tracking-wider transition ${potluck.status === status ? statusTone(status) : 'border-white/5 bg-white/5 text-slate-400 hover:text-white'}`}
              >
                {STATUS_LABELS[status]}
              </button>
            ))}
          </div>
        )}
      </div>

      <div className="grid gap-6 xl:grid-cols-[1fr_320px]">
        <div className="space-y-6">
          <DishComposer saving={saving} onSubmit={(form) => onCreateDish(potluck.id, form)} />
          <div className="grid gap-4 lg:grid-cols-2">
            {DISH_CATEGORIES.map((category) => (
              <div key={category} className="glass-card p-5 border border-white/10 bg-slate-900/30 flex flex-col justify-between">
                <div>
                  <div className="mb-3.5 flex items-center justify-between">
                    <h3 className="text-xs font-black uppercase tracking-widest text-slate-200">{CATEGORY_LABELS[category]}</h3>
                    <span className="rounded-lg bg-white/5 px-2.5 py-0.5 text-xs font-black text-cyan-400 border border-white/5">{groups[category].length}</span>
                  </div>
                  <div className="space-y-2.5">
                    {groups[category].length ? groups[category].map((dish) => (
                      <DishRow
                        key={dish.id}
                        dish={dish}
                        mine={dish.contributorId === userId}
                        canManage={canManage}
                        onClaim={() => onUpdateDish(dish.id, { assignedToMe: true })}
                        onOpen={() => onUpdateDish(dish.id, { assignedToMe: false })}
                        onSave={(form) => onUpdateDish(dish.id, form)}
                        onDelete={() => onDeleteDish(dish.id)}
                      />
                    )) : (
                      <div className="rounded-2xl border border-dashed border-white/10 p-5 text-center text-xs font-medium text-slate-500">
                        Nothing listed yet in this section.
                      </div>
                    )}
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>

        <aside className="space-y-6">
          <GoalProgressMeter potluck={potluck} onModeChange={(mode) => onUpdatePotluck(potluck.id, { progressMeterMode: mode })} />
          <GuestCheckInKiosk potluckId={potluck.id} />

          <div className="glass-card p-5 border border-white/10 bg-slate-900/40">
            <div className="flex items-center gap-2 text-cyan-300">
              <Clock className="h-4 w-4" />
              <h3 className="text-xs font-black uppercase tracking-widest text-slate-200">Pet & Venue Rules</h3>
            </div>
            <p className="mt-3 text-xs font-medium leading-relaxed text-slate-400">
              Policy: <strong className="text-cyan-400 uppercase font-black">{potluck.petPolicy?.replace(/_/g, ' ') || 'Service Animals Only'}</strong>. {potluck.petPolicyNotes || 'Kitchen areas must remain animal-free for food safety.'}
            </p>
          </div>
        </aside>
      </div>

      {pendingDelete && (
        <div className="fixed inset-0 z-[120] flex items-center justify-center bg-black/70 px-4 backdrop-blur-md">
          <div className="w-full max-w-sm rounded-3xl border border-rose-500/30 bg-slate-950 p-6 shadow-2xl">
            <h3 className="text-lg font-black text-white">Delete this potluck?</h3>
            <p className="mt-2 text-xs font-medium text-slate-400">This will permanently remove this potluck event and all dish assignments.</p>
            <div className="mt-6 flex justify-end gap-2.5">
              <button onClick={() => setPendingDelete(false)} className="rounded-xl px-4 py-2 text-xs font-bold text-slate-400 hover:text-white">Cancel</button>
              <button onClick={() => onDeletePotluck(potluck.id)} className="rounded-xl bg-rose-600 px-4 py-2 text-xs font-black text-white hover:bg-rose-500 shadow-lg shadow-rose-600/30">Delete Event</button>
            </div>
          </div>
        </div>
      )}
    </section>
  );
}

function InviteGuests({ potluckId }: { potluckId: number }) {
  const { inviteGuest } = useUsers();
  const [open, setOpen] = useState(false);
  const [form, setForm] = useState({ name: '', email: '', message: '' });

  const send = async () => {
    if (!form.name && !form.email) return toast.error('Add a name or email');
    try {
      const invite = await inviteGuest(potluckId, { name: form.name || undefined, email: form.email || undefined, message: form.message });
      if (invite?.link) {
        try {
          await navigator.clipboard.writeText(invite.link);
          toast.success('Invite link copied');
        } catch {
          toast.success('Invite created');
        }
      }
      setOpen(false);
    } catch (e: any) {
      toast.error(e.message);
    }
  };

  return (
    <div className="relative">
      <button onClick={() => setOpen((v) => !v)} className="inline-flex items-center gap-2 rounded-xl border border-white/10 bg-slate-900/60 px-3.5 py-2 text-xs font-bold text-slate-200 hover:border-emerald-400/40 hover:bg-slate-800 transition">
        <Users className="h-3.5 w-3.5 text-emerald-400" />
        Invite
      </button>
      {open && (
        <div className="absolute right-0 z-30 mt-2 w-80 rounded-2xl border border-white/10 bg-slate-950 p-5 shadow-2xl backdrop-blur-xl">
          <p className="text-xs font-black uppercase tracking-widest text-emerald-400">Invite a Guest</p>
          <input value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} placeholder="Guest name" className="mt-3 w-full rounded-xl border border-white/10 bg-slate-900 px-3.5 py-2 text-xs text-white outline-none focus:border-emerald-400" />
          <input value={form.email} onChange={(e) => setForm({ ...form, email: e.target.value })} placeholder="Email (optional)" className="mt-2 w-full rounded-xl border border-white/10 bg-slate-900 px-3.5 py-2 text-xs text-white outline-none focus:border-emerald-400" />
          <input value={form.message} onChange={(e) => setForm({ ...form, message: e.target.value })} placeholder="Personal note" className="mt-2 w-full rounded-xl border border-white/10 bg-slate-900 px-3.5 py-2 text-xs text-white outline-none focus:border-emerald-400" />
          <button onClick={send} className="mt-3.5 w-full rounded-xl bg-emerald-400 px-4 py-2 text-xs font-black uppercase tracking-wider text-slate-950 hover:bg-emerald-300 shadow-lg shadow-emerald-500/20">Generate Invite Link</button>
        </div>
      )}
    </div>
  );
}

