import React, { useState } from 'react';
import { Check, ClipboardList, Plus, ShoppingCart, Trash2 } from 'lucide-react';
import toast from 'react-hot-toast';
import { useShopping } from '../../hooks/use-shopping';

export function ShoppingBoard() {
  const state = useShopping();
  const [title, setTitle] = useState('');
  const [selected, setSelected] = useState<number | null>(null);
  const [item, setItem] = useState({ name: '', quantity: '1', category: 'General' });

  const list = state.data?.find((l) => l.id === selected) || state.data?.[0] || null;

  const submit = async () => {
    if (!title.trim()) return toast.error('Name the shopping list');
    const created = await state.createList({ title, status: 'active' });
    setTitle('');
    setSelected(created?.id);
  };

  const addItem = async () => {
    if (!item.name.trim() || !list) return toast.error('Add an item name');
    await state.addItem(list.id, item);
    setItem({ name: '', quantity: '1', category: item.category });
  };

  const bought = list?.items.filter((it) => it.isBought).length ?? 0;
  const total = list?.items.length ?? 0;

  return (
    <div className="mx-auto max-w-6xl px-4 py-10">
      <div className="flex items-center gap-2 text-amber-200">
        <ShoppingCart className="h-5 w-5" />
        <h1 className="text-xl font-black tracking-tight text-white">Shopping Lists</h1>
      </div>
      <p className="mt-1 text-sm font-medium text-slate-400">Keep the grocery run organized by category and dedication.</p>

      <div className="mt-6 grid gap-6 lg:grid-cols-[300px_1fr]">
        <aside className="space-y-4">
          <form onSubmit={(e) => { e.preventDefault(); submit(); }} className="rounded-lg border border-white/10 bg-zinc-950/70 p-4">
            <div className="flex items-center gap-2 text-amber-300"><Plus className="h-4 w-4" /><h2 className="text-sm font-black uppercase tracking-widest">New List</h2></div>
            <input value={title} onChange={(e) => setTitle(e.target.value)} placeholder="Saturday grocery run" className="mt-4 w-full rounded-lg border border-white/10 bg-black/30 px-3 py-2 text-sm text-white outline-none focus:border-amber-400" />
            <button disabled={state.mutating} className="mt-3 w-full rounded-lg bg-amber-400 px-4 py-2 text-sm font-black text-zinc-950 hover:bg-amber-300 disabled:opacity-60">Create</button>
          </form>
          <div className="rounded-lg border border-white/10 bg-zinc-950/70 p-3">
            <h2 className="px-1 pb-2 text-xs font-black uppercase tracking-widest text-slate-500">Lists</h2>
            <div className="scrollable-list space-y-2">
              {state.loading ? <div className="p-4 text-sm font-bold text-slate-400">Loading...</div> : state.data?.map((l) => (
                <div key={l.id} className={`rounded-lg border p-3 ${list?.id === l.id ? 'border-amber-300/40 bg-amber-500/10' : 'border-white/10 bg-black/20'}`}>
                  <div className="flex items-center justify-between gap-2">
                    <button onClick={() => setSelected(l.id)} className="text-left font-black text-white">{l.title}</button>
                    <button onClick={() => state.deleteList(l.id)} className="text-slate-500 hover:text-rose-300"><Trash2 className="h-4 w-4" /></button>
                  </div>
                  <div className="mt-1 text-xs font-bold text-slate-400">{l.items.filter((it) => !it.isBought).length} to buy</div>
                </div>
              ))}
            </div>
          </div>
        </aside>

        <div className="space-y-4">
          {list ? (
            <>
              <div className="rounded-lg border border-white/10 bg-zinc-950/70 p-4">
                <div className="flex flex-wrap items-center gap-3">
                  <input value={item.name} onChange={(e) => setItem({ ...item, name: e.target.value })} placeholder="Oat milk" className="flex-1 rounded-lg border border-white/10 bg-black/30 px-3 py-2 text-sm text-white outline-none focus:border-amber-400" />
                  <input value={item.quantity} onChange={(e) => setItem({ ...item, quantity: e.target.value })} placeholder="Qty" className="w-20 rounded-lg border border-white/10 bg-black/30 px-3 py-2 text-sm text-white outline-none focus:border-amber-400" />
                  <button onClick={addItem} disabled={state.mutating} className="rounded-lg bg-amber-400 px-4 py-2 text-sm font-black text-zinc-950 disabled:opacity-60">Add</button>
                </div>
              </div>

              <div className="rounded-lg border border-white/10 bg-zinc-950/70 p-4">
                <div className="flex items-center justify-between">
                  <h3 className="flex items-center gap-2 text-sm font-black uppercase tracking-widest text-white"><ClipboardList className="h-4 w-4 text-amber-200" /> {list.title}</h3>
                  <span className="text-xs font-bold text-slate-400">{bought}/{total} bought</span>
                </div>
                {total === 0 ? (
                  <p className="mt-3 text-sm font-medium text-slate-500">No items yet — add one above.</p>
                ) : (
                  <ul className="mt-3 space-y-2">
                    {list.items.map((it) => (
                      <li key={it.id} className={`flex items-center justify-between rounded-lg border px-3 py-2 ${it.isBought ? 'border-white/5 bg-black/40 opacity-60' : 'border-white/10 bg-black/20'}`}>
                        <div className="flex items-center gap-3">
                          <button onClick={() => state.updateItem(list.id, it.id, { isBought: !it.isBought })} className={`flex h-5 w-5 items-center justify-center rounded-full border ${it.isBought ? 'border-emerald-400 bg-emerald-400 text-zinc-950' : 'border-white/20 text-transparent hover:text-white/40'}`}>
                            <Check className="h-3.5 w-3.5" />
                          </button>
                          <div>
                            <p className={`font-bold ${it.isBought ? 'line-through text-slate-500' : 'text-white'}`}>{it.name}</p>
                            <p className="text-xs text-slate-500">{it.quantity} · {it.category}</p>
                          </div>
                        </div>
                        <button onClick={() => state.removeItem(list.id, it.id)} className="text-slate-500 hover:text-rose-300"><Trash2 className="h-4 w-4" /></button>
                      </li>
                    ))}
                  </ul>
                )}
                {bought > 0 && (
                  <button onClick={() => state.clearBought(list.id)} className="mt-4 rounded-lg border border-white/10 px-3 py-2 text-xs font-bold text-slate-300 hover:text-emerald-200">Clear bought items</button>
                )}
              </div>
            </>
          ) : (
            <div className="flex min-h-[60vh] items-center justify-center rounded-lg border border-dashed border-white/10 bg-black/20">
              <p className="text-sm font-medium text-slate-500">Create a shopping list to get started.</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

import React, { useEffect, useState } from 'react';
import { Lock, Shield, UserPlus, Users as UsersIcon } from 'lucide-react';
import toast from 'react-hot-toast';
import { useAuth } from '../../contexts/AuthContext';
import { useUsers } from '../../hooks/use-users';

const ROLE_OPTIONS = ['OWNER', 'EVENT_MANAGER', 'PARTICIPANT', 'GUEST'];
const ROLE_LABELS = ROLE_OPTIONS;

export function AccountAdmin() {
  const { user } = useAuth();
  const u = useUsers();
  const [roleChanges, setRoleChanges] = useState<Record<string, string>>({});
  const [merge, setMerge] = useState({ sourceUserId: '', targetUserId: '' });
  const [registrationEnabled, setRegistrationEnabled] = useState<boolean>(false);
  const [configBusy, setConfigBusy] = useState(false);

  useEffect(() => {
    u.listUsers();
    fetch('/api/config')
      .then((r) => r.json())
      .then((d: any) => setRegistrationEnabled(d?.data?.ENABLE_REGISTRATION === 'true'))
      .catch(() => {});
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const toggleRegistration = async () => {
    setConfigBusy(true);
    try {
      const next = !registrationEnabled;
      const res = await fetch('/api/admin/config', {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ key: 'ENABLE_REGISTRATION', value: String(next) }),
      });
      const json: any = await res.json();
      if (!res.ok) throw new Error(json?.error || json?.message || 'Failed to update registration');
      setRegistrationEnabled(next);
      toast.success(`Self-service sign-up ${next ? 'enabled' : 'disabled'}`);
    } catch (e: any) {
      toast.error(e.message || 'Update failed');
    } finally {
      setConfigBusy(false);
    }
  };

  const changeRole = async (id: string, role: string) => {
    const res = await u.setRole(id, role);
    const json: any = await res.json();
    if (!res.ok) return toast.error(json?.message || 'Failed to update role');
    toast.success('Role updated');
    u.listUsers();
  };

  const changeStatus = async (id: string, status: string) => {
    const res = await u.setStatus(id, status);
    const json: any = await res.json();
    if (!res.ok) return toast.error(json?.message || 'Failed to update status');
    toast.success('Status updated');
    u.listUsers();
  };

  const doMerge = async () => {
    if (!merge.sourceUserId || !merge.targetUserId) return toast.error('Choose both accounts');
    const res = await u.mergeAccounts(merge.sourceUserId, merge.targetUserId);
    const json: any = await res.json();
    if (!json.success) return toast.error(json?.message || 'Merge failed');
    toast.success('Accounts merged');
    u.listUsers();
  };

  return (
    <div className="mx-auto max-w-6xl px-4 py-10">
      <div className="flex items-center gap-2 text-violet-300">
        <UsersIcon className="h-5 w-5" />
        <h1 className="text-xl font-black tracking-tight text-white">Member Management</h1>
      </div>
      <p className="mt-1 text-sm font-medium text-slate-400">Manage roles, account status, and consolidate duplicate accounts. Sensitive actions require biometric verification.</p>

      <div className="mt-6 grid gap-6 lg:grid-cols-[1fr_340px]">
        <div className="rounded-lg border border-white/10 bg-zinc-950/70 p-4">
          <h2 className="flex items-center gap-2 text-sm font-black uppercase tracking-widest text-slate-400"><UsersIcon className="h-4 w-4" /> Members</h2>
          <div className="scrollable-list mt-3 space-y-2">
            {u.loading ? <div className="p-4 text-sm font-bold text-slate-400">Loading...</div> : u.users.map((row) => (
              <div key={row.id} className="flex flex-wrap items-center justify-between gap-3 rounded-lg border border-white/10 bg-black/20 px-3 py-3">
                <div className="flex items-center gap-3">
                  <div className="flex h-9 w-9 items-center justify-center rounded-full bg-white/10 font-black text-white">
                    {(row.displayName || row.username).slice(0, 1).toUpperCase()}
                  </div>
                  <div>
                    <p className="font-bold text-white">{row.displayName || row.username}</p>
                    <p className="text-xs text-slate-500">{row.email || row.username} · {row.identities.length ? `linked: ${row.identities.join(', ')}` : 'local'}</p>
                  </div>
                </div>
                <div className="flex items-center gap-2">
                  <span className={`rounded-lg border px-2 py-1 text-[10px] font-black uppercase ${row.status === 'active' ? 'border-emerald-400/30 text-emerald-300' : row.status === 'locked' ? 'border-amber-400/30 text-amber-300' : 'border-rose-400/30 text-rose-300'}`}>{row.status}</span>
                  <select
                    value={roleChanges[row.id] ?? row.globalRole}
                    onChange={(e) => {
                      setRoleChanges((s) => ({ ...s, [row.id]: e.target.value }));
                      changeRole(row.id, e.target.value);
                    }}
                    className="rounded-lg border border-white/10 bg-zinc-950 px-2 py-1.5 text-xs font-bold text-white"
                  >
                    {ROLE_LABELS.map((r) => <option key={r} value={r}>{r}</option>)}
                  </select>
                  {row.globalRole !== 'OWNER' && (
                    <button onClick={() => changeStatus(row.id, row.status === 'locked' ? 'active' : 'locked')} title="Lock / unlock" className="rounded-lg border border-white/10 p-2 text-slate-300 hover:text-amber-200"><Lock className="h-3.5 w-3.5" /></button>
                  )}
                </div>
              </div>
            ))}
          </div>
        </div>

        <div className="space-y-4">
          <div className="rounded-lg border border-white/10 bg-zinc-950/70 p-4">
            <h3 className="flex items-center gap-2 text-sm font-black uppercase tracking-widest text-slate-300"><UserPlus className="h-4 w-4" /> Self-service sign-up</h3>
            <p className="mt-2 text-xs font-medium leading-relaxed text-slate-400">Controls whether the "Create account" button is shown on the sign-in page and whether new registrations are accepted.</p>
            <button
              onClick={toggleRegistration}
              disabled={configBusy}
              className={`mt-3 inline-flex items-center gap-2 rounded-lg px-4 py-2 text-sm font-black transition disabled:opacity-60 ${registrationEnabled ? 'bg-emerald-400 text-zinc-950 hover:bg-emerald-300' : 'bg-white/10 text-slate-200 hover:bg-white/20'}`}
            >
              <span className={`h-2 w-2 rounded-full ${registrationEnabled ? 'bg-zinc-900' : 'bg-slate-400'}`} />
              {configBusy ? 'Saving…' : registrationEnabled ? 'Enabled — click to disable' : 'Disabled — click to enable'}
            </button>
          </div>

          <div className="rounded-lg border border-violet-400/20 bg-zinc-950/70 p-4">
            <h3 className="flex items-center gap-2 text-sm font-black uppercase tracking-widest text-violet-300"><Shield className="h-4 w-4" /> Merge accounts</h3>
            <p className="mt-2 text-xs font-medium leading-relaxed text-slate-400">Consolidate a duplicate or social account into a primary account. Only OWNER can merge.</p>
            <div className="mt-3 grid gap-2">
              <input value={merge.sourceUserId} onChange={(e) => setMerge({ ...merge, sourceUserId: e.target.value })} placeholder="Source user ID (kept)" className="rounded-lg border border-white/10 bg-black/30 px-3 py-2 text-xs text-white outline-none focus:border-violet-400" />
              <input value={merge.targetUserId} onChange={(e) => setMerge({ ...merge, targetUserId: e.target.value })} placeholder="Target user ID (kept)" className="rounded-lg border border-white/10 bg-black/30 px-3 py-2 text-xs text-white outline-none focus:border-violet-400" />
              <button onClick={doMerge} className="rounded-lg bg-violet-400 px-4 py-2 text-sm font-black text-zinc-950 hover:bg-violet-300">Merge</button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

