  const [pairingsLoading, setPairingsLoading] = useState(false)
  const [deleteConfirmPairingId, setDeleteConfirmPairingId] = useState(null)
  const [initialPairingIds, setInitialPairingIds] = useState([])

  // Avatar handling ref and state
  const fileInputRef = useRef(null)
  const [avatarAnchorEl, setAvatarAnchorEl] = useState(null)
  const [urlDialogOpen, setUrlDialogOpen] = useState(false)
  const [tempUrl, setTempUrl] = useState('')

  const [vrApproveCode, setVrApproveCode] = useState('')
  const [vrApproveMsg, setVrApproveMsg] = useState('')
  const [vrApproveSeverity, setVrApproveSeverity] = useState('info')
  const [deovrCopied, setDeovrCopied] = useState(false)
  const [deovrPairCode, setDeovrPairCode] = useState('')
  const [deovrPairExpires, setDeovrPairExpires] = useState(0)
  const [deovrPairLoading, setDeovrPairLoading] = useState(false)

  const handleGenerateDeoVRPair = async () => {
    setDeovrPairLoading(true)
    try {
      const res = await apiFetch('/deovr/pair', { method: 'POST' })
      if (res.ok) {
        const data = await res.json()
        setDeovrPairCode(data.user_code)
        setDeovrPairExpires(data.expires_in || 300)
      } else {
        const err = await res.json().catch(() => ({}))
        setSnackbar({ open: true, message: err.detail || 'Failed to generate DeoVR pairing code.', severity: 'error' })
      }
    } catch {
      setSnackbar({ open: true, message: 'Network error generating DeoVR pairing code.', severity: 'error' })
    } finally {
      setDeovrPairLoading(false)
    }
  }

  useEffect(() => {
    if (!deovrPairCode || deovrPairExpires <= 0) return
    const t = setInterval(() => {
      setDeovrPairExpires(prev => {
        if (prev <= 1) { setDeovrPairCode(''); return 0 }
        return prev - 1
      })
    }, 1000)
    return () => clearInterval(t)
  }, [deovrPairCode, deovrPairExpires])

  const handleApproveVrDevice = async () => {
    if (!vrApproveCode.trim()) return
    setVrApproveMsg('')
    try {
      const res = await apiFetch('/auth/pair/device/approve', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ user_code: vrApproveCode.trim(), device_name: 'VR Headset' })
      })
      if (res.ok) {
        setVrApproveSeverity('success')
        setVrApproveMsg('✅ VR Headset paired successfully! Your headset is now signed in.')
        setVrApproveCode('')
        fetchPairings()
      } else {
        const data = await res.json().catch(() => ({}))
        setVrApproveSeverity('error')
        setVrApproveMsg(data.detail || 'Failed to pair device. Please check the 6-digit code.')
      }
    } catch (err) {
      setVrApproveSeverity('error')
      setVrApproveMsg(err.message || 'Error connecting to pairing server.')
    }
  }

  useEffect(() => {
    let timer
    let pollTimer
    if (pairingCode && expiresIn > 0) {
      timer = setInterval(() => {
        setExpiresIn(prev => {
          if (prev <= 1) {
            setPairingCode('')
            return 300
          }
          return prev - 1
        })
      }, 1000)

      pollTimer = setInterval(() => {
        fetchPairings()
      }, 3000)
    }
    return () => {
      clearInterval(timer)
      clearInterval(pollTimer)
    }
  }, [pairingCode, expiresIn])

  useEffect(() => {
    if (pairingCode && pairings.length > 0) {
      const hasNewPairing = pairings.some(p => !initialPairingIds.includes(p.id))
      if (hasNewPairing) {
        setPairingCode('')
        setSnackbar({ open: true, message: 'Pairing successful! Device linked.', severity: 'success' })
      }
    }
  }, [pairings, pairingCode, initialPairingIds])

  useEffect(() => {
    fetchProfile()
    fetchPasskeys()
    fetchSsoLinks()
    fetchPairings()
