    }
  }

  const fetchPasskeys = async () => {
    try {
      const res = await apiFetch('/auth/passkeys')
      if (res.ok) {
        setPasskeys(await res.json())
      }
    } catch (err) {
      console.error(err)
    }
  }

  const fetchSsoLinks = async () => {
