                      <Typography variant="caption" sx={{ wordBreak: 'break-all' }}>
                        Server: {selectedLocalBackup.name}
                      </Typography>
                    </Alert>
                  )}
                </Box>

                {verifyData && verifyData.encrypted && !verifyData.decrypted_data && (
                  <Box sx={{ mt: 2, p: 2, border: '1px solid var(--accent-border)', borderRadius: '8px', backgroundColor: 'var(--accent-bg)' }}>
                    <Typography variant="body2" sx={{ fontWeight: 'bold', mb: 1, display: 'flex', alignItems: 'center', gap: 0.5 }}>
                      <LockIcon fontSize="small" sx={{ color: 'var(--accent)' }} /> Backup is Encrypted
                    </Typography>
                    <TextField
                      fullWidth
                      size="small"
                      label="Enter Decryption Passphrase"
                      type={showRestorePassword ? 'text' : 'password'}
                      value={restorePassword}
                      onChange={(e) => setRestorePassword(e.target.value)}
                      sx={{ mb: 2, '& .MuiInputBase-root': { backgroundColor: 'rgba(0,0,0,0.2)' } }}
                      slotProps={{ input: {
                        endAdornment: (
                          <InputAdornment position="end">
                            <IconButton onClick={() => setShowRestorePassword(!showRestorePassword)} edge="end" size="small">
                              {showRestorePassword ? <VisibilityOff fontSize="small" /> : <Visibility fontSize="small" />}
                            </IconButton>
                          </InputAdornment>
                        )
                      }}}
                    />
                    <Button
                      fullWidth
                      variant="contained"
                      onClick={handleDecryptVerify}
                      disabled={!restorePassword || decryptLoading}
                      sx={{ textTransform: 'none', backgroundColor: 'var(--accent)' }}
                    >
                      {decryptLoading ? <CircularProgress size={20} /> : 'Decrypt & Verify'}
                    </Button>
                  </Box>
                )}
              </Grid>

              <Grid xs={12} md={8}>
                {verifyData ? (
                  <Box>
                    <Typography variant="subtitle2" gutterBottom sx={{ fontWeight: 'bold' }}>
                      Verification Report
                    </Typography>

                    <Grid container spacing={2} sx={{ mb: 2 }}>
                      <Grid xs={12} sm={6}>
                        <Paper variant="outlined" sx={{ p: 2, bgcolor: 'rgba(255,255,255,0.03)', borderRadius: '12px', border: '1px solid rgba(255,255,255,0.08)' }}>
                          <Typography variant="caption" color="textSecondary">Backup Type</Typography>
                          <Typography variant="body1" sx={{ fontWeight: 'bold', textTransform: 'capitalize' }}>
                            {verifyData.type}
                          </Typography>
                        </Paper>
                      </Grid>
                      <Grid xs={12} sm={6}>
                        <Paper variant="outlined" sx={{ p: 2, bgcolor: 'rgba(255,255,255,0.03)', borderRadius: '12px', border: '1px solid rgba(255,255,255,0.08)' }}>
                          <Typography variant="caption" color="textSecondary">Encryption Mode</Typography>
                          <Typography variant="body1" sx={{ fontWeight: 'bold', display: 'flex', alignItems: 'center', gap: 0.5 }}>
                            {verifyData.encrypted ? (
                              <React.Fragment>
                                <LockIcon fontSize="small" sx={{ color: 'var(--accent)' }} /> AES-256 Encrypted
                              </React.Fragment>
                            ) : 'None (Plaintext)'}
                          </Typography>
                        </Paper>
                      </Grid>

                      <Grid xs={12}>
                        <Paper variant="outlined" sx={{ p: 2, bgcolor: 'rgba(255,255,255,0.03)', borderRadius: '12px', border: '1px solid rgba(255,255,255,0.08)' }}>
                          <Typography variant="caption" color="textSecondary">SHA-256 Checksum</Typography>
                          <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mt: 0.5 }}>
                            <Typography variant="body2" sx={{ fontFamily: 'var(--mono)', backgroundColor: 'var(--code-bg)', p: 0.5, borderRadius: '4px', wordBreak: 'break-all', flexGrow: 1 }}>
                              {verifyData.checksum || 'N/A'}
                            </Typography>
                            {verifyData.checksum && (
                              <IconButton size="small" onClick={() => copyToClipboard(verifyData.checksum)}>
                                <ContentCopyIcon fontSize="small" />
                              </IconButton>
                            )}
                          </Box>
                        </Paper>
                      </Grid>

                      <Grid xs={12}>
                        <Paper variant="outlined" sx={{ p: 2, bgcolor: 'rgba(255,255,255,0.03)', borderRadius: '12px', border: '1px solid rgba(255,255,255,0.08)' }}>
                          <Typography variant="caption" color="textSecondary">Signature Integrity Status</Typography>
                          <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mt: 0.5 }}>
                            {verifyData.verified_signature || (verifyData.encrypted && verifyData.decrypted_data) ? (
                              <React.Fragment>
                                <CheckCircleIcon sx={{ color: 'success.main' }} fontSize="small" />
                                <Typography variant="body2" sx={{ color: 'success.main', fontWeight: 'bold' }}>
                                  Verified Authenticity (Signature matches payload integrity)
                                </Typography>
                              </React.Fragment>
                            ) : (
                              <React.Fragment>
                                <WarningIcon sx={{ color: 'warning.main' }} fontSize="small" />
                                <Typography variant="body2" sx={{ color: 'warning.main' }}>
                                  Unsigned backup or custom-derived signature (Decrypted locally)
                                </Typography>
                              </React.Fragment>
                            )}
                          </Box>
                        </Paper>
                      </Grid>
                    </Grid>

                    {verifyData.decrypted_data && (
                      <Alert severity="success" sx={{ mb: 2 }}>
                        Ready to restore database. Payload verified successfully! Includes <strong>{verifyData.table_count}</strong> tables and <strong>{verifyData.record_count}</strong> records.
                      </Alert>
                    )}

                    {/* Collapsible Manual Verification Expander */}
                    <Accordion sx={{ backgroundColor: 'rgba(255,255,255,0.02)', border: '1px solid rgba(255,255,255,0.08)', borderRadius: '8px', overflow: 'hidden', mb: 2 }}>
                      <AccordionSummary expandIcon={<ExpandMoreIcon />}>
                        <Typography variant="body2" sx={{ fontWeight: 'bold', display: 'flex', alignItems: 'center', gap: 0.5 }}>
                          Manual Verification Protocol (Command-Line Python)
                        </Typography>
                      </AccordionSummary>
                      <AccordionDetails>
                        <Typography variant="caption" color="textSecondary" sx={{ display: 'block', mb: 1 }}>
                          Validate file integrity, authenticate signatures, and decrypt this backup file completely offline using Python.
                        </Typography>
                        <Box sx={{ position: 'relative' }}>
                          <Box sx={{ position: 'absolute', top: 5, right: 5 }}>
                            <Button size="small" variant="text" startIcon={<ContentCopyIcon />} onClick={() => copyToClipboard(pythonVerifierSnippet)} sx={{ textTransform: 'none', color: '#9ca3af' }}>
                              Copy Snippet
                            </Button>
                          </Box>
                          <pre style={{
                            margin: 0,
                            padding: '12px',
                            backgroundColor: '#1f2028',
                            borderRadius: '6px',
                            color: '#9ca3af',
                            fontSize: '0.75rem',
                            fontFamily: 'var(--mono)',
                            overflowX: 'auto'
                          }}>
                            {pythonVerifierSnippet}
                          </pre>
                        </Box>
                      </AccordionDetails>
                    </Accordion>

                    <Button
                      variant="contained"
                      color="warning"
                      onClick={handleRestore}
                      disabled={!verifyData.decrypted_data || restoreLoading}
                      fullWidth
                      sx={{ textTransform: 'none', py: 1, fontWeight: 'bold' }}
                    >
                      {restoreLoading ? <CircularProgress size={24} /> : 'Execute Database Restore'}
                    </Button>
                  </Box>
                ) : (
                  <Box sx={{ p: 4, border: '1px dashed rgba(255,255,255,0.2)', borderRadius: '8px', textAlign: 'center', color: 'text.secondary' }}>
                    No verified backup loaded. Upload a backup JSON or select one from the server-side backups list to proceed.
                  </Box>
                )}
              </Grid>
            </Grid>

            {restoreMessage && <Alert severity={restoreMessage.type} sx={{ mt: 2 }}>{restoreMessage.text}</Alert>}
          </GlassCard>
        </Grid>
      </Grid>
    </Box>
  )
}

import React, { useState, useEffect, useCallback } from 'react'
import { 
  Card, CardContent, Typography, Button, Grid, TextField, Box, 
  Dialog, DialogTitle, DialogContent, DialogActions, IconButton, Chip, Alert, Avatar
} from '@mui/material'
import { apiFetch } from '../api'
import { Landmark, Plus, Edit3, Trash2, Globe, Mail, Phone, Heart } from 'lucide-react'
import { MediaEntityCard } from './common'
import { getFaviconFromUrl } from '../utils/logoHelpers'

function BillerCardLogo({ biller }) {
  const [imgError, setImgError] = useState(false)
  const faviconUrl = getFaviconFromUrl(biller.url)

  useEffect(() => {
    setImgError(false)
  }, [biller.url])

  const initial = biller.name ? biller.name.charAt(0).toUpperCase() : '?'

  if (faviconUrl && !imgError) {
    return (
      <Box
        sx={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          p: 0.75,
          borderRadius: '12px',
          bgcolor: 'rgba(255, 255, 255, 0.12)',
          backdropFilter: 'blur(8px)',
          border: '1px solid rgba(255, 255, 255, 0.2)'
        }}
      >
        <Box 
          component="img" 
          src={faviconUrl} 
          alt={biller.name}
          onError={() => setImgError(true)}
          sx={{ 
            width: 44, 
            height: 44, 
            objectFit: 'contain',
            filter: 'drop-shadow(0px 0px 6px rgba(255, 255, 255, 0.65)) drop-shadow(0px 1px 3px rgba(0, 0, 0, 0.4))'
          }} 
        />
      </Box>
    )
  }

  return (
    <Avatar
      sx={{ 
        width: 50, 
        height: 50, 
        bgcolor: 'secondary.main', 
        color: 'secondary.contrastText',
        fontSize: '1.5rem', 
        fontWeight: 'bold'
      }}
    >
      {initial}
    </Avatar>
  )
}

export default function BillerList() {
  const [billers, setBillers] = useState([])
  const [favBillers, setFavBillers] = useState([])
  const [openBillerForm, setOpenBillerForm] = useState(false)
  const [editMode, setEditMode] = useState(false)
  const [billerFormId, setBillerFormId] = useState(null)

  const [billerForm, setBillerForm] = useState({
    name: '',
    url: '',
    support_email: '',
    support_phone: '',
    description: ''
  })

  const fetchBillers = useCallback(async () => {
    try {
      const response = await apiFetch('/billers')
      if (response.ok) {
        setBillers(await response.json())
      }
      const favRes = await apiFetch('/favorites')
      if (favRes.ok) {
        const favs = await favRes.json()
        setFavBillers(favs.biller || [])
      }
    } catch (error) {
      console.error('Failed to fetch billers:', error)
    }
  }, [])

  useEffect(() => {
    fetchBillers()
  }, [fetchBillers])

  const handleToggleFavorite = async (billerId, billerName) => {
    const stringId = String(billerId)
    try {
      const res = await apiFetch('/favorites/toggle', {
        method: 'POST',
        body: JSON.stringify({ item_type: 'biller', item_id: stringId })
      })
      if (res.ok) {
        const data = await res.json()
        if (data.favorited) {
          setFavBillers(prev => [...prev, stringId])
          window.dispatchEvent(new CustomEvent('show-toast', { 
            detail: { message: `Favorited ${billerName}!`, severity: 'success' } 
          }))
        } else {
          setFavBillers(prev => prev.filter(x => x !== stringId))
          window.dispatchEvent(new CustomEvent('show-toast', { 
            detail: { message: `Unfavorited ${billerName}.`, severity: 'info' } 
          }))
        }
      }
    } catch (e) {
      console.error(e)
    }
  }

  const handleOpenCreate = () => {
    setEditMode(false)
    setBillerFormId(null)
    setBillerForm({ name: '', url: '', support_email: '', support_phone: '', description: '' })
    setOpenBillerForm(true)
  }

  const handleOpenEdit = (biller) => {
    setEditMode(true)
    setBillerFormId(biller.id)
    setBillerForm({
      name: biller.name || '',
      url: biller.url || '',
      support_email: biller.support_email || '',
      support_phone: biller.support_phone || '',
      description: biller.description || ''
    })
    setOpenBillerForm(true)
  }

  const handleSaveBiller = async (e) => {
    e.preventDefault()
    try {
      const method = editMode ? 'PUT' : 'POST'
      const endpoint = editMode ? `/billers/${billerFormId}` : '/billers'
      const res = await apiFetch(endpoint, {
        method,
        body: JSON.stringify(billerForm)
      })

      if (res.ok) {
        window.dispatchEvent(new CustomEvent('show-toast', { 
          detail: { message: `Biller successfully ${editMode ? 'updated' : 'created'}!`, severity: 'success' } 
        }))
        setOpenBillerForm(false)
        fetchBillers()
      } else {
        const err = await res.json()
        window.dispatchEvent(new CustomEvent('show-toast', { detail: { message: err.detail, severity: 'error' } }))
      }
    } catch (err) {
      window.dispatchEvent(new CustomEvent('show-toast', { detail: { message: err.message, severity: 'error' } }))
    }
  }

  const handleDelete = async (id) => {
    const confirmed = await window.appConfirm('Are you sure you want to delete this biller? Associated subscriptions will clear their biller assignment.')
    if (!confirmed) return

    try {
      const res = await apiFetch(`/billers/${id}`, { method: 'DELETE' })
      if (res.ok) {
        window.dispatchEvent(new CustomEvent('show-toast', { detail: { message: 'Biller deleted!', severity: 'success' } }))
        fetchBillers()
      }
    } catch (err) {
      console.error(err)
    }
  }

  return (
    <Box sx={{ maxWidth: 1400, mx: 'auto', width: '100%' }}>
      <Box sx={{ display: 'flex', flexDirection: { xs: 'column', sm: 'row' }, justifyContent: 'space-between', alignItems: 'center', gap: 2, mb: 4 }}>
        <Typography variant="h4" sx={{ fontWeight: '800', letterSpacing: '-0.5px', display: 'flex', alignItems: 'center', justifyContent: { xs: 'center', sm: 'flex-start' }, gap: 1.5, textAlign: { xs: 'center', sm: 'left' } }}>
          <Box sx={{ p: 1, borderRadius: '12px', background: 'rgba(236, 72, 153, 0.15)', color: '#ec4899', display: 'flex', border: '1px solid rgba(236, 72, 153, 0.3)' }}>
            <Landmark size={28} />
          </Box>
          Subscription Billers
        </Typography>
        <Button 
          variant="contained" 
          startIcon={<Plus size={20} />} 
          onClick={handleOpenCreate} 
          sx={{ 
            width: { xs: '100%', sm: 'auto' },
            borderRadius: '12px',
            py: 1,
            px: 3,
            fontWeight: 'bold',
            background: 'linear-gradient(135deg, #ec4899 0%, #f43f5e 100%)',
            boxShadow: '0 8px 20px rgba(236, 72, 153, 0.3)',
            '&:hover': { boxShadow: '0 12px 24px rgba(236, 72, 153, 0.5)' }
          }}
        >
          Add Biller
        </Button>
      </Box>

      {/* Purpose Banner */}
      <Alert 
        severity="info" 
        icon={<Landmark size={20} />} 
        sx={{ 
          mb: 3, 
          borderRadius: '12px', 
          bgcolor: 'rgba(236, 72, 153, 0.08)', 
          color: '#f472b6',
          border: '1px solid rgba(236, 72, 153, 0.2)',
          '& .MuiAlert-icon': { color: '#ec4899' } 
        }}
      >
        <Typography variant="subtitle2" sx={{ fontWeight: 'bold', mb: 0.25 }}>
          💳 Subscription Billers & Payment Processors (How Access is Paid For)
        </Typography>
        <Typography variant="caption" sx={{ display: 'block', opacity: 0.9, lineHeight: 1.4 }}>
          Billers represent the payment processing entities listed on bank/credit card statements (e.g. CCBill, Probiller, Epoch, SegPay). Use Billers to map paid site access to statement descriptors and track subscription renewals.
        </Typography>
      </Alert>

      <Grid container spacing={3} sx={{ alignItems: 'stretch' }}>
        {billers.map(biller => {
          return (
            <Grid size={{ xs: 12, sm: 6, md: 6, lg: 4 }} xs={12} sm={6} md={6} lg={4} key={biller.id} sx={{ display: 'flex', minWidth: 0 }}>
              <MediaEntityCard
