                        <Avatar src={`https://www.google.com/s2/favicons?domain=${manager.favicon}&sz=128`} alt={manager.label} sx={{ width: 28, height: 28, borderRadius: '8px', bgcolor: 'transparent' }} />
                        {manager.label}
