            onClick={() => setIsCommandPaletteOpen(true)}
            sx={{
              display: 'flex',
              alignItems: 'center',
              gap: 1.5,
              px: 2,
              py: 0.8,
              borderRadius: 3,
              bgcolor: (theme) => theme.palette.mode === 'dark' ? 'rgba(255, 255, 255, 0.06)' : 'rgba(0, 0, 0, 0.04)',
              border: '1px solid',
              borderColor: (theme) => theme.palette.mode === 'dark' ? 'rgba(255, 255, 255, 0.1)' : 'rgba(0, 0, 0, 0.1)',
              cursor: 'pointer',
              width: { xs: 180, sm: 300 },
              transition: 'all 0.2s ease',
              '&:hover': {
                borderColor: 'primary.main',
                boxShadow: '0 0 12px rgba(59, 130, 246, 0.25)'
              }
            }}
          >
            <Search size={16} style={{ opacity: 0.6 }} />
            <Typography variant="body2" color="text.secondary" sx={{ flexGrow: 1, fontSize: '0.85rem' }}>
              Search tabs & actions...
            </Typography>
            <Chip 
              label="Cmd + K" 
              size="small" 
              sx={{ height: 20, fontSize: '0.65rem', fontWeight: 'bold', bgcolor: 'action.selected' }} 
            />
          </Box>

          {/* Right Action Icons */}
          <Box sx={{ display: 'flex', alignItems: 'center', gap: 1.5 }}>
            {/* Active Downloads Indicator */}
            {activeDownloadsCount > 0 && (
              <Tooltip title={`${activeDownloadsCount} active downloads running`}>
                <IconButton color="primary" onClick={() => onSelectTab('download_queue')}>
                  <Badge badgeContent={activeDownloadsCount} color="secondary">
                    <Zap size={20} />
                  </Badge>
                </IconButton>
              </Tooltip>
            )}

            {/* Notifications */}
            <IconButton onClick={() => onSelectTab('notification_settings')}>
              <Bell size={20} />
            </IconButton>

            {/* User Profile Avatar Menu */}
            <IconButton onClick={(e) => setUserMenuAnchor(e.currentTarget)} sx={{ p: 0.5 }}>
              <Avatar 
                src={user?.avatar_url} 
                alt={user?.username || 'User'}
                sx={{ width: 34, height: 34, bgcolor: 'primary.main', fontWeight: 'bold', fontSize: '0.9rem' }}
              >
                {user?.username ? user.username.charAt(0).toUpperCase() : 'U'}
              </Avatar>
            </IconButton>

            <Menu
              anchorEl={userMenuAnchor}
              open={Boolean(userMenuAnchor)}
              onClose={() => setUserMenuAnchor(null)}
              slotProps={{ paper: { sx: { borderRadius: 2, minWidth: 180, mt: 1 } } }}
            >
              <MenuItem onClick={() => { setUserMenuAnchor(null); onSelectTab('account_security'); }}>
                Account Security
              </MenuItem>
              <MenuItem onClick={() => { setUserMenuAnchor(null); onOpenSettings(); }}>
                Preferences & Theme
              </MenuItem>
              <MenuItem onClick={() => { setUserMenuAnchor(null); onLogout(); }} sx={{ color: 'error.main' }}>
                <LogOut size={16} style={{ marginRight: 8 }} />
                Log Out
              </MenuItem>
            </Menu>
          </Box>
        </Box>

        {/* Dynamic Page Content Viewport */}
        <Box sx={{ flexGrow: 1, p: { xs: 2, sm: 3 } }}>
          {children}
        </Box>
      </Box>

      {/* 3. Global Command Palette Modal */}
      <CommandPaletteModal
        open={isCommandPaletteOpen}
        onClose={() => setIsCommandPaletteOpen(false)}
        onSelectTab={onSelectTab}
        onRunQuickAction={(actionId) => {
          if (actionId === 'action_rescan') onSelectTab('library');
          else if (actionId === 'action_p2p') onSelectTab('p2p_sync');
          else if (actionId === 'action_rip') onSelectTab('mass_rip');
        }}
      />

      {/* 4. Floating Mini-Player */}
      <FloatingMiniPlayer
        mediaUrl={activeMedia?.url}
        mediaTitle={activeMedia?.title}
        onClose={() => setActiveMedia(null)}
      />
    </Box>
  )
}

import { useState, useEffect, useMemo } from 'react'
import { 
  Typography, LinearProgress, List, Box, Button, Chip, 
  TextField, Select, MenuItem, FormControl, InputLabel, Autocomplete, Grid, CircularProgress,
  IconButton, Divider, Tooltip
} from '@mui/material'
import ArrowUpwardIcon from '@mui/icons-material/ArrowUpward'
import ArrowDownwardIcon from '@mui/icons-material/ArrowDownward'
import DownloadIcon from '@mui/icons-material/Download'
import FilterListIcon from '@mui/icons-material/FilterList'
import apiFetch from '../api'
import GlassCard from './common/GlassCard'

const inputSx = { '& .MuiOutlinedInput-root': { borderRadius: '10px' } }
const accentSx = { bgcolor: 'rgba(99,102,241,0.06)', border: '1px solid rgba(99,102,241,0.2)', borderRadius: '12px', p: 2 }

export default function DownloadQueue({ queue, onRefresh }) {
  const [providers, setProviders] = useState([])
  const sortedProviders = useMemo(() => [...providers].sort((a, b) => a.name.localeCompare(b.name)), [providers])
  const [newDownload, setNewDownload] = useState({ provider_id: '', url: '' })
  const [loading, setLoading] = useState(false)

  const [filters, setFilters] = useState({ status: '', url_contains: '', provider_id: '' })

  useEffect(() => {
    apiFetch('/providers')
      .then(res => res.json())
      .then(data => setProviders(data))
      .catch(console.error)
  }, [])

  const handleAddDownload = async (force_duplicate = false) => {
    if (!newDownload.provider_id || !newDownload.url) return
    setLoading(true)
    try {
      const res = await apiFetch('/download/start', {
        method: 'POST',
        body: JSON.stringify({ ...newDownload, force_duplicate })
      })
      const data = await res.json()

      if (data.requires_confirmation) {
        const confirmed = await window.appConfirm(data.message)
        if (confirmed) {
          await handleAddDownload(true)
        }
      } else if (res.ok) {
        window.dispatchEvent(new CustomEvent('show-toast', { detail: { message: data.message, severity: 'success' } }))
        setNewDownload({ provider_id: '', url: '' })
        if (onRefresh) onRefresh()
      } else {
        window.dispatchEvent(new CustomEvent('show-toast', { detail: { message: data.detail || data.message || 'Download failed to start', severity: 'error' } }))
      }
    } catch (error) {
      console.error(error)
      window.dispatchEvent(new CustomEvent('show-toast', { detail: { message: error.message, severity: 'error' } }))
    }
    setLoading(false)
  }

  const handleAction = async (taskId, action) => {
    try {
      const response = await apiFetch(`/progress/${taskId}/${action}`, { 
        method: 'POST'
      })
      if (response.ok) {
        if (onRefresh) onRefresh()
      }
    } catch (error) {
      console.error(`Error performing ${action} on download:`, error)
    }
  }

  const filteredQueue = (queue || []).filter(task => {
    if (filters.status && task.status !== filters.status) return false
    if (filters.url_contains && !task.url.toLowerCase().includes(filters.url_contains.toLowerCase())) return false
    if (filters.provider_id && task.media_entry?.provider_id !== filters.provider_id) return false
    return true
  })

  return (
    <Box sx={{ maxWidth: 1400, mx: 'auto', width: '100%' }}>
      <Typography variant="h4" sx={{ fontWeight: '800', letterSpacing: '-0.5px', mb: 3 }}>
        Download Queue
      </Typography>

      {/* Add Single Download Card */}
      <GlassCard sx={{ mb: 3 }}>
        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1.5, mb: 2.5 }}>
          <Box sx={{ p: 1, borderRadius: '10px', background: 'linear-gradient(135deg, #6366f1 0%, #a855f7 100%)', color: '#fff', display: 'flex' }}>
            <DownloadIcon fontSize="small" />
          </Box>
          <Typography variant="h6" sx={{ fontWeight: '700' }}>Add Single Download</Typography>
        </Box>
        <Box sx={{ display: 'flex', gap: 2, alignItems: 'center', flexWrap: 'wrap', ...accentSx }}>
          <Box sx={{ flexShrink: 0, minWidth: 240 }}>
            <Autocomplete
              options={sortedProviders}
              getOptionLabel={(p) => p.name}
              value={sortedProviders.find(p => p.id === newDownload.provider_id) || null}
              onChange={(e, v) => setNewDownload({...newDownload, provider_id: v?.id || ''})}
              renderInput={(params) => <TextField {...params} label="Select Media Provider" size="small" />}
              isOptionEqualToValue={(o, v) => o.id === v.id}
              sx={{ '& .MuiOutlinedInput-root': { borderRadius: '10px' } }}
            />
          </Box>
          <Box sx={{ flexGrow: 1, minWidth: 280 }}>
            <TextField fullWidth size="small" label="Media URL" placeholder="https://..." value={newDownload.url} onChange={e => setNewDownload({...newDownload, url: e.target.value})} sx={inputSx} />
          </Box>
          <Box sx={{ flexShrink: 0 }}>
            <Button variant="contained" color="primary" onClick={() => handleAddDownload(false)} disabled={loading || !newDownload.provider_id || !newDownload.url} sx={{ height: 40, px: 3, borderRadius: '10px', textTransform: 'none', fontWeight: 'bold', boxShadow: '0 4px 14px rgba(99,102,241,0.35)' }}>
              {loading ? <CircularProgress size={22} color="inherit" /> : 'Queue Download'}
            </Button>
          </Box>
        </Box>
      </GlassCard>

      {/* Filter & Search Toolbar */}
      <GlassCard sx={{ mb: 3 }}>
        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 2 }}>
          <FilterListIcon sx={{ color: 'rgba(255,255,255,0.5)', fontSize: 20 }} />
          <Typography variant="subtitle2" sx={{ fontWeight: '700', color: 'rgba(255,255,255,0.7)' }}>Filter & Search</Typography>
        </Box>
        <Box sx={{ display: 'flex', gap: 2, alignItems: 'center', flexWrap: 'wrap', ...accentSx }}>
          <Box sx={{ flexShrink: 0, minWidth: 220 }}>
            <FormControl fullWidth size="small">
              <InputLabel id="filter-status-label">Filter Status</InputLabel>
              <Select labelId="filter-status-label" value={filters.status} label="Filter Status" onChange={e => setFilters({...filters, status: e.target.value})} sx={{ borderRadius: '10px' }}>
                <MenuItem value="">All Statuses</MenuItem>
                <MenuItem value="running">Running</MenuItem>
                <MenuItem value="queued">Queued</MenuItem>
                <MenuItem value="completed">Completed</MenuItem>
                <MenuItem value="failed">Failed</MenuItem>
              </Select>
            </FormControl>
          </Box>
          <Box sx={{ flexGrow: 1, minWidth: 240 }}>
            <TextField fullWidth size="small" label="Search Download URL" value={filters.url_contains} onChange={e => setFilters({...filters, url_contains: e.target.value})} sx={inputSx} />
          </Box>
        </Box>
      </GlassCard>

      {filteredQueue.length > 0 ? (
        <List sx={{ p: 0 }}>
          {filteredQueue.map((task) => (
            <GlassCard key={task.id} sx={{ mb: 2 }}>
              {/* Header row: title + status chip */}
              <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', width: '100%', mb: 1.5, gap: 1 }}>
                <Typography variant="subtitle1" noWrap sx={{ maxWidth: '75%', fontWeight: '700' }} title={task.url}>
                  Task #{task.id}: {task.url}
                </Typography>
                <Chip 
                  label={(task.status || 'unknown').toUpperCase()} 
                  color={task.status === 'completed' ? 'success' : task.status === 'failed' ? 'error' : task.status === 'queued' ? 'warning' : 'primary'} 
                  size="small"
                  sx={{ fontWeight: 'bold', fontSize: '0.65rem' }}
                />
              </Box>

              {/* Progress bar */}
              <Box sx={{ width: '100%', mb: 1.5 }}>
                <Tooltip
                  title={
                    task.speed
                      ? `${task.speed} · ${task.progress_percentage?.toFixed(1) || 0}%`
                      : `${(task.progress_percentage || 0).toFixed(1)}% complete`
                  }
                  placement="bottom"
                >
                  <LinearProgress variant="determinate" value={task.progress_percentage || 0} sx={{ height: 8, borderRadius: 4, bgcolor: 'rgba(255,255,255,0.08)' }} />
                </Tooltip>
                <Typography variant="caption" color="text.secondary" sx={{ mt: 0.5, display: 'block', fontWeight: 'bold' }}>
                  {(task.progress_percentage || 0).toFixed(1)}% complete
                  {task.speed ? ` — ${task.speed}` : ''}
                </Typography>
              </Box>

              <Divider sx={{ borderColor: 'rgba(255,255,255,0.08)', mb: 1.5 }} />

              {/* Action buttons + priority */}
              <Box sx={{ display: 'flex', gap: 1, alignItems: 'center', width: '100%' }}>
                <Box sx={{ display: 'flex', gap: 1 }}>
                  {(task.status === 'running' || task.status === 'pending' || task.status === 'queued') && (
                    <Button size="small" variant="outlined" color="warning" onClick={() => handleAction(task.id, 'pause')} sx={{ borderRadius: '8px', textTransform: 'none', fontSize: '0.75rem' }}>
                      Pause
                    </Button>
                  )}
                  {task.status === 'paused' && (
                    <Button size="small" variant="outlined" color="success" onClick={() => handleAction(task.id, 'resume')} sx={{ borderRadius: '8px', textTransform: 'none', fontSize: '0.75rem' }}>
                      Resume
                    </Button>
                  )}
                  {task.status !== 'completed' && task.status !== 'failed' && task.status !== 'cancelled' && (
                    <Button size="small" variant="outlined" color="error" onClick={() => handleAction(task.id, 'cancel')} sx={{ borderRadius: '8px', textTransform: 'none', fontSize: '0.75rem' }}>
                      Cancel
                    </Button>
                  )}
                </Box>

                {task.status !== 'completed' && task.status !== 'failed' && task.status !== 'cancelled' && (
                  <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5, ml: 'auto' }}>
                    <Typography variant="caption" color="text.secondary" sx={{ fontWeight: 'bold' }}>
                      Priority: {task.priority || 0}
                    </Typography>
                    <IconButton size="small" onClick={() => handleAction(task.id, 'priority/up')} color="primary">
                      <ArrowUpwardIcon fontSize="small" />
                    </IconButton>
                    <IconButton size="small" onClick={() => handleAction(task.id, 'priority/down')} color="primary">
                      <ArrowDownwardIcon fontSize="small" />
                    </IconButton>
                  </Box>
                )}
              </Box>
            </GlassCard>
          ))}
        </List>
      ) : (
        <GlassCard sx={{ textAlign: 'center', py: 6 }}>
          <Typography variant="h6" sx={{ color: 'rgba(255,255,255,0.3)', fontWeight: 700, mb: 1 }}>No Downloads</Typography>
          <Typography variant="body2" color="text.secondary">No downloads currently match your criteria.</Typography>
        </GlassCard>
      )}
    </Box>
  )
}

import { useState, useEffect, useCallback } from 'react'
import {
  Box, Typography, Card, CardContent, Button, TextField, Select, MenuItem,
  FormControl, InputLabel, Chip, IconButton,
  Dialog, DialogTitle, DialogContent, DialogActions, Grid,
  Table, TableBody, TableCell, TableContainer, TableHead, TableRow, TablePagination, Paper
} from '@mui/material'
import DeleteIcon from '@mui/icons-material/Delete'
import AddIcon from '@mui/icons-material/Add'
import EditIcon from '@mui/icons-material/Edit'
import { apiFetch } from '../api'

export default function DownloadRules() {
  const [lists, setLists] = useState([])
  const [rules, setRules] = useState([])

  // Custom List State
  const [openListDialog, setOpenListDialog] = useState(false)
  const [currentList, setCurrentList] = useState({ name: '', item_type: 'performers', items: [] })
  const [newItem, setNewItem] = useState('')
  const [listsPage, setListsPage] = useState(0)
  const [listsLimit, setListsLimit] = useState(5)

  // Rule State
  const [openRuleDialog, setOpenRuleDialog] = useState(false)
  const [currentRule, setCurrentRule] = useState({ name: '', scope: 'global', action: 'download', criteria: {} })
  const [criteriaKey, setCriteriaKey] = useState('resolution')
  const [criteriaValue, setCriteriaValue] = useState('')
  const [criteriaListId, setCriteriaListId] = useState('')
  const [rulesPage, setRulesPage] = useState(0)
  const [rulesLimit, setRulesLimit] = useState(5)

  const fetchLists = useCallback(async () => {
    try {
      const res = await apiFetch('/rules/lists')
      if (res.ok) setLists(await res.json())
    } catch (e) {
      console.error('Failed to fetch lists:', e)
    }
  }, [])

  const fetchRules = useCallback(async () => {
    try {
      const res = await apiFetch('/rules')
      if (res.ok) setRules(await res.json())
    } catch (e) {
      console.error('Failed to fetch rules:', e)
    }
  }, [])

  useEffect(() => {
    fetchLists()
    fetchRules()
  }, [fetchLists, fetchRules])

  // --- Custom List Handlers ---
  const handleSaveList = async () => {
    try {
      const isEdit = currentList.id !== undefined
      const url = isEdit ? `/rules/lists/${currentList.id}` : '/rules/lists'
      const method = isEdit ? 'PUT' : 'POST'

      const res = await apiFetch(url, {
        method,
        body: JSON.stringify({
          name: currentList.name,
          item_type: currentList.item_type,
          items: currentList.items
        })
      })

      if (res.ok) {
        setOpenListDialog(false)
        fetchLists()
      } else {
        const err = await res.json().catch(() => ({}))
        console.error('Failed to save list:', err.detail || res.statusText)
      }
    } catch (e) {
      console.error('Failed to save list:', e)
    }
  }

  const handleDeleteList = async (id) => {
    try {
      const res = await apiFetch(`/rules/lists/${id}`, { 
        method: 'DELETE'
      })
      if (res.ok) {
        fetchLists()
        // Reset page if needed
        const newLength = lists.length - 1
        if (listsPage * listsLimit >= newLength && listsPage > 0) {
          setListsPage(listsPage - 1)
        }
      }
    } catch (e) {
      console.error('Failed to delete list:', e)
    }
  }

  const handleEditList = (list) => {
    setCurrentList({ ...list })
    setNewItem('')
    setOpenListDialog(true)
  }

  const handleAddListItem = () => {
    if (newItem && !currentList.items.includes(newItem)) {
      setCurrentList({ ...currentList, items: [...currentList.items, newItem] })
      setNewItem('')
    }
  }

  const handleRemoveListItem = (itemToRemove) => {
    setCurrentList({
      ...currentList,
      items: currentList.items.filter(item => item !== itemToRemove)
    })
  }

  // --- Rule Handlers ---
  const handleSaveRule = async () => {
    try {
      const isEdit = currentRule.id !== undefined
      const url = isEdit ? `/rules/${currentRule.id}` : '/rules'
      const method = isEdit ? 'PUT' : 'POST'

      const res = await apiFetch(url, {
        method,
        body: JSON.stringify({
          name: currentRule.name,
          scope: currentRule.scope,
          action: currentRule.action,
          criteria: currentRule.criteria,
          is_active: currentRule.is_active !== undefined ? currentRule.is_active : true
        })
      })

      if (res.ok) {
        setOpenRuleDialog(false)
        fetchRules()
      } else {
        const err = await res.json().catch(() => ({}))
        console.error('Failed to save rule:', err.detail || res.statusText)
      }
    } catch (e) {
      console.error('Failed to save rule:', e)
    }
  }

  const handleDeleteRule = async (id) => {
    try {
      const res = await apiFetch(`/rules/${id}`, { 
        method: 'DELETE'
      })
      if (res.ok) {
        fetchRules()
        // Reset page if needed
        const newLength = rules.length - 1
        if (rulesPage * rulesLimit >= newLength && rulesPage > 0) {
          setRulesPage(rulesPage - 1)
        }
      }
    } catch (e) {
      console.error('Failed to delete rule:', e)
    }
  }

  const handleEditRule = (rule) => {
    setCurrentRule({ ...rule })
    setCriteriaValue('')
    setCriteriaListId('')
    setOpenRuleDialog(true)
  }

  const handleAddCriteria = () => {
    let value = criteriaValue
    if (criteriaKey === 'in_list') {
      if (!criteriaListId) {
        window.dispatchEvent(new CustomEvent('show-toast', { detail: { message: 'No list selected', severity: 'warning' } }))
        return
      }
      value = parseInt(criteriaListId)
    } else if (['performers', 'categories', 'series'].includes(criteriaKey)) {
      value = { contains: criteriaValue }
    } else if (criteriaKey === 'custom_terms') {
      value = criteriaValue.split(',').map(s => s.trim()).filter(Boolean)
    }

    setCurrentRule({
      ...currentRule,
      criteria: { ...currentRule.criteria, [criteriaKey]: value }
    })
    setCriteriaValue('')
  }

  // Sliced lists and rules for pagination
  const paginatedLists = lists.slice(listsPage * listsLimit, (listsPage + 1) * listsLimit)
  const paginatedRules = rules.slice(rulesPage * rulesLimit, (rulesPage + 1) * rulesLimit)

  return (
    <Box sx={{ maxWidth: 1400, mx: 'auto', width: '100%' }}>
      <Typography variant="h4" gutterBottom align="center" sx={{ fontWeight: 700, mb: 4 }}>
        Download Rules & Lists
      </Typography>

      <Box sx={{ display: 'flex', flexDirection: 'column', gap: 4, width: '100%', mb: 4 }}>
        {/* Custom Lists Section */}
        <Card sx={{ width: '100%', borderRadius: '12px', border: '1px solid rgba(255,255,255,0.08)' }}>
          <CardContent>
            <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 3 }}>
              <Typography variant="h6" sx={{ fontWeight: 600 }}>Custom Lists</Typography>
              <Button variant="contained" startIcon={<AddIcon />} onClick={() => {
                setCurrentList({ name: '', item_type: 'performers', items: [] })
                setOpenListDialog(true)
              }}>Add List</Button>
            </Box>

            <TableContainer component={Paper} elevation={0} sx={{ border: '1px solid rgba(255,255,255,0.06)', borderRadius: '8px' }}>
              <Table size="small">
                <TableHead>
                  <TableRow>
                    <TableCell sx={{ fontWeight: 600 }}>Name</TableCell>
                    <TableCell sx={{ fontWeight: 600 }}>Type</TableCell>
                    <TableCell sx={{ fontWeight: 600 }}>Items Count</TableCell>
                    <TableCell sx={{ fontWeight: 600, textAlign: 'right' }}>Actions</TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {paginatedLists.length === 0 ? (
                    <TableRow>
                      <TableCell colSpan={4} align="center" sx={{ py: 3, color: 'text.secondary' }}>
                        No custom lists configured.
                      </TableCell>
                    </TableRow>
                  ) : (
                    paginatedLists.map(list => (
                      <TableRow key={list.id} sx={{ '&:last-child td, &:last-child th': { border: 0 } }}>
                        <TableCell sx={{ fontWeight: 500 }}>{list.name}</TableCell>
                        <TableCell>
                          <Chip size="small" label={list.item_type} variant="outlined" />
                        </TableCell>
                        <TableCell>{list.items.length} items</TableCell>
                        <TableCell align="right">
                          <IconButton size="small" color="primary" onClick={() => handleEditList(list)} sx={{ mr: 0.5 }}>
                            <EditIcon fontSize="small" />
                          </IconButton>
                          <IconButton size="small" color="error" onClick={() => handleDeleteList(list.id)}>
                            <DeleteIcon fontSize="small" />
                          </IconButton>
                        </TableCell>
                      </TableRow>
                    ))
                  )}
                </TableBody>
              </Table>
            </TableContainer>

            <TablePagination
              rowsPerPageOptions={[5, 10, 25]}
              component="div"
              count={lists.length}
              rowsPerPage={listsLimit}
              page={listsPage}
              onPageChange={(e, newPage) => setListsPage(newPage)}
              onRowsPerPageChange={(e) => {
                setListsLimit(parseInt(e.target.value, 10))
                setListsPage(0)
              }}
            />
          </CardContent>
        </Card>

        {/* Download Rules Section */}
