import { useState, useEffect, useRef, useCallback } from 'react'
import { 
  Box, Typography, Paper, Button, CircularProgress, Select, MenuItem, 
  TextField, FormControl, InputLabel, Stack, Tabs, Tab, Chip, Card, CardContent, Divider, Alert 
} from '@mui/material'
import TerminalIcon from '@mui/icons-material/Terminal'
import TrashIcon from '@mui/icons-material/DeleteForever'
import RefreshIcon from '@mui/icons-material/Refresh'
import apiFetch, { API_BASE, getAuthHeaders } from '../api'

export default function LogsViewer() {
  const [activeTab, setActiveTab] = useState(0) // 0: Raw Console Logs, 1: Categorized System Errors
  const [logs, setLogs] = useState([])
  const [loading, setLoading] = useState(false)
  const [logSource, setLogSource] = useState('celery')
  const [logLevel, setLogLevel] = useState('ALL')
  const [searchQuery, setSearchQuery] = useState('')

  // Categorized Error Logs state
  const [errorLogs, setErrorLogs] = useState([])
  const [errorCategory, setErrorCategory] = useState('ALL')
  const [errorLoading, setErrorLoading] = useState(false)

  const bottomRef = useRef(null)
  const wsRef = useRef(null)

  const fetchErrorLogs = useCallback(async () => {
    setErrorLoading(true)
    try {
      const url = errorCategory !== 'ALL' ? `/logs/errors?category=${errorCategory}` : '/logs/errors'
      const res = await apiFetch(url)
      if (res.ok) {
        setErrorLogs(await res.json())
      }
    } catch (e) {
      console.error(e)
    } finally {
      setErrorLoading(false)
    }
  }, [errorCategory])

  useEffect(() => {
    if (activeTab === 1) {
      fetchErrorLogs()
    }
  }, [activeTab, fetchErrorLogs])

  useEffect(() => {
    if (activeTab !== 0) return
    setLogs([])

    const headers = getAuthHeaders()
    let authQuery = ''
    if (headers['Authorization']) {
      authQuery = `token=${encodeURIComponent(headers['Authorization'].replace('Bearer ', ''))}`
    } else if (headers['X-Voyarr-Api-Key']) {
      authQuery = `api_key=${encodeURIComponent(headers['X-Voyarr-Api-Key'])}`
    }

    const protocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
    const wsUrl = API_BASE.startsWith('http') 
      ? API_BASE.replace(/^https?/, protocol.replace(':', '')) + `/logs/ws?source=${logSource}&${authQuery}`
      : `${protocol}//${window.location.host}${API_BASE}/logs/ws?source=${logSource}&${authQuery}`;

    const ws = new WebSocket(wsUrl)
    wsRef.current = ws

    ws.onmessage = (event) => {
      setLogs((prevLogs) => {
        const newLogs = [...prevLogs, event.data]
        return newLogs.slice(-1000)
      })
    }

    ws.onerror = (error) => {
      console.error('WebSocket error:', error)
    }

    return () => {
      ws.close()
    }
  }, [logSource, activeTab])

  useEffect(() => {
    if (activeTab === 0) {
      bottomRef.current?.scrollIntoView()
    }
  }, [logs, logLevel, searchQuery, activeTab])

  const clearLogs = async () => {
    setLoading(true)
    try {
      await apiFetch(`/logs?source=${logSource}`, { method: 'DELETE' })
      setLogs([])
    } catch (e) {
      console.error(e)
    }
    setLoading(false)
  }

  const handleClearErrorsImmediately = async () => {
    setErrorLoading(true)
    try {
      const res = await apiFetch('/logs/errors', { method: 'DELETE' })
      if (res.ok) {
        setErrorLogs([])
        window.dispatchEvent(new CustomEvent('show-toast', { detail: { message: 'All system error logs cleared immediately!', severity: 'success' } }))
      }
    } catch (e) {
      console.error(e)
    } finally {
      setErrorLoading(false)
    }
  }

  const filteredLogs = logs.filter(log => {
    if (logLevel !== 'ALL' && !log.includes(logLevel)) return false
    if (searchQuery && !log.toLowerCase().includes(searchQuery.toLowerCase())) return false
    return true
  })

  const filteredErrorLogs = errorLogs.filter(err => {
    if (searchQuery && !err.message.toLowerCase().includes(searchQuery.toLowerCase()) && !err.user_friendly_explanation.toLowerCase().includes(searchQuery.toLowerCase())) {
      return false
    }
    return true
  })

  const getCategoryBadge = (category) => {
    if (category === 'local_dev') {
      return <Chip label="Local Dev Limitation" color="info" size="small" sx={{ fontWeight: 'bold' }} />
    }
    if (category === 'external_service') {
      return <Chip label="Unconnected External Layer" color="warning" size="small" sx={{ fontWeight: 'bold' }} />
    }
    return <Chip label="Fixable Application Bug" color="error" size="small" sx={{ fontWeight: 'bold' }} />
  }

  return (
    <Box sx={{ maxWidth: 1400, mx: 'auto', width: '100%' }}>
      <Box sx={{ borderBottom: 1, borderColor: 'divider', mb: 2.5 }}>
        <Tabs value={activeTab} onChange={(e, val) => setActiveTab(val)}>
          <Tab label="Live Console Logs" sx={{ fontWeight: 'bold' }} />
          <Tab label="System Error Diagnostics" sx={{ fontWeight: 'bold' }} />
        </Tabs>
      </Box>

      {/* Purpose Banner */}
      <Alert 
        severity="info" 
        icon={<TerminalIcon fontSize="small" color="primary" />} 
        sx={{ 
          mb: 3, 
          borderRadius: '12px', 
          bgcolor: 'rgba(99, 102, 241, 0.08)', 
          color: '#a5b4fc',
          border: '1px solid rgba(99, 102, 241, 0.2)',
          '& .MuiAlert-icon': { color: '#818cf8' } 
        }}
      >
        <Typography variant="subtitle2" sx={{ fontWeight: 'bold', mb: 0.25 }}>
          📋 Real-Time System Logs &amp; Error Diagnostics Console
        </Typography>
        <Typography variant="caption" sx={{ display: 'block', opacity: 0.9, lineHeight: 1.4 }}>
          System Logs streams live stdout/stderr console output from FastAPI, Celery scrapers, and Redis workers. The Diagnostics tab isolates fixable bugs, unconnected external layers, and local dev limitations with retention pruning.
        </Typography>
      </Alert>

      {activeTab === 0 ? (
        <>
          <Box sx={{ display: 'flex', flexDirection: { xs: 'column', md: 'row' }, justifyContent: 'space-between', alignItems: { xs: 'stretch', md: 'center' }, gap: 2, mb: 2 }}>
            <Typography variant="h5" sx={{ fontWeight: '800', letterSpacing: '-0.5px' }}>Console Stream</Typography>
            <Stack direction={{ xs: 'column', sm: 'row' }} spacing={2} alignItems="stretch" sx={{ width: { xs: '100%', md: 'auto' } }}>
              <FormControl size="small" sx={{ minWidth: 160 }}>
                <InputLabel id="log-source-label">Log Source Engine</InputLabel>
                <Select labelId="log-source-label" value={logSource} label="Log Source Engine" onChange={(e) => setLogSource(e.target.value)} sx={{ borderRadius: '10px' }}>
                  <MenuItem value="celery">Celery Workers</MenuItem>
                  <MenuItem value="fastapi">FastAPI Backend</MenuItem>
                </Select>
              </FormControl>

              <FormControl size="small" sx={{ minWidth: 160 }}>
                <InputLabel id="log-level-label">Filter Log Level</InputLabel>
                <Select labelId="log-level-label" value={logLevel} label="Filter Log Level" onChange={(e) => setLogLevel(e.target.value)} sx={{ borderRadius: '10px' }}>
                  <MenuItem value="ALL">All Levels</MenuItem>
                  <MenuItem value="INFO">INFO</MenuItem>
                  <MenuItem value="WARNING">WARNING</MenuItem>
                  <MenuItem value="ERROR">ERROR</MenuItem>
                  <MenuItem value="DEBUG">DEBUG</MenuItem>
                </Select>
              </FormControl>

              <TextField
                size="small"
                label="Search Log Feed"
                placeholder="Type keyword..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                sx={{ flex: 2, minWidth: 220, '& .MuiOutlinedInput-root': { borderRadius: '10px' } }}
              />

              <Button
                variant="outlined"
                color="error"
                startIcon={<TrashIcon />}
                onClick={clearLogs}
                disabled={loading}
                sx={{ borderRadius: '10px', textTransform: 'none', height: 40 }}
              >
                Clear Feed
              </Button>
            </Stack>
          </Box>
          <Paper sx={{ p: 2.5, backgroundColor: 'rgba(10, 15, 30, 0.95)', border: '1px solid rgba(255, 255, 255, 0.08)', borderRadius: '16px', color: '#38bdf8', fontFamily: 'Fira Code, monospace', fontSize: '0.85rem', height: '65vh', overflowY: 'auto', boxShadow: '0 8px 32px rgba(0,0,0,0.5)' }}>
            {filteredLogs.length === 0 ? (
              <Typography>No console logs matching criteria.</Typography>
            ) : (
              filteredLogs.map((log, index) => (
                <div key={index} style={{ whiteSpace: 'pre-wrap' }}>{log}</div>
              ))
            )}
            <div ref={bottomRef} />
          </Paper>
        </>
      ) : (
        <>
          <Box sx={{ display: 'flex', flexDirection: { xs: 'column', md: 'row' }, justifyContent: 'space-between', alignItems: { xs: 'stretch', md: 'center' }, gap: 2, mb: 2 }}>
            <Typography variant="h5">Categorized System Errors</Typography>
            <Stack direction={{ xs: 'column', sm: 'row' }} spacing={2} alignItems="stretch" sx={{ width: { xs: '100%', md: 'auto' } }}>
              <FormControl size="small" sx={{ flex: 1 }}>
                <InputLabel>Category</InputLabel>
                <Select value={errorCategory} label="Category" onChange={(e) => setErrorCategory(e.target.value)} sx={{ minWidth: 160 }}>
                  <MenuItem value="ALL">All Error Categories</MenuItem>
                  <MenuItem value="local_dev">Local Dev Limitation</MenuItem>
                  <MenuItem value="external_service">Unconnected External Layer</MenuItem>
                  <MenuItem value="app_bug">Fixable Application Bug</MenuItem>
                </Select>
              </FormControl>

              <TextField
                size="small"
                label="Search Error Messages"
                variant="outlined"
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                sx={{ flex: 2 }}
              />

              <Button variant="outlined" startIcon={<RefreshIcon />} onClick={fetchErrorLogs} disabled={errorLoading}>
                Refresh
              </Button>

              <Button 
                variant="contained" 
                color="error" 
                startIcon={<TrashIcon />} 
                onClick={handleClearErrorsImmediately} 
                disabled={errorLoading || errorLogs.length === 0}
                sx={{ height: '40px', flex: 1, fontWeight: 'bold' }}
              >
                Clear Errors Now
              </Button>
            </Stack>
          </Box>

          <Paper sx={{ p: 2, height: '65vh', overflowY: 'auto', bgcolor: 'rgba(15, 23, 42, 0.5)', backdropFilter: 'blur(10px)', border: '1px solid rgba(255, 255, 255, 0.08)' }}>
            {errorLoading ? (
              <Box sx={{ display: 'flex', justifyContent: 'center', p: 4 }}><CircularProgress /></Box>
            ) : filteredErrorLogs.length === 0 ? (
              <Box sx={{ p: 4, textAlign: 'center' }}>
                <Typography color="text.secondary">No error entries logged matching current filter.</Typography>
              </Box>
            ) : (
              <Stack spacing={2}>
                {filteredErrorLogs.map((err) => (
                  <Card key={err.id} variant="outlined" sx={{ bgcolor: 'rgba(30, 41, 59, 0.7)', border: '1px solid rgba(255,255,255,0.1)' }}>
                    <CardContent sx={{ pb: '16px !important' }}>
                      <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 1, flexWrap: 'wrap', gap: 1 }}>
                        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                          {getCategoryBadge(err.category)}
                          <Chip label={err.source || 'frontend'} variant="outlined" size="small" sx={{ fontSize: '0.7rem' }} />
                        </Box>
                        <Typography variant="caption" color="text.secondary">
                          {new Date(err.timestamp).toLocaleString()}
                        </Typography>
                      </Box>
                      <Typography variant="subtitle1" sx={{ fontWeight: 'bold', color: '#f87171', mb: 0.5 }}>
                        {err.message}
                      </Typography>
                      <Typography variant="body2" sx={{ color: '#818cf8', fontWeight: '500', mb: 1 }}>
                        💡 {err.user_friendly_explanation}
                      </Typography>
                      {err.path && (
                        <Typography variant="caption" color="text.secondary" display="block">
                          Location: <code>{err.path}</code>
                        </Typography>
                      )}
                      {err.stack_trace && (
                        <Box sx={{ mt: 1, p: 1, bgcolor: '#0b0f19', borderRadius: 1, maxHeight: 100, overflowY: 'auto' }}>
                          <Typography variant="caption" sx={{ fontFamily: 'monospace', color: 'rgba(255,255,255,0.6)', whiteSpace: 'pre-wrap' }}>
                            {err.stack_trace}
                          </Typography>
                        </Box>
                      )}
                    </CardContent>
                  </Card>
                ))}
              </Stack>
            )}
          </Paper>
        </>
      )}
    </Box>
  )
}

import { useState, useEffect, useMemo, useRef } from 'react'
import { 
  Box, Typography, TextField, Button, Paper, Grid, 
  Autocomplete, Alert, CircularProgress,
  Table, TableBody, TableCell, TableContainer, TableHead, TableRow,
  IconButton, Tooltip, LinearProgress, Chip
} from '@mui/material'
import { Play, Pause, Square, Trash2, RefreshCw, ExternalLink, Zap } from 'lucide-react'
import { apiFetch, getAuthHeaders } from '../api'

const MASS_RIP_API_BASE = import.meta.env.VITE_API_BASE || '/api'

export default function MassRip() {
  const [providers, setProviders] = useState([])
  const sortedProviders = useMemo(() => [...providers].sort((a, b) => a.name.localeCompare(b.name)), [providers])
  const [providerId, setProviderId] = useState('')
  const [url, setUrl] = useState('')
  const [loading, setLoading] = useState(false)
  const [result, setResult] = useState(null)
  const [rippingEnabled, setRippingEnabled] = useState(true)
  const [sessions, setSessions] = useState([])
  const [statusFilter, setStatusFilter] = useState('')
  const eventSourceRef = useRef(null)

  const getAuthQuery = () => {
    const token = localStorage.getItem('voyarr_jwt')
    if (token) return `token=${encodeURIComponent(token)}`
    let apiKey = localStorage.getItem('voyarr_api_key')
    if (apiKey) {
      try { apiKey = atob(apiKey) } catch {}
    }
    return `api_key=${encodeURIComponent(apiKey || '')}`
  }

  const fetchSessions = async () => {
    try {
      const res = await apiFetch('/download/mass_rip/sessions')
      if (res.ok) {
        const data = await res.json()
        setSessions(data)
      }
    } catch (e) {
      console.error('Failed to fetch mass rip sessions:', e)
    }
  }

  useEffect(() => {
    apiFetch('/providers')
      .then(res => res.json())
      .then(data => setProviders(data))
      .catch(console.error)

    apiFetch('/settings')
      .then(res => res.json())
      .then(data => {
        if (data && data.ripping_enabled === 'false') {
          setRippingEnabled(false)
        }
      })
      .catch(console.error)

    fetchSessions()

    // Connect to SSE stream for real-time updates
    const es = new EventSource(`${MASS_RIP_API_BASE}/download/mass_rip/sessions/stream?${getAuthQuery()}`)
    eventSourceRef.current = es

    es.onmessage = (event) => {
      try {
        const data = JSON.parse(event.data)
        if (Array.isArray(data)) {
          setSessions(data)
        }
      } catch {}
    }

    es.onerror = () => {}

    return () => {
      es.close()
    }
  }, [])

  const handleMassRip = async () => {
    if (!providerId || !url) return
    setLoading(true)
    setResult(null)

    try {
      const res = await apiFetch('/download/mass_rip', {
        method: 'POST',
        body: JSON.stringify({ provider_id: providerId, url: url })
      })
      const data = await res.json()

      if (res.ok) {
        setResult({ type: 'success', message: data.message })
        setUrl('')
        fetchSessions()
      } else {
        setResult({ type: 'error', message: data.detail || 'Failed to start mass rip' })
      }
    } catch (e) {
      setResult({ type: 'error', message: e.message })
    }
    setLoading(false)
  }

  const handleSessionAction = async (sessionId, action) => {
    try {
      let endpoint = `/download/mass_rip/sessions/${sessionId}/${action}`
      let method = 'POST'
      if (action === 'delete') {
        endpoint = `/download/mass_rip/sessions/${sessionId}`
        method = 'DELETE'
      }

      const res = await apiFetch(endpoint, { method })
      if (res.ok) {
        fetchSessions()
      } else {
        const data = await res.json().catch(() => ({}))
        console.error(`Failed to ${action} session:`, data.detail || res.statusText)
      }
    } catch (e) {
      console.error(e)
    }
  }

  const getProviderName = (id) => {
    const p = providers.find(prov => prov.id === id)
    return p ? p.name : `Provider #${id}`
  }

  const getStatusChip = (status) => {
    let color = 'default'
    switch (status) {
      case 'completed':
        color = 'success'
        break
      case 'running':
        color = 'primary'
        break
      case 'pending':
        color = 'info'
        break
      case 'paused':
        color = 'warning'
        break
      case 'failed':
      case 'stopped':
        color = 'error'
        break
    }
    return <Chip label={status.toUpperCase()} color={color} size="small" variant="light" sx={{ fontWeight: 600, fontSize: '10px' }} />
  }

  const formatDateTime = (dtStr) => {
    if (!dtStr) return '-'
    const date = new Date(dtStr)
    return date.toLocaleString()
  }

  const filteredSessions = statusFilter ? sessions.filter(s => s.status === statusFilter) : sessions

  return (
    <Box sx={{ maxWidth: 1400, mx: 'auto', width: '100%' }}>
      <Typography variant="h4" gutterBottom sx={{ fontWeight: 700 }}>Mass Rip Workflow</Typography>

      {/* Purpose Banner */}
      <Alert 
        severity="info" 
        icon={<Zap size={20} />} 
        sx={{ 
          mb: 3, 
          borderRadius: '12px', 
          bgcolor: 'rgba(236, 72, 153, 0.08)', 
          color: '#f472b6',
          border: '1px solid rgba(236, 72, 153, 0.2)',
          '& .MuiAlert-icon': { color: '#ec4899' } 
        }}
      >
        <Typography variant="subtitle2" sx={{ fontWeight: 'bold', mb: 0.25 }}>
          ⚡ Automated Mass Rip Scraper Engine
        </Typography>
        <Typography variant="caption" sx={{ display: 'block', opacity: 0.9, lineHeight: 1.4 }}>
          Mass Rip automates bulk URL extractions from channels, profiles, or playlists. Provide a target URL to let Voyarr scrape all media links, evaluate them against your active Download Rules, and queue matches automatically.
        </Typography>
      </Alert>

      <Paper sx={{ p: 3, mb: 3, borderRadius: '16px', background: 'rgba(15, 23, 42, 0.4)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255, 255, 255, 0.08)', boxShadow: '0 8px 32px rgba(0,0,0,0.25)' }}>
        {!rippingEnabled && (
          <Alert severity="warning" sx={{ mb: 3, borderRadius: '10px' }}>
            ⚠️ Access Denied: The Ripping feature is disabled globally by the administrator. Please enable it in Settings to use this workflow.
          </Alert>
        )}
        <Typography variant="body2" color="text.secondary" sx={{ mb: 3, lineHeight: 1.6 }}>
          Provide a channel or playlist URL. Voyarr will scrape all contained video URLs and process them sequentially through your active global and provider-specific Download Rules, queueing matched videos automatically.
        </Typography>

        <Grid container spacing={2} sx={{ alignItems: 'center' }}>
          <Grid item xs={12} md="auto" sx={{ minWidth: 280 }}>
            <Autocomplete
              options={sortedProviders}
              getOptionLabel={(p) => p.name}
              value={sortedProviders.find(p => p.id === providerId) || null}
              onChange={(e, v) => setProviderId(v?.id || '')}
              renderInput={(params) => <TextField {...params} label="Provider Ruleset" size="small" />}
              isOptionEqualToValue={(o, v) => o.id === v.id}
              disabled={!rippingEnabled}
              sx={{ '& .MuiOutlinedInput-root': { borderRadius: '10px' } }}
            />
          </Grid>
          <Grid item xs={12} md={true} sx={{ minWidth: 320 }}>
            <TextField 
              fullWidth 
              size="small" 
              label="Target URL (Channel/Playlist)" 
              placeholder="https://..."
              value={url} 
              onChange={e => setUrl(e.target.value)} 
              disabled={!rippingEnabled} 
              sx={{ '& .MuiOutlinedInput-root': { borderRadius: '10px' } }}
            />
          </Grid>
          <Grid item xs={12} md="auto">
            <Button 
              variant="contained" 
              color="primary"
              onClick={handleMassRip} 
              disabled={loading || !providerId || !url || !rippingEnabled}
              sx={{ minWidth: 160, height: 40, fontWeight: 'bold', borderRadius: '10px', textTransform: 'none' }}
            >
              {loading ? <CircularProgress size={22} color="inherit" /> : 'Start Mass Rip'}
            </Button>
          </Grid>
        </Grid>
        {result && <Alert severity={result.type} sx={{ mt: 3, borderRadius: '10px' }}>{result.message}</Alert>}
      </Paper>

      {/* Status summary + filters */}
      <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: 2, mb: 2 }}>
        <Box sx={{ display: 'flex', gap: 1, alignItems: 'center' }}>
          {['all', 'running', 'pending', 'paused', 'completed', 'failed'].map(s => {
            const count = s === 'all' ? sessions.length : sessions.filter(x => x.status === s).length
            return (
              <Chip key={s} label={`${s.charAt(0).toUpperCase() + s.slice(1)} (${count})`} size="small"
                clickable onClick={() => setStatusFilter(s === 'all' ? '' : s)}
                color={statusFilter === s || (s === 'all' && !statusFilter) ? 'primary' : 'default'}
                variant={statusFilter === s || (s === 'all' && !statusFilter) ? 'filled' : 'outlined'}
                sx={{ fontWeight: 600, fontSize: '0.65rem' }}
              />
            )
          })}
        </Box>
        <Box sx={{ display: 'flex', gap: 1 }}>
          {sessions.some(s => s.status === 'running') && (
            <Button size="small" variant="outlined" color="warning" onClick={() => sessions.filter(s => s.status === 'running').forEach(s => handleSessionAction(s.id, 'pause'))}
              sx={{ borderRadius: '8px', textTransform: 'none', fontSize: '0.75rem' }}>Pause All</Button>
          )}
          {sessions.some(s => s.status === 'paused') && (
            <Button size="small" variant="outlined" color="success" onClick={() => sessions.filter(s => s.status === 'paused').forEach(s => handleSessionAction(s.id, 'resume'))}
              sx={{ borderRadius: '8px', textTransform: 'none', fontSize: '0.75rem' }}>Resume All</Button>
          )}
          {sessions.some(s => ['completed', 'stopped', 'failed'].includes(s.status)) && (
            <Button size="small" variant="outlined" color="default" onClick={() => { sessions.filter(s => ['completed', 'stopped', 'failed'].includes(s.status)).forEach(s => handleSessionAction(s.id, 'delete')) }}
              sx={{ borderRadius: '8px', textTransform: 'none', fontSize: '0.75rem' }}>Clear All</Button>
          )}
        </Box>
      </Box>

      {/* Ripping Tasks Log Table */}
      <Paper sx={{ p: 3, borderRadius: '12px', border: '1px solid rgba(255,255,255,0.08)' }}>
        <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
          <Typography variant="h6" sx={{ fontWeight: 600 }}>Ripping Progress & History</Typography>
          <IconButton onClick={fetchSessions} size="small" title="Refresh list">
            <RefreshCw size={16} />
          </IconButton>
        </Box>

        <TableContainer>
          <Table size="small">
            <TableHead>
              <TableRow>
                <TableCell sx={{ fontWeight: 600 }}>Date Started</TableCell>
                <TableCell sx={{ fontWeight: 600 }}>Ruleset</TableCell>
                <TableCell sx={{ fontWeight: 600 }}>Target URL</TableCell>
                <TableCell sx={{ fontWeight: 600 }}>Status</TableCell>
                <TableCell sx={{ fontWeight: 600, width: '25%' }}>Progress</TableCell>
                <TableCell sx={{ fontWeight: 600, textAlign: 'right' }}>Actions</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {sessions.length === 0 ? (
                <TableRow>
                  <TableCell colSpan={6} align="center" sx={{ py: 4, color: 'text.secondary' }}>
                    No mass ripping tasks recorded.
                  </TableCell>
                </TableRow>
              ) : (
                filteredSessions.map((session) => {
                  const percent = session.total_videos > 0 
                    ? Math.round((session.processed_videos / session.total_videos) * 100) 
                    : 0

                  return (
                    <TableRow key={session.id} sx={{ '&:last-child td, &:last-child th': { border: 0 } }}>
                      <TableCell sx={{ whiteSpace: 'nowrap' }}>{formatDateTime(session.created_at)}</TableCell>
                      <TableCell sx={{ fontWeight: 500 }}>{getProviderName(session.provider_id)}</TableCell>
                      <TableCell sx={{ maxWidth: 300, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                        <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5 }}>
                          <Typography variant="body2" sx={{ fontSize: '12px', overflow: 'hidden', textOverflow: 'ellipsis' }}>
                            {session.url}
                          </Typography>
                          <IconButton size="small" component="a" href={session.url} target="_blank" rel="noopener noreferrer">
                            <ExternalLink size={12} />
                          </IconButton>
                        </Box>
                      </TableCell>
                      <TableCell>{getStatusChip(session.status)}</TableCell>
                      <TableCell>
                        <Box sx={{ display: 'flex', flexDirection: 'column', gap: 0.5 }}>
                          <Box sx={{ display: 'flex', justifyContent: 'space-between', fontSize: '11px' }}>
                            <Typography variant="caption" color="text.secondary">
                              {session.processed_videos} / {session.total_videos || '?'} vids
                            </Typography>
                            <Typography variant="caption" sx={{ fontWeight: 600 }}>
                              {percent}%
                            </Typography>
                          </Box>
                          <LinearProgress 
                            variant="determinate" 
                            value={percent} 
                            color={session.status === 'failed' ? 'error' : 'primary'}
                            sx={{ height: 6, borderRadius: 3 }} 
                          />
                          <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap', mt: 0.5, fontSize: '10px', color: 'text.secondary' }}>
                            <span>Queued: <strong>{session.queued_videos}</strong></span>
                            <span>•</span>
                            <span>Skipped: <strong>{session.skipped_videos}</strong></span>
                          </Box>
                        </Box>
                      </TableCell>
                      <TableCell align="right" sx={{ whiteSpace: 'nowrap' }}>
                        {session.status === 'running' && (
                          <>
                            <Tooltip title="Pause ripping">
                              <IconButton size="small" onClick={() => handleSessionAction(session.id, 'pause')} color="warning">
                                <Pause size={16} />
                              </IconButton>
                            </Tooltip>
                            <Tooltip title="Stop ripping">
                              <IconButton size="small" onClick={() => handleSessionAction(session.id, 'stop')} color="error">
                                <Square size={16} />
                              </IconButton>
                            </Tooltip>
                          </>
                        )}
                        {session.status === 'paused' && (
                          <>
                            <Tooltip title="Resume ripping">
                              <IconButton size="small" onClick={() => handleSessionAction(session.id, 'resume')} color="primary">
                                <Play size={16} />
                              </IconButton>
                            </Tooltip>
                            <Tooltip title="Stop ripping">
                              <IconButton size="small" onClick={() => handleSessionAction(session.id, 'stop')} color="error">
                                <Square size={16} />
                              </IconButton>
                            </Tooltip>
                          </>
                        )}
                        {session.status === 'pending' && (
                          <Tooltip title="Cancel ripping">
                            <IconButton size="small" onClick={() => handleSessionAction(session.id, 'stop')} color="error">
                              <Square size={16} />
                            </IconButton>
                          </Tooltip>
                        )}
                        {['completed', 'stopped', 'failed'].includes(session.status) && (
                          <Tooltip title="Delete record">
                            <IconButton size="small" onClick={() => handleSessionAction(session.id, 'delete')} color="default">
                              <Trash2 size={16} />
                            </IconButton>
                          </Tooltip>
                        )}
                      </TableCell>
                    </TableRow>
                  )
                })
              )}
            </TableBody>
          </Table>
        </TableContainer>
      </Paper>
    </Box>
  )
}

import { useState, useEffect } from 'react'
import {
  Box, Button, Card, CardContent, TextField, Typography, 
  Dialog, DialogTitle, DialogContent, DialogActions, Alert,
  Chip, CircularProgress, FormControl, InputLabel, Select, MenuItem
} from '@mui/material'
import { apiFetch } from '../api'
import { Tag } from 'lucide-react'
import UrlParseConfirmationModal from './UrlParseConfirmationModal'
import Duplicates from './Duplicates'
import { Paper, Tabs, Tab } from '@mui/material'

export default function MetadataManager() {
  const [subTab, setSubTab] = useState(0)
  const [entryId, setEntryId] = useState('')
  const [metadata, setMetadata] = useState(null)
  const [loading, setLoading] = useState(false)
  const [libraryEntries, setLibraryEntries] = useState([])
  const [message, setMessage] = useState('')

  // URL Parsing states
  const [parseUrl, setParseUrl] = useState('')
  const [parseLoading, setParseLoading] = useState(false)
  const [parsedMetadata, setParsedMetadata] = useState(null)
  const [modalOpen, setModalOpen] = useState(false)
  const [urlParsingPermission, setUrlParsingPermission] = useState('edit')

  useEffect(() => {
    apiFetch('/library?limit=1000')
      .then(res => {
        if (!res.ok) throw new Error('Failed to fetch library entries')
        return res.json()
      })
      .then(data => {
        if (Array.isArray(data)) setLibraryEntries(data)
        else if (data && data.items) setLibraryEntries(data.items)
      })
      .catch(console.error)

    apiFetch('/auth/me')
      .then(res => {
        if (res.ok) return res.json()
      })
      .then(data => {
        if (data) {
          const userPerms = data.permissions || {}
          const perm = userPerms.url_parsing || (data.role === 'admin' ? 'edit' : 'no_access')
          setUrlParsingPermission(perm)
        }
      })
      .catch(console.error)
  }, [])

  const handleFetchMetadata = async () => {
    if (!entryId) {
      setMessage('Please enter an entry ID')
      return
    }

    setLoading(true)
    try {
      const response = await apiFetch(`/metadata/entry/${entryId}`)
      if (response.ok) {
        const data = await response.json()
        setMetadata(data)
        setMessage('')
      } else {
        setMessage('Entry not found')
      }
    } catch (error) {
      setMessage(`Error: ${error.message}`)
    }
    setLoading(false)
  }

  const handleUpdateMetadata = async () => {
    try {
      const response = await apiFetch(`/metadata/entry/${entryId}/update`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          title: metadata.title,
          performers: metadata.performers,
          tags: metadata.tags,
          studio: metadata.studio_name,
          description: metadata.entry_metadata?.description
        })
      })
      if (response.ok) {
        setMessage('Metadata updated successfully')
      } else {
        const errData = await response.json().catch(() => ({}))
        setMessage(`Failed to update metadata: ${errData.detail || response.statusText}`)
      }
    } catch (error) {
      setMessage(`Error: ${error.message}`)
    }
  }

  const handleWriteToFile = async () => {
    if (!entryId) {
      setMessage('Please select an entry')
      return
    }

    setLoading(true)
    try {
      const response = await apiFetch(`/metadata/entry/${entryId}/write-to-file`, {
        method: 'POST'
      })
      if (response.ok) {
        const data = await response.json()
        setMessage(`Metadata written to: ${data.sidecar_file}`)
      } else {
        setMessage('Failed to write metadata')
      }
    } catch (error) {
      setMessage(`Error: ${error.message}`)
    }
    setLoading(false)
  }

  const handleQuickCache = async (source) => {
    if (!metadata || !metadata.title) {
      setMessage('Please fetch an entry first to base the search on its title.')
      return
    }
    setLoading(true)
    try {
      const settingsRes = await apiFetch('/settings')
      if (!settingsRes.ok) throw new Error('Failed to retrieve external API settings')
      const settings = await settingsRes.json()
      const apiKey = source === 'theporndb' ? settings.tpdb_api_key : settings.stashdb_api_key

      if (!apiKey) {
        throw new Error(`Missing API Key for ${source}. Please configure it in the Settings tab.`)
      }

      const res = await apiFetch(`/external-api/${source}/query`, {
        method: 'POST',
        headers: { 'X-API-Key': apiKey, 'Content-Type': 'application/json' },
        body: JSON.stringify({ query: metadata.title })
      })
      const data = await res.json()
      if (res.ok && data.results && data.results.length > 0) {
        const topResult = data.results[0]
        setMetadata(prev => ({
          ...prev,
          title: topResult.title || prev.title,
          performers: topResult.performers || prev.performers,
          tags: topResult.tags || prev.tags,
          studio_name: topResult.studio?.name || prev.studio_name,
          entry_metadata: { ...prev.entry_metadata, description: topResult.description || prev.entry_metadata?.description }
        }))
        setMessage(`Loaded top match from ${source}! Click 'Update Metadata' to save it.`)
      } else {
        setMessage(`No matches found on ${source}.`)
      }
    } catch (error) {
      setMessage(`Error: ${error.message}`)
    }
  }

  const handleParseUrl = async () => {
    if (!parseUrl) {
      setMessage('Please enter a URL to parse')
      return
    }

    if (urlParsingPermission === 'no_access') {
      setMessage('Error: You do not have permissions to access the URL parsing feature.')
      return
    }

    setParseLoading(true)
    try {
      const response = await apiFetch('/scraper/parse-url', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ url: parseUrl })
      })

      if (response.ok) {
        const data = await response.json()
        setParsedMetadata(data.metadata)
        setModalOpen(true)
        setMessage('')
      } else {
        const errData = await response.json().catch(() => ({}))
        setMessage(`Error parsing URL: ${errData.detail || response.statusText}`)
      }
    } catch (error) {
      setMessage(`Error parsing URL: ${error.message}`)
    }
    setParseLoading(false)
  }

  const handleApplyParsedMetadata = (appliedData) => {
    setMetadata(prev => {
      const updated = { ...prev }
      if (appliedData.title) updated.title = appliedData.title
      if (appliedData.studio) updated.studio_name = appliedData.studio
      if (appliedData.performers) updated.performers = appliedData.performers
      if (appliedData.tags) updated.tags = appliedData.tags
      if (appliedData.description) {
        updated.entry_metadata = {
          ...updated.entry_metadata,
          description: appliedData.description
        }
      }
      return updated
    })
    setMessage('Parsed metadata successfully loaded into form! Click "Update Metadata" to save.')
  }

  return (
    <Box sx={{ maxWidth: 1400, mx: 'auto', width: '100%' }}>
      <Typography variant="h4" sx={{ fontWeight: 'bold', mb: 3 }}>
        Metadata Management Hub
      </Typography>

      <Paper sx={{ mb: 3, borderRadius: '14px', border: '1px solid rgba(255,255,255,0.08)', bgcolor: 'rgba(15,23,42,0.4)', backdropFilter: 'blur(12px)' }}>
        <Tabs 
          value={subTab} 
          onChange={(e, val) => setSubTab(val)}
          sx={{ px: 2, '& .MuiTab-root': { fontWeight: 'bold', textTransform: 'none', minHeight: 48 } }}
        >
          <Tab label="Metadata Clean & Auto-Tag" />
          <Tab label="Duplicate Hash Resolver" />
        </Tabs>
      </Paper>

      {subTab === 0 && (
        <>
          {/* Purpose Banner */}
          <Alert 
            severity="info" 
            icon={<Tag size={20} />} 
            sx={{ 
              mb: 3, 
              borderRadius: '12px', 
              bgcolor: 'rgba(99, 102, 241, 0.08)', 
              color: '#a5b4fc',
              border: '1px solid rgba(99, 102, 241, 0.2)',
              '& .MuiAlert-icon': { color: '#818cf8' } 
            }}
          >
            <Typography variant="subtitle2" sx={{ fontWeight: 'bold', mb: 0.25 }}>
              🏷️ Centralized Media Metadata &amp; Taxonomy Engine
            </Typography>
            <Typography variant="caption" sx={{ display: 'block', opacity: 0.9, lineHeight: 1.4 }}>
              Inspect and clean scene titles, studio assignments, tags, and performer profiles. Run AI auto-tagging across your library, fetch missing metadata from provider scrapers, or parse metadata directly from video URLs.
            </Typography>
          </Alert>

          {message && (
            <Alert 
              severity={message.includes('Error') ? 'error' : 'info'} 
              sx={{ mb: 3, borderRadius: '10px' }} 
              onClose={() => setMessage('')}
            >
              {message}
            </Alert>
          )}

          {/* Fetch & Edit Metadata Card */}
          <Card sx={{ mb: 3 }}>
            <CardContent>
              <Typography variant="h6" gutterBottom sx={{ fontWeight: 'bold' }}>Fetch &amp; Edit Metadata</Typography>
              <Box sx={{ display: 'flex', gap: 2, mb: 3 }}>
                <FormControl sx={{ minWidth: 300 }} size="small">
                  <InputLabel>Select Library Entry</InputLabel>
                  <Select
                    value={entryId}
                    label="Select Library Entry"
                    onChange={(e) => setEntryId(e.target.value)}
                  >
                    {libraryEntries.map(entry => <MenuItem key={entry.id} value={entry.id}>{entry.title || `Entry #${entry.id}`}</MenuItem>)}
                  </Select>
                </FormControl>
                <Button variant="contained" onClick={() => handleFetchMetadata(entryId)} disabled={!entryId || loading}>
                  {loading ? <CircularProgress size={20} color="inherit" /> : 'Fetch'}
                </Button>
              </Box>

              {urlParsingPermission !== 'no_access' && (
                <Box sx={{ display: 'flex', gap: 1, mb: 2, mt: 1, p: 2, borderRadius: '10px', background: 'rgba(255,255,255,0.03)', border: '1px solid rgba(255,255,255,0.08)', alignItems: 'center' }}>
                  <TextField
                    fullWidth
                    size="small"
                    placeholder="Paste adult video URL to parse metadata..."
                    value={parseUrl}
                    onChange={(e) => setParseUrl(e.target.value)}
                    sx={{ '& .MuiOutlinedInput-root': { borderRadius: '8px' } }}
                  />
                  <Button variant="outlined" color="secondary" onClick={handleParseUrl} disabled={parseLoading} sx={{ borderRadius: '8px', whiteSpace: 'nowrap', py: 1 }}>
                    {parseLoading ? <CircularProgress size={20} /> : 'Parse URL'}
                  </Button>
                </Box>
              )}

              {metadata && (
                <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2, mt: 2 }}>
                  <TextField
                    fullWidth
                    label="Title"
                    value={metadata.title || ''}
                    onChange={(e) => setMetadata({...metadata, title: e.target.value})}
                  />
                  <TextField
                    fullWidth
                    label="Studio"
                    value={metadata.studio_name || ''}
                    onChange={(e) => setMetadata({...metadata, studio_name: e.target.value})}
                  />
                  <TextField
                    fullWidth
                    label="Performers (comma-separated)"
                    value={metadata.performers?.join(', ') || ''}
                    onChange={(e) => setMetadata({
                      ...metadata,
                      performers: e.target.value.split(',').map(p => p.trim())
                    })}
                  />
                  <TextField
                    fullWidth
                    label="Tags (comma-separated)"
                    value={metadata.tags?.join(', ') || ''}
                    onChange={(e) => setMetadata({
                      ...metadata,
                      tags: e.target.value.split(',').map(t => t.trim())
                    })}
                  />
                  <TextField
                    fullWidth
                    label="Description"
                    value={metadata.entry_metadata?.description || ''}
                    onChange={(e) => setMetadata({
                      ...metadata,
                      entry_metadata: {...metadata.entry_metadata, description: e.target.value}
                    })}
                    multiline
                    rows={3}
                  />

                  <Box sx={{ mt: 1, display: 'flex', gap: 1.5 }}>
                    <Button variant="contained" color="success" onClick={handleSaveMetadata}>
                      Update Metadata
                    </Button>
                  </Box>
                </Box>
              )}
            </CardContent>
          </Card>

          {/* Quick Actions */}
          <Card>
            <CardContent>
              <Typography variant="h6" gutterBottom sx={{ fontWeight: 'bold' }}>Metadata Caching</Typography>
              <Box sx={{ display: 'flex', gap: 1.5 }}>
                <Button variant="contained" onClick={() => handleQuickCache('theporndb')} disabled={loading}>
                  Cache Metadata from ThePornDB
                </Button>
                <Button variant="contained" onClick={() => handleQuickCache('stashdb')} disabled={loading}>
                  Cache Metadata from StashDB
                </Button>
              </Box>
            </CardContent>
          </Card>

          <UrlParseConfirmationModal
            open={modalOpen}
            onClose={() => setModalOpen(false)}
            parsedData={parsedMetadata}
            currentData={{
              title: metadata?.title || '',
              studio: metadata?.studio_name || '',
              performers: metadata?.performers || [],
              tags: metadata?.tags || [],
              description: metadata?.entry_metadata?.description || ''
            }}
            onApply={handleApplyParsedMetadata}
            permission={urlParsingPermission}
          />
        </>
      )}

      {subTab === 1 && <Duplicates />}
    </Box>
  )
}

import { useState, useEffect, useCallback } from 'react'
import { 
  Box, Grid, Typography, Card, CardContent, Switch, FormControlLabel, 
  Button, TextField, Select, MenuItem, InputLabel, FormControl, Table, 
  TableBody, TableCell, TableContainer, TableHead, TableRow, Paper, 
  IconButton, Chip, List, ListItem, ListItemText, ListItemIcon, 
  Divider, Tooltip
} from '@mui/material'
import DeleteIcon from '@mui/icons-material/Delete'
import NotificationsIcon from '@mui/icons-material/Notifications'
import TaskAltIcon from '@mui/icons-material/TaskAlt'
import FavoriteBorderIcon from '@mui/icons-material/FavoriteBorder'
import SendIcon from '@mui/icons-material/Send'
import MarkEmailReadIcon from '@mui/icons-material/MarkEmailRead'
import { apiFetch } from '../api'

export default function NotificationSettings() {
  const [preferences, setPreferences] = useState([])
  const [rules, setRules] = useState([])
  const [history, setHistory] = useState([])
  const [isAdmin, setIsAdmin] = useState(false)

  // Rule creation state
  const [newRule, setNewRule] = useState({
    event_type: 'task_completed',
    discord_channel_id: '',
    webhook_url: '',
    is_active: true
  })

  // Load preferences
  const fetchPrefs = useCallback(async () => {
    try {
      const res = await apiFetch('/notifications/preferences')
      if (res.ok) {
        const data = await res.json()
        setPreferences(data)
      }
    } catch (e) {
      console.error(e)
    }
  }, [])

  // Load rules (admin only)
  const fetchRules = useCallback(async () => {
    try {
      const res = await apiFetch('/notifications/rules')
      if (res.ok) {
        const data = await res.json()
        setRules(data)
        setIsAdmin(true)
      } else {
        setIsAdmin(false)
      }
    } catch (e) {
      console.error(e)
    }
  }, [])

  // Load history
  const fetchHistory = useCallback(async () => {
    try {
      const res = await apiFetch('/notifications/history')
      if (res.ok) {
        const data = await res.json()
        setHistory(data)
      }
    } catch (e) {
      console.error(e)
    }
  }, [])

  useEffect(() => {
    fetchPrefs()
    fetchRules()
    fetchHistory()
  }, [fetchPrefs, fetchRules, fetchHistory])

  // Handle preference toggle
  const handlePrefChange = async (event_type, dispatch_method, enabled) => {
    const updated = preferences.map(p => 
      (p.event_type === event_type && p.dispatch_method === dispatch_method)
        ? { ...p, enabled }
        : p
    )
    setPreferences(updated)

    try {
      await apiFetch('/notifications/preferences', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(updated)
      })
    } catch (e) {
      console.error('Failed to update preference:', e)
    }
  }

  // Handle rule submission
  const handleRuleSubmit = async (e) => {
    e.preventDefault()
    if (!newRule.discord_channel_id && !newRule.webhook_url) {
      window.dispatchEvent(new CustomEvent('show-toast', { 
        detail: { message: 'Please specify either a Webhook URL or a Discord Channel ID.', severity: 'warning' } 
      }))
      return
    }
    try {
      const res = await apiFetch('/notifications/rules', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(newRule)
      })
      if (res.ok) {
        window.dispatchEvent(new CustomEvent('show-toast', { detail: { message: 'Rule added successfully!', severity: 'success' } }))
        setNewRule({ event_type: 'task_completed', discord_channel_id: '', webhook_url: '', is_active: true })
        fetchRules()
      }
    } catch (e) {
      console.error(e)
    }
  }

  // Handle rule delete
  const handleRuleDelete = async (ruleId) => {
    const confirm = await window.appConfirm('Are you sure you want to delete this custom notification rule?')
    if (!confirm) return

    try {
      const res = await apiFetch(`/notifications/rules/${ruleId}`, {
        method: 'DELETE'
      })
      if (res.ok) {
        window.dispatchEvent(new CustomEvent('show-toast', { detail: { message: 'Rule deleted.', severity: 'success' } }))
        fetchRules()
      }
    } catch (e) {
      console.error(e)
    }
  }

  // Mark history as read
  const handleMarkRead = async (ids = null) => {
    try {
      const res = await apiFetch('/notifications/read', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ notification_ids: ids })
      })
      if (res.ok) {
        fetchHistory()
      }
    } catch (e) {
      console.error(e)
    }
  }

  return (
    <Box sx={{ flexGrow: 1, display: 'flex', flexDirection: 'column', gap: 3.5, maxWidth: 1400, mx: 'auto', width: '100%' }}>
      <Box>
        <Typography variant="h4" sx={{ fontWeight: '800', display: 'flex', alignItems: 'center', gap: 1.5, letterSpacing: '-0.5px' }}>
          <NotificationsIcon color="primary" sx={{ fontSize: 32 }} /> Notifications &amp; Webhooks
        </Typography>
        <Typography variant="body2" color="text.secondary" sx={{ mt: 0.5 }}>
          Manage your personal notification preferences and system automation alerts.
        </Typography>
      </Box>

      <Grid container spacing={3}>
        {/* Personal Preferences Card */}
        <Grid item xs={12}>
          <Card sx={{ background: 'rgba(15, 23, 42, 0.4)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255, 255, 255, 0.08)', borderRadius: '16px', boxShadow: '0 8px 32px rgba(0, 0, 0, 0.25)' }}>
            <CardContent sx={{ display: 'flex', flexDirection: 'column', gap: 2.5, p: 3 }}>
              <Typography variant="h6" sx={{ fontWeight: '700' }}>Your Notification Channels</Typography>
              <Typography variant="body2" color="text.secondary">
                Choose where you'd like to receive notifications for background tasks and catalog updates.
              </Typography>
              <Divider sx={{ borderColor: 'rgba(255,255,255,0.08)' }} />

              {/* Task Completion Delivery */}
              <Box>
                <Typography variant="subtitle1" sx={{ fontWeight: 'bold', display: 'flex', alignItems: 'center', gap: 1 }}>
                  <TaskAltIcon fontSize="small" color="primary" /> Task Completed Alerts
                </Typography>
                <Typography variant="caption" color="text.secondary" sx={{ display: 'block', mb: 1.5 }}>
                  Fires when a queued download completes processing or metadata syncing finishes.
                </Typography>
                <Box sx={{ display: 'flex', gap: 3 }}>
                  <FormControlLabel
                    control={
                      <Switch
                        checked={preferences.find(p => p.event_type === 'task_completed' && p.dispatch_method === 'toast')?.enabled || false}
                        onChange={(e) => handlePrefChange('task_completed', 'toast', e.target.checked)}
                      />
                    }
                    label="Browser Toast"
                  />
                  <FormControlLabel
                    control={
                      <Switch
                        checked={preferences.find(p => p.event_type === 'task_completed' && p.dispatch_method === 'discord_dm')?.enabled || false}
                        onChange={(e) => handlePrefChange('task_completed', 'discord_dm', e.target.checked)}
                      />
                    }
                    label="Discord DM"
                  />
                </Box>
              </Box>

              <Divider sx={{ borderColor: 'rgba(255,255,255,0.08)' }} />

              {/* Favorite Items Alerts */}
              <Box>
                <Typography variant="subtitle1" sx={{ fontWeight: 'bold', display: 'flex', alignItems: 'center', gap: 1 }}>
                  <FavoriteBorderIcon fontSize="small" color="error" /> Favorite Catalog Matches
                </Typography>
                <Typography variant="caption" color="text.secondary" sx={{ display: 'block', mb: 1.5 }}>
                  Fires when a newly scanned or downloaded item matches your favorited performers, tags, or studios.
                </Typography>
                <Box sx={{ display: 'flex', gap: 3 }}>
                  <FormControlLabel
                    control={
                      <Switch
                        checked={preferences.find(p => p.event_type === 'favorite_updated' && p.dispatch_method === 'toast')?.enabled || false}
                        onChange={(e) => handlePrefChange('favorite_updated', 'toast', e.target.checked)}
                      />
                    }
                    label="Browser Toast"
                  />
                  <FormControlLabel
                    control={
                      <Switch
                        checked={preferences.find(p => p.event_type === 'favorite_updated' && p.dispatch_method === 'discord_dm')?.enabled || false}
                        onChange={(e) => handlePrefChange('favorite_updated', 'discord_dm', e.target.checked)}
                      />
                    }
                    label="Discord DM"
                  />
                </Box>
              </Box>
            </CardContent>
          </Card>
        </Grid>

        {/* Discord Automation Rules (Admin Only) */}
        {isAdmin && (
          <Grid item xs={12}>
            <Card sx={{ background: 'rgba(15, 23, 42, 0.4)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255, 255, 255, 0.08)', borderRadius: '16px', boxShadow: '0 8px 32px rgba(0, 0, 0, 0.25)' }}>
              <CardContent sx={{ display: 'flex', flexDirection: 'column', gap: 3, p: 3 }}>
                <Typography variant="h6" sx={{ fontWeight: '700' }}>Admin Broadcast Webhooks &amp; Rules</Typography>
                <Typography variant="body2" sx={{ opacity: 0.7 }}>
                  Create rules to automatically broadcast specific system events to Discord channels via custom webhooks or channel post dispatches.
                </Typography>
                <Divider />

                {/* Add Rule Form */}
                <Box component="form" onSubmit={handleRuleSubmit} sx={{ display: 'flex', flexWrap: 'wrap', gap: 2.5, alignItems: 'center' }}>
                  <FormControl size="small" sx={{ minWidth: 200 }}>
                    <InputLabel>Event Type</InputLabel>
                    <Select
                      value={newRule.event_type}
                      label="Event Type"
                      onChange={(e) => setNewRule({ ...newRule, event_type: e.target.value })}
                    >
                      <MenuItem value="task_completed">Background Tasks (Task Completed)</MenuItem>
                      <MenuItem value="favorite_updated">Favorite Matches (Favorite Catalog Matches)</MenuItem>
                    </Select>
                  </FormControl>

                  <TextField
                    size="small"
                    label="Discord Webhook URL"
                    value={newRule.webhook_url}
                    onChange={(e) => setNewRule({ ...newRule, webhook_url: e.target.value })}
                    sx={{ flexGrow: 1, minWidth: 250 }}
                    placeholder="https://discord.com/api/webhooks/..."
                  />

                  <Typography variant="body2" sx={{ opacity: 0.5 }}>or</Typography>

                  <TextField
                    size="small"
                    label="Discord Channel ID"
                    value={newRule.discord_channel_id}
                    onChange={(e) => setNewRule({ ...newRule, discord_channel_id: e.target.value })}
                    sx={{ width: 220 }}
                    placeholder="e.g. 112233445566778899"
                  />

                  <Button 
                    type="submit" 
                    variant="contained" 
                    color="primary"
                    startIcon={<SendIcon />}
                  >
                    Add Automation Rule
                  </Button>
                </Box>

                <Divider />

                {/* Rules List */}
                <Typography variant="subtitle1" sx={{ fontWeight: 'bold' }}>Active Automation Rules</Typography>
                {rules.length === 0 ? (
                  <Typography variant="body2" sx={{ opacity: 0.5, p: 2 }}>No active notification rules configured.</Typography>
                ) : (
                  <TableContainer component={Paper} sx={{ background: 'rgba(255,255,255,0.01)', border: '1px solid rgba(255,255,255,0.05)' }}>
                    <Table size="small">
                      <TableHead>
                        <TableRow>
                      <TableCell align="center" sx={{ fontWeight: 'bold', whiteSpace: 'nowrap' }}>Event Type</TableCell>
                      <TableCell align="center" sx={{ fontWeight: 'bold', whiteSpace: 'nowrap' }}>Webhook URL</TableCell>
                      <TableCell align="center" sx={{ fontWeight: 'bold', whiteSpace: 'nowrap' }}>Discord Channel ID</TableCell>
                      <TableCell align="center" sx={{ fontWeight: 'bold', whiteSpace: 'nowrap' }}>Status</TableCell>
                      <TableCell align="center" sx={{ fontWeight: 'bold', whiteSpace: 'nowrap' }}>Actions</TableCell>
                        </TableRow>
                      </TableHead>
                      <TableBody>
                        {rules.map((rule) => (
                          <TableRow key={rule.id}>
                        <TableCell align="center" sx={{ whiteSpace: 'nowrap' }}>
                              <Chip 
                                size="small"
                                label={rule.event_type === 'task_completed' ? 'Task Completed' : 'Favorite Updated'} 
                                color={rule.event_type === 'task_completed' ? 'primary' : 'secondary'}
                              />
                            </TableCell>
                        <TableCell align="center" sx={{ fontFamily: 'monospace', opacity: 0.8, whiteSpace: 'nowrap' }}>
                              {rule.webhook_url ? `${rule.webhook_url.substring(0, 35)}...` : '-'}
                            </TableCell>
                        <TableCell align="center" sx={{ fontFamily: 'monospace', opacity: 0.8, whiteSpace: 'nowrap' }}>
                              {rule.discord_channel_id || '-'}
                            </TableCell>
                        <TableCell align="center" sx={{ whiteSpace: 'nowrap' }}>
                              <Chip 
                                size="small"
                                label={rule.is_active ? 'Active' : 'Disabled'} 
                                color={rule.is_active ? 'success' : 'default'} 
                                variant="outlined"
                              />
                            </TableCell>
                        <TableCell align="center" sx={{ whiteSpace: 'nowrap' }}>
                              <IconButton color="error" size="small" onClick={() => handleRuleDelete(rule.id)}>
                                <DeleteIcon fontSize="small" />
                              </IconButton>
                            </TableCell>
                          </TableRow>
                        ))}
                      </TableBody>
                    </Table>
                  </TableContainer>
                )}
              </CardContent>
            </Card>
          </Grid>
        )}
      </Grid>
    </Box>
  )
}

import { useState, useEffect, useCallback } from 'react'
import {
  Box, Typography, TextField, Button, Paper, Grid, Divider,
  Table, TableBody, TableCell, TableContainer, TableHead, TableRow,
  IconButton, Dialog, DialogTitle, DialogContent, DialogActions,
  Select, MenuItem, FormControl, InputLabel, Card, CardContent,
  CardActions, Chip, CircularProgress, Collapse, Checkbox, ListItemText, OutlinedInput, Alert
} from '@mui/material'
import { Trash2, RefreshCw, Plus, Edit2, Wifi, History, CheckCircle, TriangleAlert, Hourglass, ChevronDown, ChevronUp } from 'lucide-react'
import { apiFetch } from '../api'

export default function P2PSync() {
  const [nodes, setNodes] = useState([])
  const [providers, setProviders] = useState([])
  const [proposedRecipes, setProposedRecipes] = useState([])
  const [loading, setLoading] = useState(false)
  const [syncingNodes, setSyncingNodes] = useState({}) // node_id -> boolean
  const [testingNodes, setTestingNodes] = useState({}) // node_id -> boolean
  const [expandedLogs, setExpandedLogs] = useState({}) // node_id -> boolean
  const [nodeLogs, setNodeLogs] = useState({}) // node_id -> array of logs

  // Dialog Form states
  const [dialogOpen, setDialogOpen] = useState(false)
  const [editNodeId, setEditNodeId] = useState(null)
  const [formName, setFormName] = useState('')
  const [formUrl, setFormUrl] = useState('')
  const [formOutboundKey, setFormOutboundKey] = useState('')
  const [formInboundToken, setFormInboundToken] = useState('')
  const [formRecipeMode, setFormRecipeMode] = useState('auto_merge')
  const [formSchedule, setFormSchedule] = useState('manual')
  const [formScope, setFormScope] = useState('all_entries')
  const [formAllowedProviders, setFormAllowedProviders] = useState([])

  const showToast = (message, severity = 'info') => {
    window.dispatchEvent(new CustomEvent('show-toast', {
      detail: { message, severity }
    }))
  }

  const fetchNodes = useCallback(async () => {
    try {
      const res = await apiFetch('/p2p/nodes')
      if (res.ok) {
        setNodes(await res.json())
      }
    } catch (err) {
      console.error('Failed to fetch P2P nodes:', err)
    }
  }, [])

  const fetchProviders = useCallback(async () => {
    try {
      const res = await apiFetch('/providers')
      if (res.ok) {
        setProviders(await res.json())
      }
    } catch (err) {
      console.error('Failed to fetch providers:', err)
    }
  }, [])

  const fetchProposedRecipes = useCallback(async () => {
    try {
      const res = await apiFetch('/p2p/proposed-recipes')
      if (res.ok) {
        setProposedRecipes(await res.json())
      }
    } catch (err) {
      console.error('Failed to fetch proposed recipes:', err)
    }
  }, [])

  useEffect(() => {
    setLoading(true)
    Promise.all([fetchNodes(), fetchProviders(), fetchProposedRecipes()])
      .finally(() => setLoading(false))
  }, [fetchNodes, fetchProviders, fetchProposedRecipes])

  // Periodic status poll to capture syncing -> active / error updates
  useEffect(() => {
    const interval = setInterval(() => {
      fetchNodes()
    }, 10000)
    return () => clearInterval(interval)
  }, [fetchNodes])

  const handleOpenCreate = () => {
    setEditNodeId(null)
    setFormName('')
    setFormUrl('')

    // Auto-generate safe tokens for convenience
    const randToken1 = Math.random().toString(36).substring(2, 15) + Math.random().toString(36).substring(2, 15)
    const randToken2 = Math.random().toString(36).substring(2, 15) + Math.random().toString(36).substring(2, 15)

    setFormOutboundKey(randToken1)
    setFormInboundToken(randToken2)
    setFormRecipeMode('auto_merge')
    setFormSchedule('manual')
    setFormScope('all_entries')
    setFormAllowedProviders([])
    setDialogOpen(true)
  }

  const handleOpenEdit = (node) => {
    setEditNodeId(node.id)
    setFormName(node.name)
    setFormUrl(node.peer_url)
    setFormOutboundKey(node.outbound_key)
    setFormInboundToken(node.inbound_token)
    setFormRecipeMode(node.recipe_sync_mode)
    setFormSchedule(node.sync_schedule)
    setFormScope(node.library_scope)
    setFormAllowedProviders(node.allowed_providers || [])
    setDialogOpen(true)
  }

  const handleSaveNode = async () => {
    if (!formName.trim() || !formUrl.trim() || !formOutboundKey.trim() || !formInboundToken.trim()) {
      showToast('Please fill out all required fields.', 'warning')
      return
    }

    const payload = {
      name: formName.trim(),
      peer_url: formUrl.trim(),
      outbound_key: formOutboundKey.trim(),
      inbound_token: formInboundToken.trim(),
      recipe_sync_mode: formRecipeMode,
      sync_schedule: formSchedule,
      library_scope: formScope,
      allowed_providers: formAllowedProviders
    }

    try {
      let res
      if (editNodeId) {
        res = await apiFetch(`/p2p/nodes/${editNodeId}`, {
          method: 'PUT',
          body: JSON.stringify(payload)
        })
      } else {
        res = await apiFetch('/p2p/nodes', {
          method: 'POST',
          body: JSON.stringify(payload)
        })
      }

      if (res.ok) {
        showToast(editNodeId ? 'Peer updated successfully!' : 'Peer registered successfully!', 'success')
        setDialogOpen(false)
        fetchNodes()
      } else {
        const err = await res.json()
        showToast(`Failed to save: ${err.detail || 'Unknown error'}`, 'error')
      }
    } catch (err) {
      console.error(err)
      showToast('Network error saving peer.', 'error')
    }
  }

  const handleDeleteNode = async (id, name) => {
    const confirm = await window.appConfirm(`Are you sure you want to remove peer "${name}"?`)
    if (!confirm) return

    try {
      const res = await apiFetch(`/p2p/nodes/${id}`, { method: 'DELETE' })
      if (res.ok) {
        showToast(`Peer "${name}" removed.`, 'success')
        fetchNodes()
      } else {
        showToast('Failed to delete peer.', 'error')
      }
    } catch (err) {
      console.error(err)
      showToast('Network error deleting peer.', 'error')
    }
  }

  const handleTestConnection = async (id) => {
    setTestingNodes(prev => ({ ...prev, [id]: true }))
    try {
      const res = await apiFetch(`/p2p/nodes/${id}/test-connection`, { method: 'POST' })
      if (res.ok) {
        const data = await res.json()
        if (data.connected) {
          showToast(`Connection successful! Connected to ${data.peer_details?.peer_name || 'peer'}`, 'success')
        } else {
          showToast(`Connection failed: ${data.message}`, 'error')
        }
        fetchNodes()
      } else {
        showToast('Failed to execute connection test.', 'error')
      }
    } catch (err) {
      console.error(err)
      showToast('Connection test encountered a network error.', 'error')
    } finally {
      setTestingNodes(prev => ({ ...prev, [id]: false }))
    }
  }

  const handleTriggerSync = async (id, name) => {
    setSyncingNodes(prev => ({ ...prev, [id]: true }))
    try {
      const res = await apiFetch(`/p2p/nodes/${id}/sync`, { method: 'POST' })
      if (res.ok) {
        showToast(`Sync enqueued for "${name}".`, 'info')
        fetchNodes()
      } else {
        showToast('Failed to trigger sync.', 'error')
      }
    } catch (err) {
      console.error(err)
      showToast('Sync trigger network error.', 'error')
    } finally {
      setSyncingNodes(prev => ({ ...prev, [id]: false }))
    }
  }

  const toggleLogs = async (id) => {
    const isExpanded = !expandedLogs[id]
    setExpandedLogs(prev => ({ ...prev, [id]: isExpanded }))

    if (isExpanded) {
      try {
        const res = await apiFetch(`/p2p/nodes/${id}/logs`)
        if (res.ok) {
          const data = await res.json()
          setNodeLogs(prev => ({ ...prev, [id]: data }))
        }
      } catch (err) {
        console.error('Failed to load logs:', err)
      }
    }
  }

  const handleResolveProposed = async (peerId, providerName, action) => {
    try {
      const res = await apiFetch('/p2p/proposed-recipes/resolve', {
        method: 'POST',
        body: JSON.stringify({
          peer_id: peerId,
          provider_name: providerName,
          action
        })
      })
      if (res.ok) {
        showToast(`Proposed recipe for "${providerName}" has been ${action}d.`, 'success')
        fetchProposedRecipes()
      } else {
        showToast('Failed to resolve proposed recipe.', 'error')
      }
    } catch (err) {
      console.error(err)
      showToast('Network error resolving proposed recipe.', 'error')
    }
  }

  const getStatusChipColor = (status) => {
    switch (status) {
      case 'active': return 'success'
      case 'syncing': return 'info'
      case 'error': return 'error'
      default: return 'default'
    }
  }

  return (
    <Box sx={{ pb: 5, maxWidth: 1400, mx: 'auto', width: '100%' }}>
      {/* Dynamic visual page header with subtle glassmorphic backdrop */}
      <Box sx={{
        background: 'linear-gradient(135deg, rgba(0,240,255,0.05) 0%, rgba(255,0,127,0.05) 100%)',
        p: 4,
        borderRadius: '24px',
        mb: 4,
        border: '1px solid rgba(255,255,255,0.04)',
        backdropFilter: 'blur(10px)'
      }}>
        <Grid container sx={{ justifyContent: 'space-between', alignItems: 'center' }}>
          <Grid>
            <Typography variant="h4" fontWeight="800" sx={{ letterSpacing: '-1px' }} gutterBottom>
              P2P Synchronization Console
            </Typography>
            <Typography variant="body1" color="text.secondary">
              Securely share scraper recipes and reconcile media catalog lists with trusted Voyarr nodes.
            </Typography>
          </Grid>
          <Grid>
            <Button
              variant="contained"
              startIcon={<Plus size={20} />}
              onClick={handleOpenCreate}
              sx={{
                background: 'linear-gradient(45deg, #00f0ff 0%, #ff007f 100%)',
                color: '#fff',
                '&:hover': {
                  background: 'linear-gradient(45deg, #00d0df 0%, #df006f 100%)'
                }
              }}
            >
              Add Trusted Peer
            </Button>
          </Grid>
        </Grid>
      </Box>

      {/* Purpose Banner */}
      <Alert 
        severity="info" 
        icon={<Wifi size={20} />} 
        sx={{ 
          mb: 3, 
          borderRadius: '12px', 
          bgcolor: 'rgba(0, 240, 255, 0.08)', 
          color: '#38bdf8',
          border: '1px solid rgba(0, 240, 255, 0.2)',
          '& .MuiAlert-icon': { color: '#00f0ff' } 
        }}
      >
        <Typography variant="subtitle2" sx={{ fontWeight: 'bold', mb: 0.25 }}>
          🔄 Peer-to-Peer Catalog Sync &amp; Instance Replication
        </Typography>
        <Typography variant="caption" sx={{ display: 'block', opacity: 0.9, lineHeight: 1.4 }}>
          P2P Sync allows multiple isolated Voyarr nodes to securely exchange scraper recipes, reconcile library metadata, and mirror provider configurations over encrypted peer-to-peer tokens.
        </Typography>
      </Alert>

      {/* Nodes list dashboard */}
      <Typography variant="h5" fontWeight="700" sx={{ mb: 2, display: 'flex', alignItems: 'center', gap: 1 }}>
        <Box sx={{ color: 'primary.main', display: 'flex' }}><Wifi size={24} /></Box> Peer Connections
      </Typography>

      {loading && nodes.length === 0 ? (
        <Box sx={{ display: 'flex', justifyContent: 'center', py: 5 }}>
          <CircularProgress color="primary" />
        </Box>
      ) : nodes.length === 0 ? (
        <Paper sx={{
          p: 5,
          textAlign: 'center',
          borderRadius: '20px',
          background: 'rgba(255,255,255,0.02)',
          border: '1px dashed rgba(255,255,255,0.1)',
          mb: 4
        }}>
          <Box sx={{ color: 'text.secondary', display: 'flex', justifyContent: 'center', mb: 2 }}>
            <Hourglass size={50} />
          </Box>
          <Typography variant="h6" color="text.secondary">No trusted peers registered yet</Typography>
          <Typography variant="body2" color="text.secondary" sx={{ mt: 1, mb: 3 }}>
            Register Voyarr installations on other devices to begin sharing metadata.
          </Typography>
          <Button variant="outlined" startIcon={<Plus size={20} />} onClick={handleOpenCreate}>
            Register Your First Peer
          </Button>
        </Paper>
      ) : (
        <Grid container spacing={3} sx={{ mb: 5 }}>
          {nodes.map(node => (
            <Grid xs={12} key={node.id}>
              <Card sx={{
                background: 'rgba(30, 30, 30, 0.4)',
                backdropFilter: 'blur(20px)',
                border: '1px solid rgba(255,255,255,0.06)',
                borderRadius: '20px',
                position: 'relative',
                overflow: 'visible',
                transition: 'all 0.3s ease',
                '&:hover': {
                  borderColor: node.status === 'active' ? 'rgba(0, 240, 255, 0.3)' : node.status === 'error' ? 'rgba(255, 0, 127, 0.3)' : 'rgba(255,255,255,0.15)',
                  boxShadow: node.status === 'active' ? '0 0 20px rgba(0, 240, 255, 0.1)' : '0 4px 20px rgba(0,0,0,0.2)'
                }
              }}>
                <CardContent>
                  <Grid container spacing={2} sx={{ alignItems: 'center' }}>
                    <Grid xs={12} sm={4}>
                      <Box sx={{ display: 'flex', alignItems: 'center', gap: 1.5 }}>
                        <Typography variant="h6" fontWeight="700">{node.name}</Typography>
                        <Chip
                          size="small"
                          label={node.status.toUpperCase()}
                          color={getStatusChipColor(node.status)}
                          icon={node.status === 'syncing' ? <CircularProgress size={12} /> : undefined}
                        />
                      </Box>
                      <Typography variant="body2" color="text.secondary" noWrap sx={{ mt: 0.5 }}>
                        {node.peer_url}
                      </Typography>
                    </Grid>

                    <Grid xs={12} sm={5}>
                      <Grid container spacing={1}>
                        <Grid xs={6}>
                          <Typography variant="caption" color="text.secondary" display="block">Recipe Sync Mode</Typography>
                          <Typography variant="body2" fontWeight="500">
                            {node.recipe_sync_mode === 'auto_merge' ? 'Auto-Merge Selectors' : 'Hold for Review'}
                          </Typography>
                        </Grid>
                        <Grid xs={6}>
                          <Typography variant="caption" color="text.secondary" display="block">Sync Scope</Typography>
                          <Typography variant="body2" fontWeight="500">
                            {node.library_scope === 'all_entries' ? 'All Catalog Data' : `Restricted (${node.allowed_providers?.length || 0} providers)`}
                          </Typography>
                        </Grid>
                        <Grid xs={6} sx={{ mt: 1 }}>
                          <Typography variant="caption" color="text.secondary" display="block">Sync Schedule</Typography>
                          <Typography variant="body2" fontWeight="500" sx={{ textTransform: 'capitalize' }}>
                            {node.sync_schedule}
                          </Typography>
                        </Grid>
                        <Grid xs={6} sx={{ mt: 1 }}>
                          <Typography variant="caption" color="text.secondary" display="block">Last Synced</Typography>
                          <Typography variant="body2" fontWeight="500">
                            {node.last_sync_at ? new Date(node.last_sync_at).toLocaleString() : 'Never'}
                          </Typography>
                        </Grid>
                      </Grid>
                    </Grid>

                    <Grid xs={12} sm={3} sx={{ display: 'flex', justifyContent: { xs: 'flex-start', sm: 'flex-end' }, gap: 1 }}>
                      <IconButton color="primary" onClick={() => handleTestConnection(node.id)} disabled={testingNodes[node.id]} title="Verify connection">
                        {testingNodes[node.id] ? <CircularProgress size={20} /> : <Wifi size={20} />}
                      </IconButton>
                      <IconButton color="info" onClick={() => handleTriggerSync(node.id, node.name)} disabled={syncingNodes[node.id] || node.status === 'syncing'} title="Trigger synchronization now">
                        {syncingNodes[node.id] ? <CircularProgress size={20} /> : <RefreshCw size={20} />}
                      </IconButton>
                      <IconButton color="warning" onClick={() => handleOpenEdit(node)} title="Edit configuration">
                        <Edit2 size={20} />
                      </IconButton>
                      <IconButton color="error" onClick={() => handleDeleteNode(node.id, node.name)} title="Remove trusted peer">
                        <Trash2 size={20} />
                      </IconButton>
                    </Grid>
                  </Grid>
                </CardContent>

                <Divider />

                <CardActions sx={{ px: 2, py: 1, display: 'flex', justifyContent: 'space-between' }}>
                  <Button
                    size="small"
                    startIcon={<History size={18} />}
                    endIcon={expandedLogs[node.id] ? <ChevronUp size={20} /> : <ChevronDown size={20} />}
                    onClick={() => toggleLogs(node.id)}
                  >
                    Sync Log History
                  </Button>

                  {node.next_run && (
                    <Typography variant="caption" color="text.secondary">
                      Next Automated Run: {new Date(node.next_run).toLocaleString()}
                    </Typography>
                  )}
                </CardActions>

                {/* Logs Expansion console */}
                <Collapse in={expandedLogs[node.id]}>
                  <Box sx={{ p: 2, background: 'rgba(0,0,0,0.15)', borderBottomLeftRadius: '20px', borderBottomRightRadius: '20px' }}>
                    <Typography variant="subtitle2" fontWeight="bold" sx={{ mb: 1 }}>Recent Sync Runs</Typography>

                    {!nodeLogs[node.id] ? (
                      <Box sx={{ display: 'flex', justifyContent: 'center', py: 2 }}>
                        <CircularProgress size={20} />
                      </Box>
                    ) : nodeLogs[node.id].length === 0 ? (
                      <Typography variant="body2" color="text.secondary" sx={{ py: 1 }}>No sync history logged yet.</Typography>
                    ) : (
                    <TableContainer component={Paper} sx={{ maxHeight: 200, background: 'transparent', boxShadow: 'none', overflowX: 'auto' }}>
                        <Table size="small" stickyHeader>
                          <TableHead>
                            <TableRow>
                            <TableCell align="center" sx={{ background: '#1e1e1e', whiteSpace: 'nowrap' }}>Run Time</TableCell>
                            <TableCell align="center" sx={{ background: '#1e1e1e', whiteSpace: 'nowrap' }}>Direction</TableCell>
                            <TableCell align="center" sx={{ background: '#1e1e1e', whiteSpace: 'nowrap' }}>Recipes</TableCell>
                            <TableCell align="center" sx={{ background: '#1e1e1e', whiteSpace: 'nowrap' }}>Media Reconciled</TableCell>
                            <TableCell align="center" sx={{ background: '#1e1e1e', whiteSpace: 'nowrap' }}>Status</TableCell>
                            <TableCell align="center" sx={{ background: '#1e1e1e', whiteSpace: 'nowrap' }}>Details</TableCell>
                            </TableRow>
                          </TableHead>
                          <TableBody>
                            {nodeLogs[node.id].map(log => (
                              <TableRow key={log.id}>
                              <TableCell align="center" sx={{ whiteSpace: 'nowrap' }}>{new Date(log.created_at).toLocaleString()}</TableCell>
                              <TableCell align="center" sx={{ textTransform: 'uppercase', whiteSpace: 'nowrap' }}>{log.direction}</TableCell>
                              <TableCell align="center" sx={{ whiteSpace: 'nowrap' }}>{log.recipes_synced}</TableCell>
                              <TableCell align="center" sx={{ whiteSpace: 'nowrap' }}>{log.media_synced}</TableCell>
                              <TableCell align="center" sx={{ whiteSpace: 'nowrap' }}>
                                  <Chip
                                    size="small"
                                    label={log.status.toUpperCase()}
                                    color={log.status === 'success' ? 'success' : 'error'}
                                    variant="outlined"
                                  />
                                </TableCell>
                              <TableCell align="center" sx={{ maxWidth: 200, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                                  {log.error_message || 'OK'}
                                </TableCell>
                              </TableRow>
                            ))}
                          </TableBody>
                        </Table>
                      </TableContainer>
                    )}
                  </Box>
                </Collapse>
              </Card>
            </Grid>
          ))}
        </Grid>
      )}

      {/* Proposed Recipes Queue review panel */}
      <Typography variant="h5" fontWeight="700" sx={{ mb: 2, display: 'flex', alignItems: 'center', gap: 1 }}>
        <Box sx={{ color: 'secondary.main', display: 'flex' }}><History size={24} /></Box> Proposed Recipes Review Queue
      </Typography>

      {proposedRecipes.length === 0 ? (
        <Paper sx={{
          p: 4,
          textAlign: 'center',
          borderRadius: '20px',
          background: 'rgba(255,255,255,0.01)',
          border: '1px solid rgba(255,255,255,0.05)',
          mb: 4
        }}>
          <CheckCircle size={40} color="#10b981" style={{ marginBottom: '8px' }} />
          <Typography variant="subtitle1" fontWeight="bold">Review Queue Empty</Typography>
          <Typography variant="body2" color="text.secondary">
            All pushed selectors from peers have been resolved or auto-merged automatically.
          </Typography>
        </Paper>
      ) : (
        <Grid container spacing={3}>
          {proposedRecipes.map((peerBlock, blockIdx) => (
            <Grid xs={12} key={blockIdx}>
              <Paper sx={{
                p: 3,
                borderRadius: '20px',
                background: 'rgba(40, 30, 40, 0.3)',
                backdropFilter: 'blur(10px)',
                border: '1px solid rgba(255,0,127,0.06)'
              }}>
                <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
                  <Box>
                    <Typography variant="subtitle1" fontWeight="bold">
                      Recipes Pushed by "{peerBlock.peer_name}"
                    </Typography>
                    <Typography variant="caption" color="text.secondary">
                      Received: {new Date(peerBlock.timestamp).toLocaleString()}
                    </Typography>
                  </Box>
                  <Chip size="small" color="secondary" label={`${peerBlock.recipes?.length || 0} recipes pending`} />
                </Box>

                <TableContainer sx={{ overflowX: 'auto' }}>
                  <Table size="small">
                    <TableHead>
                      <TableRow>
                        <TableCell align="center" sx={{ whiteSpace: 'nowrap' }}>Provider</TableCell>
                        <TableCell align="center" sx={{ whiteSpace: 'nowrap' }}>CSS Selectors</TableCell>
