                        <TableCell align="center" sx={{ whiteSpace: 'nowrap' }}>Regex Patterns</TableCell>
                        <TableCell align="center" sx={{ whiteSpace: 'nowrap' }}>Actions</TableCell>
                      </TableRow>
                    </TableHead>
