                  </TableHead>
                  <TableBody>
                    {cookies.filter(c => c.provider_id === activeProvider?.id).length === 0 ? (
                      <TableRow>
                        <TableCell colSpan={3} align="center">No active cookies found.</TableCell>
                      </TableRow>
                    ) : (
                      cookies.filter(c => c.provider_id === activeProvider?.id).map((cookie) => (
                        <TableRow key={cookie.id}>
                      <TableCell align="center" sx={{ whiteSpace: 'nowrap' }}>
                            <Chip 
                              label={cookie.status} 
                              color={cookie.status === 'active' ? 'success' : cookie.status === 'expired' ? 'error' : 'warning'} 
                              size="small" 
                            />
                          </TableCell>
                      <TableCell align="center" sx={{ whiteSpace: 'nowrap' }}>{cookie.downloads_used} / {cookie.download_limit || '∞'}</TableCell>
                      <TableCell align="center" sx={{ whiteSpace: 'nowrap' }}>
                            <IconButton size="small" color="error" onClick={() => handleDeleteCookie(cookie.id)}>
                              <DeleteIcon fontSize="small" />
                            </IconButton>
                          </TableCell>
                        </TableRow>
                      ))
                    )}
                  </TableBody>
                </Table>
              </TableContainer>

              {/* Add Cookie Form */}
              <Typography variant="subtitle2" sx={{ fontWeight: 'bold', mb: 1 }}>
                Add Session Cookie
              </Typography>
              <TextField 
                fullWidth 
                margin="dense" 
                label="Netscape Cookie Text / Token" 
                multiline 
                rows={3} 
                value={cookieText} 
                onChange={e => setCookieText(e.target.value)} 
              />
              <TextField 
                fullWidth 
                margin="dense" 
                type="number" 
                label="Max Downloads Limit (Optional)" 
                value={cookieLimit} 
                onChange={e => setCookieLimit(e.target.value)} 
              />
              <Box sx={{ display: 'flex', justifyContent: 'flex-end', mt: 2 }}>
                <Button 
                  onClick={handleAddCookie} 
                  variant="contained" 
                  color="primary"
                  startIcon={<AddIcon />}
                  disabled={!cookieText}
                >
                  Add Cookie
                </Button>
              </Box>
            </Box>
          )}
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setOpenDialog(false)}>Cancel</Button>
          {dialogTab === 0 && (
            <Button onClick={handleSaveProvider} variant="contained" color="secondary">
              {providerFormId ? 'Save Details' : 'Create Provider'}
            </Button>
          )}
        </DialogActions>
      </Dialog>

      {/* Logo Crop & Autofit Dialog Modal */}
      <Dialog open={openLogoEditor} onClose={() => setOpenLogoEditor(false)} maxWidth="xs" fullWidth>
        <DialogTitle sx={{ fontWeight: 'bold' }}>Logo Crop & Pad Editor</DialogTitle>
        <DialogContent dividers sx={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 2 }}>
          <Typography variant="body2" color="text.secondary" sx={{ textAlign: 'center' }}>
            Drag the image to center/pan, and use the controls below to resize and pad your logo into a perfect square.
          </Typography>
          <Box sx={{ position: 'relative', width: 300, height: 300, bgcolor: 'action.hover', borderRadius: 2, overflow: 'hidden' }}>
            <canvas 
              id="logo-editor-canvas" 
              width={300} 
              height={300} 
              onMouseDown={handleCanvasMouseDown}
              onMouseMove={handleCanvasMouseMove}
              onMouseUp={handleCanvasMouseUp}
              onMouseLeave={handleCanvasMouseUp}
              style={{ cursor: isDragging ? 'grabbing' : 'grab', display: 'block' }}
            />
          </Box>
          <Box sx={{ width: '100%', display: 'flex', flexDirection: 'column', gap: 1.5, mt: 1 }}>
            <Box>
              <Typography variant="caption" sx={{ fontWeight: 'bold' }}>Zoom / Scale ({logoScale}%)</Typography>
              <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
                <span style={{ fontSize: '0.8rem' }}>➖</span>
                <input 
                  type="range" 
                  min="10" 
                  max="200" 
                  value={logoScale} 
                  onChange={(e) => setLogoScale(Number(e.target.value))} 
                  style={{ flexGrow: 1 }}
                />
                <span style={{ fontSize: '0.8rem' }}>➕</span>
              </Box>
            </Box>
            <Box>
              <Typography variant="caption" sx={{ fontWeight: 'bold' }}>Transparent Padding ({logoPadding}%)</Typography>
              <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
                <span style={{ fontSize: '0.8rem' }}>🔲</span>
                <input 
                  type="range" 
                  min="0" 
                  max="80" 
                  value={logoPadding} 
                  onChange={(e) => setLogoPadding(Number(e.target.value))} 
                  style={{ flexGrow: 1 }}
                />
                <span style={{ fontSize: '0.8rem' }}>🔳</span>
              </Box>
            </Box>
          </Box>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => {
            setLogoScale(100)
            setLogoPadding(20)
            setLogoOffset({ x: 0, y: 0 })
          }} color="warning">Reset</Button>
          <Button onClick={() => setOpenLogoEditor(false)}>Cancel</Button>
          <Button onClick={handleApplyLogoEdit} variant="contained" color="primary">Apply</Button>
        </DialogActions>
      </Dialog>

      {/* Provider Create Modal */}
      <Dialog open={openProviderForm} onClose={() => setOpenProviderForm(false)} maxWidth="sm" fullWidth>
        <DialogTitle sx={{ fontWeight: 'bold' }}>
          Create Provider
        </DialogTitle>
        <DialogContent dividers>
          {renderProviderFormDetails(true)}
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setOpenProviderForm(false)}>Cancel</Button>
          <Button onClick={handleSaveProvider} variant="contained" color="secondary">
            Create Provider
          </Button>
        </DialogActions>
      </Dialog>
    </Box>
  )
}

import { useState, useEffect } from 'react'
import { Box, Typography, Tabs, Tab, TextField, Button, IconButton, Divider, CircularProgress, Alert, Paper } from '@mui/material'
import { Plus, Trash2, Save, TestTube, Copy } from 'lucide-react'
import GlassCard from './common/GlassCard'
import { apiFetch } from '../api'

const GROUPS = ['css_selectors', 'xpath_selectors', 'regex_patterns', 'map_mode_data']
const GROUP_LABELS = {
  css_selectors: 'CSS Selectors',
  xpath_selectors: 'XPath Selectors',
  regex_patterns: 'Regex Patterns',
  map_mode_data: 'Map Mode Data',
}

function SelectorGroup({ group, selectors, onChange }) {
  const entries = Object.entries(selectors || {})

  const update = (key, newKey, value) => {
    const next = { ...(selectors || {}) }
    if (key !== undefined) delete next[key]
    if (newKey) next[newKey] = value || ''
    onChange(group, next)
  }

  return (
    <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1 }}>
      {entries.length === 0 && (
        <Typography variant="caption" sx={{ color: 'rgba(255,255,255,0.3)', textAlign: 'center', py: 3 }}>
          No {GROUP_LABELS[group].toLowerCase()} defined.
        </Typography>
      )}
      {entries.map(([key, val]) => (
        <Box key={key} sx={{ display: 'flex', gap: 1, alignItems: 'center' }}>
          <TextField size="small" placeholder="Field name" value={key}
            onChange={e => { const v = e.target.value; delete selectors[key]; update(undefined, v, val) }}
            sx={{ minWidth: 140, '& .MuiOutlinedInput-root': { borderRadius: '8px', fontSize: '0.78rem' } }} />
          <TextField size="small" placeholder="Selector / pattern" value={String(val || '')}
            onChange={e => update(key, key, e.target.value)}
            sx={{ flex: 1, '& .MuiOutlinedInput-root': { borderRadius: '8px', fontSize: '0.78rem', fontFamily: 'monospace' } }} />
          <IconButton size="small" onClick={() => update(key, undefined, undefined)}
            sx={{ color: 'rgba(255,255,255,0.3)', '&:hover': { color: '#ef4444' } }}>
            <Trash2 size={14} />
          </IconButton>
        </Box>
      ))}
      <Button size="small" variant="text" startIcon={<Plus size={14} />} onClick={() => update(undefined, '', '')}
        sx={{ alignSelf: 'flex-start', borderRadius: '8px', textTransform: 'none', fontSize: '0.75rem', mt: 0.5 }}>
        Add {GROUP_LABELS[group].toLowerCase()} rule
      </Button>
    </Box>
  )
}

export default function RecipeEditor({ providerId, recipe, onSave }) {
  const [tab, setTab] = useState(0)
  const [data, setData] = useState({
    css_selectors: null,
    xpath_selectors: null,
    regex_patterns: null,
    map_mode_data: null,
  })
  const [saving, setSaving] = useState(false)
  const [saved, setSaved] = useState(false)
  const [testUrl, setTestUrl] = useState('')
  const [testResult, setTestResult] = useState(null)
  const [testing, setTesting] = useState(false)

  useEffect(() => {
    if (recipe) {
      setData({
        css_selectors: recipe.css_selectors || null,
        xpath_selectors: recipe.xpath_selectors || null,
        regex_patterns: recipe.regex_patterns || null,
        map_mode_data: recipe.map_mode_data || null,
      })
    }
  }, [recipe])

  const handleUpdate = (group, value) => {
    setData(d => ({ ...d, [group]: value && Object.keys(value).length > 0 ? value : null }))
    setSaved(false)
  }

  const handleSave = async () => {
    setSaving(true)
    try {
      const body = {}
      for (const g of GROUPS) {
        if (data[g] !== null) body[g] = data[g]
      }
      await apiFetch(`/scraper/by-provider/${providerId}`, { method: 'PUT', body })
      setSaved(true)
      if (onSave) onSave()
    } catch (e) {}
    setSaving(false)
  }

  const handleTest = async () => {
    if (!testUrl.trim()) return
    setTesting(true)
    setTestResult(null)
    try {
      const res = await apiFetch('/scraper/parse-url', { method: 'POST', body: { url: testUrl.trim() } })
      setTestResult(await res.json())
    } catch (e) {
      setTestResult({ error: e.message || 'Test failed' })
    }
    setTesting(false)
  }

  const handleCopyJson = () => {
    const payload = {}
    for (const g of GROUPS) {
      if (data[g]) payload[g] = data[g]
    }
    navigator.clipboard.writeText(JSON.stringify(payload, null, 2))
  }

  if (!providerId) {
    return (
      <GlassCard sx={{ p: 4, textAlign: 'center' }}>
        <Typography color="text.secondary">Select a provider to manage its scraping recipe.</Typography>
      </GlassCard>
    )
  }

  return (
    <GlassCard>
      <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', mb: 2 }}>
        <Typography variant="h6" sx={{ fontWeight: '700' }}>
          Recipe — Provider #{providerId}
          {recipe ? ` (ID: ${recipe.id})` : ' (not yet created)'}
        </Typography>
        <Box sx={{ display: 'flex', gap: 1 }}>
          <Button size="small" variant="outlined" startIcon={<Copy size={14} />} onClick={handleCopyJson}
            sx={{ borderRadius: '8px', textTransform: 'none', fontSize: '0.75rem' }}>
            Copy JSON
          </Button>
          <Button size="small" variant="contained" startIcon={saving ? <CircularProgress size={14} /> : <Save size={14} />}
            onClick={handleSave} disabled={saving}
            sx={{ borderRadius: '8px', textTransform: 'none', fontSize: '0.75rem', fontWeight: 'bold' }}>
            {saving ? 'Saving...' : saved ? 'Saved!' : 'Save'}
          </Button>
        </Box>
      </Box>

      <Divider sx={{ borderColor: 'rgba(255,255,255,0.08)', mb: 2 }} />

      <Tabs value={tab} onChange={(e, v) => setTab(v)}
        sx={{ mb: 2, '& .MuiTab-root': { textTransform: 'none', fontWeight: 600, fontSize: '0.78rem', minHeight: 36 } }}>
        {GROUPS.map(g => <Tab key={g} label={GROUP_LABELS[g]} />)}
      </Tabs>

      {GROUPS.map((g, i) => (
        <Box key={g} sx={{ display: tab === i ? 'block' : 'none' }}>
          <SelectorGroup group={g} selectors={data[g]} onChange={handleUpdate} />
        </Box>
      ))}

      <Divider sx={{ borderColor: 'rgba(255,255,255,0.08)', my: 2 }} />

      {/* Test section */}
      <Typography variant="subtitle2" sx={{ fontWeight: '600', mb: 1, color: 'rgba(255,255,255,0.6)' }}>
        🧪 Test Recipe
      </Typography>
      <Box sx={{ display: 'flex', gap: 1, alignItems: 'center' }}>
        <TextField size="small" placeholder="https://example.com/video-page" value={testUrl}
          onChange={e => setTestUrl(e.target.value)}
          sx={{ flex: 1, '& .MuiOutlinedInput-root': { borderRadius: '8px' } }} />
        <Button size="small" variant="outlined" startIcon={testing ? <CircularProgress size={14} /> : <TestTube size={14} />}
          onClick={handleTest} disabled={testing || !testUrl.trim()}
          sx={{ borderRadius: '8px', textTransform: 'none', fontSize: '0.75rem' }}>
          Test
        </Button>
      </Box>
      {testResult && (
        <Paper sx={{ mt: 1.5, p: 1.5, borderRadius: '8px', bgcolor: 'rgba(0,0,0,0.3)', border: '1px solid rgba(255,255,255,0.08)', maxHeight: 300, overflow: 'auto' }}>
          <Typography variant="caption" sx={{ fontFamily: 'monospace', fontSize: '0.65rem', color: 'rgba(255,255,255,0.7)', whiteSpace: 'pre-wrap', wordBreak: 'break-all' }}>
            {JSON.stringify(testResult, null, 2)}
          </Typography>
        </Paper>
      )}
    </GlassCard>
  )
}

import { useState, useEffect, useCallback } from 'react'
import {
  Box, Typography, Table, TableBody, TableCell, TableContainer,
  TableHead, TableRow, Button, IconButton, Dialog, DialogTitle,
  DialogContent, DialogActions, TextField, MenuItem, Select, FormControl,
  InputLabel, Grid, Chip, Snackbar, Alert, CircularProgress
} from '@mui/material'
import { apiFetch } from '../api'
import GlassCard from './common/GlassCard'

const inputSx = { '& .MuiOutlinedInput-root': { borderRadius: '10px' } }
const accentSx = { bgcolor: 'rgba(99,102,241,0.06)', border: '1px solid rgba(99,102,241,0.2)', borderRadius: '12px', p: 2 }

export default function RequestManager({ userRole }) {
  const isAdmin = userRole === 'admin'
  const [requests, setRequests] = useState([])
  const [providers, setProviders] = useState([])
  const [newRequest, setNewRequest] = useState({ title: '', url: '' })

  const [openApproveDialog, setOpenApproveDialog] = useState(false)
  const [selectedReq, setSelectedReq] = useState(null)
  const [selectedProviderId, setSelectedProviderId] = useState('')

  const [loading, setLoading] = useState(false)
  const [snackbar, setSnackbar] = useState({ open: false, message: '', severity: 'success' })

  const fetchRequests = useCallback(async () => {
    try {
      const res = await apiFetch('/requests')
      if (res.ok) setRequests(await res.json())
    } catch (error) {
      console.error('Failed to fetch requests:', error)
    }
  }, [])

  const fetchProviders = useCallback(async () => {
    try {
      const res = await apiFetch('/providers')
      if (res.ok) setProviders(await res.json())
    } catch (error) {
      console.error('Failed to fetch providers:', error)
    }
  }, [])

  useEffect(() => {
    fetchRequests()
    if (isAdmin) fetchProviders()
  }, [fetchRequests, fetchProviders, isAdmin])

  const handleSubmitRequest = async (e) => {
    e.preventDefault()
    if (!newRequest.title.trim()) {
      setSnackbar({ open: true, message: 'Please enter a title', severity: 'error' })
      return
    }
    setLoading(true)
    try {
      const res = await apiFetch('/requests', {
        method: 'POST', body: JSON.stringify(newRequest)
      })
      if (res.ok) {
        setNewRequest({ title: '', url: '' })
        setSnackbar({ open: true, message: 'Media request submitted!', severity: 'success' })
        fetchRequests()
      } else {
        const data = await res.json()
        setSnackbar({ open: true, message: `Failed: ${data.detail || res.statusText}`, severity: 'error' })
      }
    } catch (error) {
      setSnackbar({ open: true, message: `Error: ${error.message}`, severity: 'error' })
    }
    setLoading(false)
  }

  const handleOpenApprove = (req) => {
    setSelectedReq(req)
    if (providers.length > 0) setSelectedProviderId(providers[0].id)
    setOpenApproveDialog(true)
  }

  const handleApprove = async () => {
    if (!selectedProviderId) {
      setSnackbar({ open: true, message: 'Select a provider', severity: 'error' })
      return
    }
    setLoading(true)
    try {
      const res = await apiFetch(`/requests/${selectedReq.id}/approve?provider_id=${selectedProviderId}`, { method: 'POST' })
      if (res.ok) {
        setSnackbar({ open: true, message: 'Request approved and queued!', severity: 'success' })
        setOpenApproveDialog(false)
        fetchRequests()
      } else {
        const data = await res.json()
        setSnackbar({ open: true, message: `Approval failed: ${data.detail || res.statusText}`, severity: 'error' })
      }
    } catch (error) {
      setSnackbar({ open: true, message: `Error: ${error.message}`, severity: 'error' })
    }
    setLoading(false)
  }

  const handleReject = async (id) => {
    const confirmed = await window.appConfirm('Reject this request?')
    if (!confirmed) return
    setLoading(true)
    try {
      const res = await apiFetch(`/requests/${id}`, { method: 'DELETE' })
      if (res.ok) {
        setSnackbar({ open: true, message: 'Request rejected.', severity: 'info' })
        fetchRequests()
      } else {
        setSnackbar({ open: true, message: 'Failed to reject.', severity: 'error' })
      }
    } catch (error) {
      setSnackbar({ open: true, message: `Error: ${error.message}`, severity: 'error' })
    }
    setLoading(false)
  }

  const getStatusColor = (status) => {
    switch (status) {
      case 'approved': return 'info'
      case 'downloaded': return 'success'
      case 'rejected': return 'error'
      default: return 'warning'
    }
  }

  return (
    <Box sx={{ maxWidth: 1400, mx: 'auto', width: '100%' }}>
      <Typography variant="h4" sx={{ fontWeight: '800', letterSpacing: '-0.5px', mb: 3 }}>
        Media Requests Portal
      </Typography>

      <Alert severity="info" sx={{ mb: 3, borderRadius: '12px', bgcolor: 'rgba(99,102,241,0.08)', color: '#a5b4fc', border: '1px solid rgba(99,102,241,0.2)', '& .MuiAlert-icon': { color: '#818cf8' } }}>
        <Typography variant="subtitle2" sx={{ fontWeight: 'bold', mb: 0.25 }}>🎯 Media Request Hub</Typography>
        <Typography variant="caption" sx={{ display: 'block', opacity: 0.9, lineHeight: 1.4 }}>
          Submit requests for media you want added to your library. Administrators can approve, reject, and queue requests for automatic download.
        </Typography>
      </Alert>

      <Grid container spacing={3} sx={{ mb: 4 }}>
        <Grid xs={12} md={4}>
          <GlassCard>
            <Typography variant="h6" sx={{ fontWeight: '700', mb: 2 }}>Submit Media Request</Typography>
            <Box sx={{ ...accentSx, mb: 2 }}>
              <Typography variant="body2" color="textSecondary" sx={{ mb: 2 }}>
                Can't find a video or channel? Paste the source URL below to request it for scanning and ripping.
              </Typography>
            </Box>
            <Box component="form" onSubmit={handleSubmitRequest} sx={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
              <TextField fullWidth label="Title / Channel Name" required value={newRequest.title} onChange={(e) => setNewRequest({ ...newRequest, title: e.target.value })} sx={inputSx} />
              <TextField fullWidth label="Source URL (e.g. OnlyFans/Fansly link)" placeholder="https://..." value={newRequest.url} onChange={(e) => setNewRequest({ ...newRequest, url: e.target.value })} sx={inputSx} />
              <Button type="submit" variant="contained" fullWidth disabled={loading} sx={{ mt: 1, borderRadius: '10px', textTransform: 'none', fontWeight: 'bold' }}>
                {loading ? <CircularProgress size={24} /> : 'Submit Request'}
              </Button>
            </Box>
          </GlassCard>
        </Grid>

        <Grid xs={12} md={8}>
          <GlassCard>
            <Typography variant="h6" sx={{ fontWeight: '700', mb: 2 }}>
              {isAdmin ? 'Centralized Approval Dashboard' : 'Your Requested Media'}
            </Typography>
            <TableContainer component={Paper} variant="outlined" sx={{ mt: 2, borderRadius: '12px', bgcolor: 'rgba(255,255,255,0.03)', border: '1px solid rgba(255,255,255,0.08)' }}>
              <Table size="small">
                <TableHead>
                  <TableRow>
                    <TableCell sx={{ fontWeight: 'bold' }}>Title</TableCell>
                    <TableCell sx={{ fontWeight: 'bold' }}>Requested By</TableCell>
                    <TableCell sx={{ fontWeight: 'bold' }}>Status</TableCell>
                    <TableCell sx={{ fontWeight: 'bold' }}>Actions</TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {requests.map((req) => (
                    <TableRow key={req.id} sx={{ '&:hover': { bgcolor: 'rgba(99,102,241,0.06)' } }}>
                      <TableCell>
                        <Typography variant="subtitle2" sx={{ display: 'inline' }}>{req.title}</Typography>
                        {req.url && (
                          <Typography variant="caption" sx={{ ml: 1 }}>
                            <a href={req.url} target="_blank" rel="noreferrer" style={{ textDecoration: 'none', color: '#818cf8' }}>(Source Link)</a>
                          </Typography>
                        )}
                      </TableCell>
                      <TableCell>{req.requested_by || 'Anonymous'}</TableCell>
                      <TableCell>
                        <Chip size="small" label={req.status ? req.status.toUpperCase() : 'PENDING'} color={getStatusColor(req.status)} sx={{ fontWeight: 'bold', fontSize: '0.65rem' }} />
                      </TableCell>
                      <TableCell>
                        {isAdmin && (req.status === 'pending' || !req.status) ? (
                          <Box sx={{ display: 'flex', gap: 1 }}>
                            <Button variant="contained" color="success" size="small" onClick={() => handleOpenApprove(req)} sx={{ borderRadius: '8px', textTransform: 'none', fontSize: '0.75rem' }}>
                              Approve
                            </Button>
                            <Button variant="outlined" color="error" size="small" onClick={() => handleReject(req.id)} sx={{ borderRadius: '8px', textTransform: 'none', fontSize: '0.75rem' }}>
                              Reject
                            </Button>
                          </Box>
                        ) : (
                          <Typography variant="caption" color="textSecondary">
                            {req.status === 'approved' ? 'Queued for rip' : req.status === 'downloaded' ? 'Ready!' : 'No actions'}
                          </Typography>
                        )}
                      </TableCell>
                    </TableRow>
                  ))}
                  {requests.length === 0 && (
                    <TableRow>
                      <TableCell colSpan={4} align="center" sx={{ py: 3 }}>
                        <Typography color="text.secondary">No media requests found.</Typography>
                      </TableCell>
                    </TableRow>
                  )}
                </TableBody>
              </Table>
            </TableContainer>
          </GlassCard>
        </Grid>
      </Grid>

      <Dialog open={openApproveDialog} onClose={() => setOpenApproveDialog(false)} maxWidth="xs" fullWidth slotProps={{ paper: { sx: { borderRadius: '12px', bgcolor: 'rgba(15,23,42,0.95)', backdropFilter: 'blur(16px)', border: '1px solid rgba(255,255,255,0.1)' } } }}>
        <DialogTitle sx={{ fontWeight: 'bold' }}>Approve & Queue Media</DialogTitle>
        <DialogContent dividers>
          <Typography variant="body2" sx={{ mb: 2, color: 'rgba(255,255,255,0.7)' }}>
            Select the provider to trigger automatic scraping and download.
          </Typography>
          <FormControl fullWidth>
            <InputLabel>Provider</InputLabel>
            <Select value={selectedProviderId} label="Provider" onChange={(e) => setSelectedProviderId(e.target.value)} sx={{ borderRadius: '10px' }}>
              {providers.map((p) => (
                <MenuItem key={p.id} value={p.id}>{p.name} ({p.base_url})</MenuItem>
              ))}
            </Select>
          </FormControl>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setOpenApproveDialog(false)} sx={{ borderRadius: '8px', textTransform: 'none' }}>Cancel</Button>
          <Button variant="contained" color="success" onClick={handleApprove} disabled={loading} sx={{ borderRadius: '8px', textTransform: 'none' }}>
            {loading ? <CircularProgress size={20} /> : 'Approve & Rip'}
          </Button>
        </DialogActions>
      </Dialog>

      <Snackbar open={snackbar.open} autoHideDuration={6000} onClose={() => setSnackbar({ ...snackbar, open: false })} anchorOrigin={{ vertical: 'bottom', horizontal: 'center' }}>
        <Alert severity={snackbar.severity} onClose={() => setSnackbar({ ...snackbar, open: false })} sx={{ borderRadius: '10px' }}>
          {snackbar.message}
        </Alert>
      </Snackbar>
    </Box>
  )
}

import { useState, useEffect, useRef } from 'react'
import { Box, Typography, LinearProgress, Tooltip, Paper, Chip, CircularProgress } from '@mui/material'
import { apiFetch } from '../api'

const SCAN_API_BASE = import.meta.env.VITE_API_BASE || '/api'

export default function ScannerProgress({ taskId, onComplete }) {
  const [progress, setProgress] = useState(0)
  const [step, setStep] = useState('')
  const [currentFile, setCurrentFile] = useState('')
  const [scanned, setScanned] = useState(0)
  const [total, setTotal] = useState(0)
  const [status, setStatus] = useState('pending')
  const [result, setResult] = useState(null)
  const esRef = useRef(null)

  const getAuthQuery = () => {
    const token = localStorage.getItem('voyarr_jwt')
    if (token) return `token=${encodeURIComponent(token)}`
    let apiKey = localStorage.getItem('voyarr_api_key')
    if (apiKey) { try { apiKey = atob(apiKey) } catch {} }
    return `api_key=${encodeURIComponent(apiKey || '')}`
  }

  useEffect(() => {
    if (!taskId) return
    const es = new EventSource(`${SCAN_API_BASE}/external-api/library/scan/stream/${taskId}?${getAuthQuery()}`)
    esRef.current = es

    es.onmessage = (event) => {
      try {
        const data = JSON.parse(event.data)
        if (data.status === 'success') {
          setProgress(100)
          setStep('Complete')
          setStatus('success')
          setResult(data.result || {})
          es.close()
          if (onComplete) onComplete(data.result)
        } else if (data.status === 'failed') {
          setStatus('failed')
          setStep('Failed')
          es.close()
          if (onComplete) onComplete(null)
        } else {
          setStatus(data.status || 'running')
          if (data.progress !== undefined) setProgress(data.progress)
          if (data.step) setStep(data.step)
          if (data.current_file) setCurrentFile(data.current_file)
          if (data.scanned !== undefined) setScanned(data.scanned)
          if (data.total !== undefined) setTotal(data.total)
        }
      } catch {}
    }

    es.onerror = () => {}

    return () => { es.close() }
  }, [taskId])

  if (!taskId) return null

  const tooltipContent = (
    <Box sx={{ fontSize: '0.8rem' }}>
      {step && <div>{step}</div>}
      {currentFile && <div style={{ opacity: 0.7, fontFamily: 'monospace', fontSize: '0.75rem' }}>{currentFile}</div>}
      {total > 0 && <div style={{ marginTop: 4 }}>{scanned} / {total} files</div>}
    </Box>
  )

  return (
    <Paper sx={{ p: 2, mb: 2, borderRadius: '12px', background: 'rgba(99,102,241,0.06)', border: '1px solid rgba(99,102,241,0.2)' }}>
      <Box sx={{ display: 'flex', alignItems: 'center', gap: 1.5, mb: 1 }}>
        {status !== 'success' && status !== 'failed' ? (
          <CircularProgress size={18} color="primary" />
        ) : status === 'success' ? (
          <Chip label="Complete" color="success" size="small" />
        ) : (
          <Chip label="Failed" color="error" size="small" />
        )}
        <Typography variant="subtitle2" sx={{ fontWeight: 'bold' }}>Library Scan</Typography>
        <Typography variant="caption" color="text.secondary" sx={{ ml: 'auto' }}>{progress}%</Typography>
      </Box>
      <Tooltip title={tooltipContent} placement="bottom">
        <LinearProgress
          variant={progress > 0 && progress < 100 ? 'determinate' : 'indeterminate'}
          value={progress > 0 ? progress : undefined}
          sx={{ height: 6, borderRadius: 3 }}
        />
      </Tooltip>
      {step && (
        <Typography variant="caption" color="text.secondary" sx={{ display: 'block', mt: 0.5, fontStyle: 'italic' }}>
          {step}
        </Typography>
      )}
      {result && result.processed_files !== undefined && (
        <Typography variant="caption" color="success.main" sx={{ display: 'block', mt: 0.5, fontWeight: 'bold' }}>
          Processed {result.processed_files} new file(s)
        </Typography>
      )}
    </Paper>
  )
}

import React, { useState, useEffect, useCallback } from 'react';
import { 
  Box, Typography, Paper, TextField, Button, Grid,
  Table, TableBody, TableCell, TableContainer, TableHead, TableRow,
  IconButton, Chip, FormControl, InputLabel, Select, MenuItem, Switch, FormControlLabel, Tooltip, Snackbar, Alert, Dialog, DialogTitle, DialogContent, DialogActions, Autocomplete
} from '@mui/material';
import DeleteIcon from '@mui/icons-material/Delete';
import PlayArrowIcon from '@mui/icons-material/PlayArrow';
import { apiFetch } from '../api';

export default function ScheduleManager() {
  const [schedules, setSchedules] = useState([]);
  const [providers, setProviders] = useState([]);
  const [formData, setFormData] = useState({
    name: '',
    provider_id: '',
    target_url: '',
    cron_expression: '0 0 * * *',
    action: 'metadata_and_download',
    is_active: true
  });
  const [snackbar, setSnackbar] = useState({ open: false, message: '', severity: 'success' });
  const [deleteConfirm, setDeleteConfirm] = useState({ open: false, scheduleId: null });
  const [scrapingEnabled, setScrapingEnabled] = useState(true);

  const fetchData = useCallback(async () => {
    try {
      const [schedRes, provRes] = await Promise.all([
        apiFetch('/schedules'),
        apiFetch('/providers')
      ]);
      if (schedRes.ok) setSchedules(await schedRes.json());
      if (provRes.ok) setProviders(await provRes.json());

      // Check global scraping setting
      const settingsRes = await apiFetch('/settings');
      if (settingsRes.ok) {
        const settings = await settingsRes.json();
        if (settings && settings.scraping_enabled === 'false') {
          setScrapingEnabled(false);
        }
      }
    } catch (e) {
      console.error('Failed to fetch data:', e);
    }
  }, []);

  useEffect(() => {
    fetchData();
  }, [fetchData]);

  const handleChange = (e) => {
    const { name, value, checked, type } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: type === 'checkbox' ? checked : value
    }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      const res = await apiFetch('/schedules', {
        method: 'POST',
        body: JSON.stringify({
          ...formData,
          provider_id: formData.provider_id ? parseInt(formData.provider_id, 10) : null
        })
      });
      if (res.ok) {
        setFormData({
          name: '', provider_id: '', target_url: '', cron_expression: '0 0 * * *', action: 'metadata_and_download', is_active: true
        });
        fetchData();
        setSnackbar({ open: true, message: 'Schedule created successfully!', severity: 'success' });
      } else {
        const error = await res.json().catch(() => ({}));
        setSnackbar({ open: true, message: `Error: ${error.detail || 'Failed to create schedule'}`, severity: 'error' });
      }
    } catch (e) {
      setSnackbar({ open: true, message: `Error: ${e.message}`, severity: 'error' });
    }
  };

  const confirmDelete = async () => {
    const id = deleteConfirm.scheduleId;
    if (!id) return;
    try {
      const res = await apiFetch(`/schedules/${id}`, {
        method: 'DELETE'
      });
      if (res.ok) {
        setDeleteConfirm({ open: false, scheduleId: null });
        fetchData();
        setSnackbar({ open: true, message: 'Schedule deleted successfully', severity: 'success' });
      } else {
        const err = await res.json().catch(() => ({}));
        setSnackbar({ open: true, message: `Error: ${err.detail || 'Failed to delete'}`, severity: 'error' });
      }
    } catch (e) {
      console.error('Failed to delete schedule:', e);
    }
  };

  const handleToggle = async (id, currentStatus) => {
    try {
      const res = await apiFetch(`/schedules/${id}`, {
        method: 'PUT',
        body: JSON.stringify({ is_active: !currentStatus })
      });
      if (res.ok) {
        fetchData();
      } else {
        setSnackbar({ open: true, message: 'Failed to update schedule.', severity: 'error' });
      }
    } catch (e) {
      console.error('Failed to toggle schedule:', e);
    }
  };

  const handleTrigger = async (id) => {
    try {
      const res = await apiFetch(`/schedules/${id}/trigger`, {
        method: 'POST'
      });
      if (res.ok) {
        setSnackbar({ open: true, message: 'Schedule triggered! Check the download queue shortly.', severity: 'success' });
        fetchData();
      } else {
        setSnackbar({ open: true, message: 'Failed to trigger schedule.', severity: 'error' });
      }
    } catch (e) {
      setSnackbar({ open: true, message: `Error: ${e.message}`, severity: 'error' });
    }
  };

  const formatTime = (timeStr) => {
    if (!timeStr) return 'N/A';
    const hasTimezone = timeStr.endsWith('Z') || timeStr.includes('+') || timeStr.match(/-\d{2}:\d{2}$/);
    return new Date(hasTimezone ? timeStr : timeStr + 'Z').toLocaleString();
  };

  return (
    <Box sx={{ maxWidth: 1400, mx: 'auto', width: '100%' }}>
      <Typography variant="h5" gutterBottom>Schedule Engine (Site Ripping)</Typography>

      {/* Purpose Banner */}
      <Alert 
        severity="info" 
        sx={{ 
          mb: 3, 
          borderRadius: '12px', 
          bgcolor: 'rgba(14, 165, 233, 0.08)', 
          color: '#38bdf8',
          border: '1px solid rgba(14, 165, 233, 0.2)',
          '& .MuiAlert-icon': { color: '#0284c7' } 
        }}
      >
        <Typography variant="subtitle2" sx={{ fontWeight: 'bold', mb: 0.25 }}>
          ⏱️ Automated Task Scheduler &amp; Recurring Cron Jobs
        </Typography>
        <Typography variant="caption" sx={{ display: 'block', opacity: 0.9, lineHeight: 1.4 }}>
          The Schedule Engine runs recurring background jobs for automated channel scraping, metadata synchronization, database maintenance, and routine media backups at custom Cron intervals.
        </Typography>
      </Alert>

      <Paper sx={{ p: 2, mb: 4, mx: 'auto', width: '100%' }}>
        <Typography variant="h6" gutterBottom>Create New Schedule</Typography>
        {!scrapingEnabled && (
          <Alert severity="warning" sx={{ mb: 2 }} style={{ color: '#ff9800', background: 'rgba(255, 152, 0, 0.08)', border: '1px solid rgba(255, 152, 0, 0.2)' }}>
            ⚠️ Access Denied: The Scraping feature is disabled globally by the administrator. Please enable it in Settings to configure or manage schedules.
          </Alert>
        )}
        <form onSubmit={handleSubmit}>
          <Grid container spacing={2}>
            <Grid xs={12}>
              <TextField 
                fullWidth size="small" name="name" label="Schedule Name" 
                slotProps={{ inputLabel: { shrink: true } }}
                value={formData.name} onChange={handleChange} required 
                disabled={!scrapingEnabled}
              />
            </Grid>
            <Grid xs={12}>
              <Autocomplete
                options={providers}
                getOptionLabel={(option) => option.name}
                value={providers.find(p => p.id === formData.provider_id) || null}
                onChange={(e, newValue) => setFormData({ ...formData, provider_id: newValue ? newValue.id : '' })}
                disabled={!scrapingEnabled}
                renderInput={(params) => <TextField {...params} label="Provider" size="small" required />}
                fullWidth
              />
            </Grid>
            <Grid xs={12}>
              <Autocomplete
                options={[
                  {value: 'metadata_and_download', label: 'Rip Metadata & Download'},
                  {value: 'download_only', label: 'Download Videos Only'},
                  {value: 'metadata_only', label: 'Rip Metadata Only'}
                ]}
                getOptionLabel={(option) => option.label}
                value={[
                  {value: 'metadata_and_download', label: 'Rip Metadata & Download'},
                  {value: 'download_only', label: 'Download Videos Only'},
                  {value: 'metadata_only', label: 'Rip Metadata Only'}
                ].find(o => o.value === formData.action) || null}
                onChange={(e, newValue) => setFormData({ ...formData, action: newValue ? newValue.value : 'metadata_and_download' })}
                disabled={!scrapingEnabled}
                renderInput={(params) => <TextField {...params} label="Action" size="small" required />}
                fullWidth
              />
            </Grid>
            <Grid xs={12}>
              <TextField 
                fullWidth size="small" name="cron_expression" label="Cron Expression" 
                slotProps={{ inputLabel: { shrink: true } }}
                value={formData.cron_expression} onChange={handleChange} required 
                helperText="e.g. 0 0 * * * (Daily at midnight)"
                disabled={!scrapingEnabled}
              />
            </Grid>
            <Grid xs={12}>
              <TextField 
                fullWidth size="small" name="target_url" label="Target URL (Channel/Playlist/Index)" 
                slotProps={{ inputLabel: { shrink: true } }}
                value={formData.target_url} onChange={handleChange} required 
                disabled={!scrapingEnabled}
              />
            </Grid>
            <Grid xs={12}>
              <FormControlLabel
                control={<Switch checked={formData.is_active} onChange={handleChange} name="is_active" disabled={!scrapingEnabled} />}
                label="Active"
              />
            </Grid>
            <Grid xs={12} sx={{ display: 'flex', justifyContent: 'center', mt: 2 }}>
              <Button variant="contained" type="submit" disabled={!scrapingEnabled} sx={{ minWidth: 200, height: 40, fontWeight: 600 }}>
                Create Schedule
              </Button>
            </Grid>
          </Grid>
        </form>
      </Paper>

      <Typography variant="h6" gutterBottom>Active Schedules</Typography>
      <TableContainer component={Paper} sx={{ overflowX: 'auto', mx: 'auto', width: '100%' }}>
        <Table size="small">
          <TableHead>
            <TableRow>
              <TableCell align="center" sx={{ whiteSpace: 'nowrap' }}>Name</TableCell>
              <TableCell align="center" sx={{ whiteSpace: 'nowrap' }}>Target URL</TableCell>
              <TableCell align="center" sx={{ whiteSpace: 'nowrap' }}>Provider</TableCell>
              <TableCell align="center" sx={{ whiteSpace: 'nowrap' }}>Action</TableCell>
              <TableCell align="center" sx={{ whiteSpace: 'nowrap' }}>Cron</TableCell>
              <TableCell align="center" sx={{ whiteSpace: 'nowrap' }}>Active</TableCell>
              <TableCell align="center" sx={{ whiteSpace: 'nowrap' }}>Last Run</TableCell>
              <TableCell align="center" sx={{ whiteSpace: 'nowrap' }}>Next Run</TableCell>
              <TableCell align="center" sx={{ whiteSpace: 'nowrap' }}>Last Result</TableCell>
              <TableCell align="center" sx={{ whiteSpace: 'nowrap' }}>Actions</TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            {schedules.map((row) => {
              const providerName = providers.find(p => p.id === row.provider_id)?.name || 'Unknown';
              return (
                <TableRow key={row.id}>
                  <TableCell align="center" sx={{ whiteSpace: 'nowrap' }}>{row.name}</TableCell>
                  <TableCell align="center" sx={{ whiteSpace: 'nowrap' }}>
                    <Tooltip title={row.target_url || ''}>
                      <Typography noWrap sx={{ maxWidth: 150 }}>{row.target_url}</Typography>
                    </Tooltip>
                  </TableCell>
                  <TableCell align="center" sx={{ whiteSpace: 'nowrap' }}>{providerName}</TableCell>
                  <TableCell align="center" sx={{ whiteSpace: 'nowrap' }}>
                    <Chip size="small" label={row.action.replace(/_/g, ' ')} />
                  </TableCell>
                  <TableCell align="center" sx={{ whiteSpace: 'nowrap' }}>{row.cron_expression}</TableCell>
                  <TableCell align="center" sx={{ whiteSpace: 'nowrap' }}>
                    <Switch size="small" checked={row.is_active} onChange={() => handleToggle(row.id, row.is_active)} disabled={!scrapingEnabled} />
                  </TableCell>
                  <TableCell align="center" sx={{ whiteSpace: 'nowrap' }}>
                    {formatTime(row.last_run)}
                  </TableCell>
                  <TableCell align="center" sx={{ whiteSpace: 'nowrap' }}>
                    {formatTime(row.next_run)}
                  </TableCell>
                  <TableCell align="center" sx={{ whiteSpace: 'nowrap' }}>
                    {row.last_run_status ? (
                      <Tooltip title={row.last_run_details || 'No details'}>
                        <Chip size="small" color={row.last_run_status === 'success' ? 'success' : 'error'} label={row.last_run_status} />
                      </Tooltip>
                    ) : 'N/A'}
                  </TableCell>
                  <TableCell align="center" sx={{ whiteSpace: 'nowrap' }}>
                    <Tooltip title="Trigger Now">
                      <IconButton size="small" color="primary" onClick={() => handleTrigger(row.id)} disabled={!scrapingEnabled}>
                        <PlayArrowIcon />
                      </IconButton>
                    </Tooltip>
                    <Tooltip title="Delete">
                      <IconButton size="small" color="error" onClick={() => setDeleteConfirm({ open: true, scheduleId: row.id })} disabled={!scrapingEnabled}>
                        <DeleteIcon />
                      </IconButton>
                    </Tooltip>
                  </TableCell>
                </TableRow>
              );
            })}
            {schedules.length === 0 && (
              <TableRow>
                <TableCell colSpan={10} align="center">No schedules defined</TableCell>
              </TableRow>
            )}
          </TableBody>
        </Table>
      </TableContainer>

      <Dialog open={deleteConfirm.open} onClose={() => setDeleteConfirm({ open: false, scheduleId: null })}>
        <DialogTitle>Delete Schedule</DialogTitle>
        <DialogContent>
          <Typography>Are you sure you want to delete this schedule? This action cannot be undone.</Typography>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setDeleteConfirm({ open: false, scheduleId: null })}>Cancel</Button>
          <Button variant="contained" color="error" onClick={confirmDelete}>Delete</Button>
        </DialogActions>
      </Dialog>

      <Snackbar open={snackbar.open} autoHideDuration={4000} onClose={() => setSnackbar({ ...snackbar, open: false })}>
        <Alert severity={snackbar.severity} sx={{ width: '100%' }}>{snackbar.message}</Alert>
      </Snackbar>
    </Box>
  );
}

