import { useState, useEffect, useCallback } from 'react'
import { 
  Box, Button, Typography, Paper, Table, TableBody, TableCell, TableContainer, 
  TableHead, TableRow, LinearProgress, IconButton, Chip, Tooltip, Card, 
  CardContent, Alert
} from '@mui/material'
import PauseIcon from '@mui/icons-material/Pause'
import PlayArrowIcon from '@mui/icons-material/PlayArrow'
import CancelIcon from '@mui/icons-material/Cancel'
import ArrowUpwardIcon from '@mui/icons-material/ArrowUpward'
import ArrowDownwardIcon from '@mui/icons-material/ArrowDownward'
import DeleteIcon from '@mui/icons-material/Delete'
import StorageIcon from '@mui/icons-material/Storage'
import { apiFetch, getAuthHeaders } from '../api'

const API_BASE = import.meta.env.VITE_API_BASE || '/api'

export default function TranscodeQueue() {
  const [jobs, setJobs] = useState([])
  const [statusFilter, setStatusFilter] = useState('')

  const fetchJobs = useCallback(async () => {
    try {
      const res = await apiFetch('/transcode')
      if (res.ok) {
        const data = await res.json()
        setJobs(data)
      }
    } catch (e) {
      console.error('Failed to fetch transcoding jobs:', e)
    }
  }, [])

  useEffect(() => {
    fetchJobs()

    const abortController = new AbortController()
    const startSSE = async () => {
      try {
        const res = await fetch(`${API_BASE}/transcode/stream`, {
          headers: getAuthHeaders(),
          signal: abortController.signal
        })
        if (res.status === 403) {
          console.warn('Access forbidden to /transcode/stream. SSE streaming disabled.')
          return
        }
        if (!res.ok) {
          throw new Error(`Transcode stream HTTP error! Status: ${res.status}`)
        }
        const reader = res.body.getReader()
        const decoder = new TextDecoder('utf-8')
        let buffer = ''
        while (true) {
          const { done, value } = await reader.read()
          if (done) break
          buffer += decoder.decode(value, { stream: true })
          const lines = buffer.split('\n\n')
          buffer = lines.pop()
          for (const line of lines) {
            if (line.startsWith('data: ')) {
              try {
                const sseJobs = JSON.parse(line.substring(6))
                // Merge static completed/failed jobs from state or let fetchJobs handle full view
                // For a smooth experience, update local jobs state with SSE updates
                setJobs(prevJobs => {
                  const sseIds = sseJobs.map(j => j.id)
                  const completedOrFailed = prevJobs.filter(j => !sseIds.includes(j.id) && ['completed', 'failed', 'cancelled'].includes(j.status))
                  return [...sseJobs, ...completedOrFailed]
                })
              } catch (e) {
                console.debug('JSON Parse error', e)
              }
            }
          }
        }
      } catch (e) {
        if (e.name !== 'AbortError' && !abortController.signal.aborted) {
          setTimeout(() => {
            if (!abortController.signal.aborted) startSSE()
          }, 5000)
        }
      }
    }

    startSSE()
    return () => abortController.abort()
  }, [fetchJobs])

  const handleAction = async (jobId, action) => {
    try {
      const res = await apiFetch(`/transcode/${jobId}/${action}`, {
        method: 'POST'
      })
      if (res.ok) {
        fetchJobs()
      } else {
        const err = await res.json()
        window.dispatchEvent(new CustomEvent('show-toast', { detail: { message: err.detail || 'Action failed.', severity: 'error' } }))
      }
    } catch (e) {
      console.error(e)
    }
  }

  const handleDeleteJob = async (jobId) => {
    const confirm = await window.appConfirm('Are you sure you want to remove this transcode job from the database?')
    if (!confirm) return
    try {
      const res = await apiFetch(`/transcode/${jobId}`, {
        method: 'DELETE'
      })
      if (res.ok) {
        setJobs(jobs.filter(j => j.id !== jobId))
        window.dispatchEvent(new CustomEvent('show-toast', { detail: { message: 'Transcode job removed.', severity: 'success' } }))
      }
    } catch (e) {
      console.error(e)
    }
  }

  const filteredJobs = statusFilter ? (jobs || []).filter(j => j.status === statusFilter) : (jobs || [])

  return (
    <Card sx={{ background: 'rgba(15, 23, 42, 0.4)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255, 255, 255, 0.08)', borderRadius: '16px', maxWidth: 1400, mx: 'auto', width: '100%', boxShadow: '0 8px 32px rgba(0, 0, 0, 0.25)' }}>
      <CardContent sx={{ display: 'flex', flexDirection: 'column', gap: 2.5, p: 3 }}>
        <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <Box>
            <Typography variant="h5" sx={{ fontWeight: '800', display: 'flex', alignItems: 'center', gap: 1.5, letterSpacing: '-0.5px' }}>
              <StorageIcon color="primary" sx={{ fontSize: 28 }} /> Transcoding Queue
            </Typography>
          </Box>
        </Box>

        {/* Purpose Banner */}
        <Alert 
          severity="info" 
          icon={<StorageIcon fontSize="small" />} 
          sx={{ 
            borderRadius: '12px', 
            bgcolor: 'rgba(14, 165, 233, 0.08)', 
            color: '#38bdf8',
            border: '1px solid rgba(14, 165, 233, 0.2)',
            '& .MuiAlert-icon': { color: '#0284c7' } 
          }}
        >
          <Typography variant="subtitle2" sx={{ fontWeight: 'bold', mb: 0.25 }}>
            ⚙️ Hardware Transcoding &amp; Codec Optimization
          </Typography>
          <Typography variant="caption" sx={{ display: 'block', opacity: 0.9, lineHeight: 1.4 }}>
            The Transcoding Queue optimizes downloaded video files into web-compatible formats (H.264/MP4, HEVC, AV1). This ensures universal stream playback across mobile devices and browsers without buffering or missing codec errors.
          </Typography>
        </Alert>

        {/* Status summary + filter */}
        <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: 2, mb: 2 }}>
          <Box sx={{ display: 'flex', gap: 1, alignItems: 'center', flexWrap: 'wrap' }}>
            {['all', 'running', 'pending', 'paused', 'completed', 'failed'].map(s => {
              const count = s === 'all' ? (jobs || []).length : (jobs || []).filter(j => j.status === s).length
              return (
                <Chip key={s} label={`${s.charAt(0).toUpperCase() + s.slice(1)} (${count})`} size="small"
                  clickable onClick={() => setStatusFilter(s === 'all' ? '' : s)}
                  color={statusFilter === s || (s === 'all' && !statusFilter) ? 'primary' : 'default'}
                  variant={statusFilter === s || (s === 'all' && !statusFilter) ? 'filled' : 'outlined'}
                  sx={{ fontWeight: 600, fontSize: '0.65rem' }}
                />
              )
            })}
          </Box>
          <Box sx={{ display: 'flex', gap: 1 }}>
            {(jobs || []).some(j => j.status === 'running') && (
              <Button size="small" variant="outlined" color="warning" onClick={() => (jobs || []).filter(j => j.status === 'running').forEach(j => handleAction(j.id, 'pause'))}
                sx={{ borderRadius: '8px', textTransform: 'none', fontSize: '0.75rem' }}>Pause All</Button>
            )}
            {(jobs || []).some(j => j.status === 'paused') && (
              <Button size="small" variant="outlined" color="success" onClick={() => (jobs || []).filter(j => j.status === 'paused').forEach(j => handleAction(j.id, 'resume'))}
                sx={{ borderRadius: '8px', textTransform: 'none', fontSize: '0.75rem' }}>Resume All</Button>
            )}
            {(jobs || []).some(j => ['completed', 'failed', 'cancelled'].includes(j.status)) && (
              <Button size="small" variant="outlined" color="default" onClick={() => (jobs || []).filter(j => ['completed', 'failed', 'cancelled'].includes(j.status)).forEach(j => handleAction(j.id, 'delete'))}
                sx={{ borderRadius: '8px', textTransform: 'none', fontSize: '0.75rem' }}>Clear All</Button>
            )}
          </Box>
        </Box>

        {(jobs || []).length === 0 ? (
          <Paper sx={{ p: 6, textAlign: 'center', background: 'rgba(255, 255, 255, 0.01)', border: '1px dashed rgba(255, 255, 255, 0.08)', borderRadius: '14px' }}>
            <StorageIcon sx={{ fontSize: 48, opacity: 0.3, mb: 1 }} />
            <Typography variant="body2" sx={{ opacity: 0.6 }}>No transcoding jobs currently active in queue.</Typography>
          </Paper>
        ) : (
          <TableContainer component={Paper} sx={{ background: 'rgba(0, 0, 0, 0.2)', border: '1px solid rgba(255, 255, 255, 0.08)', borderRadius: '12px', overflowX: 'auto' }}>
            <Table size="small">
              <TableHead sx={{ bgcolor: 'rgba(255, 255, 255, 0.03)' }}>
                <TableRow>
                  <TableCell align="left" sx={{ fontWeight: 'bold', whiteSpace: 'nowrap', py: 1.5, pl: 2 }}>Title & Details</TableCell>
                  <TableCell align="center" sx={{ fontWeight: 'bold', whiteSpace: 'nowrap', py: 1.5 }}>Target Codec</TableCell>
                  <TableCell align="center" sx={{ fontWeight: 'bold', whiteSpace: 'nowrap', py: 1.5 }}>Priority</TableCell>
                  <TableCell align="center" sx={{ fontWeight: 'bold', whiteSpace: 'nowrap', py: 1.5 }}>Status</TableCell>
                  <TableCell align="center" sx={{ fontWeight: 'bold', whiteSpace: 'nowrap', py: 1.5 }}>Progress</TableCell>
                  <TableCell align="right" sx={{ fontWeight: 'bold', whiteSpace: 'nowrap', py: 1.5, pr: 2 }}>Actions</TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {filteredJobs.map((job) => (
                  <TableRow key={job.id} hover sx={{ '&:last-child td, &:last-child th': { border: 0 } }}>
                    <TableCell align="left" sx={{ maxWidth: '340px', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap', pl: 2 }}>
                      <Tooltip title={job.title || `Entry ${job.library_entry_id}`}>
                        <Typography sx={{ fontWeight: '600', fontSize: '0.9rem' }} noWrap>
                          {job.title || `Entry ${job.library_entry_id}`}
                        </Typography>
                      </Tooltip>
                      {job.details && (
                        <Typography variant="caption" color="text.secondary" sx={{ display: 'block' }} noWrap>
                          {job.details}
                        </Typography>
                      )}
                    </TableCell>
                    <TableCell align="center" sx={{ whiteSpace: 'nowrap' }}>
                      <Chip label={job.target_codec?.toUpperCase()} size="small" variant="outlined" color="primary" sx={{ fontWeight: 'bold' }} />
                    </TableCell>
                    <TableCell align="center" sx={{ whiteSpace: 'nowrap' }}>
                      <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 0.5 }}>
                        <Typography variant="body2" sx={{ fontWeight: 'bold', minWidth: 20 }}>{job.priority}</Typography>
                        {['pending', 'paused'].includes(job.status) && (
                          <>
                            <IconButton size="small" onClick={() => handleAction(job.id, 'priority/up')} color="primary">
                              <ArrowUpwardIcon fontSize="inherit" />
                            </IconButton>
                            <IconButton size="small" onClick={() => handleAction(job.id, 'priority/down')} color="primary">
                              <ArrowDownwardIcon fontSize="inherit" />
                            </IconButton>
                          </>
                        )}
                      </Box>
                    </TableCell>
                    <TableCell align="center" sx={{ whiteSpace: 'nowrap' }}>
                      <Chip 
                        label={job.status.toUpperCase()} 
                        size="small" 
                        color={
                          job.status === 'completed' ? 'success' :
                          job.status === 'running' ? 'info' :
                          job.status === 'paused' ? 'warning' :
                          job.status === 'failed' ? 'error' : 'default'
                        }
                        sx={{ fontWeight: 'bold', fontSize: '0.7rem' }}
                      />
                    </TableCell>
                    <TableCell align="center" sx={{ minWidth: '160px', whiteSpace: 'nowrap' }}>
                      <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                        <Box sx={{ width: '100%', mr: 1 }}>
                          <Tooltip
                            title={
                              job.details
                                ? (() => {
                                    try {
                                      const d = typeof job.details === 'string' ? JSON.parse(job.details) : job.details
                                      const timeStr = d.current_time_sec ? `${Math.floor(d.current_time_sec / 60)}m ${Math.floor(d.current_time_sec % 60)}s` : ''
                                      const durStr = d.duration_sec ? `${Math.floor(d.duration_sec / 60)}m ${Math.floor(d.duration_sec % 60)}s` : ''
                                      const codec = d.target_codec || ''
                                      return `${(job.progress_percentage || 0).toFixed(1)}% · ${codec}${timeStr ? ` · ${timeStr} / ${durStr}` : ''}`
                                    } catch { return `${(job.progress_percentage || 0).toFixed(1)}%` }
                                  })()
                                : `${(job.progress_percentage || 0).toFixed(1)}%`
                            }
                            placement="bottom"
                          >
                            <LinearProgress 
                              variant="determinate" 
                              value={job.progress_percentage || 0} 
                              color={job.status === 'paused' ? 'warning' : 'primary'}
                              sx={{ borderRadius: 5, height: 6 }}
                            />
                          </Tooltip>
                        </Box>
                        <Box sx={{ minWidth: 35 }}>
                          <Typography variant="body2" color="text.secondary" sx={{ fontWeight: 'bold' }}>
                            {Math.round(job.progress_percentage || 0)}%
                          </Typography>
                        </Box>
                      </Box>
                    </TableCell>
                    <TableCell align="right" sx={{ whiteSpace: 'nowrap', pr: 2 }}>
                      <Box sx={{ display: 'inline-flex', gap: 1 }}>
                        {job.status === 'running' && (
                          <Tooltip title="Pause Task">
                            <IconButton color="warning" size="small" onClick={() => handleAction(job.id, 'pause')}>
                              <PauseIcon fontSize="small" />
                            </IconButton>
                          </Tooltip>
                        )}
                        {job.status === 'paused' && (
                          <Tooltip title="Resume Task">
                            <IconButton color="success" size="small" onClick={() => handleAction(job.id, 'resume')}>
                              <PlayArrowIcon fontSize="small" />
                            </IconButton>
                          </Tooltip>
                        )}
                        {['running', 'paused', 'pending'].includes(job.status) && (
                          <Tooltip title="Cancel Task">
                            <IconButton color="error" size="small" onClick={() => handleAction(job.id, 'cancel')}>
                              <CancelIcon fontSize="small" />
                            </IconButton>
                          </Tooltip>
                        )}
                        {['completed', 'failed', 'cancelled'].includes(job.status) && (
                          <Tooltip title="Remove Job">
                            <IconButton color="error" size="small" onClick={() => handleDeleteJob(job.id)}>
                              <DeleteIcon fontSize="small" />
                            </IconButton>
                          </Tooltip>
                        )}
                      </Box>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </TableContainer>
        )}
      </CardContent>
    </Card>
  )
}

import { useState, useEffect } from 'react'
import {
  Box, Button, Card, CardContent, TextField, Typography, 
  Alert, CircularProgress, Table, TableBody, TableCell,
  TableContainer, TableHead, TableRow, Paper, Dialog, DialogTitle,
  DialogContent, DialogActions, Chip, IconButton, InputAdornment, Grid,
  Switch, FormControlLabel, Divider
} from '@mui/material'
import SearchIcon from '@mui/icons-material/Search'
import { apiFetch } from '../api'
import GlassCard from './common/GlassCard'

export default function UniversalSearch() {
  const [universalQuery, setUniversalQuery] = useState('')
  const [universalResults, setUniversalResults] = useState(null)
  const [loading, setLoading] = useState(false)
  const [message, setMessage] = useState('')
  const [tpdbKey, setTpdbKey] = useState('')
  const [stashdbKey, setStashdbKey] = useState('')
  const [onlyfansEnabled, setOnlyfansEnabled] = useState(true)
  const [fanslyEnabled, setFanslyEnabled] = useState(true)
  const [patreonEnabled, setPatreonEnabled] = useState(true)
  const [loyalfansEnabled, setLoyalfansEnabled] = useState(true)

  const [openSyncDialog, setOpenSyncDialog] = useState(false)
  const [selectedResult, setSelectedResult] = useState(null)
  const [selectedResultSource, setSelectedResultSource] = useState('') // 'theporndb' or 'stashdb'

  // Load API keys & platform settings from global settings on mount
  useEffect(() => {
    const loadGlobalSettings = async () => {
      try {
        const response = await apiFetch('/settings')
        if (response.ok) {
          const data = await response.json()
          if (data.tpdb_api_key) setTpdbKey(data.tpdb_api_key)
          if (data.stashdb_api_key) setStashdbKey(data.stashdb_api_key)
          if (data.universal_search_onlyfans !== undefined) setOnlyfansEnabled(data.universal_search_onlyfans === 'true')
          if (data.universal_search_fansly !== undefined) setFanslyEnabled(data.universal_search_fansly === 'true')
          if (data.universal_search_patreon !== undefined) setPatreonEnabled(data.universal_search_patreon === 'true')
          if (data.universal_search_loyalfans !== undefined) setLoyalfansEnabled(data.universal_search_loyalfans === 'true')
        }
      } catch (error) {
        console.error('Failed to load global API keys in UniversalSearch:', error)
      }
    }
    loadGlobalSettings()
  }, [])

  const handleSaveGlobalSetting = async (key, value) => {
    try {
      await apiFetch('/settings', {
        method: 'POST',
        body: JSON.stringify({ key, value })
      })
    } catch (error) {
      console.error(`Error saving global setting ${key}:`, error)
    }
  }

  const handleTogglePlatform = async (platformName, enabled) => {
    if (platformName === 'onlyfans') setOnlyfansEnabled(enabled)
    if (platformName === 'fansly') setFanslyEnabled(enabled)
    if (platformName === 'patreon') setPatreonEnabled(enabled)
    if (platformName === 'loyalfans') setLoyalfansEnabled(enabled)

    await handleSaveGlobalSetting(`universal_search_${platformName}`, String(enabled))
  }

  const handleUniversalSearch = async () => {
    if (!universalQuery) {
      setMessage('Please enter a search query')
      return
    }

    setLoading(true)
    setUniversalResults(null)
    try {
      const response = await apiFetch('/external-api/universal-search', {
        method: 'POST',
        body: JSON.stringify({
          query: universalQuery
        })
      })

      if (response.ok) {
        const data = await response.json()
        setUniversalResults(data)
        setMessage('')
      } else {
        setMessage('Universal search failed')
      }
    } catch (error) {
      setMessage(`Error: ${error.message}`)
    }
    setLoading(false)
  }

  const handleSyncToThePornDB = async () => {
    if (!selectedResult) return

    setLoading(true)
    try {
      const response = await apiFetch('/external-api/theporndb/update', {
        method: 'POST',
        headers: { 'X-API-Key': tpdbKey },
        body: JSON.stringify({
          site_id: selectedResult.id,
          title: selectedResult.title,
          performers: selectedResult.performers,
          tags: selectedResult.tags,
          description: selectedResult.description
        })
      })

      if (response.ok) {
        setMessage('Synced to ThePornDB successfully')
        setOpenSyncDialog(false)
      } else {
        const errData = await response.json().catch(() => ({}))
        setMessage(`Failed to sync: ${errData.detail || response.statusText}`)
      }
    } catch (error) {
      setMessage(`Error: ${error.message}`)
    }
    setLoading(false)
  }

  const handleSyncToStashDB = async () => {
    if (!selectedResult) return

    setLoading(true)
    try {
      const response = await apiFetch('/external-api/stashdb/update', {
        method: 'POST',
        headers: { 'X-API-Key': stashdbKey },
        body: JSON.stringify({
          site_id: selectedResult.id,
          title: selectedResult.title,
          performers: selectedResult.performers,
          tags: selectedResult.tags
        })
      })

      if (response.ok) {
        setMessage('Synced to StashDB successfully')
        setOpenSyncDialog(false)
      } else {
        const errData = await response.json().catch(() => ({}))
        setMessage(`Failed to sync: ${errData.detail || response.statusText}`)
      }
    } catch (error) {
      setMessage(`Error: ${error.message}`)
    }
    setLoading(false)
  }

  return (
    <Box sx={{ maxWidth: 1400, mx: 'auto', width: '100%' }}>
      <Typography variant="h4" gutterBottom>
        Universal Search
      </Typography>

      <Alert severity="info" sx={{ mb: 3, borderRadius: '12px', bgcolor: 'rgba(99,102,241,0.08)', color: '#a5b4fc', border: '1px solid rgba(99,102,241,0.2)', '& .MuiAlert-icon': { color: '#818cf8' } }}>
        <Typography variant="subtitle2" sx={{ fontWeight: 'bold', mb: 0.25 }}>🔍 Universal Aggregated Search</Typography>
        <Typography variant="caption" sx={{ display: 'block', opacity: 0.9, lineHeight: 1.4 }}>
          Search across your local library, ThePornDB, StashDB, and connected subscription platforms in one place. Toggle search indices below to refine results.
        </Typography>
      </Alert>

      <GlassCard sx={{ mb: 3 }}>
        <Typography variant="h6" sx={{ fontWeight: '700', mb: 2 }}>Universal Aggregated Search</Typography>
        <Typography variant="body2" color="textSecondary" sx={{ mb: 2 }}>
          Search across local media, remote standard databases, and active subscription platforms in a single interface.
        </Typography>

        <Box sx={{ display: 'flex', gap: 2, alignItems: 'center', mb: 3 }}>
            <TextField
              fullWidth
              label="Search handle, performer or scene..."
              value={universalQuery}
              onChange={(e) => setUniversalQuery(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && handleUniversalSearch()}
              slotProps={{ input: {
                endAdornment: (
                  <InputAdornment position="end">
                    <IconButton onClick={handleUniversalSearch} disabled={loading}>
                      <SearchIcon />
                    </IconButton>
                  </InputAdornment>
                ),
              }}}
            />
            <Button 
              variant="contained" 
              onClick={handleUniversalSearch}
              disabled={loading}
              sx={{ height: 56, px: 4 }}
            >
              {loading ? <CircularProgress size={24} /> : 'Search'}
            </Button>
          </Box>

          <Divider sx={{ my: 2 }} />

          <Typography variant="subtitle2" sx={{ mb: 1 }}>Enabled Subscription Search Indices:</Typography>
          <Grid container spacing={2}>
            <Grid xs={6} sm={3}>
              <FormControlLabel
                control={<Switch checked={onlyfansEnabled} onChange={(e) => handleTogglePlatform('onlyfans', e.target.checked)} />}
                label="OnlyFans"
              />
            </Grid>
            <Grid xs={6} sm={3}>
              <FormControlLabel
                control={<Switch checked={fanslyEnabled} onChange={(e) => handleTogglePlatform('fansly', e.target.checked)} />}
                label="Fansly"
              />
            </Grid>
            <Grid xs={6} sm={3}>
              <FormControlLabel
                control={<Switch checked={patreonEnabled} onChange={(e) => handleTogglePlatform('patreon', e.target.checked)} />}
                label="Patreon"
              />
            </Grid>
            <Grid xs={6} sm={3}>
              <FormControlLabel
                control={<Switch checked={loyalfansEnabled} onChange={(e) => handleTogglePlatform('loyalfans', e.target.checked)} />}
                label="LoyalFans"
              />
            </Grid>
          </Grid>
      </GlassCard>

      {message && (
        <Alert severity={message.includes('Error') || message.includes('Failed') ? 'error' : 'info'} sx={{ mb: 3 }}>
          {message}
        </Alert>
      )}

      {universalResults && (
        <Box sx={{ display: 'flex', flexDirection: 'column', gap: 3 }}>
          {/* Local Library Hits */}
          {universalResults.local?.length > 0 && (
            <GlassCard>
                <Typography variant="h6" color="primary" gutterBottom>Local Library Matches</Typography>
                <TableContainer component={Paper} variant="outlined" sx={{ borderRadius: '12px', bgcolor: 'rgba(255,255,255,0.03)', border: '1px solid rgba(255,255,255,0.08)' }}>
                  <Table size="small">
                    <TableHead>
                      <TableRow sx={{ '&:hover': { bgcolor: 'rgba(99,102,241,0.06)' } }}>
                        <TableCell>Title</TableCell>
                        <TableCell>Performers</TableCell>
                        <TableCell>File Path</TableCell>
                      </TableRow>
                    </TableHead>
                    <TableBody>
                      {universalResults.local.map((entry, idx) => (
                        <TableRow key={idx} sx={{ '&:hover': { bgcolor: 'rgba(99,102,241,0.06)' } }}>
                          <TableCell><strong>{entry.title}</strong></TableCell>
                          <TableCell>{entry.performers?.map(p => p.name || p).join(', ') || 'None'}</TableCell>
                          <TableCell sx={{ fontStyle: 'italic', fontSize: '0.8rem' }}>{entry.url}</TableCell>
                        </TableRow>
                      ))}
                    </TableBody>
                  </Table>
                </TableContainer>
            </GlassCard>
          )}

          {/* Subscription Matches */}
          {universalResults.subscriptions?.length > 0 && (
            <GlassCard>
                <Typography variant="h6" color="secondary" gutterBottom>Subscription Platforms Matches</Typography>
                <TableContainer component={Paper} variant="outlined" sx={{ borderRadius: '12px', bgcolor: 'rgba(255,255,255,0.03)', border: '1px solid rgba(255,255,255,0.08)' }}>
                  <Table size="small">
                    <TableHead>
                      <TableRow sx={{ '&:hover': { bgcolor: 'rgba(99,102,241,0.06)' } }}>
                        <TableCell>Platform</TableCell>
                        <TableCell>Handle</TableCell>
                        <TableCell>Display Name</TableCell>
                        <TableCell>Teaser / Preview Metadata</TableCell>
                        <TableCell>Cross-Referencing</TableCell>
                        <TableCell>Cookie Sync</TableCell>
                      </TableRow>
                    </TableHead>
                    <TableBody>
                      {universalResults.subscriptions.map((sub, idx) => (
                        <TableRow key={idx} sx={{ '&:hover': { bgcolor: 'rgba(99,102,241,0.06)' } }}>
                          <TableCell>
                            <Chip 
                              size="small" 
                              label={sub.platform} 
                              color={sub.platform === 'OnlyFans' ? 'info' : sub.platform === 'Fansly' ? 'secondary' : 'default'}
                            />
                          </TableCell>
                          <TableCell><strong>{sub.handle}</strong></TableCell>
                          <TableCell>{sub.name}</TableCell>
                          <TableCell>
                            <Typography variant="body2" sx={{ fontStyle: sub.metadata.subscriber_only ? 'italic' : 'normal', color: sub.metadata.subscriber_only ? 'text.secondary' : 'text.primary' }}>
                              {sub.metadata.teaser_preview}
                            </Typography>
                          </TableCell>
                          <TableCell>
                            {sub.cross_referenced_performers?.length > 0 ? (
                              sub.cross_referenced_performers.map((p, i) => (
                                <Chip key={i} size="small" variant="outlined" label={`Matched: ${p}`} color="success" sx={{ mr: 0.5 }} />
                              ))
                            ) : (
                              <Typography variant="caption" color="text.secondary">No cross-ref matched</Typography>
                            )}
                          </TableCell>
                          <TableCell>
                            <Chip 
                              size="small" 
                              label={sub.metadata.subscriber_only ? 'No Active Cookie' : 'Synced'} 
                              color={sub.metadata.subscriber_only ? 'default' : 'success'} 
                            />
                          </TableCell>
                        </TableRow>
                      ))}
                    </TableBody>
                  </Table>
                </TableContainer>
            </GlassCard>
          )}

          {/* Remote StashDB Hits */}
          {universalResults.stashdb?.length > 0 && (
            <GlassCard>
                <Typography variant="h6" sx={{ color: '#9c27b0' }} gutterBottom>StashDB Registry Matches</Typography>
                <TableContainer component={Paper} variant="outlined" sx={{ borderRadius: '12px', bgcolor: 'rgba(255,255,255,0.03)', border: '1px solid rgba(255,255,255,0.08)' }}>
                  <Table size="small">
                    <TableHead>
                      <TableRow sx={{ '&:hover': { bgcolor: 'rgba(99,102,241,0.06)' } }}>
                        <TableCell>Title</TableCell>
                        <TableCell>Performers</TableCell>
                        <TableCell>Actions</TableCell>
                      </TableRow>
                    </TableHead>
                    <TableBody>
                      {universalResults.stashdb.map((item, idx) => (
                        <TableRow key={idx} sx={{ '&:hover': { bgcolor: 'rgba(99,102,241,0.06)' } }}>
                          <TableCell><strong>{item.title}</strong></TableCell>
                          <TableCell>{item.performers?.map(p => p.name || p).join(', ') || 'None'}</TableCell>
                          <TableCell>
                            <Button size="small" onClick={() => { setSelectedResult(item); setSelectedResultSource('stashdb'); setOpenSyncDialog(true); }}>
                              Sync Stats
                            </Button>
                          </TableCell>
                        </TableRow>
                      ))}
                    </TableBody>
                  </Table>
                </TableContainer>
            </GlassCard>
          )}

          {/* Remote ThePornDB Hits */}
          {universalResults.theporndb?.length > 0 && (
            <GlassCard>
                <Typography variant="h6" sx={{ color: '#009688' }} gutterBottom>ThePornDB Registry Matches</Typography>
                <TableContainer component={Paper} variant="outlined" sx={{ borderRadius: '12px', bgcolor: 'rgba(255,255,255,0.03)', border: '1px solid rgba(255,255,255,0.08)' }}>
                  <Table size="small">
                    <TableHead>
                      <TableRow sx={{ '&:hover': { bgcolor: 'rgba(99,102,241,0.06)' } }}>
                        <TableCell>Title</TableCell>
                        <TableCell>Performers</TableCell>
                        <TableCell>Actions</TableCell>
                      </TableRow>
                    </TableHead>
                    <TableBody>
                      {universalResults.theporndb.map((item, idx) => (
                        <TableRow key={idx} sx={{ '&:hover': { bgcolor: 'rgba(99,102,241,0.06)' } }}>
                          <TableCell><strong>{item.title}</strong></TableCell>
                          <TableCell>{item.performers?.map(p => p.name || p).join(', ') || 'None'}</TableCell>
                          <TableCell>
                            <Button size="small" onClick={() => { setSelectedResult(item); setSelectedResultSource('theporndb'); setOpenSyncDialog(true); }}>
                              Sync Stats
                            </Button>
                          </TableCell>
                        </TableRow>
                      ))}
                    </TableBody>
                  </Table>
                </TableContainer>
            </GlassCard>
          )}
        </Box>
      )}

      {/* Sync Dialog */}
      <Dialog open={openSyncDialog} onClose={() => setOpenSyncDialog(false)} maxWidth="sm" fullWidth>
        <DialogTitle>Sync Metadata</DialogTitle>
        <DialogContent dividers>
          {selectedResult && (
            <Box sx={{ pt: 2 }}>
              <Typography><strong>Title:</strong> {selectedResult.title}</Typography>
              <Typography>
                <strong>Performers:</strong> {selectedResult.performers?.map(p => p.name || p).join(', ')}
              </Typography>
              <Typography>
                <strong>Tags:</strong> {selectedResult.tags?.map(t => t.name || t).join(', ')}
              </Typography>
            </Box>
          )}
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setOpenSyncDialog(false)}>Cancel</Button>
          {selectedResultSource === 'theporndb' && (
            <Button onClick={handleSyncToThePornDB} variant="contained">
              Sync to ThePornDB
            </Button>
          )}
          {selectedResultSource === 'stashdb' && (
            <Button onClick={handleSyncToStashDB} variant="contained">
              Sync to StashDB
            </Button>
          )}
        </DialogActions>
      </Dialog>
    </Box>
  )
}

import React, { useState, useEffect } from 'react'
import {
  Dialog, DialogTitle, DialogContent, DialogActions, Button, IconButton,
  Box, Typography, Checkbox, FormControlLabel, TextField, Chip, Divider,
  Grid, Card, CardContent, Autocomplete
} from '@mui/material'
import CloseIcon from '@mui/icons-material/Close'
import CompareArrowsIcon from '@mui/icons-material/CompareArrows'

export default function UrlParseConfirmationModal({
  open,
  onClose,
  parsedData,
  currentData = {},
  onApply,
  permission = 'edit' // 'no_access', 'read_only', 'edit'
}) {
  const isReadOnly = permission === 'read_only'

  // Local state for parsed values
  const [title, setTitle] = useState('')
  const [studio, setStudio] = useState('')
  const [performers, setPerformers] = useState([])
  const [tags, setTags] = useState([])
  const [description, setDescription] = useState('')

  // State to track which fields the user wants to keep
  const [keepFields, setKeepFields] = useState({
    title: true,
    studio: true,
    performers: true,
    tags: true,
    description: true
  })

  // Synchronize local states when new data is parsed
  useEffect(() => {
    if (parsedData) {
      setTitle(parsedData.title || '')
      setStudio(parsedData.studio || '')
      setPerformers(Array.isArray(parsedData.performers) ? parsedData.performers : [])
      setTags(Array.isArray(parsedData.tags) ? parsedData.tags : [])
      setDescription(parsedData.description || '')

      // Default auto-select check to true if parsed value exists
      setKeepFields({
        title: Boolean(parsedData.title),
        studio: Boolean(parsedData.studio),
        performers: Boolean(parsedData.performers?.length),
        tags: Boolean(parsedData.tags?.length),
        description: Boolean(parsedData.description)
      })
    }
  }, [parsedData])

  const handleToggleField = (field) => {
    if (isReadOnly) return
    setKeepFields(prev => ({ ...prev, [field]: !prev[field] }))
  }

  const handleSave = () => {
    if (isReadOnly) return

    // Construct final payload containing only selected fields
    const finalData = {}
    if (keepFields.title) finalData.title = title
    if (keepFields.studio) finalData.studio = studio
    if (keepFields.performers) finalData.performers = performers
    if (keepFields.tags) finalData.tags = tags
    if (keepFields.description) finalData.description = description

    onApply(finalData)
    onClose()
  }

  if (!parsedData) return null

  return (
    <Dialog
      open={open}
      onClose={onClose}
      maxWidth="md"
      fullWidth
      slotProps={{ paper: {
        sx: {
          borderRadius: '16px',
          backdropFilter: 'blur(20px)',
          backgroundColor: 'rgba(30, 30, 30, 0.95)',
          border: '1px solid rgba(255, 255, 255, 0.1)',
          boxShadow: '0 8px 32px 0 rgba(0, 0, 0, 0.5)',
          color: 'white'
        }
      } }}
    >
      <DialogTitle sx={{ m: 0, p: 2.5, display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
        <Typography variant="h6" component="div" sx={{ fontWeight: 'bold' }}>
          {isReadOnly ? 'Parsed URL Details (Read-Only)' : 'Confirm Parsed Metadata'}
        </Typography>
        <IconButton onClick={onClose} sx={{ color: 'rgba(255,255,255,0.7)', '&:hover': { color: 'white' } }}>
          <CloseIcon />
        </IconButton>
      </DialogTitle>

      <DialogContent dividers sx={{ borderColor: 'rgba(255,255,255,0.1)', p: 3 }}>
        {isReadOnly && (
          <Box sx={{ mb: 2.5, p: 1.5, borderRadius: '8px', background: 'rgba(255, 152, 0, 0.1)', border: '1px solid rgba(255, 152, 0, 0.3)' }}>
            <Typography variant="body2" sx={{ color: '#ffa726' }}>
              Your account has read-only parsing privileges. You can view the extracted metadata below but cannot apply or modify it.
            </Typography>
          </Box>
        )}

        <Typography variant="body2" sx={{ opacity: 0.7, mb: 3 }}>
          Compare the parsed values from the URL with your current metadata. Choose which fields you wish to overwrite.
        </Typography>

        <Box sx={{ display: 'flex', flexDirection: 'column', gap: 3.5 }}>
          {/* TITLE FIELD */}
          <Box>
            <Box sx={{ display: 'flex', alignItems: 'center', mb: 1, gap: 1 }}>
              <Checkbox
                checked={keepFields.title}
                onChange={() => handleToggleField('title')}
                disabled={isReadOnly}
                sx={{ color: 'rgba(255,255,255,0.5)', '&.Mui-checked': { color: '#a855f7' } }}
              />
              <Typography variant="subtitle2" sx={{ fontWeight: 'bold', textTransform: 'uppercase', opacity: 0.9 }}>
                Title
              </Typography>
            </Box>
            <Grid container spacing={2} sx={{ alignItems: 'center' }}>
              <Grid xs={12} md={5.5}>
                <Card sx={{ bgcolor: 'rgba(255,255,255,0.03)', border: '1px dashed rgba(255,255,255,0.15)', height: '100%' }}>
                  <CardContent sx={{ py: 1.5, '&:last-child': { pb: 1.5 } }}>
                    <Typography variant="caption" color="textSecondary" display="block">Current Value</Typography>
                    <Typography variant="body2" sx={{ wordBreak: 'break-all', opacity: currentData.title ? 1 : 0.4 }}>
                      {currentData.title || 'Empty'}
                    </Typography>
                  </CardContent>
                </Card>
              </Grid>
              <Grid xs={12} md={1} sx={{ display: 'flex', justifyContent: 'center' }}>
                <CompareArrowsIcon sx={{ opacity: 0.3, transform: { xs: 'rotate(90deg)', md: 'none' } }} />
              </Grid>
              <Grid xs={12} md={5.5}>
                <TextField
                  fullWidth
                  size="small"
                  disabled={isReadOnly || !keepFields.title}
                  value={title}
                  onChange={(e) => setTitle(e.target.value)}
                  sx={{ '& .MuiOutlinedInput-root': { borderRadius: '10px' } }}
                />
              </Grid>
            </Grid>
          </Box>

          <Divider sx={{ borderColor: 'rgba(255,255,255,0.08)' }} />

          {/* STUDIO FIELD */}
          <Box>
            <Box sx={{ display: 'flex', alignItems: 'center', mb: 1, gap: 1 }}>
              <Checkbox
                checked={keepFields.studio}
                onChange={() => handleToggleField('studio')}
                disabled={isReadOnly}
                sx={{ color: 'rgba(255,255,255,0.5)', '&.Mui-checked': { color: '#a855f7' } }}
              />
              <Typography variant="subtitle2" sx={{ fontWeight: 'bold', textTransform: 'uppercase', opacity: 0.9 }}>
                Studio
              </Typography>
            </Box>
            <Grid container spacing={2} sx={{ alignItems: 'center' }}>
              <Grid xs={12} md={5.5}>
                <Card sx={{ bgcolor: 'rgba(255,255,255,0.03)', border: '1px dashed rgba(255,255,255,0.15)', height: '100%' }}>
                  <CardContent sx={{ py: 1.5, '&:last-child': { pb: 1.5 } }}>
                    <Typography variant="caption" color="textSecondary" display="block">Current Value</Typography>
                    <Typography variant="body2" sx={{ opacity: currentData.studio ? 1 : 0.4 }}>
                      {currentData.studio || 'Empty'}
                    </Typography>
                  </CardContent>
                </Card>
              </Grid>
              <Grid xs={12} md={1} sx={{ display: 'flex', justifyContent: 'center' }}>
                <CompareArrowsIcon sx={{ opacity: 0.3, transform: { xs: 'rotate(90deg)', md: 'none' } }} />
              </Grid>
              <Grid xs={12} md={5.5}>
                <TextField
                  fullWidth
                  size="small"
                  disabled={isReadOnly || !keepFields.studio}
                  value={studio}
                  onChange={(e) => setStudio(e.target.value)}
                  sx={{ '& .MuiOutlinedInput-root': { borderRadius: '10px' } }}
                />
              </Grid>
            </Grid>
          </Box>

          <Divider sx={{ borderColor: 'rgba(255,255,255,0.08)' }} />

          {/* PERFORMERS FIELD */}
          <Box>
            <Box sx={{ display: 'flex', alignItems: 'center', mb: 1, gap: 1 }}>
              <Checkbox
                checked={keepFields.performers}
                onChange={() => handleToggleField('performers')}
                disabled={isReadOnly}
                sx={{ color: 'rgba(255,255,255,0.5)', '&.Mui-checked': { color: '#a855f7' } }}
              />
              <Typography variant="subtitle2" sx={{ fontWeight: 'bold', textTransform: 'uppercase', opacity: 0.9 }}>
                Performers
              </Typography>
            </Box>
            <Grid container spacing={2} sx={{ alignItems: 'center' }}>
              <Grid xs={12} md={5.5}>
                <Card sx={{ bgcolor: 'rgba(255,255,255,0.03)', border: '1px dashed rgba(255,255,255,0.15)', height: '100%' }}>
                  <CardContent sx={{ py: 1.5, '&:last-child': { pb: 1.5 } }}>
                    <Typography variant="caption" color="textSecondary" display="block">Current Value</Typography>
                    <Box sx={{ display: 'flex', gap: 0.5, flexWrap: 'wrap', mt: 0.5 }}>
                      {currentData.performers?.length > 0 ? (
                        currentData.performers.map((p, i) => <Chip key={i} size="small" label={p} sx={{ height: 20 }} />)
                      ) : (
                        <Typography variant="body2" sx={{ opacity: 0.4 }}>Empty</Typography>
                      )}
                    </Box>
                  </CardContent>
                </Card>
              </Grid>
              <Grid xs={12} md={1} sx={{ display: 'flex', justifyContent: 'center' }}>
                <CompareArrowsIcon sx={{ opacity: 0.3, transform: { xs: 'rotate(90deg)', md: 'none' } }} />
              </Grid>
              <Grid xs={12} md={5.5}>
                <Autocomplete
                  multiple
                  freeSolo
                  size="small"
                  disabled={isReadOnly || !keepFields.performers}
                  options={[]}
                  value={performers}
                  onChange={(event, newValue) => setPerformers(newValue)}
                  renderTags={(value, getTagProps) =>
                    value.map((option, index) => {
                      const { key, ...tagProps } = getTagProps({ index })
                      return <Chip key={key || option} size="small" label={option} {...tagProps} />
                    })
                  }
                  renderInput={(params) => (
                    <TextField {...params} placeholder="Add Performers" sx={{ '& .MuiOutlinedInput-root': { borderRadius: '10px' } }} />
                  )}
                />
              </Grid>
            </Grid>
          </Box>

          <Divider sx={{ borderColor: 'rgba(255,255,255,0.08)' }} />

          {/* TAGS FIELD */}
          <Box>
            <Box sx={{ display: 'flex', alignItems: 'center', mb: 1, gap: 1 }}>
              <Checkbox
                checked={keepFields.tags}
                onChange={() => handleToggleField('tags')}
                disabled={isReadOnly}
                sx={{ color: 'rgba(255,255,255,0.5)', '&.Mui-checked': { color: '#a855f7' } }}
              />
              <Typography variant="subtitle2" sx={{ fontWeight: 'bold', textTransform: 'uppercase', opacity: 0.9 }}>
                Tags
              </Typography>
            </Box>
            <Grid container spacing={2} sx={{ alignItems: 'center' }}>
              <Grid xs={12} md={5.5}>
                <Card sx={{ bgcolor: 'rgba(255,255,255,0.03)', border: '1px dashed rgba(255,255,255,0.15)', height: '100%' }}>
                  <CardContent sx={{ py: 1.5, '&:last-child': { pb: 1.5 } }}>
                    <Typography variant="caption" color="textSecondary" display="block">Current Value</Typography>
                    <Box sx={{ display: 'flex', gap: 0.5, flexWrap: 'wrap', mt: 0.5 }}>
                      {currentData.tags?.length > 0 ? (
                        currentData.tags.map((t, i) => <Chip key={i} size="small" label={t} sx={{ height: 20 }} />)
                      ) : (
                        <Typography variant="body2" sx={{ opacity: 0.4 }}>Empty</Typography>
                      )}
                    </Box>
                  </CardContent>
                </Card>
              </Grid>
              <Grid xs={12} md={1} sx={{ display: 'flex', justifyContent: 'center' }}>
                <CompareArrowsIcon sx={{ opacity: 0.3, transform: { xs: 'rotate(90deg)', md: 'none' } }} />
              </Grid>
              <Grid xs={12} md={5.5}>
                <Autocomplete
                  multiple
                  freeSolo
                  size="small"
                  disabled={isReadOnly || !keepFields.tags}
                  options={[]}
                  value={tags}
                  onChange={(event, newValue) => setTags(newValue)}
                  renderTags={(value, getTagProps) =>
                    value.map((option, index) => {
                      const { key, ...tagProps } = getTagProps({ index })
                      return <Chip key={key || option} size="small" label={option} {...tagProps} />
                    })
                  }
                  renderInput={(params) => (
                    <TextField {...params} placeholder="Add Tags" sx={{ '& .MuiOutlinedInput-root': { borderRadius: '10px' } }} />
                  )}
                />
              </Grid>
            </Grid>
          </Box>

          <Divider sx={{ borderColor: 'rgba(255,255,255,0.08)' }} />

          {/* DESCRIPTION FIELD */}
          <Box>
            <Box sx={{ display: 'flex', alignItems: 'center', mb: 1, gap: 1 }}>
              <Checkbox
                checked={keepFields.description}
                onChange={() => handleToggleField('description')}
                disabled={isReadOnly}
                sx={{ color: 'rgba(255,255,255,0.5)', '&.Mui-checked': { color: '#a855f7' } }}
              />
              <Typography variant="subtitle2" sx={{ fontWeight: 'bold', textTransform: 'uppercase', opacity: 0.9 }}>
                Description
              </Typography>
            </Box>
            <Grid container spacing={2}>
              <Grid xs={12} md={5.5}>
                <Card sx={{ bgcolor: 'rgba(255,255,255,0.03)', border: '1px dashed rgba(255,255,255,0.15)', height: '100%' }}>
                  <CardContent sx={{ py: 1.5, '&:last-child': { pb: 1.5 } }}>
                    <Typography variant="caption" color="textSecondary" display="block">Current Value</Typography>
                    <Typography variant="body2" sx={{ whiteSpace: 'pre-wrap', opacity: currentData.description ? 1 : 0.4 }}>
                      {currentData.description || 'Empty'}
                    </Typography>
                  </CardContent>
                </Card>
              </Grid>
              <Grid xs={12} md={1} sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center' }}>
                <CompareArrowsIcon sx={{ opacity: 0.3, transform: { xs: 'rotate(90deg)', md: 'none' } }} />
              </Grid>
              <Grid xs={12} md={5.5}>
                <TextField
                  fullWidth
                  multiline
                  rows={4}
                  size="small"
                  disabled={isReadOnly || !keepFields.description}
                  value={description}
                  onChange={(e) => setDescription(e.target.value)}
                  sx={{ '& .MuiOutlinedInput-root': { borderRadius: '10px' } }}
                />
              </Grid>
            </Grid>
          </Box>
        </Box>
      </DialogContent>

      <DialogActions sx={{ p: 2.5 }}>
        <Button onClick={onClose} sx={{ color: 'rgba(255,255,255,0.7)', '&:hover': { bgcolor: 'rgba(255,255,255,0.08)' } }}>
          Close
        </Button>
        {!isReadOnly && (
          <Button
            variant="contained"
            onClick={handleSave}
            sx={{
              background: 'linear-gradient(135deg, #6366f1 0%, #a855f7 100%)',
              fontWeight: 'bold',
              borderRadius: '8px',
              px: 3,
              '&:hover': {
                background: 'linear-gradient(135deg, #4f46e5 0%, #9333ea 100%)'
              }
            }}
          >
            Apply Selected Fields
          </Button>
        )}
      </DialogActions>
    </Dialog>
  )
}

