                  >
                    <Typography variant="subtitle2" sx={{ fontWeight: 600, mb: 1 }}>Account History Merge Portal</Typography>
                    <Typography variant="body2" color="textSecondary" sx={{ mb: 2, fontSize: '0.85rem' }}>
                      Consolidate viewing history, favorites, video stats, WebAuthn passkeys, and linked social SSO accounts from <strong>{selectedUserForManage.username}</strong> into a target user account. The source account will be safely deleted after the migration completes.
                    </Typography>

                    <Grid container spacing={2} sx={{ alignItems: 'center' }}>
                      <Grid xs={12}>
                        <FormControl fullWidth size="small">
                          <InputLabel>Select Target Account</InputLabel>
                          <Select 
                            value={mergeTargetUserId} 
                            label="Select Target Account" 
                            onChange={e => setMergeTargetUserId(e.target.value)}
                          >
                            <MenuItem value=""><em>None selected</em></MenuItem>
                            {usersList
                              .filter(u => u.id !== selectedUserForManage.id)
                              .map(u => (
                                <MenuItem key={u.id} value={u.id}>{u.username} ({u.role})</MenuItem>
                              ))
                            }
                          </Select>
                        </FormControl>
                      </Grid>
                      <Grid xs={12} sx={{ display: 'flex', justifyContent: 'center', mt: 1 }}>
                        <Button 
                          variant="contained" 
                          color="warning" 
                          size="small" 
                          startIcon={<SyncIcon />}
                          disabled={!mergeTargetUserId}
                          onClick={async () => {
                            if (await window.appConfirm(`Are you absolutely sure you want to merge all data from ${selectedUserForManage.username} into the selected target account? This will delete ${selectedUserForManage.username} forever and is irreversible.`)) {
                              handleAdminMergeUsers(mergeTargetUserId);
                            }
                          }}
                          sx={{ borderRadius: '8px', py: 1 }}
                        >
                          Consolidate History
                        </Button>
                      </Grid>
                    </Grid>
                  </Paper>

                  {/* Revoke All Active Sessions & Paired Keys */}
                  <Paper elevation={1} sx={{ p: 2.5, mb: 3 }}>
                    <Typography variant="subtitle2" sx={{ fontWeight: 600, mb: 1 }}>Force Sign-Out & Revoke Sessions</Typography>
                    <Typography variant="body2" color="textSecondary" sx={{ mb: 2, fontSize: '0.85rem' }}>
                      Immediately invalidate all active session tokens, browser extension pairings, and API keys for <strong>{selectedUserForManage.username}</strong> across all devices.
                    </Typography>
                    <Box sx={{ display: 'flex', justifyContent: 'center' }}>
                      <Button
                        variant="outlined"
                        color="warning"
                        startIcon={<VpnKeyIcon />}
                        onClick={handleAdminRevokeSessions}
                        sx={{ borderRadius: '8px', textTransform: 'none' }}
                      >
                        Revoke All Active Sessions & API Keys
                      </Button>
                    </Box>
                  </Paper>

                  {/* Danger Zone: Delete Account */}
                  <Paper elevation={1}
                    sx={{ 
                      p: 2.5, 
                      border: '1px solid',
                      borderColor: 'error.main',
                      backgroundColor: 'rgba(211, 47, 47, 0.02)'
                    }}
                  >
                    <Typography variant="subtitle2" sx={{ color: 'error.main', fontWeight: 600, mb: 1 }}>Danger Zone: Permanent Deletion</Typography>
                    <Typography variant="body2" color="textSecondary" sx={{ mb: 2, fontSize: '0.85rem' }}>
                      Completely remove this user account and all of its associated records from the system. This cannot be undone. Lockout protection guarantees you cannot delete the sole remaining administrator account.
                    </Typography>

                    <Box sx={{ display: 'flex', justifyContent: 'center', mt: 2 }}>
                      <Button 
                        variant="contained" 
                        color="error" 
                        startIcon={<DeleteIcon />}
                        disabled={selectedUserForManage.role === 'admin' && usersList.filter(u => u.role === 'admin').length <= 1}
                        onClick={async () => {
                          if (await window.appConfirm(`Are you sure you want to permanently delete the user account for ${selectedUserForManage.username}? This will purge all associated settings, credentials, and playback data immediately.`)) {
                            handleAdminDeleteUser();
                          }
                        }}
                        sx={{ borderRadius: '8px' }}
                      >
                        Delete Account Forever
                      </Button>
                    </Box>
                  </Paper>
                </TabPanel>
              </Box>
            </Box>
          )}
        </DialogContent>
        <DialogActions sx={{ borderTop: '1px solid rgba(255,255,255,0.08)', px: 3, py: 2 }}>
          <Button onClick={() => setManageUserOpen(false)} sx={{ textTransform: 'none' }}>
            Close Settings Panel
          </Button>
        </DialogActions>
      </Dialog>

      {/* Reset Password Sub-Dialog */}
      <Dialog 
        open={adminResetPasswordOpen} 
        onClose={() => setAdminResetPasswordOpen(false)}
        disableRestoreFocus
        slotProps={{ paper: {
          elevation: 6,
          sx: {
            borderRadius: 3
          }
        } }}
      >
        <form onSubmit={(e) => { e.preventDefault(); if (adminResetPasswordNew.length >= 8) handleAdminResetPassword(adminResetPasswordNew); }}>
          <DialogTitle sx={{ pb: 1 }}>Reset User Password</DialogTitle>
          <DialogContent>
            <Typography sx={{ mb: 2, fontSize: '0.9rem', opacity: 0.8 }}>
              Set a new temporary or custom password for user <strong>{selectedUserForManage?.username}</strong>. The user will be required to input this password to authenticate next time.
            </Typography>
            <Grid container spacing={3} sx={{ alignItems: 'stretch', mt: 0.5 }}>
              <Grid xs={12} sm={7}>
                <TextField
                  fullWidth
                  type="password"
                  autoComplete="new-password"
                  label="New Password string"
                  value={adminResetPasswordNew}
                  onChange={e => setAdminResetPasswordNew(e.target.value)}
                  sx={{ '& .MuiOutlinedInput-root': { borderRadius: '10px' } }}
                />
              </Grid>
              <Grid xs={12} sm={5}>
                <PasswordChecklist password={adminResetPasswordNew} />
              </Grid>
            </Grid>
          </DialogContent>
          <DialogActions sx={{ px: 3, pb: 3 }}>
            <Button onClick={() => setAdminResetPasswordOpen(false)} sx={{ textTransform: 'none' }}>Cancel</Button>
            <Button 
              type="submit"
              variant="contained" 
              color="secondary" 
              disabled={adminResetPasswordNew.length < 8}
              sx={{ borderRadius: '8px', textTransform: 'none', px: 3 }}
            >
              Reset password
            </Button>
          </DialogActions>
        </form>
      </Dialog>

      <Snackbar open={snackbar.open} autoHideDuration={4000} onClose={() => setSnackbar({ ...snackbar, open: false })}>
        <Alert severity={snackbar.severity} sx={{ width: '100%' }}>{snackbar.message}</Alert>
      </Snackbar>
    </Box>
  )
}

import { useState, useEffect } from 'react'
import { Autocomplete, TextField, Chip, createFilterOptions } from '@mui/material'
import { apiFetch } from '../../api'

const filter = createFilterOptions()

export default function ChipInput({
  label,
  placeholder,
  value = [],
  onChange,
  fetchUrl,
  chipColor = 'rgba(99, 102, 241, 0.2)',
  chipTextColor = '#a5b4fc',
  size = 'small',
  sx = {},
}) {
  const [options, setOptions] = useState([])

  useEffect(() => {
    if (!fetchUrl) return
    apiFetch(`${fetchUrl}?per_page=100`)
      .then(res => res.json())
      .then(data => setOptions(data.items?.map(i => i.name) || []))
      .catch(() => {})
  }, [fetchUrl])

  return (
    <Autocomplete
      multiple
      freeSolo
      size={size}
      options={options}
      value={value}
      onChange={(e, newValue) => {
        const cleaned = newValue.map(v =>
          typeof v === 'string' && v.startsWith('+ Create "') && v.endsWith('"')
            ? v.replace(/^\+ Create "(.+)"$/, '$1')
            : v
        )
        onChange(cleaned)
      }}
      filterOptions={(opts, params) => {
        const filtered = filter(opts, params)
        const { inputValue } = params
        if (inputValue && !opts.some(o => o.toLowerCase() === inputValue.toLowerCase())) {
          filtered.push(`+ Create "${inputValue}"`)
        }
        return filtered
      }}
      renderTags={(tagValue, getTagProps) =>
        tagValue.map((option, index) => (
          <Chip
            size="small"
            key={option}
            label={option}
            {...getTagProps({ index })}
            sx={{ borderRadius: '6px', bgcolor: chipColor, color: chipTextColor, fontWeight: 600, fontSize: '0.72rem' }}
          />
        ))
      }
      renderInput={(params) => (
        <TextField {...params} size={size} label={label} placeholder={placeholder}
          sx={{ '& .MuiOutlinedInput-root': { borderRadius: '10px' }, ...sx }}
        />
      )}
      sx={{ '& .MuiAutocomplete-tag': { overflow: 'hidden' } }}
    />
  )
}

import { useState, useEffect } from 'react'
import {
  Box, Typography, TextField, Grid, Chip, Pagination, CircularProgress, Alert,
  InputAdornment, IconButton, Button, Dialog, DialogTitle, DialogContent, DialogActions
} from '@mui/material'
import { Search, X, Plus, Edit2, Trash2, Merge } from 'lucide-react'
import { apiFetch } from '../../api'
import GlassCard from './GlassCard'

export default function EntityListPage({
  title,
  icon: Icon,
  fetchUrl,
  createUrl,
  overviewDescription,
  emptyMessage = 'No items found.',
  onNavigate,
  onCreate,
  onRename,
  onDelete,
  onMerge,
}) {
  const [items, setItems] = useState([])
  const [search, setSearch] = useState('')
  const [page, setPage] = useState(1)
  const [totalPages, setTotalPages] = useState(0)
  const [loading, setLoading] = useState(true)

  // CRUD dialogs
  const [createOpen, setCreateOpen] = useState(false)
  const [createName, setCreateName] = useState('')
  const [renameOpen, setRenameOpen] = useState(false)
  const [renameTarget, setRenameTarget] = useState(null)
  const [renameValue, setRenameValue] = useState('')
  const [deleteOpen, setDeleteOpen] = useState(false)
  const [deleteTarget, setDeleteTarget] = useState(null)
  const [mergeOpen, setMergeOpen] = useState(false)
  const [mergeSource, setMergeSource] = useState(null)
  const [mergeTarget, setMergeTarget] = useState('')

  const fetchItems = () => {
    setLoading(true)
    const params = new URLSearchParams({ page: String(page), per_page: '20' })
    if (search) params.append('q', search)
    apiFetch(`${fetchUrl}?${params}`)
      .then(res => res.json())
      .then(data => {
        setItems(data.items || [])
        setTotalPages(data.total_pages || 0)
      })
      .catch(() => {})
      .finally(() => setLoading(false))
  }

  useEffect(() => { fetchItems() }, [fetchUrl, search, page])

  const handleCreate = async () => {
    if (!createName.trim()) return
    try {
      await apiFetch(createUrl || fetchUrl, { method: 'POST', body: { name: createName.trim() } })
      setCreateOpen(false)
      setCreateName('')
      setPage(1)
      fetchItems()
    } catch (e) { /* toast would go here */ }
  }

  const handleRename = async () => {
    if (!renameTarget || !renameValue.trim()) return
    try {
      await apiFetch(`${fetchUrl}/rename`, {
        method: 'PUT', body: { old_name: renameTarget.name, new_name: renameValue.trim() }
      })
      setRenameOpen(false)
      setRenameTarget(null)
      setRenameValue('')
      fetchItems()
    } catch (e) {}
  }

  const handleDelete = async () => {
    if (!deleteTarget) return
    try {
      await apiFetch(`${fetchUrl}/${encodeURIComponent(deleteTarget.name)}`, { method: 'DELETE' })
      setDeleteOpen(false)
      setDeleteTarget(null)
      fetchItems()
    } catch (e) {}
  }

  const handleMerge = async () => {
    if (!mergeSource || !mergeTarget.trim()) return
    try {
      await apiFetch(`${fetchUrl}/merge`, {
        method: 'POST', body: { source: mergeSource.name, target: mergeTarget.trim() }
      })
      setMergeOpen(false)
      setMergeSource(null)
      setMergeTarget('')
      fetchItems()
    } catch (e) {}
  }

  const hasCrud = onCreate || onRename || onDelete || onMerge

  return (
    <Box sx={{ maxWidth: 1400, mx: 'auto', width: '100%' }}>
      <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 3 }}>
        <Typography variant="h4" sx={{ fontWeight: '800', letterSpacing: '-0.5px' }}>
          {title}
        </Typography>
        {onCreate && (
          <Button variant="contained" size="small" startIcon={<Plus size={16} />}
            onClick={() => setCreateOpen(true)}
            sx={{ borderRadius: '8px', textTransform: 'none', fontWeight: 'bold', whiteSpace: 'nowrap', height: 36 }}>
            Add {title.slice(0, -1)}
          </Button>
        )}
      </Box>

      <Alert severity="info" sx={{ mb: 3, borderRadius: '12px', bgcolor: 'rgba(99,102,241,0.08)', color: '#a5b4fc', border: '1px solid rgba(99,102,241,0.2)', '& .MuiAlert-icon': { color: '#818cf8' } }}>
        <Typography variant="subtitle2" sx={{ fontWeight: 'bold', mb: 0.25 }}>
          {Icon && <Icon size={18} style={{ verticalAlign: 'middle', marginRight: 6 }} />}{title}
        </Typography>
        <Typography variant="caption" sx={{ display: 'block', opacity: 0.9, lineHeight: 1.4 }}>
          {overviewDescription}
        </Typography>
      </Alert>

      <GlassCard sx={{ mb: 3 }}>
        <TextField
          fullWidth size="small"
          placeholder={`Search ${title.toLowerCase()}...`}
          value={search}
          onChange={e => { setSearch(e.target.value); setPage(1) }}
          InputProps={{
            startAdornment: <InputAdornment position="start"><Search size={18} style={{ opacity: 0.5 }} /></InputAdornment>,
            endAdornment: search ? (
              <InputAdornment position="end">
                <IconButton size="small" onClick={() => setSearch('')}><X size={14} /></IconButton>
              </InputAdornment>
            ) : null
          }}
          sx={{ '& .MuiOutlinedInput-root': { borderRadius: '10px' } }}
        />
      </GlassCard>

      {loading ? (
        <Box sx={{ display: 'flex', justifyContent: 'center', py: 8 }}><CircularProgress /></Box>
      ) : items.length === 0 ? (
        <GlassCard sx={{ textAlign: 'center', py: 6 }}>
          <Typography variant="h6" sx={{ color: 'rgba(255,255,255,0.3)', fontWeight: 700, mb: 1 }}>
            {emptyMessage}
          </Typography>
        </GlassCard>
      ) : (
        <>
          <Grid container spacing={2}>
            {items.map(item => (
              <Grid size={{ xs: 12, sm: 6, md: 4, lg: 3 }} key={item.name}>
                <GlassCard hoverEffect sx={{ cursor: onNavigate ? 'pointer' : 'default', p: 2 }}>
                  <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', minWidth: 0 }}>
                    <Box
                      sx={{ minWidth: 0, flex: 1, onClick: onNavigate ? () => onNavigate(item.name) : undefined }}
                    >
                      <Typography variant="subtitle2" noWrap sx={{ fontWeight: '700', fontSize: '0.9rem' }}>
                        {item.name}
                      </Typography>
                    </Box>
                    <Chip label={`${item.count}`} size="small"
                      sx={{ ml: 1, flexShrink: 0, borderRadius: '6px', fontWeight: 'bold', fontSize: '0.65rem', bgcolor: 'rgba(99,102,241,0.12)', color: '#a5b4fc' }} />
                  </Box>
                  {hasCrud && (
                    <Box sx={{ display: 'flex', gap: 0.5, mt: 1, pt: 1, borderTop: '1px solid rgba(255,255,255,0.05)' }}>
                      {onRename && (
                        <IconButton size="small" onClick={(e) => { e.stopPropagation(); setRenameTarget(item); setRenameValue(item.name); setRenameOpen(true) }}
                          sx={{ color: 'rgba(255,255,255,0.4)', '&:hover': { color: '#818cf8' } }}>
                          <Edit2 size={14} />
                        </IconButton>
                      )}
                      {onMerge && (
                        <IconButton size="small" onClick={(e) => { e.stopPropagation(); setMergeSource(item); setMergeTarget(''); setMergeOpen(true) }}
                          sx={{ color: 'rgba(255,255,255,0.4)', '&:hover': { color: '#a78bfa' } }}>
                          <Merge size={14} />
                        </IconButton>
                      )}
                      {onDelete && (
                        <IconButton size="small" onClick={(e) => { e.stopPropagation(); setDeleteTarget(item); setDeleteOpen(true) }}
                          sx={{ color: 'rgba(255,255,255,0.4)', '&:hover': { color: '#ef4444' } }}>
                          <Trash2 size={14} />
                        </IconButton>
                      )}
                    </Box>
                  )}
                </GlassCard>
              </Grid>
            ))}
          </Grid>
          {totalPages > 1 && (
            <Box sx={{ display: 'flex', justifyContent: 'center', mt: 4 }}>
              <Pagination count={totalPages} page={page} onChange={(e, v) => setPage(v)} color="primary" />
            </Box>
          )}
        </>
      )}

      {/* Create Dialog */}
      {onCreate && (
        <Dialog open={createOpen} onClose={() => setCreateOpen(false)} maxWidth="xs" fullWidth
          slotProps={{ paper: { sx: { borderRadius: '12px', bgcolor: 'rgba(15,23,42,0.95)', backdropFilter: 'blur(16px)', border: '1px solid rgba(255,255,255,0.1)' } } }}>
          <DialogTitle sx={{ fontWeight: 'bold' }}>Create {title.slice(0, -1)}</DialogTitle>
          <DialogContent>
            <TextField autoFocus fullWidth size="small" label="Name" value={createName}
              onChange={e => setCreateName(e.target.value)}
              onKeyDown={e => e.key === 'Enter' && handleCreate()}
              sx={{ mt: 1, '& .MuiOutlinedInput-root': { borderRadius: '10px' } }} />
          </DialogContent>
          <DialogActions>
            <Button onClick={() => setCreateOpen(false)} sx={{ borderRadius: '8px', textTransform: 'none' }}>Cancel</Button>
            <Button variant="contained" onClick={handleCreate} disabled={!createName.trim()}
              sx={{ borderRadius: '8px', textTransform: 'none' }}>Create</Button>
          </DialogActions>
        </Dialog>
      )}

      {/* Rename Dialog */}
      {onRename && (
        <Dialog open={renameOpen} onClose={() => setRenameOpen(false)} maxWidth="xs" fullWidth
          slotProps={{ paper: { sx: { borderRadius: '12px', bgcolor: 'rgba(15,23,42,0.95)', backdropFilter: 'blur(16px)', border: '1px solid rgba(255,255,255,0.1)' } } }}>
          <DialogTitle sx={{ fontWeight: 'bold' }}>Rename</DialogTitle>
          <DialogContent>
            <TextField autoFocus fullWidth size="small" label="New name" value={renameValue}
              onChange={e => setRenameValue(e.target.value)}
              onKeyDown={e => e.key === 'Enter' && handleRename()}
              sx={{ mt: 1, '& .MuiOutlinedInput-root': { borderRadius: '10px' } }} />
          </DialogContent>
          <DialogActions>
            <Button onClick={() => setRenameOpen(false)} sx={{ borderRadius: '8px', textTransform: 'none' }}>Cancel</Button>
            <Button variant="contained" onClick={handleRename} disabled={!renameValue.trim()}
              sx={{ borderRadius: '8px', textTransform: 'none' }}>Save</Button>
          </DialogActions>
        </Dialog>
      )}

      {/* Delete Dialog */}
      {onDelete && (
        <Dialog open={deleteOpen} onClose={() => setDeleteOpen(false)} maxWidth="xs" fullWidth
          slotProps={{ paper: { sx: { borderRadius: '12px', bgcolor: 'rgba(15,23,42,0.95)', backdropFilter: 'blur(16px)', border: '1px solid rgba(255,255,255,0.1)' } } }}>
          <DialogTitle sx={{ fontWeight: 'bold' }}>Delete {title.slice(0, -1)}</DialogTitle>
          <DialogContent>
            <Typography variant="body2">
              Delete "<strong>{deleteTarget?.name}</strong>"? It will be removed from all library entries.
            </Typography>
          </DialogContent>
          <DialogActions>
            <Button onClick={() => setDeleteOpen(false)} sx={{ borderRadius: '8px', textTransform: 'none' }}>Cancel</Button>
            <Button variant="contained" color="error" onClick={handleDelete}
              sx={{ borderRadius: '8px', textTransform: 'none' }}>Delete</Button>
          </DialogActions>
        </Dialog>
      )}

      {/* Merge Dialog */}
      {onMerge && (
        <Dialog open={mergeOpen} onClose={() => setMergeOpen(false)} maxWidth="xs" fullWidth
          slotProps={{ paper: { sx: { borderRadius: '12px', bgcolor: 'rgba(15,23,42,0.95)', backdropFilter: 'blur(16px)', border: '1px solid rgba(255,255,255,0.1)' } } }}>
          <DialogTitle sx={{ fontWeight: 'bold' }}>Merge {title.slice(0, -1)}</DialogTitle>
          <DialogContent>
            <Typography variant="body2" sx={{ mb: 2 }}>
              Merge "<strong>{mergeSource?.name}</strong>" into:
            </Typography>
            <TextField autoFocus fullWidth size="small" label="Target name" value={mergeTarget}
              onChange={e => setMergeTarget(e.target.value)}
              onKeyDown={e => e.key === 'Enter' && handleMerge()}
              sx={{ '& .MuiOutlinedInput-root': { borderRadius: '10px' } }} />
          </DialogContent>
          <DialogActions>
            <Button onClick={() => setMergeOpen(false)} sx={{ borderRadius: '8px', textTransform: 'none' }}>Cancel</Button>
            <Button variant="contained" onClick={handleMerge} disabled={!mergeTarget.trim()}
              sx={{ borderRadius: '8px', textTransform: 'none' }}>Merge</Button>
          </DialogActions>
        </Dialog>
      )}
    </Box>
  )
}

import React from 'react'
import { Box } from '@mui/material'
import { motion } from 'framer-motion'

export default function GlassCard({ 
  children, 
  sx = {}, 
  hoverEffect = true,
  animate = true,
  ...props 
}) {
  const content = (
    <Box
      sx={{
        p: 2.5,
        borderRadius: '16px',
        bgcolor: (theme) => 
          theme.palette.mode === 'dark' 
            ? 'rgba(18, 19, 26, 0.75)' 
            : 'rgba(255, 255, 255, 0.75)',
        backdropFilter: 'blur(16px)',
        border: '1px solid',
        borderColor: (theme) => 
          theme.palette.mode === 'dark' 
            ? 'rgba(255, 255, 255, 0.08)' 
            : 'rgba(0, 0, 0, 0.08)',
        boxShadow: (theme) =>
          theme.palette.mode === 'dark'
            ? '0 8px 32px rgba(0, 0, 0, 0.3)'
            : '0 8px 32px rgba(0, 0, 0, 0.06)',
        transition: 'all 0.3s cubic-bezier(0.4, 0, 0.2, 1)',
        ...(hoverEffect && {
          '&:hover': {
            borderColor: (theme) => 
              theme.palette.mode === 'dark' 
                ? 'rgba(99, 102, 241, 0.4)' 
                : 'rgba(99, 102, 241, 0.3)',
            transform: 'translateY(-3px)',
            boxShadow: '0 12px 36px rgba(99, 102, 241, 0.2)'
          }
        }),
        ...sx
      }}
      {...props}
    >
      {children}
    </Box>
  )

  if (!animate) return content

  return (
    <motion.div
      initial={{ opacity: 0, y: 15 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.3, ease: 'easeOut' }}
    >
      {content}
    </motion.div>
  )
}

import React from 'react'
import { Box, Typography, LinearProgress } from '@mui/material'

export default function GradientProgressBar({ 
  value, 
  label, 
  sublabel, 
  isUnlimited = false, 
  height = 10,
  variant = 'primary'
}) {
  const percentage = isUnlimited ? 100 : Math.min(Math.max(value, 0), 100)

  const getGradient = () => {
    if (percentage >= 90) return 'linear-gradient(90deg, #f43f5e 0%, #e11d48 100%)'
    if (percentage >= 75) return 'linear-gradient(90deg, #f59e0b 0%, #d97706 100%)'
    return 'linear-gradient(90deg, #6366f1 0%, #a855f7 100%)'
  }

  return (
    <Box sx={{ width: '100%' }}>
      {(label || sublabel) && (
        <Box sx={{ display: 'flex', justifyContent: 'space-between', mb: 1, alignItems: 'center' }}>
          {label && (
            <Typography variant="body2" sx={{ fontWeight: 600, fontSize: '0.85rem' }}>
              {label}
            </Typography>
          )}
          {sublabel && (
            <Typography variant="caption" sx={{ color: 'text.secondary', fontWeight: 600 }}>
              {sublabel}
            </Typography>
          )}
        </Box>
      )}

      <Box sx={{ position: 'relative', borderRadius: height, overflow: 'hidden', bgcolor: 'rgba(255,255,255,0.06)' }}>
        <LinearProgress 
          variant="determinate" 
          value={percentage} 
          sx={{ 
            height, 
            borderRadius: height,
            bgcolor: 'transparent',
            '& .MuiLinearProgress-bar': {
              borderRadius: height,
              background: getGradient(),
              transition: 'transform 0.4s ease'
            }
          }}
        />
      </Box>
    </Box>
  )
}

