      <Box sx={{ textAlign: 'center', mb: subtitle ? 1 : 0 }}>
        <Typography 
          variant="h3" 
          sx={{ 
            fontFamily: "'Outfit', sans-serif",
            fontWeight: 900, 
            letterSpacing: '-1px',
            color: themeColors.text,
            lineHeight: 1.1,
